const DATA={"chapters": [{"id": 1, "titleZh": "重症藥學的發展、實務標準與專業成長", "sections": [{"title": "專科形成與跨專業團隊", "bullets": ["重症藥師自 1960 年代末開始進入 ICU；臨床服務逐漸涵蓋感染、PK、nutrition support 與急救。", "SCCM 強調 multidisciplinary care；藥師參與床邊決策、藥物監測及跨專業溝通。", "專業學會、專科期刊與 Critical Care Pharmacy 教科書共同推動知識與實務標準發展。"]}, {"title": "藥師服務的效益", "bullets": ["章節整理 ICU 藥師與藥費降低、ADE 減少及藥物交互作用改善之研究。", "參與 medical ICU rounds 的藥師介入，研究曾報告 preventable ADE 減少 66%。", "評估服務時需區分直接節省成本與 cost avoidance，並注意觀察性研究的侷限。"]}, {"title": "照護流程與文件", "bullets": ["完整流程包括收集病人資訊、評估 medication regimen、擬定及執行 care plan、追蹤效果。", "文件應包含 medication history、active problem list、治療評估與追蹤計畫。", "藥師服務需與機構 credentialing、clinical privileges 及 collaborative care 機制配合。"]}, {"title": "訓練與資格", "bullets": ["進階訓練可包含 PGY1、PGY2 critical care residency、fellowship 或適當相關實務經驗。", "Board certification 是專業能力認證的一部分；實際資格及維持條件依章節引用的 BPS 規範。", "Mentorship 可協助能力差距評估、職涯規劃與臨床及研究技能成長。"]}, {"title": "持續成長與知識傳播", "bullets": ["Continuing professional development（CPD）是自我導向、持續反思與反覆調整的歷程。", "學習計畫應與每日工作整合，設定目標、執行學習、記錄成果並重新評估需求。", "知識可透過 peer-reviewed publications、教學、會議及其他專業管道分享。"]}], "pearls": ["以病人照護流程和可量測結果呈現藥師價值。", "完成訓練不代表終止學習；CPD 是持續循環。"], "files": [{"name": "01  Evolution and Validation of Practice Standards, Training, and Professional Development.pdf", "url": "pdf/ch01.pdf"}], "titleEn": "Evolution and Validation of Practice Standards, Training, and Professional Development"}, {"id": 2, "titleZh": "研究設計、Biostatistics 與文獻評讀", "sections": [{"title": "研究倫理", "bullets": ["Belmont Report 的核心原則為 respect for persons、beneficence 與 justice。", "Informed consent 應考量病人的決策能力，必要時由合法代理人參與。", "Clinical equipoise 指對比較療法仍存在合理不確定性，是試驗倫理的重要條件。"]}, {"title": "重症研究的特殊挑戰", "bullets": ["重症 syndromes 常有高度異質性，同一診斷的病人可能具有不同病因與治療反應。", "招募時間窗、標準化定義及代表性的研究族群會影響試驗結果可推廣性。", "IRB 流程、知情同意、研究資源及終點選擇應在研究開始前規劃。"]}, {"title": "研究設計與偏差", "bullets": ["RCT 透過 randomization 與 blinding 降低組間差異及偏差。", "Cohort、case-control、cross-sectional 與 case series 各回答不同問題，需辨識其限制。", "Meta-analysis 的可信度取決於納入研究品質、異質性及適當的合併方法。"]}, {"title": "統計概念", "bullets": ["Frequentist analysis 常以 hypothesis testing、p value 與 confidence interval 呈現結果；Bayesian analysis 可納入 prior information。", "未拒絕 null hypothesis 不等於證明兩療法相同；需同時評估 power 與效果估計的精確度。", "Continuous outcome 常用 linear regression；二元 outcome 常用 logistic regression，並須妥善處理 confounders。"]}, {"title": "從文獻到病人", "bullets": ["先確認研究問題、族群、介入、比較及臨床重要的 outcomes 是否與病人情境相符。", "檢查 sample size、randomization、blinding、分析方式與 adverse effects 定義。", "結合 effect size、CI、病人偏好與臨床經驗，避免僅依 p value 決策。"]}], "pearls": ["Association 或 correlation 不直接證明 causation。", "評讀結果需同時考慮內部效度與對自己病人的適用性。"], "files": [{"name": "02 Research Design, Biostatistics, and Literature Evaluation.pdf", "url": "pdf/ch02.pdf"}], "titleEn": "Research Design, Biostatistics, and Literature Evaluation"}, {"id": 3, "titleZh": "輸液、Electrolytes、Acid–Base 與營養支持", "sections": [{"title": "體液評估與補液", "bullets": ["評估 intravascular volume、interstitial fluid 與總體液平衡，區分 resuscitation、maintenance 與持續流失補充。", "Daily fluid balance 應納入藥物輸注、營養與其他液體來源，避免重複計算造成 fluid overload。", "選擇 crystalloid 或其他液體需考量 sodium、chloride、acid–base 與病人的循環狀態。"]}, {"title": "Sodium 異常", "bullets": ["Hyponatremia 評估須先排除 hyperglycemia 等造成的移位及 pseudohyponatremia。", "搭配 serum osmolality、urine osmolality、urine sodium 與 volume status 分類原因。", "Hypernatremia 通常反映相對 water deficit；補水速度與 sodium 追蹤需考量發生時間及神經風險。"]}, {"title": "Potassium、Magnesium 與 Phosphate", "bullets": ["Hypokalemia 應同時評估攝取、腎臟及腸胃流失、細胞內移位與 hypomagnesemia。", "Electrolyte replacement 需依腎功能、嚴重度、給藥途徑及再檢驗結果調整。", "Hyperkalemia 處理分為穩定心肌、促進 potassium 進入細胞及實際移除體內 potassium。"]}, {"title": "Acid–Base 判讀", "bullets": ["正常 arterial pH 為 7.35–7.45；PaCO2 約 35–45 mm Hg，HCO3 約 22–26 mEq/L。", "先辨識 acidemia 或 alkalemia，再判定主要 respiratory 或 metabolic 原因及預期代償。", "Anion gap、albumin 與臨床情境有助辨識 mixed disorders，不能僅以 pH 正常排除異常。"]}, {"title": "Nutrition support", "bullets": ["進行 nutrition risk assessment，估算 energy、protein 與 micronutrient 需求並追蹤耐受性。", "有可用 GI tract 時評估 enteral nutrition；無法充分達標或有禁忌時考量 parenteral nutrition。", "Refeeding risk 病人需特別追蹤 phosphate、potassium、magnesium、glucose 與 thiamine 需求。"]}], "pearls": ["先找出造成 electrolyte disorder 的機轉，再規劃補充。", "所有輸注及營養均需納入每日 fluid balance。"], "files": [{"name": "03 Fluids, Electrolytes, Acid-Base Disorders, and Nutrition Support.pdf", "url": "pdf/ch03.pdf"}], "titleEn": "Fluids, Electrolytes, Acid-Base Disorders, and Nutrition Support"}, {"id": 4, "titleZh": "Protocol 建置與品質改善", "sections": [{"title": "Policy、Procedure 與 Guideline", "bullets": ["Policy 說明機構原則，procedure 描述執行步驟，guideline 支持臨床選擇。", "建立文件前確認問題、目標族群、證據及跨專業利害關係人。", "推行時搭配教育、可執行工作流程及後續更新機制。"]}, {"title": "Gap analysis", "bullets": ["比較目前的服務或流程與 best practice，明確標示差距。", "蒐集 baseline data，分析人力、系統、設備及知識需求。", "依病人風險、改善可行性及機構目標排列優先順序。"]}, {"title": "QI 工具", "bullets": ["PDSA 以 plan、do、study、act 小規模測試改變，再依結果修正。", "LEAN 著重從病人觀點定義 value，辨識並減少流程中的 waste。", "Six Sigma 的 DMAIC 依序 define、measure、analyze、improve、control，維持改善成果。"]}, {"title": "風險分析與衡量", "bullets": ["FMEA 預先分析流程可能失敗的方式、原因及影響。", "Root cause analysis 回顧已發生事件中的系統因素與改進機會。", "衡量成效應包含 process、outcome 及 balancing measures，避免改善一端卻造成另一端問題。"]}, {"title": "MUE、教育與紀錄", "bullets": ["Medication use evaluation（MUE）系統性評估藥物使用流程、適當性與結果。", "明確定義目標、抽樣、評估標準、資料收集及改善後再評估。", "教育與藥師介入紀錄支持落實、溝通、服務價值評估與成果分享。"]}], "pearls": ["QI 是持續改善循環，而非只完成一次資料收集。", "先建立 baseline，再設定可測量的目標。"], "files": [{"name": "04 Protocol Development and Quality Improvement.pdf", "url": "pdf/ch04.pdf"}], "titleEn": "Protocol Development and Quality Improvement"}, {"id": 5, "titleZh": "Pharmacoeconomics 與用藥安全", "sections": [{"title": "經濟評估的範圍", "bullets": ["Pharmacoeconomics 比較藥物或藥事服務的 costs 與 consequences。", "分析 perspective 決定納入何種成本，例如醫院、payer、病人或社會觀點。", "直接成本、間接成本、分析時間範圍及 sensitivity analysis 都會影響結論。"]}, {"title": "四種主要分析", "bullets": ["Cost-minimization 適用於已確認 outcomes 相當的選項。", "Cost-effectiveness 用自然臨床單位比較；cost-utility 常使用 quality-adjusted life-years（QALYs）。", "Cost-benefit 將 benefits 與 costs 轉成金額；不同分析類型不可直接互換。"]}, {"title": "Medication error、ADE 與 ADR", "bullets": ["Medication error 是可預防的用藥過程失誤，可能造成傷害，也可能未造成傷害。", "ADE 指藥物相關傷害；preventable ADE 包含可避免的錯誤所造成的傷害。", "ADR 與 medication error 的概念不同，事件分類需結合給藥過程及病人反應。"]}, {"title": "安全系統與事件監測", "bullets": ["事件報告、trigger tools、chart review 與主動監測可互補偵測 ADE。", "ICU 用藥安全涵蓋 prescribing、dispensing、administration、monitoring 及交接。", "CPOE、clinical decision support、barcode 及標準化可降低風險，但仍需管理 alert fatigue。"]}, {"title": "Drug interactions 與 Formulary", "bullets": ["評估 interaction 的機轉、嚴重性、證據、時間關係及病人特異風險。", "Formulary proposal 應比較 efficacy、safety、成本、替代方案與實際使用條件。", "適當限制、教育及後續 MUE 可支持新藥有效而安全的導入。"]}], "pearls": ["低 acquisition cost 不一定代表整體治療成本較低。", "Medication error 與 ADE 不完全重疊。"], "files": [{"name": "05 Pharmacoeconomics and Safe Medication Use.pdf", "url": "pdf/ch05.pdf"}], "titleEn": "Pharmacoeconomics and Safe Medication Use"}, {"id": 6, "titleZh": "Infectious Diseases I：常見 ICU 感染", "sections": [{"title": "VAP 與導管相關感染", "bullets": ["VAP 評估結合臨床惡化、肺部影像與適當呼吸道檢體。", "Empiric antimicrobials 依感染部位、MDR risk、先前抗菌藥與 local antibiogram 選擇。", "CLABSI 與 CAUTI 須評估感染來源、culture 結果及移除或更換導管的必要性。"]}, {"title": "治療優化與預防", "bullets": ["依 cultures、susceptibilities 及病人反應進行 de-escalation。", "藥物選擇外亦需考量 PK/PD、腎功能、dose、給藥方式及療程。", "使用正確置管技術並每天確認導管是否仍需保留，是重要預防措施。"]}, {"title": "Intra-abdominal infection 與 Pancreatitis", "bullets": ["Complicated intra-abdominal infection 治療同時需要 source control 與 antimicrobials。", "Empiric coverage 依 community-acquired 或 healthcare-associated、嚴重度及抗藥風險調整。", "Acute pancreatitis 應區分 sterile inflammation 與真正感染，避免將所有發炎都視為感染。"]}, {"title": "CDI 與 Wound infection", "bullets": ["Clostridioides difficile infection（CDI）需結合症狀及適當檢驗，避免治療僅有 colonization 的病人。", "CDI 療法依初次、復發及 fulminant disease 分層；章節討論 fidaxomicin、vancomycin 等選項。", "Wound infection 需區分 superficial、deep 與 organ-space infection，評估 drainage 與 debridement。"]}, {"title": "嚴重皮膚反應與病毒疾病", "bullets": ["SJS/TEN 是嚴重皮膚反應，需辨識並停止可疑致病藥物及提供支持照護。", "Hospitalized influenza 病人評估 oseltamivir 等 antiviral therapy 與合併細菌感染。", "COVID-19 治療章節依疾病嚴重度與 oxygen requirement 整理 antiviral 及免疫調節療法。"]}], "pearls": ["Source control 與抗菌藥物同樣重要。", "Empiric therapy 啟動後仍須持續重新評估與縮窄範圍。"], "files": [{"name": "06 Infectious Diseases I .pdf", "url": "pdf/ch06.pdf"}], "titleEn": "Infectious Diseases I"}, {"id": 7, "titleZh": "Infectious Diseases II：Stewardship、抗藥性與特殊宿主", "sections": [{"title": "Surgical prophylaxis 與 Meningitis", "bullets": ["Surgical prophylaxis 需考量手術類型、給藥時機、redosing 及合理的療程。", "Bacterial meningitis 是 neurologic emergency；empiric therapy 依年齡、免疫狀態與 healthcare exposure 調整。", "Dexamethasone 的使用時機及是否繼續，需結合病原與章節引用的 guideline 條件。"]}, {"title": "Antimicrobial stewardship", "bullets": ["Stewardship 同時追求最佳 clinical outcomes 並降低 toxicity、resistance 與不必要成本。", "Prospective audit with feedback、preauthorization 與教育是常見策略。", "Rapid diagnostic tests 應結合及時通知與 stewardship 行動，才能將較快的結果轉為照護效益。"]}, {"title": "Susceptibility 與 Resistance", "bullets": ["MIC、breakpoints 與 susceptibility categories 須連同 infection site 及可達藥物暴露解讀。", "Resistance 可來自藥物失活、target modification、efflux 或 permeability 改變。", "治療 resistant pathogens 須確認 resistance mechanism、可用藥物及相應 PK/PD。"]}, {"title": "Immunocompromised host", "bullets": ["Febrile neutropenia 需快速評估及開始適當 empiric antipseudomonal therapy。", "Risk stratification、ANC、預期 neutropenia 持續時間與 infection focus 會影響治療策略。", "HIV 病人評估 CD4、viral load、opportunistic infection 與 antiretroviral interactions；單次 CD4 低下不等於 HIV。"]}, {"title": "Antifungal therapy 與照護差異", "bullets": ["Amphotericin B、azoles 與 echinocandins 的 spectrum、toxicity、interactions 與感染部位穿透性不同。", "Candida 與 mold infections 需結合宿主風險、檢體及 diagnostics 選擇治療。", "Healthcare access、經濟與其他 social determinants of health 會影響感染預防及治療持續性。"]}], "pearls": ["Rapid diagnostics 的價值取決於結果是否及時轉化為治療調整。", "Susceptibility report 需結合感染位置及 achievable exposure。"], "files": [{"name": "07 Infectious Diseases II .pdf", "url": "pdf/ch07.pdf"}], "titleEn": "Infectious Diseases II"}, {"id": 8, "titleZh": "Pharmacokinetics／Pharmacodynamics", "sections": [{"title": "PK/PD 與給藥途徑", "bullets": ["PK 描述 absorption、distribution、metabolism、excretion；PD 描述藥物對身體的作用。", "IV administration 的 bioavailability 為 100%，但其他途徑會受吸收及 first-pass metabolism 影響。", "Shock、vasopressors、GI dysfunction 與 enteral feeding 可能改變非 IV 藥物的吸收。"]}, {"title": "Distribution 與 Loading dose", "bullets": ["Vd 反映體內藥量相對於 plasma concentration 的分布程度。", "Capillary leak、fluid resuscitation、hypoalbuminemia 及體組成變化可改變 Vd 與 free fraction。", "Loading dose 主要受目標濃度、Vd 與 bioavailability 影響，不能直接等同 maintenance dose。"]}, {"title": "Metabolism 與 Excretion", "bullets": ["Liver perfusion、enzyme activity、organ dysfunction 與 drug interactions 可改變 metabolism。", "Renal clearance 同時涉及 glomerular filtration、tubular secretion 與 reabsorption。", "ARC 可使 drug exposure 不足；AKI 及其恢復則可能造成 clearance 快速改變。"]}, {"title": "特殊重症環境", "bullets": ["ECMO 可因 circuit sequestration、血容量及病人狀態改變 drug disposition。", "Kidney replacement therapy 的 modality、effluent rate 及 downtime 影響藥物移除。", "重症 PK 常隨時間變動，初始 regimen 不應視為全療程固定。"]}, {"title": "PD targets 與 TDM", "bullets": ["Antimicrobial PD 常用 fT>MIC、Cmax/MIC 或 AUC/MIC 描述暴露與療效。", "TDM 尤其適用 narrow therapeutic index 或暴露與結果有關的藥物。", "濃度判讀需確認採樣時間、dose history、steady state、organ function 與臨床反應。"]}], "pearls": ["Loading dose 看 Vd；maintenance dose 更受 clearance 影響。", "同一病人不同 ICU 日的 PK 可能不同。"], "files": [{"name": "08 Pharmacokinetics:Pharmacodynamics.pdf", "url": "pdf/ch08.pdf"}], "titleEn": "Pharmacokinetics:Pharmacodynamics"}, {"id": 9, "titleZh": "Acute Kidney Injury 與 Kidney Replacement Therapy", "sections": [{"title": "AKI 診斷與分期", "bullets": ["AKI 涵蓋由輕度功能變化至嚴重腎衰竭的連續範圍。", "KDIGO 分期以 SCr 變化及 urine output 判定，不應只看單次 SCr。", "評估 baseline function、volume status、hemodynamics、nephrotoxins 及 obstruction 等原因。"]}, {"title": "腎功能估算的限制", "bullets": ["SCr 是延遲的功能指標，並受 muscle mass、fluid dilution 與生成速率影響。", "常用估算公式在 rapidly changing kidney function 下存在侷限。", "Urine output、趨勢、臨床資訊及可用 biomarkers 應共同考量。"]}, {"title": "支持治療", "bullets": ["找出並處理病因，維持適當 perfusion，避免或減少可替代的 nephrotoxins。", "Diuretics 可用於處理 fluid overload，不能視為使 AKI 恢復的療法。", "每日調整藥物暴露與 fluid、electrolyte、acid–base 管理。"]}, {"title": "KRT 模式與選擇", "bullets": ["Intermittent hemodialysis、prolonged intermittent therapy 與 continuous KRT 的清除方式及耐受性不同。", "Diffusion 依濃度梯度清除 solutes；convection 隨 ultrafiltration 帶走 solutes。", "開始 KRT 時機需結合 electrolyte、acid–base、fluid overload、uremic complications 與整體情境。"]}, {"title": "KRT 下的藥物劑量", "bullets": ["Drug removal 與 protein binding、molecular weight、Vd 及 treatment settings 有關。", "CRRT 的實際 effluent rate、circuit interruptions 與殘餘腎功能影響 clearance。", "使用可用 TDM 並隨 KRT 停止、模式轉換或腎功能恢復重新評估 dose。"]}], "pearls": ["SCr 未快速上升仍可能存在 AKI。", "依實際 KRT delivery 調整劑量，不能只看模式名稱。"], "files": [{"name": "09 Acute Kidney Injury and Kidney Replacement Therapy in the Critically Ill Patient.pdf", "url": "pdf/ch09.pdf"}], "titleEn": "Acute Kidney Injury and Kidney Replacement Therapy in the Critically Ill Patient"}, {"id": 10, "titleZh": "Neurocritical Care", "sections": [{"title": "Sodium disorders 與腦損傷", "bullets": ["腦損傷病人的 hyponatremia 需區分 SIADH、salt wasting 與其他原因。", "症狀嚴重度、volume status、急慢性及 sodium 趨勢會影響 hypertonic saline 等處置。", "避免過度快速矯正造成 osmotic demyelination；hypernatremia 也須評估 free-water balance 與原因。"]}, {"title": "Status epilepticus 與 CNS infection", "bullets": ["Status epilepticus 定義包括持續 5 分鐘或以上的 seizures，或反覆發作而未恢復意識。", "治療包含迅速給予 benzodiazepine、後續 antiseizure therapy，必要時進入 refractory status epilepticus 處置。", "Continuous EEG 有助辨識 nonconvulsive seizures；intraventricular antimicrobials 用於特定難治感染情境。"]}, {"title": "ICP 與 Cerebral perfusion", "bullets": ["ICP 增高可降低 cerebral perfusion；CPP = MAP − ICP。", "Mannitol 與 hypertonic saline 的選擇需考量 volume、sodium、osmolarity 與 renal function。", "同時處理可逆原因、鎮痛鎮靜、體位與其他支持照護；不能只追蹤單一 ICP 值。"]}, {"title": "Ischemic stroke 與 Intracerebral hemorrhage", "bullets": ["Acute ischemic stroke 先確認 last-known-well、影像、血壓與 thrombolysis 或 thrombectomy eligibility。", "Alteplase 的適用條件及 bleeding risk 必須逐項評估。", "ICH 照護重點包括 blood pressure、anticoagulant reversal、ICP 與神經狀態監測。"]}, {"title": "SAH 與其他神經重症", "bullets": ["SAH 病人評估 aneurysm treatment、nimodipine、delayed cerebral ischemia 與 vasospasm。", "避免將所有神經惡化都歸因於 vasospasm，須排除 seizures、hydrocephalus 及 metabolic causes。", "章節亦涵蓋 paroxysmal sympathetic hyperactivity、spinal cord injury、brain tumors 及 critical illness polyneuropathy。"]}], "pearls": ["ICP、MAP 與 CPP 應一起解讀。", "神經重症中的 sodium correction 與 anticoagulation 決策必須結合完整病情。"], "files": [{"name": "10 Neurocritical Care.pdf", "url": "pdf/ch10.pdf"}], "titleEn": "Neurocritical Care"}, {"id": 11, "titleZh": "Cardiovascular Critical Care I", "sections": [{"title": "Hemodynamic fundamentals", "bullets": ["Preload、afterload、contractility 與 heart rate 共同影響 stroke volume 及 cardiac output。", "Chronotropy、dromotropy、inotropy 與 lusitropy 描述不同的 myocardial function。", "評估應結合 clinical perfusion、filling pressures、CO、oxygen delivery 與各數值趨勢。"]}, {"title": "Cardiogenic shock", "bullets": ["Cardiogenic shock 包含持續 hypotension、低 cardiac output 與 tissue hypoperfusion。", "治療先辨識病因、congestion、right 或 left ventricular involvement 及可逆因素。", "Vasopressors、inotropes、revascularization 與 mechanical circulatory support 依病情選用。"]}, {"title": "Acute coronary syndromes", "bullets": ["ACS 通常與 coronary plaque disruption 及 thrombus 造成 myocardial ischemia 有關。", "STEMI 與 non-ST-elevation ACS 的 reperfusion、antiplatelet 及 anticoagulation 策略不同。", "Aspirin、P2Y12 inhibitors、anticoagulants 及 anti-ischemic agents 需兼顧 bleeding 與 hemodynamic risk。"]}, {"title": "Arrhythmias", "bullets": ["先辨識 rhythm、hemodynamic stability 與可逆原因，再決定 cardioversion、pacing 或藥物。", "Antiarrhythmics 的 conduction、QT 與 hemodynamic effects 不同，需注意 interactions。", "Electrolyte abnormalities、ischemia 與 underlying structural disease 會影響處置。"]}, {"title": "Heart failure 與 Advanced therapies", "bullets": ["HF 治療需區分 reduced 或 preserved EF、acute congestion 及 perfusion 狀態。", "急性期先穩定 circulation 及解除 congestion，再評估長期 disease-modifying therapy。", "Valvular disease、VAD、transplant 與其他 advanced therapies 會改變血流動力學與藥物需求。"]}], "pearls": ["血流動力學的數值必須與末梢灌流及病因一致。", "有 congestion 的 hypotension 病人不宜只憑低血壓反覆補液。"], "files": [{"name": "11 Cardiovascular Critical Care I.pdf", "url": "pdf/ch11.pdf"}], "titleEn": "Cardiovascular Critical Care I"}, {"id": 12, "titleZh": "Cardiovascular Critical Care II：ACLS 與 Hypertensive Crisis", "sections": [{"title": "急救的基礎", "bullets": ["High-quality CPR 與及時辨識 rhythm 是 ACLS 的基礎。", "VF/pulseless VT 屬 shockable rhythms；PEA/asystole 屬 nonshockable rhythms。", "減少 chest compression 中斷，並同時規劃 airway、vascular access 與監測。"]}, {"title": "Cardiac arrest 藥物與原因", "bullets": ["Epinephrine 在 cardiac arrest algorithm 中常用 1 mg，每 3–5 分鐘一次。", "Refractory VF/pulseless VT 可依 algorithm 使用 amiodarone 或 lidocaine。", "持續尋找 reversible causes，例如 hypoxia、hypovolemia、electrolyte disorders、tamponade 與 thrombosis。"]}, {"title": "Bradycardia、Tachycardia 與急救後", "bullets": ["有症狀 bradycardia 與 tachycardia 的處置依 rhythm 及 hemodynamic instability 區分。", "ROSC 後需整合 oxygenation、ventilation、blood pressure、ECG 與 neurological assessment。", "章節討論 post-cardiac-arrest temperature management 及造成 arrest 的病因治療。"]}, {"title": "Hypertensive crisis 定義", "bullets": ["Hypertensive emergency 的關鍵是急性 target-organ damage，而非僅有高 BP 數字。", "Hypertensive urgency 與 emergency 的降壓速度及給藥途徑不同。", "應確認 neurological、cardiac、aortic 與 renal injury，並排除可逆誘因。"]}, {"title": "IV antihypertensives", "bullets": ["依受損器官、心率、volume status 及 contraindications 選擇可調整的 IV agents。", "Nicardipine、clevidipine、labetalol 等各有不同 onset、duration 與 hemodynamic effects。", "Aortic dissection、stroke 及 pregnancy-related emergencies 需要各自的目標與療法，避免套用單一降壓方案。"]}], "pearls": ["Cardiac arrest 中，藥物不能取代 high-quality CPR。", "Hypertensive emergency 需證實 acute target-organ damage。"], "files": [{"name": "12 Cardiovascular Critical Care II.pdf", "url": "pdf/ch12.pdf"}], "titleEn": "Cardiovascular Critical Care II"}, {"id": 13, "titleZh": "Hepatic Failure、GI 與 Endocrine Emergencies", "sections": [{"title": "Acute liver failure", "bullets": ["ALF 評估重點包括原因、coagulopathy、encephalopathy 及 organ dysfunction。", "Acetaminophen-related ALF 應評估 acetylcysteine；其他原因也需病因特異治療。", "監測 glucose、renal function、ICP risk、hemodynamics 與移植評估需求。"]}, {"title": "Pancreatitis 與 GI dysfunction", "bullets": ["Acute pancreatitis 初期處理包括適當 fluid、analgesia、nutrition 與原因評估。", "Hypertriglyceridemia-associated pancreatitis 的 insulin therapy 需密切監測 glucose。", "GI fistulas 與 postoperative ileus 的照護包含 fluid/electrolytes、nutrition 及藥物因素評估。"]}, {"title": "PONV", "bullets": ["PONV risk assessment 結合病人、手術與 anesthesia-related factors。", "高風險病人常需不同機轉的 multimodal prophylaxis。", "Rescue antiemetic 選擇需考量已用療法、QT、sedation 與相關 contraindications。"]}, {"title": "Upper GI bleeding", "bullets": ["先評估 hemodynamic stability、ongoing blood loss、transfusion 及 urgent endoscopy 需求。", "Nonvariceal bleeding 與 variceal bleeding 的藥物及 definitive treatment 不同。", "PPI、vasoactive therapy、antimicrobial prophylaxis 與 anticoagulant reversal 依 bleeding source 及風險選擇。"]}, {"title": "Endocrine emergencies", "bullets": ["DKA 與 HHS 需整合 fluids、insulin、potassium 及 precipitating cause 管理。", "Myxedema coma、thyroid storm 與 adrenal crisis 需辨識特徵並迅速給予特異治療。", "Endocrine 治療過程持續監測 glucose、electrolytes、temperature、hemodynamics 與 organ function。"]}], "pearls": ["Acetaminophen 已測不到仍不能僅憑此排除晚期相關 ALF。", "DKA 的 insulin 與 potassium 管理密切相連。"], "files": [{"name": "13 Hepatic Failure:GI:Endocrine Emergencies.pdf", "url": "pdf/ch13.pdf"}], "titleEn": "Hepatic Failure:GI:Endocrine Emergencies"}, {"id": 14, "titleZh": "Supportive 與 Preventive Medicine", "sections": [{"title": "每日 ICU 照護", "bullets": ["FAST-HUG 提醒評估 Feeding、Analgesia、Sedation、Thromboembolic prophylaxis、Head-of-bed elevation、Ulcer prophylaxis 與 Glucose control。", "每日確認支持療法是否仍有適應症、是否達標以及是否產生不良反應。", "預防措施與治療主疾病同樣需要持續 reassessment。"]}, {"title": "Stress ulcer prophylaxis", "bullets": ["SUP 需依 clinically important bleeding risk 與病人狀況判斷必要性。", "PPI、H2RA 與其他選項需比較效果、給藥途徑、renal adjustment 及 adverse effects。", "離開高風險情境時重新評估，避免沒有適應症的長期延續。"]}, {"title": "VTE prevention 與 HIT", "bullets": ["ICU 病人常有 immobility、inflammation、導管及手術等 VTE risk。", "依 bleeding risk、renal function、體重與 contraindications 選擇 pharmacologic 或 mechanical prophylaxis。", "懷疑 HIT 時評估 pretest probability，停止 heparin exposure 並考量適當 non-heparin anticoagulation。"]}, {"title": "End-of-life care", "bullets": ["Palliative care 著重病人及家屬的 physical、psychosocial 與 spiritual suffering。", "藥物選擇以症狀及 goals of care 為核心，例如 pain、dyspnea、anxiety 與 secretions。", "給藥途徑、monitoring intensity 與 deprescribing 應配合舒適照護目標。"]}, {"title": "Disaster 與 SDoH", "bullets": ["Disaster response 需規劃藥物供應、替代方案、溝通、訓練及機構應變流程。", "Pharmacists 可參與 medication preparedness、distribution 與安全使用。", "Healthcare access、economic stability、education、social context 與 neighborhood conditions 影響照護結果。"]}], "pearls": ["FAST-HUG 是每日重新檢查的提醒，不能代替個別病人評估。", "預防用藥也需要停止條件。"], "files": [{"name": "14 Supportive and Preventive Medicine.pdf", "url": "pdf/ch14.pdf"}], "titleEn": "Supportive and Preventive Medicine"}, {"id": 15, "titleZh": "Shock Syndromes I：Vasodilatory Shock 與 Sepsis", "sections": [{"title": "Shock 與 Oxygen delivery", "bullets": ["Shock 是 tissue oxygen supply 與需求失衡造成的循環衰竭，可有不同機轉。", "Oxygen delivery 受 cardiac output、hemoglobin 與 oxygen saturation 影響。", "Clinical perfusion、lactate、urine output 與心血管數據應整合判讀。"]}, {"title": "分型與監測", "bullets": ["Hypovolemic、cardiogenic、obstructive 與 distributive shock 的 preload、CO 與 vascular resistance 模式不同。", "Mixed shock 可同時存在多種機轉；病程中可能變化。", "Fluid responsiveness 可用適當 dynamic tests 評估，不能單凭 CVP 決定補液。"]}, {"title": "Resuscitation 的階段", "bullets": ["Salvage 階段先處理立即生命威脅；後續 optimization 與 stabilization 調整 perfusion。", "復甦應持續評估 fluids 的效益與 fluid overload 的代價。", "恢復後進入 de-escalation 或 deresuscitation，減少不再需要的支持。"]}, {"title": "Vasoactive agents", "bullets": ["Norepinephrine 是 septic shock 常用 first-line vasopressor。", "Vasopressin、epinephrine 與其他 agents 依反應、劑量需求及 adverse effects 考量。", "Inotrope 適用於特定 low-output 情境；選藥需理解 receptor effects 與病人 hemodynamics。"]}, {"title": "Sepsis 的整合處置", "bullets": ["Sepsis 為感染引發的 dysregulated host response 造成 organ dysfunction。", "治療整合迅速辨識、cultures、適當 antimicrobials、source control、fluids 與 vasopressors。", "持續 vasopressor-dependent shock 可評估 corticosteroids，並密切追蹤 perfusion 及 organ function。"]}], "pearls": ["Fluid responsiveness 與需要繼續給 fluid 不是完全相同的問題。", "正常或升高 CO 仍可能存在 distributive shock。"], "files": [{"name": "15 Shock Syndromes I- Introduction, Vasodilatory, and Sepsis.pdf", "url": "pdf/ch15.pdf"}], "titleEn": "Shock Syndromes I- Introduction, Vasodilatory, and Sepsis"}, {"id": 16, "titleZh": "Shock Syndromes II：Hypovolemia、Critical Bleeding 與 Obstruction", "sections": [{"title": "Hypovolemic shock", "bullets": ["Intravascular volume 減少會降低 venous return、stroke volume 與 cardiac output。", "先辨識 hemorrhagic 或 nonhemorrhagic losses，並控制持續流失。", "補充策略需依失血、electrolyte losses、組織灌流與 fluid response 調整。"]}, {"title": "Critical bleeding 與大量輸血", "bullets": ["Hemorrhagic shock 需要及時 hemorrhage control 與適當 blood products。", "Massive transfusion protocols 提供協調的 erythrocytes、plasma 及 platelets 供應。", "監測 coagulopathy、fibrinogen、temperature、ionized calcium 與 acid–base，避免只看 hemoglobin。"]}, {"title": "Antifibrinolytics 與凝血評估", "bullets": ["Tranexamic acid 為 antifibrinolytic，對適當 trauma bleeding 情境有時間相關效益。", "章節討論 trauma regimen：1 g bolus 後 1 g 於 8 小時輸注；需結合給藥時間及適應症。", "Conventional coagulation tests 與 viscoelastic testing 可協助評估及指導產品使用。"]}, {"title": "Anticoagulant reversal", "bullets": ["Warfarin-related severe bleeding 的 reversal 通常結合 vitamin K 與快速補充凝血因子的策略。", "Dabigatran 與 factor Xa inhibitors 的 specific reversal options 不同，章節涵蓋 idarucizumab 與 andexanet alfa。", "同時評估最後服藥時間、renal function、出血位置、thrombotic risk 及重新開始抗凝的時機。"]}, {"title": "Obstructive shock", "bullets": ["Obstructive shock 源自 extracardiac obstruction，使 cardiac filling 或 outflow 受阻。", "Pulmonary embolism、tamponade 與 tension pneumothorax 需要各自的 definitive treatment。", "High-risk PE 的 anticoagulation、systemic thrombolysis 或 catheter/surgical options 依風險與禁忌選擇。"]}], "pearls": ["止血與復甦要同步進行。", "Obstructive shock 不能僅靠增加 vasopressor 解決根本原因。"], "files": [{"name": "16 Shock Syndromes II- Hypovolemic, Critical Bleeding, and Obstructive.pdf", "url": "pdf/ch16.pdf"}], "titleEn": "Shock Syndromes II- Hypovolemic, Critical Bleeding, and Obstructive"}, {"id": 17, "titleZh": "PADIS、Sleep 與 Neuromuscular Blockade", "sections": [{"title": "Pain assessment 與 Analgesia", "bullets": ["可溝通病人以 self-report 評估 pain；無法溝通時可用 CPOT 或 BPS。", "先處理 pain 再評估 sedative 需求，並注意 procedures-related pain。", "Opioids 與 multimodal analgesia 依 organ function、hemodynamics、interactions 及 adverse effects 選擇。"]}, {"title": "Sedation targets", "bullets": ["以 RASS 或 SAS 及明確目標 titrate sedation，對合適病人優先考量 light sedation。", "Propofol、dexmedetomidine 與 benzodiazepines 的 onset、clearance、hemodynamic effects 與 delirium risk 不同。", "Propofol 應留意 triglycerides、營養熱量與 PRIS；dexmedetomidine 注意 bradycardia 及 hypotension。"]}, {"title": "Delirium", "bullets": ["Delirium 為急性、波動性的注意與認知障礙，可為 hyperactive、hypoactive 或 mixed。", "CAM-ICU 或 ICDSC 支持標準化篩檢，需結合 arousal 狀態。", "處理可逆原因與採用非藥物措施；antipsychotics 不應視為所有 delirium 的固定療法。"]}, {"title": "ABCDEF、Sleep 與 PICS", "bullets": ["ABCDEF 整合 pain、SAT/SBT、sedative choice、delirium、early mobility 及 family engagement。", "睡眠管理包含降低夜間噪音與光線、調整照護活動及促進日夜節律。", "PICS 可包含持續的 physical、cognitive 與 mental health problems，照護需延伸至 ICU 之後。"]}, {"title": "Neuromuscular blockade", "bullets": ["NMBA 提供 paralysis，沒有 analgesia、sedation 或 amnesia，必須確保適當相關照護。", "劑量與 duration 應依目標及病情調整，可結合 TOF 與 clinical assessment。", "持續 blockade 需注意 eye care、pressure injury、immobility 與後續 weakness，並評估何時停藥。"]}], "pearls": ["無法動作不代表沒有 pain 或 awareness。", "Sedation、pain 與 delirium 應用不同工具分別評估。"], "files": [{"name": "17 Pain, Agitation:Sedation, Delirium, Immobility, Sleep Disruption, and Neuromuscular Blockade.pdf", "url": "pdf/ch17.pdf"}], "titleEn": "Pain, Agitation:Sedation, Delirium, Immobility, Sleep Disruption, and Neuromuscular Blockade"}, {"id": 18, "titleZh": "Pulmonary Disorders I：ARDS、Mechanical Ventilation 與 Intubation", "sections": [{"title": "ARDS 的辨識", "bullets": ["ARDS 依發病時間、bilateral opacities、非單純 cardiogenic 原因及 oxygenation impairment 評估。", "Berlin framework 依 PaO2/FiO2 與適當 PEEP 條件區分嚴重度。", "治療同時處理造成肺損傷的原因及支持 gas exchange。"]}, {"title": "Lung-protective ventilation", "bullets": ["採低 tidal volume，按 predicted/ideal body weight 而非實際 total body weight 評估。", "追蹤 plateau pressure、oxygenation、ventilation、PEEP 及病人與 ventilator synchrony。", "可接受的 permissive hypercapnia 需結合 pH 與個別 contraindications。"]}, {"title": "Moderate–Severe ARDS 的支持", "bullets": ["Prone positioning 在適當 moderate–severe ARDS 情境中可改善 outcomes。", "Neuromuscular blockade 的使用需衡量 oxygenation、synchrony、sedation 與相關試驗差異。", "Fluids、PEEP、rescue therapies 與 ECMO referral 需依反應及整體病情選擇。"]}, {"title": "Intubation 與 RSI", "bullets": ["Intubation 前準備包含 airway assessment、preoxygenation、hemodynamic plan 與 equipment。", "RSI 結合 induction agent 與 NMBA；選擇需考量 hypotension、neurologic status、contraindications。", "Etomidate、ketamine、propofol、succinylcholine 與 rocuronium 具不同效應及風險。"]}, {"title": "Ventilator management 與藥師角色", "bullets": ["ABG 與 ventilator settings 必須一起解讀，分清 oxygenation 與 ventilation 問題。", "Intubation 後立即評估 analgesia、sedation、paralysis duration 及藥物給藥途徑。", "持續評估撤機條件，並與 PADIS、fluid management 及 prophylaxis 協同。"]}], "pearls": ["Low tidal volume 的體重基準很重要。", "RSI 完成後仍需立刻規劃持續 analgesia 與 sedation。"], "files": [{"name": "18 Pulmonary Disorders I.pdf", "url": "pdf/ch18.pdf"}], "titleEn": "Pulmonary Disorders I"}, {"id": 19, "titleZh": "Pulmonary Disorders II：CF、Pulmonary Hypertension、Asthma 與 COPD", "sections": [{"title": "Cystic fibrosis", "bullets": ["CFTR dysfunction 造成黏稠分泌物、airway obstruction 與反覆感染。", "Exacerbation 抗菌治療依先前 respiratory cultures、susceptibilities 與病人反應調整。", "照護亦包括 airway clearance、nutrition、pancreatic support 及適用的 CFTR modulators。"]}, {"title": "Pulmonary hypertension 分型", "bullets": ["PH 需依 underlying mechanism 與 WHO group 分型，避免將所有 PH 視為 PAH。", "評估 right ventricular function、hemodynamics、functional status 與病因。", "Hypoxia、acidosis、volume problems 及 interrupted chronic therapy 可加重 RV failure。"]}, {"title": "PAH therapy 與 ICU 支持", "bullets": ["Prostacyclin pathway、endothelin receptor antagonists 與 nitric oxide pathway agents 機轉不同。", "Epoprostenol 等持續 therapy 需維持正確供應與給藥，避免非預期中斷。", "急性 RV failure 管理結合 oxygenation、volume、perfusion 及特定 pulmonary vasodilators。"]}, {"title": "Severe asthma exacerbation", "bullets": ["Assess severity using symptoms、work of breathing、oxygenation 及對初始 therapy 的反應。", "Inhaled SABA、ipratropium 及 systemic corticosteroids 是重要療法；特定嚴重情境考量 IV magnesium。", "無法控制的 deterioration 需評估 intubation，並留意 dynamic hyperinflation 與 hemodynamic consequences。"]}, {"title": "COPD exacerbation", "bullets": ["治療整合 bronchodilators、systemic corticosteroids、適當 oxygen 與必要時 ventilatory support。", "Antimicrobials 依 sputum purulence、其他 cardinal symptoms、ventilation need 及 local resistance 評估。", "Noninvasive ventilation 適用於特定 hypercapnic respiratory failure 情境，需持續評估失敗風險。"]}], "pearls": ["WHO group 與 RV function 影響 PH 的治療。", "Asthma 與 COPD 的急性支持有共同點，但治療條件不可直接互換。"], "files": [{"name": "19 Pulmonary Disorders II.pdf", "url": "pdf/ch19.pdf"}], "titleEn": "Pulmonary Disorders II"}, {"id": 20, "titleZh": "Toxicology", "sections": [{"title": "初步評估與支持", "bullets": ["Poisoning 首先處理 airway、breathing、circulation，再進行針對性 diagnostics。", "整合暴露藥物、dose、time、formulation、症狀、ECG、glucose、electrolytes 與 acid–base。", "Toxicology screen 的陽性或陰性結果都有侷限，不能取代 history、toxidrome 與臨床判斷。"]}, {"title": "Decontamination 與 Enhanced elimination", "bullets": ["Activated charcoal、whole bowel irrigation 等需評估物質、時間窗、airway 與 contraindications。", "不建議對每次暴露例行使用單一 decontamination 方法。", "Urinary alkalinization 或 extracorporeal elimination 僅適用於特定毒物及嚴重度。"]}, {"title": "Acetaminophen 與 Salicylates", "bullets": ["Acetaminophen toxicity 使用 acetylcysteine；晚期或時間不明的暴露不能僅依單次藥物濃度判斷。", "Rumack–Matthew nomogram 有時間及暴露型態限制，不適用所有 chronic 或 unknown-time ingestion。", "Salicylate toxicity 需追蹤 acid–base、electrolytes、serial concentrations 與 neurological status，評估 alkalinization 或 dialysis。"]}, {"title": "Opioids、Alcohols 與 Withdrawal", "bullets": ["Opioid toxicity 先支持 ventilation，再以 naloxone 調整至適當呼吸反應；可能需重複給藥或 infusion。", "Methanol 與 ethylene glycol 的 toxic metabolites 可造成嚴重 acidosis 及 organ injury，需評估 antidote 與 dialysis。", "Alcohol withdrawal 以 benzodiazepines 為主要 therapy，並處理營養、electrolytes 及相關併發症。"]}, {"title": "Cardiovascular 與 Psychotropic poisoning", "bullets": ["β-blockers 與 calcium channel blockers 可造成 bradycardia、conduction abnormalities 與 shock。", "章節涵蓋 calcium、high-dose insulin therapy、vasopressors 及其他 rescue options 的適用情境。", "Digoxin toxicity、TCA 及 atypical antipsychotic poisoning 需針對 arrhythmias、QRS/QT、neurologic symptoms 與適當 antidote 或支持療法處理。"]}], "pearls": ["支持 vital functions 優先於確認所有毒物細節。", "Antidote 不能取代 serial monitoring 與 supportive care。"], "files": [{"name": "20 Toxicology.pdf", "url": "pdf/ch20.pdf"}], "titleEn": "Toxicology"}], "questions": [{"id": "01-self-01", "chapter": 1, "type": "self", "number": 1, "stem": "Which is the journal that, in 1982, was the first to publish a critical care therapeutics column?", "context": "", "options": [{"key": "A", "text": "Drug Intelligence and Clinical Pharmacy.", "sourceKey": "A"}, {"key": "B", "text": "Pharmacotherapy.", "sourceKey": "B"}, {"key": "C", "text": "Chest.", "sourceKey": "C"}, {"key": "D", "text": "Heart & Lung.", "sourceKey": "D"}], "answer": "A", "explanation": "The journal Drug Intelligence and Clinical Pharmacy (now Annals of Pharmacotherapy) was the first to publish a critical care therapeutics column in 1982, which was a landmark event relative to the evolution of critical care pharmacy (Answer A). Although the other journals listed—Pharmacotherapy (Answer B), Chest (Answer C), and Heart and Lung (Answer D)—publish critical care therapeutics articles, Annals of Pharmacotherapy was the first to incorporate a critical care therapeutics column into its publication.", "page": 4, "answerPage": 43, "stemZh": "哪一期刊在 1982 年率先刊登 critical care therapeutics 專欄？", "optionsZh": [{"key": "A", "text": "Drug Intelligence and Clinical Pharmacy。"}, {"key": "B", "text": "Pharmacotherapy。"}, {"key": "C", "text": "Chest。"}, {"key": "D", "text": "Heart & Lung。"}], "explanationZh": "Drug Intelligence and Clinical Pharmacy（現為 Annals of Pharmacotherapy）於 1982 年率先刊登 critical care therapeutics 專欄，是 critical care pharmacy 發展的重要里程碑。其他期刊雖刊登相關文章，並非首先設立此專欄。", "contextZh": ""}, {"id": "01-self-02", "chapter": 1, "type": "self", "number": 2, "stem": "The scope of pharmacy practice within the intensive care unit (ICU) was outlined by two task forces focused on models of critical care delivery, the definition of an intensivist, and the practice of critical care medicine within three different proposed models in 2001. Which best depicts the professional organization that formed these two task forces?", "context": "", "options": [{"key": "A", "text": "National Academy of Medicine (formerly Institute of Medicine).", "sourceKey": "A"}, {"key": "B", "text": "American College of Clinical Pharmacy (ACCP).", "sourceKey": "B"}, {"key": "C", "text": "American College of Critical Care Medicine (ACCM).", "sourceKey": "C"}, {"key": "D", "text": "Clinical Pharmacy and Pharmacology Section of the Society of Critical Care Medicine (SCCM).", "sourceKey": "D"}], "answer": "C", "explanation": "In 2001, ACCM, which exists within the organizational framework of SCCM, formed the two task forces focused on models of critical care delivery, the definition of an intensivist, and the practice of critical care medicine within three different proposed models (Answer C). Neither the Institute of Medicine (Answer A) nor ACCP (Answer B) was involved in formulating the levels of critical care delivery. Although the Clinical Pharmacy and Pharmacology Section of SCCM (Answer D) may have contributed to this document, it is not mentioned in the publication.", "page": 4, "answerPage": 43, "stemZh": "2001 年有兩個工作小組針對 critical care 服務模式、intensivist 定義，以及三種建議模式下的 critical care medicine 執業，界定 ICU 藥事執業範圍。哪個專業組織成立這兩個工作小組？", "optionsZh": [{"key": "A", "text": "National Academy of Medicine（前身為 Institute of Medicine）。"}, {"key": "B", "text": "American College of Clinical Pharmacy（ACCP）。"}, {"key": "C", "text": "American College of Critical Care Medicine（ACCM）。"}, {"key": "D", "text": "Society of Critical Care Medicine（SCCM）的 Clinical Pharmacy and Pharmacology Section。"}], "explanationZh": "隸屬 SCCM 組織架構的 ACCM 於 2001 年成立兩個工作小組。Institute of Medicine 與 ACCP 未參與制定 critical care 服務層級；原文也未將此工作歸於 SCCM 的 Clinical Pharmacy and Pharmacology Section。", "contextZh": ""}, {"id": "01-self-03", "chapter": 1, "type": "self", "number": 3, "stem": "Which best depicts the medical event that has been documented to be associated with a lower mortality in ICUs with clinical pharmacists compared with ICUs without clinical pharmacists?", "context": "", "options": [{"key": "A", "text": "Corrected QT (QTc)-interval prolongation.", "sourceKey": "A"}, {"key": "B", "text": "Preventable adverse drug interactions.", "sourceKey": "B"}, {"key": "C", "text": "Drug-drug interactions.", "sourceKey": "C"}, {"key": "D", "text": "Thromboembolic/infarction-related events.", "sourceKey": "D"}], "answer": "D", "explanation": "In a 2009 study by MacClaren and Bond, mortality increased in thromboembolic and infarction-related events in ICU patients without clinical pharmacy services compared with ICU patients with clinical pharmacy services: 37%, p<0.0001 (Answer D). Although the impact of clinical pharmacists in affecting QTc-interval prolongation (Answer A), preventable adverse drug interactions (Answer B), and drug-drug interactions (Answer C) has been evaluated, differences in mortality have not been documented. Therefore, these answers are incorrect.", "page": 4, "answerPage": 43, "stemZh": "與沒有 clinical pharmacist 的 ICU 相比，有 clinical pharmacist 的 ICU 已被證實在哪一類醫療事件中死亡率較低？", "optionsZh": [{"key": "A", "text": "Corrected QT（QTc）interval 延長。"}, {"key": "B", "text": "可預防的 adverse drug interactions。"}, {"key": "C", "text": "Drug-drug interactions。"}, {"key": "D", "text": "Thromboembolic／infarction 相關事件。"}], "explanationZh": "MacClaren 與 Bond 的 2009 年研究指出，沒有 clinical pharmacy 服務的 ICU 病人，其 thromboembolic／infarction 相關事件死亡率增加 37%，p<0.0001。其他三項雖曾研究 clinical pharmacist 的影響，尚未證實死亡率差異。", "contextZh": ""}, {"id": "01-self-04", "chapter": 1, "type": "self", "number": 4, "stem": "Which best describes what is deemed a core knowledge base area for pharmacists caring for critically ill patients?", "context": "", "options": [{"key": "A", "text": "Nephrology.", "sourceKey": "A"}, {"key": "B", "text": "Dermatology.", "sourceKey": "B"}, {"key": "C", "text": "Rheumatology.", "sourceKey": "C"}, {"key": "D", "text": "Obstetrics.", "sourceKey": "D"}], "answer": "A", "explanation": "The core knowledge areas for pharmacists caring for critically ill patients include pulmonary, cardiology, psychiatry, oncology, neuroscience, nephrology, hepatology, nutrition, gastroenterology, surgery, trauma, burn, pharmacology, transplantation, supportive care, medical emergencies, immunology, endocrinology, hematology, nephrology, toxicology, and surgery. Therefore, nephrology (Answer A) is correct. Dermatology (Answer B), rheumatology (Answer C), and obstetrics (Answer D) are not considered core knowledge areas and are therefore incorrect.", "page": 4, "answerPage": 43, "stemZh": "哪個領域屬於照護 critically ill patients 的藥師應具備的核心知識？", "optionsZh": [{"key": "A", "text": "Nephrology。"}, {"key": "B", "text": "Dermatology。"}, {"key": "C", "text": "Rheumatology。"}, {"key": "D", "text": "Obstetrics。"}], "explanationZh": "Nephrology 屬於 critical care pharmacist 的核心知識領域。Dermatology、Rheumatology 與 Obstetrics 未被列為該核心知識範圍。", "contextZh": ""}, {"id": "01-self-05", "chapter": 1, "type": "self", "number": 5, "stem": "Which most accurately reflects the journal that published a landmark study documenting a decrease in preventable adverse drug reactions after the inclusion of pharmacists on interdisciplinary medical rounds?", "context": "", "options": [{"key": "A", "text": "New England Journal of Medicine.", "sourceKey": "A"}, {"key": "B", "text": "Lancet.", "sourceKey": "B"}, {"key": "C", "text": "Journal of the American Medical Association.", "sourceKey": "C"}, {"key": "D", "text": "Annals of Internal Medicine.", "sourceKey": "D"}], "answer": "C", "explanation": "The landmark study documenting a decrease in preventable adverse drug reactions after the inclusion of pharmacists on interdisciplinary medical rounds was published in the Journal of the American Medical Association by Dr. Lucian Leape and colleagues (Answer C). This highly publicized article published in a mainstream medical journal by a physician remains one of the foundational studies documenting the association of critical care pharmacy services with favorable health care outcomes. The other mainstream medical journals listed, New England Journal of Medicine (Answer A), Lancet (Answer B), and Annals of Internal Medicine (Answer D), have not published similar articles on preventable adverse drug reactions after the inclusion of pharmacists on interdisciplinary medical rounds.", "page": 4, "answerPage": 43, "stemZh": "哪一期刊刊登了重要研究，證實藥師參與跨專業醫療查房後，可預防的 adverse drug reactions 減少？", "optionsZh": [{"key": "A", "text": "New England Journal of Medicine。"}, {"key": "B", "text": "Lancet。"}, {"key": "C", "text": "Journal of the American Medical Association。"}, {"key": "D", "text": "Annals of Internal Medicine。"}], "explanationZh": "Dr. Lucian Leape 與同事的研究刊登於 Journal of the American Medical Association，為 critical care pharmacy 服務與良好醫療結果相關的重要基礎研究。其餘列出的期刊並未刊登題述研究。", "contextZh": ""}, {"id": "01-self-06", "chapter": 1, "type": "self", "number": 6, "stem": "There were eight American Society of HealthSystem Pharmacists (ASHP)-accredited critical care pharmacy residencies in 2001. Which annual absolute value represents the approximate increase in ASHP-accredited critical care residencies between 2001 and 2021?", "context": "", "options": [{"key": "A", "text": "5.", "sourceKey": "A"}, {"key": "B", "text": "8.", "sourceKey": "B"}, {"key": "C", "text": "12.", "sourceKey": "C"}, {"key": "D", "text": "15.", "sourceKey": "D"}], "answer": "B", "explanation": "As stated, there were eight ASHP-accredited critical care pharmacy residencies in 2001. In 2021, ASHP notes 168 ASHP-accredited critical care pharmacy residencies. Assuming linear growth, the 160-residency increase over 20 years equals an increase of eight residencies per year (Answer B is correct). Although this represents significant growth, more than 2200 pharmacists would be needed to provide critical care pharmacy services, assuming 30 patients/pharmacists in the more than 67,000 adult ICU beds in the United States as of 2009. Answer A (5 residencies/year), Answer C (12 residencies/ year), and Answer D (15 residencies/year) are incorrect.", "page": 5, "answerPage": 43, "stemZh": "2001 年有 8 個 ASHP 認證的 critical care pharmacy residency。2001 至 2021 年間，這類 residency 平均每年約增加多少個？", "optionsZh": [{"key": "A", "text": "5。"}, {"key": "B", "text": "8。"}, {"key": "C", "text": "12。"}, {"key": "D", "text": "15。"}], "explanationZh": "2021 年共有 168 個 ASHP 認證的 critical care pharmacy residency。假設線性成長，20 年增加 160 個，即每年增加 8 個。5、12 或 15 個／年均不符合此計算。", "contextZh": ""}, {"id": "01-self-07", "chapter": 1, "type": "self", "number": 7, "stem": "Which best reflects the current conventional or preferred postgraduate training pathway to clinical pharmacy practice in an ICU providing level I services?", "context": "", "options": [{"key": "A", "text": "Postgraduate year 1 (PGY1) residency with focused critical care rotations.", "sourceKey": "A"}, {"key": "B", "text": "PGY1 residency followed by on-the-job mentored training.", "sourceKey": "B"}, {"key": "C", "text": "PGY1 and PGY2 critical care residency.", "sourceKey": "C"}, {"key": "D", "text": "PGY1 and critical care traineeship.", "sourceKey": "D"}], "answer": "C", "explanation": "The preferred and recommended pathway to training in critical care pharmacy is a PGY1 pharmacy practice residency, followed by a PGY2 critical care residency. This is especially true for the provision of desirable-tooptimal pharmacy services in ICUs providing level I and II services. Critical care fellowship training is an option that would also be considered preferred; however, the intent is for a greater research and academic focus. The demands of the workplace often exceed the supply of PGY2-trained critical care pharmacists. And although many of the alternative pathways available to gaining experience, knowledge, and skills in critical care pharmacy have been successful, these are not considered preferred pathways, given the high degree of variability and inconsistency of resources to support them, therefore options A, B and D are non-preferred alternative pathways and are incorrect.", "page": 5, "answerPage": 43, "stemZh": "在提供 level I 服務的 ICU 從事 clinical pharmacy，目前一般建議或偏好的畢業後訓練途徑是什麼？", "optionsZh": [{"key": "A", "text": "PGY1 residency，含重點 critical care rotations。"}, {"key": "B", "text": "PGY1 residency 後接受在職導師訓練。"}, {"key": "C", "text": "PGY1 residency 加上 PGY2 critical care residency。"}, {"key": "D", "text": "PGY1 residency 加上 critical care traineeship。"}], "explanationZh": "建議途徑為先完成 PGY1 pharmacy practice residency，再完成 PGY2 critical care residency，尤其適用於提供 level I 與 II 服務的 ICU。其他途徑也可能成功，但資源與訓練一致性差異較大，因此並非優先建議途徑。", "contextZh": ""}, {"id": "01-self-08", "chapter": 1, "type": "self", "number": 8, "stem": "When considering the five principles of team-based health care delineated in the Institute of Medicine (now National Academy of Medicine) discussion paper, which of the other four principles is effective communication most tightly linked to?", "context": "", "options": [{"key": "A", "text": "Shared goals.", "sourceKey": "A"}, {"key": "B", "text": "Clear roles.", "sourceKey": "B"}, {"key": "C", "text": "Mutual trust.", "sourceKey": "C"}, {"key": "D", "text": "Measurable processes and outcomes.", "sourceKey": "D"}], "answer": "C", "explanation": "Even though the principles of team-based health care are all interdependent, effective communication is most tightly linked to mutual trust. Open and frank communication and the willingness to state your beliefs and challenge those of your teammates require a high level of mutual trust to keep the relationship and conversation professional and nonpersonal. Without mutual trust, communication can be more guarded, ineffective, and political. Options A, B and D are relevant principles of team-based healthcare, but not as tightly linked to effective communication, and are incorrect.", "page": 5, "answerPage": 44, "stemZh": "Institute of Medicine（現為 National Academy of Medicine）提出 team-based health care 的五項原則。有效溝通與其餘哪一項原則關係最密切？", "optionsZh": [{"key": "A", "text": "共同目標。"}, {"key": "B", "text": "明確角色。"}, {"key": "C", "text": "相互信任。"}, {"key": "D", "text": "可衡量的流程與結果。"}], "explanationZh": "有效溝通最仰賴相互信任。坦誠表達、提出不同看法或挑戰隊友觀點，都需要信任才能維持專業對話。其他原則也重要，但與有效溝通的連結不如相互信任密切。", "contextZh": ""}, {"id": "01-self-09", "chapter": 1, "type": "self", "number": 9, "stem": "Which statement is most accurate concerning the mentor-mentee relationship as it pertains to the training and development of critical care pharmacists?", "context": "", "options": [{"key": "A", "text": "Formal mentoring relationships are restricted to residency and fellowships.", "sourceKey": "A"}, {"key": "B", "text": "Voluntary relationships that evolve and develop through mutual interests have the greatest likelihood of success.", "sourceKey": "B"}, {"key": "C", "text": "Mentored training programs are the only reliable pathway for the nonconventional training of critical care pharmacists.", "sourceKey": "C"}, {"key": "D", "text": "Most successful critical care pharmacists have a single relevant mentor-mentee relationship during their training and development.", "sourceKey": "D"}], "answer": "B", "explanation": "Although structured mentor-mentee programs can be successful, there is a greater probability of success with relationships that are voluntary and that evolve from mutual interests and a perceived opportunity to have a mutually beneficial relationship. Mentors must be willing to serve in this role, which can require a great deal of time and effort; they wish to work with mentees who are highly motivated with a track record of accepting challenges. Moreover, mentees must be responsive to feedback and teaching. Mentees seek out mentors with shared interests, a record of sharing their time and expertise, and the necessary prestige and position in the organization to promote and create opportunities for them. In an arranged relationship, it is less likely that all of these factors will come together to lead to a highly productive relationship. Mentoring relationships can exist both within and outside formal training programs like residencies and fellowships so option A is incorrect, and clinical pharmacists will often have several mentors through the different stages of their career to address different and evolving needs as they mature in their practice and scholarly activities so option D is incorrect. Finally, although mentored training programs are a viable option for the nonconventional training of critical care pharmacists, they are not an exclusive pathway so option C is incorrect.", "page": 5, "answerPage": 44, "stemZh": "關於 critical care pharmacist 訓練與發展中的 mentor–mentee 關係，哪個敘述最正確？", "optionsZh": [{"key": "A", "text": "正式 mentorship 僅限於 residency 與 fellowship。"}, {"key": "B", "text": "基於共同興趣，自願形成並逐步發展的關係，最可能成功。"}, {"key": "C", "text": "Mentored training program 是 critical care pharmacist 非傳統訓練唯一可靠的途徑。"}, {"key": "D", "text": "多數成功的 critical care pharmacist 在訓練與發展期間只有一段重要的 mentor–mentee 關係。"}], "explanationZh": "基於共同興趣、自願投入且互利的 mentorship 最可能成功。Mentorship 可存在於正式訓練內外；藥師可在不同職涯階段有多位 mentor。Mentored training 也是非傳統訓練的可行途徑，但並非唯一途徑。", "contextZh": ""}, {"id": "01-self-10", "chapter": 1, "type": "self", "number": 10, "stem": "Which is the most accurate description of the relationship between the continuing pharmacy education (CPE) and the continuing professional development (CPD) of clinical pharmacists?", "context": "", "options": [{"key": "A", "text": "CPE and CPD are two distinctly different processes for continuing development.", "sourceKey": "A"}, {"key": "B", "text": "CPD is an individualized, self-directed, and iterative process of development that replaces traditional CPE.", "sourceKey": "B"}, {"key": "C", "text": "CPE is strictly a didactic process, whereas CPD incorporates many different learning strategies and techniques.", "sourceKey": "C"}, {"key": "D", "text": "CPD is an individualized, self-directed process that typically incorporates relevant CPE as one of the learning strategies.", "sourceKey": "D"}], "answer": "D", "explanation": "Continuing pharmacy education should be included as an important strategy in a CPD PDP, and therefore options A and B are incorrect. The self-directed learner should select CPE programs that are relevant to their PDP, incorporate active learning strategies, are preferably curricular based, and are free of commercial or other bias. Continuing professional development is not an alternative to CPE; rather, it is an individualized, selfdirected, continuous, and iterative process intended to address specific learning objectives developed over time by the pharmacist-learner. Continuing pharmacy education is an important component of this process, but it should not be the only learning strategy. Both CPD and CPE can include multiple learning strategies, so option C is incorrect.", "page": 5, "answerPage": 44, "stemZh": "哪個敘述最正確描述 clinical pharmacist 的 continuing pharmacy education（CPE）與 continuing professional development（CPD）之關係？", "optionsZh": [{"key": "A", "text": "CPE 與 CPD 是兩種完全不同的持續發展流程。"}, {"key": "B", "text": "CPD 是個別化、自主且反覆循環的發展流程，取代傳統 CPE。"}, {"key": "C", "text": "CPE 僅採講授方式，CPD 則包含多種學習策略與技巧。"}, {"key": "D", "text": "CPD 是個別化、自主的流程，通常將相關 CPE 納入學習策略之一。"}], "explanationZh": "CPD 是個別化、自主、持續且反覆循環的發展流程，CPE 應是 personal development plan（PDP）的重要策略之一。CPD 並未取代 CPE，兩者皆可包含多種學習方式。", "contextZh": ""}, {"id": "01-self-11", "chapter": 1, "type": "self", "number": 11, "stem": "Which statement is most accurate relative to the recently published standards of care and standardized process of care for clinical pharmacy when considering critical care pharmacy practice?", "context": "", "options": [{"key": "A", "text": "ICUs are highly individualized practice environments that cannot easily conform to broad-based, discipline-wide standards.", "sourceKey": "A"}, {"key": "B", "text": "Critical care pharmacists have knowledge and skill sets that are specific to their practice style and environment and are not consistent with the standards.", "sourceKey": "B"}, {"key": "C", "text": "The standards of care and standardized process of care are very consistent with critical care pharmacy practice standards and expectations.", "sourceKey": "C"}, {"key": "D", "text": "The standard process of care, which has evolved around the “provider status” efforts, is primarily applicable to the ambulatory, primary care environment of practice.", "sourceKey": "D"}], "answer": "C", "explanation": "The recently published Standards of Practice for Clinical Pharmacy, which includes a standardized process of care endorsed by all major pharmacy practitioner organizations, is intended to be applicable to any practice environment, regardless of acuity or complexity. Like other professions (e.g., medicine, nursing, physical therapy), clinical pharmacy must define and apply standards of care to create consistent expectations by all stakeholders. It is often argued that clinical pharmacists in different complex or unique practice environments cannot possibly conform to a standard of care; however, a thoughtful review of the Standards of Practice for Clinical Pharmacy reveals that it can be easily incorporated into any practice environment, and therefore options A, B and D are incorrect.", "page": 5, "answerPage": 44, "stemZh": "就 critical care pharmacy 執業而言，關於近期發表的 clinical pharmacy 照護標準與標準化照護流程，哪個敘述最正確？", "optionsZh": [{"key": "A", "text": "ICU 執業環境高度個別化，不容易遵循整個專業領域的廣泛標準。"}, {"key": "B", "text": "Critical care pharmacist 的知識與技能依其執業風格和環境而定，與標準不一致。"}, {"key": "C", "text": "照護標準與標準化照護流程，和 critical care pharmacy 的執業標準及期待高度一致。"}, {"key": "D", "text": "由 provider status 推動而形成的標準照護流程，主要適用於門診 primary care 環境。"}], "explanationZh": "Standards of Practice for Clinical Pharmacy 及其標準照護流程，適用於各種急重症程度與複雜度的執業環境，也可融入 critical care pharmacy。制定與應用標準可讓各利害關係人有一致期待。", "contextZh": ""}, {"id": "01-self-12", "chapter": 1, "type": "self", "number": 12, "stem": "Which is the best example of an audience that has not traditionally been an important focus of critical care pharmacists’ educational and teaching efforts?", "context": "", "options": [{"key": "A", "text": "Patients and families.", "sourceKey": "A"}, {"key": "B", "text": "Pharmacy students.", "sourceKey": "B"}, {"key": "C", "text": "Critical care physicians.", "sourceKey": "C"}, {"key": "D", "text": "Critical care nurses.", "sourceKey": "D"}], "answer": "A", "explanation": "Clinical pharmacists practicing in the ICU have long had a broad educational role that includes students and residents in their own profession, residents and students in other professions, and colleagues on the critical care team, as well as coworkers in the pharmacy department, among the target audiences. Clinical pharmacists have used many different strategies and techniques to teach these diverse audiences across different learning environments. Although there are exceptions, the frequent or regular inclusion of patients and families in their educational activities is a more recent development. Many factors have led to this change, including a greater focus on patient- and family-centered care, greater inclusion of patients and families as members of the team, increased demand for inclusion by patients and families, inclusion of patient satisfaction scores in pay-for-performance metrics (including pain control and understanding of medications), and greater patient awareness and interaction in the ICU with changes in sedation goals. It is anticipated that clinical pharmacists in the ICU will increasingly be directly involved in patient and family discussions and education. Options B, C and D all represent traditional audiences for clinical pharmacist educational efforts and are therefore incorrect.", "page": 5, "answerPage": 44, "stemZh": "哪一群對象在傳統上較不是 critical care pharmacist 教育與教學的主要重點？", "optionsZh": [{"key": "A", "text": "病人及家屬。"}, {"key": "B", "text": "藥學學生。"}, {"key": "C", "text": "Critical care physicians。"}, {"key": "D", "text": "Critical care nurses。"}], "explanationZh": "藥師傳統上常教導學生、residents 與 critical care 團隊成員；規律納入病人與家屬是較近期的發展，與以病人及家屬為中心的照護及 ICU 病人互動增加有關。", "contextZh": ""}, {"id": "01-self-13", "chapter": 1, "type": "self", "number": 13, "stem": "As part of the reflection stage of the CPD process, which would be the best example of an episodic opportunity for self-assessment?", "context": "", "options": [{"key": "A", "text": "An annual 360-degree peer evaluation providing feedback that your coworker believes you do not contribute adequately on departmental initiatives.", "sourceKey": "A"}, {"key": "B", "text": "Recognition that the usual approach to training and assessing a challenging student on rotation was ineffective.", "sourceKey": "B"}, {"key": "C", "text": "A self-evaluation of the past year’s accomplishments for your direct supervisor.", "sourceKey": "C"}, {"key": "D", "text": "An annual performance evaluation with specific goals for the coming year.", "sourceKey": "D"}], "answer": "B", "explanation": "In the context of CPD, episodic opportunities for reflection refer to spontaneous, unscheduled events that contribute to the self-assessment of learning and training needs that can be incorporated into the overall PDP. Scheduled reflection usually involves a predictable cycle like performance evaluations, annual self-evaluations, peer feedback as part of annual assessment, or a decision to schedule reflection around some set anniversary (e.g., hire dates, birthdays, end of academic year), and therefore options A, C and D are incorrect. Examples of opportunity for episodic reflection may include the challenges of managing a very difficult case, postevent debriefings for code responses, experiences with a difficult student or resident, or a request to develop a treatment guideline that is outside the clinician’s usual area of expertise.", "page": 6, "answerPage": 45, "stemZh": "在 CPD 的反思階段，哪個例子最符合偶發性的自我評估機會？", "optionsZh": [{"key": "A", "text": "年度 360-degree 同儕評估指出，同事認為你對部門計畫的貢獻不足。"}, {"key": "B", "text": "察覺慣用的訓練與評估方式，對某位難以帶領的輪訓學生無效。"}, {"key": "C", "text": "向直屬主管提交過去一年成果的自我評估。"}, {"key": "D", "text": "年度績效評估並設定下一年的明確目標。"}], "explanationZh": "偶發性反思源於自發、未預定的事件，例如困難個案、急救後檢討或帶領困難學生的經驗。年度評估、自評與同儕回饋屬於預定的反思機會。", "contextZh": ""}, {"id": "01-self-14", "chapter": 1, "type": "self", "number": 14, "stem": "Which would be considered the most valid reason for recommending the rejection of a manuscript as a scientific reviewer?", "context": "", "options": [{"key": "A", "text": "Poor syntax and word choices.", "sourceKey": "A"}, {"key": "B", "text": "A methodological flaw that results in incorrect data.", "sourceKey": "B"}, {"key": "C", "text": "A disagreement concerning the statistical analysis presented in the manuscript.", "sourceKey": "C"}, {"key": "D", "text": "Results presented in the abstract that are inconsistent with results presented in a table.", "sourceKey": "D"}], "answer": "B", "explanation": "A methodological flaw that results in the collection and reporting of incorrect data would be considered a “fatal flaw” that no amount of rewriting or reanalysis could correct. Poor writing can be corrected with revision by the authors or during copyediting, but if the study is well conducted and has value, this would not necessarily be a reason to recommend rejection so option A is incorrect. Disagreements concerning statistical analysis are not uncommon; however, the authors may have a valid explanation or be able to revise the statistical analysis if it is not a major departure from the original intent of the study meaning option C is incorrect. It is also not uncommon for the abstract to disagree in some way with the body of the manuscript, and there is an opportunity to correct that during revisions so option D is also incorrect.", "page": 6, "answerPage": 45, "stemZh": "擔任科學審稿者時，哪個理由最足以建議拒絕稿件？", "optionsZh": [{"key": "A", "text": "語法與用詞不佳。"}, {"key": "B", "text": "Methodology 有缺陷，導致資料錯誤。"}, {"key": "C", "text": "不同意稿件使用的 statistical analysis。"}, {"key": "D", "text": "摘要結果與表格結果不一致。"}], "explanationZh": "導致錯誤資料且無法透過修訂補救的 methodology 缺陷，是拒稿的充分理由。語法、用詞、統計方法爭議或摘要與表格不一致，通常可透過修訂處理。", "contextZh": ""}, {"id": "02-self-01", "chapter": 2, "type": "self", "number": 1, "stem": "A clinical trial is being planned to determine the optimal resuscitation fluid for trauma patients. This study will seek to determine whether administering crystalloid fluid, such as lactated Ringer solution, or a transfusion strategy involving packed red blood cells in the trauma field improves survival to hospital discharge. The investigator team has consulted with various ethics scholars to identify relevant issues to be addressed in the trial design. Which issue is most relevant to the ethical conduct of this study?", "context": "", "options": [{"key": "A", "text": "Treatment blinding.", "sourceKey": "A"}, {"key": "B", "text": "Uninformative study population.", "sourceKey": "B"}, {"key": "C", "text": "Consent obtained from injured subjects.", "sourceKey": "C"}, {"key": "D", "text": "Design as a noninferiority trial.", "sourceKey": "D"}], "answer": "C", "explanation": "This study seeks to compare two viable treatments of hypovolemic shock in trauma patients. Because subject identification would be trauma patients from the community and treatment would be initiated in the field, potential harm is associated with each treatment, and it is expected that many potential patients would lack decisional capacity at the time of informed consent. Although treatment blinding is an essential component to trial design to limit investigator and clinician bias, it is not an ethical consideration (Answer A is incorrect). Given the incidence of trauma in the general population and its burden on society, treatments to improve the outcomes of trauma patients are necessary and informative (Answer B is incorrect). Acknowledging the limited supply of blood products, a superiority trial is essential to help steward the use of a finite resource (Answer D is incorrect). The issue of informed consent in this study is challenging, but the issue needs to be addressed for the ethical conduct of this study (Answer C is correct). There is precedent for this trial to receive an exception for informed consent requirements under the FDA code of regulations.", "page": 4, "answerPage": 31, "stemZh": "計畫進行 clinical trial，評估 trauma 病人最佳 resuscitation fluid，比較現場給予 crystalloid（如 lactated Ringer solution）或 packed red blood cells transfusion，何者改善存活至出院。研究團隊已諮詢倫理學者。哪個議題最關乎此研究的倫理？", "contextZh": "", "optionsZh": [{"key": "A", "text": "治療 blinding。"}, {"key": "B", "text": "無法提供有用資訊的研究族群。"}, {"key": "C", "text": "取得受傷研究對象的 consent。"}, {"key": "D", "text": "採用 noninferiority trial 設計。"}], "explanationZh": "現場 trauma 病人常無法在治療前自主提供 informed consent，而兩種治療皆有風險，因此 consent 是核心倫理難題。Blinding 主要控制偏差；此研究有社會價值；有限血品資源應以 superiority trial 評估。FDA 法規亦有 informed consent 例外的先例。"}, {"id": "02-self-02", "chapter": 2, "type": "self", "number": 2, "stem": "The investigators of a new study are seeking to identify the optimal end point or study population to test the effectiveness of a novel drug compound for septic shock. The novel drug compound is a recombinant protein that mediates the inflammatory cascade of sepsis and has had impressive results for all etiologies of septic shock in preclinical animal studies. Historical estimates of septic shock mortality are 35%–40% in previous studies from the past 10 years; this guides the investigators to calculate a required sample size of ~800 patients to achieve 80% power. A more recent study of septic shock reported 28-day mortality to be 20% in the standard treatment arm. Which best describes the rationale for selecting a study population or primary end point?", "context": "", "options": [{"key": "A", "text": "The study should limit study inclusion to patients without a high level of comorbid conditions at baseline to limit confounders.", "sourceKey": "A"}, {"key": "B", "text": "The study should expand the target population to include patients with sepsis, not just septic shock, to show a 28-day mortality benefit.", "sourceKey": "B"}, {"key": "C", "text": "The sample size of the new study will need to be larger than earlier studies to increase likelihood of obtaining power.", "sourceKey": "C"}, {"key": "D", "text": "The study should limit study inclusion to patients with septic shock caused by pneumonia to test a relevant study population.", "sourceKey": "D"}], "answer": "C", "explanation": "The study seeks to establish the effectiveness of a novel drug compound for septic shock. This is challenging because of the dramatic improvements in 28-day mortality during the past decade. To show the effectiveness of a novel drug compound, the drug should be tested in a representative population of patients with the disease. Excluding patients because of baseline comorbidity would limit external validity (Answer A is incorrect). Including patients with sepsis, which has a lower 28-day mortality rate than septic shock, would not address the issue of an appropriate end point (Answer B is incorrect). Limiting study inclusion to patients with a pneumonia etiology would be inappropriate unless the pharmacology of the novel drug specifically targeted pneumonia pathophysiology (Answer D is incorrect). Answer C is correct as the anticipated incidence of mortality has changed overtime as well as the likely anticipated minimum detectable effect. With all other assumptions remaining equal, the authors will have to increase enrollment to find the effect relative to previous trials.", "page": 4, "answerPage": 31, "stemZh": "研究團隊欲評估 septic shock 新藥的最佳 end point 或族群。此 recombinant protein 調控 sepsis inflammatory cascade，動物研究對各種 septic shock 病因皆有良好效果。過去 10 年研究死亡率為 35%–40%，據此估計需 ~800 人達 80% power；近期研究 standard treatment 組 28-day mortality 僅 20%。選擇族群或 primary end point 的最佳理由為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "排除基線高度 comorbidity 病人，以減少 confounders。"}, {"key": "B", "text": "納入 sepsis 病人而不限 septic shock，以顯示 28-day mortality 益處。"}, {"key": "C", "text": "新研究需比先前研究更大的 sample size，以提高達到 power 的可能性。"}, {"key": "D", "text": "僅納入 pneumonia 引起的 septic shock，以測試相關族群。"}], "explanationZh": "預期死亡事件率降低，且可能可偵測的最小效果也改變；其他假設相同時，需增加樣本才能偵測效果。排除 comorbidity 降低 external validity；納入死亡率更低的 sepsis 無法解決問題；除非藥物機轉專門針對 pneumonia，否則不宜限制此病因。"}, {"id": "02-self-03", "chapter": 2, "type": "self", "number": 3, "stem": "A quality improvement (QI) initiative is implemented to improve antimicrobial dosing for patients with septic shock presenting to the emergency department. As the pharmacy representative, you have worked with the pharmacy operations team to ensure that an appropriate selection of antibacterial agents and doses is available in the automated drugdispensing machines. Which factor will be most important in showing the effectiveness of this QI initiative?", "context": "", "options": [{"key": "A", "text": "Obtaining informed consent for participation in the QI initiative.", "sourceKey": "A"}, {"key": "B", "text": "Identifying patients with septic shock in triage.", "sourceKey": "B"}, {"key": "C", "text": "Creating a community advertising campaign to bring awareness to the initiative.", "sourceKey": "C"}, {"key": "D", "text": "Determining the social value of the QI initiative.", "sourceKey": "D"}], "answer": "B", "explanation": "A QI study would likely show the effectiveness using a pre/postintervention cohort design. In this type of study, informed consent is generally not required because the treatment is provided to all patients as a standard of care (Answer A is incorrect). A community advertising campaign might improve the delivery of care and improve patient adherence, but it is unnecessary to measure the effectiveness of the QI initiative (Answer C is incorrect). The QI initiative is believed necessary and has therefore been deemed to have intrinsic social value (Answer D is incorrect). To show the effectiveness of the intervention, the syndrome must be recognized before initiating treatment (Answer B is correct).", "page": 4, "answerPage": 31, "stemZh": "急診推行 quality improvement（QI）計畫，改善 septic shock 病人的 antimicrobial dosing。你代表藥局與作業團隊合作，確保 automated drug-dispensing machines 備有適當 antibacterial agents 及劑量。哪個因素最重要，才能證明此 QI 計畫有效？", "contextZh": "", "optionsZh": [{"key": "A", "text": "取得參加 QI 計畫的 informed consent。"}, {"key": "B", "text": "在 triage 辨識 septic shock 病人。"}, {"key": "C", "text": "透過社區宣傳提高對計畫的認識。"}, {"key": "D", "text": "確定計畫的 social value。"}], "explanationZh": "需先辨識 syndrome，才可開始治療並評估介入成效。此類 QI 常採介入前後 cohort 設計，標準照護一般不需另取研究 consent；宣傳非衡量效果所必需，且計畫本身已有社會價值。"}, {"id": "02-self-04", "chapter": 2, "type": "self", "number": 4, "stem": "An epidemiologic study seeks to determine the impact of adverse drug events in the intensive care unit (ICU) on patient outcomes, which have an estimated incidence of 52%. Which would be the best approach to conducting this study?", "context": "", "options": [{"key": "A", "text": "Randomized controlled trial with a test for continuous variables to determine the difference in outcomes.", "sourceKey": "A"}, {"key": "B", "text": "Retrospective case-control study with a test for proportions to determine the difference in outcomes.", "sourceKey": "B"}, {"key": "C", "text": "Prospective observational study with survival analysis to determine the difference between cohorts.", "sourceKey": "C"}, {"key": "D", "text": "Retrospective cohort study with a test for proportions to determine the difference in outcomes.", "sourceKey": "D"}], "answer": "C", "explanation": "To effectively determine the incidence and clinical impact of adverse drug events on clinical outcomes in the ICU, it would be unethical to randomize patients to experience the event (Answer A is incorrect). A retrospective design would not be ideal because of the limitations in data extraction, assignment of events, and interpretation of causality (Answers B and D are incorrect). A prospective observational design would allow the investigator team to identify the incidence of adverse events, sequential outcomes, and determine causality (Answer C is correct).", "page": 5, "answerPage": 31, "stemZh": "Epidemiologic study 欲評估 ICU 的 adverse drug events 對病人結果的影響，其估計發生率為 52%。最佳研究方式為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Randomized controlled trial，使用 continuous variables 檢定比較結果。"}, {"key": "B", "text": "Retrospective case-control study，使用 proportions 檢定比較結果。"}, {"key": "C", "text": "Prospective observational study，使用 survival analysis 比較 cohorts。"}, {"key": "D", "text": "Retrospective cohort study，使用 proportions 檢定比較結果。"}], "explanationZh": "不能以倫理上不可接受的方式隨機讓病人發生 adverse drug events。Retrospective 設計受資料擷取、事件分類及因果判讀限制；prospective observational 設計較能辨識事件發生率、後續結果及因果關係。"}, {"id": "02-self-05", "chapter": 2, "type": "self", "number": 5, "stem": "A case-control study is conducted to determine whether proton pump inhibitor (PPI) use is associated with an increased risk of developing Clostridium difficile infection (CDI). The final analysis shows the odds ratio (OR) for CDI with PPI exposure to be 1.3 (95% confidence interval [CI], 0.8–1.5). Which best describes the results?", "context": "", "options": [{"key": "A", "text": "PPI exposure increases the risk of CDI by 130%.", "sourceKey": "A"}, {"key": "B", "text": "PPI exposure reduces the risk of CDI by 20%.", "sourceKey": "B"}, {"key": "C", "text": "PPI exposure increases the risk of CDI by 30%.", "sourceKey": "C"}, {"key": "D", "text": "PPI exposure is not associated with an increased risk of CDI.", "sourceKey": "D"}], "answer": "D", "explanation": "A correct interpretation of the results is recognizing that even though the OR suggests an associated increase of 30% in the risk of being exposed to CDI, the 95% CI crosses 1, meaning that the odds of exposure to CDI are as likely to increase the risk as to decrease that risk (Answer D is correct; Answers A–C are incorrect).", "page": 5, "answerPage": 31, "stemZh": "Case-control study 評估 proton pump inhibitor（PPI）與 Clostridium difficile infection（CDI）風險。PPI exposure 的 CDI odds ratio（OR）為 1.3（95% confidence interval [CI]，0.8–1.5）。如何解讀？", "contextZh": "", "optionsZh": [{"key": "A", "text": "PPI exposure 使 CDI 風險增加 130%。"}, {"key": "B", "text": "PPI exposure 使 CDI 風險降低 20%。"}, {"key": "C", "text": "PPI exposure 使 CDI 風險增加 30%。"}, {"key": "D", "text": "PPI exposure 未顯示與 CDI 風險增加有關。"}], "explanationZh": "OR 點估計暗示增加 30%，但 95% CI 跨越 1，因此未證實風險增加的統計顯著關聯。"}, {"id": "02-self-06", "chapter": 2, "type": "self", "number": 6, "stem": "A systematic review evaluated the effect of albumin for fluid resuscitation. A meta-analysis that evaluated the effect of albumin use compared with normal saline on 28-day mortality reported a combined OR of 0.45 (95% CI, 0.3–0.75) for the treatment of hypovolemic shock caused by trauma. For the treatment of septic shock, albumin compared with normal saline resulted in a combined OR of 1.1 (95% CI, 0.98–1.21) when evaluating 28-day mortality. Which best represents the findings of the review?", "context": "", "options": [{"key": "A", "text": "Albumin increased mortality in trauma but did not affect survival in the treatment of septic shock.", "sourceKey": "A"}, {"key": "B", "text": "Albumin increased survival in trauma but did not affect survival in the treatment of septic shock.", "sourceKey": "B"}, {"key": "C", "text": "Albumin did not affect survival in the treatment of hypovolemic shock caused by trauma but improved survival in the treatment of septic shock.", "sourceKey": "C"}, {"key": "D", "text": "Albumin did not affect survival in the treatment of hypovolemic shock caused by trauma or septic shock.", "sourceKey": "D"}], "answer": "B", "explanation": "Use of albumin reduced the odds of mortality (and conversely, increased the odds of survival) with an OR of 0.45, and the 95% CIs were all less than 1 in treating hypovolemic shock in trauma. In addition, the OR was 1.1 for septic shock, whereas the 95% CI crossed 1, showing that the odds were as likely that albumin increased mortality as that it reduced it (Answer B is correct). Because the OR and the 95% CI for treating hypovolemic shock are both less than 1, mortality was decreased with albumin use (Answers A, C, and D are incorrect).", "page": 5, "answerPage": 31, "stemZh": "Systematic review 評估 albumin resuscitation。Meta-analysis 比較 albumin 與 normal saline 的 28-day mortality：trauma 引起的 hypovolemic shock，合併 OR 0.45（95% CI，0.3–0.75）；septic shock，合併 OR 1.1（95% CI，0.98–1.21）。哪個敘述符合結果？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Albumin 增加 trauma 死亡率，但未影響 septic shock 存活。"}, {"key": "B", "text": "Albumin 增加 trauma 存活，但未影響 septic shock 存活。"}, {"key": "C", "text": "Albumin 未影響 trauma hypovolemic shock 存活，但改善 septic shock 存活。"}, {"key": "D", "text": "Albumin 未影響 trauma hypovolemic shock 或 septic shock 存活。"}], "explanationZh": "Trauma hypovolemic shock 的 OR 及 CI 皆小於 1，表示 albumin 降低死亡 odds、提高存活。Septic shock 的 CI 跨 1，未顯示顯著影響。"}, {"id": "02-self-07", "chapter": 2, "type": "self", "number": 7, "stem": "A critical care pharmacist is faced with an acute drug shortage in which no furosemide is available for immediate use in patient care. During patient care rounds in the ICU, the decision is made to implement a fluid-conservative strategy for a patient with acute respiratory distress syndrome (ARDS) (central venous pressure goal less than 4 mm Hg). The critical care pharmacist procures an allotment of bumetanide. Which statement best describes the course of action for this patient?", "context": "", "options": [{"key": "A", "text": "The pharmacist uses an understanding of the medical literature and experiential knowledge to develop a titration scheme using bumetanide to achieve a central venous pressure of less than 4 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "The pharmacist uses an understanding of research trial design and experiential knowledge to develop a titration scheme using bumetanide to achieve a central venous pressure of less than 4 mm Hg.", "sourceKey": "B"}, {"key": "C", "text": "The pharmacist uses a friendly rapport to convince the nephrologist to treat this patient with hemodialysis to achieve a goal central venous pressure of less than 4 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "The pharmacist uses an understanding of research ethics to obtain informed consent from the patient’s surrogate for treatment with bumetanide.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient case provides a practical example of a critical care pharmacist’s integration of various types of knowledge to optimize patient care. The FACT trial showed that a fluid-conservative strategy improves ventilator-free days for patients with acute lung injury and ARDS. Furosemide was used in the study to show the outcome benefit. However, the study was testing a treatment strategy, not specifically a drug strategy. Therefore, it can be reasoned that similar treatment outcomes can be shown with similar drugs if the study drug is unavailable – in this case, because of drug shortage. Knowledge of trial design is helpful but not critical to optimizing this patient’s therapy with bumetanide (Answer B is incorrect). Hemodialysis is invasive, requires finite resource use, and has an associated morbidity risk (Answer C is incorrect). Because this patient case does not include a broader hypothesis test in a systematic design, this is not a research activity, and informed consent is not required (Answer D is incorrect). A critical care pharmacist, using knowledge of the FACT trial (medical knowledge) together with an understanding and experience with bumetanide therapy (experiential knowledge), can develop a treatment plan (Answer A is correct).", "page": 5, "answerPage": 32, "stemZh": "Furosemide 急性缺貨，ICU 團隊決定對 acute respiratory distress syndrome（ARDS）病人採 fluid-conservative strategy，central venous pressure 目標低於 4 mm Hg。藥師取得 bumetanide。最佳處置描述為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "結合 medical literature 與經驗知識，制定 bumetanide titration 方案，達 central venous pressure <4 mm Hg。"}, {"key": "B", "text": "結合 research trial design 與經驗知識，制定 bumetanide titration 方案，達 central venous pressure <4 mm Hg。"}, {"key": "C", "text": "藉良好關係說服 nephrologist 使用 hemodialysis，達 central venous pressure <4 mm Hg。"}, {"key": "D", "text": "依 research ethics，向病人代理人取得 bumetanide 治療的 informed consent。"}], "explanationZh": "FACT trial 支持 fluid-conservative 策略改善 acute lung injury／ARDS 的 ventilator-free days，研究重點是策略而非特定藥物。可結合此文獻與 bumetanide 使用經驗制定方案。Trial design 知識非本例關鍵；hemodialysis 有侵入性與風險；此為個別照護，並非系統性研究。"}, {"id": "02-self-08", "chapter": 2, "type": "self", "number": 8, "stem": "In a study of ARDS, patients are treated with a neuromuscular blocking agent (NMBA) or placebo to determine whether administering a NMBA within the first 48 hours of presentation improves 28- and 90-day survival. The study enrolled an unequal distribution of patients, with more patients having severe ARDS than moderate and mild ARDS. The post hoc analysis of the results showed a survival benefit with NMBA administration for the patients with severe ARDS. Which rationale best describes why NMBAs should not be administered to patients with mild to moderate ARDS?", "context": "", "options": [{"key": "A", "text": "Patients with mild ARDS have a lower mortality rate and are therefore less likely to benefit from the test treatment.", "sourceKey": "A"}, {"key": "B", "text": "Patients with mild and moderate ARDS are inherently different from patients with severe ARDS because of their etiology and presentation.", "sourceKey": "B"}, {"key": "C", "text": "NMBAs are periodically on shortage from the manufacturer and need to be prioritized for necessary medical indications.", "sourceKey": "C"}, {"key": "D", "text": "The end points selected do not carry sufficient social value to warrant treatment.", "sourceKey": "D"}], "answer": "A", "explanation": "Acute respiratory distress syndrome is a clinical syndrome with an associated mortality with each progressing phase (mild, moderate, and severe). Although ARDS is also a constellation of findings and pathologic observations, patients with this disease present with a similar finding of severe, refractory hypoxia from a common etiology (Answer B is incorrect). Given the associated mortality of about 45% for severe ARDS, a finite resource should be prioritized for it (in this case, a NMBA) (Answer C is incorrect). Mortality/survival is readily identified as an end point of social value for research design (Answer D is incorrect). Given the relatively low mortality associated with mild ARDS (around 20%) compared with severe ARDS (around 45%), and mortality benefit was seen only in the subgroup of patients with severe ARDS, administering NMBAs would less likely improve survival and more likely increase harm if systematically administered to patients with mild ARDS (Answer A is correct).", "page": 6, "answerPage": 32, "stemZh": "ARDS 研究比較發病前 48 hours 給予 neuromuscular blocking agent（NMBA）或 placebo 是否改善 28-及 90-day survival。納入 severe ARDS 多於 mild／moderate ARDS，post hoc analysis 顯示 severe ARDS 有存活益處。何者最能解釋為何不應對 mild 至 moderate ARDS 給予 NMBA？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Mild ARDS 死亡率較低，較不容易從測試治療獲益。"}, {"key": "B", "text": "Mild／moderate ARDS 的病因與表現，使其本質上不同於 severe ARDS。"}, {"key": "C", "text": "NMBA 偶有廠商缺貨，需優先供必要適應症使用。"}, {"key": "D", "text": "選定 end points 的社會價值不足以支持治療。"}], "explanationZh": "Mild ARDS 死亡率約 20%，severe ARDS 約 45%；存活益處僅見於 severe subgroup。普遍給 mild ARDS NMBA 較不可能改善存活，反可能增加傷害。ARDS 各嚴重度具有共同 syndrome 特徵；缺貨並非此結果的解釋，存活亦具社會價值。"}, {"id": "02-case-01", "chapter": 2, "type": "case", "number": 1, "stem": "You are working with a multicenter group to develop a cluster-crossover randomized trial. Patients will be recruited at 12 large academic medical centers in eight metropolitan cities. The study will involve a comparison of intravenous haloperidol with intravenous droperidol for acute agitation in the emergency department. Which of the following would NOT qualify as an essential practical consideration for this proposed study design?", "context": "", "options": [{"key": "A", "text": "Informed consent - unclear whether waiver of informed consent would be appropriate because both agents may be considered current standard of care or whether community consent might be more appropriate.", "sourceKey": "A"}, {"key": "B", "text": "Social determinants of health - are some patients more likely to be enrolled in study depending on local perceptions of etiologies of agitation (e.g., drug use, psychological disorders)", "sourceKey": "B"}, {"key": "C", "text": "Subject recruitment - important to ensure that homogeneous populations are enrolled despite institutional and geographic differences that could significantly affect results.", "sourceKey": "C"}, {"key": "D", "text": "Blinding - unnecessary bias is introduced into the study due to the inability to blind patients and providers to drug selection.", "sourceKey": "D"}], "answer": "D", "explanation": "This study requires consideration of options A, B, and C. Informed consent may be waived because both drugs may be considered standard of care, but some IRBs at various institutions may require the use of community consent measures; obtaining informed consent directly from the patient or a family member may be impossible due to the acute nature of the intervention. Differences in local perceptions on why patients may be agitated on presentation to the emergency department could lead to heterogeneity in use of the study agents, affecting results downstream. In addition, a multicenter trial creates a risk of differences in patient characteristics during enrollment that may need to be controlled for in the study. Option D is not a valid practical consideration based on the study design. The cluster crossover trial may compare two known standards of care, and the crossover design allows for hospitals/units to serve as their own controls. Risk of bias is never zero, but blinding would not introduce unnecessary bias into this trial’s results (Answer D is correct; Answers A, B, and C are incorrect).", "page": 12, "answerPage": 29, "stemZh": "你與多中心團隊設計 cluster-crossover randomized trial，在八個大城市的 12 家大型學術醫療中心招募病人，比較急診 acute agitation 的 IV haloperidol 與 IV droperidol。哪一項不屬於此設計的必要實務考量？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Informed consent：兩者可能均為 standard of care，是否適合 waiver 或 community consent 尚不清楚。"}, {"key": "B", "text": "Social determinants of health：地方對 agitation 病因（如 drug use、psychological disorders）的看法，可能影響納入病人。"}, {"key": "C", "text": "Subject recruitment：雖有院際與地理差異，仍需確保納入族群同質，避免影響結果。"}, {"key": "D", "text": "Blinding：無法讓病人與照護者不知道用藥選擇，因而引入不必要的 bias。"}], "explanationZh": "需考量 consent、地方觀點與多中心病人差異。Cluster crossover 可比較兩種 standard of care，醫院／單位能作為自身對照；D 所描述的 blinding 問題並非此設計中有效的必要實務考量。"}, {"id": "02-case-02", "chapter": 2, "type": "case", "number": 2, "stem": "Which is likely the most appropriate trial design for this study?", "context": "You are a critical care pharmacist in the medical ICU and wish to retrospectively study the safety and efficacy of four-factor prothrombin complex concentrate (4F-PCC) for coagulopathy correction in patients with end-stage liver disease. You decide on a primary outcome of in-hospital mortality and secondary outcomes of INR correction, viscoelastic test correction, and thrombotic events.", "options": [{"key": "A", "text": "Case-control.", "sourceKey": "A"}, {"key": "B", "text": "Cohort.", "sourceKey": "B"}, {"key": "C", "text": "Case series.", "sourceKey": "C"}, {"key": "D", "text": "Pharmacokinetic trial.", "sourceKey": "D"}], "answer": "B", "explanation": "The study goal is to determine whether exposure to 4F-PCC resulted in mortality, or the outcome of interest. This is performed in a cohort of patients who all have end-stage liver disease (Answer B is correct). A casecontrol study involves structuring study groups by those who did and did not have an outcome of interest in order to determine relevant risk factors leading to that outcome (Answer A is incorrect). A case study would be better suited to a single group without a comparator and is typically used to describe a novel intervention or outcome (Answer C is incorrect). Pharmacokinetic trials typically involve sample collection and evaluation of drug concentrations to describe the kinetics of the drug as opposed to clinical outcomes (Answer D is incorrect).", "page": 17, "answerPage": 29, "stemZh": "此研究最適合哪種 trial design？", "contextZh": "你在 medical ICU 欲回溯研究 four-factor prothrombin complex concentrate（4F-PCC）矯正 end-stage liver disease 病人 coagulopathy 的安全性及療效。Primary outcome 為 in-hospital mortality；secondary outcomes 為 INR correction、viscoelastic test correction 與 thrombotic events。", "optionsZh": [{"key": "A", "text": "Case-control。"}, {"key": "B", "text": "Cohort。"}, {"key": "C", "text": "Case series。"}, {"key": "D", "text": "Pharmacokinetic trial。"}], "explanationZh": "在 end-stage liver disease cohort 中，按是否接受 4F-PCC exposure 比較死亡等結果，適合 cohort 設計。Case-control 是按結果分組後探討危險因子；case series 缺乏對照；pharmacokinetic trial 主要研究 drug concentrations 與 kinetics。"}, {"id": "02-case-03", "chapter": 2, "type": "case", "number": 3, "stem": "Which would create the highest risk of bias in this study?", "context": "You are a critical care pharmacist in the medical ICU and wish to retrospectively study the safety and efficacy of four-factor prothrombin complex concentrate (4F-PCC) for coagulopathy correction in patients with end-stage liver disease. You decide on a primary outcome of in-hospital mortality and secondary outcomes of INR correction, viscoelastic test correction, and thrombotic events.", "options": [{"key": "A", "text": "Selection bias – typically only patients who are bleeding receive 4F-PCC at your institution.", "sourceKey": "A"}, {"key": "B", "text": "Measurement bias – multiple students and a pharmacy resident collected data for this study.", "sourceKey": "B"}, {"key": "C", "text": "Misclassification bias Î classification of patients as having end-stage liver disease requires manual chart review.", "sourceKey": "C"}, {"key": "D", "text": "Observation bias – there was no blinding of those who did or did not receive 4F-PCC.", "sourceKey": "D"}], "answer": "A", "explanation": "If patients who are bleeding more often receive 4F-PCC according to institutional standards or physician preference, there is likely a difference in the severity of illness between the two study groups (those who did and did not receive 4F-PCC), which could lead to selection bias in the result of mortality (Answer A is correct). Although measurement bias is possible because of multiple people collecting data, it is less likely to have as large an impact on the outcomes as long as a data collection plan is implemented and followed (Answer B is incorrect). Misclassification bias is also possible but is less likely to affect outcomes at the same magnitude as selection bias as long as a consistent data collection and chart review plan is followed (Answer C is incorrect). Observation bias would likely be more important in a prospective trial than in a retrospective trial to blind those involved to ensure all other standards of care are followed (Answer D is incorrect).", "page": 17, "answerPage": 29, "stemZh": "此研究哪種 bias 風險最高？", "contextZh": "你在 medical ICU 欲回溯研究 four-factor prothrombin complex concentrate（4F-PCC）矯正 end-stage liver disease 病人 coagulopathy 的安全性及療效。Primary outcome 為 in-hospital mortality；secondary outcomes 為 INR correction、viscoelastic test correction 與 thrombotic events。", "optionsZh": [{"key": "A", "text": "Selection bias：院內通常只對出血病人給 4F-PCC。"}, {"key": "B", "text": "Measurement bias：由多位學生及一位 pharmacy resident 收集資料。"}, {"key": "C", "text": "Misclassification bias：end-stage liver disease 分類需人工 chart review。"}, {"key": "D", "text": "Observation bias：未對是否接受 4F-PCC 做 blinding。"}], "explanationZh": "若出血病人較常接受 4F-PCC，兩組疾病嚴重度可能不同，造成死亡結果的 selection bias。依一致計畫收集資料可降低 measurement／misclassification bias；observation bias 對 prospective trial 通常較重要。"}, {"id": "02-case-04", "chapter": 2, "type": "case", "number": 4, "stem": "Which statistical test would be most appropriate to evaluate any difference in creatinine clearance (milliliters per minute) between patients with positive and negative procalcitonin?", "context": "The neurosurgery physician group at your institution would like your input in evaluating the usefulness of procalcitonin for distinguishing neurogenic fevers from true infectious etiologies of fever. An additional goal of the study would be to evaluate risk factors and possible confounders for positive and negative procalcitonin values. You decide on a predictive cutoff of 0.5 ng/mL (positive 0.5 mg/mL or greater; negative less than 0.5 ng/mL).", "options": [{"key": "A", "text": "Chi-square.", "sourceKey": "A"}, {"key": "B", "text": "Wilcoxon signed rank.", "sourceKey": "B"}, {"key": "C", "text": "Student t-test for parametric data.", "sourceKey": "C"}, {"key": "D", "text": "Mann Whitney U for parametric data.", "sourceKey": "D"}], "answer": "C", "explanation": "Student t-test is appropriate to compare two independent means as a measure of parametric or normally distributed data (Answer C is correct). A chi-square analysis is used for categorical data (Answer A is incorrect). Wilcoxon signed rank is used to compare two related medians as a measure of nonparametric data (Answer B is incorrect). Mann-Whitney U is used to compare two independent medians as a measure of nonparametric data (Answer D is incorrect).", "page": 22, "answerPage": 29, "stemZh": "要比較 procalcitonin 陽性與陰性病人的 creatinine clearance（milliliters per minute）差異，哪種 statistical test 最適合？", "contextZh": "Neurosurgery 團隊欲評估 procalcitonin 區分 neurogenic fever 與真正感染性發燒的效用，同時評估陽性及陰性結果的 risk factors 與 confounders。你選擇 predictive cutoff 0.5 ng/mL（原文陽性定義為 0.5 mg/mL 或以上；陰性為低於 0.5 ng/mL）。", "optionsZh": [{"key": "A", "text": "Chi-square。"}, {"key": "B", "text": "Wilcoxon signed rank。"}, {"key": "C", "text": "Student t-test，用於 parametric data。"}, {"key": "D", "text": "Mann Whitney U，用於 parametric data。"}], "explanationZh": "Student t-test 比較兩組獨立、常態分布的平均值。Chi-square 用於 categorical data；Wilcoxon signed rank 比較相關組的 nonparametric medians；Mann-Whitney U 用於獨立組的 nonparametric medians，而非 parametric data。"}, {"id": "02-case-05", "chapter": 2, "type": "case", "number": 5, "stem": "Which statistical test would be most appropriate to determine an independent association between positive procalcitonin and true infection in the presence of possible confounders?", "context": "The neurosurgery physician group at your institution would like your input in evaluating the usefulness of procalcitonin for distinguishing neurogenic fevers from true infectious etiologies of fever. An additional goal of the study would be to evaluate risk factors and possible confounders for positive and negative procalcitonin values. You decide on a predictive cutoff of 0.5 ng/mL (positive 0.5 mg/mL or greater; negative less than 0.5 ng/mL).", "options": [{"key": "A", "text": "Linear regression.", "sourceKey": "A"}, {"key": "B", "text": "Logistic regression.", "sourceKey": "B"}, {"key": "C", "text": "Cox proportional hazards model.", "sourceKey": "C"}, {"key": "D", "text": "Correlation analysis.", "sourceKey": "D"}], "answer": "B", "explanation": "A regression analysis can be used to identify independent associations in the presence of other risk factors for the outcome. Logistic regression is used when the outcome of interest (i.e., patients with positive or negative procalcitonin) is categorical in nature (Answer B is correct). Linear regressions are used similarly to logistic regressions for a continuous dependent variable (Answer A is incorrect). A Cox proportional hazards model is used as a survival analysis or time-to-event analysis, which would not be applicable to the outcome or question in this case (Answer C is incorrect). Although a correlation could determine the strength of association between positive procalcitonin and infection, it would not consider other risk factors that could be confounding the results (Answer D is incorrect).", "page": 23, "answerPage": 29, "stemZh": "存在可能的 confounders 時，哪種 statistical test 最適合判定 procalcitonin 陽性與真正感染的獨立關聯？", "contextZh": "Neurosurgery 團隊欲評估 procalcitonin 區分 neurogenic fever 與真正感染性發燒的效用，同時評估陽性及陰性結果的 risk factors 與 confounders。你選擇 predictive cutoff 0.5 ng/mL（原文陽性定義為 0.5 mg/mL 或以上；陰性為低於 0.5 ng/mL）。", "optionsZh": [{"key": "A", "text": "Linear regression。"}, {"key": "B", "text": "Logistic regression。"}, {"key": "C", "text": "Cox proportional hazards model。"}, {"key": "D", "text": "Correlation analysis。"}], "explanationZh": "Logistic regression 可在 categorical outcome 下控制其他 risk factors，評估獨立關聯。Linear regression 用於 continuous dependent variable；Cox model 用於 survival／time-to-event；correlation 不控制 confounders。"}, {"id": "02-case-06", "chapter": 2, "type": "case", "number": 6, "stem": "You enroll 201 patients who have a true infection and 200 patients who are not infected. Of the 201 with infection, 189 have a positive procalcitonin and 12 have a negative procalcitonin. Of the 200 patients without infection, 100 have a positive procalcitonin and 100 have a negative procalcitonin. Which best describes the sensitivity and specificity of procalcitonin in this population?", "context": "The neurosurgery physician group at your institution would like your input in evaluating the usefulness of procalcitonin for distinguishing neurogenic fevers from true infectious etiologies of fever. An additional goal of the study would be to evaluate risk factors and possible confounders for positive and negative procalcitonin values. You decide on a predictive cutoff of 0.5 ng/mL (positive 0.5 mg/mL or greater; negative less than 0.5 ng/mL).", "options": [{"key": "A", "text": "94% sensitivity and 89% specificity.", "sourceKey": "A"}, {"key": "B", "text": "65% sensitivity and 89% specificity.", "sourceKey": "B"}, {"key": "C", "text": "65% sensitivity and 50% specificity.", "sourceKey": "C"}, {"key": "D", "text": "94% sensitivity and 50% specificity.", "sourceKey": "D"}], "answer": "D", "explanation": "The sensitivity is around 94%, and the specificity is 50% (Answer D is correct). The sensitivity is calculated by dividing 189/201, and the specificity is calculated by dividing 100/200. The PPV is around 65%, and the NPV is around 89% (Answers A, B, and C are incorrect). The PPV is calculated by dividing 189/289, and the NPV is calculated by dividing 100/112.", "page": 23, "answerPage": 29, "stemZh": "納入 201 位真正感染與 200 位未感染病人。感染者中 189 位 procalcitonin 陽性、12 位陰性；未感染者中 100 位陽性、100 位陰性。此族群的 sensitivity 與 specificity 為何？", "contextZh": "Neurosurgery 團隊欲評估 procalcitonin 區分 neurogenic fever 與真正感染性發燒的效用，同時評估陽性及陰性結果的 risk factors 與 confounders。你選擇 predictive cutoff 0.5 ng/mL（原文陽性定義為 0.5 mg/mL 或以上；陰性為低於 0.5 ng/mL）。", "optionsZh": [{"key": "A", "text": "94% sensitivity，89% specificity。"}, {"key": "B", "text": "65% sensitivity，89% specificity。"}, {"key": "C", "text": "65% sensitivity，50% specificity。"}, {"key": "D", "text": "94% sensitivity，50% specificity。"}], "explanationZh": "Sensitivity = 189/201，約 94%；specificity = 100/200 = 50%。PPV = 189/289，約 65%；NPV = 100/112，約 89%。"}, {"id": "02-case-07", "chapter": 2, "type": "case", "number": 7, "stem": "Which is your biggest concern with interpreting the validity of this study?", "context": "You are reading a study that evaluated the use of hydrocortisone versus placebo for lowering C-reactive protein (CRP) in patients with ARDS at 3 days after enrollment. The authors concluded that they would need to enroll 100 patients to achieve 90% power to find a decrease in CRP of 10 mg/L, assuming a baseline concentration of 35 mg/L and an ƽ level of 0.05. They enroll 50 patients in the hydrocortisone group and 51 patients in the placebo group. The median [interquartile range] CRP concentrations in the intervention and placebo groups are 23 [19–31] and 29 [20–40], respectively (p<0.05). The percentages of patients achieving a CRP decrease of at least 10 mg/L in the intervention and placebo groups are 15% and 18%, respectively (p>0.05).", "options": [{"key": "A", "text": "The study did not meet statistical power.", "sourceKey": "A"}, {"key": "B", "text": "The sample size is too small to provide a representative population for the disease state.", "sourceKey": "B"}, {"key": "C", "text": "The outcome of lowering CRP should not be dichotomized, but only analyzed as a continuous variable.", "sourceKey": "C"}, {"key": "D", "text": "The outcome of CRP is a surrogate and likely not a good representation of the clinical implications of steroid use in ARDS.", "sourceKey": "D"}], "answer": "D", "explanation": "When evaluating this study, it is important to consider that the outcome related to a biomarker is simply a surrogate as opposed to a true clinical outcome. This could be problematic or lack validity because other steroids have previously been studied for outcomes such as mechanical ventilator days and mortality (Answer D is correct). The study may not have met the criteria for the original power analysis that was defined by the authors, but it did achieve power to find a statistically significant difference according to the outcome (Answer A is incorrect). Although the sample size is small, it may represent a reasonable population with internal validity to use the information in a limited way, particularly at the institution(s) where it was performed (Answer B is incorrect). The power analysis was created around a continuous outcome, but it is reasonable to present the data in two different ways (in this case, patients who did and did not achieve a CRP decrease of at least 10 mg/L) as long as the reader understands that the study was not powered around this analysis (Answer C is incorrect).", "page": 25, "answerPage": 30, "stemZh": "解讀此研究 validity 時，最大的疑慮為何？", "contextZh": "研究比較 hydrocortisone 與 placebo 對 ARDS 病人納入後 3 days 的 C-reactive protein（CRP）下降。假設基線 35 mg/L、α = 0.05，需 100 人達 90% power 以偵測下降 10 mg/L。Hydrocortisone 組 50 人、placebo 組 51 人；CRP median [interquartile range] 分別為 23 [19–31] 與 29 [20–40]（p<0.05）；下降至少 10 mg/L 的比例為 15% 與 18%（p>0.05）。", "optionsZh": [{"key": "A", "text": "研究未達 statistical power。"}, {"key": "B", "text": "Sample size 太小，無法代表此疾病族群。"}, {"key": "C", "text": "CRP 下降不應 dichotomize，只能作 continuous variable 分析。"}, {"key": "D", "text": "CRP 是 surrogate outcome，可能無法充分反映 ARDS 使用 steroid 的臨床意義。"}], "explanationZh": "Biomarker 只是 surrogate，非真正 clinical outcome；其他 steroid 研究曾評估 mechanical ventilator days 與死亡率，因此此 outcome 的 clinical validity 是核心疑慮。研究已偵測到 CRP 的統計差異；小樣本仍可能有有限 internal validity；可同時呈現 continuous 與 dichotomized 結果，但需理解 power 分析並非針對後者。"}, {"id": "02-case-08", "chapter": 2, "type": "case", "number": 8, "stem": "Which best describes the NNT for achieving a CRP decrease of at least 10 mg/L in this study?", "context": "You are reading a study that evaluated the use of hydrocortisone versus placebo for lowering C-reactive protein (CRP) in patients with ARDS at 3 days after enrollment. The authors concluded that they would need to enroll 100 patients to achieve 90% power to find a decrease in CRP of 10 mg/L, assuming a baseline concentration of 35 mg/L and an ƽ level of 0.05. They enroll 50 patients in the hydrocortisone group and 51 patients in the placebo group. The median [interquartile range] CRP concentrations in the intervention and placebo groups are 23 [19–31] and 29 [20–40], respectively (p<0.05). The percentages of patients achieving a CRP decrease of at least 10 mg/L in the intervention and placebo groups are 15% and 18%, respectively (p>0.05).", "options": [{"key": "A", "text": "34.", "sourceKey": "A"}, {"key": "B", "text": "17.", "sourceKey": "B"}, {"key": "C", "text": "50.", "sourceKey": "C"}, {"key": "D", "text": "6.", "sourceKey": "D"}], "answer": "A", "explanation": "The NNT is calculated by 1/ARR. The absolute risk reduction is 3%, or 0.03. The NNT is 1/0.03 = 34 (rounding up to the nearest whole number) (Answer A is correct; Answers B, C, and D are incorrect).", "page": 25, "answerPage": 30, "stemZh": "此研究達成 CRP 下降至少 10 mg/L 的 NNT 為何？", "contextZh": "研究比較 hydrocortisone 與 placebo 對 ARDS 病人納入後 3 days 的 C-reactive protein（CRP）下降。假設基線 35 mg/L、α = 0.05，需 100 人達 90% power 以偵測下降 10 mg/L。Hydrocortisone 組 50 人、placebo 組 51 人；CRP median [interquartile range] 分別為 23 [19–31] 與 29 [20–40]（p<0.05）；下降至少 10 mg/L 的比例為 15% 與 18%（p>0.05）。", "optionsZh": [{"key": "A", "text": "34。"}, {"key": "B", "text": "17。"}, {"key": "C", "text": "50。"}, {"key": "D", "text": "6。"}], "explanationZh": "依原文答案：ARR = 3% = 0.03，NNT = 1/ARR = 1/0.03，向上取整為 34。"}, {"id": "03-self-01", "chapter": 3, "type": "self", "number": 1, "stem": "Which is the most appropriate indication for parenteral nutrition (PN)?", "context": "", "options": [{"key": "A", "text": "Severe anorexia.", "sourceKey": "A"}, {"key": "B", "text": "Lack of bowel sounds.", "sourceKey": "B"}, {"key": "C", "text": "Ileus.", "sourceKey": "C"}, {"key": "D", "text": "Gastric residual volume (GRV) of 300 mL.", "sourceKey": "D"}], "answer": "C", "explanation": "An ileus, usually detected on radiologic examination of the lower abdomen, indicates lack of motility and presence of distention and air within the small bowel. This is usually depicted as “dilated loops of bowel.” Patients cannot be fed safely or efficaciously by the enteral route during an ileus (Answer C is correct). Answer A is incorrect because a feeding tube can be placed for enteral feeding of the patient with anorexia, and PN is not indicated. Answer B is incorrect because presence or absence of bowel sounds is not an accurate marker for assessing bowel function. Answer D is incorrect because a high gastric residual volume during enteral feeding, combined with abdominal distension, bloating, emesis, or regurgitation, can often be efficaciously treated with prokinetic pharmacotherapy or advancement of the feeding tube into the small bowel with resumption of enteral feeding. In addition, the guidelines recommend against discontinuing EN for a GRV less than 500 mL in the absence of other signs of intolerance.", "page": 4, "answerPage": 60, "stemZh": "哪個情況最適合使用 parenteral nutrition（PN）？", "contextZh": "", "optionsZh": [{"key": "A", "text": "嚴重 anorexia。"}, {"key": "B", "text": "無 bowel sounds。"}, {"key": "C", "text": "Ileus。"}, {"key": "D", "text": "Gastric residual volume（GRV）300 mL。"}], "explanationZh": "Ileus 表示小腸缺乏 motility、擴張且含氣，無法安全有效地進行 enteral feeding。Anorexia 可用 feeding tube；bowel sounds 不足以判斷腸功能；無其他不耐受症狀時，GRV <500 mL 不應停 EN，可考慮 prokinetic 或 postpyloric feeding。"}, {"id": "03-self-02", "chapter": 3, "type": "self", "number": 2, "stem": "Which fluid option would most closely match the composition of nasogastric (NG) fluid losses?", "context": "", "options": [{"key": "A", "text": "0.9% sodium chloride and potassium chloride 20 mEq/L.", "sourceKey": "A"}, {"key": "B", "text": "0.45% sodium chloride and potassium chloride 20 mEq/L.", "sourceKey": "B"}, {"key": "C", "text": "5% dextrose in 0.225% sodium chloride and potassium chloride 20 mEq/L.", "sourceKey": "C"}, {"key": "D", "text": "Lactated Ringer solution.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B, 0.45% sodium chloride and potassium chloride 20 mEq/L, is correct given the average electrolyte composition of gastric fluid (see Table 4 regarding the electrolyte composition of GI fluids). Answers A, C, and D are incorrect because they do not as accurately replace the electrolyte content that is lost from gastric fluid output.", "page": 4, "answerPage": 60, "stemZh": "哪種輸液最接近 nasogastric（NG）fluid losses 的組成？", "contextZh": "", "optionsZh": [{"key": "A", "text": "0.9% sodium chloride 加 potassium chloride 20 mEq/L。"}, {"key": "B", "text": "0.45% sodium chloride 加 potassium chloride 20 mEq/L。"}, {"key": "C", "text": "5% dextrose in 0.225% sodium chloride 加 potassium chloride 20 mEq/L。"}, {"key": "D", "text": "Lactated Ringer solution。"}], "explanationZh": "依 gastric fluid 的平均 electrolyte 組成，0.45% sodium chloride 加 potassium chloride 20 mEq/L 最接近流失內容；其他方案的電解質比例較不吻合。"}, {"id": "03-self-03", "chapter": 3, "type": "self", "number": 3, "stem": "A patient with prolonged, intractable diarrhea would most likely have excess losses of which trace mineral?", "context": "", "options": [{"key": "A", "text": "Zinc.", "sourceKey": "A"}, {"key": "B", "text": "Copper.", "sourceKey": "B"}, {"key": "C", "text": "Iodine.", "sourceKey": "C"}, {"key": "D", "text": "Manganese.", "sourceKey": "D"}], "answer": "A", "explanation": "With significant diarrhea, intravenous zinc requirements from GI fluid losses during critical illness increase from the normal requirements of 3–5 mg/day. Data analyses show that most patients with increased intestinal losses can achieve a positive zinc balance on 13 mg of intravenous zinc daily (Gastroenterology 1979;76:458-67). As a result, most clinicians provide additional zinc supplementation for patients with short bowel syndrome, intestinal fistulas, or prolonged and sustained diarrhea (Answer A is correct). Answer B is incorrect because copper is an extremely rare and unlikely deficiency to occur during parenteral nutrition therapy. Answers C and D are incorrect because intractable diarrhea losses are less likely to cause a deficiency, albeit with the exception of copper (especially with extreme intestinal bypass procedures for obesity).", "page": 4, "answerPage": 60, "stemZh": "長期難以控制的 diarrhea 最可能使哪種 trace mineral 過度流失？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Zinc。"}, {"key": "B", "text": "Copper。"}, {"key": "C", "text": "Iodine。"}, {"key": "D", "text": "Manganese。"}], "explanationZh": "大量 GI losses 會使 zinc 需求超過一般 3–5 mg/day。資料顯示 intestinal losses 增加者，每日 IV zinc 13 mg 多可達正平衡，因此 short bowel syndrome、fistula 或持續 diarrhea 常需額外補充。其他選項較不符合此情境。"}, {"id": "03-self-04", "chapter": 3, "type": "self", "number": 4, "stem": "A 70-year-old man admitted to the intensive care unit (ICU) for sepsis was recently given a diagnosis of syndrome of inappropriate antidiuretic hormone secretion. His serum sodium fell from 130 mEq/L to 115 mEq/L during the past 3 days, and his course was subsequently complicated by a seizure. Which would be the most appropriate treatment option?", "context": "", "options": [{"key": "A", "text": "Intravenous 0.9% sodium chloride.", "sourceKey": "A"}, {"key": "B", "text": "Intravenous desmopressin acetate (DDAVP).", "sourceKey": "B"}, {"key": "C", "text": "Intravenous 3% sodium chloride.", "sourceKey": "C"}, {"key": "D", "text": "Intravenous conivaptan.", "sourceKey": "D"}], "answer": "C", "explanation": "Given the severity of the patient’s condition (recent seizure from severe hyponatremia) and likely diagnosis of SIADH, the immediate goal should be to achieve a serum sodium concentration of greater than 120 mEq/L by short-term infusion of 3% sodium chloride (Answer C is correct). Conivaptan (Answer D) could then be given to correct the hyponatremia, limiting the increase in serum sodium concentration to less than 10–12 mEq/L/day. Fluid restriction is imperative and is the primary overall management technique for this patient. Answer A is incorrect because a more rapid response is imperative because of the patient’s seizure and severity of the condition. Answer B is incorrect because it would be a potentially life-threatening error by providing more ADH-like substance and because it is used to treat diabetes insipidus (the opposite condition of SIADH).", "page": 5, "answerPage": 60, "stemZh": "70 歲男性因 sepsis 入 ICU，近期診斷 syndrome of inappropriate antidiuretic hormone secretion。3 days 內 serum sodium 從 130 降至 115 mEq/L，並發生 seizure。最適合的治療為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "IV 0.9% sodium chloride。"}, {"key": "B", "text": "IV desmopressin acetate（DDAVP）。"}, {"key": "C", "text": "IV 3% sodium chloride。"}, {"key": "D", "text": "IV conivaptan。"}], "explanationZh": "嚴重 symptomatic hyponatremia 合併 seizure，應短期輸注 3% sodium chloride，立即目標 serum sodium >120 mEq/L。原章節後續可考慮 conivaptan，限制上升 <10–12 mEq/L/day，並以 fluid restriction 為主要整體處置。0.9% sodium chloride 反應不夠快；DDAVP 增加 ADH-like 作用，題述情況不適合。"}, {"id": "03-self-05", "chapter": 3, "type": "self", "number": 5, "stem": "Other than the absorption/infusion rate, which best explains why enteral potassium administration is safer than parenteral potassium administration?", "context": "", "options": [{"key": "A", "text": "Bioavailability of potassium is significantly lower with enteral versus parenteral administration.", "sourceKey": "A"}, {"key": "B", "text": "Feed-forward sensing of changes in mesenteric potassium concentration increases urinary potassium excretion.", "sourceKey": "B"}, {"key": "C", "text": "Potassium chloride elixir is likely to cause diarrhea and reduce potassium absorption.", "sourceKey": "C"}, {"key": "D", "text": "Wax matrix tablets sequester potassium release throughout the gastrointestinal (GI) tract.", "sourceKey": "D"}], "answer": "B", "explanation": "Studies show that increases in mesenteric potassium concentrations detected by potassium sensors in the splanchnic vascular bed evoke increased renal potassium excretion (feed-forward regulation of potassium homeostasis), even before regulation by aldosterone (classic feedback regulation) (Answer B is correct). The bioavailability of enteral potassium is 95%–100% in the absence of aberrations in GI motility, function, or anatomy. A primary difference between enteral and parenteral potassium is that the rate of absorption is slower with enteral potassium (Answer A is incorrect). Intravenous potassium administration can inadvertently be infused too quickly (it is acceptable to infuse potassium at 10 mEq/hour for patients without a cardiac monitor and up to 20 mEq/hour for those with a monitor). Answer C is incorrect because potassium chloride elixir or solution is an effective means for providing potassium when given intra-gastrically. It generally only causes diarrhea when given in higher doses or when administered directly into the small bowel through a feeding jejunostomy because it is a hypertonic solution. Answer D is a nonsensible answer.", "page": 5, "answerPage": 60, "stemZh": "除了 absorption／infusion rate，為何 enteral potassium 比 parenteral potassium 更安全？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Enteral potassium 的 bioavailability 顯著較低。"}, {"key": "B", "text": "Mesenteric potassium 變化的 feed-forward sensing 會增加 urinary potassium excretion。"}, {"key": "C", "text": "Potassium chloride elixir 易造成 diarrhea，降低 potassium absorption。"}, {"key": "D", "text": "Wax matrix tablets 在整個 GI tract 中封存 potassium 釋放。"}], "explanationZh": "Splanchnic vascular bed 的 potassium sensors 感知 mesenteric potassium 上升，在 aldosterone feedback 前即可增加 renal potassium excretion。正常 GI 功能下 enteral bioavailability 為 95%–100%；elixir 是有效補充方式，高劑量或直接小腸給藥才較易 diarrhea。"}, {"id": "03-self-06", "chapter": 3, "type": "self", "number": 6, "stem": "A 40-year-old man (weight 60 kg) is admitted to the trauma ICU after a motor vehicle collision. He is noted to have a serum magnesium concentration of 1.2 mg/dL, and his family states that he has a history of alcohol abuse (12–18 beers/day). He is given magnesium sulfate 6 g intravenously for 6 hours by the primary service. His repeat serum magnesium concentration on the following day is 1.8 mg/dL. Which would be the most appropriate treatment for this patient?", "context": "", "options": [{"key": "A", "text": "No treatment is necessary because his serum magnesium concentration is normal.", "sourceKey": "A"}, {"key": "B", "text": "If a repeat serum magnesium concentration is 2 mg/dL or greater, no additional magnesium therapy is indicated.", "sourceKey": "B"}, {"key": "C", "text": "Supplemental calcium therapy should be given concurrently with the magnesium therapy.", "sourceKey": "C"}, {"key": "D", "text": "Additional magnesium therapy should be given daily for the next 4–5 days.", "sourceKey": "D"}], "answer": "D", "explanation": "Answer D, additional magnesium therapy should be given daily for the next 4–5 days, is correct because it takes 48 hours for magnesium to equilibrate after a shortterm infusion, making Answer A incorrect. Although Answer B is common in clinical practice, failure to provide additional magnesium repletion in the setting of a normal serum magnesium concentration the day after a large intravenous dosage usually causes serum concentrations to decrease below the normal range again over the next 1–2 days as magnesium equilibrates. Thus, Answer B is not ideal management and is incorrect. Answer C is incorrect because hypocalcemia should autocorrect with magnesium supplementation within 48 hours of magnesium therapy; however, calcium therapy can be given concurrently, if necessary (symptomatic or ionized calcium concentration less than 1 mmol/L).", "page": 5, "answerPage": 61, "stemZh": "40 歲男性，60 kg，車禍後入 trauma ICU；serum magnesium 1.2 mg/dL，家屬表示 alcohol abuse（12–18 beers/day）。給 magnesium sulfate 6 g IV，歷時 6 hours；隔天 magnesium 1.8 mg/dL。最適合的治療為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Magnesium 已正常，不需治療。"}, {"key": "B", "text": "再次測得 magnesium ≥2 mg/dL，便不需額外 magnesium。"}, {"key": "C", "text": "應與 magnesium 同時給 supplemental calcium。"}, {"key": "D", "text": "接下來 4–5 days 每日再補 magnesium。"}], "explanationZh": "短期輸注後約需 48 hours 平衡，翌日血中濃度可能暫時正常，若不繼續補充，1–2 days 後可能再次下降；通常需 4–5 days 補足。Hypocalcemia 常在 magnesium 治療 48 hours 內自行改善，只有 symptomatic 或 ionized calcium <1 mmol/L 等情況才可能需同步 calcium。"}, {"id": "03-self-07", "chapter": 3, "type": "self", "number": 7, "stem": "A 45-year-old man (weight 78 kg) with a history significant for hypertension and pancreatitis is admitted to the ICU after operative management of necrotizing pancreatitis. He is given PN consisting of 650 g of dextrose, 120 g of amino acids, and 55 g of lipid injectable emulsion (ILE) daily. Blood glucose (BG) measurements over the past 24 hours have been 180-325 mg/dL. Which change to this patient’s nutrition regimen is most appropriate at this time?", "context": "", "options": [{"key": "A", "text": "Initiate a sliding-scale insulin regimen with insulin aspart every 4 hours.", "sourceKey": "A"}, {"key": "B", "text": "Temporarily decrease the dextrose dose in the PN to 200 g and advance to dextrose 650 g once blood glucose is less than 180 mg/dL.", "sourceKey": "B"}, {"key": "C", "text": "Decrease dextrose to 500 g and make up with remaining kilocalories by increasing protein to 160 g.", "sourceKey": "C"}, {"key": "D", "text": "Decrease dextrose to 315 g and reassess glycemic control over the next 24 hours.", "sourceKey": "D"}], "answer": "D", "explanation": "The current PN formula prescribed provides 3240 kcal/ day (42 kcal/kg/day with a glucose infusion rate of 5.8 mg/kg/minute), which is an excessive amount of energy for this patient, and he has possible signs of overfeeding in the form of hyperglycemia. Answer D is correct because decreasing the dextrose dose to 315 g would appropriately bring the patient’s energy down to 2101 kcal/day (27 kcal/kg/day with a glucose infusion rate of 2.8 mg/kg/minute). An initial energy goal of 25–30 kcal/kg/day is appropriate for this patient, and by significantly decreasing the dextrose and total energy load provided in the PN, his hyperglycemia should improve. Answer A is incorrect because the additional insulin will not address the issue of overfeeding, and slidingscale insulin is unlikely to provide adequate glycemic control for this patient. Answer B is incorrect because temporarily adjusting the dextrose dose will not correct the issue of overfeeding in the long term. Answer C is incorrect because the total energy provided with these changes would still provide 37 kcal/kg/day and exceed the appropriate initial goal of 25–30 kcal/kg/day.", "page": 5, "answerPage": 61, "stemZh": "45 歲男性，78 kg，既往 hypertension、pancreatitis，necrotizing pancreatitis 術後入 ICU。PN 每日含 dextrose 650 g、amino acids 120 g、lipid injectable emulsion（ILE）55 g；過去 24 hours BG 180-325 mg/dL。目前最適合如何調整營養？", "contextZh": "", "optionsZh": [{"key": "A", "text": "每 4 hours 給 sliding-scale insulin aspart。"}, {"key": "B", "text": "暫降 dextrose 至 200 g，BG <180 mg/dL 後再升至 650 g。"}, {"key": "C", "text": "Dextrose 降至 500 g，protein 增至 160 g 補足熱量。"}, {"key": "D", "text": "Dextrose 降至 315 g，接下來 24 hours 重評 glycemic control。"}], "explanationZh": "原 PN 約 3240 kcal/day（42 kcal/kg/day），glucose infusion rate 5.8 mg/kg/minute，屬 overfeeding。降 dextrose 至 315 g 後約 2101 kcal/day（27 kcal/kg/day），2.8 mg/kg/minute，符合初始 25–30 kcal/kg/day。單加 insulin 或暫降後復原不能解決 overfeeding；C 仍有 37 kcal/kg/day。"}, {"id": "03-self-08", "chapter": 3, "type": "self", "number": 8, "stem": "A 48-year-old man is admitted to the trauma ICU after a motorcycle collision. His injuries include a subarachnoid hemorrhage, right pneumothorax, multiple rib fractures, grade 5 liver laceration, right sacral fracture, and transverse process fractures. His course is complicated by respiratory failure, acute kidney injury (AKI), and hyperglycemia. His labs today reveal serum sodium 141 mEq/L, chloride 102 mEq/L, carbon dioxide 20 mEq/L, and lactate 2.6 mmol/L. His arterial blood gas values are as follows: pH 7.46, Pco2 31 mmHg, and HCO 3 22 mEq/L, Which of the following assessments of his acid-base status is correct?", "context": "", "options": [{"key": "A", "text": "Primary respiratory alkalosis only.", "sourceKey": "A"}, {"key": "B", "text": "Primary respiratory alkalosis with underlying metabolic acidosis.", "sourceKey": "B"}, {"key": "C", "text": "Primary metabolic alkalosis with underlying respiratory alkalosis.", "sourceKey": "C"}, {"key": "D", "text": "Primary metabolic acidosis only.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient’s pH is high at 7.46 mmHg so his primary disorder is an alkalosis (Answer D is incorrect). His serum HCO 3 is 20 mEq/L (low) and Pco2 is 31 mmHg (low). His high pH and low Pco2 indicate that his primary disorder is a respiratory alkalosis (Answer C is incorrect). However, his laboratory values reveal an anion gap of 19 (141 − 102 − 20 = 19), which indicates that a metabolic acidosis is present, regardless of his pH or HCO 3 values (Answer A is incorrect). His delta ratio is 1.25 ([19−14] / [24−20]), which indicates that an anion gap metabolic acidosis is present with no other hidden metabolic process. Answer B is correct.", "page": 5, "answerPage": 61, "stemZh": "48 歲男性機車事故後入 trauma ICU，有 subarachnoid hemorrhage、right pneumothorax、多處 rib fractures、grade 5 liver laceration、right sacral fracture 與 transverse process fractures；併發 respiratory failure、AKI、hyperglycemia。Na 141 mEq/L、Cl 102 mEq/L、CO₂ 20 mEq/L、lactate 2.6 mmol/L；ABG：pH 7.46、Pco₂ 31 mmHg、HCO₃ 22 mEq/L。哪項 acid-base 評估正確？", "contextZh": "", "optionsZh": [{"key": "A", "text": "只有 primary respiratory alkalosis。"}, {"key": "B", "text": "Primary respiratory alkalosis，合併 metabolic acidosis。"}, {"key": "C", "text": "Primary metabolic alkalosis，合併 respiratory alkalosis。"}, {"key": "D", "text": "只有 primary metabolic acidosis。"}], "explanationZh": "高 pH 與低 Pco₂ 指向 primary respiratory alkalosis。Anion gap = 141 − 102 − 20 = 19，表示同時存在 metabolic acidosis；delta ratio = (19−14)/(24−20) = 1.25，符合 anion gap metabolic acidosis，未提示其他隱藏 metabolic process。"}, {"id": "03-case-01", "chapter": 3, "type": "case", "number": 1, "stem": "Which is the most likely etiology for the patient’s hyponatremia?", "context": "A 55-year-old woman (70 kg) admitted to the ICU for pneumonia and respiratory failure develops a serum sodium of 125 mEq/L on her fifth day of hospital admission. Her other laboratory values include a serum potassium of 4.6 mEq/L, chloride (Cl) 100 mEq/L, total carbon dioxide (CO 2 ) content 24 mEq/L, BUN 20 mg/ dL, serum creatinine (SCr) 1.1 mg/dL, and glucose 167 mg/dL. She currently receives a 1-kcal/mL, 62 g of protein/L enteral feeding formula at 60 mL/hour and a 5% dextrose in 0.45% sodium chloride infusion at 25 mL/hour. Her fluid balance has ranged from +300 to +600 mL/day during the past 3 days. She has no evidence of any significant amount of edema. Her measured serum osmolality is 265 mOsm/kg, urine osmolality is 490 mOsm/kg, and urine sodium is 67 mEq/L.", "options": [{"key": "A", "text": "Factitious hyponatremia", "sourceKey": "A"}, {"key": "B", "text": "Adrenal insufficiency", "sourceKey": "B"}, {"key": "C", "text": "Cerebral salt wasting", "sourceKey": "C"}, {"key": "D", "text": "SIAD", "sourceKey": "D"}], "answer": "D", "explanation": "Hyperglycemia and other causes of non-hypotonic hyponatremia have been excluded. Urine osmolality is greater than 100 mOsm/kg, which rules out psychogenic polydipsia, and a large amount of hypotonic fluids were not being given. Urine sodium was greater than 30 mEq/L, and the patient did not receive diuretic therapy or have kidney disease. The patient appeared to be normovolemic without evidence of significant edema (expansion of the ECF compartment). Because the patient also has pneumonia (a common cause of SIADH), all of these factors indicate that the patient has hyponatremia caused by SIADH (Answer D is correct). Answer A is incorrect because the serum glucose concentration is not high enough to cause hyponatremia; nor has the patient received mannitol, glycine: nor is the patient hypertriglyceridemic. Answer B is unlikely because there was no evidence of adrenal insufficiency given in the case. Answer C is impossible because the patient did not have a traumatic brain injury.", "page": 14, "answerPage": 57, "stemZh": "此病人 hyponatremia 最可能的病因為何？", "contextZh": "55 歲女性，70 kg，因 pneumonia、respiratory failure 入 ICU，第 5 天 sodium 125 mEq/L。K 4.6 mEq/L、Cl 100 mEq/L、total CO₂ 24 mEq/L、BUN 20 mg/dL、SCr 1.1 mg/dL、glucose 167 mg/dL。EN 配方 1-kcal/mL、protein 62 g/L，60 mL/hour；5% dextrose in 0.45% sodium chloride，25 mL/hour。過去 3 days fluid balance +300 至 +600 mL/day，無明顯 edema。Serum osmolality 265 mOsm/kg、urine osmolality 490 mOsm/kg、urine sodium 67 mEq/L。", "optionsZh": [{"key": "A", "text": "Factitious hyponatremia。"}, {"key": "B", "text": "Adrenal insufficiency。"}, {"key": "C", "text": "Cerebral salt wasting。"}, {"key": "D", "text": "SIAD。"}], "explanationZh": "低 serum osmolality、urine osmolality >100 mOsm/kg、urine sodium >30 mEq/L、無 diuretic 或 kidney disease、外觀 normovolemic，加上 pneumonia 常引起 SIADH，支持 SIADH。Glucose 不足以造成此 hyponatremia，也無 mannitol、glycine 或 hypertriglyceridemia；無 adrenal insufficiency 或 traumatic brain injury 的證據。"}, {"id": "03-case-02", "chapter": 3, "type": "case", "number": 2, "stem": "Which would be the most appropriate treatment for this woman?", "context": "A 55-year-old woman (70 kg) admitted to the ICU for pneumonia and respiratory failure develops a serum sodium of 125 mEq/L on her fifth day of hospital admission. Her other laboratory values include a serum potassium of 4.6 mEq/L, chloride (Cl) 100 mEq/L, total carbon dioxide (CO 2 ) content 24 mEq/L, BUN 20 mg/ dL, serum creatinine (SCr) 1.1 mg/dL, and glucose 167 mg/dL. She currently receives a 1-kcal/mL, 62 g of protein/L enteral feeding formula at 60 mL/hour and a 5% dextrose in 0.45% sodium chloride infusion at 25 mL/hour. Her fluid balance has ranged from +300 to +600 mL/day during the past 3 days. She has no evidence of any significant amount of edema. Her measured serum osmolality is 265 mOsm/kg, urine osmolality is 490 mOsm/kg, and urine sodium is 67 mEq/L.", "options": [{"key": "A", "text": "Give sodium chloride tablets 1 g three times daily.", "sourceKey": "A"}, {"key": "B", "text": "Limit fluids.", "sourceKey": "B"}, {"key": "C", "text": "Change the intravenous fluid to 0.9% sodium chloride.", "sourceKey": "C"}, {"key": "D", "text": "Provide a short-term intravenous infusion of 3% sodium chloride.", "sourceKey": "D"}], "answer": "B", "explanation": "Fluid restriction is the most appropriate treatment of SIADH (Answer B is correct). The “vaptans” may also be considered; however, this was not a choice. Answer A is incorrect because giving salt tabs may result in worsened fluid overload and edema. Answer C is incorrect for the same reason as Answer A. Answer D is incorrect because the severity of hyponatremia and lack of symptoms does not warrant the emergency use of hypertonic saline.", "page": 14, "answerPage": 57, "stemZh": "此女性最適合的治療為何？", "contextZh": "55 歲女性，70 kg，因 pneumonia、respiratory failure 入 ICU，第 5 天 sodium 125 mEq/L。K 4.6 mEq/L、Cl 100 mEq/L、total CO₂ 24 mEq/L、BUN 20 mg/dL、SCr 1.1 mg/dL、glucose 167 mg/dL。EN 配方 1-kcal/mL、protein 62 g/L，60 mL/hour；5% dextrose in 0.45% sodium chloride，25 mL/hour。過去 3 days fluid balance +300 至 +600 mL/day，無明顯 edema。Serum osmolality 265 mOsm/kg、urine osmolality 490 mOsm/kg、urine sodium 67 mEq/L。", "optionsZh": [{"key": "A", "text": "Sodium chloride tablets 1 g，每日 3 次。"}, {"key": "B", "text": "限制輸入液體。"}, {"key": "C", "text": "將 IV fluid 改為 0.9% sodium chloride。"}, {"key": "D", "text": "短期 IV infusion 3% sodium chloride。"}], "explanationZh": "SIADH 以 fluid restriction 最適合。Salt tablets 或 isotonic saline 可能加重 fluid overload；目前無症狀且程度不足以支持緊急 hypertonic saline。Vaptans 亦可能考慮，但不在選項中。"}, {"id": "03-case-03", "chapter": 3, "type": "case", "number": 3, "stem": "Which change in the enteral feeding formula would be best for this patient?", "context": "A 55-year-old woman (70 kg) admitted to the ICU for pneumonia and respiratory failure develops a serum sodium of 125 mEq/L on her fifth day of hospital admission. Her other laboratory values include a serum potassium of 4.6 mEq/L, chloride (Cl) 100 mEq/L, total carbon dioxide (CO 2 ) content 24 mEq/L, BUN 20 mg/ dL, serum creatinine (SCr) 1.1 mg/dL, and glucose 167 mg/dL. She currently receives a 1-kcal/mL, 62 g of protein/L enteral feeding formula at 60 mL/hour and a 5% dextrose in 0.45% sodium chloride infusion at 25 mL/hour. Her fluid balance has ranged from +300 to +600 mL/day during the past 3 days. She has no evidence of any significant amount of edema. Her measured serum osmolality is 265 mOsm/kg, urine osmolality is 490 mOsm/kg, and urine sodium is 67 mEq/L.", "options": [{"key": "A", "text": "Add sodium chloride 100 mEq/L to the current formula.", "sourceKey": "A"}, {"key": "B", "text": "Change the formula to a fish oil–enriched product.", "sourceKey": "B"}, {"key": "C", "text": "Change the formula to a low-carbohydrate, high-fat product.", "sourceKey": "C"}, {"key": "D", "text": "Change the formula to a 2-kcal/mL formula, and decrease the rate.", "sourceKey": "D"}], "answer": "D", "explanation": "The best way to fluid-restrict an enterally fed patient is to use the most concentrated formulas, which are the 2-kcal/mL formulations that are specifically designed for patients with congestive heart failure. Unfortunately, protein intake may be inadequate with the use of these formulations in certain populations, and supplemental protein may have to be provided. Answers A, B, and C are incorrect because they do not result in the appropriate therapeutic decision to reduce fluid intake.", "page": 14, "answerPage": 57, "stemZh": "如何調整 enteral feeding formula 最適合此病人？", "contextZh": "55 歲女性，70 kg，因 pneumonia、respiratory failure 入 ICU，第 5 天 sodium 125 mEq/L。K 4.6 mEq/L、Cl 100 mEq/L、total CO₂ 24 mEq/L、BUN 20 mg/dL、SCr 1.1 mg/dL、glucose 167 mg/dL。EN 配方 1-kcal/mL、protein 62 g/L，60 mL/hour；5% dextrose in 0.45% sodium chloride，25 mL/hour。過去 3 days fluid balance +300 至 +600 mL/day，無明顯 edema。Serum osmolality 265 mOsm/kg、urine osmolality 490 mOsm/kg、urine sodium 67 mEq/L。", "optionsZh": [{"key": "A", "text": "在現有配方加入 sodium chloride 100 mEq/L。"}, {"key": "B", "text": "改用 fish oil-enriched 配方。"}, {"key": "C", "text": "改用 low-carbohydrate、high-fat 配方。"}, {"key": "D", "text": "改用 2-kcal/mL 配方並降低速率。"}], "explanationZh": "使用 2-kcal/mL 濃縮配方並降速，可達 fluid restriction；需確認 protein 是否足夠，必要時補充。其他選项無法達成減少液體攝入的主要目標。"}, {"id": "03-case-04", "chapter": 3, "type": "case", "number": 4, "stem": "Which potassium-phosphorus dosing regimen would be most appropriate for this patient?", "context": "A 65-year-old man (weight 87 kg) is admitted to the hospital with severe acute pancreatitis. A computed tomography (CT) scan of the abdomen reveals a pancreatic pseudocyst. He is to remain NPO (nothing by mouth) because of marked abdominal pain on a low-fat diet and during a trial of EN; therefore, he is given PN. He is a 2 pack/day tobacco smoker and has a history of frequent alcohol consumption. His serum laboratory values are as follows: sodium (Na) 139 mEq/L, potassium (K) 3.3 mEq/L, Cl 102 mEq/L, total CO 2 content 25 mEq/L, BUN 14 mg/dL, SCr 0.8 mg/dL, calcium 7.6 mg/dL, phosphorus 2.2 mg/dL, magnesium 1.5 mg/dL, and albumin 2.5 g/dL.", "options": [{"key": "A", "text": "Potassium phosphate 30 mmol intravenously x 1 dose, followed by potassium chloride 40 mEq via NG tube x 2 doses.", "sourceKey": "A"}, {"key": "B", "text": "Potassium phosphate 30 mmol intravenously x 1 dose, followed by potassium chloride 40 mEq intravenously x 1 dose.", "sourceKey": "B"}, {"key": "C", "text": "Potassium phosphate 60 mmol intravenously x 1 dose.", "sourceKey": "C"}, {"key": "D", "text": "Potassium chloride 40 mEq via NG tube x 2 doses, followed by Neutra-Phos 250 mg via NG tube x 2 doses.", "sourceKey": "D"}], "answer": "B", "explanation": "These dosages should be selected as the correct answer because they follow the dosing guidelines given in this chapter (unlike the doses given in answers A, C, D). Given that the patient is NPO with intolerance to anything by mouth, oral options (Answers A and D) are not practical. If the patient had a history of significant recent weight loss or if he did not respond adequately to these doses, the dose could be increased. Answer C is not correct as the dosage of phosphorus is excessive. Supplemental potassium and phosphorus would be added to the PN solution, in addition to daily intravenous doses of potassium and phosphorus.", "page": 20, "answerPage": 57, "stemZh": "哪個 potassium–phosphorus 補充方案最適合？", "contextZh": "65 歲男性，87 kg，因 severe acute pancreatitis 入院，CT 顯示 pancreatic pseudocyst。Low-fat diet 及 EN 均造成明顯 abdominal pain，維持 NPO 並給 PN。每日吸菸 2 pack/day，經常飲酒。Na 139 mEq/L、K 3.3 mEq/L、Cl 102 mEq/L、total CO₂ 25 mEq/L、BUN 14 mg/dL、SCr 0.8 mg/dL、calcium 7.6 mg/dL、phosphorus 2.2 mg/dL、magnesium 1.5 mg/dL、albumin 2.5 g/dL。", "optionsZh": [{"key": "A", "text": "Potassium phosphate 30 mmol IV × 1 dose，後給 potassium chloride 40 mEq 經 NG tube × 2 doses。"}, {"key": "B", "text": "Potassium phosphate 30 mmol IV × 1 dose，後給 potassium chloride 40 mEq IV × 1 dose。"}, {"key": "C", "text": "Potassium phosphate 60 mmol IV × 1 dose。"}, {"key": "D", "text": "Potassium chloride 40 mEq 經 NG tube × 2 doses，後給 Neutra-Phos 250 mg 經 NG tube × 2 doses。"}], "explanationZh": "B 符合本章補充劑量。病人 NPO 且不耐受 enteral intake，A／D 不實用；60 mmol phosphorus 過量。PN 亦應補充 potassium 與 phosphorus，若近期顯著體重下降或反應不足再考量增加劑量。"}, {"id": "03-case-05", "chapter": 3, "type": "case", "number": 5, "stem": "In addition to potassium and phosphorus supplementation, the patient is given magnesium sulfate 6 g intravenously for 6 hours. His repeat serum magnesium the next day is 2.0 mg/dL. Which therapeutic option would be best for this patient?", "context": "A 65-year-old man (weight 87 kg) is admitted to the hospital with severe acute pancreatitis. A computed tomography (CT) scan of the abdomen reveals a pancreatic pseudocyst. He is to remain NPO (nothing by mouth) because of marked abdominal pain on a low-fat diet and during a trial of EN; therefore, he is given PN. He is a 2 pack/day tobacco smoker and has a history of frequent alcohol consumption. His serum laboratory values are as follows: sodium (Na) 139 mEq/L, potassium (K) 3.3 mEq/L, Cl 102 mEq/L, total CO 2 content 25 mEq/L, BUN 14 mg/dL, SCr 0.8 mg/dL, calcium 7.6 mg/dL, phosphorus 2.2 mg/dL, magnesium 1.5 mg/dL, and albumin 2.5 g/dL.", "options": [{"key": "A", "text": "Give magnesium oxide 500 mg twice daily for the next few days.", "sourceKey": "A"}, {"key": "B", "text": "Give magnesium sulfate 2–4 g intravenously daily for the next few days.", "sourceKey": "B"}, {"key": "C", "text": "Give an additional dose of 8 g of magnesium sulfate intravenously.", "sourceKey": "C"}, {"key": "D", "text": "No additional treatment is necessary.", "sourceKey": "D"}], "answer": "B", "explanation": "Because it takes about 48 hours for serum magnesium to redistribute, the next day’s serum magnesium concentration is falsely elevated. In general, it will take 4–5 days to replete this patient’s magnesium deficiency (presumably caused by chronic alcohol ingestion). Thus, answer B would be the best option for this patient. Given that the patient is NPO, oral dosing options (answer A) are less desirable. Answer C is incorrect because it is too aggressive a dosage given the current serum magnesium concentration of 2.0 mg/dL (despite it being falsely elevated). Supplemental magnesium would be added to the PN solution in addition to daily doses of intravenous magnesium sulfate if he remained low or in the lownormal range or if he was also hypocalcemic (because hypomagnesemia can elicit hypocalcemia secondary to end-organ resistance to parathyroid hormone). Answer D is incorrect as the serum magnesium concentration is falsely elevated to within the normal range but has not fully redistributed yet. It would be anticipated that the concentration will decrease the following day since it takes multiple days to replenish magnesium stores.", "page": 20, "answerPage": 57, "stemZh": "除 potassium 與 phosphorus 補充外，給 magnesium sulfate 6 g IV，歷時 6 hours；翌日 magnesium 2.0 mg/dL。最佳治療為何？", "contextZh": "65 歲男性，87 kg，因 severe acute pancreatitis 入院，CT 顯示 pancreatic pseudocyst。Low-fat diet 及 EN 均造成明顯 abdominal pain，維持 NPO 並給 PN。每日吸菸 2 pack/day，經常飲酒。Na 139 mEq/L、K 3.3 mEq/L、Cl 102 mEq/L、total CO₂ 25 mEq/L、BUN 14 mg/dL、SCr 0.8 mg/dL、calcium 7.6 mg/dL、phosphorus 2.2 mg/dL、magnesium 1.5 mg/dL、albumin 2.5 g/dL。", "optionsZh": [{"key": "A", "text": "接下來數日 magnesium oxide 500 mg，每日 2 次。"}, {"key": "B", "text": "接下來數日 magnesium sulfate 2–4 g IV，每日給藥。"}, {"key": "C", "text": "再給 magnesium sulfate 8 g IV。"}, {"key": "D", "text": "不需額外治療。"}], "explanationZh": "Magnesium 約需 48 hours 重新分布，翌日濃度會暫時偏高；通常需 4–5 days 補足儲存量。NPO 不宜口服；目前 8 g 過於積極；停止補充則預期再下降。若仍低或低正常，PN 中亦可追加 magnesium。"}, {"id": "03-case-06", "chapter": 3, "type": "case", "number": 6, "stem": "Which is the most likely etiology of his hypocalcemia?", "context": "A 24-year-old man (weight 90 kg) is admitted to the trauma ICU postoperatively from repair of his duodenal, jejunal, ileal, and colon injuries; hepatorrhaphy; and splenectomy after several gunshot wounds to the abdomen. He also received 10 units of packed red blood cells. He has a serum ionized calcium concentration of 0.86 mmol/L, K 4.6 mEq/L, and magnesium 1.8 mg/dL. His SCr concentration is 0.8 mg/dL, and his urine output is 0.5 mL/kg/hour.", "options": [{"key": "A", "text": "Hypomagnesemia", "sourceKey": "A"}, {"key": "B", "text": "Excessive urinary diuresis", "sourceKey": "B"}, {"key": "C", "text": "Blood transfusion", "sourceKey": "C"}, {"key": "D", "text": "Critical illness", "sourceKey": "D"}], "answer": "C", "explanation": "Although critical illness (Answer D) and fluid resuscitation therapy may have been a factor in the development of his hypocalcemia, massive blood transfusion is the most profound cause. Citrate, added to the blood as an anticoagulant, readily binds calcium and can cause hypocalcemia. Previous studies have shown that hypocalcemia is common when patients are given more than 5 units of blood at a time (Answer C is correct). Answer A is incorrect because a low-normal serum magnesium concentration of 1.8 mg/dL is unlikely to contribute to the pathogenesis of hypocalcemia. A serum magnesium concentration of less than or equal to 1.5 mg/dL is more likely to contribute to the pathogenesis of hypocalcemia. Answer B is incorrect because a urine output of 0.5 mL/kg/hr is not excessive.", "page": 22, "answerPage": 57, "stemZh": "此病人 hypocalcemia 最可能的病因為何？", "contextZh": "24 歲男性，90 kg，多處腹部槍傷後，接受 duodenal、jejunal、ileal、colon 修補、hepatorrhaphy 與 splenectomy，術後入 trauma ICU。輸注 packed red blood cells 10 units；ionized calcium 0.86 mmol/L、K 4.6 mEq/L、magnesium 1.8 mg/dL、SCr 0.8 mg/dL，urine output 0.5 mL/kg/hour。", "optionsZh": [{"key": "A", "text": "Hypomagnesemia。"}, {"key": "B", "text": "過度 urinary diuresis。"}, {"key": "C", "text": "Blood transfusion。"}, {"key": "D", "text": "Critical illness。"}], "explanationZh": "大量輸血中作為 anticoagulant 的 citrate 會結合 calcium；一次 >5 units 即常見 hypocalcemia，本例 10 units 是最重要原因。Magnesium 1.8 mg/dL 低正常較不可能致病，通常 ≤1.5 mg/dL 較相關；urine output 0.5 mL/kg/hour 並非過多。"}, {"id": "03-case-07", "chapter": 3, "type": "case", "number": 7, "stem": "Which therapeutic regimen would be best for this patient?", "context": "A 24-year-old man (weight 90 kg) is admitted to the trauma ICU postoperatively from repair of his duodenal, jejunal, ileal, and colon injuries; hepatorrhaphy; and splenectomy after several gunshot wounds to the abdomen. He also received 10 units of packed red blood cells. He has a serum ionized calcium concentration of 0.86 mmol/L, K 4.6 mEq/L, and magnesium 1.8 mg/dL. His SCr concentration is 0.8 mg/dL, and his urine output is 0.5 mL/kg/hour.", "options": [{"key": "A", "text": "Calcium gluconate 2 g intravenously for 2 hours", "sourceKey": "A"}, {"key": "B", "text": "Calcium gluconate 4 g intravenously for 4 hours", "sourceKey": "B"}, {"key": "C", "text": "Calcium chloride 1 g intravenous push for 5–10 minutes", "sourceKey": "C"}, {"key": "D", "text": "No calcium therapy necessary.", "sourceKey": "D"}], "answer": "B", "explanation": "A short-term intravenous infusion of 4 g of calcium gluconate (1 g = 4.6 mEq) for 4 hours has been shown to be a safe and effective therapeutic regimen for moderate to severe hypocalcemia (ionized calcium less than 1 mmol/L) (Answer B is correct). Answer A is incorrect because it is an insufficient dosage of elemental calcium. A bolus/push dose of calcium chloride (1 g = 13.6 mEq), as given in answer C, would be an effective means for treating symptomatic severe hyperkalemia, but it would be unnecessarily aggressive for treating hypocalcemia in this patient scenario. Answer D is incorrect because the moderate to severe hypocalcemia should be corrected in this post-operative trauma patient who is anemic and at high risk for bleeding complications.", "page": 22, "answerPage": 58, "stemZh": "此病人最佳治療方案為何？", "contextZh": "24 歲男性，90 kg，多處腹部槍傷後，接受 duodenal、jejunal、ileal、colon 修補、hepatorrhaphy 與 splenectomy，術後入 trauma ICU。輸注 packed red blood cells 10 units；ionized calcium 0.86 mmol/L、K 4.6 mEq/L、magnesium 1.8 mg/dL、SCr 0.8 mg/dL，urine output 0.5 mL/kg/hour。", "optionsZh": [{"key": "A", "text": "Calcium gluconate 2 g IV，歷時 2 hours。"}, {"key": "B", "text": "Calcium gluconate 4 g IV，歷時 4 hours。"}, {"key": "C", "text": "Calcium chloride 1 g IV push，歷時 5–10 minutes。"}, {"key": "D", "text": "不需 calcium 治療。"}], "explanationZh": "Calcium gluconate 4 g／4 hours 是 moderate 至 severe hypocalcemia（ionized calcium <1 mmol/L）的安全有效方案；1 g 含 4.6 mEq。2 g 不足；calcium chloride 1 g 含 13.6 mEq，push 對此情境過於積極。術後貧血且出血風險高，應矯正。"}, {"id": "03-case-08", "chapter": 3, "type": "case", "number": 8, "stem": "Which best describes the patient’s type of acid-base disorder?", "context": "A 60-year-old woman (weight 80 kg) was admitted to the hospital after 1 week of severe diarrhea. She presents with clinical evidence of dehydration (hypotension, tachycardia, decreased urine output) and is weak. Her serum laboratory values are as follows: Na 145 mEq/L, K 3.0 mEq/L, Cl 118 mEq/L, total CO 2 18 mEq/L, BUN 29 mg/dL, SCr 0.9 mg/dL, glucose 122 mg/dL, calcium 9.1 mg/dL, phosphorus 3.7 mg/dL, magnesium 1.4 mg/L, albumin 3.9 g/dL, and lactate 1.6 mmol/L. Her ABG is pH 7.29, Po2 93 mm Hg, Pco2 34 mm Hg, HCO 3 17 mEq/L, and base excess -5 mEq/L. She has a 30 pack/year smoking history.", "options": [{"key": "A", "text": "Hyperchloremic, normal AG acidosis", "sourceKey": "A"}, {"key": "B", "text": "AG acidosis", "sourceKey": "B"}, {"key": "C", "text": "AG acidosis with hyperchloremia", "sourceKey": "C"}, {"key": "D", "text": "Respiratory alkalosis with concurrent metabolic alkalosis", "sourceKey": "D"}], "answer": "A", "explanation": "Examination of the pH indicates that the patient has an acidemia because it is lower than 7.35. Looking at Pco2 and serum bicarbonate would indicate that the primary etiology is metabolic because both are low. Calculation of the AG (145 − 118 − 18 =9) shows that no AG is present (Answers B and C are incorrect).A correction for serum albumin concentration is not needed because it is normal. The serum lactate is near the high end of the normal range but still within the normal range. This would indicate that the patient’s dehydration has not become so extreme that a significant decrease in tissue perfusion was not evident (yet). Respiratory compensation appears to be intact ([1.5 x 17] + 8 = 33 vs. 34 mm Hg) on the blood gas, and it appears that the patient’s history of smoking did not compromise her ability to mount a reasonable respiratory response to the acidosis. The serum chloride of 118 mEq/L indicates hyperchloremia. A non-AG hyperchloremic metabolic acidosis is common for patients with severe diarrhea. The low serum potassium and magnesium would also strongly suggest that the patient has significant diarrhea (Answer A is correct). Answer D is incorrect because the decreased Pco2 is in response to the metabolic acidosis and the patient does not have a metabolic alkalosis but rather an acidosis.", "page": 31, "answerPage": 58, "stemZh": "此病人屬於哪種 acid-base disorder？", "contextZh": "60 歲女性，80 kg，severe diarrhea 1 week 後入院，出現 dehydration（hypotension、tachycardia、urine output 下降）與無力。Na 145 mEq/L、K 3.0 mEq/L、Cl 118 mEq/L、total CO₂ 18 mEq/L、BUN 29 mg/dL、SCr 0.9 mg/dL、glucose 122 mg/dL、calcium 9.1 mg/dL、phosphorus 3.7 mg/dL、magnesium 1.4 mg/L、albumin 3.9 g/dL、lactate 1.6 mmol/L。ABG：pH 7.29、Po₂ 93 mm Hg、Pco₂ 34 mm Hg、HCO₃ 17 mEq/L、base excess -5 mEq/L；吸菸史 30 pack/year。", "optionsZh": [{"key": "A", "text": "Hyperchloremic、normal AG acidosis。"}, {"key": "B", "text": "AG acidosis。"}, {"key": "C", "text": "AG acidosis 合併 hyperchloremia。"}, {"key": "D", "text": "Respiratory alkalosis 合併 metabolic alkalosis。"}], "explanationZh": "pH <7.35、HCO₃ 低，表示 metabolic acidosis；AG = 145−118−18 = 9，albumin 正常不需校正。預期 Pco₂ = (1.5 × 17)+8 = 33，實測 34 mm Hg，respiratory compensation 適當。Cl 118 mEq/L 配合 diarrhea，符合 non-AG hyperchloremic metabolic acidosis。"}, {"id": "03-case-09", "chapter": 3, "type": "case", "number": 9, "stem": "Which is the most appropriate initial fluid therapy for this patient?", "context": "A 60-year-old woman (weight 80 kg) was admitted to the hospital after 1 week of severe diarrhea. She presents with clinical evidence of dehydration (hypotension, tachycardia, decreased urine output) and is weak. Her serum laboratory values are as follows: Na 145 mEq/L, K 3.0 mEq/L, Cl 118 mEq/L, total CO 2 18 mEq/L, BUN 29 mg/dL, SCr 0.9 mg/dL, glucose 122 mg/dL, calcium 9.1 mg/dL, phosphorus 3.7 mg/dL, magnesium 1.4 mg/L, albumin 3.9 g/dL, and lactate 1.6 mmol/L. Her ABG is pH 7.29, Po2 93 mm Hg, Pco2 34 mm Hg, HCO 3 17 mEq/L, and base excess -5 mEq/L. She has a 30 pack/year smoking history.", "options": [{"key": "A", "text": "0.45% sodium chloride with potassium chloride 20 mEq/L", "sourceKey": "A"}, {"key": "B", "text": "0.9% sodium chloride with potassium chloride 20 mEq/L", "sourceKey": "B"}, {"key": "C", "text": "Lactated Ringer solution", "sourceKey": "C"}, {"key": "D", "text": "5% dextrose", "sourceKey": "D"}], "answer": "C", "explanation": "Initial therapy with lactated Ringer solution would be the ideal choice (Answer C is correct). Treatment with 0.9% sodium chloride (Answer B) is incorrect because it would worsen the hyperchloremic acidosis. A 5% dextrose solution (Answer D) would be a poor choice because sodium/isotonic fluids are necessary to restore intravascular volume. Because the severity of the patient’s acidemia is mild (pH 7.29), aggressive therapy with sodium bicarbonate is not indicated. After the first day of lactated Ringer solution to restore intravascular volume and improve pH, it would be reasonable to change to 0.45% sodium chloride to continue to restore volume depletion, depending on the patient’s response to the lactated Ringer solution (e.g., restoration of normal pH, adequate urine output, resolution of tachycardia). Thus, answer A would be incorrect as the question asked for the most appropriate initial treatment. Of course, aggressive potassium and magnesium repletion is indicated as well. This could be done with infusions as previously discussed, and it would be reasonable to add 20 mEq of potassium chloride per liter to the 0.45% sodium chloride upon discontinuation of the lactated Ringer solution.", "page": 31, "answerPage": 58, "stemZh": "此病人最適合的初始 fluid therapy 為何？", "contextZh": "60 歲女性，80 kg，severe diarrhea 1 week 後入院，出現 dehydration（hypotension、tachycardia、urine output 下降）與無力。Na 145 mEq/L、K 3.0 mEq/L、Cl 118 mEq/L、total CO₂ 18 mEq/L、BUN 29 mg/dL、SCr 0.9 mg/dL、glucose 122 mg/dL、calcium 9.1 mg/dL、phosphorus 3.7 mg/dL、magnesium 1.4 mg/L、albumin 3.9 g/dL、lactate 1.6 mmol/L。ABG：pH 7.29、Po₂ 93 mm Hg、Pco₂ 34 mm Hg、HCO₃ 17 mEq/L、base excess -5 mEq/L；吸菸史 30 pack/year。", "optionsZh": [{"key": "A", "text": "0.45% sodium chloride 加 potassium chloride 20 mEq/L。"}, {"key": "B", "text": "0.9% sodium chloride 加 potassium chloride 20 mEq/L。"}, {"key": "C", "text": "Lactated Ringer solution。"}, {"key": "D", "text": "5% dextrose。"}], "explanationZh": "Lactated Ringer solution 可恢復 intravascular volume，避免 normal saline 加重 hyperchloremic acidosis。5% dextrose 不適合恢復 intravascular volume；0.45% sodium chloride 可在初始 resuscitation 後視反應考慮。pH 7.29 不需積極 sodium bicarbonate，並需補 potassium、magnesium。"}, {"id": "03-case-10", "chapter": 3, "type": "case", "number": 10, "stem": "A 40-kg woman admitted to the trauma ICU receives a PN solution containing 350 g of dextrose, 160 g of amino acids, and 60 g of lipid daily. She has normal renal and hepatic function. Her most recent ABG from the morning shows a pH of 7.30, Pco2 55 mm Hg, Po2 96 mm Hg, and HCO 3 31 mEq/L. Her fingerstick BG values from the past 24 hours are 180–200 mg/dL. Which would be best to recommend regarding her PN?", "context": "", "options": [{"key": "A", "text": "Decrease dextrose to 175 g/day, and increase lipid to 120 g/day.", "sourceKey": "A"}, {"key": "B", "text": "Add 20 units of regular human insulin per day to the PN solution.", "sourceKey": "B"}, {"key": "C", "text": "Decrease all the macronutrients by about one-half.", "sourceKey": "C"}, {"key": "D", "text": "Increase the acetate content of the PN solution.", "sourceKey": "D"}], "answer": "C", "explanation": "The current PN regimen provides 61 kcal/kg/day total (glucose 6.1 mg/kg/minute and lipid emulsion 1.5 g/ kg/day) and protein 4 g/kg/day. The PN regimen represents gross overfeeding of this small woman and can explain her hyperglycemia and hypercapnia. Cutting all macronutrients by about one-half would result in a more reasonable regimen for this patient: 30 kcal/kg/ day (glucose 3 mg/kg/minute and lipid emulsion 0.8 g/ kg/day) and protein 2 g/kg/day. Because she is so small (weight 40 kg), it would be important to double-check the weight-based calculation to see whether this new regimen is appropriate to meet her caloric needs without overfeeding by calculating the BEE using the HarrisBenedict equation for women (caloric intake should not exceed 1.3–1.5 x BEE for a critically ill patient with traumatic injuries) (Answer C is correct). Although answer A reduces the respiratory quotient of the nutrient admixture, this will not solve the primary problem of overfeeding the patient because excessive calories are being provided. Answers B and D may help with the consequences of overfeeding (e.g., hyperglycemia and respiratory acidosis) but do not address the primary problem (overfeeding) and are inappropriate management techniques.", "page": 45, "answerPage": 58, "stemZh": "40-kg 女性入 trauma ICU，每日 PN 含 dextrose 350 g、amino acids 160 g、lipid 60 g，renal 與 hepatic function 正常。ABG：pH 7.30、Pco₂ 55 mm Hg、Po₂ 96 mm Hg、HCO₃ 31 mEq/L；24 hours 指尖 BG 180–200 mg/dL。PN 最佳調整為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dextrose 降至 175 g/day，lipid 增至 120 g/day。"}, {"key": "B", "text": "PN 加 regular human insulin 20 units/day。"}, {"key": "C", "text": "所有 macronutrients 約減半。"}, {"key": "D", "text": "增加 PN 的 acetate。"}], "explanationZh": "原 PN 61 kcal/kg/day、glucose 6.1 mg/kg/minute、lipid 1.5 g/kg/day、protein 4 g/kg/day，嚴重 overfeeding，可解釋 hyperglycemia 與 hypercapnia。減半約為 30 kcal/kg/day、glucose 3 mg/kg/minute、lipid 0.8 g/kg/day、protein 2 g/kg/day，並應用 Harris-Benedict equation 重核需求（不超過 1.3–1.5 × BEE）。其他選項未處理熱量過高。"}, {"id": "03-case-11", "chapter": 3, "type": "case", "number": 11, "stem": "Which best depicts the kilocalories and protein this regimen will provide?", "context": "A 60-year-old man (weight 65 kg; about 90% IBW) is admitted for acute pancreatitis. After 4 days, he still has significant abdominal pain and distension without resolution. He has a fever, and blood/urine cultures are obtained. A CT scan of the abdomen reveals an ileus and an intra-abdominal abscess. He is given a goal PN regimen containing 300 g of dextrose, 70 g of amino acids, and 40 g of 20% lipids daily.", "options": [{"key": "A", "text": "26 kcal/kg/day and 1.1 g/kg/day", "sourceKey": "A"}, {"key": "B", "text": "26 kcal/kg/day and 1.5 g/kg/day", "sourceKey": "B"}, {"key": "C", "text": "28 kcal/kg/day and 1.5 g/kg/day", "sourceKey": "C"}, {"key": "D", "text": "30 kcal/kg/day and 1.5 g/kg/day", "sourceKey": "D"}], "answer": "A", "explanation": "Total kilocalories per day = (300 g x 3.4 kcal/g of dextrose) + (70 g x 4 kcal/g of protein) + (40 x 10 kcal/g of lipid emulsion) = 1020 glucose kcal + 280 protein kcal + 400 lipid kcal = 1700 total kcal/65 kg = 26 kcal/kg/day. Only 20% and 30% lipid emulsions are available for PN compounding. Each solution provides 10 kcal/g of intravenous lipid (unlike 9 kcal/g with oral fat) because glycerol and phospholipids are added to the emulsion. Protein intake is 70 g/65 kg = 1.1 g/kg/day (Answer A is correct). Answers B, C, and D do not represent the correct calculations as described previously.", "page": 45, "answerPage": 59, "stemZh": "此方案每日提供多少 kilocalories 與 protein？", "contextZh": "60 歲男性，65 kg，約 90% IBW，因 acute pancreatitis 入院，4 days 後仍有明顯腹痛與腹脹。因 fever 取得 blood／urine cultures；CT 顯示 ileus 與 intra-abdominal abscess。目標 PN 每日含 dextrose 300 g、amino acids 70 g、20% lipids 40 g。", "optionsZh": [{"key": "A", "text": "26 kcal/kg/day 與 1.1 g/kg/day。"}, {"key": "B", "text": "26 kcal/kg/day 與 1.5 g/kg/day。"}, {"key": "C", "text": "28 kcal/kg/day 與 1.5 g/kg/day。"}, {"key": "D", "text": "30 kcal/kg/day 與 1.5 g/kg/day。"}], "explanationZh": "熱量 = 300 × 3.4 + 70 × 4 + 40 × 10 = 1700 kcal；1700/65 = 26 kcal/kg/day。Protein = 70/65 = 1.1 g/kg/day。IV lipid emulsion 含 glycerol、phospholipids，20%／30% 配方為 10 kcal/g，與口服脂肪 9 kcal/g 不同。"}, {"id": "03-case-12", "chapter": 3, "type": "case", "number": 12, "stem": "Which changes would be best for this patient’s PN regimen?", "context": "A 60-year-old man (weight 65 kg; about 90% IBW) is admitted for acute pancreatitis. After 4 days, he still has significant abdominal pain and distension without resolution. He has a fever, and blood/urine cultures are obtained. A CT scan of the abdomen reveals an ileus and an intra-abdominal abscess. He is given a goal PN regimen containing 300 g of dextrose, 70 g of amino acids, and 40 g of 20% lipids daily.", "options": [{"key": "A", "text": "Increase dextrose to 400 g/day.", "sourceKey": "A"}, {"key": "B", "text": "Decrease dextrose to 200 g/day.", "sourceKey": "B"}, {"key": "C", "text": "Increase protein to 100 g/day.", "sourceKey": "C"}, {"key": "D", "text": "Increase lipids to 70 g/day.", "sourceKey": "D"}], "answer": "C", "explanation": "This patient is moderately stressed with a normal BMI. Appropriate energy intake would be 25–30 kcal/kg/day (1625–1950 kcal/day), and protein intake would be 1.2–2 g/kg/day (78–130 g). Increasing dextrose to 400 g/day would provide a total energy of 31 kcal/kg/day. Although this glucose intake of 4.3 mg/kg/minute does not exceed 5 mg/kg/minute, the total kcal/day from all macronutrients would exceed the recommended initial range for this patient (Answer A is incorrect). Decreasing the dextrose dose to 200 g/day would provide a total energy of 21 kcal/kg/day from all macronutrients, which is below the target energy range for this patient (Answer B is incorrect). Increasing the lipid dose to 70 g/day would provide a total energy of 31 kcal/kg/day from all macronutrients, which is above the target of 25–30 kcal/kg/ day (Answer D is incorrect). A protein dose of 100 g/ day would provide 1.5 g/kg/day of protein. This dose is appropriate and falls within the recommended 1.2–2 g/ kg/day. Increasing the protein dose to 100 g/day while maintaining dextrose at 300 g and lipid at 40 g would provide the patient with 1820 kcal or 28 kcal/kg/day. This is an appropriate protein and energy intake for this patient (Answer C is correct).", "page": 45, "answerPage": 59, "stemZh": "此病人 PN 最佳調整為何？", "contextZh": "60 歲男性，65 kg，約 90% IBW，因 acute pancreatitis 入院，4 days 後仍有明顯腹痛與腹脹。因 fever 取得 blood／urine cultures；CT 顯示 ileus 與 intra-abdominal abscess。目標 PN 每日含 dextrose 300 g、amino acids 70 g、20% lipids 40 g。", "optionsZh": [{"key": "A", "text": "Dextrose 增至 400 g/day。"}, {"key": "B", "text": "Dextrose 降至 200 g/day。"}, {"key": "C", "text": "Protein 增至 100 g/day。"}, {"key": "D", "text": "Lipids 增至 70 g/day。"}], "explanationZh": "目標 25–30 kcal/kg/day（1625–1950 kcal/day）、protein 1.2–2 g/kg/day（78–130 g）。Protein 100 g/day 為 1.5 g/kg/day，維持 dextrose 300 g 與 lipid 40 g 時，總熱量 1820 kcal／28 kcal/kg/day。A／D 熱量升至 31 kcal/kg/day；B 降至 21 kcal/kg/day，均偏離目標。"}, {"id": "03-case-13", "chapter": 3, "type": "case", "number": 13, "stem": "A 55-year-old woman (weight 75 kg) without diabetes is given PN after a major GI resection. She has been weaned from mechanical ventilation and is being transferred from the ICU to the floor. Her current PN formulation is 200 g of dextrose (1.8 mg/kg/minute), 110 g of amino acids, and 80 g of lipids (1.1 g/kg/day), which meets her goal requirements at 26 kcal/kg/day and 1.5 g/kg/day of protein. It contains regular human insulin at 20 units/day. During the past 24 hours, her fingerstick BG measurements have been 170–210 mg/ dL, and her serum glucose concentration is 182 mg/dL. She has received 14 units of sliding-scale regular human insulin coverage. Which would be best to suggest for optimal glycemic control?", "context": "", "options": [{"key": "A", "text": "Increase regular insulin to 30 units/day.", "sourceKey": "A"}, {"key": "B", "text": "Decrease dextrose to 100 g/day.", "sourceKey": "B"}, {"key": "C", "text": "Increase regular insulin to 50 units/day.", "sourceKey": "C"}, {"key": "D", "text": "Do not change the current regimen.", "sourceKey": "D"}], "answer": "A", "explanation": "Because the target BG should be within 140–180 mg/dL for this surgical patient being transferred to the floor, a modest improvement in glycemic control is indicated. Thus, answer D (no change) would be incorrect. Ideally, obligatory glucose requirements should be met (e.g., about 130 g/day plus about 80–150 g/day for wound healing) to prevent the use of amino acids for gluconeogenesis. Thus, decreasing the glucose intake to 100 g/ day as described in answer B is not desirable, given the mild increases in BG concentration. The easiest method to achieve glycemic control and meet caloric needs is to modestly increase the regular human insulin content in the PN solution. Because 14 units of sliding scale insulin still appears insufficient, a modest increase in insulin appears prudent. The patient is unlikely to experience hypoglycemia with the provision of insulin at 30 units/ day when given 200 g of intravenous dextrose concurrently (Answer A is correct). As the stress resolves and glycemic control improves, insulin can be decreased or eliminated from the PN solution. Answer C is incorrect because it would likely provide too much insulin, based on sliding scale coverage and current BG range, and increase the patient’s risk for hypoglycemia.", "page": 47, "answerPage": 59, "stemZh": "55 歲女性，75 kg，無 diabetes，重大 GI resection 後使用 PN，已脫離 mechanical ventilation，將由 ICU 轉病房。PN：dextrose 200 g（1.8 mg/kg/minute）、amino acids 110 g、lipids 80 g（1.1 g/kg/day），達 26 kcal/kg/day、protein 1.5 g/kg/day；含 regular human insulin 20 units/day。24 hours 指尖 BG 170–210 mg/dL、serum glucose 182 mg/dL，另給 sliding-scale regular human insulin 14 units。最佳 glycemic control 建議為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Regular insulin 增至 30 units/day。"}, {"key": "B", "text": "Dextrose 降至 100 g/day。"}, {"key": "C", "text": "Regular insulin 增至 50 units/day。"}, {"key": "D", "text": "維持原方案。"}], "explanationZh": "BG 目標 140–180 mg/dL，需適度改善。將 PN regular human insulin 增至 30 units/day 較合理，待 stress 緩解再降低。Dextrose 100 g/day 不足以兼顧基本 glucose 與 wound healing 需求；50 units/day 可能增加 hypoglycemia，維持不變則未達目標。"}, {"id": "04-self-01", "chapter": 4, "type": "self", "number": 1, "stem": "As the clinical coordinator/manager, you have received a request to add the critical care pharmacist’s review of all intensive care unit (ICU) patients. You recognize that you lack the necessary personnel to accomplish this request. Which justification method would offer the most significant financial impact on the institution to justify the position?", "context": "", "options": [{"key": "A", "text": "Developing protocols in the critically ill patient.", "sourceKey": "A"}, {"key": "B", "text": "Reducing prescribing errors.", "sourceKey": "B"}, {"key": "C", "text": "Reducing medication administration errors.", "sourceKey": "C"}, {"key": "D", "text": "Implementation of an anticoagulation reversal stewardship program.", "sourceKey": "D"}], "answer": "D", "explanation": "Financial justification for a critical care pharmacist has been shown by the impact of clinical pharmacists on critically ill patients. The critical care pharmacist can reduce adverse events in the critically ill population, reduce order prescribing errors, optimize the correct drug for the correct disease process, decrease the LOS, reduce medication administration errors, and reduce inappropriate antibiotic use. One of the main financial impacts on critically ill patients is antimicrobial therapy. Using an anticoagulation reversal stewardship program will most affect the institution (Answer D is correct). Developing protocols is important in streamlining practice in the critically ill population and can reduce health care costs, and prescribing errors and medication administration errors can result in adverse events to the patient, but none of these would have the most significant effect on finances (Answers A, B, and C are incorrect).", "page": 4, "answerPage": 43, "stemZh": "你是 clinical coordinator／manager，收到要求，讓 critical care pharmacist 評估所有 ICU 病人，但目前人力不足。哪種人力增補論證方式對機構財務影響最大？", "contextZh": "", "optionsZh": [{"key": "A", "text": "為 critically ill patients 建立 protocols。"}, {"key": "B", "text": "減少 prescribing errors。"}, {"key": "C", "text": "減少 medication administration errors。"}, {"key": "D", "text": "推行 anticoagulation reversal stewardship program。"}], "explanationZh": "依原章節，anticoagulation reversal stewardship program 的財務影響最大。藥師亦能降低 adverse events、prescribing／administration errors、住院天數與不當 antibiotic 使用；建立 protocols 也有價值，但本題其他選項的財務影響不如 D。"}, {"id": "04-self-02", "chapter": 4, "type": "self", "number": 2, "stem": "You are the critical care pharmacist implementing a delirium screening tool in critically ill patients according to the Society of Critical Care Medicine guidelines. Which would best be described as a practice environment barrier to implementing delirium screening in your ICU?", "context": "", "options": [{"key": "A", "text": "The nursing standard work does not include delirium screening.", "sourceKey": "A"}, {"key": "B", "text": "Screening process takes up valuable nursing time.", "sourceKey": "B"}, {"key": "C", "text": "Providers are unfamiliar with how to perform delirium screening.", "sourceKey": "C"}, {"key": "D", "text": "Providers believe their knowledge of bedside delirium is adequate and does not require a screening tool.", "sourceKey": "D"}], "answer": "B", "explanation": "Practice environment constraints include financial disincentives (not enough staff to support delirium screening), organizational constraints (screening process takes up valuable nursing time), perception of liability (if the screen is conducted and the test is positive, the provider will be blamed), and patient expectations (Answer B is correct). Another barrier to implementing delirium screening includes the key stakeholders’ standard or routine work of the process, which is based on opinion, not evidence (Answer A is incorrect). A third barrier involves the professional context and includes clinical uncertainty. Practitioners may believe they have adequate skills to act. In addition, information overload occurs with the vast amount of literature being published. An example of a knowledge barrier includes providers being unfamiliar with how to perform delirium screening (Answer C is incorrect). A fourth barrier is when the key stakeholders’ opinion does not agree with screening patients for delirium because of changes in evidence-based medicine and possible knowledge gaps (Answer D is incorrect).", "page": 4, "answerPage": 43, "stemZh": "你依 SCCM guidelines 在 ICU 推行 delirium screening tool。哪一項最符合 practice environment barrier？", "contextZh": "", "optionsZh": [{"key": "A", "text": "護理標準工作流程未含 delirium screening。"}, {"key": "B", "text": "Screening 過程占用寶貴 nursing time。"}, {"key": "C", "text": "照護者不熟悉如何做 delirium screening。"}, {"key": "D", "text": "照護者認為其 bedside delirium 知識足夠，不需 screening tool。"}], "explanationZh": "Screening 占用 nursing time 屬於組織及 practice environment 限制。A 關乎 routine work；C 為知識障礙；D 是 stakeholders 觀點與 evidence 或知識落差。"}, {"id": "04-self-03", "chapter": 4, "type": "self", "number": 3, "stem": "The pharmacy and therapeutics (P&T) committee would like to evaluate the use of pharmacotherapy in stress ulcer prophylaxis (SUP) in the ICU. Which is the best method for making this evaluation?", "context": "", "options": [{"key": "A", "text": "Perform a medication use evaluation (MUE).", "sourceKey": "A"}, {"key": "B", "text": "Administer a performance improvement (PI) initiative.", "sourceKey": "B"}, {"key": "C", "text": "Review adverse drug event (ADE) data from the ICU.", "sourceKey": "C"}, {"key": "D", "text": "Review medication error data from the ICU.", "sourceKey": "D"}], "answer": "A", "explanation": "Evaluating the use of pharmacotherapy in SUP in the ICU is best suited for an MUE (Answer A is correct). The goal of an MUE is to ensure optimal medication therapy management and improve patient safety and outcomes for drug-related processes—in this case, pharmacotherapy in SUP. Although one component of an MUE is PI, a review of the quality should occur before determining whether a PI project is necessary (Answer B is incorrect). An interventional MUE incorporates a review of quality in the form of making a pharmacotherapeutic intervention—PI. Although reviewing ADE data and medication error data from the ICU is helpful in detecting and determining problems associated with the use of pharmacotherapy in SUP, these are isolated events and are reporterdependent, and a lack of reports does not ensure that the use of pharmacotherapy in SUP is appropriate (Answers C and D are incorrect). Only an MUE is a robust and comprehensive method of evaluating the use of pharmacotherapy in SUP.", "page": 4, "answerPage": 43, "stemZh": "Pharmacy and therapeutics（P&T）committee 欲評估 ICU 的 stress ulcer prophylaxis（SUP）pharmacotherapy。最佳方法為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "進行 medication use evaluation（MUE）。"}, {"key": "B", "text": "直接推行 performance improvement（PI）計畫。"}, {"key": "C", "text": "檢視 ICU adverse drug event（ADE）資料。"}, {"key": "D", "text": "檢視 ICU medication error 資料。"}], "explanationZh": "MUE 可全面評估用藥管理、病人安全與結果，適合 SUP。需先評估品質，再決定 PI；ADE／error 報告屬孤立且依賴通報事件，沒有報告並不代表用藥適當。"}, {"id": "04-self-04", "chapter": 4, "type": "self", "number": 4, "stem": "Which medication use process is best suited for an MUE?", "context": "", "options": [{"key": "A", "text": "Pharmacist verification times for routine orders in the ICU.", "sourceKey": "A"}, {"key": "B", "text": "Management of warfarin-induced hypoprothrombinemia.", "sourceKey": "B"}, {"key": "C", "text": "Drug interaction warnings on the computerized provider order entry (CPOE) system.", "sourceKey": "C"}, {"key": "D", "text": "Duplicate warnings on the CPOE system.", "sourceKey": "D"}], "answer": "B", "explanation": "Evaluating the management of warfarin-induced hypoprothrombinemia is best suited for an MUE. The goal of an MUE is to ensure optimal medication therapy management and improve patient safety and outcomes for drug-related processes; an MUE is drug-, drug class–, or disease-specific—in this case, management of warfarin-induced hypoprothrombinemia (Answer B is correct). Quality assurance is a process for monitoring the effectiveness and safety of the medication use process that includes prescribing, dispensing, and administering medications. Evaluating pharmacist verification times for routine orders in the ICU, drug interaction warnings on the CPOE system, and duplicate warnings on the CPOE system is not necessarily drug- or disease state–specific and is best suited for a QA review (Answers A, C, and D are incorrect).", "page": 5, "answerPage": 43, "stemZh": "哪個 medication use process 最適合 MUE？", "contextZh": "", "optionsZh": [{"key": "A", "text": "ICU routine orders 的 pharmacist verification time。"}, {"key": "B", "text": "Warfarin-induced hypoprothrombinemia 的處置。"}, {"key": "C", "text": "CPOE 的 drug interaction warnings。"}, {"key": "D", "text": "CPOE 的 duplicate warnings。"}], "explanationZh": "MUE 以特定 drug、drug class 或 disease 為焦點，因此 warfarin-induced hypoprothrombinemia 最適合。其他流程較屬廣泛 medication use process 的 quality assurance（QA）。"}, {"id": "04-self-05", "chapter": 4, "type": "self", "number": 5, "stem": "You have been asked to develop a quality improvement (QI) strategy for your ICU regarding when to institute targeted temperature management in patients after cardiac arrest. The current process has been defined, and best practices for targeted temperature management have been outlined. You identify key stakeholders in this patient population to collaborate with you in this process improvement. Which is the next best step in developing the QI program?", "context": "", "options": [{"key": "A", "text": "Determine which patients with cardiac arrest should receive targeted temperature management.", "sourceKey": "A"}, {"key": "B", "text": "Evaluate the current clinical guidelines associated with targeted temperature management.", "sourceKey": "B"}, {"key": "C", "text": "Determine the current process of targeted temperature management.", "sourceKey": "C"}, {"key": "D", "text": "Evaluate the data associated with patients receiving targeted temperature management.", "sourceKey": "D"}], "answer": "A", "explanation": "The next best step is determining which patients with cardiac arrest should receive targeted temperature management. (Answer A is correct). Best practices have already been identified, so additional literature evaluation is not needed. (Answer B is incorrect). Finally, data will be collected on the current process of managing targeted temperature management (Answer D is incorrect), which will be evaluated to determine the areas for improvement in the outcome desired. The current process has already been determined, as provided in the question (Answer C is incorrect).", "page": 5, "answerPage": 43, "stemZh": "你要建立 ICU cardiac arrest 後何時啟動 targeted temperature management 的 QI 策略。已界定現有流程、整理 best practices，並邀請 key stakeholders 合作。下一個最佳步驟為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "確定哪些 cardiac arrest 病人應接受 targeted temperature management。"}, {"key": "B", "text": "評估相關現行 clinical guidelines。"}, {"key": "C", "text": "確定現行 targeted temperature management 流程。"}, {"key": "D", "text": "評估接受 targeted temperature management 病人的資料。"}], "explanationZh": "下一步是確定適用病人。Best practices 與現行流程均已確定，不必重做；之後才收集並評估現行流程資料，以找出改善空間。"}, {"id": "04-self-06", "chapter": 4, "type": "self", "number": 6, "stem": "You obtain data related to time to administration of immediate antibiotics for sepsis from your CPOE system in order to determine a baseline metric for quality improvement. Using the define, measure, analyze, improve, control (DMAIC) method, which step describes the process phase to determine the baseline time to antibiotics?", "context": "", "options": [{"key": "A", "text": "Data are collected.", "sourceKey": "A"}, {"key": "B", "text": "Methods are established.", "sourceKey": "B"}, {"key": "C", "text": "Change process is implemented.", "sourceKey": "C"}, {"key": "D", "text": "Data are analyzed.", "sourceKey": "D"}], "answer": "D", "explanation": "Because the data have already been collected, they must be analyzed to determine the baseline time to antibiotics (Answer D is correct). The measuring phase includes collecting the data, which has already been completed (Answer A is incorrect). Establishing methods is part of the design (Answer B is incorrect). The change process being implemented is the improvement phase (Answer C is incorrect).", "page": 5, "answerPage": 44, "stemZh": "你已從 CPOE 取得 sepsis 立即 antibiotics 給藥時間資料，欲建立 QI baseline metric。依 define、measure、analyze、improve、control（DMAIC），確定 baseline time to antibiotics 屬於哪個階段？", "contextZh": "", "optionsZh": [{"key": "A", "text": "收集資料。"}, {"key": "B", "text": "建立方法。"}, {"key": "C", "text": "實施流程變更。"}, {"key": "D", "text": "分析資料。"}], "explanationZh": "資料已收集，接著須分析才能確定 baseline，屬 analyze。收集是 measure；建立方法屬設計；實施改變屬 improve。"}, {"id": "04-self-07", "chapter": 4, "type": "self", "number": 7, "stem": "Which metric best quantifies a critical care pharmacist’s activities?", "context": "", "options": [{"key": "A", "text": "Weighing each variable to quantify measured activities.", "sourceKey": "A"}, {"key": "B", "text": "Number of cardiac arrest codes attended each month.", "sourceKey": "B"}, {"key": "C", "text": "Number and severity of hospital-acquired Clostridioides difficile infections each year.", "sourceKey": "C"}, {"key": "D", "text": "Number of in-services provided each year.", "sourceKey": "D"}], "answer": "A", "explanation": "Using weighted metrics for each critical care pharmacist activity – quantified over time and annualized – more accurately quantifies a critical care pharmacist’s activities (Answer A is correct). The number of cardiac arrest codes attended each month, number and severity of hospital-acquired Clostridioides difficile infections each year, and the number of in-services provided each year are important, but do not quantify a comprehensive list of a critical care pharmacist’s activities individually (Answers B, C, and D are incorrect).", "page": 5, "answerPage": 44, "stemZh": "哪種 metric 最能量化 critical care pharmacist 的活動？", "contextZh": "", "optionsZh": [{"key": "A", "text": "對各變項加權，量化測量的活動。"}, {"key": "B", "text": "每月參與 cardiac arrest codes 的次數。"}, {"key": "C", "text": "每年 hospital-acquired Clostridioides difficile infections 的數量與嚴重度。"}, {"key": "D", "text": "每年提供 in-services 的次數。"}], "explanationZh": "對各活動使用 weighted metrics，隨時間量化並年化，較能全面反映工作。單獨計算急救、感染或教學次數，無法呈現所有活動。"}, {"id": "04-self-08", "chapter": 4, "type": "self", "number": 8, "stem": "As the clinical pharmacist in the ICU, you are asked to evaluate the quality initiatives specific to critically ill patients. Which best describes a Centers for Medicare & Medicaid Services (CMS) quality metric?", "context": "", "options": [{"key": "A", "text": "Sepsis management bundle and venous thromboembolism prophylaxis.", "sourceKey": "A"}, {"key": "B", "text": "Thrombolytic therapy for stroke and SUP.", "sourceKey": "B"}, {"key": "C", "text": "Heart failure readmission and pneumonia vaccination rates.", "sourceKey": "C"}, {"key": "D", "text": "Ventilator bundles and acute coronary syndrome readmission rates.", "sourceKey": "D"}], "answer": "A", "explanation": "Sepsis management bundle and VTE prophylaxis are quality measures reported to CMS (Answer A is correct). Thrombolytic therapy for patients with stroke is correct, but stress ulcer prophylaxis is not reported (Answer B is incorrect). Heart failure readmissions are reported, but pneumonia vaccination rates are not (Answer C is incorrect). Use of ventilator bundles is not reported, but rates of acute coronary syndrome readmission are reported (Answer D is incorrect). Exert from Source: Centers for Disease Control and Prevention (CDC). The Core Elements of Hospital Antibiotic Stewardship Programs: Antibiotic Stewardship Program Assessment Tool. Reference to specific commercial products, manufacturers, companies, or trademarks does not constitute its endorsement or recommendation by the U.S. Government, Department of Health and Human Services, or Centers for Disease Control and Prevention. Available at the following website at no charge. https://www.cdc. gov/antibiotic-use/healthcare/pdfs/assessment-tool-P.pdf.", "page": 5, "answerPage": 44, "stemZh": "你要評估 critically ill patients 的品質計畫。哪組符合 Centers for Medicare & Medicaid Services（CMS）quality metrics？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Sepsis management bundle 與 venous thromboembolism prophylaxis。"}, {"key": "B", "text": "Stroke thrombolytic therapy 與 SUP。"}, {"key": "C", "text": "Heart failure readmission 與 pneumonia vaccination rates。"}, {"key": "D", "text": "Ventilator bundles 與 acute coronary syndrome readmission rates。"}], "explanationZh": "依 2024 原章節，sepsis management bundle 與 VTE prophylaxis 均為向 CMS 報告的措施。其他配對中，stroke thrombolysis、heart failure readmission 與 acute coronary syndrome readmission 有報告，而 SUP、pneumonia vaccination rates、ventilator bundles 並非題述指標。"}, {"id": "04-case-01", "chapter": 4, "type": "case", "number": 1, "stem": "As the critical care pharmacist, you have been asked to develop a guideline for reversal agents used in the setting of bleeding associated with anticoagulation therapy. Which is the best example of a component that should be involved in establishing the clinical pathway?", "context": "", "options": [{"key": "A", "text": "Evaluate the closed-loop technology to support a clinical pathway, and establish a physician champion.", "sourceKey": "A"}, {"key": "B", "text": "Use EBM to support the clinical pathway and develop agreement among practitioners.", "sourceKey": "B"}, {"key": "C", "text": "Develop a clinical protocol, and obtain agreement among practitioners.", "sourceKey": "C"}, {"key": "D", "text": "Evaluate formulary proposals and the EBM supporting the clinical practice.", "sourceKey": "D"}], "answer": "B", "explanation": "Using evidence-based practice helps provide support in creating a clinical pathway with support and agreement among practitioners (Answer B is correct). Using closedloop technology is important when implementing a clinical pathway, as is establishing a physician champion (Answer A). Developing a clinical protocol and pathway comes after the evidence is evaluated (Answer C). Formulary proposals are not a primary factor in implementing a clinical pathway (Answer D).", "page": 11, "answerPage": 41, "stemZh": "你要為 anticoagulation 相關出血建立 reversal agents guideline。建立 clinical pathway 應包含哪項要素？", "contextZh": "", "optionsZh": [{"key": "A", "text": "評估支援 pathway 的 closed-loop technology，並建立 physician champion。"}, {"key": "B", "text": "以 evidence-based medicine（EBM）支持 pathway，並取得 practitioners 共識。"}, {"key": "C", "text": "建立 clinical protocol，並取得 practitioners 共識。"}, {"key": "D", "text": "評估 formulary proposals 與支援 clinical practice 的 EBM。"}], "explanationZh": "先以 evidence 支持 pathway 並取得共識。Closed-loop technology／physician champion 對實施重要；clinical protocol 應在 evidence 評估後建立；formulary proposal 並非主要因素。"}, {"id": "04-case-02", "chapter": 4, "type": "case", "number": 2, "stem": "Neuromuscular blocking agents are high alert medications and have led to significant medication errors and patient harm. You noticed at your new job in the medical ICU when you went to pull rocuronium from the automated dispensing cabinet that there were no warnings on the pyxis, and it was in an open cubie pocket. You recalled ISMP having safety alerts and even a best practice regarding the safe storage and handling of neuromuscular blocking agents. Which is the best example of how to conduct a gap analysis?", "context": "", "options": [{"key": "A", "text": "Conduct a survey of other institutions to see how they are handling the storage of NMBs and compare with practice at your new institution.", "sourceKey": "A"}, {"key": "B", "text": "Recommend implementation of storage solutions based on what your previous institution did.", "sourceKey": "B"}, {"key": "C", "text": "Create a table of the ISMP best practice recommendations for the safe storage and handling of NMBs and compare with the current practice at your new institution.", "sourceKey": "C"}, {"key": "D", "text": "Survey the staff as to what they think the safest storage would be while still being convenient to obtain.", "sourceKey": "D"}], "answer": "C", "explanation": "A gap analysis compares best practice and current state to identify opportunities for improvement (Answer C is correct). Creating a table of the ISMP best practice recommendations regarding storage and handling of NMBs and comparing them with current practice would be the best way to identify opportunity to improve. A survey could be helpful to learn what other institutions are doing, but it does not ensure they are in line with best practices. It could provide additional information but would not show where gaps exist in current state and best practice at your institution (Answer A is incorrect). Answer B is incorrect because it is jumping right to solutions without completing the gap analysis. Answer D is also incorrect because surveying the staff would not provide information on the best practice gaps that exist.", "page": 13, "answerPage": 41, "stemZh": "Neuromuscular blocking agents 是 high-alert medications。你在新任職 medical ICU 從 automated dispensing cabinet 取 rocuronium，發現 Pyxis 無警示，且藥品位於開放 cubie pocket。ISMP 已有安全儲存與處理建議。哪種 gap analysis 最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "調查其他醫院如何儲存 NMB，再與現院比較。"}, {"key": "B", "text": "依前任職醫院做法直接建議儲存方案。"}, {"key": "C", "text": "將 ISMP 的 NMB 安全儲存及處理 best practices 製成表，與現院實務比較。"}, {"key": "D", "text": "詢問員工認為何種儲存最安全且易取得。"}], "explanationZh": "Gap analysis 比較 best practice 與 current state，找出改善空間，故 C 最適合。其他醫院做法未必符合標準；直接提出方案跳過分析；員工意見無法確定實務與標準的差距。"}, {"id": "04-case-03", "chapter": 4, "type": "case", "number": 3, "stem": "You are reviewing compliance with the national patient safety goals in the perioperative setting specific to appropriate medication labeling. Through observation, you notice that there are inconsistencies in how propofol is drawn up and labled in the syringe, if labeled at all. In the majority of cases, the name of the drug is placed on the label. What other information should be included on the label of the syringe?", "context": "", "options": [{"key": "A", "text": "Patient name, drug name, dose, and expiration date/time.", "sourceKey": "A"}, {"key": "B", "text": "Drug name, concentration, diluent if applicable, and expiration date/time.", "sourceKey": "B"}, {"key": "C", "text": "Patient name, drug name, drug dose, and concentration.", "sourceKey": "C"}, {"key": "D", "text": "Drug name, drug dose, concentration, and diluent if applicable.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer A is incorrect because the patient name and dose do not need to be on the label per the NPSG requirements. Both drug name and expiration date/ time should be. Answer B is correct because all of these must be on the label of a medication drawn up in the perioperative setting. Answer C is incorrect because the patient name and drug dose are not needed on the label but drug name and concentration do. Answer D is incorrect because drug dose does not need to be on the label.", "page": 20, "answerPage": 41, "stemZh": "你評估 perioperative setting 的 national patient safety goals medication labeling。觀察 propofol 抽取及 syringe 標示不一致，有時未標示；多數只寫 drug name。Syringe label 還應包含什麼資訊？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Patient name、drug name、dose、expiration date/time。"}, {"key": "B", "text": "Drug name、concentration、適用時的 diluent、expiration date/time。"}, {"key": "C", "text": "Patient name、drug name、drug dose、concentration。"}, {"key": "D", "text": "Drug name、drug dose、concentration、適用時的 diluent。"}], "explanationZh": "Perioperative medication syringe label 應包含 drug name、concentration、適用的 diluent 與 expiration date/time。依題述 NPSG 要求，patient name 與 dose 不是必要標示項目。"}, {"id": "04-case-04", "chapter": 4, "type": "case", "number": 4, "stem": "As a critical care pharmacist, you are involved in a QI program. Which TJC measure is best known to be affected by the critical care pharmacist?", "context": "", "options": [{"key": "A", "text": "ED median time from ED arrival to ED departure for admitted ED patients.", "sourceKey": "A"}, {"key": "B", "text": "Procoagulant reversal agent initiation for intracerebral hemorrhage (ICH).", "sourceKey": "B"}, {"key": "C", "text": "Hemorrhagic transformation for patients receiving intravenous alteplase therapy or mechanical endovascular reperfusion therapy.", "sourceKey": "C"}, {"key": "D", "text": "Severe sepsis and septic shock management bundle.", "sourceKey": "D"}], "answer": "B", "explanation": "Current data show that the critical care pharmacist affects many areas associated with TJC measures. According to TJC’s current measures, the critical care pharmacist affects procoagulant reversal agent initiation for ICH (Answer B is correct). The ED median time from ED arrival to ED departure for admitted ED patients is not affected by the pharmacist (Answer A is incorrect). Hemorrhage transformation for patients treated with intravenous alteplase therapy or mechanical endovascular reperfusion therapy is also not affected by the pharmacist (Answer C is incorrect). Although the pharmacist would have impact on the severe sepsis and septic shock management bundle, this is not currently a required measurement (Answer D is incorrect).", "page": 26, "answerPage": 41, "stemZh": "你參與 QI program。哪個 TJC measure 最已知可受 critical care pharmacist 影響？", "contextZh": "", "optionsZh": [{"key": "A", "text": "住院急診病人從 ED arrival 至 ED departure 的 median time。"}, {"key": "B", "text": "Intracerebral hemorrhage（ICH）的 procoagulant reversal agent 啟動。"}, {"key": "C", "text": "IV alteplase 或 mechanical endovascular reperfusion therapy 後的 hemorrhagic transformation。"}, {"key": "D", "text": "Severe sepsis 與 septic shock management bundle。"}], "explanationZh": "依原章節 TJC measures，critical care pharmacist 已證實影響 ICH procoagulant reversal agent 啟動。未證實影響 A／C；藥師雖可影響 sepsis bundle，但原文指出其當時並非此項必需測量。"}, {"id": "04-case-05", "chapter": 4, "type": "case", "number": 5, "stem": "As part of a QI initiative, you identify an increase in the monthly rate of catheter-related bloodstream infections in your ICU. You decide to evaluate the current practice using LEAN methodology. Which is the best example of a component of LEAN?", "context": "", "options": [{"key": "A", "text": "Define the problem.", "sourceKey": "A"}, {"key": "B", "text": "Ask your nurses why they think a spike in catheter-related bloodstream infections has occurred.", "sourceKey": "B"}, {"key": "C", "text": "Identify transportation barriers.", "sourceKey": "C"}, {"key": "D", "text": "Describe the past process.", "sourceKey": "D"}], "answer": "A", "explanation": "Defining the problem is the first step in LEAN (Answer A is correct). The LEAN strategy involves attempting to remove the team members’ opinions so their emotions do not influence the process. Hence, asking the nurses their opinion for the spike in catheter-related bloodstream infections influences their emotions (Answer B is incorrect). Identifying operational barriers is a LEAN process, however a transportation barrier is not related to catheter related blood stream infections (Answer C is incorrect). Describing the past process is not a LEAN evaluation component (Answer D is incorrect).", "page": 26, "answerPage": 41, "stemZh": "ICU 每月 catheter-related bloodstream infections 增加，你用 LEAN 評估現行實務。哪項最符合 LEAN 要素？", "contextZh": "", "optionsZh": [{"key": "A", "text": "界定問題。"}, {"key": "B", "text": "問 nurses 為何認為感染激增。"}, {"key": "C", "text": "辨識 transportation barriers。"}, {"key": "D", "text": "描述過去流程。"}], "explanationZh": "LEAN 第一個步驟為 define the problem。應避免主觀意見與情緒影響分析；transportation barrier 與此感染問題無直接關聯；描述過去流程並非本題所問的評估要素。"}, {"id": "04-case-06", "chapter": 4, "type": "case", "number": 6, "stem": "Which medication use process is best suited for an MUE?", "context": "", "options": [{"key": "A", "text": "Review of pharmacist notes in the electronic health record (EHR).", "sourceKey": "A"}, {"key": "B", "text": "Review of accuracy of expiration dates placed on intravenous admixture products.", "sourceKey": "B"}, {"key": "C", "text": "Review of vancomycin dosing and ordering of vancomycin blood concentrations.", "sourceKey": "C"}, {"key": "D", "text": "Review of frequency of drug interaction warnings on the CPOE system.", "sourceKey": "D"}], "answer": "C", "explanation": "An MUE is drug- or disease-specific and is best suited for reviewing vancomycin dosing and the ordering of vancomycin blood concentrations (Answer C is correct). Quality assurance surveys are best suited for monitoring the medication use process that may not be specific to a drug or disease, such as the review of a pharmacist’s notes in the EHR, review of the accuracy of expiration dates placed on intravenous admixture products, and review of the frequency of drug interaction warnings on the CPOE system (Answers A, B, and D are incorrect).", "page": 30, "answerPage": 41, "stemZh": "哪個 medication use process 最適合 MUE？", "contextZh": "", "optionsZh": [{"key": "A", "text": "檢視 EHR 中的 pharmacist notes。"}, {"key": "B", "text": "檢視 IV admixture products expiration dates 標示準確性。"}, {"key": "C", "text": "檢視 vancomycin dosing 與 vancomycin blood concentrations 檢驗醫囑。"}, {"key": "D", "text": "檢視 CPOE drug interaction warnings 的頻率。"}], "explanationZh": "MUE 專注特定 drug 或 disease，適合 vancomycin dosing／concentration monitoring。其他非藥物或疾病特定的用藥流程較適合 QA review。"}, {"id": "04-case-07", "chapter": 4, "type": "case", "number": 7, "stem": "You round daily in your ICU as part of the multidisciplinary team. Your manager asks you to help them justify clinical pharmacy services to obtain additional FTEs for the other ICUs at your institution. Which of the following would be the most effective metrics to include in the justification to hospital leadership?", "context": "", "options": [{"key": "A", "text": "Antibiotic stewardship and cost savings.", "sourceKey": "A"}, {"key": "B", "text": "Provider education and in-services provided.", "sourceKey": "B"}, {"key": "C", "text": "Time spent rounding and on other activities.", "sourceKey": "C"}, {"key": "D", "text": "Renal dose adjustments and intravenous to oral conversion.", "sourceKey": "D"}], "answer": "A", "explanation": "Justification to hospital leadership should provide financial benefit to the organization as well as improvement in patient outcomes and safety. Antibiotic stewardship outcomes as well as cost savings would provide both of these above and help justify additional pharmacy FTEs (Answer A is correct). Although provider education and in-services can be of benefit, it is difficult to justify these with cost savings or outcome benefits (Answer B is incorrect). Although many clinical pharmacists spend time on rounds, this time is not value added without interventions and cost savings metrics associated with it (Answer c is incorrect). While renal dose adjustments and intravenous to oral conversion are interventions clinical pharmacists frequently make, they do not provide measurable metrics unless associated with a cost savings and safety benefit (Answer D is incorrect).", "page": 32, "answerPage": 41, "stemZh": "你每日參與 ICU multidisciplinary rounds，主管要你向醫院管理層論證 clinical pharmacy services，以增補其他 ICU 的 FTEs。最有效的 metrics 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Antibiotic stewardship 與 cost savings。"}, {"key": "B", "text": "Provider education 與 in-services 次數。"}, {"key": "C", "text": "查房及其他活動耗時。"}, {"key": "D", "text": "Renal dose adjustments 與 IV-to-oral conversion。"}], "explanationZh": "論證需同時呈現財務效益、病人結果及安全改善；antibiotic stewardship 與 cost savings 可提供這些證據。教學、耗時或介入次數本身，若未連結 measurable cost／safety／outcome benefit，說服力較有限。"}, {"id": "04-case-08", "chapter": 4, "type": "case", "number": 8, "stem": "During ICU rounds, the team is recommending a cost-prohibitive non-formulary drug with controversial outcomes as a last line vasopressor for a patient with septic shock. You review the chart and think there are safer formulary options to try before resorting to this new therapy. You are required to document your interventions in the patient chart for tracking purposes. Which wording is the most appropriate to use?", "context": "", "options": [{"key": "A", "text": "Because of the significant cost of this drug, the team should resort to other formulary options.", "sourceKey": "A"}, {"key": "B", "text": "This drug was associated with significant adverse effects in clinical trials and will likely cause harm if used in this patient.", "sourceKey": "B"}, {"key": "C", "text": "The team should consider optimizing the patient’s pharmacological therapy with agents that are on formulary and have a proven benefit in patients with septic shock.", "sourceKey": "C"}, {"key": "D", "text": "The use of this non-formulary drug would be a poor choice and likely lead to patient harm if used.", "sourceKey": "D"}], "answer": "C", "explanation": "Answer A is incorrect because it solely focuses on cost with little rationale on how this might impact the patient clinically. Answer B is incorrect because it is worded such that it is implying harm will result if the provider does not take the recommendation. Answer C is correct because it is worded that the provider should consider the recommendation as well as the rationale as to why. Answer D is incorrect because it is focusing on the fact that it is non-formulary and would likely cause harm if the provider does not take the recommendation.", "page": 34, "answerPage": 42, "stemZh": "ICU 團隊建議 septic shock 病人使用高價、non-formulary、結果具爭議的新藥作最後線 vasopressor。你認為應先嘗試較安全的 formulary options，且須在 chart 紀錄介入。哪個措辭最適當？", "contextZh": "", "optionsZh": [{"key": "A", "text": "因藥價昂貴，團隊應改用其他 formulary options。"}, {"key": "B", "text": "Clinical trials 顯示嚴重 adverse effects，此病人使用後很可能受傷害。"}, {"key": "C", "text": "團隊可考慮以 formulary 內且已證實對 septic shock 有益的 agents，最佳化病人的 pharmacological therapy。"}, {"key": "D", "text": "使用此 non-formulary 藥是差的選擇，很可能導致傷害。"}], "explanationZh": "C 以建議方式提出，並提供 clinical rationale。A 只聚焦成本；B／D 暗示不接受建議就會造成傷害，措辭不適當。"}, {"id": "05-self-01", "chapter": 5, "type": "self", "number": 1, "stem": "Which best describes the type of cost this medication would have?", "context": "Your institution wants to evaluate the addition of coagulation factor Xa (recombinant), inactivated-zhzo to your formulary for reversal of direct oral anticoagulants.", "options": [{"key": "A", "text": "Fixed medical.", "sourceKey": "A"}, {"key": "B", "text": "Variable medical.", "sourceKey": "B"}, {"key": "C", "text": "Indirect.", "sourceKey": "C"}, {"key": "D", "text": "Incremental.", "sourceKey": "D"}], "answer": "B", "explanation": "The cost of a medication would be considered a variable medical cost (Answer B is correct). The cost of the lights in the clean room would be considered a fixed medical cost (Answer A is incorrect). The time resulting in loss of work for a patient requiring this medication would be considered an indirect cost (Answer C is incorrect). Additional use of blood products after administration of this medication would be considered an incremental cost (Answer D is incorrect).", "page": 4, "answerPage": 31, "stemZh": "此藥物的成本最適合歸類為何？", "contextZh": "醫院欲評估將 coagulation factor Xa (recombinant), inactivated-zhzo 納入 formulary，用於 reversal of direct oral anticoagulants。", "optionsZh": [{"key": "A", "text": "Fixed medical cost。"}, {"key": "B", "text": "Variable medical cost。"}, {"key": "C", "text": "Indirect cost。"}, {"key": "D", "text": "Incremental cost。"}], "explanationZh": "藥品費用屬 variable medical cost。Clean room 照明屬 fixed medical cost；病人因病無法工作屬 indirect cost；給藥後額外使用 blood products 可屬 incremental cost。"}, {"id": "05-self-02", "chapter": 5, "type": "self", "number": 2, "stem": "Your institution wants to use pharmacoeconomic data to evaluate the impact of this medication on neurologic disability and cost compared with prothrombin complex concentrate. Which analysis would be best to find in the literature?", "context": "Your institution wants to evaluate the addition of coagulation factor Xa (recombinant), inactivated-zhzo to your formulary for reversal of direct oral anticoagulants.", "options": [{"key": "A", "text": "Cost-benefit.", "sourceKey": "A"}, {"key": "B", "text": "Cost-effectiveness.", "sourceKey": "B"}, {"key": "C", "text": "Cost-minimization.", "sourceKey": "C"}, {"key": "D", "text": "Cost-utility.", "sourceKey": "D"}], "answer": "B", "explanation": "Given the need to consider efficacy and cost, a costeffectiveness analysis would be the best type of analysis (Answer B is correct). A cost-benefit analysis would be used if your institution were purely interested in a monetary outcome (Answer A is incorrect). A cost-minimization analysis would only evaluate the difference in costs between these medications (Answer C is incorrect). A cost-utility analysis includes the patient perspective, which was not a focus of this evaluation (Answer D is incorrect).", "page": 4, "answerPage": 31, "stemZh": "醫院要用 pharmacoeconomic data 比較此藥與 prothrombin complex concentrate 對 neurologic disability 及成本的影響。最適合尋找哪種分析？", "contextZh": "醫院欲評估將 coagulation factor Xa (recombinant), inactivated-zhzo 納入 formulary，用於 reversal of direct oral anticoagulants。", "optionsZh": [{"key": "A", "text": "Cost-benefit。"}, {"key": "B", "text": "Cost-effectiveness。"}, {"key": "C", "text": "Cost-minimization。"}, {"key": "D", "text": "Cost-utility。"}], "explanationZh": "同時評估 clinical efficacy 與成本，最適合 cost-effectiveness。Cost-benefit 以金錢結果為主；cost-minimization 只比較成本；cost-utility 納入 patient perspective，並非本題重點。"}, {"id": "05-self-03", "chapter": 5, "type": "self", "number": 3, "stem": "A 60-year-old patient is admitted to the surgical ICU with a documented history of cefuroxime allergy (shortness of breath). The patient is administered ceftriaxone and develops a life-threatening anaphylactic reaction. Which best describes this patient’s reaction to ceftriaxone?", "context": "", "options": [{"key": "A", "text": "Adverse drug reaction (ADR).", "sourceKey": "A"}, {"key": "B", "text": "Side effect.", "sourceKey": "B"}, {"key": "C", "text": "Adverse drug event (ADE).", "sourceKey": "C"}, {"key": "D", "text": "Preventable ADE.", "sourceKey": "D"}], "answer": "D", "explanation": "A preventable ADE, by definition, is a medication error that occurs and reaches the patient to cause harm because of a breach of standard professional behavior or practice. The patient had a documented history of cefuroxime allergy with shortness of breath but still received ceftriaxone and developed another life-threatening anaphylactic reaction; this is a medication error, and the anaphylactic reaction is the harm. Allergy crossreactivity between cefuroxime and ceftriaxone is well documented for patients with a history of shortness of breath because of similarity in side chains; therefore, this is a preventable ADE (Answer D is correct). Although this case of ceftriaxone-induced life-threatening anaphylaxis is an ADE, a preventable ADE best describes this case (Answer C is incorrect). In general, ADRs and side effects are synonymous terms, and a ceftriaxoneinduced allergy is an ADR; however, a preventable ADE best describes this case (Answers A and B are incorrect).", "page": 4, "answerPage": 31, "stemZh": "60 歲病人入 surgical ICU，已有 cefuroxime allergy（shortness of breath）紀錄。給 ceftriaxone 後出現 life-threatening anaphylactic reaction。哪個分類最符合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Adverse drug reaction（ADR）。"}, {"key": "B", "text": "Side effect。"}, {"key": "C", "text": "Adverse drug event（ADE）。"}, {"key": "D", "text": "Preventable ADE。"}], "explanationZh": "Cefuroxime 與 ceftriaxone 因 side chain 類似而有已知 cross-reactivity。已有 allergy 紀錄仍給藥，medication error 到達病人並造成傷害，最精確分類為 preventable ADE；雖亦是 ADE／ADR，較不具體。"}, {"id": "05-self-04", "chapter": 5, "type": "self", "number": 4, "stem": "A 50-year-old patient is admitted to the neurology ICU from the medical floor for the management of an apixaban-induced cerebral hemorrhage. Which medication would best have been used as an effective tracer medication to help detect this ADE?", "context": "", "options": [{"key": "A", "text": "Coagulation factor VIIa.", "sourceKey": "A"}, {"key": "B", "text": "Phytonadione.", "sourceKey": "B"}, {"key": "C", "text": "Protamine.", "sourceKey": "C"}, {"key": "D", "text": "Prothrombin complex concentrate.", "sourceKey": "D"}], "answer": "D", "explanation": "Prothrombin complex concentrate would be the best tracer for an ADE associated with apixaban (Answer D is correct). Coagulation factor VIIa would not be effective for this indication (Answer A is incorrect). Phytonadione would be an appropriate tracer for a warfarin-induced bleeding event (Answer B is incorrect). Protamine would be an appropriate tracer for a heparin- or enoxaparininduced bleeding event (Answer C is incorrect).", "page": 4, "answerPage": 31, "stemZh": "50 歲病人因 apixaban-induced cerebral hemorrhage，從普通病房轉 neurology ICU。哪種 tracer medication 最適合協助偵測此 ADE？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Coagulation factor VIIa。"}, {"key": "B", "text": "Phytonadione。"}, {"key": "C", "text": "Protamine。"}, {"key": "D", "text": "Prothrombin complex concentrate。"}], "explanationZh": "Prothrombin complex concentrate 最適合作 apixaban 相關出血的 tracer。Phytonadione 對應 warfarin；protamine 對應 heparin／enoxaparin；factor VIIa 不適合此適應症。"}, {"id": "05-self-05", "chapter": 5, "type": "self", "number": 5, "stem": "According to the grading system of the guideline recommendations, which is the best initial recommendation to improve medication use safety, given the strength of recommendation?", "context": "As a new pharmacist in the medical ICU at your institution, you have been tasked with improving the safety of medication use in the ICU. You have read the 2017 SCCM Guidelines for Safe Medication Use in the ICU and are prepared to provide recommendations to the interdisciplinary critical care committee regarding your suggestions.", "options": [{"key": "A", "text": "Fully integrating the institution’s electronic health record (EHR) systems to improve communication.", "sourceKey": "A"}, {"key": "B", "text": "Integrating interruptive clinical decision support (CDS) into the EHR.", "sourceKey": "B"}, {"key": "C", "text": "Creating a policy requiring that intravenous medications can only be prepared by pharmacists.", "sourceKey": "C"}, {"key": "D", "text": "Investing in smart intravenous infusion pumps to reduce medication errors.", "sourceKey": "D"}], "answer": "C", "explanation": "The guidelines provide several recommendations, with only one having a strong recommendation, which is based on the dispensing of medications and streamlining them as only being from the pharmacy (Answer C is correct). The other potential answers are potential opportunities to improve medication safety but are based on weak recommendations (Answers A, B, and D are incorrect).", "page": 4, "answerPage": 31, "stemZh": "依 guideline 建議分級與 recommendation strength，最適合首先提出哪項 medication safety 改善建議？", "contextZh": "你是 medical ICU 新任藥師，負責改善 ICU medication use safety。已閱讀 2017 SCCM Guidelines for Safe Medication Use in the ICU，準備向跨專業 critical care committee 提出建議。", "optionsZh": [{"key": "A", "text": "完全整合醫院 EHR systems，改善溝通。"}, {"key": "B", "text": "在 EHR 納入 interruptive clinical decision support（CDS）。"}, {"key": "C", "text": "制定政策，規定 IV medications 只能由 pharmacists 調製。"}, {"key": "D", "text": "投資 smart IV infusion pumps 減少 medication errors。"}], "explanationZh": "依題述 2017 guideline，唯一 strong recommendation 是藥物 dispensing 標準化、由 pharmacy 提供，因此 C 最佳。其他項目也可能改善安全，但屬 weak recommendations。"}, {"id": "05-self-06", "chapter": 5, "type": "self", "number": 6, "stem": "After your institution has integrated your recommendation into routine medical care, a former patient recommends including the patient and other caregivers in reducing medication errors. According to the available literature, which best supports this recommendation?", "context": "As a new pharmacist in the medical ICU at your institution, you have been tasked with improving the safety of medication use in the ICU. You have read the 2017 SCCM Guidelines for Safe Medication Use in the ICU and are prepared to provide recommendations to the interdisciplinary critical care committee regarding your suggestions.", "options": [{"key": "A", "text": "The 2017 SCCM guidelines provide a strong recommendation for this integration into routine care.", "sourceKey": "A"}, {"key": "B", "text": "Areas in the hospital outside the ICU provide data supporting this integration.", "sourceKey": "B"}, {"key": "C", "text": "Data analyses on direct observations of interactions between the medical team and patients have shown a reduction in medical errors in the ICU.", "sourceKey": "C"}, {"key": "D", "text": "Data analyses on chart reviews of ICU patients have shown that these reported outcomes are not routinely accounted for.", "sourceKey": "D"}], "answer": "B", "explanation": "The guidelines suggest (not recommend) that patient/ caregiver-reported outcomes be integrated into routine patient care (Answer A is incorrect). Data analyses on the benefit of these interactions are limited to non-ICU environments, though the theoretical benefits listed in Answers C and D may be true (Answers C and D are incorrect; Answer B is correct).", "page": 5, "answerPage": 31, "stemZh": "醫院已將你的建議納入 routine care。前病人建議讓病人與 caregivers 參與減少 medication errors。哪項文獻證據最支持此建議？", "contextZh": "你是 medical ICU 新任藥師，負責改善 ICU medication use safety。已閱讀 2017 SCCM Guidelines for Safe Medication Use in the ICU，準備向跨專業 critical care committee 提出建議。", "optionsZh": [{"key": "A", "text": "2017 SCCM guidelines 對此納入 routine care 提出 strong recommendation。"}, {"key": "B", "text": "ICU 以外的住院環境有資料支持此做法。"}, {"key": "C", "text": "直接觀察 ICU 醫療團隊與病人的互動，已證實減少 medical errors。"}, {"key": "D", "text": "ICU chart reviews 已顯示這類 reported outcomes 未被常規記錄。"}], "explanationZh": "Guideline 是 suggest 而非 strong recommendation。益處資料主要來自 non-ICU 環境；C／D 所述可能有理論益處，但不是題述已有的 ICU 證據。"}, {"id": "05-self-07", "chapter": 5, "type": "self", "number": 7, "stem": "A 50-year-old patient was initiated on meropenem for empiric coverage of pneumonia, given prior culture data. They were subsequently initiated on valproic acid for the management of agitation; however, this was not effective for management and resulted in self-extubation and subsequent reintubation. In investigating this adverse event, which method would best evaluate the likelihood of its occurrence?", "context": "", "options": [{"key": "A", "text": "Drug interaction database.", "sourceKey": "A"}, {"key": "B", "text": "Drug interaction probability scale.", "sourceKey": "B"}, {"key": "C", "text": "Naranjo nomogram.", "sourceKey": "C"}, {"key": "D", "text": "Roussel Uclaf Causality Assessment Method (RUCAM).", "sourceKey": "D"}], "answer": "B", "explanation": "To determine the probability of a drug interaction between meropenem and valproic acid, the drug interaction probability scale should be used (Answer B is correct). A drug interaction database would provide general information and is not a patient-specific evaluation (Answer A is incorrect). The Naranjo nomogram investigates the likelihood of an ADE but is not specific to a drug interaction (Answer C is incorrect). The RUCAM evaluates the likelihood of drug-induced liver injury (Answer D is incorrect).", "page": 5, "answerPage": 31, "stemZh": "50 歲病人依先前 culture 結果，給 meropenem empiric treatment pneumonia。後用 valproic acid 處理 agitation，但效果不佳，造成 self-extubation 後再次 intubation。調查此事件時，哪種方法最適合評估發生可能性？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Drug interaction database。"}, {"key": "B", "text": "Drug interaction probability scale。"}, {"key": "C", "text": "Naranjo nomogram。"}, {"key": "D", "text": "Roussel Uclaf Causality Assessment Method（RUCAM）。"}], "explanationZh": "Drug interaction probability scale 可評估 meropenem 與 valproic acid 的病人特定 interaction 可能性。Database 提供一般資訊；Naranjo 評估 ADE 因果但非 interaction 特定；RUCAM 用於 drug-induced liver injury。"}, {"id": "05-self-08", "chapter": 5, "type": "self", "number": 8, "stem": "Your hospital wants to add meropenem/vaborbactam, a broad-spectrum antimicrobial targeting highly drug-resistant organisms that is FDA approved for complicated UTIs, to the formulary. Which would be the most appropriate restriction to its use?", "context": "", "options": [{"key": "A", "text": "Restriction to intensivist use.", "sourceKey": "A"}, {"key": "B", "text": "Restriction to patients with hospital-acquired pneumonia.", "sourceKey": "B"}, {"key": "C", "text": "Restriction to infectious diseases clinicians’ approval.", "sourceKey": "C"}, {"key": "D", "text": "Restriction to patients with appropriate cardiac monitoring.", "sourceKey": "D"}], "answer": "C", "explanation": "Broad-spectrum antimicrobials should be restricted to the appropriate clinicians with expertise in this area (Answer C is correct). Restricting use to intensivists would not be appropriate because non-ICU patients may require this agent (Answer A is incorrect). Although FDA approved only for complicated UTIs, restriction to pneumonia would not be appropriate (Answer B is incorrect). Cardiac monitoring is not required for this medication (Answer D is incorrect).", "page": 5, "answerPage": 31, "stemZh": "醫院欲納入 meropenem/vaborbactam：此 broad-spectrum antimicrobial 針對高度抗藥性菌，FDA 核准 complicated UTIs。最適合限制為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "限 intensivists 使用。"}, {"key": "B", "text": "限 hospital-acquired pneumonia 病人。"}, {"key": "C", "text": "須 infectious diseases clinicians 核可。"}, {"key": "D", "text": "限有適當 cardiac monitoring 的病人。"}], "explanationZh": "Broad-spectrum antimicrobials 宜由具該領域專業的 clinicians 核可。Non-ICU 病人亦可能需要，不宜限 intensivists；限制 pneumonia 不符合題述；此藥不需特定 cardiac monitoring。"}, {"id": "05-case-01", "chapter": 5, "type": "case", "number": 1, "stem": "A 30-year-old patient is admitted to the surgical ICU after a motor vehicle accident. Which would best exemplify an indirect cost from their perspective?", "context": "", "options": [{"key": "A", "text": "Loss of wages from occupation as an engineer.", "sourceKey": "A"}, {"key": "B", "text": "Effects of posttraumatic stress disorder from the accident.", "sourceKey": "B"}, {"key": "C", "text": "Fentanyl administered to manage pain.", "sourceKey": "C"}, {"key": "D", "text": "Cost of the ambulance that transported them to the hospital.", "sourceKey": "D"}], "answer": "A", "explanation": "Indirect costs occur from loss of employment or productivity as the result of illness (Answer A is correct). Effects from stress would be considered an intangible cost (Answer B is incorrect). Costs from fentanyl and transportation would be considered direct costs (Answers C and D are incorrect).", "page": 10, "answerPage": 29, "stemZh": "30 歲病人車禍後入 surgical ICU。從病人觀點，哪項最符合 indirect cost？", "contextZh": "", "optionsZh": [{"key": "A", "text": "因無法從事 engineer 工作而損失工資。"}, {"key": "B", "text": "車禍所致 posttraumatic stress disorder 的影響。"}, {"key": "C", "text": "止痛使用 fentanyl 的費用。"}, {"key": "D", "text": "送至醫院的 ambulance 費用。"}], "explanationZh": "Indirect cost 是疾病造成就業或生產力損失。Stress 影響屬 intangible cost；藥品與運輸費為 direct costs。"}, {"id": "05-case-02", "chapter": 5, "type": "case", "number": 2, "stem": "Which best classifies the degree of severity of an ADE in a patient who develops enalapril-induced asymptomatic hyperkalemia with no noted ECG changes (K 5.7 mEq/L) managed with one dose of sodium zirconium cyclosilicate?", "context": "", "options": [{"key": "A", "text": "Mild.", "sourceKey": "A"}, {"key": "B", "text": "Moderate.", "sourceKey": "B"}, {"key": "C", "text": "Severe.", "sourceKey": "C"}, {"key": "D", "text": "Life threatening.", "sourceKey": "D"}], "answer": "A", "explanation": "A mild ADE is defined as an ADE that resulted in a heightened need for patient monitoring with or without a change in vital signs but no ultimate patient harm, or as any adverse event that resulted in the need for increased laboratory monitoring. Enalapril-induced hyperkalemia managed by one dose of sodium zirconium cyclosilicate did not require aggressive interventions, nor did it lead to any patient harm; however, it did require increased laboratory monitoring, making Answer A correct and Answers B, C, and D incorrect.", "page": 18, "answerPage": 29, "stemZh": "Enalapril 造成無症狀 hyperkalemia（K 5.7 mEq/L），無 ECG changes，給一劑 sodium zirconium cyclosilicate 處理。ADE 嚴重度如何分類？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Mild。"}, {"key": "B", "text": "Moderate。"}, {"key": "C", "text": "Severe。"}, {"key": "D", "text": "Life threatening。"}], "explanationZh": "Mild ADE 需要增加病人或 laboratory monitoring，但未造成最終傷害。本例不需 aggressive interventions，無病人傷害，主要需增加 laboratory monitoring，故為 mild。"}, {"id": "05-case-03", "chapter": 5, "type": "case", "number": 3, "stem": "Which best classifies the degree of severity of an ADE in a patient who is in the geriatric psychiatry unit and develops intravenous haloperidol-induced torsades de pointes that is successfully treated with intravenous magnesium and managed with additional monitoring in the cardiac care unit and telemetry?", "context": "", "options": [{"key": "A", "text": "Mild.", "sourceKey": "A"}, {"key": "B", "text": "Moderate.", "sourceKey": "B"}, {"key": "C", "text": "Severe.", "sourceKey": "C"}, {"key": "D", "text": "No classification.", "sourceKey": "D"}], "answer": "C", "explanation": "A severe ADE results in patient harm, prolonged hospitalization, transfer to a higher level of care, permanent organ damage, or death, which did occur in this case (Answer D is incorrect). Haloperidol-induced torsades de pointes is a life-threatening dysrhythmia (end-organ damage) that required aggressive and successful management with intravenous magnesium and patient transfer to a higher level of care (Answer C is correct). A moderate ADE is defined as an ADE that resulted in the need for aggressive intervention with antidotes or an increased length of hospital stay (Answer B is incorrect). A mild ADE is defined as an ADE that resulted in a heightened need for patient monitoring with or without a change in vital signs but no ultimate patient harm, or as any adverse event that resulted in the need for increased laboratory monitoring, which did not occur in this case, making Answer A incorrect.", "page": 18, "answerPage": 29, "stemZh": "Geriatric psychiatry 病人出現 IV haloperidol-induced torsades de pointes，以 IV magnesium 成功治療，並轉 cardiac care unit 接受額外 monitoring 與 telemetry。ADE 嚴重度如何分類？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Mild。"}, {"key": "B", "text": "Moderate。"}, {"key": "C", "text": "Severe。"}, {"key": "D", "text": "無分類。"}], "explanationZh": "Torsades de pointes 是 life-threatening dysrhythmia，需積極 IV magnesium 及轉較高照護層級，符合 severe ADE。Mild 僅增加 monitoring；moderate 的定義不足以涵蓋本例轉高層級照護及傷害。"}, {"id": "05-case-04", "chapter": 5, "type": "case", "number": 4, "stem": "Which best describes this patient’s reaction to lisinopril?", "context": "M.S., a 77-year-old patient residing in a nursing home, has taken lisinopril 10 mg daily for the past 3 months. They are admitted to the ICU with lisinopril-induced angioedema and present with severe tongue swelling, stridor, and shortness of breath that necessitated a tracheotomy. They had no history of allergies and did not miss any doses of lisinopril.", "options": [{"key": "A", "text": "ADE.", "sourceKey": "A"}, {"key": "B", "text": "Preventable ADE.", "sourceKey": "B"}, {"key": "C", "text": "Medication error.", "sourceKey": "C"}, {"key": "D", "text": "Preventable ADR.", "sourceKey": "D"}], "answer": "A", "explanation": "Because this patient developed lisinopril-induced angioedema, had no history of allergy to angiotensinconverting enzyme inhibitors, and missed no lisinopril doses, his ADE was not a preventable error (Answer B is incorrect). This was also not a medication error, given the information provided (Answer C is incorrect). There is no such thing as a preventable ADR because an ADR occurs from normal use of a medication and is therefore by definition nonpreventable (Answer D is incorrect). Therefore, this would be considered an ADE (Answer A is correct).", "page": 19, "answerPage": 29, "stemZh": "此病人對 lisinopril 的反應如何分類？", "contextZh": "M.S.，77 歲 nursing home 住民，過去 3 months 每日 lisinopril 10 mg。因 lisinopril-induced angioedema 入 ICU，嚴重 tongue swelling、stridor、shortness of breath，需 tracheotomy。無 allergy 史，也未漏服 lisinopril。", "optionsZh": [{"key": "A", "text": "ADE。"}, {"key": "B", "text": "Preventable ADE。"}, {"key": "C", "text": "Medication error。"}, {"key": "D", "text": "Preventable ADR。"}], "explanationZh": "無 ACE inhibitor allergy、未漏藥，也無題述 medication error，因此為 ADE，而非 preventable ADE。依原章節定義，正常用藥發生的 ADR 不屬 preventable ADR。"}, {"id": "05-case-05", "chapter": 5, "type": "case", "number": 5, "stem": "Which best classifies the degree of severity of this patient’s ADE to lisinopril?", "context": "M.S., a 77-year-old patient residing in a nursing home, has taken lisinopril 10 mg daily for the past 3 months. They are admitted to the ICU with lisinopril-induced angioedema and present with severe tongue swelling, stridor, and shortness of breath that necessitated a tracheotomy. They had no history of allergies and did not miss any doses of lisinopril.", "options": [{"key": "A", "text": "Mild.", "sourceKey": "A"}, {"key": "B", "text": "Moderate.", "sourceKey": "B"}, {"key": "C", "text": "Severe.", "sourceKey": "C"}, {"key": "D", "text": "No classification.", "sourceKey": "D"}], "answer": "C", "explanation": "A severe ADE is defined as an ADE that results in patient harm, prolonged hospitalization, transfer to a higher level of care, permanent organ damage, or death, with the probable ADE causality nomogram score. Because this patient developed life-threatening lisinopril-induced angioedema and needed a tracheotomy, resulting in patient harm, hospitalization, and transfer to a higher level of care, this case meets the criteria for a “severe” ADE, making Answer C correct and Answers A, B, and D incorrect.", "page": 19, "answerPage": 29, "stemZh": "此 lisinopril ADE 的嚴重度如何分類？", "contextZh": "M.S.，77 歲 nursing home 住民，過去 3 months 每日 lisinopril 10 mg。因 lisinopril-induced angioedema 入 ICU，嚴重 tongue swelling、stridor、shortness of breath，需 tracheotomy。無 allergy 史，也未漏服 lisinopril。", "optionsZh": [{"key": "A", "text": "Mild。"}, {"key": "B", "text": "Moderate。"}, {"key": "C", "text": "Severe。"}, {"key": "D", "text": "無分類。"}], "explanationZh": "Life-threatening angioedema 需 tracheotomy、住院與較高照護層級，已造成病人傷害，符合 severe ADE。"}, {"id": "05-case-06", "chapter": 5, "type": "case", "number": 6, "stem": "When creating the drug evaluation monograph for adding ATII, which recommendation would be most appropriate to include?", "context": "Your institution is considering adding angiotensin II (ATII) to the hospital formulary. Angiotensin II is a noncatecholamine vasopressor that is FDA approved for increasing blood pressure in distributive shock after publication of the ATHOS-3 trial. The trial, which compared intravenous ATII with placebo once patients received a certain dose of vasopressors, showed that patients who received ATII reached a hemodynamic goal more often than placebo, with no differences in mortality or safety outcomes. Your hospital formulary currently includes the catecholamine vasopressors and vasopressin. A particular concern of your institution is the cost of ATII therapy and adherence to formulary restrictions.", "options": [{"key": "A", "text": "Remove vasopressin from the hospital formulary to make room for ATII.", "sourceKey": "A"}, {"key": "B", "text": "Addition of statement that ATII decreases mortality in patients with distributive shock.", "sourceKey": "B"}, {"key": "C", "text": "Addition of both the intravenous and oral formulations of ATII to the formulary.", "sourceKey": "C"}, {"key": "D", "text": "Restrict use to patients who received the same dose of vasopressors as those included in the ATHOS-3 trial.", "sourceKey": "D"}], "answer": "D", "explanation": "When considering what to include in a drug evaluation monograph for formulary addition, it is important to consider the data analyses available supporting its use. According to what was provided in the case, ATII was only compared with placebo (Answer A is incorrect), did not show any significant differences in mortality (Answer B is incorrect), and was studied in an intravenous formulation (Answer C is incorrect). Answer D is correct because considering the inclusion criteria for the study would be helpful for formulary restriction, especially given the institutional concern of cost.", "page": 25, "answerPage": 29, "stemZh": "為新增 ATII 撰寫 drug evaluation monograph 時，最適合包含哪項建議？", "contextZh": "醫院考慮將 angiotensin II（ATII）納入 formulary。此 noncatecholamine vasopressor 在 ATHOS-3 trial 發表後，FDA 核准用於提高 distributive shock 的 blood pressure。Trial 在接受一定 vasopressor 劑量後，比較 IV ATII 與 placebo；ATII 更常達 hemodynamic goal，但 mortality／safety outcomes 無差異。現有 formulary 包含 catecholamine vasopressors 與 vasopressin；醫院特別關注 ATII 成本與使用限制遵循。", "optionsZh": [{"key": "A", "text": "從 formulary 移除 vasopressin，改納 ATII。"}, {"key": "B", "text": "聲明 ATII 可降低 distributive shock 死亡率。"}, {"key": "C", "text": "將 ATII 的 IV 與 oral formulations 一併納入。"}, {"key": "D", "text": "限制於接受與 ATHOS-3 trial 納入者相同 vasopressor 劑量的病人。"}], "explanationZh": "宜依 trial inclusion criteria 限制使用，尤其需控制成本。ATII 僅與 placebo 比較，不支持移除 vasopressin；未顯示死亡率差異；研究的是 IV formulation。"}, {"id": "05-case-07", "chapter": 5, "type": "case", "number": 7, "stem": "In considering adding ATII to the formulary, which characteristic of your institution would be most important to consider?", "context": "Your institution is considering adding angiotensin II (ATII) to the hospital formulary. Angiotensin II is a noncatecholamine vasopressor that is FDA approved for increasing blood pressure in distributive shock after publication of the ATHOS-3 trial. The trial, which compared intravenous ATII with placebo once patients received a certain dose of vasopressors, showed that patients who received ATII reached a hemodynamic goal more often than placebo, with no differences in mortality or safety outcomes. Your hospital formulary currently includes the catecholamine vasopressors and vasopressin. A particular concern of your institution is the cost of ATII therapy and adherence to formulary restrictions.", "options": [{"key": "A", "text": "Data from ATHOS-3 suggesting its clinical superiority to other FDA-approved medications.", "sourceKey": "A"}, {"key": "B", "text": "How often you encounter patients who require several vasopressors for management of distributive shock.", "sourceKey": "B"}, {"key": "C", "text": "The increased risk of ADEs associated with the use of ATII.", "sourceKey": "C"}, {"key": "D", "text": "Data analyses suggesting the cost-saving benefits of ATII compared with other FDA-approved medications.", "sourceKey": "D"}], "answer": "B", "explanation": "Considerations for formulary addition are important before P&T committee proposals. According to the ATHOS-3 trial, ATII was not compared with other currently available medications (Answer A is incorrect), there were no significant differences in ADEs (Answer C is incorrect), and no data analyses are available suggesting that ATII is cost-saving (Answer D is incorrect). Considering how often you might require the use of ATII would be an important initial consideration (Answer B is correct).", "page": 25, "answerPage": 29, "stemZh": "評估是否將 ATII 納入 formulary，最需考量醫院哪項特性？", "contextZh": "醫院考慮將 angiotensin II（ATII）納入 formulary。此 noncatecholamine vasopressor 在 ATHOS-3 trial 發表後，FDA 核准用於提高 distributive shock 的 blood pressure。Trial 在接受一定 vasopressor 劑量後，比較 IV ATII 與 placebo；ATII 更常達 hemodynamic goal，但 mortality／safety outcomes 無差異。現有 formulary 包含 catecholamine vasopressors 與 vasopressin；醫院特別關注 ATII 成本與使用限制遵循。", "optionsZh": [{"key": "A", "text": "ATHOS-3 顯示 ATII 優於其他 FDA-approved medications 的資料。"}, {"key": "B", "text": "院內需要多種 vasopressors 處理 distributive shock 的病人出現頻率。"}, {"key": "C", "text": "ATII 增加 ADE 風險。"}, {"key": "D", "text": "ATII 比其他 FDA-approved medications 節省成本的資料。"}], "explanationZh": "應先評估實際需要 ATII 的頻率。ATHOS-3 未與其他現有藥品直接比較，未顯示 ADE 顯著差異，也無題述 cost-saving 證據。"}, {"id": "05-case-08", "chapter": 5, "type": "case", "number": 8, "stem": "Angiotensin II was approved by your institution last December, after presentation to the P&T committee. Which best depicts the month in which the first medication use evaluation should be completed?", "context": "Your institution is considering adding angiotensin II (ATII) to the hospital formulary. Angiotensin II is a noncatecholamine vasopressor that is FDA approved for increasing blood pressure in distributive shock after publication of the ATHOS-3 trial. The trial, which compared intravenous ATII with placebo once patients received a certain dose of vasopressors, showed that patients who received ATII reached a hemodynamic goal more often than placebo, with no differences in mortality or safety outcomes. Your hospital formulary currently includes the catecholamine vasopressors and vasopressin. A particular concern of your institution is the cost of ATII therapy and adherence to formulary restrictions.", "options": [{"key": "A", "text": "March of this year.", "sourceKey": "A"}, {"key": "B", "text": "June of this year.", "sourceKey": "B"}, {"key": "C", "text": "October of this year.", "sourceKey": "C"}, {"key": "D", "text": "December of this year.", "sourceKey": "D"}], "answer": "A", "explanation": "The first medication use evaluation is recommended to occur within 3–6 months of formulary addition. Therefore, March would be the most appropriate month (Answer A is correct). Although June would fall in the 3- to 6-month range, given the novelty of this agent and its cost, it would be important to conduct a medication use evaluation as soon as possible (Answer B is incorrect). October and December would be too long to wait for an evaluation to be performed (Answers C and D are incorrect).", "page": 25, "answerPage": 29, "stemZh": "Angiotensin II 去年 12 月經 P&T committee 核准納入院內使用。第一次 MUE 最適合在哪個月完成？", "contextZh": "醫院考慮將 angiotensin II（ATII）納入 formulary。此 noncatecholamine vasopressor 在 ATHOS-3 trial 發表後，FDA 核准用於提高 distributive shock 的 blood pressure。Trial 在接受一定 vasopressor 劑量後，比較 IV ATII 與 placebo；ATII 更常達 hemodynamic goal，但 mortality／safety outcomes 無差異。現有 formulary 包含 catecholamine vasopressors 與 vasopressin；醫院特別關注 ATII 成本與使用限制遵循。", "optionsZh": [{"key": "A", "text": "今年 3 月。"}, {"key": "B", "text": "今年 6 月。"}, {"key": "C", "text": "今年 10 月。"}, {"key": "D", "text": "今年 12 月。"}], "explanationZh": "第一次 MUE 建議於納入 formulary 後 3–6 months 進行。因藥物新穎且昂貴，應儘早評估，以 3 月最佳；6 月雖仍在範圍，但不如 3 月適當；10／12 月過晚。"}, {"id": "06-self-01", "chapter": 6, "type": "self", "number": 1, "stem": "Which is the most likely causative pathogen of K.P.’s suspected VAP?", "context": "K.P., a 38-year-old otherwise healthy woman, was involved in a motor vehicle collision, sustaining a traumatic brain injury and severe chest injuries requiring endotracheal intubation and mechanical ventilation. After being in the trauma intensive care unit (ICU) for 96 hours, a new infiltrate is noted on her chest radiograph, as well as a temperature of 101.9°F (38.8°C), a white blood cell count (WBC) of 15 x 103 cells/mm3, and macroscopically purulent sputum. K.P. is hemodynamically stable. Accordingly, your team decides to obtain a bronchoscopic bronchoalveolar lavage (BAL) of the affected lung field to assess for ventilator-associated pneumonia (VAP), where your local ICU MRSA prevalence is less than 10%.", "options": [{"key": "A", "text": "Acinetobacter spp.", "sourceKey": "A"}, {"key": "B", "text": "Methicillin-resistant Staphylococcus aureus (MRSA)", "sourceKey": "B"}, {"key": "C", "text": "Multidrug-resistant Pseudomonas aeruginosa", "sourceKey": "C"}, {"key": "D", "text": "Streptococcus pneumoniae ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 225", "sourceKey": "D"}], "answer": "D", "explanation": "The patient described has early onset VAP without apparent updated risk factors for MDROs (Answers A, B, and C, are incorrect). Pathogens associated with early onset hospital-acquired pneumonia and VAP in the absence of other MDR risk factors are usually community-acquired organisms, including S. pneumoniae, MSSA, H. inÞuenzae, and enteric gram-negative bacilli (Answer D is correct). However, because some epidemiological studies have documented the occurrence of traditionally nosocomial or late-onset pathogens within 5 days from admission, guideline updates recommend that P. aeruginosa coverage be considered as empiric therapy for all patients suspected of having VAP. This further emphasizes the importance of understanding local VAP pathogen trends amid MDR risk factors and time from admission to onset. Atypical bacteria are rarely associated with early onset VAP. If MDRO risk factors were present, MRSA and P. aeruginosa would also be considered.", "page": 4, "answerPage": 69, "stemZh": "K.P. 疑似 VAP 最可能由哪個 pathogen 引起？", "contextZh": "K.P. 為 38 歲、原本健康的女性，因車禍發生 traumatic brain injury 及嚴重胸部損傷，需 endotracheal intubation 與 mechanical ventilation。入住 trauma ICU 96 小時後，chest radiograph 出現新 infiltrate，temperature 101.9°F（38.8°C）、WBC 15 x 103 cells/mm3，並有肉眼可見的 purulent sputum。Hemodynamics 穩定。團隊決定對受影響肺區進行 bronchoscopic bronchoalveolar lavage（BAL），評估 VAP；當地 ICU 的 MRSA prevalence 低於 10%。", "optionsZh": [{"key": "A", "text": "Acinetobacter spp."}, {"key": "B", "text": "Methicillin-resistant Staphylococcus aureus (MRSA)"}, {"key": "C", "text": "Multidrug-resistant Pseudomonas aeruginosa"}, {"key": "D", "text": "Streptococcus pneumoniae"}], "explanationZh": "依原教材，無 MDR risk factors 的 early-onset VAP 常見 community-acquired pathogens，包括 S. pneumoniae；實際 empiric treatment 仍須納入 local trends 及 antipseudomonal coverage。"}, {"id": "06-self-02", "chapter": 6, "type": "self", "number": 2, "stem": "Based on the 2016 IDSA guidelines, which empiric antibiotic regimen is best for the likely causative pathogen(s) of K.P.’s suspected VAP?", "context": "K.P., a 38-year-old otherwise healthy woman, was involved in a motor vehicle collision, sustaining a traumatic brain injury and severe chest injuries requiring endotracheal intubation and mechanical ventilation. After being in the trauma intensive care unit (ICU) for 96 hours, a new infiltrate is noted on her chest radiograph, as well as a temperature of 101.9°F (38.8°C), a white blood cell count (WBC) of 15 x 103 cells/mm3, and macroscopically purulent sputum. K.P. is hemodynamically stable. Accordingly, your team decides to obtain a bronchoscopic bronchoalveolar lavage (BAL) of the affected lung field to assess for ventilator-associated pneumonia (VAP), where your local ICU MRSA prevalence is less than 10%.", "options": [{"key": "A", "text": "Azithromycin plus moxifloxacin", "sourceKey": "A"}, {"key": "B", "text": "Cefepime", "sourceKey": "B"}, {"key": "C", "text": "Ceftriaxone", "sourceKey": "C"}, {"key": "D", "text": "Ceftriaxone plus vancomycin", "sourceKey": "D"}], "answer": "B", "explanation": "Empiric antibiotic choices for VAP should be based on the likely causative pathogens, the presence of MDRO risk factors, and local antibiotic susceptibility patterns. The 2016 IDSA guidelines recommend P. aeruginosa coverage as empiric therapy for all patients suspected of having VAP, with monotherapy antipseudomonal β-lactam sufficient in the absence of MDRO risk factors or if the local antibiogram suggests less than 10% resistance. Therefore, cefepime is preferred to ceftriaxone (Answer B is correct; Answers C and D are incorrect). Atypical bacteria are rarely associated with early-onset VAP (Answer A is incorrect).", "page": 5, "answerPage": 69, "stemZh": "依 2016 IDSA guidelines，對 K.P. 疑似 VAP 的可能 pathogen，哪個 empiric antibiotic regimen 最適合？", "contextZh": "K.P. 為 38 歲、原本健康的女性，因車禍發生 traumatic brain injury 及嚴重胸部損傷，需 endotracheal intubation 與 mechanical ventilation。入住 trauma ICU 96 小時後，chest radiograph 出現新 infiltrate，temperature 101.9°F（38.8°C）、WBC 15 x 103 cells/mm3，並有肉眼可見的 purulent sputum。Hemodynamics 穩定。團隊決定對受影響肺區進行 bronchoscopic bronchoalveolar lavage（BAL），評估 VAP；當地 ICU 的 MRSA prevalence 低於 10%。", "optionsZh": [{"key": "A", "text": "Azithromycin 合併 moxifloxacin"}, {"key": "B", "text": "Cefepime"}, {"key": "C", "text": "Ceftriaxone"}, {"key": "D", "text": "Ceftriaxone 合併 vancomycin"}], "explanationZh": "Cefepime 提供 P. aeruginosa coverage；無 MDR risk 且 local resistance 低時，antipseudomonal β-lactam monotherapy 可符合題目條件。"}, {"id": "06-self-03", "chapter": 6, "type": "self", "number": 3, "stem": "T.D. is a 57-year-old man admitted to the medical intensive care unit (MICU) with severe hyperosmolar hyperglycemic syndrome. A subclavian central venous catheter (CVC) is placed on his arrival at the MICU. On ICU day 4, T.D. has a temperature of 102.7°F (39.2°C) and a WBC of 17 x 103 cells/mm3. The nurse notes new-onset erythema at the catheter site. After an appropriate diagnostic workup, it is decided to initiate empiric antibiotic therapy for a suspected central line–associated bloodstream infection (CLABSI). Which agent is best for empiric therapy?", "context": "", "options": [{"key": "A", "text": "Cefazolin", "sourceKey": "A"}, {"key": "B", "text": "Linezolid", "sourceKey": "B"}, {"key": "C", "text": "Piperacillin/tazobactam", "sourceKey": "C"}, {"key": "D", "text": "Vancomycin", "sourceKey": "D"}], "answer": "D", "explanation": "Gram-positive organisms are the most common cause of CLABSI, including MRSE and MRSA. Vancomycin is the best option listed for empiric management (Answer D is correct). Although linezolid has a sufficient spectrum of activity against these organisms, it is not recommended for empiric management of CLABSI because of concerns for worse patient outcomes (Answer B is incorrect). The other options are inactive against MRSE and MRSA and could be considered in addition to vancomycin if there were a high suspicion for additional pathogens (Answers A and C are incorrect).", "page": 5, "answerPage": 69, "stemZh": "T.D. 為 57 歲男性，因嚴重 hyperosmolar hyperglycemic syndrome 入住 MICU，入院時放置 subclavian CVC。ICU 第 4 天 temperature 102.7°F（39.2°C）、WBC 17 x 103 cells/mm3，護理師注意到 catheter site 新發 erythema。完成適當診斷評估後，團隊決定對疑似 CLABSI 開始 empiric antibiotics。哪個藥物最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Cefazolin"}, {"key": "B", "text": "Linezolid"}, {"key": "C", "text": "Piperacillin/tazobactam"}, {"key": "D", "text": "Vancomycin"}], "explanationZh": "Vancomycin 可涵蓋常見的 MRSE 與 MRSA；linezolid 雖有活性，原教材不建議用於 empiric CLABSI therapy。"}, {"id": "06-self-04", "chapter": 6, "type": "self", "number": 4, "stem": "D.G., a 31-year-old woman, presents to the MICU with severe respiratory failure and acute respiratory distress syndrome (ARDS) requiring intubation after 48 hours of malaise, fever, and myalgias. The nasal washing sent by the emergency department (ED) for rapid diagnostic testing is positive for influenza A. The local prevalence of subtype 2009 H1N1 is high. Which agent would be most appropriate for initial treatment of D.G.’s severe influenza?", "context": "", "options": [{"key": "A", "text": "Amantadine", "sourceKey": "A"}, {"key": "B", "text": "Inhaled zanamivir", "sourceKey": "B"}, {"key": "C", "text": "Intravenous zanamivir", "sourceKey": "C"}, {"key": "D", "text": "Oseltamivir", "sourceKey": "D"}], "answer": "D", "explanation": "Given the high prevalence of the 2009 H1N1 subtype of influenza A, oseltamivir is the empiric drug of choice. In addition, oseltamivir has high-level activity against other contemporary influenza A and B subtypes (Answer D is correct). Zanamivir also has high-level activity against these strains; however, inhaled therapy through the mechanical ventilator is not indicated because of insufficient systemic delivery, and intravenous zanamivir is available through compassionate use and indicated only if oseltamivir cannot be administered (e.g., patient is unable to receive enteral medications, has poor absorption) (Answers B and C are incorrect). Amantadine has insufficient activity against most contemporary influenza A and B strains (Answer A is incorrect).", "page": 5, "answerPage": 69, "stemZh": "D.G. 為 31 歲女性，經歷 48 小時 malaise、fever 與 myalgias 後，因嚴重 respiratory failure 及 ARDS 入住 MICU 並需插管。ED 送驗的 nasal washing rapid diagnostic test 為 influenza A 陽性；當地 2009 H1N1 subtype prevalence 高。哪個藥物最適合初始治療 severe influenza？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Amantadine"}, {"key": "B", "text": "吸入 zanamivir"}, {"key": "C", "text": "靜脈 zanamivir"}, {"key": "D", "text": "Oseltamivir"}], "explanationZh": "Oseltamivir 適合本題重症 influenza；inhaled zanamivir 不適合經 ventilator 給藥，amantadine 對當代 strains 活性不足。"}, {"id": "06-self-05", "chapter": 6, "type": "self", "number": 5, "stem": "T.S. is a 79-year-old woman admitted to the MICU for respiratory failure and severe communityacquired pneumonia. T.S. has had a urethral catheter in place for 6 days while mechanically ventilated on fentanyl infusion and intermittent haloperidol as needed for pain and delirium, respectively. This morning, T.S. had a temperature of 101.6°F (38.7°C) and an elevation in WBC to 16 x 103 cells/mm3; she is hemodynamically stable. Blood and urine cultures are sent. Urinalysis reveals significant pyuria. Which pathogen is most likely to cause a catheter-associated urinary tract infection (CAUTI) in T.S.?", "context": "", "options": [{"key": "A", "text": "Enterococcus faecalis", "sourceKey": "A"}, {"key": "B", "text": "Escherichia coli", "sourceKey": "B"}, {"key": "C", "text": "P. aeruginosa", "sourceKey": "C"}, {"key": "D", "text": "S. aureus", "sourceKey": "D"}], "answer": "B", "explanation": "Although a health care–associated CAUTI is caused by a more diverse spectrum of pathogens, E. coli is still the most common pathogen and is responsible for around 30% of cases (Answer B is correct). The other pathogens listed are also possible and should be considered when choosing empiric antibiotic therapy in patients with a suspected CAUTI (Answers A, C, and D are incorrect).", "page": 5, "answerPage": 69, "stemZh": "T.S. 為 79 歲女性，因 respiratory failure 與 severe community-acquired pneumonia 入住 MICU。她已放置 urethral catheter 6 天，接受 mechanical ventilation；使用 fentanyl infusion 止痛，並依需求間歇給予 haloperidol 處理 delirium。今早 temperature 101.6°F（38.7°C）、WBC 16 x 103 cells/mm3，hemodynamics 穩定。已送 blood 及 urine cultures，urinalysis 顯示明顯 pyuria。哪個 pathogen 最可能造成她的 CAUTI？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Enterococcus faecalis"}, {"key": "B", "text": "Escherichia coli"}, {"key": "C", "text": "P. aeruginosa"}, {"key": "D", "text": "S. aureus"}], "explanationZh": "E. coli 仍是 CAUTI 最常見 pathogen，原教材估計約占 30%；其他選項也可能致病，但不是最常見。"}, {"id": "06-self-06", "chapter": 6, "type": "self", "number": 6, "stem": "K.D. is a 59-year-old man admitted to the surgical intensive care unit (SICU) after an emergency operation and partial bowel resection with primary anastomosis for mid-small bowel necrosis and perforation likely secondary to severe peripheral vascular disease. During the operation, significant peritoneal contamination with evidence of gross peritonitis was noted together with persistent hypotension and need for vasopressors. K.D. received perioperative cefazolin and metronidazole. Which empiric antibiotic regimen would be most appropriate for K.D.?", "context": "", "options": [{"key": "A", "text": "Ceftriaxone and vancomycin", "sourceKey": "A"}, {"key": "B", "text": "Ciprofloxacin and metronidazole", "sourceKey": "B"}, {"key": "C", "text": "Ertapenem", "sourceKey": "C"}, {"key": "D", "text": "Piperacillin/tazobactam", "sourceKey": "D"}], "answer": "D", "explanation": "This patient has community-acquired complicated intra-abdominal infection involving the middle small intestine. Although enteric gram-negative bacilli (e.g., E. coli, Klebsiella spp.) are the most common pathogens related to this type of infection, patients with severe disease, as evidenced by concomitant septic shock, are at a higher risk of MDROs, including P. aeruginosa and enterococci. Piperacillin/tazobactam has empiric activity against these organisms, whereas the other regimens/ agents listed have relevant gaps in the bacterial spectrum relative to these pathogens (Answer D is correct; Answers A–C are incorrect).", "page": 5, "answerPage": 69, "stemZh": "K.D. 為 59 歲男性，因可能由 severe peripheral vascular disease 造成的 mid-small bowel necrosis 與 perforation，接受緊急 partial bowel resection 及 primary anastomosis 後入住 SICU。手術見嚴重 peritoneal contamination、gross peritonitis、持續 hypotension 並需 vasopressors。圍手術期已給 cefazolin 與 metronidazole。哪個 empiric antibiotic regimen 最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Ceftriaxone 與 vancomycin"}, {"key": "B", "text": "Ciprofloxacin 與 metronidazole"}, {"key": "C", "text": "Ertapenem"}, {"key": "D", "text": "Piperacillin/tazobactam"}], "explanationZh": "Septic shock 增加 MDR risk；piperacillin/tazobactam 涵蓋本題需要的 gram-negative pathogens、P. aeruginosa、anaerobes 及 enterococci。"}, {"id": "06-self-07", "chapter": 6, "type": "self", "number": 7, "stem": "T.M. is a 42-year-old man with chronic alcoholism who presents to the ED with severe epigastric pain and serum lipase greater than 10 times the upper limit of normal. The resident orders a computed tomography (CT) scan, which reveals necrosis affecting almost 40% of the pancreas but no abnormal fluid collections or evidence of abscess. T.M. is febrile and tachycardic, and his WBC is elevated. T.M.’s urine output is less than 0.5 mL/kg/hour, suggestive of hypovolemia. Which best describes the role of antibiotic therapy for T.M. at this time?", "context": "", "options": [{"key": "A", "text": "Antibiotic therapy is not indicated.", "sourceKey": "A"}, {"key": "B", "text": "Initiate empiric antibiotic therapy for presumed sepsis and likely pancreatic infection.", "sourceKey": "B"}, {"key": "C", "text": "Initiate perioperative antibiotic therapy in preparation for pancreatic debridement.", "sourceKey": "C"}, {"key": "D", "text": "Initiate prophylactic antibiotic therapy to prevent infection of necrotic tissue. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 226", "sourceKey": "D"}], "answer": "A", "explanation": "This patient presents with severe acute pancreatitis with radiographic evidence of pancreatic necrosis. Although the patient presents with SIRS, the absence of significant fluid collection or abscess suggests there is no concomitant infection. As such, there is no indication for empiric antibiotic therapy at this time (Answer A is correct; Answer B is incorrect). Most recent evidence ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 290 and guideline recommendations do not support prophylactic antibiotic therapy for preventing infection of the necrotic tissue (Answer D is incorrect). The mainstay of therapy for this patient is volume resuscitation and consideration of surgical debridement of pancreatic necrosis if persistent SIRS is evident (Answer C is incorrect).", "page": 5, "answerPage": 69, "stemZh": "T.M. 為 42 歲男性，有 chronic alcoholism，因 severe epigastric pain 至 ED；serum lipase 超過正常上限 10 倍。CT 顯示近 40% pancreas necrosis，但無 abnormal fluid collections 或 abscess。病人 fever、tachycardia、WBC 升高，urine output 低於 0.5 mL/kg/hour，提示 hypovolemia。目前 antibiotic therapy 的角色為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "目前無 antibiotic therapy 適應症。"}, {"key": "B", "text": "針對 presumed sepsis 及可能 pancreatic infection 開始 empiric antibiotics。"}, {"key": "C", "text": "為 pancreatic debridement 準備 perioperative antibiotics。"}, {"key": "D", "text": "開始 prophylactic antibiotics，避免 necrotic tissue 感染。"}], "explanationZh": "本題為無感染證據的 necrotizing pancreatitis；SIRS 不代表感染，不應例行給 prophylactic antibiotics。"}, {"id": "06-self-08", "chapter": 6, "type": "self", "number": 8, "stem": "J.E. is a 67-year-old woman admitted to the MICU for severe metabolic acidosis secondary to unintentional metformin overdosage. Her ICU stay has been complicated by a femoral vein CLABSI and related severe sepsis caused by pan-sensitive E. coli. J.E. received a 3-day course of empiric piperacillin/tazobactam, removal of her central line, and 11 days of ceftriaxone as definitive therapy with resolution of sepsis. Starting yesterday, it was noted that J.E. had nine loose bowel movements and new leukocytosis of 14,500 cells/mm3, which suggests Clostridioides difficile infection (CDI). J.E. continues to tolerate enteral nutrition. Per the 2021 IDSA focused guideline update, which is the most appropriate regimen for J.E.’s suspected CDI?", "context": "", "options": [{"key": "A", "text": "Fidaxomicin 200 mg per feeding tube every 12 hours", "sourceKey": "A"}, {"key": "B", "text": "Metronidazole 500 mg per feeding tube every 8 hours", "sourceKey": "B"}, {"key": "C", "text": "Metronidazole 500 mg intravenously every 8 hours", "sourceKey": "C"}, {"key": "D", "text": "Vancomycin 125 mg per feeding tube every 6 hours", "sourceKey": "D"}], "answer": "A", "explanation": "Metronidazole orally or through a feeding tube is not recommended for management of an initial-episode CDI (Answer B is incorrect). Intravenous metronidazole is indicated for fulminant CDI in combination with vancomycin (Answer C is incorrect) In the absence of fulminant CDI (i.e., shock, megacolon, ileus), the 2021 IDSA focused guideline update recommends fidaxomicin over oral/enteral vancomycin for first-episode CDI to increase the likelihood of complete clinical response (Answer A is correct; Answer D is incorrect). If fidaxomicin is unavailable or cost-prohibitive, oral/enteral vancomycin is an acceptable alternative.", "page": 6, "answerPage": 70, "stemZh": "J.E. 為 67 歲女性，因意外 metformin overdose 所致 severe metabolic acidosis 入住 MICU。期間發生 pan-sensitive E. coli femoral-vein CLABSI 及 severe sepsis，接受 3 天 empiric piperacillin/tazobactam、移除 central line，再以 ceftriaxone 治療 11 天後 sepsis 緩解。昨天起有 9 次 loose stools，新發 leukocytosis 14,500 cells/mm3，疑似 CDI；仍可耐受 enteral nutrition。依 2021 IDSA focused guideline update，哪個 regimen 最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Fidaxomicin 200 mg 經 feeding tube 每 12 小時"}, {"key": "B", "text": "Metronidazole 500 mg 經 feeding tube 每 8 小時"}, {"key": "C", "text": "Metronidazole 500 mg 靜脈給藥 每 8 小時"}, {"key": "D", "text": "Vancomycin 125 mg 經 feeding tube 每 6 小時"}], "explanationZh": "初次、非 fulminant CDI 優先考量 fidaxomicin；oral/enteral vancomycin 為可接受替代。IV metronidazole 單用不適合本題。"}, {"id": "06-self-09", "chapter": 6, "type": "self", "number": 9, "stem": "J.S. is a 42-year-old man admitted to the SICU after an open total colectomy with ileostomy for ischemic colitis. On postoperative day 4, the surgery resident on your interdisciplinary ICU team notes moderate erythema (3 cm) and purulent drainage from the wound. The resident subsequently opens the skin portion of the wound and finds infected material just above the unaffected fascia. No systemic signs and symptoms are noted. Which intervention is most appropriate?", "context": "", "options": [{"key": "A", "text": "Continue dressing changes and patient assessment.", "sourceKey": "A"}, {"key": "B", "text": "Initiate empiric vancomycin for postoperative wound infection.", "sourceKey": "B"}, {"key": "C", "text": "Initiate empiric antibiotic therapy targeted against skin and colonic flora.", "sourceKey": "C"}, {"key": "D", "text": "Initiate broad-spectrum antibiotic therapy for suspected necrotizing fasciitis.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient has a superficial incisional wound infection requiring opening and the local debridement of infected material. Lack of systemic signs of infection and no involvement of the fascia suggest that no antibiotic therapy is necessary at this time (Answer A is correct; Answers B–D are incorrect). If the infection extends to include these features or worsened erythema consistent with cellulitis, empiric antibiotic therapy may be warranted.", "page": 6, "answerPage": 70, "stemZh": "J.S. 為 42 歲男性，因 ischemic colitis 接受 open total colectomy 及 ileostomy 後入住 SICU。術後第 4 天傷口有 3 cm erythema 及 purulent drainage。住院醫師打開皮膚傷口，發現感染物位於未受影響 fascia 上方；無 systemic signs 或 symptoms。哪個處置最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "持續換藥與病人評估。"}, {"key": "B", "text": "為 postoperative wound infection 開始 empiric vancomycin。"}, {"key": "C", "text": "開始涵蓋 skin 與 colonic flora 的 empiric antibiotics。"}, {"key": "D", "text": "因疑似 necrotizing fasciitis 開始 broad-spectrum antibiotics。"}], "explanationZh": "Superficial incisional infection 已局部打開，無 systemic signs、fascia involvement 或明顯 cellulitis 時，可持續 wound care 與評估。"}, {"id": "06-self-10", "chapter": 6, "type": "self", "number": 10, "stem": "A.C. is a 27-year-old man with human immunodeficiency virus (HIV) on active antiretroviral therapy who presents to the burn ICU from an outside hospital with 30% total body surface area (TBSA) epidermolysis of his back and upper arms suggestive of toxic epidermal necrolysis (TEN), likely from sulfamethoxazole/trimethoprim. Reportedly, A.C. arrived at the outside hospital about 6 hours ago with less than 10% TBSA involvement. Vital signs include heart rate 142 beats/minute, respiratory rate 30 breaths/minute, and blood pressure 100/50 mm Hg. Which would be the best initial pharmacotherapeutic intervention?", "context": "", "options": [{"key": "A", "text": "Administer high-dose corticosteroids to halt the progression of TEN.", "sourceKey": "A"}, {"key": "B", "text": "Initiate crystalloid resuscitation for hypovolemia.", "sourceKey": "B"}, {"key": "C", "text": "Place a nasogastric tube to administer antiretroviral medications.", "sourceKey": "C"}, {"key": "D", "text": "Initiate broad-spectrum antibiotic prophylaxis for wound infection.", "sourceKey": "D"}], "answer": "B", "explanation": "Similar to severe thermal cutaneous injury, the foundation for managing TEN is volume resuscitation and supportive care as well as removal of all suspected causes (Answer B is correct). The utility of corticosteroids is limited and may be harmful to wound healing (Answer A is incorrect). Addition of unnecessary drugs that could confound response or worsen the injury (e.g., antibiotics) should be avoided (Answers C and D are incorrect).", "page": 6, "answerPage": 70, "stemZh": "A.C. 為 27 歲男性，有 HIV 且接受 active antiretroviral therapy，從外院轉至 burn ICU；back 及 upper arms 有 30% TBSA epidermolysis，疑似 sulfamethoxazole/trimethoprim 引起 TEN。約 6 小時前至外院時 TBSA involvement 低於 10%。HR 142 beats/minute、RR 30 breaths/minute、BP 100/50 mm Hg。哪個初始 pharmacotherapeutic intervention 最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "給 high-dose corticosteroids 阻止 TEN 惡化。"}, {"key": "B", "text": "針對 hypovolemia 開始 crystalloid resuscitation。"}, {"key": "C", "text": "放置 nasogastric tube 給 antiretroviral medications。"}, {"key": "D", "text": "為 wound infection 開始 broad-spectrum antibiotic prophylaxis。"}], "explanationZh": "TEN 初始重點為移除可疑致病藥、volume resuscitation 與 supportive care，避免無必要新增藥物。"}, {"id": "06-self-11", "chapter": 6, "type": "self", "number": 11, "stem": "T.F. is a 68-year-old man with diabetes and hypertension who presents to the ED with altered mental status and acute kidney injury. T.F. was seen at an outside hospital 5 days ago, where he tested positive for novel severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2). On initial assessment, T.F. is hemodynamically stable with an oxygen saturation (SaO 2 ) of 87% on room air, which has worsened over the past 4 hours. T.F. now requires 5 L of highflow nasal cannula to maintain an SaO 2 above 92%. Chest radiography is notable for bilateral opacities consistent with viral pneumonia. Initial laboratory tests indicate alanine aminotransferase 23 U/L and estimated creatinine clearance 31 mL/minute (baseline 68 mL/minute). Which agent is considered first-line therapy in hospitalized patients with coronavirus disease 2019 (COVID-19) and increasing oxygen requirement?", "context": "", "options": [{"key": "A", "text": "Dexamethasone.", "sourceKey": "A"}, {"key": "B", "text": "Hydroxychloroquine.", "sourceKey": "B"}, {"key": "C", "text": "Remdesivir.", "sourceKey": "C"}, {"key": "D", "text": "Tocilizumab. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 227", "sourceKey": "D"}], "answer": "A", "explanation": "The RECOVERY trial showed that dexamethasone decreases 28-day mortality compared with usual care in hospitalized patients with COVID-19 requiring supplemental oxygen or MV. A meta-analysis of available trials also supports corticosteroid use (Answer A is correct). Hydroxychloroquine has limited to no benefit in patients hospitalized with COVID-19 (Answer B is incorrect). Evidence from the ACTT study showed that remdesivir may shorten the duration to clinical recovery, but it has no difference on mortality compared with placebo. Non-controlled, aggregated data have suggested an association with lower mortality, but this has not been confirmed in controlled trials; therefore, remdesivir should be considered in addition to dexamethasone rather than monotherapy in patients with increasing oxygen requirement (Answer C is incorrect). Tocilizumab, an anti–IL-6 monoclonal antibody, can be considered in addition to dexamethasone with or without remdesivir in patients recently hospitalized and demonstrating rapid decline in oxygenation and systemic inflammation. (Answer D is incorrect).", "page": 6, "answerPage": 70, "stemZh": "T.F. 為 68 歲男性，有 diabetes 與 hypertension，因 altered mental status 與 AKI 至 ED。5 天前在外院 SARS-CoV-2 陽性。起初 hemodynamics 穩定、room-air SaO2 87%，過去 4 小時惡化，目前需 5 L high-flow nasal cannula 才能維持 SaO2 >92%。Chest radiograph 有符合 viral pneumonia 的 bilateral opacities。ALT 23 U/L、estimated creatinine clearance 31 mL/minute（baseline 68 mL/minute）。住院 coronavirus disease 2019（COVID-19）且 oxygen requirement 增加時，哪個藥物被視為 first-line therapy？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dexamethasone."}, {"key": "B", "text": "Hydroxychloroquine."}, {"key": "C", "text": "Remdesivir."}, {"key": "D", "text": "Tocilizumab."}], "explanationZh": "依原教材，需 oxygen 的 hospitalized COVID-19 使用 dexamethasone 可降低 mortality；其餘選項不適合作為本題單一 first-line therapy。"}, {"id": "06-case-01", "chapter": 6, "type": "case", "number": 1, "stem": "C.T. is a 48-year-old man sustaining a 40% TBSA burn to his left side with likely inhalational injury requiring mechanical ventilation. C.T. has been in the ICU for 7 days. Overnight, C.T. had a temperature of 102.1°F (39°C), a WBC of 18 x 103 cells/mm3, and an increase in macroscopically purulent sputum production; C.T. is hemodynamically stable with no signs of new-onset organ dysfunction. C.T.’s chest radiograph is difficult to assess, given his inhalational injury. The respiratory therapist was asked by the fellow to do a catheter-directed BAL for suspected VAP. The culture was sent to the microbiology laboratory. Which would be best to do at this point?", "context": "", "options": [{"key": "A", "text": "Initiate broad-spectrum empiric antibiotic therapy for suspected MDR VAP.", "sourceKey": "A"}, {"key": "B", "text": "Await 1–2 days for Gram stain results to determine empiric antibiotic regimen.", "sourceKey": "B"}, {"key": "C", "text": "Await preliminary quantitative culture results before initiating empiric antibiotic therapy.", "sourceKey": "C"}, {"key": "D", "text": "Send blood and urine cultures, and await their results before initiating empiric antibiotic therapy.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient has suspicion for MDR VAP, as evidenced by the presence of clinical signs of infection, the patient’s increased sputum production, and the patient’s having been in the ICU for 5 days or longer. Empiric antibiotic therapy should be initiated after obtaining a respiratory culture and be based on patient-specific risk factors for MDROs, together with local pathogen prevalence and antibiotic susceptibility, to increase the likelihood of providing timely appropriate antibiotic therapy (Answer A is correct). Gram stain results can be used to help guide empiric therapy as per GRACE-VAP, but antibiotics should not be delayed 1–2 days awaiting Gram stain, preliminary or final respiratory culture results, as well as blood or urine cultures, may cause an unacceptable delay in appropriate antibiotic therapy (Answers B–D are incorrect).", "page": 15, "answerPage": 65, "stemZh": "C.T. 為 48 歲男性，左側有 40% TBSA burn 及疑似 inhalational injury，需 mechanical ventilation。ICU 第 7 天夜間 temperature 102.1°F（39°C）、WBC 18 x 103 cells/mm3，purulent sputum 增多；hemodynamics 穩定，無新發 organ dysfunction。因 inhalational injury，chest radiograph 難判讀。Fellow 請 respiratory therapist 進行 catheter-directed BAL 評估疑似 VAP，檢體已送 microbiology laboratory。此時最佳處置為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "對疑似 MDR VAP 開始 broad-spectrum empiric antibiotics。"}, {"key": "B", "text": "等待 1–2 天 Gram stain 結果再決定 empiric regimen。"}, {"key": "C", "text": "等待 preliminary quantitative culture 結果再開始 antibiotics。"}, {"key": "D", "text": "送 blood 及 urine cultures，等待結果再開始 antibiotics。"}], "explanationZh": "採取 respiratory culture 後應及時開始依 MDR risk 與 local susceptibility 選擇的 empiric antibiotics，不宜等待 1–2 天檢驗結果。"}, {"id": "06-case-02", "chapter": 6, "type": "case", "number": 2, "stem": "C.P. is a 67-year-old woman with a medical history significant for chronic obstructive pulmonary disease (COPD), type 2 diabetes, and coronary artery disease. She is readmitted to the ICU with respiratory failure requiring intubation secondary to severe COPD. C.P. had a 10-day hospitalization 12 days ago, during which time she received intravenous azithromycin for a COPD exacerbation. On day 4 of this readmission, a worsening infiltrate is in the left lower lung base with increased sputum production from admission, maximum temperature is 101.9°F (38.8°C), and there is worsening oxygenation, despite previous improvement in initial COPD exacerbation. The patient is thought to have clinical VAP, and a semiquantitative tracheal aspirate is sent to identify causative pathogen(s). The local ICU prevalence of MRSA is 30%, and the most active β-lactam antibiotic against P. aeruginosa on the antibiogram has 80% activity. Which empiric antibiotic regimen is best for this patient?", "context": "", "options": [{"key": "A", "text": "Azithromycin plus moxifloxacin.", "sourceKey": "A"}, {"key": "B", "text": "Cefepime plus tobramycin, and vancomycin.", "sourceKey": "B"}, {"key": "C", "text": "Ceftriaxone plus azithromycin.", "sourceKey": "C"}, {"key": "D", "text": "Linezolid plus tobramycin.", "sourceKey": "D"}], "answer": "B", "explanation": "Although this patient is suspected of having earlyonset VAP for the current admission, a history of recent intravenous antibiotic therapy is a risk factor for MDROs. Empiric antibiotic therapy for VAP in patients with MDRO risk factors should include agents active against P. aeruginosa and MRSA. Empiric combination therapy against P. aeruginosa is recommended to increase the likelihood of appropriate antibiotic therapy (Answer B is correct; Answers A and C are incorrect) with a β-lactam antibiotic as one of the preferred agents (Answer D is incorrect). Atypical bacteria coverage is not necessary because their prevalence is low, although consideration should be given if there is a poor response to initial therapy.", "page": 15, "answerPage": 65, "stemZh": "C.P. 為 67 歲女性，有 COPD、type 2 diabetes 及 coronary artery disease，因嚴重 COPD 所致 respiratory failure 再入住 ICU 並插管。12 天前曾住院 10 天，期間因 COPD exacerbation 接受 IV azithromycin。本次入院第 4 天，雖 COPD 曾改善，left lower lung base infiltrate 惡化、sputum 增多、最高 temperature 101.9°F（38.8°C），oxygenation 變差。疑似 VAP，送 semiquantitative tracheal aspirate。當地 ICU MRSA prevalence 30%，antibiogram 中對 P. aeruginosa 活性最高的 β-lactam 僅 80% active。最佳 empiric regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Azithromycin 合併 moxifloxacin."}, {"key": "B", "text": "Cefepime 合併 tobramycin, 與 vancomycin."}, {"key": "C", "text": "Ceftriaxone 合併 azithromycin."}, {"key": "D", "text": "Linezolid 合併 tobramycin."}], "explanationZh": "近期 IV antibiotics 與 local resistance 提示 MDR risk；需 MRSA coverage 及含 β-lactam 的雙重 antipseudomonal coverage。"}, {"id": "06-case-03", "chapter": 6, "type": "case", "number": 3, "stem": "K.L., a 37-year-old man who presents after a motorcycle collision, has sustained several orthopedic and chest injuries. K.L. has been mechanically ventilated for 8 days, during which time he was given a diagnosis of VAP caused by Klebsiella pneumoniae. K.L. received appropriate empiric antibiotic therapy and has improved oxygenation, decreased WBC temperature curve. Which would be the best duration of definitive antibiotic therapy for K.L.’s VAP?", "context": "", "options": [{"key": "A", "text": "24 hours after resolution of clinical signs and symptoms.", "sourceKey": "A"}, {"key": "B", "text": "7 days.", "sourceKey": "B"}, {"key": "C", "text": "10 days.", "sourceKey": "C"}, {"key": "D", "text": "14 days. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 236", "sourceKey": "D"}], "answer": "B", "explanation": "Based on the PneumA trial and related meta-analyses, the most recent IDSA VAP guidelines recommend definitive antibiotic therapy duration of 7 full treatment days for all patients. This is further emphasized in this patient, who has VAP caused by Klebsiella spp., which are lactose-fermenting gram-negative bacilli, and who received appropriate empiric antibiotic therapy and had an appropriate clinical response during therapy (Answer B is correct; Answers A, C, and D are incorrect).", "page": 15, "answerPage": 65, "stemZh": "K.L. 為 37 歲男性，機車事故後有多處 orthopedic 及 chest injuries。Mechanical ventilation 已 8 天，期間診斷 K. pneumoniae VAP。接受適當 empiric antibiotics 後，oxygenation 改善，WBC 與發燒趨勢下降。Definitive antibiotic therapy 最佳療程為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Clinical signs 與 symptoms 消失後 24 小時。"}, {"key": "B", "text": "7 天。"}, {"key": "C", "text": "10 天。"}, {"key": "D", "text": "14 天。"}], "explanationZh": "依原教材的 IDSA VAP recommendations，適當治療且有良好 clinical response 的 VAP 使用完整 7 天療程。"}, {"id": "06-case-04", "chapter": 6, "type": "case", "number": 4, "stem": "T.W. is a 47-year-old woman admitted to the MICU with respiratory failure secondary to severe 2009 H1N1 influenza infection. T.W., who requires intubation and mechanical ventilation, is given a diagnosis of septic shock associated with influenza and a secondary MSSA pneumonia. An internal jugular vein CVC was placed in the ED during acute resuscitation. T.W. continues to require a CVC. Although her hypotension and fever resolved 72 hours post-admission, she has a new temperature of 101.7°F (38.7°C) with worsening leukocytosis on ICU day 5; there is no change on her chest radiograph. Which action would be best to take next?", "context": "", "options": [{"key": "A", "text": "Initiate broad-spectrum antibiotic therapy for a new sepsis episode.", "sourceKey": "A"}, {"key": "B", "text": "Perform bronchoscopic BAL for suspected VAP.", "sourceKey": "B"}, {"key": "C", "text": "Remove CVC.", "sourceKey": "C"}, {"key": "D", "text": "Send two sets of blood cultures, one from the catheter and one from a peripheral blood sample. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 240", "sourceKey": "D"}], "answer": "D", "explanation": "In the absence of other suspected sources (i.e., no change in chest radiograph), CLABSI should be suspected as the cause of new-onset fever and leukocytosis, given the emergency placement and related duration of the CVC (Answer B is incorrect). Although catheter removal should strongly be considered, cultures should be obtained before catheter removal for documentation if the patient has a bloodstream infection (Answer C is incorrect). Initiation of antibiotic therapy should be considered, if appropriate, but only after cultures of the suspected source are obtained (Answer D is correct; Answer A is incorrect).", "page": 19, "answerPage": 65, "stemZh": "T.W. 為 47 歲女性，因 severe 2009 H1N1 influenza 所致 respiratory failure 入住 MICU，需插管及 mechanical ventilation，另有 influenza-associated septic shock 與 secondary MSSA pneumonia。急救時於 ED 放置 internal jugular CVC，目前仍需此導管。入院 72 小時後 hypotension 與 fever 已緩解，但 ICU 第 5 天新發 temperature 101.7°F（38.7°C）及 leukocytosis 惡化；chest radiograph 無變化。下一步最佳處置為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "為新發 sepsis 開始 broad-spectrum antibiotics。"}, {"key": "B", "text": "因疑似 VAP 做 bronchoscopic BAL。"}, {"key": "C", "text": "移除 CVC。"}, {"key": "D", "text": "採兩組 blood cultures，一組來自 catheter，一組來自 peripheral blood。"}], "explanationZh": "無新的肺部影像變化，應考慮 CLABSI；移除導管或開始新療法前先採 paired catheter/peripheral blood cultures。"}, {"id": "06-case-05", "chapter": 6, "type": "case", "number": 5, "stem": "Which regimen would be best to consider for empiric management of a suspected CLABSI?", "context": "F.P. is a 29-year-old man admitted to the MICU from another hospital with severe, alcohol-induced, sterile acute pancreatitis. During his 5-day stay at the outside hospital, he had multiple organ failure, including respiratory failure requiring tracheostomy. A right internal jugular CVC was placed on the patient’s admission to the outside hospital. On MICU day 3, F.P. has a maximum temperature of 102°F (38.9°C). Two sets of blood cultures are obtained; the right internal jugular catheter is removed and the tip sent for culture.", "options": [{"key": "A", "text": "Daptomycin and ceftriaxone.", "sourceKey": "A"}, {"key": "B", "text": "Fluconazole.", "sourceKey": "B"}, {"key": "C", "text": "Linezolid and cefepime.", "sourceKey": "C"}, {"key": "D", "text": "Vancomycin, cefepime, and tobramycin.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient, who is thought to have a CLABSI, has risk factors for MDROs, given that the patient was hospitalized for 5 or more days. Empiric antibiotic therapy choices should include agents active against MRSE and MRSA as well as P. aeruginosa (Answer D is correct; Answer A is incorrect). Linezolid is active against MRSA; however, it should be considered only for definitive therapy because its empiric use in patients with a CLABSI is associated with worse outcomes (Answer C is incorrect). Fluconazole may be considered in addition to antibiotic therapy, but monotherapy is not recommended empirically (Answer B is incorrect).", "page": 20, "answerPage": 65, "stemZh": "對疑似 CLABSI 的 empiric management，最適合考量哪個 regimen？", "contextZh": "F.P. 為 29 歲男性，因 severe alcohol-induced sterile acute pancreatitis 從外院轉至 MICU。外院住院 5 天期間發生 multiple organ failure，包括需 tracheostomy 的 respiratory failure；外院入院時放置 right internal jugular CVC。MICU 第 3 天最高 temperature 102°F（38.9°C），採取兩組 blood cultures，移除 right internal jugular catheter 並送 tip culture。", "optionsZh": [{"key": "A", "text": "Daptomycin 與 ceftriaxone."}, {"key": "B", "text": "Fluconazole."}, {"key": "C", "text": "Linezolid 與 cefepime."}, {"key": "D", "text": "Vancomycin, cefepime, 與 tobramycin."}], "explanationZh": "住院 ≥5 天提示 MDR risk；vancomycin、cefepime、tobramycin 可涵蓋題目需要的 MRSA/MRSE 與 P. aeruginosa。"}, {"id": "06-case-06", "chapter": 6, "type": "case", "number": 6, "stem": "F.P. is found to have K. pneumoniae CLABSI and receives appropriate empiric antibiotic therapy. He has had a good clinical response with no persistence of bacteremia. Which represents the best duration of F.P.’s definitive antibiotic therapy for CLABSI?", "context": "F.P. is a 29-year-old man admitted to the MICU from another hospital with severe, alcohol-induced, sterile acute pancreatitis. During his 5-day stay at the outside hospital, he had multiple organ failure, including respiratory failure requiring tracheostomy. A right internal jugular CVC was placed on the patient’s admission to the outside hospital. On MICU day 3, F.P. has a maximum temperature of 102°F (38.9°C). Two sets of blood cultures are obtained; the right internal jugular catheter is removed and the tip sent for culture.", "options": [{"key": "A", "text": "5 days.", "sourceKey": "A"}, {"key": "B", "text": "14 days.", "sourceKey": "B"}, {"key": "C", "text": "21 days.", "sourceKey": "C"}, {"key": "D", "text": "4 weeks.", "sourceKey": "D"}], "answer": "B", "explanation": "The guideline recommendation for definitive antibiotic therapy duration is 7–14 days from the first negative blood culture in patients with uncomplicated gramnegative CLABSI. Longer durations of therapy should be considered in patients with persistent bacteremia or if the patient has a poor clinical response. (Answer B is correct; Answers A and C are incorrect). Patients with complicated bacteremia (e.g., endocarditis, septic thrombus, chronic intravascular hardware) should receive 4-6 weeks of therapy (Answer D is incorrect).", "page": 20, "answerPage": 65, "stemZh": "F.P. 確診 K. pneumoniae CLABSI 並接受適當 empiric antibiotics，clinical response 良好，無 persistent bacteremia。最佳 definitive antibiotic therapy 療程為何？", "contextZh": "F.P. 為 29 歲男性，因 severe alcohol-induced sterile acute pancreatitis 從外院轉至 MICU。外院住院 5 天期間發生 multiple organ failure，包括需 tracheostomy 的 respiratory failure；外院入院時放置 right internal jugular CVC。MICU 第 3 天最高 temperature 102°F（38.9°C），採取兩組 blood cultures，移除 right internal jugular catheter 並送 tip culture。", "optionsZh": [{"key": "A", "text": "5 天。"}, {"key": "B", "text": "14 天。"}, {"key": "C", "text": "21 天。"}, {"key": "D", "text": "4 週。"}], "explanationZh": "Uncomplicated gram-negative CLABSI 原教材建議自首次 negative blood culture 起 7–14 天；本題選項中 14 天最適合。"}, {"id": "06-case-07", "chapter": 6, "type": "case", "number": 7, "stem": "Which intervention is most appropriate in P.H.?", "context": "P.H. is a 67-year-old woman admitted from a long-term care facility to the MICU for respiratory failure secondary to severe pneumonia. P.H. is initiated on vancomycin and levofloxacin and has a urethral catheter placed in the emergency department. On ICU day 6, P.H. has a new fever with a temperature of 101.9°F (38.9°C) and an elevated WBC to 18 x 103 cells/mm3, despite an initial clinical response to pneumonia therapy. Blood and urine cultures are sent. Urinalysis reveals many bacteria and greater than 10 white blood cells/mm3.", "options": [{"key": "A", "text": "Await final culture results before changing the current antibiotic regimen.", "sourceKey": "A"}, {"key": "B", "text": "Continue pneumonia therapy for an extended treatment duration.", "sourceKey": "B"}, {"key": "C", "text": "Initiate empiric antibiotic therapy for a suspected catheter-associated urinary tract infection (CAUTI).", "sourceKey": "C"}, {"key": "D", "text": "Insert a new urinary catheter and resend a urinalysis to confirm CAUTI.", "sourceKey": "D"}], "answer": "C", "explanation": "The presence of new fever and an elevated WBC in conjunction with an indwelling urinary catheter and pyuria on urinalysis is highly suggestive of a CAUTI rather than worsening pneumonia (Answer B is incorrect). Similar to other ICU-related infections, empiric ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 286 antibiotic therapy should be considered if there is strong clinical suspicion for infection (Answer C is correct). Waiting for final culture results before initiating antimicrobial therapy in patients thought to have a CAUTI may delay appropriate treatment (Answer A is incorrect). Although it is recommended to discontinue the urinary catheter and replace as necessary, a confirmatory urinalysis is not needed if the catheter has been indwelling for less than 2 weeks (Answer D is incorrect).", "page": 23, "answerPage": 65, "stemZh": "P.H. 最適合的處置為何？", "contextZh": "P.H. 為 67 歲女性，從 long-term care facility 因 severe pneumonia 所致 respiratory failure 入住 MICU，開始 vancomycin 與 levofloxacin，ED 放置 urethral catheter。肺炎曾有初始 clinical response，但 ICU 第 6 天新發 temperature 101.9°F（38.9°C），WBC 18 x 103 cells/mm3。已送 blood 及 urine cultures；urinalysis 有大量 bacteria 及 >10 white blood cells/mm3。", "optionsZh": [{"key": "A", "text": "等待 final culture 才調整目前 antibiotic regimen。"}, {"key": "B", "text": "延長 pneumonia therapy 療程。"}, {"key": "C", "text": "因疑似 CAUTI 開始 empiric antibiotics。"}, {"key": "D", "text": "插入新 urinary catheter 並重送 urinalysis 確認 CAUTI。"}], "explanationZh": "新發 fever、leukocytosis、indwelling catheter 與 pyuria 提示 CAUTI，應依臨床疑慮開始 empiric treatment。"}, {"id": "06-case-08", "chapter": 6, "type": "case", "number": 8, "stem": "Given P.H.’s risk factors for multidrug-resistant pathogens, which listing of pathogen would most likely be associated with a CAUTI?", "context": "P.H. is a 67-year-old woman admitted from a long-term care facility to the MICU for respiratory failure secondary to severe pneumonia. P.H. is initiated on vancomycin and levofloxacin and has a urethral catheter placed in the emergency department. On ICU day 6, P.H. has a new fever with a temperature of 101.9°F (38.9°C) and an elevated WBC to 18 x 103 cells/mm3, despite an initial clinical response to pneumonia therapy. Blood and urine cultures are sent. Urinalysis reveals many bacteria and greater than 10 white blood cells/mm3.", "options": [{"key": "A", "text": "E. coli, P. aeruginosa, C. albicans.", "sourceKey": "A"}, {"key": "B", "text": "Enterococcus spp., C. albicans, S. maltophilia.", "sourceKey": "B"}, {"key": "C", "text": "MRSA, Enterococcus spp., C. albicans.", "sourceKey": "C"}, {"key": "D", "text": "P. aeruginosa, Enterococcus spp., MRSA.", "sourceKey": "D"}], "answer": "A", "explanation": "The causative pathogens associated with a CAUTI, with or without multidrug-resistant risk factors, are more heterogeneous than an uncomplicated or communityacquired urinary tract infection. Nonetheless, E. coli remains the most common bacterial pathogen together with other gram-negative bacilli and Candida spp. (Answer A is correct). Except for S. maltophilia (Answer B is incorrect), other associated pathogens include those listed in Answers B–D; however, the absence of E. coli makes these answers incorrect.", "page": 23, "answerPage": 66, "stemZh": "考量 P.H. 的 MDR risk factors，哪一組 pathogens 最可能與 CAUTI 有關？", "contextZh": "P.H. 為 67 歲女性，從 long-term care facility 因 severe pneumonia 所致 respiratory failure 入住 MICU，開始 vancomycin 與 levofloxacin，ED 放置 urethral catheter。肺炎曾有初始 clinical response，但 ICU 第 6 天新發 temperature 101.9°F（38.9°C），WBC 18 x 103 cells/mm3。已送 blood 及 urine cultures；urinalysis 有大量 bacteria 及 >10 white blood cells/mm3。", "optionsZh": [{"key": "A", "text": "E. coli, P. aeruginosa, C. albicans."}, {"key": "B", "text": "Enterococcus spp., C. albicans, S. maltophilia."}, {"key": "C", "text": "MRSA, Enterococcus spp., C. albicans."}, {"key": "D", "text": "P. aeruginosa, Enterococcus spp., MRSA."}], "explanationZh": "CAUTI 病原較多元，但 E. coli 仍最常見；選項 A 同時涵蓋 gram-negative organisms 與 Candida。"}, {"id": "06-case-09", "chapter": 6, "type": "case", "number": 9, "stem": "D.L. is a 69-year-old woman admitted from home to the SICU with severe acute abdominal pain in the left lower quadrant. An abdominal CT reveals free air in the peritoneal cavity and evidence of distal ischemic colitis. D.L. is taken urgently to the operating room, where she is noted to have gross contamination from distal colonic perforation with marked peritonitis. After a partial colectomy and abdominal washout, she is admitted to the SICU for continued resuscitation for septic shock. Which empiric antibiotic regimen would be most appropriate for D.L.?", "context": "", "options": [{"key": "A", "text": "Ceftriaxone and vancomycin.", "sourceKey": "A"}, {"key": "B", "text": "Ciprofloxacin and metronidazole.", "sourceKey": "B"}, {"key": "C", "text": "Ertapenem.", "sourceKey": "C"}, {"key": "D", "text": "Piperacillin/tazobactam.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient has complicated intra-abdominal infection from secondary peritonitis caused by colonic perforation. Although it is community acquired, the presence of septic shock suggests severe classification increasing the risk of gram-negative MDROs (Answer C is incorrect). The involvement of the colon also obligates antibiotic therapy active against anaerobes and enterococci (Answer B is incorrect); MRSA is an unlikely pathogen (Answer A is incorrect). According to this, piperacillin/tazobactam is the most appropriate agent listed (Answer D is correct).", "page": 27, "answerPage": 66, "stemZh": "D.L. 為 69 歲女性，從家中因 severe acute left-lower-quadrant abdominal pain 入住 SICU。CT 顯示 peritoneal free air 及 distal ischemic colitis。緊急手術發現 distal colonic perforation、gross contamination 與 marked peritonitis；partial colectomy 及 abdominal washout 後，持續在 SICU 為 septic shock 復甦。最適合的 empiric antibiotic regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Ceftriaxone 與 vancomycin."}, {"key": "B", "text": "Ciprofloxacin 與 metronidazole."}, {"key": "C", "text": "Ertapenem."}, {"key": "D", "text": "Piperacillin/tazobactam."}], "explanationZh": "Severe colonic-source infection 需涵蓋 gram-negative MDR pathogens、anaerobes 與 enterococci，選 piperacillin/tazobactam。"}, {"id": "06-case-10", "chapter": 6, "type": "case", "number": 10, "stem": "K.D. is a 58-year-old man with severe peripheral vascular disease admitted from home to the SICU with severe acute abdominal pain in the left lower quadrant. An emergency abdominal CT reveals free air in the peritoneal cavity and evidence of distal small bowel ischemia. K.D. is taken emergently to the operating room for an exploratory laparotomy, where he is noted to have gross peritoneal contamination with marked peritonitis from a small bowel perforation. Intraoperative cultures were sent and are pending. After primary repair of the distal small bowel and abdominal washout, K.D. returns to the SICU for continued resuscitation for septic shock. Which empiric antibiotic regimen would be most appropriate for K.D.?", "context": "", "options": [{"key": "A", "text": "Piperacillin/tazobactam.", "sourceKey": "A"}, {"key": "B", "text": "Ertapenem.", "sourceKey": "B"}, {"key": "C", "text": "Ciprofloxacin and vancomycin.", "sourceKey": "C"}, {"key": "D", "text": "Cefazolin, metronidazole, and fluconazole.", "sourceKey": "D"}], "answer": "A", "explanation": "The approach to managing a complicated intra-abdominal infection includes timely source control and initiation of empiric antimicrobial therapy active against likely pathogens. This involves assessment of the anatomic location of the source, risk factors for multidrug-resistant organisms (i.e., community- or health care–associated disposition), and severity of illness. This patient has community-acquired secondary peritonitis from a distal small bowel perforation with concomitant septic shock. Although his disease is community acquired, the presence of septic shock suggests a severe classification, increasing the risk of gram-negative multidrug-resistant organisms and involvement of the distal small bowel obligates empiric coverage for anaerobic pathogens and enterococci, for all of which piperacillin/tazobactam should provide appropriate empiric coverage (Answer A is correct). Ertapenem would likely have adequate empiric coverage for enteric, gram-negative pathogens, both aerobic and anaerobic; however, lack or enterococcal coverage makes it less optimal (Answer B is incorrect). Ciprofloxacin lacks sufficient activity against enterococci or anaerobic pathogens, and MRSA coverage with vancomycin is unnecessary (Answer C is incorrect). Cefazolin is too narrow as empiric therapy for a severe community-acquired complicated intraabdominal infection, and fluconazole should be reserved for definitive therapy for fluconazole-susceptible yeast identified on final culture (Answer D is incorrect).", "page": 27, "answerPage": 66, "stemZh": "K.D. 為 58 歲男性，有 severe peripheral vascular disease，從家中因 severe acute left-lower-quadrant abdominal pain 入住 SICU。緊急 CT 顯示 peritoneal free air 與 distal small-bowel ischemia。Exploratory laparotomy 發現 small-bowel perforation 引起 gross peritoneal contamination 與 marked peritonitis；術中 cultures 已送驗。完成 distal small-bowel primary repair 與 abdominal washout 後，返回 SICU 持續為 septic shock 復甦。最適合的 empiric regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Piperacillin/tazobactam."}, {"key": "B", "text": "Ertapenem."}, {"key": "C", "text": "Ciprofloxacin 與 vancomycin."}, {"key": "D", "text": "Cefazolin, metronidazole, 與 fluconazole."}], "explanationZh": "Septic shock 與 distal small-bowel source 需廣泛 gram-negative、anaerobic 與 enterococcal coverage，piperacillin/tazobactam 最完整。"}, {"id": "06-case-11", "chapter": 6, "type": "case", "number": 11, "stem": "R.P. is a 43-year-old man with a history of chronic alcohol abuse who presents to the emergency department from home with acute, severe epigastric abdominal pain; heart rate 142 beats/minute; MAP 62 mm Hg; WBC 24 x 103 cells/mm3; and serum lipase 1527 U/L. R.P. receives 3 L of normal saline intravenously over 60 minutes. An immediate abdominal CT scan is remarkable for significant pancreatic edema and greater than 30% necrosis of the pancreas. There is no evidence of an acute fluid collection. Which antimicrobial regimen would be most appropriate for R.P.?", "context": "", "options": [{"key": "A", "text": "Ceftriaxone and vancomycin.", "sourceKey": "A"}, {"key": "B", "text": "Ciprofloxacin and metronidazole.", "sourceKey": "B"}, {"key": "C", "text": "Meropenem.", "sourceKey": "C"}, {"key": "D", "text": "None; prophylactic antibiotic therapy is not indicated in acute pancreatitis.", "sourceKey": "D"}], "answer": "D", "explanation": "Acute necrotizing pancreatitis often presents with signs and symptoms consistent with systemic inflammatory response syndrome. However, most cases of severe necrotizing pancreatitis are sterile and do not require antibiotic therapy. The presence of a pancreatic pseudocyst or abscess increases the likelihood of infected necrotizing pancreatitis, which thus warrants empiric antimicrobial therapy. However, this patient has no evidence of these on CT scan; thus, empiric antibiotic therapy is not indicated (Answers A–C are incorrect). Moreover, prophylactic antimicrobial therapy is not recommended in the recent guidelines, despite the presentation of systemic inflammation and pancreatic necrosis (Answer D is correct). A prospective, randomized, noninferiority study most strongly supports these recommendations.", "page": 30, "answerPage": 66, "stemZh": "R.P. 為 43 歲男性，有 chronic alcohol abuse，從家中因 acute severe epigastric pain 至 ED；HR 142 beats/minute、MAP 62 mm Hg、WBC 24 x 103 cells/mm3、lipase 1527 U/L。60 分鐘內接受 3 L IV normal saline。CT 有 marked pancreatic edema 及 >30% pancreatic necrosis，但無 acute fluid collection。最適合的 antimicrobial regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Ceftriaxone 與 vancomycin。"}, {"key": "B", "text": "Ciprofloxacin 與 metronidazole。"}, {"key": "C", "text": "Meropenem。"}, {"key": "D", "text": "不給；acute pancreatitis 無 prophylactic antibiotics 適應症。"}], "explanationZh": "Sterile necrotizing pancreatitis 可出現 SIRS；無感染證據時不使用 prophylactic antibiotics。"}, {"id": "06-case-12", "chapter": 6, "type": "case", "number": 12, "stem": "T.J. is a 27-year-old man who is admitted to the MICU from an outside hospital with alcohol-induced acute pancreatitis and associated respiratory failure, SIRS, and blood pressure 100/55 mm Hg. Admission abdominal CT shows severe pancreatitis with about 30% necrosis and a large focal fluid collection requiring guided drainage. A fluid sample is sent for a Gram stain, which reveals many gram-negative rods and yeast. Which antimicrobial regimen would best be initiated in T.J.?", "context": "", "options": [{"key": "A", "text": "None – low suspicion for infected pancreatitis.", "sourceKey": "A"}, {"key": "B", "text": "Ciprofloxacin and metronidazole.", "sourceKey": "B"}, {"key": "C", "text": "Imipenem.", "sourceKey": "C"}, {"key": "D", "text": "Meropenem and fluconazole.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient has acute, severe pancreatitis with CT evidence of pancreatic abscess. Gram stain of fluid obtained from CT-guided drainage suggests the presence of gram-negative bacilli and yeast (Answer A is incorrect). Empiric antimicrobial therapy is indicated for suspected infected pancreatitis. Extended-spectrum carbapenems, which achieve relevant pancreatic fluid concentrations, are effective in the management of infected pancreatitis. Addition of anti-candidal therapy is indicated, given the presence of yeast on the Gram stain (Answer D is correct; Answers B and C are incorrect). ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 287", "page": 30, "answerPage": 66, "stemZh": "T.J. 為 27 歲男性，因 alcohol-induced acute pancreatitis、respiratory failure、SIRS 與 BP 100/55 mm Hg 自外院轉入 MICU。入院 CT 顯示 severe pancreatitis、約 30% necrosis，以及需 guided drainage 的大型 focal fluid collection。引流液 Gram stain 有大量 gram-negative rods 與 yeast。最適合開始哪個 antimicrobial regimen？", "contextZh": "", "optionsZh": [{"key": "A", "text": "不給；infected pancreatitis 疑慮低。"}, {"key": "B", "text": "Ciprofloxacin 與 metronidazole。"}, {"key": "C", "text": "Imipenem。"}, {"key": "D", "text": "Meropenem 與 fluconazole。"}], "explanationZh": "本題有 infected pancreatic collection 及 yeast 證據，需適當 antibacterial 並加入 anti-Candida therapy。"}, {"id": "06-case-13", "chapter": 6, "type": "case", "number": 13, "stem": "K.L. is a 57-year-old man admitted to the MICU with diffuse abdominal pain, temperature 101.9°F (38.8°C), WBC 27 x 103 cells/mm3, heart rate 125 beats/minute, and mean arterial pressure 57 mm Hg. An abdominal CT scan reveals a large amount of intestinal air, suggestive of ileus and moderate transverse and sigmoid colonic inflammation. On review of the patient’s history, it is learned that K.L. recently completed a 4-week course of broad-spectrum antibiotic therapy for a postoperative osteomyelitis after repair of right comminuted femur fracture, increasing the suggestion of CDI. Which regimen would be best for empiric management of a suspected CDI in K.L.?", "context": "", "options": [{"key": "A", "text": "Metronidazole 500 mg intravenously every 8 hours.", "sourceKey": "A"}, {"key": "B", "text": "Vancomycin 500 mg orally/by nasogastric tube/feeding tube four times daily, metronidazole 500 mg intravenously every 8 hours, and intracolonic vancomycin 500 mg instilled every 8 hours.", "sourceKey": "B"}, {"key": "C", "text": "Metronidazole 500 mg orally or by nasogastric tube every 8 hours and vancomycin 250 mg orally or by nasogastric tube every 6 hours.", "sourceKey": "C"}, {"key": "D", "text": "Vancomycin 250 mg orally or by nasogastric tube every 6 hours.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient is thought to have fulminant (IDSA 2017) CDI, given his recent exposure to broad-spectrum antibiotic therapy, signs of infection, CT findings, and the presence of hypotension. Combination therapy with metronidazole and enteral vancomycin is indicated (Answers A and D are incorrect). The presence of ileus requires consideration of adding intracolonic vancomycin because of possible impaired delivery to the colon through enteral routes (Answer B is correct; Answer C is incorrect).", "page": 37, "answerPage": 67, "stemZh": "K.L. 為 57 歲男性，因 diffuse abdominal pain、temperature 101.9°F（38.8°C）、WBC 27 x 103 cells/mm3、HR 125 beats/minute、MAP 57 mm Hg 入住 MICU。CT 見大量 intestinal air，提示 ileus，另有 moderate transverse 及 sigmoid colonic inflammation。右 comminuted femur fracture 修復後發生 postoperative osteomyelitis，近期剛完成 4 週 broad-spectrum antibiotics，增加 CDI 疑慮。疑似 CDI 的最佳 empiric regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Metronidazole 500 mg IV，每 8 小時。"}, {"key": "B", "text": "Vancomycin 500 mg 口服／經鼻胃管／feeding tube，每日 4 次，合併 metronidazole 500 mg IV 每 8 小時及 intracolonic vancomycin 500 mg 每 8 小時灌注。"}, {"key": "C", "text": "Metronidazole 500 mg 口服或經鼻胃管，每 8 小時，合併 vancomycin 250 mg 口服或經鼻胃管，每 6 小時。"}, {"key": "D", "text": "Vancomycin 250 mg 口服或經鼻胃管，每 6 小時。"}], "explanationZh": "Hypotension 與 ileus 符合 fulminant CDI 情境，需 enteral vancomycin 合併 IV metronidazole，並因 ileus 考慮 intracolonic vancomycin。"}, {"id": "06-case-14", "chapter": 6, "type": "case", "number": 14, "stem": "E.A. is a 79-year-old man admitted to the MICU for severe pneumonia. On day 5 of treatment with broadspectrum antibiotic therapy despite negative culture, E.A. is noted to have several liquid bowel movements requiring a rectal pouch (around 1.6 L of stool in past 24 hours), a low-grade fever, elevation of WBC at 27 x 103 cells/mm3, heart rate 124 beats/minute, MAP 67 mm Hg, lactate 1.6 mmol/L, and SCr 1.5 mg/dL. A stool sample is sent for a suspected C. difficile infection (CDI). Which regimen would be the best empiric management of a suspected CDI in E.A.?", "context": "", "options": [{"key": "A", "text": "Metronidazole 500 mg intravenously every 8 hours and intracolonic vancomycin 500 mg instilled every 8 hours.", "sourceKey": "A"}, {"key": "B", "text": "Metronidazole 500 mg intravenously every 8 hours.", "sourceKey": "B"}, {"key": "C", "text": "Metronidazole 500 mg orally or by nasogastric tube every 8 hours and vancomycin 125 mg orally or by nasogastric tube every 6 hours.", "sourceKey": "C"}, {"key": "D", "text": "Vancomycin 125 mg orally or by nasogastric tube every 6 hours.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient in this case presents with what is likely an initial-episode, severe CDI, as supported by new-onset diarrhea and clinical signs and symptoms of infection. Of note, the patient is not hypotensive and has a lactate below 2–4 mmol/L, suggesting the absence of shock or other defining features of fulminant CDI; thus, monotherapy with enteral vancomycin is the best available answer (Answer D is correct). Although the 2021 IDSA/ SHEA focused guideline update recommends fidaxomicin for non-fulminant, first-episode CDI, oral/enteral vancomycin is an acceptable alternative, especially if fidaxomicin is unavailable. Combination therapy with oral/enteral vancomycin and intravenous metronidazole should be reserved for a complicated CDI (Answer C is incorrect), and intravenous metronidazole is not recommended (Answer B is incorrect). The combination of metronidazole and intracolonic is recommended for patients with a complicated CDI and concern for ileus or inability to deliver oral/enteral vancomycin to the colon (Answer A is incorrect).", "page": 37, "answerPage": 67, "stemZh": "E.A. 為 79 歲男性，因 severe pneumonia 入住 MICU，cultures 陰性仍接受 broad-spectrum antibiotics。治療第 5 天有多次 liquid stools，需 rectal pouch（過去 24 小時約 1.6 L），low-grade fever、WBC 27 x 103 cells/mm3、HR 124 beats/minute、MAP 67 mm Hg、lactate 1.6 mmol/L、SCr 1.5 mg/dL。已送 stool 檢體評估 CDI。最佳 empiric regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Metronidazole 500 mg IV 每 8 小時，合併 intracolonic vancomycin 500 mg 每 8 小時灌注。"}, {"key": "B", "text": "Metronidazole 500 mg IV，每 8 小時。"}, {"key": "C", "text": "Metronidazole 500 mg 口服或經鼻胃管，每 8 小時，合併 vancomycin 125 mg 口服或經鼻胃管，每 6 小時。"}, {"key": "D", "text": "Vancomycin 125 mg 口服或經鼻胃管，每 6 小時。"}], "explanationZh": "本題 severe 但無 fulminant 特徵；可用 enteral vancomycin。Fidaxomicin 雖為原教材引用更新的優先選項，但未列於選項。"}, {"id": "06-case-15", "chapter": 6, "type": "case", "number": 15, "stem": "Which empiric antimicrobial regimen is most appropriate for R.J.?", "context": "R.J. is a 57-year-old man admitted to the SICU after a bowel resection following an acute bowel obstruction. On postoperative day 3, R.J. has worsening tachycardia and decreased urinary output together with a maximum temperature of 102.9°F (39.4°C) and a WBC of 18.2 x 103 cells/mm3. R.J. reports worsening pain around his large abdominal surgical wound despite minimal erythema. On opening a few sutures of the wound, pus is expressed on examination, and crepitus is noted in the area surrounding the wound. R.J. is emergently taken to the operating room for exploration and is noted to require significant debridement of necrotic subcutaneous tissue, including the involved fascia. R.J.’s wound is left open with a temporary gauze dressing.", "options": [{"key": "A", "text": "Ceftaroline and vancomycin.", "sourceKey": "A"}, {"key": "B", "text": "Clindamycin, penicillin G, and vancomycin.", "sourceKey": "B"}, {"key": "C", "text": "Piperacillin/tazobactam, clindamycin, and vancomycin.", "sourceKey": "C"}, {"key": "D", "text": "Clindamycin and linezolid.", "sourceKey": "D"}], "answer": "C", "explanation": "Necrotizing fasciitis is a severe, life-threatening infection that is often polymicrobial. Prompt surgical debridement of necrotic tissue and broad-spectrum antibiotic therapy are the mainstays of initial therapy. Agents active against S. pyogenes, MRSA, and aerobic and anaerobic gram-negative bacilli should be initiated empirically, together with adjunctive clindamycin added, which may decrease bacterial toxin production. The empiric regimen of piperacillin/tazobactam, vancomycin, and clindamycin is most appropriate, given the severity of infection despite the absence of traditional multidrug-resistant organism risk factors (Answer C is correct). Penicillin G is not broad enough (Answer B is incorrect), and the combination of ceftaroline and vancomycin does not contain clindamycin (Answer A is incorrect). Combination of clindamycin and linezolid do not include empiric gram-negative coverage. (Answer D is incorrect).", "page": 41, "answerPage": 67, "stemZh": "R.J. 最適合哪個 empiric antimicrobial regimen？", "contextZh": "R.J. 為 57 歲男性，因 acute bowel obstruction 接受 bowel resection 後入住 SICU。術後第 3 天 tachycardia 惡化、urine output 下降，最高 temperature 102.9°F（39.4°C）、WBC 18.2 x 103 cells/mm3。腹部大型 surgical wound 疼痛惡化但 erythema 很少。打開部分 sutures 後有 pus，周邊可見 crepitus。緊急手術發現需大量 debridement 的 necrotic subcutaneous tissue，包括 fascia。傷口維持開放，以 gauze 暫時覆蓋。", "optionsZh": [{"key": "A", "text": "Ceftaroline 與 vancomycin."}, {"key": "B", "text": "Clindamycin, penicillin G, 與 vancomycin."}, {"key": "C", "text": "Piperacillin/tazobactam, clindamycin, 與 vancomycin."}, {"key": "D", "text": "Clindamycin 與 linezolid."}], "explanationZh": "Necrotizing fasciitis 需緊急 debridement、廣效 antibiotics 及降低 toxin production 的 adjunctive clindamycin。"}, {"id": "06-case-16", "chapter": 6, "type": "case", "number": 16, "stem": "Intraoperative tissue culture from the first debridement of R.J.’s wound shows many gram-positive cocci in chains and moderate non–lactose-fermenting gram-negative bacilli. R.J. is to undergo serial intraoperative debridements of necrotic tissue. Given the concern for S. pyogenes from the Gram stain, which pharmacotherapeutic intervention would be most appropriate for treatment of R.J.’s necrotizing fasciitis?", "context": "R.J. is a 57-year-old man admitted to the SICU after a bowel resection following an acute bowel obstruction. On postoperative day 3, R.J. has worsening tachycardia and decreased urinary output together with a maximum temperature of 102.9°F (39.4°C) and a WBC of 18.2 x 103 cells/mm3. R.J. reports worsening pain around his large abdominal surgical wound despite minimal erythema. On opening a few sutures of the wound, pus is expressed on examination, and crepitus is noted in the area surrounding the wound. R.J. is emergently taken to the operating room for exploration and is noted to require significant debridement of necrotic subcutaneous tissue, including the involved fascia. R.J.’s wound is left open with a temporary gauze dressing.", "options": [{"key": "A", "text": "Add synergistic gentamicin.", "sourceKey": "A"}, {"key": "B", "text": "Continue or initiate adjunctive clindamycin for toxin production.", "sourceKey": "B"}, {"key": "C", "text": "Ensure vancomycin is part of the regimen for concerns of S. pyogenes resistance.", "sourceKey": "C"}, {"key": "D", "text": "Give intravenous immunoglobulin (IVIG).", "sourceKey": "D"}], "answer": "B", "explanation": "The intraoperative cultures of this patient’s necrotizing infection are of concern for S. pyogenes. S. pyogenes produces exotoxin, which is associated with tissue necrosis. Although bactericidal antibiotic therapy is necessary for eradicating S. pyogenes, adjunctive clindamycin may decrease toxin production, which could limit the extent of tissue necrosis (Answer B is correct). Vancomycin should be reserved for patients with an S. pyogenes infection who have a β-lactam allergy because β-lactam resistance is rare (Answer C is incorrect). Moreover, synergistic antibiotic therapy with gentamicin is not needed, given the effectiveness of gram-positive β-lactams against S. pyogenes (Answer A is incorrect). The role of IVIG in streptococcal necrotizing fasciitis is controversial. A small randomized, placebo-controlled trial – stratified on the basis of need for surgery and clindamycin treatment – showed no improvement in survival or reduction in the time to no further progression of necrotizing fasciitis or cellulitis in 21 patients with streptococcal toxic shock syndrome. As such, the guidelines do not recommend IVIG until additional studies are available (Answer D is incorrect).", "page": 41, "answerPage": 67, "stemZh": "第一次 debridement 的 tissue culture 見大量 gram-positive cocci in chains 與中量 non–lactose-fermenting gram-negative bacilli，並將接受 serial debridements。Gram stain 提示 S. pyogenes，最適合的 pharmacotherapeutic intervention 為何？", "contextZh": "R.J. 為 57 歲男性，因 acute bowel obstruction 接受 bowel resection 後入住 SICU。術後第 3 天 tachycardia 惡化、urine output 下降，最高 temperature 102.9°F（39.4°C）、WBC 18.2 x 103 cells/mm3。腹部大型 surgical wound 疼痛惡化但 erythema 很少。打開部分 sutures 後有 pus，周邊可見 crepitus。緊急手術發現需大量 debridement 的 necrotic subcutaneous tissue，包括 fascia。傷口維持開放，以 gauze 暫時覆蓋。", "optionsZh": [{"key": "A", "text": "加入 synergistic gentamicin。"}, {"key": "B", "text": "持續或開始 adjunctive clindamycin，抑制 toxin production。"}, {"key": "C", "text": "因擔心 S. pyogenes resistance，確保 regimen 含 vancomycin。"}, {"key": "D", "text": "給 IVIG。"}], "explanationZh": "Adjunctive clindamycin 可降低 S. pyogenes toxin production；不需為罕見 β-lactam resistance 例行改用 vancomycin 或加入 synergistic gentamicin。"}, {"id": "06-case-17", "chapter": 6, "type": "case", "number": 17, "stem": "Which would be the best initial pharmacotherapeutic intervention?", "context": "L.H. is a 23-year-old woman with a recently diagnosed uncomplicated urinary tract infection. Two days after starting sulfamethoxazole/trimethoprim, L.H. presents to the burn ICU from an outside hospital with severe systemic inflammatory response and 30% total body surface area (TBSA) epidermolysis of her upper arms and back. L.H. reportedly presented to the outside hospital 6 hours earlier with only 10% TBSA involvement. New lesions since admission to the burn ICU include erythema of her thighs and oral cavity with TBSA now at 40%, suggestive of toxic epidermal necrolysis (TEN). L.H.’s SCORTEN score is 3.", "options": [{"key": "A", "text": "Crystalloid resuscitation.", "sourceKey": "A"}, {"key": "B", "text": "Cyclophosphamide.", "sourceKey": "B"}, {"key": "C", "text": "Empiric vancomycin for wound prophylaxis.", "sourceKey": "C"}, {"key": "D", "text": "High-dose systemic corticosteroids.", "sourceKey": "D"}], "answer": "A", "explanation": "One of the cornerstones of managing severe cutaneous injury includes volume resuscitation, preferentially with crystalloids (Answer A is correct). The usefulness of immunomodulating therapies such as corticosteroids and cyclophosphamide is limited by observational and poorly controlled evidence or case reports; thus, use of immunomodulating therapies should be reserved for specialty centers using formal protocols with consideration for treatment under clinical study or registry (Answers B and D are incorrect). Wound care is imperative in these patients; however, adding unnecessary drugs that could confound response or worsen the injury (e.g., antibiotics) should be avoided (Answer C is incorrect) unless there is an objectively suspected or confirmed infection. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 288", "page": 45, "answerPage": 67, "stemZh": "最佳初始 pharmacotherapeutic intervention 為何？", "contextZh": "L.H. 為 23 歲女性，近期診斷 uncomplicated UTI。開始 sulfamethoxazole/trimethoprim 2 天後，從外院轉至 burn ICU，出現 severe systemic inflammatory response，upper arms 與 back 有 30% TBSA epidermolysis。6 小時前在外院僅 10% TBSA involvement。入 burn ICU 後 thighs 及 oral cavity 新增 erythema，TBSA 達 40%，提示 TEN；SCORTEN score 3。", "optionsZh": [{"key": "A", "text": "Crystalloid resuscitation。"}, {"key": "B", "text": "Cyclophosphamide。"}, {"key": "C", "text": "以 empiric vancomycin 作 wound prophylaxis。"}, {"key": "D", "text": "High-dose systemic corticosteroids。"}], "explanationZh": "TEN 初始照護重點為 crystalloid volume resuscitation；不例行加入 antibiotic prophylaxis 或未充分驗證的 immunomodulating therapy。"}, {"id": "06-case-18", "chapter": 6, "type": "case", "number": 18, "stem": "L.H. continues to worsen, with a TBSA involvement now at 50%, with worsening oral cavity involvement and progressing acute kidney injury. You and your team consider IVIG as the next pharmacotherapeutic intervention. Which best describes the evidence-based role of IVIG in managing TEN?", "context": "L.H. is a 23-year-old woman with a recently diagnosed uncomplicated urinary tract infection. Two days after starting sulfamethoxazole/trimethoprim, L.H. presents to the burn ICU from an outside hospital with severe systemic inflammatory response and 30% total body surface area (TBSA) epidermolysis of her upper arms and back. L.H. reportedly presented to the outside hospital 6 hours earlier with only 10% TBSA involvement. New lesions since admission to the burn ICU include erythema of her thighs and oral cavity with TBSA now at 40%, suggestive of toxic epidermal necrolysis (TEN). L.H.’s SCORTEN score is 3.", "options": [{"key": "A", "text": "IVIG should be administered before the patient’s condition progresses to TEN.", "sourceKey": "A"}, {"key": "B", "text": "IVIG should be reserved for specialty centers with interdisciplinary consensus protocols to guide use.", "sourceKey": "B"}, {"key": "C", "text": "Multicenter pivotal trials show that IVIG is most efficacious for patients with ocular involvement.", "sourceKey": "C"}, {"key": "D", "text": "Meta-analyses of the available evidence support that IVIG is standard of care in managing TEN.", "sourceKey": "D"}], "answer": "B", "explanation": "Use of IVIG for Stevens-Johnson syndrome (SJS)/TEN is controversial. Available evidence is from case reports/ series, observational cohort studies, or small, singlecenter randomized trials (Answer C is incorrect). Because of bias, limited external validity, and mixed results/ observations between publications, meta-analyses and consensus guidelines do not broadly endorse the use of IVIG (Answer D is incorrect). The available data analyses that suggest that IVIG decreases the SCORTEN-related mortality in patients with TEN and a middle to higher SCORTEN score; there are even fewer data for the role of IVIG in SJS (Answer A is incorrect). Given the limited evidence supporting pharmacotherapeutic interventions and the life-threatening severity of TEN, burn referral centers should base the decision to use IVIG on local protocols/guidelines developed by interdisciplinary practitioners who have objectively evaluated the available evidence regarding safety, efficacy, and pharmacogenomic implications (Answer B is correct).", "page": 45, "answerPage": 68, "stemZh": "L.H. 持續惡化，TBSA 達 50%，oral cavity involvement 加重且 AKI 進展。團隊考慮 IVIG。下列何者最符合 IVIG 用於 TEN 的 evidence-based role？", "contextZh": "L.H. 為 23 歲女性，近期診斷 uncomplicated UTI。開始 sulfamethoxazole/trimethoprim 2 天後，從外院轉至 burn ICU，出現 severe systemic inflammatory response，upper arms 與 back 有 30% TBSA epidermolysis。6 小時前在外院僅 10% TBSA involvement。入 burn ICU 後 thighs 及 oral cavity 新增 erythema，TBSA 達 40%，提示 TEN；SCORTEN score 3。", "optionsZh": [{"key": "A", "text": "應在病情進展至 TEN 前給 IVIG。"}, {"key": "B", "text": "IVIG 應限於具跨專業 consensus protocols 的 specialty centers。"}, {"key": "C", "text": "Multicenter pivotal trials 顯示 IVIG 對 ocular involvement 最有效。"}, {"key": "D", "text": "Meta-analyses 支持 IVIG 為 TEN 的 standard of care。"}], "explanationZh": "IVIG 證據有限且結果不一致，非普遍標準療法；應由 specialty centers 依跨專業 consensus protocols 評估。"}, {"id": "06-case-19", "chapter": 6, "type": "case", "number": 19, "stem": "T.Y., a 32-year-old woman who has had flulike symptoms for the past 72 hours, presents to the ED from home with severe fatigue, shortness of breath, and rigors. T.Y. has a heart rate of 120 beats/minute, mean arterial pressure 70 mm Hg, respiratory rate 24 breaths/minute, temperature 102.7°F (39.3°C), and arterial oxygen saturation (SaO 2 ) of 85% on room air. Because it is in the middle of influenza season (high prevalence of influenza A and B), a nasal swab is done and sent for rapid diagnostic testing for suspected influenza infection. Shortly thereafter, T.Y. is intubated for severe respiratory failure and admitted to the MICU. In addition to antibiotic therapy for CAP, which would best be considered next?", "context": "", "options": [{"key": "A", "text": "None; the patient is outside the time window to effectively treat influenza.", "sourceKey": "A"}, {"key": "B", "text": "Await rapid diagnostic test results before initiating influenza-specific therapy.", "sourceKey": "B"}, {"key": "C", "text": "Give amantadine.", "sourceKey": "C"}, {"key": "D", "text": "Give oseltamivir.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient likely has severe influenza amid a local seasonal outbreak. Local infection patterns suggest a prevalence of influenza A and B strains. Empiric influenza-specific therapy against these strains should be initiated in patients with severe influenza before confirmatory test results are known to avoid a delay in appropriate therapy (Answer B is incorrect). Neuraminidase-based therapy is recommended for modern influenza A and B stains (Answer D is correct; Answer C is incorrect). Even if they are outside 48 hours from symptom onset, patients with severe influenza have benefited from therapy initiated beyond this period (Answer A is incorrect).", "page": 50, "answerPage": 68, "stemZh": "T.Y. 為 32 歲女性，過去 72 小時有 flulike symptoms，從家中因 severe fatigue、dyspnea 與 rigors 至 ED。HR 120 beats/minute、MAP 70 mm Hg、RR 24 breaths/minute、temperature 102.7°F（39.3°C）、room-air SaO2 85%。目前為 influenza 季節且 A/B prevalence 高，nasal swab 已送 rapid test。隨後因 severe respiratory failure 插管並入住 MICU。除 CAP antibiotics 外，下一步最適合考量何者？", "contextZh": "", "optionsZh": [{"key": "A", "text": "不給；已超過有效治療 influenza 的時間窗。"}, {"key": "B", "text": "等 rapid diagnostic test 結果再開始 influenza-specific therapy。"}, {"key": "C", "text": "給 amantadine。"}, {"key": "D", "text": "給 oseltamivir。"}], "explanationZh": "Severe influenza 即使症狀已超過 48 小時仍可受益於 treatment，無須等待確認檢驗；本題選 oseltamivir。"}, {"id": "06-case-20", "chapter": 6, "type": "case", "number": 20, "stem": "G.L. is a 25-year-old woman admitted to the medical ICU in late February this year with severe, acute hypoxemic respiratory failure requiring mechanical ventilation. G.L. is hypotensive, requiring norepinephrine after fluid resuscitation, and has acute kidney injury. She is awaiting a renal consult for continuous renal replacement therapy. A rapid diagnostic test of a nasal washing suggests influenza B, consistent with this year’s local influenza epidemiology. A nasogastric feeding tube is placed when she is admitted to the ICU. Which would be most appropriate to treat G.L.’s severe influenza?", "context": "", "options": [{"key": "A", "text": "Enteral amantadine.", "sourceKey": "A"}, {"key": "B", "text": "Enteral oseltamivir.", "sourceKey": "B"}, {"key": "C", "text": "Inhaled zanamivir.", "sourceKey": "C"}, {"key": "D", "text": "Intravenous peramivir.", "sourceKey": "D"}], "answer": "B", "explanation": "Neuraminidase inhibitors are the mainstay of treatment because resistance to adamantanes has developed in contemporary influenza A strains, and these agents have no antiviral activity against influenza B (Answer A is incorrect). Inhaled zanamivir is not appropriate for administration to mechanically ventilated patients (Answer C is incorrect). Intravenous peramivir also is available; however, data are limited for its use in critically ill patients with severe, complicated influenza infection (Answer D is incorrect). Enteral oseltamivir is the preferred therapy for current influenza B strains in critically ill patients with severe, complicated influenza infection (Answer B is correct). Clinicians should be mindful of the need for renal dosage adjustment, if necessary.", "page": 50, "answerPage": 68, "stemZh": "G.L. 為 25 歲女性，今年 2 月下旬因 severe acute hypoxemic respiratory failure 入住 medical ICU，需 mechanical ventilation。Fluid resuscitation 後仍 hypotensive，需 norepinephrine，且有 AKI，等待 CRRT 腎臟科評估。Nasal washing rapid test 提示 influenza B，符合當地今年流行病學。入 ICU 已放置 nasogastric feeding tube。哪個療法最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "腸道給藥 amantadine."}, {"key": "B", "text": "腸道給藥 oseltamivir."}, {"key": "C", "text": "吸入 zanamivir."}, {"key": "D", "text": "靜脈 peramivir."}], "explanationZh": "重症 influenza B 首選可腸道給予的 oseltamivir，並評估 renal adjustment；inhaled zanamivir 不適合 ventilated patient。"}, {"id": "06-case-21", "chapter": 6, "type": "case", "number": 21, "stem": "S.B. is a 48-year-old woman with severe obesity and heart disease intubated emergently at an outside hospital for refractory hypoxemic respiratory failure despite maximal MV support. S.B. is being evaluated for venovenous ECMO. She is quickly transferred to the MICU for evaluation. S.B. is initiated on dexamethasone 6 mg intravenously once daily, and her analgesia-sedative regimen is modified to maintain deep sedation in anticipation of starting continuous neuromuscular blockade. S.B. is receiving norepinephrine at 10 mcg/minute, which continues to be tapered to maintain a mean arterial pressure greater than 65 mm Hg. S.B. is being considered for remdesivir, which is in ample supply at your institution. Which best describes the current guideline recommendations for remdesivir in patients with COVID-19 requiring MV?", "context": "", "options": [{"key": "A", "text": "Shown to decrease in-hospital mortality.", "sourceKey": "A"}, {"key": "B", "text": "Not recommended because of safety concerns.", "sourceKey": "B"}, {"key": "C", "text": "Recommended to shorten time to clinical recovery.", "sourceKey": "C"}, {"key": "D", "text": "Uncertain benefit on clinical recovery and mortality. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 280", "sourceKey": "D"}], "answer": "D", "explanation": "Remdesivir is recommended for patients requiring supplemental oxygen. On the basis of the results of the ACTT study showing no difference in recovery time or mortality in more severe subgroups, the NIH guidelines do not recommend for or against remdesivir in patients requiring high-flow oxygen, MV, or ECMO (Answer D is correct; Answers A and C are incorrect). If remdesivir is initiated before advancing to MV, it is recommended to continue and complete therapy. Available evidence guidelines do not suggest increased adverse effects with remdesivir between less and more severely ill patients (Answer B is incorrect). ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 289", "page": 59, "answerPage": 68, "stemZh": "S.B. 為 48 歲女性，有 severe obesity 與 heart disease，在外院因最大 MV support 下仍有 refractory hypoxemic respiratory failure 而緊急插管，迅速轉至 MICU 評估 venovenous ECMO。開始 dexamethasone 6 mg IV 每日 1 次，調整 analgesia-sedation 至 deep sedation，準備 continuous NMBA。Norepinephrine 10 mcg/minute 持續調降，以維持 MAP >65 mm Hg。院內 remdesivir 供應充足，正在評估使用。原教材所述 guidelines 對需 MV 的 COVID-19 病人使用 remdesivir 的建議為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "已證實降低 in-hospital mortality。"}, {"key": "B", "text": "因 safety concerns 不建議。"}, {"key": "C", "text": "建議使用以縮短 clinical recovery time。"}, {"key": "D", "text": "對 clinical recovery 與 mortality 的 benefit 不確定。"}], "explanationZh": "依原教材引用的證據，已需 MV/ECMO subgroup 的 recovery 及 mortality benefit 不確定；若先前已開始則可完成療程。"}, {"id": "07-self-01", "chapter": 7, "type": "self", "number": 1, "stem": "A 56-year-old man (weight 140 kg) is scheduled to have elective coronary artery bypass surgery with aortic valve bioprosthetic replacement. The patient has a medical history of diabetes and hypertension. He has no drug allergies and has a calculated CrCl of 90 mL/minute/1.73 m2. It is anticipated that the patient will be admitted to the cardiovascular surgery ICU after the surgery with two chest tubes placed for drainage. Which is the most appropriate antimicrobial prophylactic regimen for the patient?", "context": "", "options": [{"key": "A", "text": "Cefazolin 2 g once within 2 hours before incision and administered every 8 hours until chest tubes are removed.", "sourceKey": "A"}, {"key": "B", "text": "Vancomycin 2 g once within 2 hours before incision and administered every 12 hours until 48 hours after surgery.", "sourceKey": "B"}, {"key": "C", "text": "Cefazolin 3 g once within 1 hour before incision, re-dosed if surgery lasts more than 4 hours, and continued for 48 hours after surgery.", "sourceKey": "C"}, {"key": "D", "text": "Cefazolin 2 g once within 1 hour before surgery, re-dosed if surgery lasts more than 4 hours, and continued for 48 hours after surgery.", "sourceKey": "D"}], "answer": "C", "explanation": "The prophylactic regimen for a patient without a β-lactam allergy who is undergoing cardiac surgery should be cephalosporin administered within 60 minutes of incision time, administered every 4 hours during surgery, and continued for no more than 48 hours. In this case, the patient has obesity disorder and weighs more than 120 kg; hence, the patient requires an initial dose of cefazolin 3 g (Answer C is correct). Given the patient’s weight, administering cefazolin 2 g initially is inappropriate (Answers A and D are incorrect). Vancomycin is usually reserved for patients with a β-lactam allergy (Answer B is incorrect).", "page": 4, "answerPage": 72, "stemZh": "56 歲男性，weight 140 kg，預計接受 elective coronary artery bypass surgery 及 aortic bioprosthetic valve replacement。有 diabetes 與 hypertension，無 drug allergy；calculated CrCl 90 mL/minute/1.73 m2。術後將入住 cardiovascular surgery ICU，放置兩條 chest tubes。最適合的 antimicrobial prophylaxis regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Cefazolin 2 g，切皮前 2 小時內給 1 次，此後每 8 小時給至 chest tubes 移除。"}, {"key": "B", "text": "Vancomycin 2 g，切皮前 2 小時內給 1 次，此後每 12 小時給至術後 48 小時。"}, {"key": "C", "text": "Cefazolin 3 g，切皮前 1 小時內給 1 次；手術 >4 小時時 redose，持續至術後 48 小時。"}, {"key": "D", "text": "Cefazolin 2 g，手術前 1 小時內給 1 次；手術 >4 小時時 redose，持續至術後 48 小時。"}], "explanationZh": "原教材心臟手術 prophylaxis 採 cefazolin，切皮前 60 分鐘內給藥，必要時 intraoperative redosing，術後不超過 48 小時；weight >120 kg 初劑量 3 g。"}, {"id": "07-self-02", "chapter": 7, "type": "self", "number": 2, "stem": "Which statement best describes antimicrobial stewardship in the ICU?", "context": "", "options": [{"key": "A", "text": "Formal antimicrobial stewardship team membership should be reserved for clinical pharmacists with infectious diseases training.", "sourceKey": "A"}, {"key": "B", "text": "Antibiotic cycling is helpful in minimizing antimicrobial resistance.", "sourceKey": "B"}, {"key": "C", "text": "Daily clinical activities of a critical care pharmacist may constitute an antimicrobial stewardship effort.", "sourceKey": "C"}, {"key": "D", "text": "Antimicrobial stewardship should not be instituted in critically ill patients because restriction of antimicrobial choices may worsen outcomes.", "sourceKey": "D"}], "answer": "C", "explanation": "Although critical care pharmacists may not officially be part of many antimicrobial stewardship teams, many of their daily clinical activities constitute antimicrobial stewardship activities. These may include selecting the most appropriate treatment regimen and advocating the early de-escalation of antimicrobials. Even in the presence of a formalized antimicrobial stewardship team, these activities are often complementary to the formalized activities of the team (Answer C is correct). Given the wide variations in clinical practice, it may not be feasible to include an infectious diseases– trained pharmacist with every stewardship team. In that case, the activities and involvement of a critical care pharmacist may be even more crucial (Answer A is incorrect). Antimicrobial cycling has not consistently demonstrated beneficial effect on antimicrobial resistance. (Answer B is incorrect). Studies have shown that antimicrobial stewardship efforts in critically ill patients do not worsen outcomes. Given the aggressive empiric antimicrobial regimens commonly used in critically ill patients, antimicrobial stewardship should be instituted to minimize adverse effects and the emergence of resistance (Answer D is incorrect).", "page": 4, "answerPage": 72, "stemZh": "哪項敘述最能描述 ICU antimicrobial stewardship？", "contextZh": "", "optionsZh": [{"key": "A", "text": "正式 stewardship team 應只納入受 infectious diseases 訓練的 clinical pharmacists。"}, {"key": "B", "text": "Antibiotic cycling 有助降低 antimicrobial resistance。"}, {"key": "C", "text": "重症藥師每日的 clinical activities 可構成 antimicrobial stewardship。"}, {"key": "D", "text": "重症病人不應推行 stewardship，因限制藥物選擇可能惡化 outcomes。"}], "explanationZh": "重症藥師每日適當選藥、dose optimization 與早期 de-escalation 本身就是 stewardship，並可與正式團隊互補。"}, {"id": "07-self-03", "chapter": 7, "type": "self", "number": 3, "stem": "A 33-year-old woman with a history of hydrocephalus since early childhood requiring placement of an internal cerebrospinal fluid (CSF) shunt, presents with a temperature of 102.8°F (39.3°C), an altered mental status, and a white blood cell count of 19 x 103 cells/mm3. After a computed tomography scan reveals no hydrocephalus or midline shift, a lumbar puncture is performed. Initial cell count shows elevated CSF white blood cells with a high proportion of neutrophils and low glucose. Neurosurgery is consulted for a presumed CSF shunt infection. Which empiric systemic antibiotic regimen is most appropriate?", "context": "", "options": [{"key": "A", "text": "Ceftriaxone and ampicillin.", "sourceKey": "A"}, {"key": "B", "text": "Ceftriaxone and vancomycin.", "sourceKey": "B"}, {"key": "C", "text": "Piperacillin/tazobactam and tobramycin.", "sourceKey": "C"}, {"key": "D", "text": "Cefepime and vancomycin.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient presents with a health care–associated CNS infection, given the post-neurosurgical and devicerelated etiology of the infection. The most common pathogens include MRSA and multidrug-resistant gram-negative organisms. In addition to neurosurgical management of the device (e.g., removal or revision), empiric antibiotic therapy is indicated, including therapy with agents having empiric activity against suspected pathogens and the ability to safely achieve relevant CSF concentrations. Cefepime and vancomycin are the most appropriate options listed with consideration of CNS-specific dosing (Answer D is correct). Ceftriaxone does not cover nosocomial-acquired gram negatives such as Pseudomonas (Answers A and B are incorrect). Piperacillin/tazobactam would be reasonable according to the spectrum of antibacterial activity; however, poor CNS penetration of tazobactam limits the utility of this agent for meningitis and other CNS infections (Answer C is incorrect).", "page": 5, "answerPage": 72, "stemZh": "33 歲女性，自幼有 hydrocephalus 並放置 internal CSF shunt，目前 temperature 102.8°F（39.3°C）、altered mental status、WBC 19 x 103 cells/mm3。CT 無 hydrocephalus 或 midline shift，lumbar puncture 顯示 CSF WBC 升高且 neutrophils 比例高、glucose 低。Neurosurgery 評估疑似 shunt infection。最適合的 empiric systemic antibiotic regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Ceftriaxone 與 ampicillin."}, {"key": "B", "text": "Ceftriaxone 與 vancomycin."}, {"key": "C", "text": "Piperacillin/tazobactam 與 tobramycin."}, {"key": "D", "text": "Cefepime 與 vancomycin."}], "explanationZh": "Device-related healthcare-associated CNS infection 需涵蓋 MRSA 與 resistant gram-negative organisms，並達到適當 CSF concentrations；選 cefepime 與 vancomycin。"}, {"id": "07-self-04", "chapter": 7, "type": "self", "number": 4, "stem": "A 75-year-old man is admitted to the medical ICU from the emergency department with septic shock. He is fluid resuscitated and administered broadspectrum antibiotics with piperacillin/tazobactam and vancomycin. On day 2 of therapy, the patient remains hemodynamically unstable, requiring norepinephrine. The patient’s blood culture is positive, according to the institution’s microbiology laboratory, which recently implemented rapid diagnostic tests using nanoparticle microarray technology, and the microarray results show the presence of Escherichia coli with the CTX-M resistance gene. Which intervention regarding the patient’s antimicrobial therapy is most appropriate?", "context": "", "options": [{"key": "A", "text": "Change piperacillin/tazobactam to cefepime.", "sourceKey": "A"}, {"key": "B", "text": "Add tobramycin to the current regimen.", "sourceKey": "B"}, {"key": "C", "text": "Add levofloxacin to the current regimen.", "sourceKey": "C"}, {"key": "D", "text": "Change piperacillin/tazobactam to meropenem.", "sourceKey": "D"}], "answer": "D", "explanation": "The presence of the CTX-M gene detected on E. coli by rapid diagnostic testing usually signifies the presence of ESBL. This may be why the patient has not yet responded to piperacillin/tazobactam. The most appropriate action at this point is to broaden the coverage to cover for potential ESBL-producing E. coli. Carbapenems remain the drug of choice for ESBL-producing organisms, particularly in a patient who is hemodynamically unstable (Answer D is correct). Extended-spectrum β-lactamases are usually encoded on genes that carry resistance against other classes of antimicrobials; hence, resistance to other antimicrobials is common; therefore, adding either aminoglycosides or fluoroquinolones may not be appropriate (Answers B and C are incorrect). Although at times ESBLs may be covered by cefepime, it must be determined by final AST (Answer A is incorrect).", "page": 5, "answerPage": 72, "stemZh": "75 歲男性從 ED 因 septic shock 入住 medical ICU，接受 fluids、piperacillin/tazobactam 與 vancomycin。治療第 2 天仍 hemodynamically unstable 並需 norepinephrine。Blood culture 陽性；院內新導入的 nanoparticle microarray rapid diagnostic test 顯示 E. coli 及 CTX-M resistance gene。Antimicrobial therapy 最適合如何調整？", "contextZh": "", "optionsZh": [{"key": "A", "text": "將 piperacillin/tazobactam 換為 cefepime。"}, {"key": "B", "text": "目前 regimen 加入 tobramycin。"}, {"key": "C", "text": "目前 regimen 加入 levofloxacin。"}, {"key": "D", "text": "將 piperacillin/tazobactam 換為 meropenem。"}], "explanationZh": "CTX-M 提示 ESBL；病人仍不穩定，選 meropenem 提供適當 coverage。"}, {"id": "07-self-05", "chapter": 7, "type": "self", "number": 5, "stem": "An 81-year-old man is admitted to the medical ICU with presumed line-associated sepsis. Blood cultures are obtained that grow pan-sensitive Enterobacter cloacae. The patient is being treated with intravenous ceftriaxone, and the offending central venous catheter is removed. The patient initially responds, but on day 10 of therapy, he becomes febrile, and blood cultures are re-sent. At that time, the patient was maintained on ceftriaxone because he was hemodynamically stable. Gram stain for the new blood cultures is positive for lactose-positive gramnegative bacilli. Which is the most appropriate action for this patient’s antimicrobial management?", "context": "", "options": [{"key": "A", "text": "Change ceftriaxone to ceftazidime.", "sourceKey": "A"}, {"key": "B", "text": "Change ceftriaxone to piperacillin/tazobactam.", "sourceKey": "B"}, {"key": "C", "text": "Change ceftriaxone to meropenem.", "sourceKey": "C"}, {"key": "D", "text": "Continue ceftriaxone alone.", "sourceKey": "D"}], "answer": "C", "explanation": "E. cloacae are AmpC β-lactamase–producing Enterobacterales. The use of ceftriaxone or extendedspectrum penicillins (e.g., piperacillin and ticarcillin) may select out derepressed mutants, which are capable of causing the hyperproduction of AmpC β-lactamases. Derepressed mutants are capable of producing resistance against third-generation cephalosporins, monobactams, and extended-spectrum penicillins. In this case, the patient was taking 10 days of ceftriaxone before a new blood culture was growing lactose-positive gram-negative bacilli. Because lactose-positive gramnegative bacilli are usually Enterobacterales, growing multidrug-resistant pathogens such as P. aeruginosa and Acinetobacter baumannii is less likely. Hence, the most likely resistance mechanism in this patient is either selection of derepressed mutants or acquisition of a pathogen with ESBL. Both of these resistance mechanisms are adequately treated by a carbapenem. Hence, changing to a carbapenem pending final sensitivities is the most reasonable option (Answer C is correct). Both types of resistance mechanisms are capable of producing resistance against ceftazidime and piperacillin/tazobactam (Answers A and B are incorrect). Because the patient developed a new bacteremia while taking ceftriaxone, it is not reasonable to continue ceftriaxone alone (Answer D is incorrect).", "page": 5, "answerPage": 72, "stemZh": "81 歲男性因疑似 line-associated sepsis 入住 medical ICU，blood cultures 為 pan-sensitive E. cloacae。使用 IV ceftriaxone 並移除致病 CVC，起初改善。治療第 10 天再發 fever，重新送 cultures；因 hemodynamics 穩定而續用 ceftriaxone。新 blood culture Gram stain 為 lactose-positive gram-negative bacilli。最適合如何調整？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Ceftriaxone 換 ceftazidime。"}, {"key": "B", "text": "Ceftriaxone 換 piperacillin/tazobactam。"}, {"key": "C", "text": "Ceftriaxone 換 meropenem。"}, {"key": "D", "text": "繼續單用 ceftriaxone。"}], "explanationZh": "E. cloacae 可因 derepressed AmpC 出現 resistance；本題復發可能為 AmpC 或 ESBL，選 carbapenem 等待 final susceptibility。"}, {"id": "07-self-06", "chapter": 7, "type": "self", "number": 6, "stem": "An 86-year-old woman with a history of endstage renal disease is admitted to the hospital with respiratory distress requiring intubation, fluid resuscitation, and hemodynamic monitoring. Bronchoalveolar lavage cultures show methicillinresistant Staphylococcus aureus (MRSA). The patient is being treated with intravenous vancomycin. On day 4 of therapy, the patient develops fever, leukocytosis, and erythema around the insertion site of her tunneled dialysis catheter. Blood cultures are sent, and the dialysis catheter is removed. Gram stain from blood cultures is significant for grampositive cocci in pairs and chains. The medical team discontinues vancomycin and approaches you to inquire about treatment options for this patient. Which agent is most appropriate for this patient?", "context": "", "options": [{"key": "A", "text": "Daptomycin.", "sourceKey": "A"}, {"key": "B", "text": "Linezolid.", "sourceKey": "B"}, {"key": "C", "text": "Ceftaroline.", "sourceKey": "C"}, {"key": "D", "text": "Tigecycline.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient is only on day 4 of therapy from proven MRSA pneumonia. However, the patient developed a bacteremia with gram-positive cocci in pairs and chains despite receiving systemic vancomycin therapy. The most likely culprit is a vancomycinresistant Enterococcus sp. The medical team has already discontinued vancomycin; therefore, the new therapy must cover both the MRSA pneumonia and the possibility of a vancomycin-resistant Enterococcus sp. Linezolid has good lung penetration and can adequately cover vancomycin-resistant enterococci (Answer B is correct). Daptomycin would provide adequate coverage for vancomycin-resistant enterococci, but because it is inactivated by lung surfactants, it is not a good option for the treatment of MRSA pneumonia (Answer A is incorrect). Ceftaroline covers MRSA and has good lung penetration; however, it covers only vancomycinresistant E. faecalis, not E. faecium. Because, at this point, the speciation of the gram-positive cocci in pairs and chains is not available, ceftaroline is not the best choice (Answer C is incorrect). Tigecycline does cover MRSA and vancomycin-resistant enterococci; however, given its large volume of distribution and relatively low serum concentrations, it is not the ideal choice for the treatment of bacteremia when other treatments are available (Answer D is incorrect).", "page": 5, "answerPage": 73, "stemZh": "86 歲女性，有 ESRD，因 respiratory distress 住院並插管、fluid resuscitation 及 hemodynamic monitoring。BAL cultures 為 MRSA，使用 IV vancomycin。治療第 4 天有 fever、leukocytosis 與 tunneled dialysis catheter site erythema，採 blood cultures 並移除 catheter；Gram stain 為 gram-positive cocci in pairs and chains。團隊停止 vancomycin，詢問替代療法。最適合哪個藥物？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Daptomycin."}, {"key": "B", "text": "Linezolid."}, {"key": "C", "text": "Ceftaroline."}, {"key": "D", "text": "Tigecycline."}], "explanationZh": "需同時涵蓋尚未治療完成的 MRSA pneumonia 與疑似 VRE bacteremia；linezolid 合適，daptomycin 不適合 pneumonia。"}, {"id": "07-self-07", "chapter": 7, "type": "self", "number": 7, "stem": "A 35-year-old man is admitted to the medical ICU with respiratory distress. He has a 3-week history of cough and pleuritic chest pain that has worsened with time. Chest radiography is performed, which shows bilateral infiltrates with ground-glass opacities. The patient is HIV positive and not currently receiving antiretroviral therapy because of nonadherence. The patient requires intubation and is receiving 40% fraction of inspired oxygen (Fio 2 ). His relevant laboratory values are as follows: SCr 1.0 mg/dL, CD4+ count 100/mm3, lactate dehydrogenase (LDH) 550 IU/L, partial pressure of arterial oxygen (PaO 2 ) 80 mm Hg, partial pressure of arterial carbon dioxide (PaCO 2 ) 40 mm Hg, and white blood cell count (WBC) 4 x 103 cells/ mm3. The patient has a sulfa allergy and a glucose6-phosphate dehydrogenase deficiency. In addition to adjunctive corticosteroids, which regimen for presumed Pneumocystis jiroveci pneumonia is most appropriate?", "context": "", "options": [{"key": "A", "text": "Trimethoprim/sulfamethoxazole 15–20 mg/kg intravenously, divided every 6 hours.", "sourceKey": "A"}, {"key": "B", "text": "Pentamidine 4 mg/kg intravenously every 24 hours alone.", "sourceKey": "B"}, {"key": "C", "text": "Primaquine 30 mg orally once daily plus clindamycin 600 mg intravenously every 8 hours alone.", "sourceKey": "C"}, {"key": "D", "text": "Atovaquone 750 mg orally every 12 hours.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient’s history and clinical presentation suggest Pneumocystis jiroveci pneumonia. It is severe enough to warrant intubation, and the patient has a significant alveolar-arterial oxygen gradient. The usual drug of choice for such patients is trimethoprim/sulfamethoxazole, but because this patient has a sulfa allergy, this is not an option (Answer A is incorrect). According to the HIV OI guideline, the second-line agent for the treatment of severe Pneumocystis jiroveci pneumonia is intravenous pentamidine. Because the patient had severe hypoxemia, adjunctive steroids should be administered (Answer B is correct). Atovaquone and primaquine/clindamycin regimens are usually reserved for patients with milder Pneumocystis jiroveci pneumonia. Furthermore, primaquine should not be administered to someone with a glucose-6-phosphate dehydrogenase deficiency (Answers C and D are incorrect).", "page": 5, "answerPage": 73, "stemZh": "35 歲男性因 respiratory distress 入住 medical ICU，cough 與 pleuritic chest pain 已 3 週且逐漸惡化。Chest radiograph 有 bilateral infiltrates 及 ground-glass opacities。HIV 陽性，因 nonadherence 未接受 ART；需插管、FiO2 40%。SCr 1.0 mg/dL、CD4+ 100/mm3、LDH 550 IU/L、PaO2 80 mm Hg、PaCO2 40 mm Hg、WBC 4 x 103 cells/mm3。有 sulfa allergy 與 G6PD deficiency。除 adjunctive corticosteroids 外，疑似 P. jiroveci pneumonia 最適合哪個 regimen？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Trimethoprim/sulfamethoxazole 15–20 mg/kg 靜脈給藥, divided 每 6 小時."}, {"key": "B", "text": "Pentamidine 4 mg/kg 靜脈給藥 每 24 小時 alone."}, {"key": "C", "text": "Primaquine 30 mg 口服 每日 1 次 合併 clindamycin 600 mg 靜脈給藥 每 8 小時 alone."}, {"key": "D", "text": "Atovaquone 750 mg 口服 每 12 小時."}], "explanationZh": "Severe PJP 且 sulfa allergy 可選 IV pentamidine；G6PD deficiency 也排除 primaquine。"}, {"id": "07-self-08", "chapter": 7, "type": "self", "number": 8, "stem": "A 50-year-old woman with acute myeloid leukemia is admitted for induction therapy. During the patient’s clinical course, she develops respiratory distress, for which she is admitted to the medical ICU. She is found to have neutropenic fever and is empirically treated with meropenem plus gentamicin plus vancomycin. On day 5 of empiric therapy, blood cultures are growing pan-susceptible E. coli. The patient’s relevant laboratory values and vital signs are as follows: blood pressure 115/70 mm Hg, heart rate 84 beats/minute, temperature 101.2°F (38.4°C), and absolute neutrophil count less than 50 cells/mm3. Which is the most appropriate antimicrobial regimen for the patient?", "context": "", "options": [{"key": "A", "text": "Continue meropenem, gentamicin, and vancomycin for 14 days.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue all empiric antimicrobials, and initiate ampicillin intravenously to treat until neutrophils recover.", "sourceKey": "B"}, {"key": "C", "text": "Discontinue vancomycin, and continue meropenem and gentamicin until neutrophil recovery.", "sourceKey": "C"}, {"key": "D", "text": "Add voriconazole, and continue all other antimicrobials for 14 days.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient has febrile neutropenia with no recovery of neutrophils. According to the IDSA febrile neutropenia guidelines, when a source of infection is identified, the empiric antimicrobial therapy can be de-escalated to a more narrow-spectrum regimen according to the antibiotic susceptibility report. In this case, because the E. coli was pan-sensitive, it would be appropriate to de-escalate to a narrow-spectrum antimicrobial. The guidelines also specify that antimicrobial therapies should be continued for at least 14 days and until neutrophils are greater than 500 cells/mm3 (Answer B is correct). Although the patient continues to be febrile, an otherwise stable patient with continued fevers rarely requires additional antimicrobial therapy according to the guidelines. Hence, continuing more broad-spectrum therapy than necessary or adding other antimicrobials is unwarranted (Answers A, C, and D are incorrect).", "page": 6, "answerPage": 73, "stemZh": "50 歲女性，有 AML，住院接受 induction therapy 後發生 respiratory distress，轉至 medical ICU。Neutropenic fever empiric 使用 meropenem、gentamicin、vancomycin。第 5 天 blood cultures 為 pan-susceptible E. coli；BP 115/70 mm Hg、HR 84 beats/minute、temperature 101.2°F（38.4°C）、ANC <50 cells/mm3。最適合的 antimicrobial regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Meropenem、gentamicin、vancomycin 持續 14 天。"}, {"key": "B", "text": "停止所有 empiric antimicrobials，開始 IV ampicillin，治療至 neutrophils 恢復。"}, {"key": "C", "text": "停止 vancomycin，meropenem 與 gentamicin 持續至 neutrophils 恢復。"}, {"key": "D", "text": "加入 voriconazole，其餘藥物全部持續 14 天。"}], "explanationZh": "已確認 pan-sensitive E. coli，可 de-escalate；原教材建議至少治療 14 天且至 neutrophils >500 cells/mm3。"}, {"id": "07-case-01", "chapter": 7, "type": "case", "number": 1, "stem": "C.L is a 55-year-old man admitted to the surgical ICU after exploratory laparotomy for duodenal perforation and peritonitis. The patient was transferred from the operating room to the surgical ICU with a urinary catheter in place. On day 4 of the surgical ICU stay, the patient is extubated, and his urinary catheter is removed. On day 6 of the surgical ICU stay, the patient develops signs and symptoms of UTI with fever, urgency, and frequency. Urinalysis reveals no nitrites or leukocyte esterase. Urine cultures show 100,000 CFU/mL of E. coli. You are asked by the quality officer of the surgical ICU to discuss this case and determine whether this patient will qualify for the definition of CAUTI according to CDC criteria. Which statement regarding the diagnosis of CAUTI in this patient is most appropriate?", "context": "", "options": [{"key": "A", "text": "Qualifies for definition of CAUTI because the patient is symptomatic and has positive cultures.", "sourceKey": "A"}, {"key": "B", "text": "Does not qualify for definition of CAUTI because the patient had a negative urinalysis.", "sourceKey": "B"}, {"key": "C", "text": "Qualifies for definition of CAUTI because the patient is symptomatic and had recent urinary catheter.", "sourceKey": "C"}, {"key": "D", "text": "Does not qualify for definition of CAUTI because the catheter was removed 2 days before symptoms.", "sourceKey": "D"}], "answer": "D", "explanation": "The CDC definitions for CAUTIs, which are used by the CMS reporting system, were recently updated. Because this patient had his urinary catheter removed for more than 24 hours before developing UTI symptoms, this case does not satisfy the definition of CAUTI (Answer D is correct; Answers A and C are incorrect). The current CDC CAUTI definitions do not consider the results of a urinalysis (Answer B is incorrect).", "page": 12, "answerPage": 70, "stemZh": "C.L. 為 55 歲男性，因 duodenal perforation 與 peritonitis 接受 exploratory laparotomy，帶 urinary catheter 從 OR 轉至 surgical ICU。第 4 天 extubation 並移除 catheter；第 6 天發生 fever、urgency、frequency 等 UTI symptoms。Urinalysis 無 nitrites 或 leukocyte esterase；urine culture 為 E. coli 100,000 CFU/mL。Quality officer 要求依 CDC criteria 判斷是否符合 CAUTI。何者最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "符合 CAUTI，因有 symptoms 及 positive cultures。"}, {"key": "B", "text": "不符合 CAUTI，因 urinalysis 陰性。"}, {"key": "C", "text": "符合 CAUTI，因有 symptoms 且近期曾有 urinary catheter。"}, {"key": "D", "text": "不符合 CAUTI，因 catheter 已在 symptoms 前 2 天移除。"}], "explanationZh": "依原教材的監測定義，catheter 移除超過 24 小時才出現 UTI symptoms，不符合 CAUTI；urinalysis 不是此定義判斷依據。"}, {"id": "07-case-02", "chapter": 7, "type": "case", "number": 2, "stem": "H.K. is a 42-year-old woman who presents with her husband to the emergency department from home with mental status changes, lethargy, and a temperature of 102.9°F (39.4°C). Her husband reports that she had a severe headache 24 hours earlier. She has no significant medical history. Diagnostic workup results are highly suggestive of meningitis. A lumbar puncture is performed, during which a high initial pressure is noted. Which intervention would be best initially for H.K.?", "context": "", "options": [{"key": "A", "text": "Administer dexamethasone 0.15 mg/kg intravenously.", "sourceKey": "A"}, {"key": "B", "text": "Await laboratory and microbiologic analysis.", "sourceKey": "B"}, {"key": "C", "text": "Initiate empiric ceftriaxone and vancomycin.", "sourceKey": "C"}, {"key": "D", "text": "Initiate empiric ampicillin, cefepime, and vancomycin.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient presents with community-acquired meningitis. The high opening pressure is suggestive of a bacterial etiology, of which the most prevalent pathogen for this patient’s risk factors and age is S. pneumoniae. Administering dexamethasone before initiating antibiotic therapy decreases mortality in patients with S. pneumoniae meningitis. (Answer A is correct) Awaiting laboratory and microbiologic test results analysis may cause inappropriate delays in therapy (Answer B is incorrect). In addition, although administering antimicrobials is a good idea, the beneficial effects associated with dexamethasone are diminished if administered after antimicrobials have been initiated. At the very least, corticosteroids should be administered concomitantly with antimicrobials (Answer C and D are incorrect).", "page": 17, "answerPage": 70, "stemZh": "H.K. 為 42 歲女性，與丈夫從家中至 ED，出現 mental status changes、lethargy、temperature 102.9°F（39.4°C）；丈夫說 24 小時前有 severe headache。無重要病史。評估高度懷疑 meningitis，lumbar puncture 有 high opening pressure。最佳初始處置為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "給 dexamethasone 0.15 mg/kg IV。"}, {"key": "B", "text": "等待 laboratory 與 microbiologic results。"}, {"key": "C", "text": "開始 empiric ceftriaxone 與 vancomycin。"}, {"key": "D", "text": "開始 empiric ampicillin、cefepime、vancomycin。"}], "explanationZh": "疑似 pneumococcal meningitis 的 dexamethasone 應在 antibiotics 前或至少同時給予，以保留相關 benefit。"}, {"id": "07-case-03", "chapter": 7, "type": "case", "number": 3, "stem": "A 54-year-old man is admitted to the medical ICU with acute necrotizing pancreatitis. He is found to have an infected pancreatic abscess, which is being treated with meropenem and vancomycin. One week into the course, the patient develops a fever and leukocytosis. He also becomes hemodynamically unstable and oliguric. He is initiated on caspofungin empirically to cover for possible invasive candidiasis. Blood cultures are obtained, which become positive with a preliminary result of yeast. This institution is equipped with PNA FISH technology, which identifies the yeast as Candida parapsilosis on day 2 of therapy. The patient remains hemodynamically unstable. Which is the most appropriate choice for this patient’s antifungal therapy?", "context": "", "options": [{"key": "A", "text": "Continue caspofungin while fungal susceptibilities are finalized.", "sourceKey": "A"}, {"key": "B", "text": "Change to voriconazole 6 mg/kg every 12 hours.", "sourceKey": "B"}, {"key": "C", "text": "Change to liposomal amphotericin 5 mg/kg/day.", "sourceKey": "C"}, {"key": "D", "text": "Change to fluconazole 400 mg intravenously daily.", "sourceKey": "D"}], "answer": "D", "explanation": "The PNA FISH technology is designed to identify pathogens earlier. It performs well, with good sensitivity and specificity; hence, identification of C. parapsilosis should not require verification from culture (Answer A is incorrect). The drug of choice for the treatment of C. parapsilosis is fluconazole (Answer D is correct). Although echinocandin, voriconazole, and amphotericin would all cover C. parapsilosis, they all have a broader spectrum than is necessary, making them not the ideal choice (Answers A–C are incorrect).", "page": 26, "answerPage": 70, "stemZh": "54 歲男性因 acute necrotizing pancreatitis 入住 medical ICU，infected pancreatic abscess 使用 meropenem 與 vancomycin。1 週後 fever、leukocytosis、hemodynamic instability 與 oliguria，empiric 加入 caspofungin 處理可能 invasive candidiasis。Blood culture 初步為 yeast，PNA FISH 在治療第 2 天辨識 C. parapsilosis；仍不穩定。最適合的 antifungal therapy 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "等待 final fungal susceptibility 期間持續 caspofungin。"}, {"key": "B", "text": "換 voriconazole 6 mg/kg，每 12 小時。"}, {"key": "C", "text": "換 liposomal amphotericin 5 mg/kg/day。"}, {"key": "D", "text": "換 fluconazole 400 mg IV，每日 1 次。"}], "explanationZh": "依本題原教材答案，PNA FISH 已識別 C. parapsilosis，可轉為較窄 spectrum 的 fluconazole；保留此題原始作答依據。"}, {"id": "07-case-04", "chapter": 7, "type": "case", "number": 4, "stem": "A 64-year-old woman is admitted to the medical ICU with possible community-acquired pneumonia. The patient is initiated on ceftriaxone and azithromycin. Chest radiography reveals focal infiltrate. On admission, she is dyspneic with a respiratory rate of 33 breaths/minute. Her vital signs and laboratory values are as follows: blood pressure 90/50 mm Hg, heart rate 101 beats/minute, WBC 18 x 103 cells/mm3, and lactate 4.2 mmol/L. A PCT is obtained on admission. The results are available 12 hours after antibiotics are initiated. The PCT result is 0.1 mcg/L. Which is the most appropriate option, given the PCT result?", "context": "", "options": [{"key": "A", "text": "Continue all current antibiotics.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue all antibiotics.", "sourceKey": "B"}, {"key": "C", "text": "Escalate antibiotics to piperacillin/tazobactam.", "sourceKey": "C"}, {"key": "D", "text": "Discontinue ceftriaxone only.", "sourceKey": "D"}], "answer": "A", "explanation": "Although PCT is a promising biomarker for the detection of bacterial infections, it must be interpreted within the context of the patient’s clinical course. In this case, the patient has clear signs and symptoms of infection, together with signs of hypoperfusion. A low PCT should not be used to guide therapy discontinuation in this case, and antibiotics should be continued to cover the most likely pathogens (Answer A is correct; Answer B is incorrect). Because the patient is admitted with presumed community-acquired pneumonia, the combination of ceftriaxone and azithromycin is appropriate right now (Answers C and D are incorrect).", "page": 31, "answerPage": 70, "stemZh": "64 歲女性因疑似 CAP 入住 medical ICU，開始 ceftriaxone 與 azithromycin，chest radiograph 有 focal infiltrate。入院有 dyspnea、RR 33 breaths/minute、BP 90/50 mm Hg、HR 101 beats/minute、WBC 18 x 103 cells/mm3、lactate 4.2 mmol/L。入院採 PCT，在 antibiotics 開始後 12 小時得到結果 0.1 mcg/L。最適合的選擇為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "持續目前全部 antibiotics。"}, {"key": "B", "text": "停止全部 antibiotics。"}, {"key": "C", "text": "Escalate 至 piperacillin/tazobactam。"}, {"key": "D", "text": "只停止 ceftriaxone。"}], "explanationZh": "低 PCT 不能推翻明顯 infection 與 hypoperfusion 的臨床證據，本題持續目前 CAP regimen。"}, {"id": "07-case-05", "chapter": 7, "type": "case", "number": 5, "stem": "A 74-year-old man is admitted to the surgical ICU after elective hip replacement surgery. The patient, who has a history of chronic pulmonary obstructive disease, cannot be weaned off the ventilator after surgery. During the patient’s course, he develops signs and symptoms of infection. His vital signs and laboratory values are as follows: blood pressure 94/55 mm Hg, heart rate 114 beats/minute, temperature 101.9°F (38.8°C), WBC 18 x 103 cells/mm3, and lactate 3.2 mmol/L. The patient is empirically initiated on piperacillin/tazobactam and vancomycin and given 2 L of crystalloid fluids; pan cultures are sent. Urinalysis reveals pyuria, positive leukocyte esterases, and nitrites. Blood and sputum cultures are negative, but urine culture shows E. coli. The patient’s urinary catheter is removed, and vancomycin is discontinued. On day 3 of therapy, antibiotic susceptibility results are available. The patient’s E. coli is resistant to third-generation cephalosporins with laboratory confirmation of the presence of ESBL. The laboratory reports the following antimicrobials and corresponding MIC values: piperacillin/tazobactam less than 2 mcg/mL – S; cefepime 4 mcg/mL – SDD; imipenem 0.5 mcg/mL – S; and ciprofloxacin 0.25 mcg/mL – S. The patient’s vital signs and laboratory values are as follows: blood pressure 110/70 mm Hg, heart rate 98 beats/minute, respiratory rate 30 breaths/minute, temperature 98.7°F (37.1°C), and WBC 9 x 103 cells/mm3. Which is the most appropriate antibiotic option?", "context": "", "options": [{"key": "A", "text": "Change piperacillin/tazobactam to imipenem.", "sourceKey": "A"}, {"key": "B", "text": "Continue piperacillin/tazobactam alone.", "sourceKey": "B"}, {"key": "C", "text": "Change piperacillin/tazobactam to cefepime.", "sourceKey": "C"}, {"key": "D", "text": "Add ciprofloxacin to piperacillin/tazobactam.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient is being treated for an ESBL E. coli UTI, in which the source of the infection (urinary catheter) is removed. The patient also has signs of response to piperacillin/tazobactam with resolution of leukocytosis and fever. In this case, given the low inoculum of the infection, initial response, removal of source, and low MIC, continuing piperacillin/tazobactam is the best choice (Answer B is correct). This choice may only be the case for UTIs, not other sources of infection (e.g., bacteremias). Traditionally, it was widely believed that ESBL infections had to be treated with carbapenems. However, recent evidence suggests that β-lactam/ β-lactamase inhibitor combinations are a suitable option. In the era of antimicrobial stewardship, the preservation of carbapenem therapy should be regarded with high importance (Answer A is incorrect). This current culture has an MIC of 4 mcg/mL to cefepime, which, according to the updated CLSI guidelines, would be considered resistant (Answer C is incorrect). Because the patient is responding to the current therapy, combination therapy is unnecessary (Answer D is incorrect).", "page": 39, "answerPage": 70, "stemZh": "74 歲男性，有 COPD，elective hip replacement 後入住 surgical ICU，無法脫離 ventilator。之後出現 infection signs：BP 94/55 mm Hg、HR 114 beats/minute、temperature 101.9°F（38.8°C）、WBC 18 x 103 cells/mm3、lactate 3.2 mmol/L。Empiric piperacillin/tazobactam 與 vancomycin、2 L crystalloid，並送 pan cultures。Urinalysis 為 pyuria、leukocyte esterase 及 nitrites 陽性。Blood/sputum cultures 陰性，urine culture 為 E. coli，移除 urinary catheter 並停止 vancomycin。第 3 天 susceptibility：third-generation cephalosporins resistant，確認 ESBL；piperacillin/tazobactam MIC <2 mcg/mL（S）、cefepime 4 mcg/mL（SDD）、imipenem 0.5 mcg/mL（S）、ciprofloxacin 0.25 mcg/mL（S）。目前 BP 110/70 mm Hg、HR 98 beats/minute、RR 30 breaths/minute、temperature 98.7°F（37.1°C）、WBC 9 x 103 cells/mm3。最適合的 antibiotic option 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Piperacillin/tazobactam 換 imipenem。"}, {"key": "B", "text": "單用並持續 piperacillin/tazobactam。"}, {"key": "C", "text": "Piperacillin/tazobactam 換 cefepime。"}, {"key": "D", "text": "Piperacillin/tazobactam 加 ciprofloxacin。"}], "explanationZh": "依本題原教材，urinary source 已移除、low MIC 且 clinical response 良好，可持續 piperacillin/tazobactam；此推論不延伸至 bacteremia 等其他 source。"}, {"id": "07-case-06", "chapter": 7, "type": "case", "number": 6, "stem": "A 72-year-old woman with a history of end-stage renal disease is admitted to the medical ICU with signs and symptoms of sepsis. Blood cultures are obtained in which two of two bottles grow gram-positive cocci. The patient is initiated on vancomycin, and her tunneled dialysis catheter is removed. On day 4 of therapy, the blood cultures are finalized to be MRSA with the following antibiotic susceptibility results: oxacillin greater than 4 mcg/mL – R; vancomycin 2 mcg/mL – S; daptomycin 0.5 mcg/mL – S; and linezolid 1 mcg/ mL – S. A transthoracic echocardiogram is obtained, which reveals echodensities on the mitral valve. The patient will be treated medically with antibiotics for 4–6 weeks. The patient’s repeat blood cultures are currently no growth. Her vital signs and laboratory values are as follows: blood pressure 150/90 mm Hg, heart rate 88 beats/minute, temperature 100.2°F, WBC 11 x 103 cells/mm3, and lactate 1.1 mmol/L. Which is the most appropriate treatment regimen?", "context": "", "options": [{"key": "A", "text": "Change vancomycin to linezolid 600 mg every 12 hours.", "sourceKey": "A"}, {"key": "B", "text": "Add gentamicin and rifampin to vancomycin.", "sourceKey": "B"}, {"key": "C", "text": "Change vancomycin to daptomycin 6 mg/kg every 48 hours.", "sourceKey": "C"}, {"key": "D", "text": "Continue vancomycin, and target a trough level of 15–20 mcg/mL.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient is being treated for MRSA right-sided endocarditis, with the presumed source from her tunneled dialysis catheter. According to the IDSA guidelines for the treatment of MRSA, treatment with vancomycin of an isolate with an MIC of 2 mcg/ mL or less should be determined by the patient’s response to therapy, regardless of the actual MIC. This patient has responded to therapy with the presumed clearance of blood cultures and resolution of signs and symptoms of infection. Hence, continuing vancomycin and targeting a trough of 15–20 mcg/mL is the most appropriate choice (Answer D is correct). Linezolid is not indicated for the treatment of endocarditis (Answer A is incorrect). Adding gentamicin and rifampin is considered in the medical treatment of prosthetic valve endocarditis (Answer B is incorrect). Because the patient is responding to current vancomycin therapy, an escalation to daptomycin is inappropriate right now (Answer C is incorrect).", "page": 49, "answerPage": 70, "stemZh": "72 歲女性，有 ESRD，因 sepsis signs 入住 medical ICU，2/2 blood culture bottles 有 gram-positive cocci，開始 vancomycin 並移除 tunneled dialysis catheter。第 4 天確認 MRSA：oxacillin >4 mcg/mL（R）、vancomycin 2 mcg/mL（S）、daptomycin 0.5 mcg/mL（S）、linezolid 1 mcg/mL（S）。TTE 見 mitral-valve echodensities，預計 antibiotics 4–6 週；repeat blood cultures 無生長。BP 150/90 mm Hg、HR 88 beats/minute、temperature 100.2°F、WBC 11 x 103 cells/mm3、lactate 1.1 mmol/L。最適合 regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "換 linezolid 600 mg，每 12 小時。"}, {"key": "B", "text": "Vancomycin 加 gentamicin 與 rifampin。"}, {"key": "C", "text": "換 daptomycin 6 mg/kg，每 48 小時。"}, {"key": "D", "text": "持續 vancomycin，target trough 15–20 mcg/mL。"}], "explanationZh": "依原題答案，MRSA vancomycin MIC ≤2 mcg/mL 且臨床與 cultures 有反應，可續用 vancomycin；選項中的 trough target 是原教材設定。"}, {"id": "07-case-07", "chapter": 7, "type": "case", "number": 7, "stem": "A 46-year-old man is admitted to the medical ICU for diabetic ketoacidosis. The patient has a history of insulin-dependent diabetes, is HIV positive, and has cryptococcal meningitis. His current HAART regimen consists of atazanavir, ritonavir, tenofovir, and emtricitabine, which is continued on admission to the ICU. The patient’s CD4+ count is 85 cells/mm3. The patient’s diabetic ketoacidosis is well controlled, and he is ready to be discharged from the ICU. Before discharge, the patient is noted not to be on any prophylaxis against OIs. Which prophylactic regimen would be most appropriate for the patient?", "context": "", "options": [{"key": "A", "text": "Azithromycin 1200 mg once weekly and trimethoprim/sulfamethoxazole 1 double-strength (DS) tablet thrice weekly.", "sourceKey": "A"}, {"key": "B", "text": "Fluconazole 200 mg daily and trimethoprim/sulfamethoxazole 1 DS tablet daily.", "sourceKey": "B"}, {"key": "C", "text": "Azithromycin 1200 mg once weekly and fluconazole 200 mg daily.", "sourceKey": "C"}, {"key": "D", "text": "Fluconazole 200 mg daily and trimethoprim/sulfamethoxazole 1 DS tablet thrice weekly.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient is admitted to the ICU for an indication that is unrelated to the patient’s underlying HIV. The assessment of which prophylactics are necessary against OIs depends on the patient’s underlying disease, history, and CD4+ count. In this case, the patient has a CD4+ count less than 100/mm3 and a history of cryptococcal meningitis. Hence, prophylaxis should be administered for toxoplasmosis, P. jiroveci, and Cryptococcus. The best regimen for this patient is fluconazole 200 mg daily and trimethoprim/sulfamethoxazole 1 DS tablet once daily (Answer B is correct). The prophylaxis for Mycobacterium avium complex is indicated for patients with a CD4+ count of less than 50 cells/mm3, which is unnecessary at this point (Answers A and C are incorrect). Although trimethoprim/sulfamethoxazole 1 DS tablet thrice weekly is an option for prophylaxis, it is not the best choice against toxoplasmosis (Answer D is incorrect).", "page": 54, "answerPage": 71, "stemZh": "46 歲男性因 DKA 入住 medical ICU，有 insulin-dependent diabetes、HIV 及 cryptococcal meningitis 病史。HAART 為 atazanavir、ritonavir、tenofovir、emtricitabine，入 ICU 後持續。CD4+ 85 cells/mm3。DKA 已控制，準備離開 ICU，但未使用任何 OI prophylaxis。最適合的 prophylactic regimen 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Azithromycin 1200 mg 每週 1 次，TMP/SMX 1 DS tablet 每週 3 次。"}, {"key": "B", "text": "Fluconazole 200 mg 每日 1 次，TMP/SMX 1 DS tablet 每日 1 次。"}, {"key": "C", "text": "Azithromycin 1200 mg 每週 1 次，fluconazole 200 mg 每日 1 次。"}, {"key": "D", "text": "Fluconazole 200 mg 每日 1 次，TMP/SMX 1 DS tablet 每週 3 次。"}], "explanationZh": "CD4 <100 且有 cryptococcal meningitis 病史，需 PJP、toxoplasmosis 及 Cryptococcus prophylaxis；選 daily TMP/SMX DS 與 fluconazole。"}, {"id": "07-case-08", "chapter": 7, "type": "case", "number": 8, "stem": "A 66-year-old woman (height 66 inches, weight 75 kg) is admitted to the medical ICU for dehydration and acute kidney injury. The patient recently received an allogeneic bone marrow transplant and has not yet engrafted. She has been pancytopenic for 12 days. On day 5 of the medical ICU stay, the patient develops acute respiratory distress requiring intubation. Bronchoalveolar lavage is done, which eventually grows Aspergillus fumigatus, and the patient is given a diagnosis of invasive pulmonary aspergillosis. The patient’s current medications include tacrolimus, corticosteroids, and fluconazole fungal prophylaxis. Her current relevant laboratory values are as follows: WBC 0.2 x 103 cells/mm3, lactate 1.5 mmol/L, and SCr 3.4 mg/dL. Which antifungal therapy is most appropriate?", "context": "", "options": [{"key": "A", "text": "Amphotericin 50 mg intravenously once daily.", "sourceKey": "A"}, {"key": "B", "text": "Isavuconazole load followed by 200 mg intravenously daily.", "sourceKey": "B"}, {"key": "C", "text": "Caspofungin load followed by 50 mg intravenously daily.", "sourceKey": "C"}, {"key": "D", "text": "Voriconazole load followed by 300 mg intravenously every 12 hours.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient has invasive pulmonary aspergillosis. Usually, the treatment of choice is voriconazole. However, in this case, the patient has acute kidney injury with a CrCl less than 50 mL/minute/1.73 m2. According to the package insert, voriconazole is contraindicated in this case because of the possibility of accumulation of cyclodextrin, the intravenous drug carrier for voriconazole. Although the clinical relevance of this accumulation is controversial, continued use of a contraindicated therapy is inappropriate when alternatives may be available (Answer D is incorrect). Isavuconazole is a new triazole that was found to be noninferior to voriconazole for the treatment of aspergillosis and has improved water solubility, which does not require it to be formulated with cyclodextrin (Answer B is correct). Conventional amphotericin may be a reasonable choice, but it will likely worsen the patient’s acute kidney injury (Answer A is incorrect). Echinocandins are not the ideal therapies for invasive aspergillosis and should only be considered if there are no other treatment options. In addition, caspofungin can decrease the serum concentration of tacrolimus (Answer C is incorrect).", "page": 62, "answerPage": 71, "stemZh": "66 歲女性，height 66 inches、weight 75 kg，因 dehydration 與 AKI 入住 medical ICU。近期 allogeneic bone marrow transplant 尚未 engraft，pancytopenia 已 12 天。ICU 第 5 天 acute respiratory distress 需插管，BAL 最終有 A. fumigatus，診斷 invasive pulmonary aspergillosis。目前使用 tacrolimus、corticosteroids、fluconazole prophylaxis；WBC 0.2 x 103 cells/mm3、lactate 1.5 mmol/L、SCr 3.4 mg/dL。最適合 antifungal therapy 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Amphotericin 50 mg IV，每日 1 次。"}, {"key": "B", "text": "Isavuconazole loading 後 200 mg IV，每日 1 次。"}, {"key": "C", "text": "Caspofungin loading 後 50 mg IV，每日 1 次。"}, {"key": "D", "text": "Voriconazole loading 後 300 mg IV，每 12 小時。"}], "explanationZh": "本題 AKI 時選不含 IV cyclodextrin vehicle 的 isavuconazole；原教材以此比較 IV voriconazole、amphotericin 及 echinocandin。"}, {"id": "08-self-01", "chapter": 8, "type": "self", "number": 1, "stem": "J.H. is a 30-year-old man admitted to the intensive care unit (ICU) for septic shock. He initially received 30 mL/kg of normal saline for intravenous fluid resuscitation. He required further fluid administration to improve his pulse pressure variation. Despite prophylaxis with enoxaparin 30 mg subcutaneously every 12 hours, J.H. has a proximal deep venous thrombosis. Which pharmacokinetic (PK) alteration most likely contributed to this therapeutic failure?", "context": "", "options": [{"key": "A", "text": "Decreased anti-factor Xa (anti-Xa) activity secondary to decreased volume of distribution (Vd).", "sourceKey": "A"}, {"key": "B", "text": "Decreased anti-Xa activity secondary to decreased absorption.", "sourceKey": "B"}, {"key": "C", "text": "Increased anti-Xa activity secondary to decreased hepatic metabolism.", "sourceKey": "C"}, {"key": "D", "text": "Increased anti-Xa activity secondary to decreased renal elimination.", "sourceKey": "D"}], "answer": "B", "explanation": "Decreased anti-Xa activity occurs in critically ill patients receiving several different low-molecular-weight heparins. This patient received the standard fluid bolus and then required more fluid to raise his central venous pressure. This suggests that the patient has redistributed the fluids to the extravascular space. The data showing that edematous patients have lower anti-Xa activity than non-edematous patients supports the connection between anti-Xa activity and absorption (Answer B is correct). Given the patient’s fluid distribution, the Vd of enoxaparin would likely be increased, not decreased (Answer A is incorrect). Enoxaparin is not hepatically metabolized (Answer C is incorrect). Although a patient could have an increased anti-Xa activity secondary to decreased renal elimination, this would require a CrCl of less than 30 mL/minute/1.73 m2. That the patient had a deep venous thrombosis does not correlate with increased activity (Answer D is incorrect).", "page": 4, "answerPage": 37, "stemZh": "J.H. 為 30 歲男性，因 septic shock 入住 ICU。初始給予 normal saline 30 mL/kg IV resuscitation，仍需額外 fluids 改善 pulse pressure variation。雖使用 enoxaparin 30 mg SC 每 12 小時 prophylaxis，仍發生 proximal DVT。哪個 PK alteration 最可能導致此 treatment failure？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Vd 降低造成 anti-Xa activity 降低。"}, {"key": "B", "text": "Absorption 降低造成 anti-Xa activity 降低。"}, {"key": "C", "text": "Hepatic metabolism 降低造成 anti-Xa activity 增加。"}, {"key": "D", "text": "Renal elimination 降低造成 anti-Xa activity 增加。"}], "explanationZh": "大量 fluids 與 edema 可降低 SC enoxaparin absorption，使 anti-Xa activity 不足。"}, {"id": "08-self-02", "chapter": 8, "type": "self", "number": 2, "stem": "Which most accurately assesses the risk factors for the decreased absorption of enterally administered drugs?", "context": "E.W. is a 48-year-old man (height 70 inches, weight 85 kg) admitted to the trauma ICU after a motorcycle collision. E.W. presents with a traumatic brain injury (TBI; head computed tomography [CT] reveals a depressed skull fracture, frontal subarachnoid hemorrhage, and right intraparenchymal hemorrhage), right acetabulum fracture, bilateral rib fractures, and abdominal trauma. According to his abdominal CT, E.W. must go to the operating room for an exploratory laparotomy for repair of several serosal tears. After surgery, E.W. requires significant resuscitation in his first 24 hours of admission (5 L of normal saline). He is made NPO to allow bowel rest. E.W.’s laboratory values are as follows: serum creatinine (SCr) 1.1 mg/dL, blood urea nitrogen (BUN) 17 mg/dL, and white blood cell count (WBC) 19 × 103 cells/ mm3. The patient’s pulmonary artery catheterization values are cardiac index 4.2 L/minute/m2 (normal 2.8–3.6 L/minute/m2) and pulmonary artery wedge pressure 16 mm Hg. His medication therapy includes a fentanyl continuous infusion of 75 mcg/hour, a propofol continuous infusion of 15 mcg/kg/minute, pantoprazole 40 mg intravenously every 24 hours, enoxaparin 30 mg subcutaneously every 12 hours, and phenytoin 150 mg intravenously every 8 hours.", "options": [{"key": "A", "text": "Intestinal atrophy, pantoprazole therapy, abdominal surgery.", "sourceKey": "A"}, {"key": "B", "text": "TBI, fentanyl therapy, cardiac output.", "sourceKey": "B"}, {"key": "C", "text": "Abdominal surgery, pantoprazole therapy, TBI.", "sourceKey": "C"}, {"key": "D", "text": "Intestinal atrophy, cardiac output, fentanyl therapy.", "sourceKey": "D"}], "answer": "C", "explanation": "Abdominal surgery has been identified as a risk factor for ileus. Antisecretory agents such as pantoprazole alter drug absorption. Traumatic brain injury is significantly associated with intolerance of enteral nutrition, as indicated by increased gastric residuals. This indicates delayed gastric emptying and the risk of altered absorption. Therefore, the combination of abdominal surgery, pantoprazole therapy, and TBI contains the three variables identified in the literature to alter absorption (Answer C is correct). Theoretically, intestinal atrophy could cause changes in absorption, but no data are available to confirm this theory (Answers A and D are incorrect). Changes in cardiac output have been correlated with changes in hepatosplanchnic blood flow. These changes in blood flow are thought to affect absorption, but again, no data have correlated increased cardiac output with increased drug absorption (Answer B is incorrect).", "page": 5, "answerPage": 37, "stemZh": "哪一組最正確描述 enterally administered drugs absorption 下降的 risk factors？", "contextZh": "E.W. 為 48 歲男性，height 70 inches、weight 85 kg，機車事故後入住 trauma ICU。TBI 的 head CT 見 depressed skull fracture、frontal SAH、right intraparenchymal hemorrhage，另有 right acetabulum fracture、bilateral rib fractures 與 abdominal trauma。Abdominal CT 提示需 exploratory laparotomy 修補數處 serosal tears。術後前 24 小時需 5 L normal saline resuscitation，NPO 讓 bowel rest。SCr 1.1 mg/dL、BUN 17 mg/dL、WBC 19 × 103 cells/mm3。Pulmonary artery catheter：cardiac index 4.2 L/minute/m2（normal 2.8–3.6）、PAWP 16 mm Hg。用藥：fentanyl infusion 75 mcg/hour、propofol infusion 15 mcg/kg/minute、pantoprazole 40 mg IV 每 24 小時、enoxaparin 30 mg SC 每 12 小時、phenytoin 150 mg IV 每 8 小時。", "optionsZh": [{"key": "A", "text": "Intestinal atrophy、pantoprazole therapy、abdominal surgery。"}, {"key": "B", "text": "TBI、fentanyl therapy、cardiac output。"}, {"key": "C", "text": "Abdominal surgery、pantoprazole therapy、TBI。"}, {"key": "D", "text": "Intestinal atrophy、cardiac output、fentanyl therapy。"}], "explanationZh": "Abdominal surgery、pantoprazole 改變胃酸環境及 TBI 所致 delayed gastric emptying 都是原教材所述有證據的因素。"}, {"id": "08-self-03", "chapter": 8, "type": "self", "number": 3, "stem": "Before E.W.’s ICU admission, his albumin concentration was 3.8 g/dL, but after surgery, it decreased to 2.1 g/dL. Given this change in albumin, which change in the total and unbound concentration of propofol would be most likely?", "context": "E.W. is a 48-year-old man (height 70 inches, weight 85 kg) admitted to the trauma ICU after a motorcycle collision. E.W. presents with a traumatic brain injury (TBI; head computed tomography [CT] reveals a depressed skull fracture, frontal subarachnoid hemorrhage, and right intraparenchymal hemorrhage), right acetabulum fracture, bilateral rib fractures, and abdominal trauma. According to his abdominal CT, E.W. must go to the operating room for an exploratory laparotomy for repair of several serosal tears. After surgery, E.W. requires significant resuscitation in his first 24 hours of admission (5 L of normal saline). He is made NPO to allow bowel rest. E.W.’s laboratory values are as follows: serum creatinine (SCr) 1.1 mg/dL, blood urea nitrogen (BUN) 17 mg/dL, and white blood cell count (WBC) 19 × 103 cells/ mm3. The patient’s pulmonary artery catheterization values are cardiac index 4.2 L/minute/m2 (normal 2.8–3.6 L/minute/m2) and pulmonary artery wedge pressure 16 mm Hg. His medication therapy includes a fentanyl continuous infusion of 75 mcg/hour, a propofol continuous infusion of 15 mcg/kg/minute, pantoprazole 40 mg intravenously every 24 hours, enoxaparin 30 mg subcutaneously every 12 hours, and phenytoin 150 mg intravenously every 8 hours.", "options": [{"key": "A", "text": "Increased total concentration, decreased unbound concentration.", "sourceKey": "A"}, {"key": "B", "text": "No change in total concentration, increased unbound concentration.", "sourceKey": "B"}, {"key": "C", "text": "Increased total concentration, no change in unbound concentration.", "sourceKey": "C"}, {"key": "D", "text": "Decreased total concentration, increased unbound concentration.", "sourceKey": "D"}], "answer": "B", "explanation": "Propofol is a high extraction ratio drug that is bound to albumin. When the albumin concentration decreases, there is an expected increase in the free fraction of propofol. Using the equations describing the total and unbound concentrations of a high extraction ratio drug, the total concentration is not affected by changes in the free fraction, but unbound concentrations are increased when the free fraction increases (Answer B is correct; Answers A, C, and D are incorrect).", "page": 5, "answerPage": 37, "stemZh": "E.W. 入 ICU 前 albumin 3.8 g/dL，術後降至 2.1 g/dL。Propofol 的 total 與 unbound concentrations 最可能如何改變？", "contextZh": "E.W. 為 48 歲男性，height 70 inches、weight 85 kg，機車事故後入住 trauma ICU。TBI 的 head CT 見 depressed skull fracture、frontal SAH、right intraparenchymal hemorrhage，另有 right acetabulum fracture、bilateral rib fractures 與 abdominal trauma。Abdominal CT 提示需 exploratory laparotomy 修補數處 serosal tears。術後前 24 小時需 5 L normal saline resuscitation，NPO 讓 bowel rest。SCr 1.1 mg/dL、BUN 17 mg/dL、WBC 19 × 103 cells/mm3。Pulmonary artery catheter：cardiac index 4.2 L/minute/m2（normal 2.8–3.6）、PAWP 16 mm Hg。用藥：fentanyl infusion 75 mcg/hour、propofol infusion 15 mcg/kg/minute、pantoprazole 40 mg IV 每 24 小時、enoxaparin 30 mg SC 每 12 小時、phenytoin 150 mg IV 每 8 小時。", "optionsZh": [{"key": "A", "text": "Total 增加、unbound 減少。"}, {"key": "B", "text": "Total 不變、unbound 增加。"}, {"key": "C", "text": "Total 增加、unbound 不變。"}, {"key": "D", "text": "Total 減少、unbound 增加。"}], "explanationZh": "Propofol 為 high-extraction drug；albumin 降低使 free fraction 上升，依題目模型 total concentration 不變、unbound concentration 上升。"}, {"id": "08-self-04", "chapter": 8, "type": "self", "number": 4, "stem": "On postoperative day 3, E.W.’s SCr increased to 3 mg/dL. On postoperative day 4, his SCr is 3.2 mg/ dL. Which variable for assessing kidney function would be most important for determining E.W.’s dosing adjustments?", "context": "E.W. is a 48-year-old man (height 70 inches, weight 85 kg) admitted to the trauma ICU after a motorcycle collision. E.W. presents with a traumatic brain injury (TBI; head computed tomography [CT] reveals a depressed skull fracture, frontal subarachnoid hemorrhage, and right intraparenchymal hemorrhage), right acetabulum fracture, bilateral rib fractures, and abdominal trauma. According to his abdominal CT, E.W. must go to the operating room for an exploratory laparotomy for repair of several serosal tears. After surgery, E.W. requires significant resuscitation in his first 24 hours of admission (5 L of normal saline). He is made NPO to allow bowel rest. E.W.’s laboratory values are as follows: serum creatinine (SCr) 1.1 mg/dL, blood urea nitrogen (BUN) 17 mg/dL, and white blood cell count (WBC) 19 × 103 cells/ mm3. The patient’s pulmonary artery catheterization values are cardiac index 4.2 L/minute/m2 (normal 2.8–3.6 L/minute/m2) and pulmonary artery wedge pressure 16 mm Hg. His medication therapy includes a fentanyl continuous infusion of 75 mcg/hour, a propofol continuous infusion of 15 mcg/kg/minute, pantoprazole 40 mg intravenously every 24 hours, enoxaparin 30 mg subcutaneously every 12 hours, and phenytoin 150 mg intravenously every 8 hours.", "options": [{"key": "A", "text": "BUN/SCr ratio.", "sourceKey": "A"}, {"key": "B", "text": "Total daily urinary output.", "sourceKey": "B"}, {"key": "C", "text": "Estimation of glomerular filtration rate (GFR).", "sourceKey": "C"}, {"key": "D", "text": "History of chronic kidney disease (CKD).", "sourceKey": "D"}], "answer": "C", "explanation": "The update to the KDIGO guidelines notes that the most important factor in determining kidney function is having at least one estimate of GFR. The update recommends that the GFR or the CrCl be estimated to determine this (Answer C is correct). The BUN value can help identify the BUN/SCr ratio indicating intravascular volume contraction and, potentially, a prerenal cause to the patient’s AKI, but it does not help in drug dosing (Answer A is incorrect). Total daily urinary output is helpful in diagnosing AKI (oliguric vs. non-oliguric AKI) and in staging AKI (using a urinary output of less than 0.5 mL/kg/hour) but not in drug dosing (Answer B is incorrect). A history of CKD can help determine a baseline kidney function, but the GFR is still needed for changes in drug dosing (Answer D is incorrect).", "page": 5, "answerPage": 37, "stemZh": "術後第 3 天 E.W. SCr 升至 3 mg/dL，第 4 天為 3.2 mg/dL。決定 dosing adjustments 時，最重要的 kidney function assessment variable 為何？", "contextZh": "E.W. 為 48 歲男性，height 70 inches、weight 85 kg，機車事故後入住 trauma ICU。TBI 的 head CT 見 depressed skull fracture、frontal SAH、right intraparenchymal hemorrhage，另有 right acetabulum fracture、bilateral rib fractures 與 abdominal trauma。Abdominal CT 提示需 exploratory laparotomy 修補數處 serosal tears。術後前 24 小時需 5 L normal saline resuscitation，NPO 讓 bowel rest。SCr 1.1 mg/dL、BUN 17 mg/dL、WBC 19 × 103 cells/mm3。Pulmonary artery catheter：cardiac index 4.2 L/minute/m2（normal 2.8–3.6）、PAWP 16 mm Hg。用藥：fentanyl infusion 75 mcg/hour、propofol infusion 15 mcg/kg/minute、pantoprazole 40 mg IV 每 24 小時、enoxaparin 30 mg SC 每 12 小時、phenytoin 150 mg IV 每 8 小時。", "optionsZh": [{"key": "A", "text": "BUN/SCr ratio。"}, {"key": "B", "text": "每日 total urine output。"}, {"key": "C", "text": "Estimated GFR。"}, {"key": "D", "text": "CKD 病史。"}], "explanationZh": "原題選擇 GFR/CrCl estimate，作為 dose adjustment 的關鍵資訊；SCr 動態變化時估算仍有侷限。"}, {"id": "08-self-05", "chapter": 8, "type": "self", "number": 5, "stem": "According to S.H.’s anticipated PK changes and guideline recommendations, which would be the most appropriate intravenous loading dose of vancomycin?", "context": "S.H. is a 35-year-old man (height 70 inches, weight 85 kg) admitted to the medical ICU because of sepsis caused by hospital-acquired pneumonia. He is empirically treated with intermittent vancomycin, piperacillin/ tazobactam, and ciprofloxacin. His laboratory values are as follows: SCr 1 mg/dL, BUN 12 mg/dL, and WBC 18 × 103 cells/mm3.", "options": [{"key": "A", "text": "1000 mg.", "sourceKey": "A"}, {"key": "B", "text": "1500 mg.", "sourceKey": "B"}, {"key": "C", "text": "2500 mg.", "sourceKey": "C"}, {"key": "D", "text": "3500 mg.", "sourceKey": "D"}], "answer": "C", "explanation": "The ASHP (American Society of Health-System Pharmacists) vancomycin dosing guidelines recommend a 20- to 25-mg/kg loading dose of vancomycin for serious infections. Given the patient’s sepsis, he is likely to have more interstitial fluid, which will increase the Vd of hydrophilic drugs like vancomycin. The 2500-mg dose is near the top end of the recommended 20- to 25-mg/kg loading dose (Answer C is correct). The other doses are outside the recommended 20- to 25-mg/kg loading dose range (Answers A, B, and D are incorrect).", "page": 5, "answerPage": 37, "stemZh": "依 S.H. 預期的 PK changes 與原教材 guideline recommendations，最適合的 IV vancomycin loading dose 為何？", "contextZh": "S.H. 為 35 歲男性，height 70 inches、weight 85 kg，因 HAP 所致 sepsis 入住 medical ICU。Empiric regimen 為 intermittent vancomycin、piperacillin/tazobactam、ciprofloxacin。SCr 1 mg/dL、BUN 12 mg/dL、WBC 18 × 103 cells/mm3。", "optionsZh": [{"key": "A", "text": "1000 mg."}, {"key": "B", "text": "1500 mg."}, {"key": "C", "text": "2500 mg."}, {"key": "D", "text": "3500 mg."}], "explanationZh": "原題答案為 2500 mg，理由為 sepsis 的 Vd 增加；原文的 20–25 mg/kg 描述與 85 kg 對應此選項並不完全一致，保留原題答案並標明原文數值矛盾。"}, {"id": "08-self-06", "chapter": 8, "type": "self", "number": 6, "stem": "S.H. is given a diagnosis of methicillin-resistant Staphylococcus aureus hospital-acquired pneumonia. On day 10 of vancomycin therapy, his vancomycin area under the curve (AUC) is 700 mg x h/L. His previous vancomycin AUC was 425 mg x h/L on the same dosing regimen. Which most likely explains what transpired?", "context": "S.H. is a 35-year-old man (height 70 inches, weight 85 kg) admitted to the medical ICU because of sepsis caused by hospital-acquired pneumonia. He is empirically treated with intermittent vancomycin, piperacillin/ tazobactam, and ciprofloxacin. His laboratory values are as follows: SCr 1 mg/dL, BUN 12 mg/dL, and WBC 18 × 103 cells/mm3.", "options": [{"key": "A", "text": "Augmented renal excretion returned to normal.", "sourceKey": "A"}, {"key": "B", "text": "Vd increased to larger than normal.", "sourceKey": "B"}, {"key": "C", "text": "Tissue penetration decreased to below normal.", "sourceKey": "C"}, {"key": "D", "text": "Liver blood flow returned to normal.", "sourceKey": "D"}], "answer": "A", "explanation": "Critically ill patients younger than 50 are more likely to have augmented renal excretion. Vancomycin is excreted unchanged in the urine. The initial dosing would result in a therapeutic trough concentration, given the increased (augmented) renal excretion of vancomycin. Augmented renal excretion usually returns to normal around day 7. An increased vancomycin trough after a previously therapeutic trough is most likely associated with decreased renal excretion at day 10 of therapy (Answer A is correct). There is no indication that the Vd has changed, which would likely result in lower or unchanged concentrations (Answer B is incorrect). Vancomycin tissue penetration may be better if inflammation is present, but no documented studies correlate decreased inflammation with increased serum concentrations (Answer C is incorrect). The liver does not appreciably metabolize vancomycin, and liver blood flow would not be a factor in the vancomycin concentration (Answer D is incorrect).", "page": 5, "answerPage": 37, "stemZh": "S.H. 確診 MRSA HAP。Vancomycin 第 10 天 AUC 為 700 mg x h/L；同一 dosing regimen 之前 AUC 為 425 mg x h/L。最可能的原因為何？", "contextZh": "S.H. 為 35 歲男性，height 70 inches、weight 85 kg，因 HAP 所致 sepsis 入住 medical ICU。Empiric regimen 為 intermittent vancomycin、piperacillin/tazobactam、ciprofloxacin。SCr 1 mg/dL、BUN 12 mg/dL、WBC 18 × 103 cells/mm3。", "optionsZh": [{"key": "A", "text": "Augmented renal excretion 恢復正常。"}, {"key": "B", "text": "Vd 增至高於正常。"}, {"key": "C", "text": "Tissue penetration 降至低於正常。"}, {"key": "D", "text": "Liver blood flow 恢復正常。"}], "explanationZh": "ARC 恢復至正常使 vancomycin renal clearance 減少，同 dose 下 AUC 增加。"}, {"id": "08-self-07", "chapter": 8, "type": "self", "number": 7, "stem": "B.B. is 40-year-old woman with a surgical site infection caused by Pseudomonas aeruginosa. She is initiated on a piperacillin/tazobactam 3.375 g intravenous infusion over 4 hours every 8 hours. Which is the most likely benefit of this approach with piperacillin/tazobactam?", "context": "", "options": [{"key": "A", "text": "Decreased mortality supported by prospective controlled studies.", "sourceKey": "A"}, {"key": "B", "text": "Decreased neurotoxicity supported by prospective controlled studies.", "sourceKey": "B"}, {"key": "C", "text": "Decreased mortality supported by retrospective reviews.", "sourceKey": "C"}, {"key": "D", "text": "Decreased neurotoxicity supported by retrospective reviews.", "sourceKey": "D"}], "answer": "C", "explanation": "Prospective controlled studies of prolonged piperacillin/tazobactam infusions have shown no improvement in mortality (Answer A is incorrect). No studies have reported neurotoxicity as an outcome (Answers B and D are incorrect). Only retrospective studies have shown improvements in mortality with the use of prolonged or continuous infusions of piperacillin/tazobactam (Answer C is correct).", "page": 5, "answerPage": 38, "stemZh": "B.B. 為 40 歲女性，P. aeruginosa surgical-site infection 開始 piperacillin/tazobactam 3.375 g IV，每 8 小時輸注 4 小時。原教材所述此給藥方式最可能的 benefit 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Prospective controlled studies 支持 mortality 降低。"}, {"key": "B", "text": "Prospective controlled studies 支持 neurotoxicity 降低。"}, {"key": "C", "text": "Retrospective reviews 支持 mortality 降低。"}, {"key": "D", "text": "Retrospective reviews 支持 neurotoxicity 降低。"}], "explanationZh": "依原教材當時的證據，prolonged infusion 降低 mortality 的支持來自 retrospective reviews，而非其列出的 prospective controlled studies。"}, {"id": "08-self-08", "chapter": 8, "type": "self", "number": 8, "stem": "C.W. is a 52-year-old man admitted to the ICU for acute respiratory failure. He is given scheduled oral morphine for pain control. Which PK variable would most likely affect the hepatic metabolism of morphine?", "context": "", "options": [{"key": "A", "text": "Increased α 1 -acid glycoprotein (AAG).", "sourceKey": "A"}, {"key": "B", "text": "Decreased albumin.", "sourceKey": "B"}, {"key": "C", "text": "Increased hepatic blood flow.", "sourceKey": "C"}, {"key": "D", "text": "Increased intrinsic clearance.", "sourceKey": "D"}], "answer": "C", "explanation": "Morphine is a high extraction ratio drug. As such, its hepatic metabolism or hepatic clearance depends only on hepatic blood flow. Hepatic clearance equals hepatic blood flow (Answer C is correct). Morphine does not bind to AAG (Answer A is incorrect). Because hepatic blood flow is the main determinant of hepatic metabolism of morphine, changes in protein binding do not affect metabolism (Answer B is incorrect). Changes in intrinsic clearance do not affect the metabolism of morphine as significantly as does hepatic blood flow (Answer D is incorrect).", "page": 5, "answerPage": 38, "stemZh": "C.W. 為 52 歲男性，因 acute respiratory failure 入住 ICU，定時 oral morphine 止痛。哪個 PK variable 最可能影響 morphine hepatic metabolism？", "contextZh": "", "optionsZh": [{"key": "A", "text": "α1-acid glycoprotein（AAG）增加。"}, {"key": "B", "text": "Albumin 減少。"}, {"key": "C", "text": "Hepatic blood flow 增加。"}, {"key": "D", "text": "Intrinsic clearance 增加。"}], "explanationZh": "Morphine 為 high-extraction drug，hepatic clearance 主要受 hepatic blood flow 影響。"}, {"id": "08-case-01", "chapter": 8, "type": "case", "number": 1, "stem": "M.J. is a 70-year-old man admitted to the neurosurgical ICU for an aneurysmal subarachnoid hemorrhage. His initial treatment included placement of an external ventricular drain. Subsequently, he had a maximum temperature of 101.5°F, a WBC of 15 × 103 cells/mm3, and a cerebrospinal fluid culture positive for methicillin-resistant S. aureus. Intraventricular vancomycin 20 mg is used for therapy. Which is the best rationale for this approach?", "context": "", "options": [{"key": "A", "text": "Demonstrated superiority to intravenous antibiotics.", "sourceKey": "A"}, {"key": "B", "text": "Maximizing localized antibiotic concentrations.", "sourceKey": "B"}, {"key": "C", "text": "Safer administration method.", "sourceKey": "C"}, {"key": "D", "text": "Reducing the ototoxicity of vancomycin.", "sourceKey": "D"}], "answer": "B", "explanation": "Increasing the concentration of an antibiotic at an infection site is most important (Answer B is correct). Although case reports describe the use of intraventricular antibiotics in the treatment of meningitis, they have not shown superiority (Answer A is incorrect). Although there is the potential to reduce vancomycininduced nephrotoxicity, no studies have compared the nephrotoxicity of intraventricular antibiotics with that of intravenous antibiotics, likely because this is not the rationale for their use (Answer C is incorrect). Ototoxicity could also be reduced, but this was not the intent of the locally instilled antibiotics (Answer D is incorrect).", "page": 8, "answerPage": 35, "stemZh": "M.J. 為 70 歲男性，因 aneurysmal SAH 入住 neurosurgical ICU，初始放置 EVD。隨後最高 temperature 101.5°F、WBC 15 × 103 cells/mm3，CSF culture 為 MRSA，使用 intraventricular vancomycin 20 mg。此給藥方式最佳理由為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "已證實優於 IV antibiotics。"}, {"key": "B", "text": "最大化 local antibiotic concentrations。"}, {"key": "C", "text": "較安全的 administration method。"}, {"key": "D", "text": "降低 vancomycin ototoxicity。"}], "explanationZh": "局部給藥主要為提高 infection site 的 antibiotic concentration，並非已證實較 IV therapy 優越或更安全。"}, {"id": "08-case-02", "chapter": 8, "type": "case", "number": 2, "stem": "I.L. is a 32-year-old man receiving stress ulcer prophylaxis with esomeprazole 40 mg intravenously every day. Which drug will most likely have an increased absorption secondary to the increased gastric pH?", "context": "", "options": [{"key": "A", "text": "Carvedilol.", "sourceKey": "A"}, {"key": "B", "text": "Ciprofloxacin.", "sourceKey": "B"}, {"key": "C", "text": "Diazepam.", "sourceKey": "C"}, {"key": "D", "text": "Digoxin.", "sourceKey": "D"}], "answer": "D", "explanation": "Three studies have documented an increase in digoxin absorption when the gastric pH is increased, with two studies noting the cause of increased gastric pH from a proton pump inhibitor (Answer D is correct). However, no studies have shown a decreased absorption of carvedilol (Answer A is incorrect), ciprofloxacin (Answer B is incorrect), or diazepam (Answer C is incorrect).", "page": 12, "answerPage": 35, "stemZh": "I.L. 為 32 歲男性，stress ulcer prophylaxis 使用 esomeprazole 40 mg IV，每日 1 次。Gastric pH 增加最可能使哪個藥物 absorption 增加？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Carvedilol."}, {"key": "B", "text": "Ciprofloxacin."}, {"key": "C", "text": "Diazepam."}, {"key": "D", "text": "Digoxin."}], "explanationZh": "原教材引用研究顯示較高 gastric pH 可增加 digoxin absorption。"}, {"id": "08-case-03", "chapter": 8, "type": "case", "number": 3, "stem": "R.H. is 20-year-old man who presents to the emergency department with nausea and vomiting. His vital signs are significant for heart rate 130 beats/minute, blood pressure 98/62 mm Hg, and respiratory rate 28 breaths/minute. Laboratory tests reveal an arterial blood gas significant for a pH of 7.11, Pco 2 of 18 mm Hg, and bicarbonate of 5.2 mEq/L. His basic metabolic panel is significant for potassium concentration 5 mEq/L, BUN 22 mg/dL, SCr 1.4 mg/dL, and blood glucose 400 mg/dL. Which changes would be most likely to occur in the Vd of a weak acid like ciprofloxacin in this patient?", "context": "", "options": [{"key": "A", "text": "Increased because of decreased ionization.", "sourceKey": "A"}, {"key": "B", "text": "Decreased because of increased ionization.", "sourceKey": "B"}, {"key": "C", "text": "No change because of no change in ionization.", "sourceKey": "C"}, {"key": "D", "text": "Decreased because of decreased ionization.", "sourceKey": "D"}], "answer": "A", "explanation": "A decrease in the ionization of a drug allows the drug to pass more easily through membranes. Increasing the ionization would decrease the Vd by decreasing its ability to pass through membranes. A weak acid would be less ionized in a more acidic environment. The patient is likely in diabetic ketoacidosis with a definite acidosis. Aspirin (a weak acid) is less likely to be ionized and would have an increased Vd (Answer A is correct; Answers B–D are incorrect).", "page": 15, "answerPage": 35, "stemZh": "R.H. 為 20 歲男性，因 nausea 與 vomiting 至 ED。HR 130 beats/minute、BP 98/62 mm Hg、RR 28 breaths/minute。ABG：pH 7.11、PCO2 18 mm Hg、HCO3 5.2 mEq/L。Potassium 5 mEq/L、BUN 22 mg/dL、SCr 1.4 mg/dL、glucose 400 mg/dL。題目所稱 weak acid（如 ciprofloxacin）的 Vd 最可能如何改變？", "contextZh": "", "optionsZh": [{"key": "A", "text": "因 ionization 減少而增加。"}, {"key": "B", "text": "因 ionization 增加而減少。"}, {"key": "C", "text": "Ionization 無變化，因此不變。"}, {"key": "D", "text": "因 ionization 減少而減少。"}], "explanationZh": "依原題模型，acidic environment 使 weak acid ionization 降低、更易穿越 membranes，Vd 增加；原文以 ciprofloxacin 舉例而 explanation 改以 aspirin，屬原教材不一致。"}, {"id": "08-case-04", "chapter": 8, "type": "case", "number": 4, "stem": "B.B. is a 62-year-old woman admitted to the ICU for septic shock. She has received 6 L of crystalloids in the past 24 hours, including her initial resuscitation and maintenance fluids. Which of the following antibiotic volumes of distribution would most likely be unaffected by the amount of intravenous fluids administered?", "context": "", "options": [{"key": "A", "text": "Tobramycin.", "sourceKey": "A"}, {"key": "B", "text": "Daptomycin.", "sourceKey": "B"}, {"key": "C", "text": "Levofloxacin.", "sourceKey": "C"}, {"key": "D", "text": "Cefepime.", "sourceKey": "D"}], "answer": "C", "explanation": "Levofloxacin has a large Vd. The increase in interstitial fluid volume caused by 6 L of crystalloids would increase the Vd of hydrophilic drugs but would not appreciably affect the Vd of a drug like levofloxacin, which already has a large Vd (Answer C is correct). Tobramycin, daptomycin, and cefepime have relatively small Vd values and are increased in patients with increased interstitial volumes (Answers A, B, and D are incorrect).", "page": 15, "answerPage": 35, "stemZh": "B.B. 為 62 歲女性，因 septic shock 入住 ICU，過去 24 小時 resuscitation 與 maintenance 合計 6 L crystalloids。哪個 antibiotic 的 Vd 最可能不受這些 fluids 明顯影響？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Tobramycin."}, {"key": "B", "text": "Daptomycin."}, {"key": "C", "text": "Levofloxacin."}, {"key": "D", "text": "Cefepime."}], "explanationZh": "Levofloxacin 原本 Vd 大，interstitial fluids 增加對其影響較小；其他選項較 hydrophilic、Vd 較小。"}, {"id": "08-case-05", "chapter": 8, "type": "case", "number": 5, "stem": "A.P. is a 35-year-old woman admitted to the ICU for an acute asthma exacerbation. She was intubated and required mechanical ventilation. She is prescribed morphine for pain control. Which best describes the effect of mechanical ventilation on morphine unbound concentrations?", "context": "", "options": [{"key": "A", "text": "Increases oxygenation delivery to the liver and increases the unbound concentration.", "sourceKey": "A"}, {"key": "B", "text": "Decreases hepatic blood flow and increases the unbound concentration.", "sourceKey": "B"}, {"key": "C", "text": "Increases cytokine production and decreases the unbound concentration.", "sourceKey": "C"}, {"key": "D", "text": "Cannot affect the unbound concentration.", "sourceKey": "D"}], "answer": "B", "explanation": "Morphine is a high extraction ratio drug. Mechanical ventilation can decrease cardiac output and thus decrease liver blood flow. The decrease in liver blood flow is inversely proportional to the unbound steadystate concentration. Therefore, it both decreases the hepatic blood flow and increases the unbound concentration (Answer B is correct). The effects of mechanical ventilation on cardiac output would likely decrease oxygen delivery (Answer A is incorrect). Cytokines affect intrinsic clearance but would not affect the concentration of a high extraction ratio drug (Answer C is incorrect). Mechanical ventilation can indirectly affect the unbound concentration (Answer D is incorrect).", "page": 20, "answerPage": 35, "stemZh": "A.P. 為 35 歲女性，因 acute asthma exacerbation 入住 ICU，插管並需 mechanical ventilation，以 morphine 止痛。Mechanical ventilation 對 morphine unbound concentration 的影響為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "增加 liver oxygen delivery，增加 unbound concentration。"}, {"key": "B", "text": "降低 hepatic blood flow，增加 unbound concentration。"}, {"key": "C", "text": "增加 cytokine production，降低 unbound concentration。"}, {"key": "D", "text": "不會影響 unbound concentration。"}], "explanationZh": "Ventilation 可降低 CO 與 hepatic blood flow；對 high-extraction morphine，clearance 減少可提高 unbound concentration。"}, {"id": "08-case-06", "chapter": 8, "type": "case", "number": 6, "stem": "J.M. is a 34-year-old woman admitted to the ICU with new-onset sepsis. She was continued on her home medication, diazepam, for anxiety. She is empirically initiated on vancomycin 1 g intravenously every 12 hours, piperacillin/tazobactam 3.375 g intravenously every 6 hours, and fluconazole 400 mg intravenously every 24 hours. Which PD response would you most expect in J.M.?", "context": "", "options": [{"key": "A", "text": "Increased risk of anxiety caused by an increased intrinsic clearance of diazepam.", "sourceKey": "E"}, {"key": "B", "text": "Increased risk of sedation caused by a decreased intrinsic clearance of diazepam.", "sourceKey": "F"}, {"key": "C", "text": "Increased risk of anxiety caused by a decreased unbound fraction of diazepam.", "sourceKey": "G"}, {"key": "D", "text": "Increased risk of sedation caused by an increased unbound fraction of diazepam.", "sourceKey": "H"}], "answer": "B", "explanation": "This patient has sepsis, which is associated with an increased production of inflammatory cytokines. These cytokines can decrease the activity of the CYP enzymes and decrease intrinsic clearance. In addition, fluconazole inhibits CYP2C19 activity. Diazepam is a low extraction ratio drug. The hepatic clearance of diazepam is affected by changes in intrinsic clearance (including CYP2C19 activity). The unbound steadystate concentration would be increased, because of a decrease in intrinsic clearance caused by the inflammatory cytokines and CYP2C19 inhibition by fluconazole. The increased unbound steady-state concentrations would cause increased sedation (Answer B is correct). There is no cause for an increase in intrinsic clearance and a corresponding decrease in sedation (Answer A is incorrect). There is no reason for this patient to have a decrease in the unbound fraction of diazepam (Answer C is incorrect). A decrease in albumin could occur with sepsis and would result in an increase in the unbound fraction of diazepam. The increase in unbound fraction would not affect the unbound steady-state concentration, nor would it affect the level of sedation (Answer D is incorrect).", "page": 20, "answerPage": 35, "stemZh": "J.M. 為 34 歲女性，因 new-onset sepsis 入住 ICU，持續原 home diazepam 處理 anxiety。Empiric vancomycin 1 g IV 每 12 小時、piperacillin/tazobactam 3.375 g IV 每 6 小時、fluconazole 400 mg IV 每 24 小時。最預期哪個 PD response？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Diazepam intrinsic clearance 增加造成 anxiety risk 增加。"}, {"key": "B", "text": "Diazepam intrinsic clearance 降低造成 sedation risk 增加。"}, {"key": "C", "text": "Diazepam unbound fraction 降低造成 anxiety risk 增加。"}, {"key": "D", "text": "Diazepam unbound fraction 增加造成 sedation risk 增加。"}], "explanationZh": "Sepsis cytokines 與 fluconazole enzyme inhibition 可降低 diazepam intrinsic clearance，提高 unbound exposure 與 sedation risk。"}, {"id": "08-case-07", "chapter": 8, "type": "case", "number": 7, "stem": "P.M. is receiving phenytoin for the treatment of posttraumatic seizures. The measured total phenytoin concentration is 8 mcg/mL. You calculate the adjusted concentration according to P.M.’s hypoalbuminemia (albumin of 2.5 g/dL) and determine the concentration to be approximately 13 mcg/mL. Which of the following relationships best describes why an adjusted total phenytoin concentration must be calculated?", "context": "", "options": [{"key": "A", "text": "The phenytoin C ssu is increased because of an increase in the f u .", "sourceKey": "A"}, {"key": "B", "text": "The phenytoin C ss is increased because of an increase in f u .", "sourceKey": "B"}, {"key": "C", "text": "The phenytoin C ssu is decreased because of an increase in f u .", "sourceKey": "C"}, {"key": "D", "text": "The phenytoin C ss is decreased because of an increase in f u .", "sourceKey": "D"}], "answer": "D", "explanation": "Under normal conditions, the unbound steady-state concentration for phenytoin is expected to be 10% of the total concentration. Thus, a total concentration of 10-20 mg/L is equivalent to an unbound steady-state concentration of 1-2 mg/L. When the unbound fraction changes, this ratio changes. The unbound steady-state concentration does not change, but the total concentration decreases, which causes the change in the ratio. Using the equations for low extraction ratio drugs (like phenytoin) to explain what has occurred, the unbound fraction is inversely proportional to the total concentration but has no effect on the unbound steady-state concentration (Answer D is correct; Answers A, B, and C are incorrect).", "page": 20, "answerPage": 35, "stemZh": "P.M. 使用 phenytoin 治療 posttraumatic seizures，measured total concentration 8 mcg/mL。依 hypoalbuminemia（albumin 2.5 g/dL）計算 adjusted concentration 約 13 mcg/mL。哪個關係最能解釋為何需計算 adjusted total concentration？", "contextZh": "", "optionsZh": [{"key": "A", "text": "fu 增加使 phenytoin Css,u 增加。"}, {"key": "B", "text": "fu 增加使 phenytoin Css 增加。"}, {"key": "C", "text": "fu 增加使 phenytoin Css,u 減少。"}, {"key": "D", "text": "fu 增加使 phenytoin Css 減少。"}], "explanationZh": "依 low-extraction model，fu 增加使 total Css 降低，而 unbound Css 不因 protein binding 變化而同幅改變。"}, {"id": "08-case-08", "chapter": 8, "type": "case", "number": 8, "stem": "C.P. is a 50-year-old man admitted to the medical ICU for management of diabetic ketoacidosis. His medical history is significant for hypertension, type 1 diabetes, and a myocardial infarction 2 years ago. He quit smoking last year and drinks alcohol occasionally. His vital signs are significant for heart rate 125 beats/ minute, blood pressure 95/65 mm Hg, and respiratory rate 22 breaths/minute. His significant hypovolemia contributed to the development of AKI. His current SCr is 2.8 mg/dL. His blood glucose is significantly elevated at 350 mg/dL. He will be initiated on a continuous intravenous infusion of insulin to correct his blood glucose. Which factor is most important to consider when dosing insulin in C.P.?", "context": "", "options": [{"key": "A", "text": "Decreased renal metabolism of insulin.", "sourceKey": "A"}, {"key": "B", "text": "Increased Vd of insulin.", "sourceKey": "B"}, {"key": "C", "text": "Increased hepatic metabolism of insulin.", "sourceKey": "C"}, {"key": "D", "text": "Decreased receptor binding of insulin.", "sourceKey": "D"}], "answer": "A", "explanation": "The kidney plays a role in the excretion and metabolism of insulin. Acute kidney injury will decrease the ability of the kidney to metabolize insulin, which will increase circulating insulin and contribute to hypoglycemia (Answer A is correct). The Vd of insulin in AKI is not well studied and has not been linked with episodes of hypoglycemia (Answer B is incorrect). Hepatic impairment may increase the risk of hypoglycemia with insulin, but an increase in hepatic metabolism is unlikely to affect the risk of hypoglycemia in AKI (Answer C is incorrect). Insulin resistance has been reported in patients with AKI, but this would not contribute to hypoglycemia (Answer D is incorrect).", "page": 20, "answerPage": 36, "stemZh": "C.P. 為 50 歲男性，因 DKA 入住 medical ICU，有 hypertension、type 1 diabetes 與 2 年前 MI，去年戒菸、偶爾飲酒。HR 125 beats/minute、BP 95/65 mm Hg、RR 22 breaths/minute。明顯 hypovolemia 導致 AKI，SCr 2.8 mg/dL、glucose 350 mg/dL，將開始 continuous IV insulin。Insulin dosing 最重要的考量為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Insulin renal metabolism 降低。"}, {"key": "B", "text": "Insulin Vd 增加。"}, {"key": "C", "text": "Insulin hepatic metabolism 增加。"}, {"key": "D", "text": "Insulin receptor binding 減少。"}], "explanationZh": "腎臟參與 insulin metabolism 及 clearance；AKI 使 renal metabolism 降低，增加 exposure 與 hypoglycemia risk。"}, {"id": "09-self-01", "chapter": 9, "type": "self", "number": 1, "stem": "In E.R., which drug-induced kidney disease phenotype is most associated with his antibiotic program?", "context": "E.R. is a 67-year-old man admitted to your intensive care unit (ICU) several days ago with acute respiratory failure. He required mechanical ventilation and was placed on empiric antibiotics to cover community-acquired pneumonia. His kidney function has worsened over the past 5 days (serum creatinine [SCr] 0.6 mg/dL on admission; today, 2.4 mg/dL), and he now requires kidney replacement therapy (KRT) with continuous venovenous hemofiltration (CVVH). He is extubated, but still unstable. His current medications include as-needed fentanyl, norepinephrine, ceftriaxone, azithromycin, and heparin prophylaxis.", "options": [{"key": "A", "text": "AKI.", "sourceKey": "A"}, {"key": "B", "text": "Glomerular disease.", "sourceKey": "B"}, {"key": "C", "text": "Nephrolithiasis/crystalluria.", "sourceKey": "C"}, {"key": "D", "text": "Tubular dysfunction.", "sourceKey": "D"}], "answer": "A", "explanation": "The drug-induced kidney disease phenotype most likely associated with these antibiotics is AIN from ceftriaxone. Acute interstitial nephritis is considered under the AKI phenotype (Answer A is correct). Azithromycin would unlikely cause drug-induced kidney disease. Although AIN is an overall uncommon cause of DIKD, in 75% of AIN cases, one or more drugs are involved. Several medications have been associated with this type of kidney disease, including penicillins, cephalosporins, sulfonamides, ciprofloxacin, vancomycin, NSAIDs and COX-2 inhibitors, proton pump inhibitors, immune checkpoint inhibitors, antiepileptic drugs, ranitidine, diuretics, and cocaine. This patient may have other contributing factors to AKI, including sepsis and shock. Glomerular disease, nephrolithiasis, and tubular dysfunction have not been associated with cephalosporins (Answers B-D are incorrect).", "page": 4, "answerPage": 26, "stemZh": "E.R. 的 antibiotic regimen 最相關的 drug-induced kidney disease phenotype 為何？", "contextZh": "E.R. 為 67 歲男性，數天前因 acute respiratory failure 入住 ICU，需 mechanical ventilation 並使用 empiric antibiotics 涵蓋 CAP。過去 5 天 kidney function 惡化，SCr 從入院 0.6 mg/dL 升至今日 2.4 mg/dL，現需 CVVH KRT。已 extubate，但仍不穩定。目前藥物包含 PRN fentanyl、norepinephrine、ceftriaxone、azithromycin 與 heparin prophylaxis。", "optionsZh": [{"key": "A", "text": "AKI。"}, {"key": "B", "text": "Glomerular disease。"}, {"key": "C", "text": "Nephrolithiasis／crystalluria。"}, {"key": "D", "text": "Tubular dysfunction。"}], "explanationZh": "Ceftriaxone 可能造成 AIN，歸在 AKI phenotype；sepsis、shock 等也可共同造成 AKI。"}, {"id": "09-self-02", "chapter": 9, "type": "self", "number": 2, "stem": "What KDIGO stage best characterizes E.R.’s AKI?", "context": "E.R. is a 67-year-old man admitted to your intensive care unit (ICU) several days ago with acute respiratory failure. He required mechanical ventilation and was placed on empiric antibiotics to cover community-acquired pneumonia. His kidney function has worsened over the past 5 days (serum creatinine [SCr] 0.6 mg/dL on admission; today, 2.4 mg/dL), and he now requires kidney replacement therapy (KRT) with continuous venovenous hemofiltration (CVVH). He is extubated, but still unstable. His current medications include as-needed fentanyl, norepinephrine, ceftriaxone, azithromycin, and heparin prophylaxis.", "options": [{"key": "A", "text": "Stage 1.", "sourceKey": "A"}, {"key": "B", "text": "Stage 2.", "sourceKey": "B"}, {"key": "C", "text": "Stage 3.", "sourceKey": "C"}, {"key": "D", "text": "Cannot determine because urinary output (UOP) is not provided.", "sourceKey": "D"}], "answer": "C", "explanation": "Stage 3 AKI is met by both the SCr criteria (3 x baseline) and the need for KRT (Answer C is correct; Answers A and B are incorrect). Urinary output is not needed to stage the kidney dysfunction in this case because the patient fulfills other criteria (Answer D is incorrect).", "page": 4, "answerPage": 26, "stemZh": "E.R. 的 AKI 最符合哪個 KDIGO stage？", "contextZh": "E.R. 為 67 歲男性，數天前因 acute respiratory failure 入住 ICU，需 mechanical ventilation 並使用 empiric antibiotics 涵蓋 CAP。過去 5 天 kidney function 惡化，SCr 從入院 0.6 mg/dL 升至今日 2.4 mg/dL，現需 CVVH KRT。已 extubate，但仍不穩定。目前藥物包含 PRN fentanyl、norepinephrine、ceftriaxone、azithromycin 與 heparin prophylaxis。", "optionsZh": [{"key": "A", "text": "Stage 1。"}, {"key": "B", "text": "Stage 2。"}, {"key": "C", "text": "Stage 3。"}, {"key": "D", "text": "無 UOP，無法判定。"}], "explanationZh": "SCr 已超過 baseline 3 倍，且需 KRT，任一條件即可符合 stage 3，不須一定有 UOP 才分期。"}, {"id": "09-self-03", "chapter": 9, "type": "self", "number": 3, "stem": "E.R. continues to worsen. He is now febrile with an increasing white blood cell count (WBC). You are asked to dose his antibiotics while he receives CVVH. Which would be the best place to begin looking for dosing recommendations?", "context": "E.R. is a 67-year-old man admitted to your intensive care unit (ICU) several days ago with acute respiratory failure. He required mechanical ventilation and was placed on empiric antibiotics to cover community-acquired pneumonia. His kidney function has worsened over the past 5 days (serum creatinine [SCr] 0.6 mg/dL on admission; today, 2.4 mg/dL), and he now requires kidney replacement therapy (KRT) with continuous venovenous hemofiltration (CVVH). He is extubated, but still unstable. His current medications include as-needed fentanyl, norepinephrine, ceftriaxone, azithromycin, and heparin prophylaxis.", "options": [{"key": "A", "text": "Intermittent hemodialysis (IHD) guidelines.", "sourceKey": "A"}, {"key": "B", "text": "Package insert.", "sourceKey": "B"}, {"key": "C", "text": "Primary literature/dosing summaries.", "sourceKey": "C"}, {"key": "D", "text": "Estimates using an estimated sieving coefficient.", "sourceKey": "D"}], "answer": "C", "explanation": "Answer C is correct. Drug-dosing recommendations for IHD can be found in many resources. However, dosing during continuous KRT and SLED/EDD is less clear. Primary literature and/or summary tables for continuous KRT and SLED should be referenced because these recommendations are not usually found in other sources (Answers A and B are incorrect). Use caution to ensure that identical modes of continuous KRT are referenced with similar flow rates. Drug dosing using a sieving coefficient should only be used when a review of the literature fails to provide specific drug adjustment recommendations (Answer D is incorrect).", "page": 4, "answerPage": 26, "stemZh": "E.R. 持續惡化，新發 fever 且 WBC 增加。要調整 CVVH 期間 antibiotic dosing，最適合先參考哪個來源？", "contextZh": "E.R. 為 67 歲男性，數天前因 acute respiratory failure 入住 ICU，需 mechanical ventilation 並使用 empiric antibiotics 涵蓋 CAP。過去 5 天 kidney function 惡化，SCr 從入院 0.6 mg/dL 升至今日 2.4 mg/dL，現需 CVVH KRT。已 extubate，但仍不穩定。目前藥物包含 PRN fentanyl、norepinephrine、ceftriaxone、azithromycin 與 heparin prophylaxis。", "optionsZh": [{"key": "A", "text": "IHD guidelines。"}, {"key": "B", "text": "Package insert。"}, {"key": "C", "text": "Primary literature／dosing summaries。"}, {"key": "D", "text": "用 estimated sieving coefficient 推算。"}], "explanationZh": "Continuous KRT dose 建議應先查相同 modality 與近似 flow rates 的 primary literature／dosing summaries。"}, {"id": "09-self-04", "chapter": 9, "type": "self", "number": 4, "stem": "Which best describes the method for solute removal during CVVH?", "context": "", "options": [{"key": "A", "text": "Convection.", "sourceKey": "A"}, {"key": "B", "text": "Diffusion.", "sourceKey": "B"}, {"key": "C", "text": "Both convection and diffusion.", "sourceKey": "C"}, {"key": "D", "text": "Membrane binding.", "sourceKey": "D"}], "answer": "A", "explanation": "Solute removal during CVVH is by convection, which is primarily influenced by membrane pore size, free fraction of drug, and ultrafiltration rate. Diffusion is the process of clearance during CVVHD making Answers B and C incorrect. Membrane binding does occur but is not the primary route of clearance during CVVH (Answer D is incorrect).", "page": 4, "answerPage": 26, "stemZh": "CVVH 的主要 solute removal mechanism 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Convection。"}, {"key": "B", "text": "Diffusion。"}, {"key": "C", "text": "Convection 與 diffusion 皆有。"}, {"key": "D", "text": "Membrane binding。"}], "explanationZh": "CVVH 主要透過 convection，受 membrane、free fraction 與 ultrafiltration rate 影響。"}, {"id": "09-self-05", "chapter": 9, "type": "self", "number": 5, "stem": "Which drug would most likely be cleared through a CVVHD circuit?", "context": "", "options": [{"key": "A", "text": "Drug A: 10% protein bound, 140-Da molecular weight (MW), volume of distribution (Vd) 1.2 L/kg.", "sourceKey": "A"}, {"key": "B", "text": "Drug B: 90% protein bound, 1030-Da MW, Vd 0.8 L/kg.", "sourceKey": "B"}, {"key": "C", "text": "Drug C: 40% protein bound, 250-Da MW, Vd 1.5 L/kg.", "sourceKey": "C"}, {"key": "D", "text": "Drug D: 35% protein bound, 480-Da MW, Vd 4.6 L/kg.", "sourceKey": "D"}], "answer": "A", "explanation": "Answer A is correct. Protein binding is a primary determinant of drug clearance during continuous KRT. Only unbound drug can be cleared through the circuit; therefore, an increase in protein binding while other factors remain stable would lead to reduced drug elimination (Answers B and C are incorrect). A high Vd would reduce drug clearance (Answer D is incorrect). The impact of high Vd is more significant in IHD, resulting in less drug removal because there is little time during the 3- to 4-hour IHD run for a drug to redistribute out of the peripheral tissues.", "page": 5, "answerPage": 26, "stemZh": "哪個藥物最可能由 CVVHD circuit 清除？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Drug A：protein binding 10%、MW 140 Da、Vd 1.2 L/kg。"}, {"key": "B", "text": "Drug B：protein binding 90%、MW 1030 Da、Vd 0.8 L/kg。"}, {"key": "C", "text": "Drug C：protein binding 40%、MW 250 Da、Vd 1.5 L/kg。"}, {"key": "D", "text": "Drug D：protein binding 35%、MW 480 Da、Vd 4.6 L/kg。"}], "explanationZh": "低 protein binding、低 MW 且 Vd 相對不高，有利 continuous KRT removal；本題選 A。"}, {"id": "09-case-01", "chapter": 9, "type": "case", "number": 1, "stem": "Which best describes F.B.’s AKI?", "context": "F.B. is a 68-year-old male patient (weight 70 kg) admitted to your ICU with fever, elevated WBC, respiratory failure requiring mechanical ventilation, and norepinephrine to support his blood pressure. His medical history is significant for chronic back pain, diabetes, and hypertension. He takes both enalapril and glipizide once daily, as well as acetaminophen as needed. Before this admission, he had otherwise been healthy. He saw his primary care provider about 1 week ago. At that time, his blood pressure was 140/80 mm Hg, and his hemoglobin A1C was 5.2%. His laboratory workup was also unremarkable: WBC 5.0 x 103 cells/mm3, BUN 7 mg/dL, and SCr 0.9 mg/dL. Today, his WBC is 24 x 103 cells/mm3, BUN is 38 mg/dL, and SCr is 3.2 mg/dL, with 325 mL of UOP since his admission 24 hours ago.", "options": [{"key": "A", "text": "RIFLE class R.", "sourceKey": "A"}, {"key": "B", "text": "AKIN stage 1.", "sourceKey": "B"}, {"key": "C", "text": "RIFLE class F or AKIN stage 3.", "sourceKey": "C"}, {"key": "D", "text": "RIFLE class E or AKIN stage 3.", "sourceKey": "D"}], "answer": "C", "explanation": "Both RIFLE class ÑFÒ and AKIN stage 3 are met using similar SCr and UOP criteria. For this case, the SCr increased by at least 3-fold above baseline, and the patient’s UOP was less than 0.3 mL/kg/hour for 24 hours. Although A and B are true, the worse values in the RIFLE class and AKIN staging systems should be chosen when determining the class and stage of AKI. Answer D is incorrect because his renal indices have not been present for at least 3 months. Collectively, both the RIFLE and the AKIN criteria have been included in the KDIGO criteria, which is the current standard definition.", "page": 16, "answerPage": 25, "stemZh": "F.B. 的 AKI 最符合哪種描述？", "contextZh": "F.B. 為 68 歲男性，weight 70 kg，因 fever、WBC 升高、需 mechanical ventilation 的 respiratory failure 入住 ICU，使用 norepinephrine 支持 BP。病史為 chronic back pain、diabetes、hypertension，每日 enalapril 與 glipizide，PRN acetaminophen。此前健康情形良好，約 1 週前看 primary care provider：BP 140/80 mm Hg、A1C 5.2%、WBC 5.0 x 103 cells/mm3、BUN 7 mg/dL、SCr 0.9 mg/dL。今日 WBC 24 x 103 cells/mm3、BUN 38 mg/dL、SCr 3.2 mg/dL，入院 24 小時 UOP 325 mL。", "optionsZh": [{"key": "A", "text": "RIFLE R。"}, {"key": "B", "text": "AKIN stage 1。"}, {"key": "C", "text": "RIFLE F 或 AKIN stage 3。"}, {"key": "D", "text": "RIFLE E 或 AKIN stage 3。"}], "explanationZh": "SCr 增加 ≥3 倍，UOP <0.3 mL/kg/hour 持續 24 小時，符合 RIFLE F／AKIN stage 3，應選最嚴重符合條件。"}, {"id": "09-case-02", "chapter": 9, "type": "case", "number": 2, "stem": "Which medication is most likely contributing to his AKI?", "context": "F.B. is a 68-year-old male patient (weight 70 kg) admitted to your ICU with fever, elevated WBC, respiratory failure requiring mechanical ventilation, and norepinephrine to support his blood pressure. His medical history is significant for chronic back pain, diabetes, and hypertension. He takes both enalapril and glipizide once daily, as well as acetaminophen as needed. Before this admission, he had otherwise been healthy. He saw his primary care provider about 1 week ago. At that time, his blood pressure was 140/80 mm Hg, and his hemoglobin A1C was 5.2%. His laboratory workup was also unremarkable: WBC 5.0 x 103 cells/mm3, BUN 7 mg/dL, and SCr 0.9 mg/dL. Today, his WBC is 24 x 103 cells/mm3, BUN is 38 mg/dL, and SCr is 3.2 mg/dL, with 325 mL of UOP since his admission 24 hours ago.", "options": [{"key": "A", "text": "Enalapril.", "sourceKey": "A"}, {"key": "B", "text": "Glipizide.", "sourceKey": "B"}, {"key": "C", "text": "Acetaminophen.", "sourceKey": "C"}, {"key": "D", "text": "Both enalaparil and glipizide equally.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient has severe sepsis that led to decreased renal perfusion, causing AKI. Enalapril likely contributed to the injury by altering renal hemodynamics (Answer A is correct). Neither glipizide nor acetaminophen is likely to cause AKI (Answers B–D are incorrect).", "page": 16, "answerPage": 25, "stemZh": "哪個藥物最可能加重 F.B. 的 AKI？", "contextZh": "F.B. 為 68 歲男性，weight 70 kg，因 fever、WBC 升高、需 mechanical ventilation 的 respiratory failure 入住 ICU，使用 norepinephrine 支持 BP。病史為 chronic back pain、diabetes、hypertension，每日 enalapril 與 glipizide，PRN acetaminophen。此前健康情形良好，約 1 週前看 primary care provider：BP 140/80 mm Hg、A1C 5.2%、WBC 5.0 x 103 cells/mm3、BUN 7 mg/dL、SCr 0.9 mg/dL。今日 WBC 24 x 103 cells/mm3、BUN 38 mg/dL、SCr 3.2 mg/dL，入院 24 小時 UOP 325 mL。", "optionsZh": [{"key": "A", "text": "Enalapril。"}, {"key": "B", "text": "Glipizide。"}, {"key": "C", "text": "Acetaminophen。"}, {"key": "D", "text": "Enalapril 與 glipizide 同樣程度。"}], "explanationZh": "Sepsis 降低 renal perfusion；enalapril 改變 renal hemodynamics 可進一步加重 AKI。"}, {"id": "09-case-03", "chapter": 9, "type": "case", "number": 3, "stem": "When evaluating F.B.’s potential causes of AKI, which additional information or test would be most important to consider or obtain?", "context": "F.B. is a 68-year-old male patient (weight 70 kg) admitted to your ICU with fever, elevated WBC, respiratory failure requiring mechanical ventilation, and norepinephrine to support his blood pressure. His medical history is significant for chronic back pain, diabetes, and hypertension. He takes both enalapril and glipizide once daily, as well as acetaminophen as needed. Before this admission, he had otherwise been healthy. He saw his primary care provider about 1 week ago. At that time, his blood pressure was 140/80 mm Hg, and his hemoglobin A1C was 5.2%. His laboratory workup was also unremarkable: WBC 5.0 x 103 cells/mm3, BUN 7 mg/dL, and SCr 0.9 mg/dL. Today, his WBC is 24 x 103 cells/mm3, BUN is 38 mg/dL, and SCr is 3.2 mg/dL, with 325 mL of UOP since his admission 24 hours ago.", "options": [{"key": "A", "text": "Rate of loss, symptoms, and coexisting diseases and medications.", "sourceKey": "A"}, {"key": "B", "text": "Renal evaluation using ultrasonography because this can determine the cause of AKI in most patients.", "sourceKey": "B"}, {"key": "C", "text": "Review of blood chemistries because this will likely determine the cause of injury.", "sourceKey": "C"}, {"key": "D", "text": "Renal evaluation using biopsy.", "sourceKey": "D"}], "answer": "A", "explanation": "Acute kidney injury cannot currently be diagnosed with a specific blood test or imaging study (Answer C is incorrect). The degree of kidney dysfunction and the patient’s symptoms and coexisting diseases may provide clues regarding the etiology of the patient’s kidney injury (Answer A is correct). Drug-induced AKI is most common in the setting of additional insults and may occur even after the drug is discontinued. Given a patient’s history and presentation as well as a patient’s physical examination, a clinician may pursue additional testing to find the DIKD phenotype. Serum markers (e.g., SCr, UOP) are often nonspecific (Answer C is incorrect); kidney biopsy is only warranted for certain DIKD phenotypes (e.g., AIN, glomerular diseases) and is often not pursued in the acute setting (Answer D is incorrect). Renal ultrasonography would be helpful for nephrolithiasis/crystalluria phenotypes or evidence of postrenal AKI not alleviated with urinary catheter placement (Answer B is incorrect).", "page": 16, "answerPage": 25, "stemZh": "評估 F.B. 的 AKI causes，最重要的額外資料或檢查為何？", "contextZh": "F.B. 為 68 歲男性，weight 70 kg，因 fever、WBC 升高、需 mechanical ventilation 的 respiratory failure 入住 ICU，使用 norepinephrine 支持 BP。病史為 chronic back pain、diabetes、hypertension，每日 enalapril 與 glipizide，PRN acetaminophen。此前健康情形良好，約 1 週前看 primary care provider：BP 140/80 mm Hg、A1C 5.2%、WBC 5.0 x 103 cells/mm3、BUN 7 mg/dL、SCr 0.9 mg/dL。今日 WBC 24 x 103 cells/mm3、BUN 38 mg/dL、SCr 3.2 mg/dL，入院 24 小時 UOP 325 mL。", "optionsZh": [{"key": "A", "text": "Function 下降速度、symptoms、coexisting diseases 與 medications。"}, {"key": "B", "text": "Renal ultrasonography，因可找出大多數 AKI 原因。"}, {"key": "C", "text": "Blood chemistries，因通常可直接確認 injury cause。"}, {"key": "D", "text": "Renal biopsy。"}], "explanationZh": "需整合 function 下降速度、症狀、coexisting diseases 與 medications，沒有單一 chemistry 或影像即可確認所有 AKI causes。"}, {"id": "09-case-04", "chapter": 9, "type": "case", "number": 4, "stem": "Which renal replacement mode will most likely be chosen?", "context": "F.B. is a 68-year-old man (weight 70 kg) admitted to your ICU with fever, elevated WBC, respiratory failure requiring mechanical ventilation, and norepinephrine to support his blood pressure. His medical history is significant for chronic back pain, diabetes, and hypertension. He takes both enalapril and glipizide once daily, as well as acetaminophen as needed. Before this admission, he had otherwise been healthy, seeing his primary care provider about 1 week ago. At that time, his blood pressure was 140/80 mm Hg, and his A1C was 5.2%. His laboratory workup was also unremarkable: WBC 5.0 x 103 cells/mm3, BUN 7 mg/dL, and SCr 0.9 mg/dL. Today, his WBC is 24 x 103 cells/mm3, BUN 38 mg/dL, and SCr 3.2 mg/dL, with 325 mL of UOP since his admission 24 hours ago. It is determined that F.B. needs KRT to manage his volume and control his metabolic derangements. He is currently receiving norepinephrine with a mean arterial pressure of 65 mm Hg.", "options": [{"key": "A", "text": "IHD.", "sourceKey": "A"}, {"key": "B", "text": "Slow-low EDD.", "sourceKey": "B"}, {"key": "C", "text": "Continuous KRT.", "sourceKey": "C"}, {"key": "D", "text": "Peritoneal dialysis.", "sourceKey": "D"}], "answer": "C", "explanation": "Intermittent hemodialysis is often used in critically ill patients because many physicians are familiar with this therapy; however, about 20%–30% of patients receiving IHD become hypotensive and require discontinuation or a switch to an alternative therapy. Although prolonged intermittent KRT methods like SLED or EDD are an option, some form of continuous KRT would likely be chosen because of this patient’s unfavorable hemodynamics. Continuous renal replacement therapies such as CVVH, CVVHD, and CVVHDF are often used because they allow for slower flow rates and improved hemodynamics. However, there is no clear benefit with one therapy over another.", "page": 22, "answerPage": 25, "stemZh": "最可能選擇哪個 KRT mode？", "contextZh": "F.B. 為 68 歲男性，weight 70 kg，因 fever、WBC 升高、需 mechanical ventilation 的 respiratory failure 入住 ICU，使用 norepinephrine 支持 BP。病史為 chronic back pain、diabetes、hypertension，每日 enalapril 與 glipizide，PRN acetaminophen。此前健康情形良好，約 1 週前看 primary care provider：BP 140/80 mm Hg、A1C 5.2%、WBC 5.0 x 103 cells/mm3、BUN 7 mg/dL、SCr 0.9 mg/dL。今日 WBC 24 x 103 cells/mm3、BUN 38 mg/dL、SCr 3.2 mg/dL，入院 24 小時 UOP 325 mL。 已判定需 KRT 控制 volume 與 metabolic derangements，目前 norepinephrine 支持下 MAP 65 mm Hg。", "optionsZh": [{"key": "A", "text": "IHD。"}, {"key": "B", "text": "Slow-low EDD。"}, {"key": "C", "text": "Continuous KRT。"}, {"key": "D", "text": "Peritoneal dialysis。"}], "explanationZh": "Hemodynamics 不穩時較可能選 continuous KRT，以較慢流速改善耐受；並非證明某一 mode 對所有 outcomes 優越。"}, {"id": "09-case-05", "chapter": 9, "type": "case", "number": 5, "stem": "F.B. will be initiated on a new extended-spectrum cephalosporin with limited information available for its use during continuous KRT. Given the following parameters, estimate the drug’s SC: MW 480 Da, positively charged drug, Vd 1.9 L/kg, protein binding 12%.", "context": "F.B. is a 68-year-old man (weight 70 kg) admitted to your ICU with fever, elevated WBC, respiratory failure requiring mechanical ventilation, and norepinephrine to support his blood pressure. His medical history is significant for chronic back pain, diabetes, and hypertension. He takes both enalapril and glipizide once daily, as well as acetaminophen as needed. Before this admission, he had otherwise been healthy, seeing his primary care provider about 1 week ago. At that time, his blood pressure was 140/80 mm Hg, and his A1C was 5.2%. His laboratory workup was also unremarkable: WBC 5.0 x 103 cells/mm3, BUN 7 mg/dL, and SCr 0.9 mg/dL. Today, his WBC is 24 x 103 cells/mm3, BUN 38 mg/dL, and SCr 3.2 mg/dL, with 325 mL of UOP since his admission 24 hours ago. It is determined that F.B. needs KRT to manage his volume and control his metabolic derangements. He is currently receiving norepinephrine with a mean arterial pressure of 65 mm Hg.", "options": [{"key": "A", "text": "0", "sourceKey": "A"}, {"key": "B", "text": "0.52", "sourceKey": "B"}, {"key": "C", "text": "1.9", "sourceKey": "C"}, {"key": "D", "text": "0.88", "sourceKey": "D"}], "answer": "D", "explanation": "Protein binding primarily determines drug clearance during KRT. Other factors that contribute to drug clearance include low MW and low Vd. Drug charge leading to dialyzer adhesion has only a limited effect on drug clearance during continuous KRT and has been poorly studied. When available, SC should be identified from the package insert information or the primary literature or calculated from the concentration of the solute in the ultrafiltrate divided by the concentration of the solute in the plasma. When unavailable, SC can be estimated as SC = 1 Č fb. In this case, the SC = 1 – 0.12 = ~0.88 (Answer D is correct; Answers A–C are incorrect).", "page": 22, "answerPage": 25, "stemZh": "F.B. 將使用 continuous KRT 資料有限的新 extended-spectrum cephalosporin。MW 480 Da、帶正電、Vd 1.9 L/kg、protein binding 12%。估算 sieving coefficient（SC）為何？", "contextZh": "F.B. 為 68 歲男性，weight 70 kg，因 fever、WBC 升高、需 mechanical ventilation 的 respiratory failure 入住 ICU，使用 norepinephrine 支持 BP。病史為 chronic back pain、diabetes、hypertension，每日 enalapril 與 glipizide，PRN acetaminophen。此前健康情形良好，約 1 週前看 primary care provider：BP 140/80 mm Hg、A1C 5.2%、WBC 5.0 x 103 cells/mm3、BUN 7 mg/dL、SCr 0.9 mg/dL。今日 WBC 24 x 103 cells/mm3、BUN 38 mg/dL、SCr 3.2 mg/dL，入院 24 小時 UOP 325 mL。 已判定需 KRT 控制 volume 與 metabolic derangements，目前 norepinephrine 支持下 MAP 65 mm Hg。", "optionsZh": [{"key": "A", "text": "0"}, {"key": "B", "text": "0.52"}, {"key": "C", "text": "1.9"}, {"key": "D", "text": "0.88"}], "explanationZh": "缺少實測資料時，SC ≈1−protein-bound fraction＝1−0.12＝0.88。"}, {"id": "09-case-06", "chapter": 9, "type": "case", "number": 6, "stem": "Given the calculated SC, estimate the new cephalosporin’s clearance during continuous KRT if the prescription is CVVH, blood flow 200 mL/minute, ultrafiltration rate 2000 mL/hour, 100% pre-filter replacement fluids, and use of a high-flux, high-efficiency dialyzer.", "context": "F.B. is a 68-year-old man (weight 70 kg) admitted to your ICU with fever, elevated WBC, respiratory failure requiring mechanical ventilation, and norepinephrine to support his blood pressure. His medical history is significant for chronic back pain, diabetes, and hypertension. He takes both enalapril and glipizide once daily, as well as acetaminophen as needed. Before this admission, he had otherwise been healthy, seeing his primary care provider about 1 week ago. At that time, his blood pressure was 140/80 mm Hg, and his A1C was 5.2%. His laboratory workup was also unremarkable: WBC 5.0 x 103 cells/mm3, BUN 7 mg/dL, and SCr 0.9 mg/dL. Today, his WBC is 24 x 103 cells/mm3, BUN 38 mg/dL, and SCr 3.2 mg/dL, with 325 mL of UOP since his admission 24 hours ago. It is determined that F.B. needs KRT to manage his volume and control his metabolic derangements. He is currently receiving norepinephrine with a mean arterial pressure of 65 mm Hg.", "options": [{"key": "A", "text": "0.9 L/hour.", "sourceKey": "A"}, {"key": "B", "text": "1.5 L/hour.", "sourceKey": "B"}, {"key": "C", "text": "3.3 L/hour.", "sourceKey": "C"}, {"key": "D", "text": "5.3 L/hour.", "sourceKey": "D"}], "answer": "B", "explanation": "The general approach to calculating clearance during CVVH multiplies the SC (the degree to which a substance is able to pass through the membrane) by the ultrafiltration rate. If predilution (i.e., before the filter) fluids are used, clearance across the membrane is reduced, which must be accounted for in the formula. Clearance in that case can be estimated using the following equation: CVVHpre-dilution = QUF x SC x [Qb/(Qb + Qrf)] (where QUF is ultrafiltration flow rate (liters per hour), Qb is blood flow rate [converted to liters per hour for consistent units], and Qrf is predilution replacement fluid flow rate, as stated earlier). In this case, clearance = 2 L/hr x 0.88 x [12 L/hr/(12 L/hr + 2 L/hr)] = 1.5 L/hr (Answer B is correct; Answers A, C, and D are incorrect).", "page": 22, "answerPage": 25, "stemZh": "依前題 SC，估算 cephalosporin 的 continuous KRT clearance。處方為 CVVH，blood flow 200 mL/minute、ultrafiltration 2000 mL/hour、replacement fluids 100% pre-filter，使用 high-flux、high-efficiency dialyzer。", "contextZh": "F.B. 為 68 歲男性，weight 70 kg，因 fever、WBC 升高、需 mechanical ventilation 的 respiratory failure 入住 ICU，使用 norepinephrine 支持 BP。病史為 chronic back pain、diabetes、hypertension，每日 enalapril 與 glipizide，PRN acetaminophen。此前健康情形良好，約 1 週前看 primary care provider：BP 140/80 mm Hg、A1C 5.2%、WBC 5.0 x 103 cells/mm3、BUN 7 mg/dL、SCr 0.9 mg/dL。今日 WBC 24 x 103 cells/mm3、BUN 38 mg/dL、SCr 3.2 mg/dL，入院 24 小時 UOP 325 mL。 已判定需 KRT 控制 volume 與 metabolic derangements，目前 norepinephrine 支持下 MAP 65 mm Hg。", "optionsZh": [{"key": "A", "text": "0.9 L/hour."}, {"key": "B", "text": "1.5 L/hour."}, {"key": "C", "text": "3.3 L/hour."}, {"key": "D", "text": "5.3 L/hour."}], "explanationZh": "Predilution 需修正：2 L/hour ×0.88×[12/(12+2)] ≈1.5 L/hour。"}, {"id": "10-self-01", "chapter": 10, "type": "self", "number": 1, "stem": "A 56-year-old woman is hospital day 4 after her acute aneurysmal subarachnoid hemorrhage (SAH). She is oriented and following commands. Laboratory values reveal a serum sodium of 128 mmol/L. Other serum chemistry values include potassium (K) 3.9 mEq/L, chloride 103 mEq/L, bicarbonate 27 mEq/L, blood urea nitrogen (BUN) 10 mg/dL, and serum creatinine (SCr) 1.0 mg/dL. Her urinary output is 1–2 mL/kg/hour, and her fluid balance has been +435 mL during the past 24 hours (currently receiving 0.9% sodium chloride at 125 mL/hour). Which is the best initial therapy for this patient’s hyponatremia?", "context": "", "options": [{"key": "A", "text": "Tolvaptan 20 mg orally daily.", "sourceKey": "A"}, {"key": "B", "text": "1.5% sodium chloride infusion at 125 mL/hour.", "sourceKey": "B"}, {"key": "C", "text": "Water restriction to less than 1.5 L/day.", "sourceKey": "C"}, {"key": "D", "text": "No treatment indicated right now.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct because sodium supplementation is effective for treating hypovolemic and euvolemic hyponatremia. Although inducing hypervolemia is no longer advocated, ensuring euvolemia is important. Answers A and C are incorrect because water restriction or tolvaptan is undesirable in a patient who is 4 days after ictus for SAH because of the importance of maintaining adequate cerebral perfusion. Hyponatremia may be harmful in a patient with a new stroke such as SAH caused by cerebral edema, making Answer D incorrect.", "page": 4, "answerPage": 51, "stemZh": "56 歲女性，acute aneurysmal SAH 後住院第 4 天，oriented 且可依指令動作。Na 128 mmol/L、K 3.9 mEq/L、chloride 103 mEq/L、HCO3 27 mEq/L、BUN 10 mg/dL、SCr 1.0 mg/dL。UOP 1–2 mL/kg/hour，24 小時 fluid balance +435 mL；目前 0.9% sodium chloride 125 mL/hour。Hyponatremia 的最佳初始療法為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Tolvaptan 20 mg 口服，每日 1 次。"}, {"key": "B", "text": "1.5% sodium chloride 125 mL/hour infusion。"}, {"key": "C", "text": "Water restriction 至 <1.5 L/day。"}, {"key": "D", "text": "目前不需 treatment。"}], "explanationZh": "SAH 需維持 cerebral perfusion 與 euvolemia，原題選 sodium supplementation，避免 water restriction 或 tolvaptan 降低 volume。"}, {"id": "10-self-02", "chapter": 10, "type": "self", "number": 2, "stem": "A 27-year-old woman is admitted with an acute ventriculoperitoneal shunt failure and associated infection. She has no significant medical history and no allergies to medications. A lumbar puncture reveals cerebrospinal fluid (CSF) white blood cell count (WBC) 34 × 103 cells/mm3, red blood cell count (RBC) 1 × 103 cells/mm3, protein 78 mg/dL, and glucose 21 mg/dL. The cultures grow methicillin-resistant Staphylococcus epidermidis (MRSE). Her shunt is externalized. Despite 4 days of intravenous vancomycin (most recent vancomycin trough was 17.7 mcg/mL), the CSF continues to grow MRSE. Which is the most appropriate intraventricular antimicrobial regimen to initiate for this patient’s refractory ventriculitis?", "context": "", "options": [{"key": "A", "text": "Give vancomycin 10 mg intraventricularly daily.", "sourceKey": "A"}, {"key": "B", "text": "Give gentamicin 5 mg intraventricularly daily.", "sourceKey": "B"}, {"key": "C", "text": "Give ampicillin 50 mg intraventricularly daily.", "sourceKey": "C"}, {"key": "D", "text": "No antimicrobials should be given intraventricularly for this patient.", "sourceKey": "D"}], "answer": "A", "explanation": "Answer A is correct because vancomycin effectively covers MRSE, and the intraventricular dose of 10 mg daily is appropriate. Answer B is incorrect because gentamicin is less likely to be effective alone for MRSE and is more associated with seizures than other aminoglycosides. Answer C is incorrect because ampicillin (or other penicillins) should not be given by the intraventricular route, given the risk of seizures. Answer D is incorrect because this patient has a treatment-refractory, devicerelated CNS infection. In this instance, intraventricular antimicrobials may be considered.", "page": 4, "answerPage": 51, "stemZh": "27 歲女性因 acute ventriculoperitoneal shunt failure 與感染入院，無重要病史或 drug allergy。CSF WBC 34 × 103 cells/mm3、RBC 1 × 103 cells/mm3、protein 78 mg/dL、glucose 21 mg/dL，culture 為 MRSE。Shunt 已 externalize；IV vancomycin 4 天後（最新 trough 17.7 mcg/mL），CSF 仍有 MRSE。Refractory ventriculitis 最適合開始哪個 intraventricular regimen？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Vancomycin 10 mg intraventricular，每日 1 次。"}, {"key": "B", "text": "Gentamicin 5 mg intraventricular，每日 1 次。"}, {"key": "C", "text": "Ampicillin 50 mg intraventricular，每日 1 次。"}, {"key": "D", "text": "此病人不應使用任何 intraventricular antimicrobials。"}], "explanationZh": "Refractory device-related CNS infection 可考慮 intraventricular vancomycin，原題 dose 為 10 mg daily。"}, {"id": "10-self-03", "chapter": 10, "type": "self", "number": 3, "stem": "A 25-year-old man is admitted after a two-story fall from a ladder. The initial computed tomography (CT) scan of his brain reveals a large right temporal subdural hematoma, an overlying skull fracture, and a left temporal contusion. His post-resuscitation Glasgow Coma Scale (GCS) score is E1-M4-V1T. An intracranial pressure (ICP) monitor is placed with an opening pressure of 32 mm Hg and a cerebral perfusion pressure (CPP) of 53 mm Hg. Serum laboratory values include sodium (Na) 141 mEq/L, K 3.6 mEq/L, BUN 8 mg/dL, SCr 1.1 mg/dL, glucose 178 mg/dL, WBC 14.8 × 103 cells/mm3, pH 7.46, and partial pressure of carbon dioxide (Pco2 ) 34 mm Hg. Which supportive care issue is most relevant to the appropriate treatment of a patient with a severe traumatic brain injury (TBI)?", "context": "", "options": [{"key": "A", "text": "Avoid enteral nutrition for the first 5–7 days because of the lack of gastrointestinal (GI) tolerance in severe TBI.", "sourceKey": "A"}, {"key": "B", "text": "Maintain CPP at 60–70 mm Hg to optimize perfusion and reduce complications.", "sourceKey": "B"}, {"key": "C", "text": "Provide dextrose 5% or other dextrose-containing intravenous fluids to compensate for the patient’s increased metabolic needs.", "sourceKey": "C"}, {"key": "D", "text": "Initiate high-dose methylprednisolone therapy within 8 hours of injury to reduce cerebral edema.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct; although the optimal CPP varies with each individual, the typical recommended target range is 60–70 mm Hg. Patients with a TBI have gastric intolerance but benefit greatly from early enteral nutrition, making Answer A incorrect. Answer C is incorrect because dextrose-containing fluids may increase cerebral edema in TBI and lower the serum sodium concentration. Answer D is incorrect because high-dose methylprednisolone therapy increases mortality in patients with a TBI.", "page": 5, "answerPage": 51, "stemZh": "25 歲男性從梯子墜落約兩層樓高度。初始 CT：大型 right temporal subdural hematoma、其上 skull fracture、left temporal contusion。Resuscitation 後 GCS E1-M4-V1T。ICP monitor opening pressure 32 mm Hg、CPP 53 mm Hg。Na 141 mEq/L、K 3.6 mEq/L、BUN 8 mg/dL、SCr 1.1 mg/dL、glucose 178 mg/dL、WBC 14.8 × 103 cells/mm3、pH 7.46、PCO2 34 mm Hg。Severe TBI 支持照護中哪項最相關且適當？", "contextZh": "", "optionsZh": [{"key": "A", "text": "因 GI intolerance，前 5–7 天避免 enteral nutrition。"}, {"key": "B", "text": "維持 CPP 60–70 mm Hg，優化 perfusion 並降低 complications。"}, {"key": "C", "text": "給 5% dextrose 或其他含 dextrose IV fluids 補償 metabolic needs 增加。"}, {"key": "D", "text": "傷後 8 小時內開始 high-dose methylprednisolone 降低 cerebral edema。"}], "explanationZh": "原題 CPP target 60–70 mm Hg 可平衡 perfusion 與 complications；high-dose methylprednisolone 不適用 TBI。"}, {"id": "10-self-04", "chapter": 10, "type": "self", "number": 4, "stem": "A 69-year-old woman presents to the emergency department with a 30-minute history of difficulty with word finding and left upper-extremity weakness. Her NIH Stroke Scale score is 13. A head CT scan reveals no acute abnormalities. The patient’s home medications include lisinopril, carvedilol, warfarin, and atorvastatin. Her medical history includes hypertension, atrial fibrillation, and transient ischemic attacks (diagnosed 6 months ago). Serum laboratory values include Na 145 mEq/L, K 4.0 mEq/L, BUN 18 mg/dL, SCr 1.2 mg/dL, glucose 132 mg/dL, WBC 8.7 × 103 cells/mm3, hematocrit (Hct) 38.9%, platelet count (Plt) 355,000/mm3, and international normalized ratio (INR) 1.5. Her vital signs include blood pressure 167/98 mm Hg, heart rate 132 beats/minute, oxygen saturation (Sao2 ) 98%, and respiratory rate 14 breaths/minute. Which is the most appropriate next step in this patient’s care?", "context": "", "options": [{"key": "A", "text": "Initiate aspirin 324 mg orally × 1.", "sourceKey": "A"}, {"key": "B", "text": "Initiate alteplase 0.9 mg/kg intravenously (10% bolus dose, 90% infusion up to 90 mg maximum).", "sourceKey": "B"}, {"key": "C", "text": "Initiate nicardipine to reduce blood pressure to systolic blood pressure (SBP) less than 140 mm Hg, followed by alteplase 0.9 mg/kg intravenously (10% bolus dose, 90% infusion up to 90 mg maximum).", "sourceKey": "C"}, {"key": "D", "text": "Initiate vitamin K 10 mg intravenously × 1.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct because this patient meets the criteria for receiving alteplase and has no obvious contraindications. The more timely the alteplase administration, the more likely the patient will benefit (and the less risk). Answer A is incorrect because aspirin should be initiated within the first 24–48 hours after stroke, but not necessarily immediately. Answer C is incorrect because the blood pressure may be slightly elevated (SBP less than 185 mm Hg, DBP less than 110 mm Hg) before alteplase administration or immediately after stroke in general (so-called permissive hypertension to ensure adequate cerebral perfusion). Nicardipine is not necessary for this patient at this point. Answer D is incorrect because reversal of warfarin with vitamin K is not recommended for an acute thrombosis in the brain.", "page": 5, "answerPage": 51, "stemZh": "69 歲女性因 word-finding difficulty 與 left upper-extremity weakness 持續 30 分鐘至 ED。NIHSS 13，CT 無 acute abnormality。Home medications：lisinopril、carvedilol、warfarin、atorvastatin；病史 hypertension、AF、6 個月前 TIA。Na 145 mEq/L、K 4.0 mEq/L、BUN 18 mg/dL、SCr 1.2 mg/dL、glucose 132 mg/dL、WBC 8.7 × 103 cells/mm3、Hct 38.9%、Plt 355,000/mm3、INR 1.5。BP 167/98 mm Hg、HR 132 beats/minute、SaO2 98%、RR 14 breaths/minute。下一步最適合何者？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Aspirin 324 mg 口服 ×1。"}, {"key": "B", "text": "Alteplase 0.9 mg/kg IV（10% bolus、90% infusion，總量最高 90 mg）。"}, {"key": "C", "text": "先 nicardipine 將 SBP 降至 <140 mm Hg，再 alteplase 0.9 mg/kg IV（10% bolus、90% infusion，總量最高 90 mg）。"}, {"key": "D", "text": "Vitamin K 10 mg IV ×1。"}], "explanationZh": "本題符合 alteplase criteria，無明顯 contraindications；目前 BP 低於 pre-thrombolysis threshold，不需先降至 <140。"}, {"id": "10-self-05", "chapter": 10, "type": "self", "number": 5, "stem": "An 18-year-old man is admitted to the intensive care unit (ICU) after falling from a tree. Initial trauma screening reveals a C3–C4 fracture and dislocation with an incomplete spinal cord injury (SCI) at the corresponding levels (he has some sensory function bilaterally). The fracture has been reduced, and he arrives in the ICU 6 hours after injury. Which is the most appropriate statement related to initiating high-dose methylprednisolone therapy for this patient’s SCI?", "context": "", "options": [{"key": "A", "text": "May be used because he has an incomplete injury with some sensory function.", "sourceKey": "A"}, {"key": "B", "text": "Should be used because it will augment spinal perfusion.", "sourceKey": "B"}, {"key": "C", "text": "Should not be used because of the potential for adverse effects and questionable benefit.", "sourceKey": "C"}, {"key": "D", "text": "Should not be used because the patient is outside the treatment window.", "sourceKey": "D"}], "answer": "C", "explanation": "Answer C is correct; the current guidelines do not recommend high-dose methylprednisolone therapy because of the inconsistency in beneficial effects and the relatively consistent risk of adverse effects (GI bleeding, infection) shown in clinical trials. Answer B is incorrect because high-dose methylprednisolone does not augment spinal perfusion. Answers A and D are incorrect; although the NASCIS-III study showed some potential benefit for patients who received a bolus and a 47-hour infusion when high-dose methylprednisolone therapy was initiated 3–8 hours after injury, particularly for incomplete injuries, the therapy is no longer recommended.", "page": 5, "answerPage": 51, "stemZh": "18 歲男性從樹上墜落後入住 ICU，trauma assessment 發現 C3–C4 fracture/dislocation，及相對應 incomplete SCI，雙側仍有部分 sensory function。Fracture 已 reduced，傷後 6 小時抵 ICU。關於 high-dose methylprednisolone，哪項敘述最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "可用，因 incomplete injury 仍有部分 sensory function。"}, {"key": "B", "text": "應用，因可增加 spinal perfusion。"}, {"key": "C", "text": "不應用，因 potential adverse effects 與 benefit 存疑。"}, {"key": "D", "text": "不應用，因已超過 treatment window。"}], "explanationZh": "依原教材，benefit 不一致且 GI bleeding、infection risk 明確，不建議例行使用；並非因已超過其舊研究時間窗。"}, {"id": "10-self-06", "chapter": 10, "type": "self", "number": 6, "stem": "A 27-year-old woman presents with fever, agitation, hypertension, and muscle rigidity. Her drugs-ofabuse screen is negative, and serotonin syndrome is a possible diagnosis. Which home medication is most likely a causative agent for serotonin syndrome?", "context": "", "options": [{"key": "A", "text": "Buspirone.", "sourceKey": "A"}, {"key": "B", "text": "Levetiracetam.", "sourceKey": "B"}, {"key": "C", "text": "Cyproheptadine.", "sourceKey": "C"}, {"key": "D", "text": "Bupropion.", "sourceKey": "D"}], "answer": "A", "explanation": "Answer A is correct; of the agents listed, buspirone is the only one that increases CNS serotonin concentrations. Answers B–D would not be expected to increase CNS serotonin concentrations. Cyproheptadine is a potential therapeutic agent for patients with serotonin syndrome.", "page": 5, "answerPage": 51, "stemZh": "27 歲女性有 fever、agitation、hypertension 與 muscle rigidity，drug-of-abuse screen 陰性，可能為 serotonin syndrome。哪個 home medication 最可能致病？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Buspirone."}, {"key": "B", "text": "Levetiracetam."}, {"key": "C", "text": "Cyproheptadine."}, {"key": "D", "text": "Bupropion."}], "explanationZh": "選項中 buspirone 有 serotonergic effect；cyproheptadine 反而可作 treatment。"}, {"id": "10-self-07", "chapter": 10, "type": "self", "number": 7, "stem": "A 58-year-old woman with a Hunt and Hess grade 4 SAH resides in your ICU. She is day 6 after her SAH. Her current medications include 0.9% normal saline at 100 mL/hour, nimodipine 60 mg by feeding tube every 4 hours, norepinephrine 0.05 mcg/kg/minute (5 mcg/minute), famotidine 20 mg intravenously every 12 hours, docusate 250 mg by tube every 12 hours, and morphine as needed for headache. Current laboratory values include Na 144 mEq/L, K 4.1 mEq/L, SCr 0.6 mg/dL, serum osmolality 322 mOsm/L, and Hct 32.3%. Her blood pressure is 167/99 mm Hg, heart rate 133 beats/minute, respiratory rate 18 breaths/minute, Sao2 99%, and central venous pressure 5 mm Hg. Her most recent transcranial Doppler velocities are mean middle cerebral artery 125/135 (right/left), with a corresponding Lindegaard ratio of 3.5/3.7 (right/left). Her ICP is currently 24 mm Hg. She has a Licox monitor placed in the hemisphere ipsilateral to her aneurysm, which currently reveals a partial pressure of brain tissue oxygen of 14%. She is intubated and on the ventilator. Her GCS score has decreased from 10 to 8 during the past hour. Which treatment would be most appropriate for this patient in the ICU?", "context": "", "options": [{"key": "A", "text": "Verapamil 2.5 mg intra-arterially × 1.", "sourceKey": "A"}, {"key": "B", "text": "3% sodium chloride 2.5 mL/kg intravenously × 1.", "sourceKey": "B"}, {"key": "C", "text": "20% mannitol 0.25 g/kg intravenously × 1.", "sourceKey": "C"}, {"key": "D", "text": "1 unit of packed RBCs.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct; given this patient’s change in neurologic status, vital signs, and monitoring values, she is likely having a cerebral vasospasm with increased ICP. Therapy should be targeted at optimizing cerebral perfusion (fluid bolus or increase in MAP) and reducing ICP. Hypertonic saline will address both issues, causing an increase in intravascular volume to improve perfusion and possibly an increase in blood pressure while lowering ICP through osmotic effects. Answer A is incorrect because verapamil must be given superselectively in the angiography suite. One possible adverse effect of verapamil is cerebral vasodilation, which could lead to increased ICP, and ICP would be undesirable in this patient right now. Answer C is incorrect; although mannitol may decrease ICP, it also causes diuresis, which is undesirable in a patient with ongoing cerebral vasospasm. Answer D is incorrect; although a blood transfusion might theoretically increase oxygen-carrying capacity to the brain (enhancing perfusion), a blood transfusion may in fact cause a risk of cerebral vasospasm. In addition, it is unlikely to affect ICP.", "page": 5, "answerPage": 51, "stemZh": "58 歲女性，Hunt and Hess grade 4 SAH 後第 6 天，ICU 藥物為 0.9% normal saline 100 mL/hour、nimodipine 60 mg feeding tube 每 4 小時、norepinephrine 0.05 mcg/kg/minute（5 mcg/minute）、famotidine 20 mg IV 每 12 小時、docusate 250 mg tube 每 12 小時、PRN morphine 處理 headache。Na 144 mEq/L、K 4.1 mEq/L、SCr 0.6 mg/dL、serum osmolality 322 mOsm/L、Hct 32.3%。BP 167/99 mm Hg、HR 133 beats/minute、RR 18 breaths/minute、SaO2 99%、CVP 5 mm Hg。TCD mean MCA velocities 125/135（右／左）、Lindegaard ratio 3.5/3.7（右／左）。ICP 24 mm Hg；aneurysm 同側 hemisphere 的 Licox monitor 顯示 brain tissue oxygen partial pressure 為 14%（原文單位）。已插管及 ventilated；過去 1 小時 GCS 從 10 降至 8。最適合哪個 ICU treatment？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Verapamil 2.5 mg intra-arterial ×1。"}, {"key": "B", "text": "3% sodium chloride 2.5 mL/kg IV ×1。"}, {"key": "C", "text": "20% mannitol 0.25 g/kg IV ×1。"}, {"key": "D", "text": "Packed RBCs 1 unit。"}], "explanationZh": "疑似 vasospasm 合併 ICP 增高，hypertonic saline 可提高 intravascular volume/perfusion 並藉 osmotic effect 降低 ICP，避免 mannitol diuresis。"}, {"id": "10-self-08", "chapter": 10, "type": "self", "number": 8, "stem": "Which sedative in an intubated patient is most desirable for a patient with a diagnosis of SAH currently having vasospasm?", "context": "", "options": [{"key": "A", "text": "Lorazepam 1 mg/hour.", "sourceKey": "A"}, {"key": "B", "text": "Midazolam 4 mg/hour.", "sourceKey": "B"}, {"key": "C", "text": "Morphine 2 mg/hour.", "sourceKey": "C"}, {"key": "D", "text": "Propofol 25 mcg/kg/minute.", "sourceKey": "D"}], "answer": "D", "explanation": "Answer D is correct because propofol is an almostideal agent for sedation with its quick onset and offset of activity and relative lack of dependence on organ function for clearance; however, boluses and large dose titrations should be avoided because of the risk of hypotension. Answers A and C are incorrect; long-acting sedating agents such as lorazepam and morphine are undesirable in patients with a neurologic injury because of their propensity to obscure the neurologic examination for prolonged periods. Answer B is incorrect; midazolam (and other benzodiazepines) is associated with increased delirium. In addition, midazolam may accumulate when used for a prolonged period because of its long context-sensitive half-life.", "page": 6, "answerPage": 52, "stemZh": "SAH 且目前有 vasospasm 的 intubated patient，哪個 sedative 最適合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Lorazepam 1 mg/hour."}, {"key": "B", "text": "Midazolam 4 mg/hour."}, {"key": "C", "text": "Morphine 2 mg/hour."}, {"key": "D", "text": "Propofol 25 mcg/kg/minute."}], "explanationZh": "Propofol onset/offset 快，有利 neurological assessment；避免 bolus 或大幅 titration 導致 hypotension。"}, {"id": "10-case-01", "chapter": 10, "type": "case", "number": 1, "stem": "A 37-year-old man (weight 75 kg) is admitted to the emergency department with meningitis. On admission, his GCS score decreases from E3-M6-V1T to E1-M5-V1T over 10 minutes, and his nurse notices facial twitching. An EEG is ordered. Current medications include famotidine 20 mg intravenously every 12 hours, heparin 5000 units subcutaneously every 8 hours, docusate 100 mg nasogastrically twice daily, and a supplemental vitamin infusion for potential alcohol withdrawal. Which is the best acute therapy for this patient’s suspected seizure activity?", "context": "", "options": [{"key": "A", "text": "Fosphenytoin 1500 mg PE intravenously × 1.", "sourceKey": "A"}, {"key": "B", "text": "Valproic acid 1500 mg intravenously × 1.", "sourceKey": "B"}, {"key": "C", "text": "Midazolam 10 mg intramuscularly × 1.", "sourceKey": "C"}, {"key": "D", "text": "Levetiracetam 1 g intravenously × 1.", "sourceKey": "D"}], "answer": "C", "explanation": "Answer C is correct because midazolam (together with lorazepam) is recommended by the status epilepticus guidelines. Answers A, B, and D are incorrect because phenytoin is less effective than lorazepam as the initial agent. Although valproic acid and levetiracetam have not been formally compared with lorazepam as the initial agent for status epilepticus, their use is supported by less clinically rigorous evidence.", "page": 16, "answerPage": 50, "stemZh": "37 歲男性，weight 75 kg，因 meningitis 入 ED。入院後 10 分鐘 GCS 從 E3-M6-V1T 降至 E1-M5-V1T，護理師見 facial twitching，已安排 EEG。目前 famotidine 20 mg IV 每 12 小時、heparin 5000 units SC 每 8 小時、docusate 100 mg NG 每日 2 次及 vitamin infusion 處理 potential alcohol withdrawal。疑似 seizures 的最佳 acute therapy 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Fosphenytoin 1500 mg PE 靜脈給藥 × 1."}, {"key": "B", "text": "Valproic acid 1500 mg 靜脈給藥 × 1."}, {"key": "C", "text": "Midazolam 10 mg 肌肉注射 × 1."}, {"key": "D", "text": "Levetiracetam 1 g 靜脈給藥 × 1."}], "explanationZh": "Initial status epilepticus therapy 優先 benzodiazepine；本題選 IM midazolam。"}, {"id": "10-case-02", "chapter": 10, "type": "case", "number": 2, "stem": "A 25-year-old man (weight 80 kg) is admitted after a two-story fall from a ladder. The initial CT scan of his brain reveals a large right temporal subdural hematoma, an overlying skull fracture, and a left temporal contusion. His post-resuscitation GCS is E1-M4-V1T. An ICP monitor is placed with an opening pressure of 32 mm Hg, and CPP is 53 mm Hg. Serum laboratory values include Na 139 mEq/L, K 3.6 mEq/L, BUN 42 mg/dL, SCr 2.4 mg/dL, glucose 178 mg/dL, WBC 14.8 × 103 cells/mm3, pH 7.46, and Pco2 34 mm Hg. Which is the best initial therapy for this patient’s elevated ICP?", "context": "", "options": [{"key": "A", "text": "Mannitol 20% 1 g/kg intravenously × 1.", "sourceKey": "A"}, {"key": "B", "text": "23.4% sodium chloride 30 mL intravenously × 1.", "sourceKey": "B"}, {"key": "C", "text": "Pentobarbital 10 mg/kg intravenously × 1.", "sourceKey": "C"}, {"key": "D", "text": "Midazolam 10 mg intravenously × 1.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct because clinical evidence supports the safety and efficacy of osmotherapy as a first-line therapy in this situation. Hypertonic saline would be more appropriate than mannitol because of the patient’s relatively low serum sodium concentration and elevated SCr (mannitol is cleared renally and is thus not optimal for patients with renal dysfunction, making Answer A incorrect). Answers C and D (pentobarbital and midazolam) are not ideal for this patient because of the likelihood of hypotension.", "page": 21, "answerPage": 50, "stemZh": "25 歲男性，weight 80 kg，從梯子墜落約兩層樓高度。CT：large right temporal subdural hematoma、overlying skull fracture、left temporal contusion。Resuscitation 後 GCS E1-M4-V1T。ICP opening pressure 32 mm Hg、CPP 53 mm Hg。Na 139 mEq/L、K 3.6 mEq/L、BUN 42 mg/dL、SCr 2.4 mg/dL、glucose 178 mg/dL、WBC 14.8 × 103 cells/mm3、pH 7.46、PCO2 34 mm Hg。ICP 增高的最佳 initial therapy 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Mannitol 20% 1 g/kg 靜脈給藥 × 1."}, {"key": "B", "text": "23.4% sodium chloride 30 mL 靜脈給藥 × 1."}, {"key": "C", "text": "Pentobarbital 10 mg/kg 靜脈給藥 × 1."}, {"key": "D", "text": "Midazolam 10 mg 靜脈給藥 × 1."}], "explanationZh": "Osmotherapy 合適，renal dysfunction 下本題偏向 hypertonic saline 而非 renally cleared mannitol；其他 sedatives 有 hypotension 風險。"}, {"id": "10-case-03", "chapter": 10, "type": "case", "number": 3, "stem": "Which is the most appropriate initial therapy in addition to vitamin K for this patient’s care?", "context": "A 61-year-old man is admitted with acute onset of difficulty speaking, confusion, and right-sided weakness. His NIH Stroke Scale score is 20. A head CT scan reveals a right parietal intracerebral hemorrhage (ICH). The patient’s home medications include hydroxychloroquine, ibuprofen as needed, warfarin, amlodipine, and donepezil. His medical history includes a deep venous thrombosis (1 year ago), hypertension, early dementia, and arthritis. Serum laboratory values include Na 140 mEq/L, K 3.6 mEq/L, BUN 27 mg/dL, SCr 1.8 mg/dL, glucose 289 mg/dL, Hct 36.7%, Plt 245,000/mm3, and INR 6.8. His vital signs include blood pressure 163/101 mm Hg, heart rate 99 beats/minute, Sao2 97%, and respiratory rate 20 breaths/minute.", "options": [{"key": "A", "text": "Reinitiate amlodipine.", "sourceKey": "A"}, {"key": "B", "text": "Give 4-factor prothrombin complex concentrate (4F-PCC) 50 units/kg intravenously × 1.", "sourceKey": "B"}, {"key": "C", "text": "Give 6-pack infusion of platelets.", "sourceKey": "C"}, {"key": "D", "text": "Give recombinant factor VIIa (rFVIIa) 90 mcg/kg intravenously × 1.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct because warfarin is well reversed by 4F-PCC products in a much more timely and complete manner than vitamin K in the acute setting. Answer A is incorrect; although blood pressure control is important for this patient, amlodipine is unlikely to have timely effects immediately after ICH. Answer C is incorrect because platelets are minimally effective for reversing ibuprofen. Answer D is incorrect; rFVIIa is not recommended for reversal of warfarin because of thrombosis risks.", "page": 30, "answerPage": 50, "stemZh": "除 vitamin K 外，此病人最適合的 initial therapy 為何？", "contextZh": "61 歲男性，acute difficulty speaking、confusion、right-sided weakness 入院，NIHSS 20。Head CT 顯示 right parietal ICH。Home medications：hydroxychloroquine、PRN ibuprofen、warfarin、amlodipine、donepezil。病史 DVT（1 年前）、hypertension、early dementia、arthritis。Na 140 mEq/L、K 3.6 mEq/L、BUN 27 mg/dL、SCr 1.8 mg/dL、glucose 289 mg/dL、Hct 36.7%、Plt 245,000/mm3、INR 6.8。BP 163/101 mm Hg、HR 99 beats/minute、SaO2 97%、RR 20 breaths/minute。", "optionsZh": [{"key": "A", "text": "重新開始 amlodipine。"}, {"key": "B", "text": "4F-PCC 50 units/kg IV ×1。"}, {"key": "C", "text": "Platelets 6-pack infusion。"}, {"key": "D", "text": "rFVIIa 90 mcg/kg IV ×1。"}], "explanationZh": "4F-PCC 可比單用 vitamin K 更迅速且完整地 reverse warfarin；本題選 50 units/kg。"}, {"id": "10-case-04", "chapter": 10, "type": "case", "number": 4, "stem": "For this 61-year-old patient with ICH, which is the most appropriate initial antihypertensive therapy?", "context": "A 61-year-old man is admitted with acute onset of difficulty speaking, confusion, and right-sided weakness. His NIH Stroke Scale score is 20. A head CT scan reveals a right parietal intracerebral hemorrhage (ICH). The patient’s home medications include hydroxychloroquine, ibuprofen as needed, warfarin, amlodipine, and donepezil. His medical history includes a deep venous thrombosis (1 year ago), hypertension, early dementia, and arthritis. Serum laboratory values include Na 140 mEq/L, K 3.6 mEq/L, BUN 27 mg/dL, SCr 1.8 mg/dL, glucose 289 mg/dL, Hct 36.7%, Plt 245,000/mm3, and INR 6.8. His vital signs include blood pressure 163/101 mm Hg, heart rate 99 beats/minute, Sao2 97%, and respiratory rate 20 breaths/minute.", "options": [{"key": "A", "text": "Clevidipine 1-mg/hour infusion to keep SBP 180 - 220 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "Nicardipine 5-mg/hour infusion to keep SBP 140 - 150 mm Hg.", "sourceKey": "B"}, {"key": "C", "text": "Labetalol 10 mg intravenously as needed to keep SBP 160 - 200 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "Esmolol 50-mcg/kg/minute infusion to keep SBP 120 - 130 mm Hg.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct because nicardipine is recommended for reducing blood pressure after ICH, and the threshold for treatment is correct according to the INTERACT-2 and ATACH-2 studies. Answer A is incorrect; although clevidipine may be considered in this case, the typical goal blood pressure target after ICH is a SBP 140-150 mm Hg. Answers C and D are incorrect; although labetalol and esmolol also reduce blood pressure, the optimal SBP goal after ICH 140-150 mm Hg.", "page": 30, "answerPage": 50, "stemZh": "此 61 歲 ICH 病人最適合的初始 antihypertensive therapy 為何？", "contextZh": "61 歲男性，acute difficulty speaking、confusion、right-sided weakness 入院，NIHSS 20。Head CT 顯示 right parietal ICH。Home medications：hydroxychloroquine、PRN ibuprofen、warfarin、amlodipine、donepezil。病史 DVT（1 年前）、hypertension、early dementia、arthritis。Na 140 mEq/L、K 3.6 mEq/L、BUN 27 mg/dL、SCr 1.8 mg/dL、glucose 289 mg/dL、Hct 36.7%、Plt 245,000/mm3、INR 6.8。BP 163/101 mm Hg、HR 99 beats/minute、SaO2 97%、RR 20 breaths/minute。", "optionsZh": [{"key": "A", "text": "Clevidipine 1 mg/hour infusion，維持 SBP 180–220 mm Hg。"}, {"key": "B", "text": "Nicardipine 5 mg/hour infusion，維持 SBP 140–150 mm Hg。"}, {"key": "C", "text": "Labetalol 10 mg IV PRN，維持 SBP 160–200 mm Hg。"}, {"key": "D", "text": "Esmolol 50 mcg/kg/minute infusion，維持 SBP 120–130 mm Hg。"}], "explanationZh": "原題以 nicardipine 及 SBP 140–150 mm Hg 為最佳組合；其他選項的 target 不符合原題設定。"}, {"id": "10-case-05", "chapter": 10, "type": "case", "number": 5, "stem": "Which therapy is most appropriate to prevent ischemic complications from SAH?", "context": "A 49-year-old woman presents to an urgent treatment center with the “worst headache of her life.” She is sent to your emergency department, where a head CT scan reveals a diffuse SAH. The patient takes no home medications and has an insignificant medical history other than a 20 pack-year history of smoking.", "options": [{"key": "A", "text": "Nimodipine for 21 days.", "sourceKey": "A"}, {"key": "B", "text": "Euvolemia and permissive hypertension for 14 days.", "sourceKey": "B"}, {"key": "C", "text": "Simvastatin for 14 days.", "sourceKey": "C"}, {"key": "D", "text": "Aminocaproic acid infusion for 48 hours.", "sourceKey": "D"}], "answer": "A", "explanation": "Answer A is correct because nimodipine is the only agent with an FDA indication for preventing ischemic complications related to SAH. Answer B is incorrect because prophylactic Triple-H therapy or variants thereof do not prevent ischemic complications; rather, hyperperfusion therapies are used when vasospasm develops. Answer C is incorrect because in clinical trials, the efficacy of statins for preventing vasospasm has failed. Answer D is incorrect because aminocaproic acid may in fact increase the risk of stroke in patients with SAH.", "page": 35, "answerPage": 50, "stemZh": "哪個療法最適合預防 SAH 的 ischemic complications？", "contextZh": "49 歲女性因「一生最嚴重的 headache」至 urgent treatment center，轉至 ED 後 head CT 見 diffuse SAH。無 home medications，除 20 pack-year smoking 外無重要病史。", "optionsZh": [{"key": "A", "text": "Nimodipine，21 天。"}, {"key": "B", "text": "Euvolemia 與 permissive hypertension，14 天。"}, {"key": "C", "text": "Simvastatin，14 天。"}, {"key": "D", "text": "Aminocaproic acid infusion，48 小時。"}], "explanationZh": "原題 nimodipine 用 21 天可降低 SAH-related ischemic complications；不以 prophylactic hypervolemia/Triple-H 預防。"}, {"id": "10-case-06", "chapter": 10, "type": "case", "number": 6, "stem": "On hospital day 5, the patient has reduced alertness, and her GCS score decreases by 2 points. The digital subtraction angiography suggests cerebral vasospasm. Which treatment modality is best to initiate first?", "context": "A 49-year-old woman presents to an urgent treatment center with the “worst headache of her life.” She is sent to your emergency department, where a head CT scan reveals a diffuse SAH. The patient takes no home medications and has an insignificant medical history other than a 20 pack-year history of smoking.", "options": [{"key": "A", "text": "Norepinephrine 0.05 mcg/kg/minute to increase MAP to 90 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "One unit of packed RBCs to increase Hgb to 10 g/dL.", "sourceKey": "B"}, {"key": "C", "text": "3% sodium chloride boluses to increase central venous pressure to 14 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "Milrinone 0.375-mcg/kg/minute infusion to increase cardiac index to 5 L/minute/m2.", "sourceKey": "D"}], "answer": "A", "explanation": "Answer A is correct because induction of hypertension with a vasopressor such as norepinephrine appears to improve cerebral perfusion. Titrating the infusion to MAP values that result in improved neurologic symptoms is often necessary. Answer B is incorrect because data analyses are limited to support transfusing blood to a high hemoglobin (in fact, blood transfusion appears to be a risk factor for vasospasm). In addition, fluid resuscitation to hypervolemic levels is not beneficial. Answer C is incorrect because when hypervolemia is compared with euvolemia, neurologic outcomes are no different, but patients receiving hypervolemia develop more pulmonary edema. Answer D is incorrect because milrinone is not first-line therapy for vasospasm.", "page": 35, "answerPage": 50, "stemZh": "住院第 5 天 alertness 下降，GCS 減少 2 分；digital subtraction angiography 提示 cerebral vasospasm。最適合先開始哪個 treatment？", "contextZh": "49 歲女性因「一生最嚴重的 headache」至 urgent treatment center，轉至 ED 後 head CT 見 diffuse SAH。無 home medications，除 20 pack-year smoking 外無重要病史。", "optionsZh": [{"key": "A", "text": "Norepinephrine 0.05 mcg/kg/minute，將 MAP 增至 90 mm Hg。"}, {"key": "B", "text": "Packed RBCs 1 unit，將 Hgb 增至 10 g/dL。"}, {"key": "C", "text": "3% sodium chloride boluses，將 CVP 增至 14 mm Hg。"}, {"key": "D", "text": "Milrinone 0.375 mcg/kg/minute infusion，將 cardiac index 增至 5 L/minute/m2。"}], "explanationZh": "Symptomatic vasospasm 可先以 norepinephrine induced hypertension 改善 cerebral perfusion，依 neurological response titrate。"}, {"id": "10-case-07", "chapter": 10, "type": "case", "number": 7, "stem": "Which laboratory test would best evaluate the extent of anticoagulation from rivaroxaban?", "context": "A 52-year-old woman is admitted to your ICU after a single-vehicle crash. She has many orthopedic injuries to her lower extremities and a subdural hematoma, which will require an emergency craniotomy for evacuation. Her home medications include metoprolol, rivaroxaban 10 mg (last dose 5 hours ago), lisinopril, and atorvastatin. Her medical history is significant for atrial fibrillation. Laboratory values on admission were notable for Hct 31.2% and Plt 577,000/mm3.", "options": [{"key": "A", "text": "INR.", "sourceKey": "A"}, {"key": "B", "text": "Anti-Xa activity concentration.", "sourceKey": "B"}, {"key": "C", "text": "Activated partial thromboplastin time.", "sourceKey": "C"}, {"key": "D", "text": "VerifyNow PRU test measurement.", "sourceKey": "D"}], "answer": "B", "explanation": "Answer B is correct because the anti-Xa activity concentration is the laboratory value that best correlates with rivaroxaban activity. Answers A and C are incorrect because neither INR nor activated partial thromboplastin time is typically affected by rivaroxaban alone. Answer D is incorrect because the VerifyNow PRU test measurement is more specific to antiplatelet agents such as aspirin or clopidogrel.", "page": 36, "answerPage": 50, "stemZh": "哪個 laboratory test 最適合評估 rivaroxaban 的 anticoagulant effect？", "contextZh": "52 歲女性，single-vehicle crash 後入住 ICU，有多處 lower-extremity orthopedic injuries 與 subdural hematoma，需 emergency craniotomy evacuation。Home medications：metoprolol、rivaroxaban 10 mg（最後一劑 5 小時前）、lisinopril、atorvastatin；病史 AF。入院 Hct 31.2%、Plt 577,000/mm3。", "optionsZh": [{"key": "A", "text": "INR。"}, {"key": "B", "text": "Anti-Xa activity concentration。"}, {"key": "C", "text": "aPTT。"}, {"key": "D", "text": "VerifyNow PRU measurement。"}], "explanationZh": "Anti-Xa activity 與 rivaroxaban activity 較相關；INR、aPTT 或 platelet-function tests 不能可靠量化本題 effect。"}, {"id": "10-case-08", "chapter": 10, "type": "case", "number": 8, "stem": "Which therapy would be most appropriate to reverse rivaroxaban before this patient’s emergency craniotomy?", "context": "A 52-year-old woman is admitted to your ICU after a single-vehicle crash. She has many orthopedic injuries to her lower extremities and a subdural hematoma, which will require an emergency craniotomy for evacuation. Her home medications include metoprolol, rivaroxaban 10 mg (last dose 5 hours ago), lisinopril, and atorvastatin. Her medical history is significant for atrial fibrillation. Laboratory values on admission were notable for Hct 31.2% and Plt 577,000/mm3.", "options": [{"key": "A", "text": "4F-PCC 50 units/kg intravenously × 1.", "sourceKey": "A"}, {"key": "B", "text": "Andexanet 200 mg intravenously x 1.", "sourceKey": "B"}, {"key": "C", "text": "Fresh frozen plasma 15 mL/kg intravenously × 1.", "sourceKey": "C"}, {"key": "D", "text": "rFVIIa 90 mcg/kg intravenously × 1.", "sourceKey": "D"}], "answer": "A", "explanation": "Answer A is correct because the most consistent reversal effects, although with low-quality evidence, occur with 4F-PCCs. Answer B is incorrect because the appropriate bolus dose of andexanet would be 400 mg followed by a 2-hour continuous infusion, given the dose and time of the last dose. In addition, available data are currently limited regarding the periprocedural use of andexanet. Answer C is incorrect because fresh frozen plasma does not reverse factor Xa inhibitors reliably. Answer D is incorrect; although factor VII may have some usefulness, reversal is incomplete, and factor VII is associated with an increased risk of thrombosis.", "page": 36, "answerPage": 50, "stemZh": "Emergency craniotomy 前，哪個療法最適合 reverse rivaroxaban？", "contextZh": "52 歲女性，single-vehicle crash 後入住 ICU，有多處 lower-extremity orthopedic injuries 與 subdural hematoma，需 emergency craniotomy evacuation。Home medications：metoprolol、rivaroxaban 10 mg（最後一劑 5 小時前）、lisinopril、atorvastatin；病史 AF。入院 Hct 31.2%、Plt 577,000/mm3。", "optionsZh": [{"key": "A", "text": "4F-PCC 50 units/kg 靜脈給藥 × 1."}, {"key": "B", "text": "Andexanet 200 mg 靜脈給藥 x 1."}, {"key": "C", "text": "Fresh frozen plasma 15 mL/kg 靜脈給藥 × 1."}, {"key": "D", "text": "rFVIIa 90 mcg/kg 靜脈給藥 × 1."}], "explanationZh": "依原題選 4F-PCC 50 units/kg；andexanet 200 mg 不符原題 dose，FFP 不能可靠 reverse Xa inhibitors。"}, {"id": "11-self-01", "chapter": 11, "type": "self", "number": 1, "stem": "Which is the most likely cause of this patient’s admission and transfer?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Septic shock caused by suspected pneumonia with subsequent myocardial depression and demand ischemia.", "sourceKey": "A"}, {"key": "B", "text": "Cardiogenic shock caused by acute on chronic decompensated systolic heart failure (HF).", "sourceKey": "B"}, {"key": "C", "text": "Cardiogenic shock caused by a suspected inferior ST-segment elevation myocardial infarction (STEMI).", "sourceKey": "C"}, {"key": "D", "text": "Cardiogenic shock caused by a suspected non– ST-segment elevation myocardial infarction (NSTEMI) affecting the lateral wall.", "sourceKey": "D"}], "answer": "C", "explanation": "A diagnosis of cardiogenic shock is most likely, given the patient’s history, presentation, ongoing vasopressor requirement, elevated BNP, and lack of infectious symptoms (Answer A is incorrect). Furthermore, this patient has positive troponins and ST-segment elevation in leads II, III, and aVF (inferior leads), making STEMI the primary diagnosis and reason for cardiogenic shock (Answer C is correct; Answer D is incorrect). The presence of hypotension and bradycardia are more likely consistent with complications of an inferior MI with possible RV involvement, as opposed to an acute exacerbation of HF. The patient also has a preserved LVEF and not systolic HF (Answer B is incorrect).", "page": 5, "answerPage": 61, "stemZh": "這位病人最可能因何原因住院並轉院？", "optionsZh": [{"key": "A", "text": "疑似pneumonia造成septic shock，伴隨心肌抑制與demand ischemia"}, {"key": "B", "text": "慢性systolic HF急性惡化造成cardiogenic shock"}, {"key": "C", "text": "疑似inferior STEMI造成cardiogenic shock"}, {"key": "D", "text": "疑似lateral wall NSTEMI造成cardiogenic shock"}], "explanationZh": "胸痛、II／III／aVF ST elevation與低血壓符合inferior STEMI併cardiogenic shock。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-02", "chapter": 11, "type": "self", "number": 2, "stem": "Given this patient’s presentation, which coronary artery is most likely to be the culprit lesion?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Left main coronary artery.", "sourceKey": "A"}, {"key": "B", "text": "Left anterior descending artery.", "sourceKey": "B"}, {"key": "C", "text": "Left circumflex coronary artery.", "sourceKey": "C"}, {"key": "D", "text": "Right coronary artery.", "sourceKey": "D"}], "answer": "D", "explanation": "ST-segment elevation in leads II, III, and aVF (inferior) are most consistent with the right coronary artery (Answer D is correct). Answers A (left main coronary artery), B (left anterior descending artery), and C (left circumflex coronary artery) are incorrect.", "page": 5, "answerPage": 61, "stemZh": "依病人表現，哪條coronary artery最可能是culprit lesion？", "optionsZh": [{"key": "A", "text": "Left main coronary artery"}, {"key": "B", "text": "Left anterior descending artery"}, {"key": "C", "text": "Left circumflex coronary artery"}, {"key": "D", "text": "Right coronary artery"}], "explanationZh": "Inferior STEMI伴bradycardia與疑似right ventricular involvement，最支持Right coronary artery。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-03", "chapter": 11, "type": "self", "number": 3, "stem": "The interventional cardiologist who is evaluating the patient for potential revascularization asks the ICU team to place a central venous catheter. Which changes/interventions regarding this patient’s hemodynamic support would be best to recommend?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Increase dopamine to achieve a mean arterial pressure (MAP) greater than 65 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "Convert the patient to norepinephrine, and titrate the dose to achieve a MAP greater than 65 mm Hg while weaning off dopamine.", "sourceKey": "B"}, {"key": "C", "text": "Initiate milrinone at 0.375 mcg/kg/minute, and continue dopamine at 15 mcg/kg/minute.", "sourceKey": "C"}, {"key": "D", "text": "Administer 1000 mL of normal saline as a bolus because of low urine output.", "sourceKey": "D"}], "answer": "B", "explanation": "According to the SOAP II investigation, dopamine is associated with increased rates of adverse events in patients with cardiogenic shock compared with norepinephrine (Answer B is correct; Answer A is incorrect). Milrinone (Answer C), although helpful in some patients with HF, would not be favored, given the patient’s current hypotension and acute renal failure. Normal saline administration (Answer D) would likely be detrimental because of the patient’s signs of fluid overload, including BNP elevation, hyponatremia, and rales on examination.", "page": 5, "answerPage": 61, "stemZh": "Interventional cardiologist評估revascularization並要求置放central venous catheter。何種hemodynamic support調整最適當？", "optionsZh": [{"key": "A", "text": "增加dopamine，使MAP>65 mm Hg"}, {"key": "B", "text": "轉用norepinephrine並調整至MAP>65 mm Hg，同時減停dopamine"}, {"key": "C", "text": "開始milrinone 0.375 mcg/kg/min並維持dopamine 15 mcg/kg/min"}, {"key": "D", "text": "因尿量低給予normal saline 1000 mL bolus"}], "explanationZh": "Norepinephrine較適合維持血壓，dopamine增加arrhythmia風險。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-04", "chapter": 11, "type": "self", "number": 4, "stem": "The patient has been taken to the cardiac catheterization laboratory, and a “code blue” is called overhead for immediate emergency response to this patient’s procedural area. On arrival, chest compressions have just been paused for defibrillation, and a single dose of epinephrine has been administered. The interventional team indicates that, when attempting visualization of the right coronary artery, the patient went into ventricular tachycardia (VT). The patient’s telemetry monitor now shows sinus tachycardia with noted ectopy—heart rate 113 beats/minute and blood pressure 84/52 mm Hg. The cardiologist asks for recommendations for an antiarrhythmic because he is concerned about a VT recurrence, given the bigeminy on telemetry. Which agent would be best to recommend?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Lidocaine 100 mg intravenous push for 2–3 minutes, followed by an infusion at 1 mg/ minute.", "sourceKey": "A"}, {"key": "B", "text": "Amiodarone 300 mg intravenous push for less than 1 minute.", "sourceKey": "B"}, {"key": "C", "text": "Metoprolol 10 mg intravenous push for 1–2 minutes.", "sourceKey": "C"}, {"key": "D", "text": "Diltiazem 20 mg intravenous push for 2 minutes, followed by a continuous infusion at 5 mg/hour and titrated to maintain a heart rate less than 110 beats/minute.", "sourceKey": "D"}], "answer": "A", "explanation": "Lidocaine would be most favorable in patients with ischemia-mediated ventricular arrhythmias, and although the patient is not currently in VT, he is having persistent premature ventricular contractions (bigeminy), further increasing concern for ongoing ischemia and myocardial irritability (Answer A is correct). Metoprolol (Answer C) and diltiazem (Answer D) would be contraindicated because of ongoing cardiogenic shock and vasopressor requirements. Amiodarone 300 mg intravenous push (Answer B) is no longer appropriate because the patient has a pulse and blood pressure and is currently not in VT. Furthermore, rapid administration of amiodarone may lead to worsening hypotension.", "page": 5, "answerPage": 61, "stemZh": "病人在right coronary artery檢查時發生VT，接受defibrillation及epinephrine後恢復sinus tachycardia。HR113、BP84/52 mm Hg且有bigeminy；為預防VT再發，何藥最適當？", "optionsZh": [{"key": "A", "text": "Lidocaine 100 mg IV push，歷時2–3分鐘，再以1 mg/min輸注"}, {"key": "B", "text": "Amiodarone 300 mg IV push，少於1分鐘"}, {"key": "C", "text": "Metoprolol 10 mg IV push，歷時1–2分鐘"}, {"key": "D", "text": "Diltiazem 20 mg IV push，歷時2分鐘，再以5 mg/hour輸注並調整至HR<110"}], "explanationZh": "已有pulse但仍低血壓，選項中的lidocaine方案較適當；300 mg快速amiodarone屬cardiac arrest給法。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-05", "chapter": 11, "type": "self", "number": 5, "stem": "The patient returns to the ICU after his left heart catheterization, which was performed through the femoral artery. In addition to his acute decompensation, which major procedural complication is of greatest concern during the next 12 hours?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Bleeding (particularly retroperitoneal bleeding).", "sourceKey": "A"}, {"key": "B", "text": "Dissection/rupture.", "sourceKey": "B"}, {"key": "C", "text": "Stent thrombosis.", "sourceKey": "C"}, {"key": "D", "text": "Papillary muscle rupture.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient’s heart catheterization was performed through the femoral artery, a vessel that is much more difficult to compress to facilitate hemostasis. Hematomas can occur at the access site; however, the most serious bleeding complication associated with this access site is a retroperitoneal bleed (Answer A is correct). Answer B (dissection/rupture), Answer C (stent thrombosis), and Answer D (papillary muscle rupture) are incorrect.", "page": 5, "answerPage": 61, "stemZh": "病人接受femoral artery途徑left heart catheterization後返回ICU；未來12小時最需注意哪項procedural complication？", "optionsZh": [{"key": "A", "text": "出血，尤其retroperitoneal bleeding"}, {"key": "B", "text": "Dissection／rupture"}, {"key": "C", "text": "Stent thrombosis"}, {"key": "D", "text": "Papillary muscle rupture"}], "explanationZh": "Femoral access後應特別監測retroperitoneal bleeding。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-06", "chapter": 11, "type": "self", "number": 6, "stem": "The patient returns to the ICU with a pulmonary artery catheter in place and is currently receiving dopamine at 12 mcg/kg/minute and norepinephrine at 0.08 mcg/kg/minute with heart rate 108 beats/ minute, blood pressure 82/51 mm Hg, cardiac index 2.0, central venous pressure (CVP) 26 mm Hg, and pulmonary artery pressure 49/21 mm Hg. The physician is concerned about right ventricular dysfunction in the setting of shock and approaches you for a recommendation to increase blood pressure (BP). Ideally, the physician would prefer to wean dopamine and minimize further increases in pulmonary vascular resistance (PVR) because of the presence of pulmonary hypertension. Which strategy would be best to recommend?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Keep the current infusions, and reevaluate later.", "sourceKey": "A"}, {"key": "B", "text": "Initiate phenylephrine at 1 mcg/kg/minute, and wean the dopamine off if MAP is greater than 65 mm Hg.", "sourceKey": "B"}, {"key": "C", "text": "Initiate vasopressin at 0.04 unit/minute, and wean the dopamine off if MAP is greater than 65 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "Administer a 1-L bolus of normal saline, and wean the dopamine off if MAP is greater than 65 mm Hg.", "sourceKey": "D"}], "answer": "C", "explanation": "Vasopressin would be favored because, when administered at normal physiologic doses, it mediates predominant increases in SVR while minimally affecting the PVR (Answer C is correct). Phenylephrine (Answer B), however, will increase both PVR and SVR by the α 1 -receptors. Given the patient’s ongoing hypotension, low cardiac index, and rising CVP, inaction (Answer A) would be inappropriate, and additional volume administration (Answer D) would be detrimental in the setting of volume overload and RV failure.", "page": 6, "answerPage": 61, "stemZh": "目前dopamine12 mcg/kg/min、norepinephrine0.08 mcg/kg/min；HR108、BP82/51、CI2.0、CVP26、PAP49/21。疑似right ventricular dysfunction且有pulmonary hypertension，希望減停dopamine並避免PVR再上升，何策略最好？", "optionsZh": [{"key": "A", "text": "維持目前輸注，稍後再評估"}, {"key": "B", "text": "加phenylephrine1 mcg/kg/min，MAP>65時減停dopamine"}, {"key": "C", "text": "加vasopressin0.04 unit/min，MAP>65時減停dopamine"}, {"key": "D", "text": "給normal saline1 L bolus，MAP>65時減停dopamine"}], "explanationZh": "Vasopressin可提升systemic BP，對PVR影響較小；已有高CVP，不宜任意大量補液。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-07", "chapter": 11, "type": "self", "number": 7, "stem": "Hours later, this patient goes into atrial fibrillation (AF) with a heart rate of 126 beats/minute; however, the patient’s blood pressure remains 86/56 mm Hg according to the regimen selected in the previous question. Which agent would you most likely administer to manage the patient’s AF?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Amiodarone 150 mg intravenous push, followed by a continuous infusion at 1 mg/minute.", "sourceKey": "A"}, {"key": "B", "text": "Amiodarone 150 mg intravenous infusion for 10 minutes, followed by a continuous infusion at 1 mg/minute.", "sourceKey": "B"}, {"key": "C", "text": "Metoprolol 5 mg intravenous push once, followed by 5 mg intravenous push every 6 hours.", "sourceKey": "C"}, {"key": "D", "text": "Diltiazem 20 mg intravenous push, followed by a continuous infusion at 5 mg/hour and titrated to maintain a heart rate of less than 110 beats/ minute.", "sourceKey": "D"}], "answer": "B", "explanation": "Amiodarone boluses would be safest if administered slowly for 10 minutes to avoid additional hypotension, followed by a continuous infusion (Answer B is correct; Answer A is incorrect). Metoprolol (Answer C) and diltiazem (Answer D) would be contraindicated because of ongoing cardiogenic shock and vasopressor requirements.", "page": 6, "answerPage": 61, "stemZh": "數小時後發生AF，HR126、BP86/56 mm Hg。依前題治療後，最適合用何藥處理AF？", "optionsZh": [{"key": "A", "text": "Amiodarone150 mg IV push，再1 mg/min輸注"}, {"key": "B", "text": "Amiodarone150 mg於10分鐘內IV infusion，再1 mg/min輸注"}, {"key": "C", "text": "Metoprolol5 mg IV push一次，再每6小時5 mg"}, {"key": "D", "text": "Diltiazem20 mg IV push，再5 mg/hour輸注，調整至HR<110"}], "explanationZh": "有pulse時amiodarone150 mg應於10分鐘輸注；快速push可能加重低血壓。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-self-08", "chapter": 11, "type": "self", "number": 8, "stem": "Which medication-related quality metric would not require documentation of contraindications based on this patient’s clinical presentation (acute MI with preserved LVEF)?", "context": "A 58-year-old man (height 71 inches, weight 106 kg) was transferred to the intensive care unit (ICU) from an outlying hospital after 24 hours of progressively worsening chest pain and shortness of breath. He arrives on 6 L of oxygen by high-flow nasal cannula, with a heparin infusion at 16 units/kg/hour and dopamine infusion at 15 mcg/kg/minute. Notes show that he was bradycardic (heart rate of 50–58 beats/minute) and hypotensive (78/49–86/55 mm Hg) on presentation to the outlying hospital. His 12-lead electrocardiogram (ECG) at the outlying hospital showed ST-segment elevation in leads II, III, and aVF. Given his chest pain and ECG findings, aspirin 324 mg (chewed and swallowed), clopidogrel 600 mg, and morphine 4 mg intravenously once were administered before transfer. Notes also show that β-blockers and nitroglycerin were held because of bradycardia and hypotension. His past medical history is significant for nonadherence, hypertension, diabetes, dyslipidemia, and heart failure with preserved ejection fraction (HFpEF), with a last-reported left ventricular ejection fraction (LVEF) of 65% 1 year ago. The patient reports that he currently takes no medications at home. • Vital signs on transfer: blood pressure 87/52 mm Hg, heart rate 110 beats/minute, respiratory rate 19 breaths/minute, temperature 99.7°F (37.6°C) • The team’s physical assessment indicates ongoing distress, radiating chest pain 7/10, evidence of rales, absence of any cardiac murmurs, and presence of a right radial arterial line. • A preexisting urinary catheter with 20 mL of urine in the reservoir is also present (the patient reports that his most recent void was yesterday morning). According to outlying hospital records, only 30 mL of urine was reported before time of transfer. • His chest radiography reveals evidence of diffuse patchy opacities; however, the report indicates that an infiltrate cannot be ruled out. • His serum chemistry panel results are as follows: sodium 132 mEq/L, potassium 4.2 mEq/L, chloride 102 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 34 mg/dL, serum creatinine (SCr) 1.9 mg/dL, and glucose 163 mg/dL. • Results of the complete blood cell count (CBC) are as follows: white blood cell count (WBC) 11.3 × 103 cells/mm3, hemoglobin 10.9 g/dL, hematocrit 31.1%, and platelet count 213,000/mm3. • Additional laboratory values include troponin-T 3.9 ng/mL, aspartate aminotransferase (AST) 14 IU/L, alanine aminotransferase (ALT) 46 IU/L, hemoglobin A1C (A1C) 8.3%, and brain natriuretic peptide (BNP) of 1423 pg/mL.", "options": [{"key": "A", "text": "Aspirin contraindication.", "sourceKey": "A"}, {"key": "B", "text": "Statin contraindication.", "sourceKey": "B"}, {"key": "C", "text": "β-Blocker contraindication.", "sourceKey": "C"}, {"key": "D", "text": "Angiotensin-converting enzyme (ACE) inhibitor/angiotensin receptor blocker (ARB) contraindication.", "sourceKey": "D"}], "answer": "D", "explanation": "Because of the diagnosis of acute MI, current quality measures would require initiation of or documentation to contraindications for each item except for ACE inhibitors/ARBs (Answer D) because the patient still has an LVEF greater than 40%. Answer A (aspirin contraindication), Answer B (statin contraindication), and C (β-blocker contraindication) are incorrect.", "page": 6, "answerPage": 61, "stemZh": "Acute MI且LVEF保留的病人，哪項用藥品質指標不要求記錄contraindication？", "optionsZh": [{"key": "A", "text": "Aspirin contraindication"}, {"key": "B", "text": "Statin contraindication"}, {"key": "C", "text": "β-blocker contraindication"}, {"key": "D", "text": "ACE inhibitor／ARB contraindication"}], "explanationZh": "依本章品質指標，LVEF>40%時不須因未用ACE inhibitor／ARB而記錄contraindication。", "contextZh": "58歲男性，106 kg，24小時持續胸痛與dyspnea，ECG為II、III、aVF ST elevation。先前HR50–58、BP78/49–86/55，轉院後BP87/52、HR110、RR19、37.6°C。用heparin16 units/kg/hour、dopamine15 mcg/kg/min，曾給aspirin324 mg、clopidogrel600 mg與morphine4 mg。因bradycardia及hypotension未給β-blocker／nitroglycerin。病史hypertension、diabetes、dyslipidemia、HFpEF（去年LVEF65%），目前未規律用藥。肺部rales、尿量極少，胸片diffuse patchy opacities。Na132、K4.2、Cl102、CO2 22、BUN34、SCr1.9、glucose163；WBC11.3×10³、Hgb10.9、Plt213000；troponin-T3.9、AST14、ALT46、A1C8.3%、BNP1423。"}, {"id": "11-case-01", "chapter": 11, "type": "case", "number": 1, "stem": "Given J.M.’s comorbidities, some drugs or drug classes have proven mortality benefits. Which medications could be added or modified to the patient’s home medication profile to further slow disease progression and improve mortality?", "context": "J.M. is a 68-year-old man with a history of CAD including STEMI 6 months ago with placement of two drugeluting stents, type 2 diabetes, hypertension, dyslipidemia, gastroesophageal reflux disease, obstructive sleep apnea, frequent epistaxis, ischemic cardiomyopathy (LVEF 30%–35%), and moderate to severe mitral regurgitation. He is admitted to the cardiac intensive care unit for severe shortness of breath and altered mental status, and he is currently on continuous positive airway pressure (CPAP). He has gained 13 kg during the past 2 weeks (now weighs 121 kg) and has had decreased urine output, despite having had his diuretic dose increased. Home medications include the following: aspirin 81 mg once daily, ticagrelor 90 mg every 12 hours, pantoprazole 40 mg once daily, atorvastatin 40 mg once daily, insulin glargine 10 units every night, metformin 500 mg every 12 hours, furosemide 40 mg twice daily, and potassium chloride 20 mEq twice daily. His wife states that he was taking clopidogrel until 1 month ago, at which time he was given ticagrelor samples from his primary care physician because of cost concerns. A physical examination reveals rales throughout his lung fields. He is afebrile, anxious, and alert.", "options": [{"key": "A", "text": "Amlodipine, clopidogrel, and sitagliptin", "sourceKey": "A"}, {"key": "B", "text": "Spironolactone, lisinopril, and carvedilol", "sourceKey": "B"}, {"key": "C", "text": "Pravastatin, amlodipine, and aspirin", "sourceKey": "C"}, {"key": "D", "text": "Prasugrel, sildenafil, and atenolol", "sourceKey": "D"}], "answer": "B", "explanation": "Given this patient’s CAD, type 2 diabetes, dyslipidemia, gastroesophageal reflux disease, hypertension, obstructive sleep apnea, and ischemic cardiomyopathy, only Answer B consists of the three agents that reduce morbidity and mortality among these comorbidities: carvedilol (HF and potentially diabetes), spironolactone (HF progression post-MI), and lisinopril (HF and diabetes), making Answer B correct and Answers A (Amlodipine, clopidogrel, and sitagliptin.), C (Pravastatin, amlodipine, and aspirin 325 mg), and D (Prasugrel, sildenafil, and atenolol) incorrect.", "page": 16, "answerPage": 59, "stemZh": "依J.M.的comorbidities，何組藥物可加入或調整居家用藥，以延緩疾病進展並改善mortality？", "optionsZh": [{"key": "A", "text": "Amlodipine、clopidogrel、sitagliptin"}, {"key": "B", "text": "Spironolactone、lisinopril、carvedilol"}, {"key": "C", "text": "Pravastatin、amlodipine、aspirin"}, {"key": "D", "text": "Prasugrel、sildenafil、atenolol"}], "explanationZh": "HFrEF的ACE inhibitor、適當β-blocker及mineralocorticoid receptor antagonist具有mortality效益。", "contextZh": "J.M.，68歲男性，6個月前STEMI並放置兩個drug-eluting stents，合併type2 diabetes、hypertension、dyslipidemia、GERD、OSA、反覆epistaxis、ischemic cardiomyopathy（LVEF30–35%）及moderate–severe mitral regurgitation。因嚴重dyspnea與mental status改變入住cardiac ICU，使用CPAP。兩週體重增加13 kg至121 kg，利尿劑增加後仍尿量下降。居家藥物aspirin81 mg daily、ticagrelor90 mg每12小時、pantoprazole40 mg daily、atorvastatin40 mg daily、insulin glargine10 units nightly、metformin500 mg每12小時、furosemide40 mg BID、potassium chloride20 mEq BID。因費用1個月前clopidogrel換成ticagrelor samples；肺部廣泛rales，無發燒、焦慮但清醒。"}, {"id": "11-case-02", "chapter": 11, "type": "case", "number": 2, "stem": "Given the patient’s presentation, which group of diagnostic tests would be most helpful to guide your recommendations to the team for J.M.’s current management? (Assume that a basic metabolic panel [Chem 7], a pulse oximetry, and a capillary blood glucose have already been completed.)", "context": "J.M. is a 68-year-old man with a history of CAD including STEMI 6 months ago with placement of two drugeluting stents, type 2 diabetes, hypertension, dyslipidemia, gastroesophageal reflux disease, obstructive sleep apnea, frequent epistaxis, ischemic cardiomyopathy (LVEF 30%–35%), and moderate to severe mitral regurgitation. He is admitted to the cardiac intensive care unit for severe shortness of breath and altered mental status, and he is currently on continuous positive airway pressure (CPAP). He has gained 13 kg during the past 2 weeks (now weighs 121 kg) and has had decreased urine output, despite having had his diuretic dose increased. Home medications include the following: aspirin 81 mg once daily, ticagrelor 90 mg every 12 hours, pantoprazole 40 mg once daily, atorvastatin 40 mg once daily, insulin glargine 10 units every night, metformin 500 mg every 12 hours, furosemide 40 mg twice daily, and potassium chloride 20 mEq twice daily. His wife states that he was taking clopidogrel until 1 month ago, at which time he was given ticagrelor samples from his primary care physician because of cost concerns. A physical examination reveals rales throughout his lung fields. He is afebrile, anxious, and alert.", "options": [{"key": "A", "text": "Urine culture, respiratory culture, lactate, and procalcitonin", "sourceKey": "A"}, {"key": "B", "text": "Chest radiography, arterial blood gas (ABG), liver function tests, and serial troponins", "sourceKey": "B"}, {"key": "C", "text": "Chest radiography, echocardiogram (ECHO), lactate, and BNP", "sourceKey": "C"}, {"key": "D", "text": "Chest radiography, arterial line, ABG, and lactate", "sourceKey": "D"}], "answer": "C", "explanation": "Although many of these tests might be helpful in this patient’s differential diagnosis, the most likely consideration would be respiratory decompensation or an HF decompensation, given the patient’s presentation; thus, a chest radiograph, ECHO, BNP, and lactate would be most appropriate, making Answer C correct. Answer A is incorrect; although an infectious etiology cannot be ruled out, it is less likely than noninfectious cardiorespiratory differentials. Answer B is not the best answer; although serial troponins and an ABG could be argued for, liver function tests are unlikely to provide additional insight into this patient’s differential. Answer D also is not the best answer; although it provides additional information for hemodynamic assessment, it is lacking in an assessment of cardiac function, which is a likely contributor to the patient’s presentation.", "page": 16, "answerPage": 59, "stemZh": "已完成Chem7、pulse oximetry及capillary glucose；哪組檢查最有助於J.M.目前的治療決策？", "optionsZh": [{"key": "A", "text": "Urine culture、respiratory culture、lactate、procalcitonin"}, {"key": "B", "text": "Chest radiography、ABG、liver function tests、serial troponins"}, {"key": "C", "text": "Chest radiography、ECHO、lactate、BNP"}, {"key": "D", "text": "Chest radiography、arterial line、ABG、lactate"}], "explanationZh": "Chest radiography與ECHO評估HF及structural disease，lactate與BNP協助評估灌流與HF。", "contextZh": "J.M.，68歲男性，6個月前STEMI並放置兩個drug-eluting stents，合併type2 diabetes、hypertension、dyslipidemia、GERD、OSA、反覆epistaxis、ischemic cardiomyopathy（LVEF30–35%）及moderate–severe mitral regurgitation。因嚴重dyspnea與mental status改變入住cardiac ICU，使用CPAP。兩週體重增加13 kg至121 kg，利尿劑增加後仍尿量下降。居家藥物aspirin81 mg daily、ticagrelor90 mg每12小時、pantoprazole40 mg daily、atorvastatin40 mg daily、insulin glargine10 units nightly、metformin500 mg每12小時、furosemide40 mg BID、potassium chloride20 mEq BID。因費用1個月前clopidogrel換成ticagrelor samples；肺部廣泛rales，無發燒、焦慮但清醒。"}, {"id": "11-case-03", "chapter": 11, "type": "case", "number": 3, "stem": "All tests previously mentioned have been ordered, and the following results are available. J.M.’s blood pressure is 90/56 mm Hg (MAP 67 mm Hg), and his heart rate is 56 beats/minute. A 12-lead ECG showed normal sinus rhythm without evidence of acute ST-T changes. • Chest radiography reveals diffuse patchy opacities; however, infiltrate cannot be ruled out; lines are all in appropriate positions. • Serum chemistry panel results are as follows: sodium 126 mEq/L, potassium 4.8 mEq/L, chloride 102 mEq/L, carbon dioxide 21 mEq/L, BUN 32 mg/dL, SCr 1.6 mg/dL, and glucose 134 mg/dL. • Results of the CBC are as follows: WBC 9.8 × 103 cells/mm3, hemoglobin 11.1 g/dL, hematocrit 32.6%, and platelet count 173,000/mm3. • Additional laboratory values include the following: troponin 0.9 ng/mL, AST 114 IU/L, ALT 102 IU/L, and BNP 1936 pg/mL. • Invasive hemodynamic variables include CVP 28 mm Hg, pulmonary artery pressures 46/22 mm Hg, cardiac index 1.8 L/minute/m2, and central venous oxygen saturation (Scvo2 ) 53%; pulmonary artery occlusion pressure is not yet available. • ABG results are as follows: pH 7.36, partial pressure of oxygen (Po2 ) 93.7, partial pressure of carbon dioxide (Pco2 ) 43.2, bicarbonate 23.9, oxygen (O 2 ) saturation 89%, and lactate 6.9. • ECHO results are pending. The patient’s physical examination reveals that his extremities are cold to the touch, and his capillary refill is poor. The team has ordered furosemide 80 mg intravenously once and would like to initiate a vasopressor or inotrope for this patient. Which would be best to recommend at this time?", "context": "J.M. is a 68-year-old man with a history of CAD including STEMI 6 months ago with placement of two drugeluting stents, type 2 diabetes, hypertension, dyslipidemia, gastroesophageal reflux disease, obstructive sleep apnea, frequent epistaxis, ischemic cardiomyopathy (LVEF 30%–35%), and moderate to severe mitral regurgitation. He is admitted to the cardiac intensive care unit for severe shortness of breath and altered mental status, and he is currently on continuous positive airway pressure (CPAP). He has gained 13 kg during the past 2 weeks (now weighs 121 kg) and has had decreased urine output, despite having had his diuretic dose increased. Home medications include the following: aspirin 81 mg once daily, ticagrelor 90 mg every 12 hours, pantoprazole 40 mg once daily, atorvastatin 40 mg once daily, insulin glargine 10 units every night, metformin 500 mg every 12 hours, furosemide 40 mg twice daily, and potassium chloride 20 mEq twice daily. His wife states that he was taking clopidogrel until 1 month ago, at which time he was given ticagrelor samples from his primary care physician because of cost concerns. A physical examination reveals rales throughout his lung fields. He is afebrile, anxious, and alert.", "options": [{"key": "A", "text": "Norepinephrine 0.08 mcg/kg/minute", "sourceKey": "A"}, {"key": "B", "text": "Epinephrine 0.08 mcg/kg/minute", "sourceKey": "B"}, {"key": "C", "text": "Milrinone 0.75 mcg/kg/minute", "sourceKey": "C"}, {"key": "D", "text": "Dobutamine 5 mcg/kg/minute", "sourceKey": "D"}], "answer": "D", "explanation": "Dobutamine would be the ideal choice, given the patient’s acutely worsening cardiac index and malperfusion and its rapid onset; this would facilitate β 2 arterial vasodilation (both SVR and PVR reduction) as well as increase chronotropy and inotropy. Milrinone, although likely beneficial for both cardiac index and PVR reduction, would be less favorable, given that its time to peak effect will exceed 6 hours (the time required to achieve greater than 87.5% of steady state, even in normal renal function), and the dosing is rather high for safe initiation of therapy. Neither norepinephrine nor epinephrine would be favored (particularly at these doses) because the patient’s MAP is currently elevated, and these agents would contribute to increased α 1 -mediated afterload increases, causing increased myocardial workload in a patient who already has decompensated systolic HF. Answer D (dobutamine 5 mcg/kg/min) is correct, and Answers A (norepinephrine 0.08 mcg/kg/min), B (epinephrine 0.08 mcg/kg/min), and C (Milrinone 0.75 mcg/ kg/min) are incorrect.", "page": 17, "answerPage": 59, "stemZh": "J.M.檢查顯示BP90/56、MAP67、HR56、CVP28、PAP46/22、CI1.8、ScvO2 53%、lactate6.9、BNP1936；四肢冰冷、capillary refill不佳。團隊已開furosemide80 mg IV一次，何種vasopressor或inotrope最適當？", "optionsZh": [{"key": "A", "text": "Norepinephrine0.08 mcg/kg/min"}, {"key": "B", "text": "Epinephrine0.08 mcg/kg/min"}, {"key": "C", "text": "Milrinone0.75 mcg/kg/min"}, {"key": "D", "text": "Dobutamine5 mcg/kg/min"}], "explanationZh": "有明顯low cardiac output而MAP尚可，dobutamine可改善contractility與灌流。", "contextZh": "J.M.，68歲男性，6個月前STEMI並放置兩個drug-eluting stents，合併type2 diabetes、hypertension、dyslipidemia、GERD、OSA、反覆epistaxis、ischemic cardiomyopathy（LVEF30–35%）及moderate–severe mitral regurgitation。因嚴重dyspnea與mental status改變入住cardiac ICU，使用CPAP。兩週體重增加13 kg至121 kg，利尿劑增加後仍尿量下降。居家藥物aspirin81 mg daily、ticagrelor90 mg每12小時、pantoprazole40 mg daily、atorvastatin40 mg daily、insulin glargine10 units nightly、metformin500 mg每12小時、furosemide40 mg BID、potassium chloride20 mEq BID。因費用1個月前clopidogrel換成ticagrelor samples；肺部廣泛rales，無發燒、焦慮但清醒。"}, {"id": "11-case-04", "chapter": 11, "type": "case", "number": 4, "stem": "J.M.’s ECG results reveal no acute evidence of ST segment changes. However, the resident is still considering a diagnosis of ACS, given the patient’s shortness of breath and mild troponin elevation. Which statement would be most accurate regarding the potential for other potential diagnoses?", "context": "J.M. is a 68-year-old man with a history of CAD including STEMI 6 months ago with placement of two drugeluting stents, type 2 diabetes, hypertension, dyslipidemia, gastroesophageal reflux disease, obstructive sleep apnea, frequent epistaxis, ischemic cardiomyopathy (LVEF 30%–35%), and moderate to severe mitral regurgitation. He is admitted to the cardiac intensive care unit for severe shortness of breath and altered mental status, and he is currently on continuous positive airway pressure (CPAP). He has gained 13 kg during the past 2 weeks (now weighs 121 kg) and has had decreased urine output, despite having had his diuretic dose increased. Home medications include the following: aspirin 81 mg once daily, ticagrelor 90 mg every 12 hours, pantoprazole 40 mg once daily, atorvastatin 40 mg once daily, insulin glargine 10 units every night, metformin 500 mg every 12 hours, furosemide 40 mg twice daily, and potassium chloride 20 mEq twice daily. His wife states that he was taking clopidogrel until 1 month ago, at which time he was given ticagrelor samples from his primary care physician because of cost concerns. A physical examination reveals rales throughout his lung fields. He is afebrile, anxious, and alert.", "options": [{"key": "A", "text": "No, this is most likely an NSTEMI.", "sourceKey": "A"}, {"key": "B", "text": "Yes, it is likely undiagnosed chronic obstructive pulmonary disease.", "sourceKey": "B"}, {"key": "C", "text": "Yes, it is likely early sepsis.", "sourceKey": "C"}, {"key": "D", "text": "Yes, it is likely decompensated HF.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient’s troponin elevation is most likely a result of the patient’s decompensated HF (especially considering clinical evidence of acute HF, such as high BNP, CVP, and low cardiac output) superimposed on chronic CAD (Answer D is correct). Given the patient’s chemistry and ABG results, chronic obstructive pulmonary disease (Answer B) is highly unlikely. Although this presentation could be attributed to NSTEMI (Answer A), it is less likely, given the lack of new ST-T changes on ECG and the accompanying evidence of an HF exacerbation. Sepsis (Answer C) is also a potential contributor to troponin elevation; by comparison, an infectious etiology is less likely in this patient’s case.", "page": 26, "answerPage": 59, "stemZh": "J.M.無acute ST changes，但有dyspnea與輕度troponin升高；住院醫師懷疑ACS。關於其他診斷，哪項最準確？", "optionsZh": [{"key": "A", "text": "最可能是NSTEMI"}, {"key": "B", "text": "可能是未診斷的COPD"}, {"key": "C", "text": "可能是early sepsis"}, {"key": "D", "text": "可能是decompensated HF"}], "explanationZh": "Troponin輕度上升可發生於decompensated HF，不能單憑此確診ACS。", "contextZh": "J.M.，68歲男性，6個月前STEMI並放置兩個drug-eluting stents，合併type2 diabetes、hypertension、dyslipidemia、GERD、OSA、反覆epistaxis、ischemic cardiomyopathy（LVEF30–35%）及moderate–severe mitral regurgitation。因嚴重dyspnea與mental status改變入住cardiac ICU，使用CPAP。兩週體重增加13 kg至121 kg，利尿劑增加後仍尿量下降。居家藥物aspirin81 mg daily、ticagrelor90 mg每12小時、pantoprazole40 mg daily、atorvastatin40 mg daily、insulin glargine10 units nightly、metformin500 mg每12小時、furosemide40 mg BID、potassium chloride20 mEq BID。因費用1個月前clopidogrel換成ticagrelor samples；肺部廣泛rales，無發燒、焦慮但清醒。"}, {"id": "11-case-05", "chapter": 11, "type": "case", "number": 5, "stem": "J.M. has been experiencing intermittent bradycardia on telemetry. The team has consulted the cardiac electrophysiology team. In the meantime, which statement most accurately reflects whether any other underlying correctable/contributing causes can be addressed?", "context": "J.M. is a 68-year-old man with a history of CAD including STEMI 6 months ago with placement of two drugeluting stents, type 2 diabetes, hypertension, dyslipidemia, gastroesophageal reflux disease, obstructive sleep apnea, frequent epistaxis, ischemic cardiomyopathy (LVEF 30%–35%), and moderate to severe mitral regurgitation. He is admitted to the cardiac intensive care unit for severe shortness of breath and altered mental status, and he is currently on continuous positive airway pressure (CPAP). He has gained 13 kg during the past 2 weeks (now weighs 121 kg) and has had decreased urine output, despite having had his diuretic dose increased. Home medications include the following: aspirin 81 mg once daily, ticagrelor 90 mg every 12 hours, pantoprazole 40 mg once daily, atorvastatin 40 mg once daily, insulin glargine 10 units every night, metformin 500 mg every 12 hours, furosemide 40 mg twice daily, and potassium chloride 20 mEq twice daily. His wife states that he was taking clopidogrel until 1 month ago, at which time he was given ticagrelor samples from his primary care physician because of cost concerns. A physical examination reveals rales throughout his lung fields. He is afebrile, anxious, and alert.", "options": [{"key": "A", "text": "Ticagrelor could be discontinued and switched back to clopidogrel.", "sourceKey": "A"}, {"key": "B", "text": "Ticagrelor should be discontinued altogether.", "sourceKey": "B"}, {"key": "C", "text": "No treatment intervention is needed; this is likely the result of J.M.’s HF progression.", "sourceKey": "C"}, {"key": "D", "text": "J.M.’s hyperkalemia should be treated.", "sourceKey": "D"}], "answer": "A", "explanation": "Ticagrelor has been associated with adenosine-mediated dyspnea and bradycardia; therefore, this medication should be evaluated as a contributing cause. According to the current ACC/AHA guidelines, this patient should continue P2Y 12 inhibitor therapy because his stent was placed less than 12 months ago, and he should continue aspirin therapy indefinitely (Answer A is correct). Conversely, it would not be appropriate to stop ticagrelor without switching to an alternative P2Y 12 inhibitor (Answer B is incorrect). A likely cause has been identified (Answer C is incorrect), and the patient has no evidence of hyperkalemia (Answer D is incorrect).", "page": 26, "answerPage": 59, "stemZh": "J.M.反覆bradycardia，已會診cardiac electrophysiology；目前何種可矯正因素最需處理？", "optionsZh": [{"key": "A", "text": "停ticagrelor並改回clopidogrel"}, {"key": "B", "text": "完全停用ticagrelor"}, {"key": "C", "text": "無須介入，可能是HF進展"}, {"key": "D", "text": "治療hyperkalemia"}], "explanationZh": "Ticagrelor可能造成bradyarrhythmia，可改回clopidogrel，同時維持所需antiplatelet therapy。", "contextZh": "J.M.，68歲男性，6個月前STEMI並放置兩個drug-eluting stents，合併type2 diabetes、hypertension、dyslipidemia、GERD、OSA、反覆epistaxis、ischemic cardiomyopathy（LVEF30–35%）及moderate–severe mitral regurgitation。因嚴重dyspnea與mental status改變入住cardiac ICU，使用CPAP。兩週體重增加13 kg至121 kg，利尿劑增加後仍尿量下降。居家藥物aspirin81 mg daily、ticagrelor90 mg每12小時、pantoprazole40 mg daily、atorvastatin40 mg daily、insulin glargine10 units nightly、metformin500 mg每12小時、furosemide40 mg BID、potassium chloride20 mEq BID。因費用1個月前clopidogrel換成ticagrelor samples；肺部廣泛rales，無發燒、焦慮但清醒。"}, {"id": "11-case-06", "chapter": 11, "type": "case", "number": 6, "stem": "J.M. has had increasing premature atrial complexes on telemetry, and his heart rate has consistently been 83–96 beats/minute. He is receiving dobutamine at 5 mcg/kg/minute and a furosemide infusion at 10 mg/ hour. The team is notified that J.M. has gone into AF with rapid ventricular response and a heart rate of 132 beats/minute (he has been in AF for about 30 minutes). His blood pressure is now 83/52 mm Hg. Which treatment plan would be most preferred for this patient?", "context": "The appropriate intervention has been made from question 5, and the patient has not required any need for pacing. For the next 48 hours, J.M. continues on inotrope therapy and is being diuresed (his net fluid balance has been 1250 and 900 mL negative each day for the past 2 days). The transthoracic ECHO results showed J.M.’s ejection fraction to be 15%–20%, with a dilated, hypokinetic LV, severe mitral regurgitation, and dilated atria. No evidence of intracardiac thrombus was seen, but this could not be ruled out.", "options": [{"key": "A", "text": "Synchronized cardioversion", "sourceKey": "A"}, {"key": "B", "text": "Metoprolol 5 mg intravenous push", "sourceKey": "B"}, {"key": "C", "text": "Adenosine 6 mg rapid intravenous push", "sourceKey": "C"}, {"key": "D", "text": "Amiodarone 300-mg intravenous push, followed by a continuous infusion at 1 mg/minute", "sourceKey": "D"}], "answer": "A", "explanation": "Because of this patient’s hypotension and ongoing cardiogenic shock, synchronized cardioversion would be preferred (Answer A is correct). Metoprolol (Answer B) would be unfavorable because of the patient’s concurrent dobutamine use and hypotension; similarly, amiodarone 300 mg intravenous push (Answer D) could contribute to further hypotension. The primary of role of adenosine (Answer C) is to slow AV nodal conduction when patients are tachycardiac with a regular rhythm (i.e., supraventricular tachycardia) to terminate the arrhythmia or to help differentiate atrial from ventricular arrhythmias.", "page": 38, "answerPage": 59, "stemZh": "J.M.使用dobutamine5 mcg/kg/min與furosemide10 mg/hour，出現AF with RVR約30分鐘；HR132、BP83/52。何種方案最適當？", "optionsZh": [{"key": "A", "text": "Synchronized cardioversion"}, {"key": "B", "text": "Metoprolol5 mg IV push"}, {"key": "C", "text": "Adenosine6 mg rapid IV push"}, {"key": "D", "text": "Amiodarone300 mg IV push，再1 mg/min輸注"}], "explanationZh": "AF伴hemodynamic instability時優先synchronized cardioversion。", "contextZh": "第5題介入後未需pacing。接續48小時持續inotrope及diuresis，兩天fluid balance分別−1250及−900 mL。Transthoracic ECHO：EF15–20%、dilated hypokinetic LV、severe mitral regurgitation、dilated atria；未見intracardiac thrombus但無法排除。"}, {"id": "11-case-07", "chapter": 11, "type": "case", "number": 7, "stem": "J.M.’s BP and HR improved after the previous intervention; however, he remains in AF. The team is now concerned about evaluating the patient for anticoagulation. You are asked to provide input about the appropriateness of anticoagulation, given the patient’s clinical course and past medical history. His calculated CHA 2 DS 2 -VASc score is 5 and HAS-BLED score is 5. The physician is considering anticoagulation with a heparin infusion while the patient is in the ICU and asks for a recommendation. Which is the most appropriate response?", "context": "The appropriate intervention has been made from question 5, and the patient has not required any need for pacing. For the next 48 hours, J.M. continues on inotrope therapy and is being diuresed (his net fluid balance has been 1250 and 900 mL negative each day for the past 2 days). The transthoracic ECHO results showed J.M.’s ejection fraction to be 15%–20%, with a dilated, hypokinetic LV, severe mitral regurgitation, and dilated atria. No evidence of intracardiac thrombus was seen, but this could not be ruled out.", "options": [{"key": "A", "text": "According to these scores, the patient’s risk of bleeding is the same as his stroke risk; therefore, it would be reasonable to either initiate or withhold anticoagulation.", "sourceKey": "A"}, {"key": "B", "text": "According to these scores, the patient’s risk of stroke exceeds his risk of bleeding; therefore, it would be reasonable to initiate heparin anticoagulation.", "sourceKey": "B"}, {"key": "C", "text": "The HAS-BLED score is less relevant because it is derived from chronic warfarin use. However, anticoagulation is still likely warranted eventually, given the patient’s CHA 2 DS 2 -VASc score.", "sourceKey": "C"}, {"key": "D", "text": "The HAS-BLED and CHA 2 DS 2 -VASc scores are irrelevant to this patient’s current care, and anticoagulation is not warranted.", "sourceKey": "D"}], "answer": "C", "explanation": "The physician is considering heparin anticoagulation while the patient is in the ICU. Although valuable to consider for long-term anticoagulation, the HAS-BLED score is not validated for bleeding risk specific to heparin anticoagulation. Nonetheless, given the patient’s CHA 2 DS 2 -VASc score (annual stroke risk of 6.7%), anticoagulation should be considered, making Answer C correct and Answer D (“anticoagulation is not warranted”) incorrect. Answer A, “the patient’s risk of bleeding is the same as his stroke risk,” and Answer B, “the patient’s risk of stroke exceeds his risk of bleeding,” are incorrect statements because the foundation of these scores does not include risk of thromboembolism during ICU stay, nor do the scores assess risk of bleeding on heparin infusions.", "page": 38, "answerPage": 60, "stemZh": "介入後BP及HR改善但仍AF；CHA2DS2-VASc5、HAS-BLED5，團隊考慮heparin infusion。哪項建議最適當？", "optionsZh": [{"key": "A", "text": "兩種風險相同，給或不給anticoagulation皆合理"}, {"key": "B", "text": "Stroke風險高於bleeding，可開始heparin"}, {"key": "C", "text": "HAS-BLED來自chronic warfarin資料，目前較不適用，但依CHA2DS2-VASc未來仍可能需要anticoagulation"}, {"key": "D", "text": "兩分數都不相關且不需anticoagulation"}], "explanationZh": "兩種分數不能以數值直接相比；HAS-BLED並非專為急性ICU heparin治療建立。", "contextZh": "第5題介入後未需pacing。接續48小時持續inotrope及diuresis，兩天fluid balance分別−1250及−900 mL。Transthoracic ECHO：EF15–20%、dilated hypokinetic LV、severe mitral regurgitation、dilated atria；未見intracardiac thrombus但無法排除。"}, {"id": "11-case-08", "chapter": 11, "type": "case", "number": 8, "stem": "J.M. is no longer in AF but remains in cardiogenic shock. The cardiac intensive care unit team has consulted the cardiothoracic surgeons for evaluation of his mitral valve disease and has considered advanced HF therapies. In the patient’s decompensated state, he would likely need additional optimization if he were to undergo surgery. Which temporary means of mechanical circulatory support (MCS) might be most favorable to help stabilize this patient’s cardiogenic shock in the setting of moderate to severe mitral regurgitation?", "context": "The appropriate intervention has been made from question 5, and the patient has not required any need for pacing. For the next 48 hours, J.M. continues on inotrope therapy and is being diuresed (his net fluid balance has been 1250 and 900 mL negative each day for the past 2 days). The transthoracic ECHO results showed J.M.’s ejection fraction to be 15%–20%, with a dilated, hypokinetic LV, severe mitral regurgitation, and dilated atria. No evidence of intracardiac thrombus was seen, but this could not be ruled out.", "options": [{"key": "A", "text": "Venoarterial extracorporeal membrane oxygenation (ECMO)", "sourceKey": "A"}, {"key": "B", "text": "Venovenous ECMO", "sourceKey": "B"}, {"key": "C", "text": "Intra-aortic balloon counterpulsation", "sourceKey": "C"}, {"key": "D", "text": "None; the patient likely requires urgent surgery.", "sourceKey": "D"}], "answer": "C", "explanation": "Given his ongoing cardiogenic shock, this patient is unlikely to remain stable without intervention; thus, Answer D is incorrect. To help stabilize him, intraaortic balloon counterpulsation (Answer C) would best facilitate selective afterload reduction during systole (increasing cardiac output in a patient with a low ejection fraction and severe mitral regurgitation) while providing augmented diastolic pressures. Venovenous ECMO (Answer B) is unlikely to help because this means of MCS depends on a functional LV and RV to provide forward blood flow. Venoarterial ECMO (Answer A) may stabilize the patient; however, it would increase afterload on the aortic valve, which could worsen his mitral regurgitation. Furthermore, this degree of MCS may be unwarranted at this time unless the patient develops progressive hypoxic cardiopulmonary failure.", "page": 54, "answerPage": 60, "stemZh": "J.M.已不再AF但持續cardiogenic shock，伴moderate–severe mitral regurgitation，團隊評估手術及advanced HF therapy；哪種temporary MCS最有利於穩定？", "optionsZh": [{"key": "A", "text": "VA-ECMO"}, {"key": "B", "text": "VV-ECMO"}, {"key": "C", "text": "Intra-aortic balloon counterpulsation"}, {"key": "D", "text": "不使用，直接urgent surgery"}], "explanationZh": "Intra-aortic balloon counterpulsation可降低afterload，對mitral regurgitation伴cardiogenic shock有幫助。", "contextZh": "第5題介入後未需pacing。接續48小時持續inotrope及diuresis，兩天fluid balance分別−1250及−900 mL。Transthoracic ECHO：EF15–20%、dilated hypokinetic LV、severe mitral regurgitation、dilated atria；未見intracardiac thrombus但無法排除。"}, {"id": "12-self-01", "chapter": 12, "type": "self", "number": 1, "stem": "Which is the most appropriate first step in T.B.’s resuscitation?", "context": "T.B. is a 72-year-old man with a history of atrial fibrillation, coronary artery disease with drug-eluting stent placement in 2009, heart failure with reduced ejection fraction (most recent ejection fraction was 45% on echocardiogram in 2018), and gastroesophageal reflux disease. T.B. is sent to the catheterization laboratory for suspected acute myocardial infarction. Laboratory values for T.B. are as follows: international normalized ratio (INR) 1, platelet count 200,000/mm3, hemoglobin 12 g/ dL, serum creatinine (SCr) 1.7 mg/dL (baseline 1.5 mg/ dL), white blood cell count (WBC) 17 x 103 cells/mm3, and aspartate aminotransferase (AST) 100 IU/L. He is admitted to the coronary care unit for observation after catheterization when he suddenly loses consciousness and becomes pulseless. The coronary care unit team of which you are part is called to the bedside. Of note, T.B. has peripheral intravenous access, and before this event, he was on room air by nasal cannula.", "options": [{"key": "A", "text": "Promptly intubate because this is likely a hypoxic pulmonary arrest.", "sourceKey": "A"}, {"key": "B", "text": "Place central line for vasopressor administration.", "sourceKey": "B"}, {"key": "C", "text": "Provide chest compressions.", "sourceKey": "C"}, {"key": "D", "text": "Give 2 breaths by bag-mask ventilator.", "sourceKey": "D"}], "answer": "C", "explanation": "The largest portion of adult cardiac arrests are caused by cardiovascular, not respiratory, events (Answer A is incorrect). In addition, this patient was on room air and nasal cannula immediately before the event, which could suggest his respiratory status was stable and unlikely to lead to cardiac arrest. Advanced airways and medications have only been shown to facilitate ROSC in cardiac arrest in contrast to chest compressions and defibrillation (if indicated), which can improve survival. Because of this, CPR should begin immediately for this patient before line placement to facilitate medication delivery (Answer B is incorrect), starting with chest compressions in accordance with the BLS guidelines with pads placed simultaneously to facilitate rapid defibrillation if the patient’s rhythm reveals a shockable rhythm (Answer C is correct; Answer D is incorrect).", "page": 4, "answerPage": 55, "stemZh": "T.B.復甦最適當的第一步為何？", "optionsZh": [{"key": "A", "text": "立即intubation，因可能為hypoxic pulmonary arrest"}, {"key": "B", "text": "置放central line以給vasopressor"}, {"key": "C", "text": "Chest compressions"}, {"key": "D", "text": "Bag-mask ventilation給2次呼吸"}], "explanationZh": "無pulse時立即高品質chest compressions。", "contextZh": "T.B.，72歲男性，有AF、CAD（2009年drug-eluting stent）、HFrEF（2018年EF45%）及GERD。因疑acute MI接受catheterization後，在CCU觀察時突然失去意識且無pulse。INR1、Plt200000、Hgb12、SCr1.7（baseline1.5）、WBC17×10³、AST100；已有peripheral IV，事件前未需額外氧氣。"}, {"id": "12-self-02", "chapter": 12, "type": "self", "number": 2, "stem": "The monitor reveals that T.B. is in ventricular fibrillation (VF), and T.B. remains pulseless. Which is the most appropriate management of T.B.’s VF arrest?", "context": "T.B. is a 72-year-old man with a history of atrial fibrillation, coronary artery disease with drug-eluting stent placement in 2009, heart failure with reduced ejection fraction (most recent ejection fraction was 45% on echocardiogram in 2018), and gastroesophageal reflux disease. T.B. is sent to the catheterization laboratory for suspected acute myocardial infarction. Laboratory values for T.B. are as follows: international normalized ratio (INR) 1, platelet count 200,000/mm3, hemoglobin 12 g/ dL, serum creatinine (SCr) 1.7 mg/dL (baseline 1.5 mg/ dL), white blood cell count (WBC) 17 x 103 cells/mm3, and aspartate aminotransferase (AST) 100 IU/L. He is admitted to the coronary care unit for observation after catheterization when he suddenly loses consciousness and becomes pulseless. The coronary care unit team of which you are part is called to the bedside. Of note, T.B. has peripheral intravenous access, and before this event, he was on room air by nasal cannula.", "options": [{"key": "A", "text": "Provide an unsynchronized shock/defibrillation at 120 J from a biphasic defibrillator.", "sourceKey": "A"}, {"key": "B", "text": "Give intravenous amiodarone at a dose of 300 mg.", "sourceKey": "B"}, {"key": "C", "text": "Give intravenous atropine at a dose of 1 mg.", "sourceKey": "C"}, {"key": "D", "text": "Provide emergency transcutaneous pacing.", "sourceKey": "D"}], "answer": "A", "explanation": "The cornerstone of therapy for VF cardiac arrest is rapid defibrillation (Answer A is correct). The recommended dosage of voltage for biphasic defibrillators is 200 J or the manufacturer’s recommendation (often the same dosage). Although amiodarone is in the treatment algorithm for VF cardiac arrest, it is reserved and recommended for refractory VF cardiac arrest, which is defined as defibrillation refractory (Answer B is incorrect). Therefore, defibrillation should occur first. Atropine has been removed from the cardiac arrest algorithms for PEA and asystole because of a lack of benefit on outcomes and should not be considered for VF cardiac arrest (Answer C is incorrect). Pacing has not shown benefit in cardiac arrest and should not be used (Answer D is incorrect).", "page": 4, "answerPage": 55, "stemZh": "T.B.為VF且無pulse，最適當處置為何？", "optionsZh": [{"key": "A", "text": "Biphasic defibrillator以120 J進行unsynchronized shock"}, {"key": "B", "text": "Amiodarone300 mg IV"}, {"key": "C", "text": "Atropine1 mg IV"}, {"key": "D", "text": "緊急transcutaneous pacing"}], "explanationZh": "VF屬shockable rhythm，應儘速defibrillation。", "contextZh": "T.B.，72歲男性，有AF、CAD（2009年drug-eluting stent）、HFrEF（2018年EF45%）及GERD。因疑acute MI接受catheterization後，在CCU觀察時突然失去意識且無pulse。INR1、Plt200000、Hgb12、SCr1.7（baseline1.5）、WBC17×10³、AST100；已有peripheral IV，事件前未需額外氧氣。"}, {"id": "12-self-03", "chapter": 12, "type": "self", "number": 3, "stem": "T.B.’s rhythm changes from VF to pulseless electrical activity (PEA) on the monitor. Which is the most appropriate management of T.B.’s PEA arrest?", "context": "T.B. is a 72-year-old man with a history of atrial fibrillation, coronary artery disease with drug-eluting stent placement in 2009, heart failure with reduced ejection fraction (most recent ejection fraction was 45% on echocardiogram in 2018), and gastroesophageal reflux disease. T.B. is sent to the catheterization laboratory for suspected acute myocardial infarction. Laboratory values for T.B. are as follows: international normalized ratio (INR) 1, platelet count 200,000/mm3, hemoglobin 12 g/ dL, serum creatinine (SCr) 1.7 mg/dL (baseline 1.5 mg/ dL), white blood cell count (WBC) 17 x 103 cells/mm3, and aspartate aminotransferase (AST) 100 IU/L. He is admitted to the coronary care unit for observation after catheterization when he suddenly loses consciousness and becomes pulseless. The coronary care unit team of which you are part is called to the bedside. Of note, T.B. has peripheral intravenous access, and before this event, he was on room air by nasal cannula.", "options": [{"key": "A", "text": "Provide an unsynchronized shock/defibrillation at 120 J from a biphasic defibrillator.", "sourceKey": "A"}, {"key": "B", "text": "Chest compressions while considering treatable causes of cardiac arrest.", "sourceKey": "B"}, {"key": "C", "text": "Give intravenous lidocaine 1 mg/kg x 1, followed by an infusion at 1 mg/minute.", "sourceKey": "C"}, {"key": "D", "text": "Give intravenous atropine at a dose of 1 mg.", "sourceKey": "D"}], "answer": "B", "explanation": "Because the rhythm detected is PEA and no longer VF, the cornerstone of therapy changes from giving defibrillation (Answer A is incorrect) to giving high-quality chest compressions and addressing the treatable causes of cardiac arrest (H’s and T’s) (Answer B is correct). Lidocaine is reserved for refractory VF/pVT) (defined as defibrillator refractory) when amiodarone is unavailable (Answer C is incorrect). Atropine was previously recommended for PEA/asystole, but in the 2010 ACLS guidelines it was removed because of a lack of data supporting any beneficial outcomes (Answer D is incorrect).", "page": 4, "answerPage": 55, "stemZh": "T.B.由VF轉為PEA，最適當處置為何？", "optionsZh": [{"key": "A", "text": "120 J unsynchronized shock"}, {"key": "B", "text": "Chest compressions並尋找可治療原因"}, {"key": "C", "text": "Lidocaine1 mg/kg IV一次，再1 mg/min輸注"}, {"key": "D", "text": "Atropine1 mg IV"}], "explanationZh": "PEA非shockable rhythm，持續CPR並處理reversible causes。", "contextZh": "T.B.，72歲男性，有AF、CAD（2009年drug-eluting stent）、HFrEF（2018年EF45%）及GERD。因疑acute MI接受catheterization後，在CCU觀察時突然失去意識且無pulse。INR1、Plt200000、Hgb12、SCr1.7（baseline1.5）、WBC17×10³、AST100；已有peripheral IV，事件前未需額外氧氣。"}, {"id": "12-self-04", "chapter": 12, "type": "self", "number": 4, "stem": "T.B. has return of spontaneous circulation (ROSC) after 15 minutes of total resuscitation. The team is deciding whether temperature control would be appropriate for T.B. Which is the most accurate statement regarding temperature control for T.B.?", "context": "T.B. is a 72-year-old man with a history of atrial fibrillation, coronary artery disease with drug-eluting stent placement in 2009, heart failure with reduced ejection fraction (most recent ejection fraction was 45% on echocardiogram in 2018), and gastroesophageal reflux disease. T.B. is sent to the catheterization laboratory for suspected acute myocardial infarction. Laboratory values for T.B. are as follows: international normalized ratio (INR) 1, platelet count 200,000/mm3, hemoglobin 12 g/ dL, serum creatinine (SCr) 1.7 mg/dL (baseline 1.5 mg/ dL), white blood cell count (WBC) 17 x 103 cells/mm3, and aspartate aminotransferase (AST) 100 IU/L. He is admitted to the coronary care unit for observation after catheterization when he suddenly loses consciousness and becomes pulseless. The coronary care unit team of which you are part is called to the bedside. Of note, T.B. has peripheral intravenous access, and before this event, he was on room air by nasal cannula.", "options": [{"key": "A", "text": "He should not be considered because his initial presentation was VF arrest.", "sourceKey": "A"}, {"key": "B", "text": "He should not be considered because he has transaminitis.", "sourceKey": "B"}, {"key": "C", "text": "He should be considered with SCr monitoring.", "sourceKey": "C"}, {"key": "D", "text": "He should be considered, but thrombolysis should be initiated concurrently because of the associated risk of clotting.", "sourceKey": "D"}], "answer": "C", "explanation": "Temperature control is a consideration, according to the international guidelines for all patients with ROSC who remain comatose after a cardiac arrest (Answer A is incorrect). Although most well-designed and executed studies primarily enrolled patients with VF cardiac arrest, application is recommended for all patients with a cardiac arrest independent of rhythm. Although worsening transaminitis and hepatic enzymatic function slowing is likely to occur during hypothermia, neither of these principles would be considered a contraindication for hypothermia (Answer B is incorrect). Furthermore, renal function with respect to glomerular filtration worsens, which requires vigilant monitoring of renal function and close attention to renal dose modifications and serum concentration monitoring of medications when applicable (Answer C is correct). An additional complication of therapeutic hypothermia is an induced coagulopathy, which leads patients to be at risk of bleeding. Thrombolytics may carry specific indications for cardiac arrest (e.g., pulmonary embolism or acute coronary syndromes), but they would not be recommended empirically (Answer D is incorrect).", "page": 5, "answerPage": 55, "stemZh": "T.B.復甦15分鐘後ROSC；關於temperature control，何者最準確？", "optionsZh": [{"key": "A", "text": "初始VF所以不適合"}, {"key": "B", "text": "Transaminitis所以不適合"}, {"key": "C", "text": "可考慮並監測SCr"}, {"key": "D", "text": "可考慮，但須同時thrombolysis預防clotting"}], "explanationZh": "應考慮temperature control，並監测renal function與相關併發症。", "contextZh": "T.B.，72歲男性，有AF、CAD（2009年drug-eluting stent）、HFrEF（2018年EF45%）及GERD。因疑acute MI接受catheterization後，在CCU觀察時突然失去意識且無pulse。INR1、Plt200000、Hgb12、SCr1.7（baseline1.5）、WBC17×10³、AST100；已有peripheral IV，事件前未需額外氧氣。"}, {"id": "12-self-05", "chapter": 12, "type": "self", "number": 5, "stem": "The medical team wants further information about the literature regarding temperature control. Which is the most appropriate information regarding the data to support temperature control?", "context": "T.B. is a 72-year-old man with a history of atrial fibrillation, coronary artery disease with drug-eluting stent placement in 2009, heart failure with reduced ejection fraction (most recent ejection fraction was 45% on echocardiogram in 2018), and gastroesophageal reflux disease. T.B. is sent to the catheterization laboratory for suspected acute myocardial infarction. Laboratory values for T.B. are as follows: international normalized ratio (INR) 1, platelet count 200,000/mm3, hemoglobin 12 g/ dL, serum creatinine (SCr) 1.7 mg/dL (baseline 1.5 mg/ dL), white blood cell count (WBC) 17 x 103 cells/mm3, and aspartate aminotransferase (AST) 100 IU/L. He is admitted to the coronary care unit for observation after catheterization when he suddenly loses consciousness and becomes pulseless. The coronary care unit team of which you are part is called to the bedside. Of note, T.B. has peripheral intravenous access, and before this event, he was on room air by nasal cannula.", "options": [{"key": "A", "text": "Improves survival in PEA cardiac arrests.", "sourceKey": "A"}, {"key": "B", "text": "Shown to improve neurologic outcomes.", "sourceKey": "B"}, {"key": "C", "text": "Superiority found when targeting a core temperature of 36°C compared with 33°C.", "sourceKey": "C"}, {"key": "D", "text": "Most studied in patients with asystole.", "sourceKey": "D"}], "answer": "B", "explanation": "Temperature control improves neurologic recovery in patients after a cardiac arrest (Answer B is correct). Most patients included in randomized clinical trials have VF as the causative rhythm (Answers A and D are incorrect). Because of its impact on neurologic recovery, guideline recommendations have applied this literature to cardiac arrests of all rhythms, and many institutions have adopted this same recommendation. Recent studies targeting mild hypothermia (36°C vs. 33°C) have shown no difference regarding outcomes between the two modalities, and because of this, some question the utility of hypothermia at all in an era of potentially more advanced cardiac arrest care (Answer C is incorrect).", "page": 5, "answerPage": 55, "stemZh": "哪項最符合本章temperature control的文獻證據？", "optionsZh": [{"key": "A", "text": "改善PEA arrest的survival"}, {"key": "B", "text": "可改善neurologic outcomes"}, {"key": "C", "text": "36°C優於33°C"}, {"key": "D", "text": "研究多數為asystole"}], "explanationZh": "本章強調temperature control與neurologic outcomes的證據；其他敘述不符合原章解析。", "contextZh": "T.B.，72歲男性，有AF、CAD（2009年drug-eluting stent）、HFrEF（2018年EF45%）及GERD。因疑acute MI接受catheterization後，在CCU觀察時突然失去意識且無pulse。INR1、Plt200000、Hgb12、SCr1.7（baseline1.5）、WBC17×10³、AST100；已有peripheral IV，事件前未需額外氧氣。"}, {"id": "12-self-06", "chapter": 12, "type": "self", "number": 6, "stem": "Which laboratory abnormality or presenting symptom best qualifies J.H. for hypertensive emergency?", "context": "J.H. is a 48-year-old woman with no known medical history who presents to the emergency department (ED) for acute onset of shortness of breath, right-side pain, and some blurry vision. She denies any illicit drug or cigarette use, but she confirms social alcohol intake (about 3 drinks per week). Urine toxicology is negative. Initial vital signs are as follows: blood pressure (BP) 202/140 mm Hg, heart rate (HR) 88 beats/minute, respiratory rate (RR) 22 breaths/minute, and pain 4/10 (chest and rightside pain). Initial laboratory values are as follows: SCr 0.8 mg/dL, AST 608 U/L, ALT 458 U/L, lipase 20 U/L, total bilirubin (Tbil) 1 mg/dL, direct bilirubin (Dbil) 0.4 mg/dL, WBC 6 x 103 cells/mm3, hemoglobin 11 mg/dL, troponin T less than 0.01 ng/mL, and D-dimer less than 0.5 mcg/mL. Chest radiography shows moderate bilateral pleural effusions and no focal consolidations. Chest computed tomography (CT) is negative for pulmonary embolism. Of note, J.H. is taking no prescription or overthe-counter medications.", "options": [{"key": "A", "text": "None; she is having a hypertensive urgency.", "sourceKey": "A"}, {"key": "B", "text": "Her SCr.", "sourceKey": "B"}, {"key": "C", "text": "Her AST/ALT.", "sourceKey": "C"}, {"key": "D", "text": "Her D-dimer.", "sourceKey": "D"}], "answer": "C", "explanation": "By definition, this patient is having a hypertensive emergency because she has an abrupt, severe increase in BP with target organ damage—in this case, potentially shock liver and vision changes. (Answer A is incorrect). The patient’s SCr is not elevated from baseline and is thus not presently showing target organ damage (Answer B is incorrect). This patient’s D-dimer is normal as well, but even if it were elevated, this is not a specific marker of target organ damage (Answer D is incorrect). The patient has significant elevations in her transaminases, indicating injury to the liver and thus qualifying her for hypertensive emergency (Answer C is correct).", "page": 5, "answerPage": 55, "stemZh": "J.H.哪項異常最支持hypertensive emergency？", "optionsZh": [{"key": "A", "text": "沒有，屬hypertensive urgency"}, {"key": "B", "text": "SCr"}, {"key": "C", "text": "AST／ALT"}, {"key": "D", "text": "D-dimer"}], "explanationZh": "嚴重BP升高伴AST／ALT顯著上升，支持acute end-organ injury。", "contextZh": "J.H.，48歲女性，無已知病史，急性dyspnea、右側疼痛及blurred vision，無非法藥物或吸菸；每週約3份酒精，urine toxicology陰性且無處方／OTC藥。BP202/140、HR88、RR22、pain4/10。SCr0.8、AST608、ALT458、lipase20、Tbil1、Dbil0.4、WBC6×10³、Hgb11、troponin-T<0.01、D-dimer<0.5。胸片bilateral pleural effusions無focal consolidation，CT未見PE。"}, {"id": "12-self-07", "chapter": 12, "type": "self", "number": 7, "stem": "Which is the most appropriate initial treatment strategy for J.H.’s BP?", "context": "J.H. is a 48-year-old woman with no known medical history who presents to the emergency department (ED) for acute onset of shortness of breath, right-side pain, and some blurry vision. She denies any illicit drug or cigarette use, but she confirms social alcohol intake (about 3 drinks per week). Urine toxicology is negative. Initial vital signs are as follows: blood pressure (BP) 202/140 mm Hg, heart rate (HR) 88 beats/minute, respiratory rate (RR) 22 breaths/minute, and pain 4/10 (chest and rightside pain). Initial laboratory values are as follows: SCr 0.8 mg/dL, AST 608 U/L, ALT 458 U/L, lipase 20 U/L, total bilirubin (Tbil) 1 mg/dL, direct bilirubin (Dbil) 0.4 mg/dL, WBC 6 x 103 cells/mm3, hemoglobin 11 mg/dL, troponin T less than 0.01 ng/mL, and D-dimer less than 0.5 mcg/mL. Chest radiography shows moderate bilateral pleural effusions and no focal consolidations. Chest computed tomography (CT) is negative for pulmonary embolism. Of note, J.H. is taking no prescription or overthe-counter medications.", "options": [{"key": "A", "text": "Phentolamine 1 mg intravenously every 30 minutes.", "sourceKey": "A"}, {"key": "B", "text": "Metoprolol 25 mg orally every 12 hours.", "sourceKey": "B"}, {"key": "C", "text": "Nitroprusside 0.25 mcg/kg/minute by continuous intravenous infusion.", "sourceKey": "C"}, {"key": "D", "text": "Enalaprilat 10 mg intravenously every 6 hours.", "sourceKey": "D"}], "answer": "C", "explanation": "The patient should be initiated on nitroprusside for BP management (Answer C is correct). Although she has transaminitis, nitroprusside can be used safely in the first 24 hours in these patients. Cyanide accumulation would be a concern with extended use, but for the first 24 hours, the patient will be at minimal risk, and the benefit of rapid BP control outweighs any potential risk. Phentolamine would be reserved for hypertensive crisis that presents from a catecholamine crisis (Answer A is incorrect). Oral metoprolol might be an appropriate option to transition to after the emergency is resolved, but because of the target organ damage, more rapid reduction is needed using an intravenous agent such as nitroprusside (Answer B is incorrect). Enalaprilat is an option, but 10 mg every 6 hours would not be an appropriate starting dose because it would put the patient at risk of overshooting and, given the long duration of activity, could lead to unwanted consequences (Answer D is incorrect).", "page": 5, "answerPage": 56, "stemZh": "J.H.最適當初始降壓策略為何？", "optionsZh": [{"key": "A", "text": "Phentolamine1 mg IV每30分鐘"}, {"key": "B", "text": "Metoprolol25 mg口服每12小時"}, {"key": "C", "text": "Nitroprusside0.25 mcg/kg/min持續IV infusion"}, {"key": "D", "text": "Enalaprilat10 mg IV每6小時"}], "explanationZh": "Hypertensive emergency需可快速調整的IV藥物；原章選nitroprusside。", "contextZh": "J.H.，48歲女性，無已知病史，急性dyspnea、右側疼痛及blurred vision，無非法藥物或吸菸；每週約3份酒精，urine toxicology陰性且無處方／OTC藥。BP202/140、HR88、RR22、pain4/10。SCr0.8、AST608、ALT458、lipase20、Tbil1、Dbil0.4、WBC6×10³、Hgb11、troponin-T<0.01、D-dimer<0.5。胸片bilateral pleural effusions無focal consolidation，CT未見PE。"}, {"id": "12-self-08", "chapter": 12, "type": "self", "number": 8, "stem": "Which is the most appropriate goal for J.H.’s BP reduction?", "context": "J.H. is a 48-year-old woman with no known medical history who presents to the emergency department (ED) for acute onset of shortness of breath, right-side pain, and some blurry vision. She denies any illicit drug or cigarette use, but she confirms social alcohol intake (about 3 drinks per week). Urine toxicology is negative. Initial vital signs are as follows: blood pressure (BP) 202/140 mm Hg, heart rate (HR) 88 beats/minute, respiratory rate (RR) 22 breaths/minute, and pain 4/10 (chest and rightside pain). Initial laboratory values are as follows: SCr 0.8 mg/dL, AST 608 U/L, ALT 458 U/L, lipase 20 U/L, total bilirubin (Tbil) 1 mg/dL, direct bilirubin (Dbil) 0.4 mg/dL, WBC 6 x 103 cells/mm3, hemoglobin 11 mg/dL, troponin T less than 0.01 ng/mL, and D-dimer less than 0.5 mcg/mL. Chest radiography shows moderate bilateral pleural effusions and no focal consolidations. Chest computed tomography (CT) is negative for pulmonary embolism. Of note, J.H. is taking no prescription or overthe-counter medications.", "options": [{"key": "A", "text": "Goal mean arterial pressure (MAP) reduction of 25% during the first 60 minutes.", "sourceKey": "A"}, {"key": "B", "text": "Goal MAP reduction of 50% during the first 60 minutes.", "sourceKey": "B"}, {"key": "C", "text": "Goal MAP reduction of 25% during the first 24 hours.", "sourceKey": "C"}, {"key": "D", "text": "Goal MAP reduction of 50% during the first 24 hours.", "sourceKey": "D"}], "answer": "A", "explanation": "The initial goal reduction for this patient’s BP, given that she is experiencing a hypertensive emergency, is a 25% reduction in MAP within the first 60 minutes (Answer A is correct). More rapid BP reductions may result in a lack of cerebral perfusion; therefore, they are not recommended (Answer B is incorrect). The patient is not experiencing any of the specific hypertensive emergencies (e.g., aortic dissection) that would call for a more rapid BP reduction. In addition, she is not experiencing a hypertensive emergency that would require a slower BP reduction (e.g., stroke) (Answers C and D are incorrect).", "page": 5, "answerPage": 56, "stemZh": "J.H.最適當降壓目標為何？", "optionsZh": [{"key": "A", "text": "首60分鐘MAP下降25%"}, {"key": "B", "text": "首60分鐘MAP下降50%"}, {"key": "C", "text": "首24小時MAP下降25%"}, {"key": "D", "text": "首24小時MAP下降50%"}], "explanationZh": "一般hypertensive emergency避免降壓過快，首小時MAP下降約25%。", "contextZh": "J.H.，48歲女性，無已知病史，急性dyspnea、右側疼痛及blurred vision，無非法藥物或吸菸；每週約3份酒精，urine toxicology陰性且無處方／OTC藥。BP202/140、HR88、RR22、pain4/10。SCr0.8、AST608、ALT458、lipase20、Tbil1、Dbil0.4、WBC6×10³、Hgb11、troponin-T<0.01、D-dimer<0.5。胸片bilateral pleural effusions無focal consolidation，CT未見PE。"}, {"id": "12-case-01", "chapter": 12, "type": "case", "number": 1, "stem": "A.C., a 50-year-old man with a history of gastroesophageal reflux disorder and chronic obstructive pulmonary disease, was admitted for shortness of breath, palpitations, and presumed exacerbation of his lung disease. On hospital admission day 4, A.C. has a witnessed cardiac arrest on the family medicine unit. The emergency response team of which you are part is called, and when you arrive, the bedside nurse has already begun chest compressions. Which insight would be best shared regarding chest compressions for A.C.?", "context": "", "options": [{"key": "A", "text": "Because the nurse has already begun chest compressions, she should continue chest compressions for the duration of CPR.", "sourceKey": "A"}, {"key": "B", "text": "Compressions increase intrathoracic pressure and directly compress the heart, which can generate cardiac output and deliver oxygen.", "sourceKey": "B"}, {"key": "C", "text": "Because increasing the intrathoracic pressure is vital to oxygen delivery, chest recoil is unnecessary and should be avoided.", "sourceKey": "C"}, {"key": "D", "text": "Number of chest compressions per minute does not affect outcomes, so pulse check and line and airway placements can interrupt chest compressions.", "sourceKey": "D"}], "answer": "B", "explanation": "Because rescuer fatigue is common and may lead to inadequate compression quality, it is recommended to change rescuers every 2 minutes, with no more than 5 seconds between changes (Answer A is incorrect). Compressions are vital because they increase intrathoracic pressure and directly compress the heart, leading to oxygen delivery to the vital organs (Answer B is correct). Specific aspects of chest compression quality are necessary. These include a rate of 100–120 compressions per minute at a depth of 2–2.4 inches in adults, allowing for recoil after each compression; placement of the patient on a hard surface (e.g., backboard); and minimization of interruptions (Answer C is incorrect). Outcomes, including neurologically intact survival, ROSC, and possibly overall survival, are linked to minimizing interruptions in chest compressions. Because of this, it is recommended that interruptions (e.g., pulse checks and intubation) be less than 10 seconds and that chest compressions be resumed immediately (Answer D is incorrect).", "page": 9, "answerPage": 53, "stemZh": "50歲A.C.因dyspnea與palpitations住院，第4天發生目擊cardiac arrest；護理師已開始CPR。關於chest compressions哪項最正確？", "optionsZh": [{"key": "A", "text": "同一護理師應持續壓胸至整個CPR結束"}, {"key": "B", "text": "壓胸增加intrathoracic pressure並直接壓迫心臟，產生cardiac output與氧輸送"}, {"key": "C", "text": "Chest recoil不必要且應避免"}, {"key": "D", "text": "壓胸頻率不影響outcomes，可為pulse check或置管而中斷"}], "explanationZh": "Chest compressions透過胸腔壓力與直接壓迫心臟維持血流；亦須完整recoil並减少中斷。", "contextZh": ""}, {"id": "12-case-02", "chapter": 12, "type": "case", "number": 2, "stem": "L.S. is a 66-year-old woman visiting her husband at the hospital on the hospice unit. She is buying lunch in the cafeteria, and while in line to check out, she collapses. The emergency response team of which you are part is summoned. L.S. does not respond to voice or tapping of the shoulder, and a brief look at her chest shows no chest movement. Chest compressions are initiated while the crash cart and defibrillator are retrieved. Of note, a bag-mask ventilator is available at the scene because it is carried with the emergency response team. Which is most accurate about L.S.’s airway and breathing management?", "context": "", "options": [{"key": "A", "text": "A compression/ventilation ratio of 15:2 should be used throughout resuscitation efforts.", "sourceKey": "A"}, {"key": "B", "text": "Because it is a multiple-rescuer scene, bag-mask ventilation should not be used because it is recommended only in single-rescuer resuscitations.", "sourceKey": "B"}, {"key": "C", "text": "Rescue breaths should be given at a ratio of 30 compressions to 2 breaths, avoiding excessive ventilation given as synchronous ventilations.", "sourceKey": "C"}, {"key": "D", "text": "Bag-mask ventilation should not be used in any patient because advanced airways are preferred to supply oxygen and eliminate CO 2 .", "sourceKey": "D"}], "answer": "C", "explanation": "Cardiac arrest patients have minimal blood flow, and oxygenation/ventilation requirements are lower; the new recommendation is to provide 1 breath every 5–6 seconds (10–12 breaths/minute) until an advanced airway is in place (Answer C is correct). Although the optimal ratio is unclear and chest compressions appear to be more vital to resuscitation, other ratios cannot currently be recommended (Answer A is incorrect). It is clear, however, that excessive ventilation can lead to decreased venous return and gastric inflation, which can lead to aspiration, regurgitation, and impacts on outcomes. In this case, a bag-mask ventilator is available, and more than one rescuers are involved, so the bag-mask ventilator should be used (Answer B is incorrect). In single health care provider rescuer situations, the bag-mask ventilator should never be used, and mouth-to-mouth or mouth-to-barrier resuscitation is recommended. In a single nonmedical rescuer situation, hands-only CPR is recommended. Advanced airways can be considered but should be placed only by experienced and trained personnel. Bag-mask ventilation can provide adequate oxygenation/ventilation until an airway can be secured (Answer D is incorrect).", "page": 11, "answerPage": 53, "stemZh": "66歲L.S.在餐廳倒下，無反應且無呼吸；已開始CPR，現場有bag-mask。關於airway及breathing何者最正確？", "optionsZh": [{"key": "A", "text": "全程15:2"}, {"key": "B", "text": "多位rescuers時不可bag-mask ventilation"}, {"key": "C", "text": "30次壓胸搭配2次同步呼吸，避免excessive ventilation"}, {"key": "D", "text": "任何病人都不應bag-mask ventilation，應使用advanced airway"}], "explanationZh": "尚無advanced airway時採30:2並避免過度通氣。", "contextZh": ""}, {"id": "12-case-03", "chapter": 12, "type": "case", "number": 3, "stem": "T.V. is a 72-year-old man with a history of chronic liver disease, hypoglycemia, and atrial fibrillation. He was admitted to the medical intensive care unit (MICU) 2 days ago for sepsis requiring aggressive fluid resuscitation and intravenous antibiotics. T.V. did not require vasopressors to treat his sepsis. On ICU day 3, T.V. develops VF on telemetry, loses consciousness, and becomes pulseless; the MICU team is summoned for a presumed VF cardiac arrest. Pads are placed on T.V. by the time the team arrives, and the rhythm is confirmed to be VF. Which is the most accurate statement regarding defibrillation for T.V.?", "context": "", "options": [{"key": "A", "text": "Three vital actions with VF can lead to increased survival if they occur rapidly: activate emergency response system, provide CPR, and deliver shock.", "sourceKey": "A"}, {"key": "B", "text": "T.V. should not be defibrillated but should be paced out of the VF, if possible, because pacing is more effective for pulseless VF.", "sourceKey": "B"}, {"key": "C", "text": "Chest compressions should be delayed until the defibrillator is charged because defibrillation is the definitive treatment of VF.", "sourceKey": "C"}, {"key": "D", "text": "Alternative treatments such as antiarrhythmics, vasopressors, and magnesium should be tried first.", "sourceKey": "D"}], "answer": "A", "explanation": "Three vital actions with VF aid in survival: call emergency response team (already accomplished in case), begin CPR (must be initiated in case), and deliver shock (must occur in case) (Answer A is correct). Pacing can be effective in overriding stable VT but should not be used in the cardiac arrest or hemodynamically unstable patient (Answer B is incorrect). It is currently unclear whether postponing defibrillation for the provision of chest compressions first is of benefit, but it is clear that chest compressions should be initiated until the defibrillator is ready, charged, and set to deliver the shock because this increases the likelihood of success with defibrillation (Answer C is incorrect). Because time in VF predicts survival, and the longer patients are in VF the more difficult it is to terminate the arrhythmia, alternative treatments such as medications should not impede the provision of defibrillation (Answer D is incorrect).", "page": 13, "answerPage": 53, "stemZh": "72歲T.V.有liver disease、hypoglycemia與AF，因sepsis住ICU，第3天發生pulseless VF。關於defibrillation何者正確？", "optionsZh": [{"key": "A", "text": "快速啟動emergency response、CPR與shock可改善survival"}, {"key": "B", "text": "Pacing比defibrillation更有效"}, {"key": "C", "text": "等待defibrillator充電後才CPR"}, {"key": "D", "text": "先試antiarrhythmic、vasopressor及magnesium"}], "explanationZh": "VF需要即時CPR與儘早defibrillation，不應因藥物或充電而延誤壓胸。", "contextZh": ""}, {"id": "12-case-04", "chapter": 12, "type": "case", "number": 4, "stem": "F.V. is a 63-year-old woman with a history of diabetes, heart failure with preserved ejection fraction, hypertension, and obstructive sleep apnea who presents to the ED with chest tightness and “feeling funny.” In the ED, F.V. loses consciousness and develops pVT. Chest compressions are initiated immediately, pads are placed, and bag-mask ventilation is given at a compression/ventilation ratio of 30:2 for two cycles. The monitor confirms the rhythm of pVT. The defibrillator is charged, the patient is cleared, and the first shock is delivered. Chest compressions resume, and during the next pulse check, the patient is intubated. F.V. still has no pulse, and chest compressions are continued. Which is the most accurate statement about F.V.’s resuscitation after advanced airway placement?", "context": "", "options": [{"key": "A", "text": "The compression/ventilation ratio should remain 30:2 to avoid excessive ventilation.", "sourceKey": "A"}, {"key": "B", "text": "The advanced airway should have been placed before defibrillation and CPR for pVT.", "sourceKey": "B"}, {"key": "C", "text": "The patient should be placed on room air (21% Fio2 [fraction of inspired oxygen]).", "sourceKey": "C"}, {"key": "D", "text": "Proper airway placement should be confirmed with clinical assessment and objective measures.", "sourceKey": "D"}], "answer": "D", "explanation": "After the advanced airway is in place, it is crucial to confirm placement in order to provide the intended oxygenation/ventilation. The confirmation should occur with both clinical and objective measurements (Answer D is correct). These include a physical assessment of the chest and epigastrium, end-tidal CO 2 monitoring, and/ or continuous waveform capnography. In most cardiac arrests (particularly in this patient’s pVT), airway management should not impede the provision of CPR and/or defibrillation (when defibrillation is indicated) (Answer B is incorrect). After the advanced airway is in place, 100% oxygen should be delivered to optimize the arterial oxygen saturation (Answer C is incorrect). In the cardiac arrest population, this has not been shown to carry the same toxicity as in other populations. Furthermore, after advanced airway is placed, compressions should be administered at a rate of 100–120 compressions per minute continuously, with breaths every 6 seconds (Answer A is incorrect).", "page": 16, "answerPage": 53, "stemZh": "63歲F.V.發生pVT，已CPR及shock，隨後intubation仍無pulse。關於advanced airway後復甦何者最準確？", "optionsZh": [{"key": "A", "text": "仍維持30:2"}, {"key": "B", "text": "應於defibrillation及CPR之前intubation"}, {"key": "C", "text": "改用room air21% FiO2"}, {"key": "D", "text": "用clinical assessment及objective measures確認airway位置"}], "explanationZh": "Advanced airway placement應以臨床與客觀方式確認。", "contextZh": ""}, {"id": "12-case-05", "chapter": 12, "type": "case", "number": 5, "stem": "V.B., a 62-year-old man with an unknown medical history, comes to your ED altered and incoherent. He is admitted to the ED for observation, where he suddenly becomes unconscious and pulseless. The ED staff immediately initiates CPR for V.B., who is found to be in PEA. Which statement best describes appropriate cardiac arrest treatment?", "context": "", "options": [{"key": "A", "text": "Survival from PEA is solely dependent on medications and advanced airways, so airway intubation and line placement take priority over CPR.", "sourceKey": "A"}, {"key": "B", "text": "The treatable causes of PEA cardiac arrest should be reviewed and addressed while CPR and laboratory tests are sent.", "sourceKey": "B"}, {"key": "C", "text": "Because the patient is in PEA, pads should be placed, the patient cleared, and shock delivered immediately.", "sourceKey": "C"}, {"key": "D", "text": "No strategies exist for post-arrest care to avoid re-arrest or improve outcomes from the PEA cardiac arrest.", "sourceKey": "D"}], "answer": "B", "explanation": "In all cardiac arrests, the treatable causes (i.e., H’s and T’s) should be reviewed and addressed, if possible (Answer B is correct). In patients for whom the laboratory and diagnostic data are known, the information should be reviewed while CPR is being provided. In patients for whom the information is unknown, clinical evaluation and attainment of information should occur, when possible. This retrieval of information, together with the administration of medications and advanced airway placement, should never impede on the provision of CPR or defibrillation, if indicated, because defibrillation (for VF and pVT)) and CPR are the only strategies that have been shown to affect survival from cardiac arrest (Answer A is incorrect). Pulseless electrical activity is not a wide complex dysrhythmia, and defibrillation would not be indicated (Answer C is incorrect). Post-cardiac arrest care is crucial in the prevention of re-arrest and, in temperature control, can significantly affect neurologic outcomes (Answer D is incorrect).", "page": 18, "answerPage": 53, "stemZh": "62歲V.B.意識不清，觀察中變無反應且無pulse，節律為PEA；何項敘述最適當？", "optionsZh": [{"key": "A", "text": "Survival只取決於藥物與airway，置管優先於CPR"}, {"key": "B", "text": "CPR及檢驗同時檢視並處理PEA可治療原因"}, {"key": "C", "text": "PEA應立即shock"}, {"key": "D", "text": "沒有post-arrest care策略可以改善結果"}], "explanationZh": "PEA需CPR與reversible causes評估，無須defibrillation。", "contextZh": ""}, {"id": "12-case-06", "chapter": 12, "type": "case", "number": 6, "stem": "M.G., a 58-year-old woman with a history of chronic osteoarthritis and peptic ulcer disease, is admitted to the MICU with hypovolemic shock caused by a suspected bleeding gastric ulcer. Endoscopy is performed, confirming the gastric ulceration. The ulcer is cauterized, and M.G. is stabilized. On ICU day 2, M.G. becomes lethargic, hypoxic, and subsequently pulseless. The MICU team is summoned, and the monitor reveals VF. Resuscitation efforts begin, and the ACLS algorithm is followed. The patient will receive amiodarone. Which general principles are most accurate regarding amiodarone administration for M.G.’s VF arrest?", "context": "", "options": [{"key": "A", "text": "Endotracheal delivery is preferred because all cardiac arrest medications can be delivered by the endotracheal route.", "sourceKey": "A"}, {"key": "B", "text": "Peripheral administration is preferred because the peak concentrations are higher and the circulation time is shorter than with other routes.", "sourceKey": "B"}, {"key": "C", "text": "Intraosseous administration is preferred because administration and dosing are similar to that for the endotracheal route.", "sourceKey": "C"}, {"key": "D", "text": "Central intravenous administration is preferred because the peak concentration and circulation time is shorter than with other routes.", "sourceKey": "D"}], "answer": "D", "explanation": "In general, it is important to remember that medication administration benefits only myocardial blood flow, ROSC, and possibly survival to hospital admission in cardiac arrest. Medication administration should never impede the provision of CPR and/or defibrillation. Central administration, if already available, is preferred for several reasons. These include higher peak concentrations, shorter circulation time, more standard dosing, and the lack of additional administration techniques needed (Answer D is correct). Endotracheal administration is an option, but only NAVEL (naloxone, atropine, vasopressin, epinephrine, and lidocaine) medications can be administered, the optimal doses are unknown, and medications must be diluted before administered (Answer A is incorrect). Given that this patient is in VF arrest, amiodarone, for example, could not be administered by endotracheal administration if it were indicated. Peripheral administration can be used and is the most common route of administration given that most hospitalized patients have it already, but it requires an additional bolus of fluid afterward and has a longer circulating time than does central administration (Answer B is incorrect). Intraosseous can also be used, with the caveat that tibial intraosseous administration is similar to peripheral administration and requires training to master the technique for placement (Answer C is incorrect).", "page": 19, "answerPage": 54, "stemZh": "58歲M.G.因bleeding gastric ulcer造成hypovolemic shock，止血後第2天發生VF arrest；將給amiodarone，何種給藥原則最準確？", "optionsZh": [{"key": "A", "text": "Endotracheal route優先，所有arrest藥物皆可由此給"}, {"key": "B", "text": "Peripheral route優先，peak較高且circulation time較短"}, {"key": "C", "text": "IO優先，其劑量與endotracheal相同"}, {"key": "D", "text": "Central IV較佳，peak與circulation time較有利"}], "explanationZh": "原章比較給藥動力學，central IV到達central circulation較快；選項A–C錯誤。", "contextZh": ""}, {"id": "12-case-07", "chapter": 12, "type": "case", "number": 7, "stem": "K.G., a 71-year-old woman with a history of atrial fibrillation, coronary artery disease status post three-vessel coronary bypass artery grafting 6 years ago, diabetes, and osteoarthritis, is being admitted to your MICU for temperature control after PEA arrest and subsequent ROSC. K.G., who remained comatose after the ROSC, was intubated and is now hemodynamically stable (BP 94/72 mm Hg and HR 86 beats/minute). Which is the most accurate statement regarding temperature control?", "context": "", "options": [{"key": "A", "text": "Hypoglycemia is a common complication of hypothermia and may require continuous dextrose infusions.", "sourceKey": "A"}, {"key": "B", "text": "Dose modifications or avoidance of cytochrome P450 (CYP)–metabolized medications should occur during hypothermia.", "sourceKey": "B"}, {"key": "C", "text": "The optimal duration of temperature control should be at least 72 hours to affect survival.", "sourceKey": "C"}, {"key": "D", "text": "Temperature targets should be 28°C–30°C to improve the neurologic recovery.", "sourceKey": "D"}], "answer": "B", "explanation": "Temperature control improves neurologic recovery when initiated, optimally within 2 hours but in up to 6–8 hours after VF cardiac arrest (application to all forms), and used for 12–24 hours (Answer C is incorrect). The goal temperature is 32°C–36°C. Data suggest there is no benefit of 33 C versus 36 C in improvement of survival or neurologic outcomes (Answer D is incorrect). If temperature control will be used, close monitoring of complications should occur. These complications include hyperglycemia caused by decreased insulin production and peripheral activity (Answer A is incorrect), bradycardias, enzymatic slowing (including CYP system), increased incidence of sepsis and infections, coagulopathies, decreased glomerular filtration, and shivering (Answer B is correct).", "page": 34, "answerPage": 54, "stemZh": "71歲K.G.在PEA arrest後ROSC但仍coma，已intubation且BP94/72、HR86；temperature control何者正確？", "optionsZh": [{"key": "A", "text": "Hypothermia常有hypoglycemia，可能需dextrose infusion"}, {"key": "B", "text": "Hypothermia時應調整或避免CYP代謝藥物"}, {"key": "C", "text": "至少72小時才改善survival"}, {"key": "D", "text": "溫度目標28–30°C"}], "explanationZh": "Hypothermia降低drug metabolism與clearance，需評估CYP代謝藥物劑量。", "contextZh": ""}, {"id": "12-case-08", "chapter": 12, "type": "case", "number": 8, "stem": "B.B. is a 44-year-old man with no significant medical history who presents to the ED with a ripping sensation in his chest. His social history includes cigarette smoking, 1.5 packs/day for the past 20 years. Chest radiography in the ED reveals mediastinal widening. Cardiac enzymes are within normal limits. Laboratory values include sodium 135 mEq/L, potassium 4.3 mEq/L, HCO 3 - 24 mEq/L, SCr 0.55 mg/dL, glucose 110 mg/dL, DBil 0.2 mg/dL, and AST 39 U/L. B.B. is rushed for a chest CT and angiography, which reveal an acute type A and B aortic dissection. His vital signs include BP 208/140 mm Hg and HR 120 beats/minute. Which is the most appropriate management for B.B.?", "context": "", "options": [{"key": "A", "text": "Use esmolol to achieve goal of 25% reduction in MAP during the first 60 minutes.", "sourceKey": "A"}, {"key": "B", "text": "Use lisinopril and hydrochlorothiazide to achieve BP reduction goal to 160/100 mm Hg during the first 24 hours.", "sourceKey": "B"}, {"key": "C", "text": "Use labetalol to achieve 25% reduction in MAP and HR less than 60 beats/minute in the first 60 minutes.", "sourceKey": "C"}, {"key": "D", "text": "Use esmolol with or without nitroprusside to achieve SBP less than 100 mm Hg and HR less than 60 beats/minute as soon as possible.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient is experiencing a hypertensive emergency with his target organ damage being an acute aortic dissection. Aortic dissection is one of the individual hypertensive emergencies that has a specific mechanism of worsening (propagation) from BP and shear stress, which require both rapid BP and HR control. Given the gravity of propagation, goals for aortic dissection are HR less than 60 beats/minute and SBP less than 100 mm Hg within minutes, if possible (Answer A is incorrect). This can be accomplished with a single agent like labetalol, which will control HR with its β-antagonist properties and decrease BP (afterload) with its α-antagonist properties (Answers B and C are incorrect). Esmolol can also be used as first line but will likely require an additional afterload-reducing agent such as nitroprusside (Answer D is correct).", "page": 41, "answerPage": 54, "stemZh": "44歲B.B.有撕裂胸痛，CT顯示acute typeA及B aortic dissection；BP208/140、HR120。何種治療最適當？", "optionsZh": [{"key": "A", "text": "Esmolol使首60分鐘MAP下降25%"}, {"key": "B", "text": "Lisinopril及hydrochlorothiazide使首24小時BP降至160/100"}, {"key": "C", "text": "Labetalol使首60分鐘MAP下降25%且HR<60"}, {"key": "D", "text": "Esmolol±nitroprusside，儘速使SBP<100且HR<60"}], "explanationZh": "Aortic dissection需迅速控制HR與BP，原章選esmolol並視需要加nitroprusside。", "contextZh": ""}, {"id": "13-self-01", "chapter": 13, "type": "self", "number": 1, "stem": "Which option best represents the two signs or symptoms that would qualify this patient for a diagnosis of acetaminophen-induced acute liver failure (ALF)?", "context": "A 25-year-old woman is brought to the emergency department (ED) after a suspected overdose of acetaminophen. The time of ingestion is unknown. On presentation, her acetaminophen concentration is undetectable, but her alanine aminotransferase (ALT) and aspartate aminotransferase (AST) concentrations are 3500 IU/L and 2500 IU/L, respectively. The patient is markedly confused with incoherent speech, but arousable. Other pertinent laboratory values include bilirubin 3.0 mg/dL and alkaline phosphatase 500 IU/L. White blood cell count is 12  103 cells/mm3, platelet count is 90,000/mm3, and international normalized ratio (INR) is 2.6.", "options": [{"key": "A", "text": "Jaundice and encephalopathy.", "sourceKey": "A"}, {"key": "B", "text": "Thrombocytopenia and encephalopathy.", "sourceKey": "B"}, {"key": "C", "text": "Coagulopathy and encephalopathy.", "sourceKey": "C"}, {"key": "D", "text": "Leukocytosis and encephalopathy.", "sourceKey": "D"}], "answer": "C", "explanation": "The most recent guidelines from the American Association for the Study of Liver Diseases and the U.S. Acute Liver Failure Study Group define ALF as a coagulopathy, usually an INR of 1.5 or more, with any degree of encephalopathy in patients without preexisting liver disease (Answer C is correct). Although jaundice, thrombocytopenia, and leukocytosis can occur in patients with ALF, they are not currently defined as hallmark signs of the disease that exist in all patients (Answers A, B, and D are incorrect).", "page": 4, "answerPage": 64, "stemZh": "哪兩項症狀或徵象符合acetaminophen-induced ALF？", "optionsZh": [{"key": "A", "text": "Jaundice與encephalopathy"}, {"key": "B", "text": "Thrombocytopenia與encephalopathy"}, {"key": "C", "text": "Coagulopathy與encephalopathy"}, {"key": "D", "text": "Leukocytosis與encephalopathy"}], "explanationZh": "ALF的關鍵為coagulopathy與hepatic encephalopathy。", "contextZh": "25歲女性疑acetaminophen overdose，服藥時間不明。Acetaminophen濃度測不到，但ALT3500、AST2500 IU/L；明顯confusion與語無倫次，仍可喚醒。Bilirubin3、alkaline phosphatase500、WBC12×10³、Plt90000、INR2.6。"}, {"id": "13-self-02", "chapter": 13, "type": "self", "number": 2, "stem": "Which is the most appropriate treatment for her suspected acetaminophen-induced ALF?", "context": "A 25-year-old woman is brought to the emergency department (ED) after a suspected overdose of acetaminophen. The time of ingestion is unknown. On presentation, her acetaminophen concentration is undetectable, but her alanine aminotransferase (ALT) and aspartate aminotransferase (AST) concentrations are 3500 IU/L and 2500 IU/L, respectively. The patient is markedly confused with incoherent speech, but arousable. Other pertinent laboratory values include bilirubin 3.0 mg/dL and alkaline phosphatase 500 IU/L. White blood cell count is 12  103 cells/mm3, platelet count is 90,000/mm3, and international normalized ratio (INR) is 2.6.", "options": [{"key": "A", "text": "Give intravenous acetylcysteine 21-hour regimen, continuing if necessary until signs and symptoms of ALF have resolved.", "sourceKey": "A"}, {"key": "B", "text": "Acetylcysteine therapy is not indicated at this time because her acetaminophen concentration is undetectable.", "sourceKey": "B"}, {"key": "C", "text": "Give oral acetylcysteine 72-hour regimen.", "sourceKey": "C"}, {"key": "D", "text": "Oral acetylcysteine or intravenous acetylcysteine may be used because the two routes are similarly efficacious.", "sourceKey": "D"}], "answer": "A", "explanation": "Administration of acetylcysteine is recommended in all ALF cases when acetaminophen is suspected as a cause, regardless of the acetaminophen concentration (Answer B is incorrect). Although oral and intravenous formulations have efficacy for the treatment of acetaminophen overdose, the intravenous formulation is recommended when patients have greater than grade I encephalopathy or hypotension or when they cannot tolerate oral therapy (Answers C and D are incorrect). Intravenous acetylcysteine is recommended for most patients who present with liver failure and can be extended beyond the 21-hour regimen, especially if therapy was initiated more than 8 hours after ingestion or baseline concentrations were greater than 300 mg/dL (Answer A is correct).", "page": 4, "answerPage": 64, "stemZh": "疑似acetaminophen-induced ALF最適當治療為何？", "optionsZh": [{"key": "A", "text": "IV acetylcysteine21小時療程，必要時延長至ALF改善"}, {"key": "B", "text": "濃度測不到所以不需acetylcysteine"}, {"key": "C", "text": "Oral acetylcysteine72小時療程"}, {"key": "D", "text": "口服與IV皆可，療效相同"}], "explanationZh": "濃度測不到仍可能已有acetaminophen-related ALF，應給IV acetylcysteine並按臨床反應延長。", "contextZh": "25歲女性疑acetaminophen overdose，服藥時間不明。Acetaminophen濃度測不到，但ALT3500、AST2500 IU/L；明顯confusion與語無倫次，仍可喚醒。Bilirubin3、alkaline phosphatase500、WBC12×10³、Plt90000、INR2.6。"}, {"id": "13-self-03", "chapter": 13, "type": "self", "number": 3, "stem": "A 46-year-old man presents with alcohol-induced severe acute pancreatitis (AP). Pertinent medical history includes alcoholic cirrhosis and several admissions for aspiration pneumonia secondary to hepatic encephalopathy. He is given intravenous fluids for initial volume resuscitation with lactated Ringer solution. Which action would be best for the patient’s nutrition?", "context": "", "options": [{"key": "A", "text": "Give nothing by mouth (i.e., kept NPO) to rest the pancreas until AP is resolved.", "sourceKey": "A"}, {"key": "B", "text": "Initiate total parenteral nutrition (TPN).", "sourceKey": "B"}, {"key": "C", "text": "Give enteral feeding by the nasogastric (NG) route.", "sourceKey": "C"}, {"key": "D", "text": "Give enteral feeding by the nasojejunal (NJ) route.", "sourceKey": "D"}], "answer": "D", "explanation": "Patients with AP should not be kept NPO (Answer A is incorrect). Studies that have compared TPN with enteral feeding in AP have shown that enteral feeding is associated with reduced mortality and infectious complications. Thus, enteral feeding is recommended over TPN for AP, if it is tolerated (Answer B is incorrect). Enteral feeding can be given by either the NJ or the NG route for AP, though the NG route may increase the risk of aspiration. Because this patient has several admissions for aspiration and is thus high risk for aspiration, it is safer to use the NJ route over the NG route (Answer C is incorrect, Answer D is correct).", "page": 5, "answerPage": 64, "stemZh": "46歲男性有alcohol-induced severe AP與alcoholic cirrhosis，曾因hepatic encephalopathy多次aspiration pneumonia；已LR復甦，營養何者最好？", "optionsZh": [{"key": "A", "text": "AP改善前保持NPO"}, {"key": "B", "text": "開始TPN"}, {"key": "C", "text": "NG enteral feeding"}, {"key": "D", "text": "NJ enteral feeding"}], "explanationZh": "Enteral nutrition較TPN適當；此人aspiration風險高，NJ較合適。", "contextZh": ""}, {"id": "13-self-04", "chapter": 13, "type": "self", "number": 4, "stem": "A 37-year-old woman presents after a Roux-en-Y gastric bypass for morbid obesity. Her postoperative course was complicated by the formation of an enterocutaneous fistula, fevers, and leukocytosis. She was initiated on broad-spectrum antibiotics, and a wound vacuum-assisted closure was placed on her fistula site to help with drainage and healing. Her fistula output was 570 mL/day yesterday, and today, it was 250 mL/ day. Which statement is most accurate regarding her fistula output between the two recordings?", "context": "", "options": [{"key": "A", "text": "Her output would be defined as a low output on both days.", "sourceKey": "A"}, {"key": "B", "text": "Her output would be defined as a high output that has converted to a low output.", "sourceKey": "B"}, {"key": "C", "text": "Her output would be defined as a high output that has converted to a moderate output.", "sourceKey": "C"}, {"key": "D", "text": "Her output would be considered moderate on both days.", "sourceKey": "D"}], "answer": "C", "explanation": "Fistula output is defined as high if the output is greater than 500 mL/day, moderate if it is 200–500 mL/day, and low if it is less than 200 mL/day. This patient’s fistula output has decreased significantly (Answers A and D are incorrect) from 570 mL/day to 250 mL/day, but it is still not enough to classify her fistula output as low (Answer B is incorrect). Her output has decreased from high to moderate (Answer C is correct).", "page": 5, "answerPage": 64, "stemZh": "37歲女性gastric bypass後出現enterocutaneous fistula；昨天570 mL/day，今天250 mL/day，如何分類？", "optionsZh": [{"key": "A", "text": "兩天皆low output"}, {"key": "B", "text": "由high轉low"}, {"key": "C", "text": "由high轉moderate"}, {"key": "D", "text": "兩天皆moderate"}], "explanationZh": "High output>500 mL/day；250 mL/day為moderate output。", "contextZh": ""}, {"id": "13-self-05", "chapter": 13, "type": "self", "number": 5, "stem": "A 68-year-old man presents for a large bowel resection. Given the high incidence of postoperative ileus (POI) with this procedure, he is initiated on alvimopan before surgery. To reduce the cardiovascular risk associated with alvimopan, the U.S. Food and Drug Administration (FDA) placed a restriction on alvimopan use that has been implemented through the EASE (ENTEREG Access Support & Education) program. Which best represents that restriction?", "context": "", "options": [{"key": "A", "text": "Start continuous electrocardiogram (ECG) monitoring on initiation to monitor for corrected QT (QTc) prolongation.", "sourceKey": "A"}, {"key": "B", "text": "Use is restricted to short term with a limit of 15 doses.", "sourceKey": "B"}, {"key": "C", "text": "Decrease alvimopan dose to 6 mg twice daily.", "sourceKey": "C"}, {"key": "D", "text": "Use is contraindicated in patients with previous myocardial infarction.", "sourceKey": "D"}], "answer": "B", "explanation": "In a long-term study of alvimopan for opioid-induced bowel dysfunction, alvimopan was associated with higher rates of myocardial infarction than was placebo. To mitigate this risk, the FDA has limited the use of alvimopan to short-term, inpatient use, and patients cannot receive more than 15 doses (Answer B is correct); however, its use is not contraindicated in patients with a history of myocardial infarction (Answer D is incorrect). The FDA-approved dose is 12 mg twice daily, and there is no requirement for QTc monitoring with alvimopan (Answers A and C are incorrect).", "page": 5, "answerPage": 64, "stemZh": "68歲男性large bowel resection前使用alvimopan；FDA EASE計畫的使用限制為何？", "optionsZh": [{"key": "A", "text": "開始時continuous ECG監測QTc"}, {"key": "B", "text": "短期使用且最多15劑"}, {"key": "C", "text": "減至6 mg BID"}, {"key": "D", "text": "曾MI者禁用"}], "explanationZh": "Alvimopan限短期住院使用且總量不超過15劑。", "contextZh": ""}, {"id": "13-self-06", "chapter": 13, "type": "self", "number": 6, "stem": "A 40-year-old woman presents for elective abdominal surgery to remove a malignancy from her liver. Given the extensiveness of the surgery, the expected use of volatile anesthetics, and the use of perioperative opioids, a multimodal plan is developed to avoid postoperative nausea and vomiting (PONV). Which best describes the timing of prophylactic administration with respect to surgery?", "context": "", "options": [{"key": "A", "text": "Dexamethasone 4 mg intravenously given at the end of surgery.", "sourceKey": "A"}, {"key": "B", "text": "Ondansetron 4 mg intravenously given when inducing anesthesia.", "sourceKey": "B"}, {"key": "C", "text": "Neurokinin-1 receptor antagonist (aprepitant 40–125 mg) given at the end of surgery.", "sourceKey": "C"}, {"key": "D", "text": "Droperidol 0.625–1.25 mg intravenously given at the end of surgery.", "sourceKey": "D"}], "answer": "D", "explanation": "Dexamethasone and aprepitant should be given before inducing anesthesia for the prevention of PONV (Answers A and C are incorrect). Ondansetron and other serotonin-3 antagonists are most effective if given at the end of surgery (Answer B is incorrect). Droperidol is effective for the prevention of PONV when given at the end of surgery (Answer D is correct).", "page": 5, "answerPage": 64, "stemZh": "40歲女性接受大型abdominal surgery，會用volatile anesthetics及opioids；哪项PONV prophylaxis給藥時間最適當？", "optionsZh": [{"key": "A", "text": "Dexamethasone4 mg IV於手術結束"}, {"key": "B", "text": "Ondansetron4 mg IV於induction"}, {"key": "C", "text": "Aprepitant40–125 mg於手術結束"}, {"key": "D", "text": "Droperidol0.625–1.25 mg IV於手術結束"}], "explanationZh": "Droperidol於手術結束給予；dexamethasone通常induction時，ondansetron近手術結束時。", "contextZh": ""}, {"id": "13-self-07", "chapter": 13, "type": "self", "number": 7, "stem": "A 69-year-old woman presents to the surgical intensive care unit (ICU) at your institution with upper gastrointestinal bleeding (UGIB) caused by a gastric ulcer. She has lost a significant amount of blood because of the bleed and currently requires blood transfusions. As part of her diagnostic workup to determine the etiology of her ulcer, she tests positive for a Helicobacter pylori infection. Which best reflects an inappropriate treatment option for her?", "context": "", "options": [{"key": "A", "text": "Octreotide 50 mcg bolus, followed by 50 mcg/ hour for 72 hours.", "sourceKey": "A"}, {"key": "B", "text": "Treatment with a proton pump inhibitor (PPI)/ antibiotic combination for 14 days.", "sourceKey": "B"}, {"key": "C", "text": "A therapeutic endoscopy within 24 hours.", "sourceKey": "C"}, {"key": "D", "text": "Blood transfusions to maintain hemoglobin greater than 7 g/dL.", "sourceKey": "D"}], "answer": "A", "explanation": "H. pylori is a recognized carcinogen and should be eradicated using a 14-day PPI/antibiotic combination (Answer B is incorrect). Patients with an acute UGIB who present with a high-risk bleed should have a diagnostic and therapeutic endoscopy within 24 hours of admission (Answer C is incorrect). Blood transfusions should be administered to keep the hemoglobin concentration greater than 7 g/dL (Answer D is incorrect). Therefore, the only inappropriate treatment option is using octreotide (Answer A is correct).", "page": 5, "answerPage": 64, "stemZh": "69歲女性gastric ulcer造成UGIB需輸血且H.pylori陽性；哪項治療不適當？", "optionsZh": [{"key": "A", "text": "Octreotide50 mcg bolus後50 mcg/hour72小時"}, {"key": "B", "text": "PPI與antibiotic組合14天"}, {"key": "C", "text": "24小時內therapeutic endoscopy"}, {"key": "D", "text": "輸血維持Hgb>7 g/dL"}], "explanationZh": "此為nonvariceal ulcer bleeding，octreotide並非適當常規治療。", "contextZh": ""}, {"id": "13-self-08", "chapter": 13, "type": "self", "number": 8, "stem": "Which set of laboratory abnormalities best reflects those that patients in thyroid storm typically present with?", "context": "", "options": [{"key": "A", "text": "High thyroid-stimulating hormone (TSH), triiodothyronine (T 3 ), and thyroxine (T 4 ) concentrations.", "sourceKey": "A"}, {"key": "B", "text": "Low TSH, high T 3 , and high T 4 concentrations.", "sourceKey": "B"}, {"key": "C", "text": "Low TSH, high T 3 , and low T 4 concentrations.", "sourceKey": "C"}, {"key": "D", "text": "Low TSH, low T 3 , and low T 4 concentrations.", "sourceKey": "D"}], "answer": "B", "explanation": "Thyroid storm is an uncommon but deadly manifestation of hyperthyroidism; therefore, TSH will be low, whereas T 4 and T 3 will be high (Answer B is correct). Myxedema coma is a manifestation of hypothyroidism; therefore, patients will typically have high TSH and low T 4 /T 3 . When TSH is high, both T 3 and T 4 are typically low (Answer A is incorrect). Conversely, if TSH is low, both T 3 and T 4 are typically high (Answers C and D are incorrect).", "page": 5, "answerPage": 65, "stemZh": "Thyroid storm典型thyroid function如何？", "optionsZh": [{"key": "A", "text": "TSH、T3、T4皆高"}, {"key": "B", "text": "TSH低、T3及T4高"}, {"key": "C", "text": "TSH低、T3高、T4低"}, {"key": "D", "text": "三者皆低"}], "explanationZh": "Thyrotoxicosis常見TSH受抑制，T3／T4升高。", "contextZh": ""}, {"id": "13-case-01", "chapter": 13, "type": "case", "number": 1, "stem": "A 60-year-old woman with rheumatoid arthritis was initiated on azathioprine 3 months ago and now presents with NAI-ALF secondary to DILI. On presentation, her ALT and AST concentrations are 500 IU/L and 350 IU/L, respectively. Her INR is 1.7, and she is mildly confused and drowsy. Which intervention has been shown most effective for the treatment of NAI-ALF?", "context": "", "options": [{"key": "A", "text": "Intravenous acetylcysteine 21-hour regimen.", "sourceKey": "A"}, {"key": "B", "text": "Intravenous acetylcysteine 72-hour regimen.", "sourceKey": "B"}, {"key": "C", "text": "Oral acetylcysteine 72-hour regimen.", "sourceKey": "C"}, {"key": "D", "text": "Oral glutamine supplementation.", "sourceKey": "D"}], "answer": "B", "explanation": "Intravenous acetylcysteine increases transplant-free survival rates for patients with NAI-ALF, particularly for patients with low-grade encephalopathy. Oral acetylcysteine has not been studied in a randomized controlled trial for NAI-ALF (Answer C is incorrect), and the dosing strategy for NAI-ALF is different from the 21-hour intravenous regimen for acetaminophen overdose (Answer A is incorrect). The dosing strategy for NAI-ALF is a 72-hour regimen with a 150-mg/kg bolus, followed by a 12.5-mg/kg/hour dose for 4 hours and then a 6.25-mg/kg/hour dose for 67 hours (Answer B is correct). Oral glutamine is not used for NAI-ALF; it has been studied to aid in the healing of GI fistulas (Answer D is incorrect).", "page": 15, "answerPage": 62, "stemZh": "60歲女性使用azathioprine3個月後發生DILI造成NAI-ALF；ALT500、AST350、INR1.7且輕度confusion及drowsiness，何介入最有效？", "optionsZh": [{"key": "A", "text": "IV acetylcysteine21小時"}, {"key": "B", "text": "IV acetylcysteine72小時"}, {"key": "C", "text": "Oral acetylcysteine72小時"}, {"key": "D", "text": "Oral glutamine"}], "explanationZh": "本章NAI-ALF證據支持IV acetylcysteine72小時，尤其早期encephalopathy。", "contextZh": ""}, {"id": "13-case-02", "chapter": 13, "type": "case", "number": 2, "stem": "A 33-year-old man presents with ALF secondary to acetaminophen overdose. He is now 72 hours post-ingestion and is profoundly encephalopathic and unresponsive to pain on examination. An ICP monitor is placed, which shows acute elevations of 30 mm Hg. Which is most appropriate for the acute management of ICP elevations?", "context": "", "options": [{"key": "A", "text": "Hypertonic saline continuous infusion to maintain serum sodium 145–155 mEq/L.", "sourceKey": "A"}, {"key": "B", "text": "Mannitol 0.5 mg/kg intravenously × 1.", "sourceKey": "B"}, {"key": "C", "text": "Hyperventilation to Paco2 of 25–30 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "Thiopental continuous infusion.", "sourceKey": "D"}], "answer": "B", "explanation": "Osmotic agents are first-line treatment for control of ICP. Although hypertonic saline prevents ICP elevations, the continuous infusion is not used for acute control (Answer A is incorrect). For acute control of ICP elevations, mannitol boluses are used first line provided serum osmolaity is less than 320 (Answer B is correct). Hyperventilation and barbiturates are only used to control ICP elevations when other options have failed (Answers C and D are incorrect).", "page": 18, "answerPage": 62, "stemZh": "33歲男性acetaminophen overdose後72小時，ALF且深度encephalopathy、無pain response；ICP升至30 mm Hg，急性處理何者最適當？", "optionsZh": [{"key": "A", "text": "Hypertonic saline持續輸注使Na145–155"}, {"key": "B", "text": "Mannitol0.5 mg/kg IV一次（原題如此）"}, {"key": "C", "text": "Hyperventilation至PaCO2 25–30"}, {"key": "D", "text": "Thiopental持續輸注"}], "explanationZh": "原章答案為mannitol，但題目印0.5 mg/kg，解析為0.5 g/kg，單位不一致，須核對原文；勿據此直接處方。", "contextZh": ""}, {"id": "13-case-03", "chapter": 13, "type": "case", "number": 3, "stem": "A 44-year-old woman presents to the ED with a 2-day history of diffuse abdominal pain. Amylase is 700 IU/L, and lipase is 800 IU/L. She is given intravenous fluids with lactated Ringer solution and enteral nutrition through an NJ tube. However, after 48 hours, she has still not improved, and CT imaging reveals pancreatic necrosis involving 40% of the pancreas. Which interventions would best be performed at this time?", "context": "", "options": [{"key": "A", "text": "Piperacillin/tazobactam should be prophylactically administered to prevent infected necrotizing pancreatitis.", "sourceKey": "A"}, {"key": "B", "text": "Surgical management of necrotizing pancreatitis is necessary.", "sourceKey": "B"}, {"key": "C", "text": "Antibiotics should be deferred unless systemic signs of infection are present.", "sourceKey": "C"}, {"key": "D", "text": "Meropenem should be prophylactically administered to prevent infected necrotizing pancreatitis.", "sourceKey": "D"}], "answer": "C", "explanation": "This patient has severe acute necrotizing pancreatitis because she has not improved after the first 48 hours, and her CT reveals pancreatitic necrosis involving more than 30% of her pancreas. There appears to be no benefit with using prophylactic antibiotics for patients with necrotizing AP, in reducing either mortality rates or rates of pancreatic and extrapancreatic infections, particularly in more recent studies (Answers A and D are incorrect). Surgical management for sterile necrosis is only recommended if patients have gastric outlet obstruction and/ or bile duct obstruction (Answer B is incorrect). For patients with severe acute necrotizing pancreatitis, it is recommended to defer antibiotics unless there is suggestion of infection or if patients have not improved within 7–10 days (Answer C is correct).", "page": 26, "answerPage": 62, "stemZh": "44歲女性AP以LR及NJ nutrition處理48小時仍未改善，CT顯示40%pancreatic necrosis；何介入最適當？", "optionsZh": [{"key": "A", "text": "預防性piperacillin/tazobactam"}, {"key": "B", "text": "立即手術"}, {"key": "C", "text": "無systemic infection徵象則暫不給antibiotics"}, {"key": "D", "text": "預防性meropenem"}], "explanationZh": "Sterile pancreatic necrosis不常規預防性antibiotics；需有感染證據再治療。", "contextZh": ""}, {"id": "13-case-04", "chapter": 13, "type": "case", "number": 4, "stem": "A 34-year-old woman with morbid obesity presents to the surgical ICU after gastric bypass surgery 1 week prior with an enterocutaneous fistula requiring medical management. Her current output is about 600 mL/ day. For the patient’s high-output fistula, which best represents the intervention that has not been associated with a reduction in fistula output volume?", "context": "", "options": [{"key": "A", "text": "Somatostatin 250 mcg/hour intravenously continuously.", "sourceKey": "A"}, {"key": "B", "text": "Octreotide 100 mcg subcutaneously three times daily.", "sourceKey": "B"}, {"key": "C", "text": "TPN.", "sourceKey": "C"}, {"key": "D", "text": "Glutamine 0.3 g/kg/day orally.", "sourceKey": "D"}], "answer": "D", "explanation": "Somatostatin significantly decreases fistula output compared with placebo (Answer A is incorrect). Total parenteral nutrition increases spontaneous closure rates by reducing GI secretions (Answer C is incorrect), and octreotide had a beneficial effect on fistula output in one small study (Answer B is incorrect). Although glutamine has been associated with spontaneous rates of fistula closure, it has been not been associated with reduced fistula output (Answer D is correct).", "page": 30, "answerPage": 62, "stemZh": "34歲女性gastric bypass後high-output enterocutaneous fistula約600 mL/day，何介入未證實降低output？", "optionsZh": [{"key": "A", "text": "Somatostatin250 mcg/hour IV"}, {"key": "B", "text": "Octreotide100 mcg SC TID"}, {"key": "C", "text": "TPN"}, {"key": "D", "text": "Glutamine0.3 g/kg/day口服"}], "explanationZh": "Glutamine未顯示降低fistula output；其他措施可減少output。", "contextZh": ""}, {"id": "13-case-05", "chapter": 13, "type": "case", "number": 5, "stem": "A 40-year-old man presents for a large bowel resection. Because of the complexity of the procedure and the anticipated use of perioperative opioids and inhalation anesthesia, the team is creating a plan to prevent POI. Which medication would be best to recommend for reducing the incidence of POI?", "context": "", "options": [{"key": "A", "text": "Hydromorphone patient-controlled analgesia postoperatively instead of morphine.", "sourceKey": "A"}, {"key": "B", "text": "Alvimopan 12 mg orally just before surgery and continued twice daily for 7 days.", "sourceKey": "B"}, {"key": "C", "text": "Metoclopramide 5 mg intravenously every 6 hours for 7 days postoperatively.", "sourceKey": "C"}, {"key": "D", "text": "Octreotide 100 mcg subcutaneously every 8 hours for 7 days postoperatively.", "sourceKey": "D"}], "answer": "B", "explanation": "Of the possible answers, only alvimopan has been shown to reduce the incidence of ileus postoperatively (Answer B is correct). Metoclopramide has shown mixed results, though the antiemetic properties may be beneficial as adjunctive therapy in POI, and octreotide is not used in the prevention of POI (Answers C and D are incorrect). All opioids can contribute equally to POI (Answer A is incorrect).", "page": 34, "answerPage": 62, "stemZh": "40歲男性large bowel resection，預期用opioids與inhalation anesthesia，何藥最適合減少POI？", "optionsZh": [{"key": "A", "text": "術後hydromorphone PCA取代morphine"}, {"key": "B", "text": "Alvimopan12 mg術前口服，之後BID7天"}, {"key": "C", "text": "Metoclopramide5 mg IV每6小時術後7天"}, {"key": "D", "text": "Octreotide100 mcg SC每8小時術後7天"}], "explanationZh": "Alvimopan可減少opioid-related POI，依規範短期使用。", "contextZh": ""}, {"id": "13-case-06", "chapter": 13, "type": "case", "number": 6, "stem": "A 27-year-old woman presents for a total abdominal hysterectomy. She is a nonsmoker who has a significant history of motion sickness. During the procedure, she is expected to receive general anesthesia with volatile anesthetics. She will probably require high-dose opioids perioperatively. Given this patient’s risk of developing PONV, which would she best receive for prevention of PONV?", "context": "", "options": [{"key": "A", "text": "Patient has a high risk of PONV; she should receive transdermal scopolamine the evening before surgery, dexamethasone 4 mg intravenously at the time of induction, and ondansetron 4 mg intravenously at the end of surgery.", "sourceKey": "A"}, {"key": "B", "text": "Patient has a moderate risk of PONV; she should receive dexamethasone 4 mg intravenously at the time of induction and ondansetron 4 mg intravenously at the end of surgery.", "sourceKey": "B"}, {"key": "C", "text": "Patient has a high risk of PONV; she should receive dexamethasone 4 mg intravenously at the time of induction and ondansetron 4 mg intravenously at the end of surgery.", "sourceKey": "C"}, {"key": "D", "text": "Patient has a low risk of PONV; she should receive ondansetron 4 mg intravenously at the end of surgery.", "sourceKey": "D"}], "answer": "A", "explanation": "According to the simplified Apfel risk score criteria, this patient has four risk factors for developing PONV (female sex, nonsmoker, history of motion sickness, and perioperative opioids). These risk factors place her at high risk of developing PONV, estimated at greater than 80% (Answers B and D are incorrect). Patients with a high risk of PONV should receive more than two pharmacologic interventions to prevent PONV (Answer A is correct; Answer C is incorrect).", "page": 36, "answerPage": 62, "stemZh": "27歲女性total abdominal hysterectomy，非吸菸、有motion sickness，預期volatile anesthetics與高劑量opioids；何種PONV預防最佳？", "optionsZh": [{"key": "A", "text": "High risk：前晚scopolamine patch、induction時dexamethasone4 mg IV、術末ondansetron4 mg IV"}, {"key": "B", "text": "Moderate risk：dexamethasone加ondansetron"}, {"key": "C", "text": "High risk：dexamethasone加ondansetron"}, {"key": "D", "text": "Low risk：術末ondansetron"}], "explanationZh": "女性、非吸菸、motion sickness及opioids形成high risk，適合三種不同機制的multimodal prophylaxis。", "contextZh": ""}, {"id": "13-case-07", "chapter": 13, "type": "case", "number": 7, "stem": "A 27-year-old man with a medical history of Crohn disease presents to your ED with frank bloody output from his rectum. The patient has hypotension (systolic blood pressure 85 mm Hg, MAP 58 mm Hg), and an NG lavage reveals “coffee-ground” material. The resident on call is in the process of calling the endoscopy team to help diagnose and intervene on an UGIB with an esophagogastroduodenoscopy. Which statement is most accurate regarding the care of this patient?", "context": "", "options": [{"key": "A", "text": "An endoscopy is the appropriate course of action but should not be performed until after initiation of PPI continuous infusion.", "sourceKey": "A"}, {"key": "B", "text": "A PPI continuous infusion should be initiated as soon as possible and continued for 48 hours post-endoscopy.", "sourceKey": "B"}, {"key": "C", "text": "The patient, who likely has a lower GI bleed, would benefit from a colonoscopy as opposed to an esophagogastroduodenoscopy.", "sourceKey": "C"}, {"key": "D", "text": "An endoscopy and a PPI continuous infusion should be initiated as soon as possible.", "sourceKey": "D"}], "answer": "D", "explanation": "Frank bloody output from the rectum is more indicative of a lower GI bleed than an UGIB. However, patients with a brisk UGIB may present with bright red blood per rectum. Although a lower GI bleed is more likely, the patient should be initiated on a PPI infusion and undergo an esophagogastroduodenoscopy as soon as possible (Answer D is correct). After the esophagogastroduodenoscopy, the patient should have a colonoscopy. The priority in this patient’s case is to evaluate for an UGIB because the finding of “coffee-ground” material on NG lavage suggests that the bleeding source is UGIB (Answer C is incorrect). Although previous guidelines recommended initiating PPIs before endoscopy, the most recent version does not recommend for or against this practice (Answer A is incorrect). High-dose PPIs should be continued for 48 hours after endoscopy and then followed by twice-daily treatment from days 4–14. (Answer B is incorrect).", "page": 42, "answerPage": 62, "stemZh": "27歲男性Crohn disease，血便、SBP85／MAP58，NG lavage為coffee-ground；準備EGD處理UGIB，何者最準確？", "optionsZh": [{"key": "A", "text": "PPI infusion開始後才可endoscopy"}, {"key": "B", "text": "立刻PPI且endoscopy後續48小時"}, {"key": "C", "text": "更可能LGIB，应colonoscopy"}, {"key": "D", "text": "儘速endoscopy及PPI infusion"}], "explanationZh": "Hemodynamic instability與coffee-ground提示UGIB，需迅速內視鏡及PPI，不應互相延誤。", "contextZh": ""}, {"id": "13-case-08", "chapter": 13, "type": "case", "number": 8, "stem": "A 23-year-old man (weight 80 kg) presents to the ED with an acute mental status change and a core body temperature of 94°F (34.4°C). He has a history of hypothyroidism, but according to his family, he had decided to stop taking all of his thyroid medications 1 week earlier. The team has given him a diagnosis of myxedema coma. Which is the most appropriate treatment option for this patient?", "context": "", "options": [{"key": "A", "text": "Intravenous levothyroxine 400 mcg  1 followed by 125 mcg daily.", "sourceKey": "A"}, {"key": "B", "text": "An insulin infusion titrated to a BG of 140–180 mg/dL.", "sourceKey": "B"}, {"key": "C", "text": "Propylthiouracil 200 mg every 4 hours.", "sourceKey": "C"}, {"key": "D", "text": "Propranolol 60 mg orally every 4 hours.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient, who presented with signs and symptoms of myxedema coma, was given this diagnosis by the treating team. Of the possible answers listed, only levothyroxine is appropriate for the treatment of myxedema coma (Answer A is correct). Insulin, propylthiouracil, and propranolol play no role in the treatment of myxedema coma (Answers B–D are incorrect).", "page": 53, "answerPage": 63, "stemZh": "23歲男性80 kg，停thyroid medications1週後意識改變、34.4°C，診斷myxedema coma；治療何者最適當？", "optionsZh": [{"key": "A", "text": "IV levothyroxine400 mcg一次，之後125 mcg daily"}, {"key": "B", "text": "Insulin infusion使BG140–180"}, {"key": "C", "text": "Propylthiouracil200 mg每4小時"}, {"key": "D", "text": "Propranolol60 mg口服每4小時"}], "explanationZh": "Myxedema coma需thyroid hormone replacement；本題IV levothyroxine為正確選項。", "contextZh": ""}, {"id": "14-self-01", "chapter": 14, "type": "self", "number": 1, "stem": "On rounds, you have a “checklist” of interventions that will benefit all critically ill patients in an intensive care unit (ICU). Which interventions would be most effective?", "context": "", "options": [{"key": "A", "text": "Initiate stress ulcer prophylaxis (SUP) in patients who are admitted to the ICU, and if appropriate, discontinue sedation.", "sourceKey": "A"}, {"key": "B", "text": "Initiate enteral nutrition, when appropriate, and mechanical venous thromboembolism (VTE) prophylaxis.", "sourceKey": "B"}, {"key": "C", "text": "If appropriate, initiate sedation interruption, and ensure that patients’ heads are elevated 45 degrees above the bed, if not contraindicated.", "sourceKey": "C"}, {"key": "D", "text": "Assess the need for VTE prophylaxis in patients admitted to the ICU, and initiate an insulin infusion to maintain a blood glucose of 120 mg/dL.", "sourceKey": "D"}], "answer": "C", "explanation": "The FAST-HUG mnemonic can serve as a checklist for every patient admitted to the ICU. Every patient should be assessed for a sedation interruption to minimize sedative exposure and maintain a light level of sedation (Answer C is correct). To decrease the risk of nosocomial pneumonia, each patient should have his or her head elevated 30–45 degrees above the head of the bed (Answer C is correct). Enteral nutrition should be initiated as soon as possible – typically, once the patient is stabilized; however, thromboprophylaxis should be initiated in every patient, using pharmacologic agents preferentially to mechanical prophylaxis (Answer B is incorrect). Stress ulcer prophylaxis should only be initiated in patients who have risk factors and should be discontinued once the risk factors no longer exist (Answer A is incorrect). Insulin infusions should be initiated only if blood glucose readings are not 140–180 mg/dL (Answer D is incorrect).", "page": 4, "answerPage": 38, "stemZh": "ICU rounds的共通照護checklist中，哪組介入最有效？", "optionsZh": [{"key": "A", "text": "所有ICU病人SUP，適當時停sedation"}, {"key": "B", "text": "適當時enteral nutrition與mechanical VTE prophylaxis"}, {"key": "C", "text": "適當時sedation interruption，若無contraindication抬高床頭45°"}, {"key": "D", "text": "評估VTE並用insulin使BG120"}], "explanationZh": "應評估sedation interruption並抬高床頭；SUP與glucose control須依風險而非一律套用。", "contextZh": ""}, {"id": "14-self-02", "chapter": 14, "type": "self", "number": 2, "stem": "Regarding pharmacologic prophylaxis for stressrelated mucosal injury, which is most appropriate?", "context": "", "options": [{"key": "A", "text": "Sucralfate neutralizes gastric pH.", "sourceKey": "A"}, {"key": "B", "text": "Proton pump inhibitors (PPIs) are superior to histamine-2 receptor antagonists (H 2 RAs) in preventing clinically significant bleeding.", "sourceKey": "B"}, {"key": "C", "text": "Tolerance will occur with continued H 2 RA administration.", "sourceKey": "C"}, {"key": "D", "text": "Antacids are effective when used up to three times daily.", "sourceKey": "D"}], "answer": "C", "explanation": "Sucralfate forms a protective barrier over the surface of the stomach, reducing exposure to acidic gastric contents; therefore, sucralfate does not affect gastric pH (Answer A is incorrect). Compared with H 2 RAs, PPIs appear more effective at reducing gastric acidity, but no well-conducted trial has shown PPIs superior in preventing clinically significant bleeding (Answer B is incorrect). Tolerance to any H 2 RA may occur, but not to PPIs (Answer C is correct). Antacids have some effect on reducing stress ulceration, provided the gastric pH is kept around 3.5, but frequent dosing (up to every 2 hours) is required to achieve this goal, making their use impractical (Answer D is incorrect).", "page": 4, "answerPage": 38, "stemZh": "關於stress-related mucosal injury的藥物預防，何者最適當？", "optionsZh": [{"key": "A", "text": "Sucralfate中和gastric pH"}, {"key": "B", "text": "PPI在clinically significant bleeding一定優於H2RA"}, {"key": "C", "text": "持續H2RA會產生tolerance"}, {"key": "D", "text": "Antacid一天最多3次即可有效"}], "explanationZh": "H2RA持續使用可產生tolerance。", "contextZh": ""}, {"id": "14-self-03", "chapter": 14, "type": "self", "number": 3, "stem": "A 66-year-old man is admitted to the ICU with abdominal pain, nausea, and altered mental status. He has a history of alcoholic cirrhosis, atrial fibrillation, chronic kidney diease, and erosive esophagitis. He is intubated and stabilized on the ventilator. A nasogastric tube (NGT) is placed, and the patient is tolerating enteral tube feedings. Which would be best to recommend for preventing stress-related bleeding?", "context": "", "options": [{"key": "A", "text": "Pantoprazole 40 mg intravenously twice daily.", "sourceKey": "A"}, {"key": "B", "text": "Ranitidine 50 mg intravenously three times daily.", "sourceKey": "B"}, {"key": "C", "text": "Famotidine 20 mg twice daily by NGT.", "sourceKey": "C"}, {"key": "D", "text": "Omeprazole suspension 20 mg once daily by NGT.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient has an indication for SUP (mechanical ventilation). He has an NGT in place and is tolerating tube feedings, indicating a functioning gut; therefore, intravenous therapy is not required (Answers A and B are incorrect). The patient has erosive esophagitis, for which a PPI will be more effective than an H 2 RA (Answer C is incorrect). Omeprazole suspension is effective in preventing SRMD; therefore, an omeprazole suspension would be most appropriate for this patient (Answer D is correct).", "page": 4, "answerPage": 38, "stemZh": "66歲男性有alcoholic cirrhosis、AF、CKD、erosive esophagitis；已intubation且耐受NGT feeding，何SUP最適當？", "optionsZh": [{"key": "A", "text": "Pantoprazole40 mg IV BID"}, {"key": "B", "text": "Ranitidine50 mg IV TID"}, {"key": "C", "text": "Famotidine20 mg NGT BID"}, {"key": "D", "text": "Omeprazole suspension20 mg NGT daily"}], "explanationZh": "可使用enteral route；原章選omeprazole20 mg daily，且不需renal adjustment。", "contextZh": ""}, {"id": "14-self-04", "chapter": 14, "type": "self", "number": 4, "stem": "A 51-year-old woman is admitted to the ICU for hypovolemic shock secondary to severe dehydration. She reports a 5-day history of diarrhea and malaise. She has no recent history of illnesses or contact with health care personnel. Her medical history includes hypothyroidism and gastroesophageal reflux disease. Her medications include levothyroxine 25 mcg orally daily and famotidine 20 mg orally at bedtime. Recently, her primary care physician changed famotidine to omeprazole 20 mg orally at bedtime for increased gastroesophageal reflux disease symptoms. While she is in the ICU, testing for Clostridioides (formerly Clostridium) difficile infection (CDI) returns positive. Which would be most appropriate regarding PPI use and CDI?", "context": "", "options": [{"key": "A", "text": "PPIs are a potential risk factor for CDI by producing hypochlorhydria and increasing the host susceptibility to infections.", "sourceKey": "A"}, {"key": "B", "text": "Prospective randomized controlled trials have shown that the risk of CDI is associated with PPI use.", "sourceKey": "B"}, {"key": "C", "text": "There is no association between PPI use and CDI risk.", "sourceKey": "C"}, {"key": "D", "text": "Studies reporting on CDI and PPI use have used the same definition of CDI and implemented the same infection control practices.", "sourceKey": "D"}], "answer": "A", "explanation": "Proton pump inhibitors are potent inhibitors of gastric acid production and are the drug of choice for gastroesophageal reflux disease. To date, the only prospective randomized controlled trial to evaluate CDI risk with PPI use found no difference between PPI and placebo; however, this was an underpowered secondary end point, and several cohort studies have found an association. (Answer C is incorrect). All published trials assessing the risk of CDI with PPI use have been limited by the inconsistent definitions of CDI and the variable infection control practices (Answer D is incorrect). Gastric juice is strongly bactericidal for microorganisms. Proton pump inhibitors are commonly used to increase the gastric pH; therefore, they act as a potential risk factor for CDI (Answer A is correct).", "page": 4, "answerPage": 38, "stemZh": "51歲女性因腹瀉dehydration造成hypovolemic shock，近期famotidine改omeprazole後CDI陽性；PPI與CDI何者最適當？", "optionsZh": [{"key": "A", "text": "PPI造成hypochlorhydria，可能增加CDI susceptibility"}, {"key": "B", "text": "Prospective RCT已證實PPI相關風險"}, {"key": "C", "text": "完全無關"}, {"key": "D", "text": "所有研究CDI定義與infection control均相同"}], "explanationZh": "PPI與CDI有觀察性關聯，可能透過hypochlorhydria增加感染風險；不代表RCT已證實因果。", "contextZh": ""}, {"id": "14-self-05", "chapter": 14, "type": "self", "number": 5, "stem": "A 50-year-old woman (weight 70 kg) is admitted to the ICU for worsening mental status. Her medical history is significant for hypertension, tobacco use, and osteoporosis. The next morning, she is intubated and stabilized on a ventilator. An NGT is placed. Her current medications include ceftriaxone 2 g intravenously every 12 hours, vancomycin 1250 mg intravenously every 12 hours, acyclovir 800 mg intravenously every 8 hours, famotidine 20 mg by NGT twice daily, and a bowel regimen. Serum creatinine (SCr) is normal. Which would be the most appropriate VTE prophylaxis for this patient?", "context": "", "options": [{"key": "A", "text": "Intermittent pneumatic compression devices.", "sourceKey": "A"}, {"key": "B", "text": "Enoxaparin 40 mg subcutaneously daily.", "sourceKey": "B"}, {"key": "C", "text": "Unfractionated heparin continuous infusion to maintain a therapeutic activated partial thromboplastin time (aPTT).", "sourceKey": "C"}, {"key": "D", "text": "No VTE prophylaxis at this time.", "sourceKey": "D"}], "answer": "B", "explanation": "Low-dose unfractionated heparin or low-molecularweight heparin should be initiated for VTE prophylaxis in a critically ill patient over no prophylaxis (Answer D is incorrect). Intermittent pneumatic compression devices would be insufficient prophylaxis in a patient with several risk factors for VTE (Answer A is incorrect). A continuous infusion of heparin is inappropriate for preventing VTE (Answer C is incorrect). Enoxaparin may be used for VTE prophylaxis in a critically ill patient with stable renal function (Answer B is correct).", "page": 5, "answerPage": 38, "stemZh": "50歲女性70 kg因mental status惡化intubation；用ceftriaxone、vancomycin、acyclovir及famotidine，SCr正常；VTE prophylaxis何者最適當？", "optionsZh": [{"key": "A", "text": "Intermittent pneumatic compression"}, {"key": "B", "text": "Enoxaparin40 mg SC daily"}, {"key": "C", "text": "UFH infusion至therapeutic aPTT"}, {"key": "D", "text": "目前不預防"}], "explanationZh": "無明顯bleeding contraindication且renal function正常，可用enoxaparin40 mg daily。", "contextZh": ""}, {"id": "14-self-06", "chapter": 14, "type": "self", "number": 6, "stem": "A 34-year-old woman (weight 65 kg) is admitted to the ICU with several upper extremity fractures, a closed-head injury, and a grade 4 liver laceration after a motor vehicle crash. Her medical history is nonsignificant. She is admitted to the ICU on a ventilator after surgery. Her current laboratory values are as follows: sodium (Na) 145 mEq/L, potassium (K) 3.1 mEq/L, chloride 97 mEq/L, carbon dioxide 18 mEq/L, blood urea nitrogen (BUN) 70 mg/ dL, and SCr 3.5 mg/dL. Which would be the most appropriate VTE prophylaxis on the day of admission for this patient?", "context": "", "options": [{"key": "A", "text": "Provide intermittent pneumatic compression devices.", "sourceKey": "A"}, {"key": "B", "text": "Give dalteparin 5000 units subcutaneously daily.", "sourceKey": "B"}, {"key": "C", "text": "Give fondaparinux 2.5 mg subcutaneously daily.", "sourceKey": "C"}, {"key": "D", "text": "No VTE prophylaxis is indicated at this time.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient had a closed-head injury, placing her at high risk of VTE (Answer D is incorrect). She is at high risk of major bleeding and acute kidney injury; therefore, a low-molecular-weight heparin or a factor Xa inhibitor would not be best for her (Answers B and C are incorrect). Mechanical prophylaxis with intermittent pneumatic compression devices is preferred to no prophylaxis in the absence of lower-extremity injury until the bleeding risk is no longer present (Answer A is correct).", "page": 5, "answerPage": 38, "stemZh": "34歲女性65 kg，車禍後多處fractures、closed-head injury、grade4 liver laceration，術後MV；BUN70、SCr3.5，入院當天VTE prophylaxis何者最好？", "optionsZh": [{"key": "A", "text": "Intermittent pneumatic compression"}, {"key": "B", "text": "Dalteparin5000 units SC daily"}, {"key": "C", "text": "Fondaparinux2.5 mg SC daily"}, {"key": "D", "text": "不需要任何預防"}], "explanationZh": "有重大bleeding risk時先mechanical prophylaxis，非完全不預防。", "contextZh": ""}, {"id": "14-self-07", "chapter": 14, "type": "self", "number": 7, "stem": "A 34-year-old man (weight 70 kg) is admitted to the surgical ICU for acute respiratory failure from pancreatitis. He has no pertinent medical history. His current medications include norepinephrine at 0.07 mcg/kg/minute, dexmedetomidine at 0.7 mcg/kg/ hour, ampicillin/sulbactam 3 g intravenously every 6 hours, famotidine 20 mg intravenously twice daily, and heparin 5000 units subcutaneously three times daily. On day 3 of his ICU admission, the team suspects heparin-induced thrombocytopenia (HIT). His platelet count (Plt) was 360,000/mm3 on admission and is 180,000/mm3 today. The 4Ts score is used to determine the probability of HIT. The score is calculated as 3 equals low risk. The team would like to send the heparin–platelet factor 4 (PF4) immunoassay and initiate argatroban. Which is the most appropriate response?", "context": "", "options": [{"key": "A", "text": "Discontinue all heparin products, but do not initiate argatroban.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue all heparin products, and initiate argatroban.", "sourceKey": "B"}, {"key": "C", "text": "Send the heparin-PF4 immunoassay, and continue low-dose unfractionated heparin until the results return.", "sourceKey": "C"}, {"key": "D", "text": "Do not send the heparin-PF4 immunoassay, and continue low-dose unfractionated heparin.", "sourceKey": "D"}], "answer": "D", "explanation": "Clinical assessment is essential in diagnosing HIT because of the immediate need for treatment and the delay in laboratory testing. Although this patient’s Plt did decrease by 50%, the characteristic onset of the Plt decrease in HIT is 5–10 days after heparin initiation. Clinical prediction rules to help determine the probability of HIT (e.g., 4Ts score) have been developed. Patients with a low 4Ts score (0–3) have a very low probability of HIT (Answer D is correct). Direct thrombin inhibitors are the agents of choice for anticoagulation in acute HIT because they have no cross-reactivity with heparin. Initiating these agents in those with a low probability of HIT could lead to an unnecessary increase in bleeding risk (Answer B is incorrect). If the 4T score revealed an intermediate or high risk of HIT, the first step would be to ensure that all forms of heparin are discontinued, including flushes and heparin-coated catheters (Answer C is incorrect). The next step would be to initiate an alternative form of anticoagulation (Answer A is incorrect).", "page": 5, "answerPage": 38, "stemZh": "34歲男性用heparin預防，ICU第3天Plt由360000降至180000；4Ts=3低風險，團隊想送PF4並給argatroban，何建議最好？", "optionsZh": [{"key": "A", "text": "停所有heparin但不給argatroban"}, {"key": "B", "text": "停所有heparin且給argatroban"}, {"key": "C", "text": "送PF4，結果回來前繼續低劑量UFH"}, {"key": "D", "text": "不送PF4並繼續低劑量heparin"}], "explanationZh": "低4Ts有高度negative predictive value，不宜不必要檢驗或empiric non-heparin anticoagulation。", "contextZh": ""}, {"id": "14-self-08", "chapter": 14, "type": "self", "number": 8, "stem": "Which would be the most important group of considerations in a critically ill patient approaching the end of life?", "context": "", "options": [{"key": "A", "text": "Pain management, tight glucose management, and control of secretions.", "sourceKey": "A"}, {"key": "B", "text": "Routine vital sign checks, discontinuation of unnecessary medications, and control of secretions.", "sourceKey": "B"}, {"key": "C", "text": "Pain management, control of secretions, and discontinuation of unnecessary medications.", "sourceKey": "C"}, {"key": "D", "text": "Discontinuation of unnecessary medications, insertion of a Foley catheter, and treatment of nausea and vomiting.", "sourceKey": "D"}], "answer": "C", "explanation": "General considerations in the critically ill patient at the end of life include minimizing uncomfortable or unnecessary procedures, tests, and treatments, including fingersticks, Foley catheters, and routine vital signs (Answers A, B, and D are incorrect). Symptom management of pain and anxiety, fever, cough, secretions, nausea and vomiting, and delirium should be considered in the dying patient (Answer C is correct).", "page": 5, "answerPage": 39, "stemZh": "End of life的critically ill patient，最重要的考量組合為何？", "optionsZh": [{"key": "A", "text": "Pain management、tight glucose control、secretion control"}, {"key": "B", "text": "例行vital signs、停不必要藥、secretion control"}, {"key": "C", "text": "Pain management、secretion control、停不必要藥"}, {"key": "D", "text": "停不必要藥、Foley catheter、nausea及vomiting治療"}], "explanationZh": "以舒適為目標，優先疼痛、分泌物控制與移除無益藥物。", "contextZh": ""}, {"id": "14-case-01", "chapter": 14, "type": "case", "number": 1, "stem": "A 68-year-old man (weight 85 kg) is admitted to the ICU for the management of severe hypoxemic respiratory failure associated with community-acquired pneumonia. He is endotracheally intubated and placed on mechanical ventilation. His medical history consists of Child-Pugh class B cirrhosis secondary to alcohol abuse, heart failure, and myocardial infarction. His laboratory values show white blood cell count (WBC) 15 x 103 cells/mm3, Plt 150,000/mm3, BUN 15 mg/dL, SCr 1.1 mg/dL, K 4.5 mEq/L, international normalized ratio (INR) 1.0, aspartate aminotransferase (AST) 58 IU/mL, and alanine aminotransferase (ALT) 49 IU/mL. His current medications include azithromycin 500 mg intravenously daily, ceftriaxone 1 g intravenously daily, vancomycin 1250 mg intravenously every 12 hours, heparin 5000 units subcutaneously every 8 hours, fentanyl drip at 50 mcg/hour titrated to CPOT less than 2, midazolam drip at 1 mg/hour titrated to a Richmond Agitation-Sedation Scale (RASS) of 0 to -1, and a regular insulin drip at 1.5 units/hour titrated to maintain blood glucose at 140–180 mg/dL. Currently, on day 3 of his ICU stay, the patient’s head is 30 degrees above the bed, his RASS is documented as -4, he is on minimal ventilator settings, and an NGT is placed. As the clinical pharmacist rounding on this patient, you go through the FAST-HUG mnemonic. Which are the best recommendations for the team?", "context": "", "options": [{"key": "A", "text": "Initiate enteral nutrition by NGT, add SUP, and discontinue fentanyl and midazolam drips.", "sourceKey": "A"}, {"key": "B", "text": "Initiate enteral nutrition by NGT, discontinue deep venous thrombosis (DVT) prophylaxis, and transition the insulin drip to sliding scale.", "sourceKey": "B"}, {"key": "C", "text": "Transition the insulin drip to sliding scale, add SUP, and discontinue fentanyl and midazolam drips.", "sourceKey": "C"}, {"key": "D", "text": "Discontinue fentanyl and midazolam drips, discontinue DVT prophylaxis, and add SUP.", "sourceKey": "D"}], "answer": "A", "explanation": "The mnemonic FAST-HUG stands for Feeding, Analgesia, Sedation, Thromboembolic prophylaxis, Head of bed elevation, stress Ulcer prophylaxis, and Glycemic control. Using this mnemonic as a checklist every day for each critically ill patient will help maximize therapeutic interventions and promote patient safety. This patient would benefit from receiving enteral nutrition (an NGT is already placed and he has a working GI tract), interrupting the sedative (current RASS score is above the designated goal), and adding SUP (risk factors include mechanical ventilation) (Answer A is correct). Critically ill patients with risk factors for VTE should remain on VTE prophylaxis (Answers B and D are incorrect); moreover, sliding-scale insulin should be initiated when the patient is not critically ill, adding another reason why Answer B is incorrect and making Answer C incorrect.", "page": 9, "answerPage": 36, "stemZh": "68歲男性CAP伴respiratory failure，已MV；ICU第3天RASS−4、minimal ventilator settings且NGT已置放，fentanyl及midazolam持續輸注。依FAST-HUG何組建議最佳？", "optionsZh": [{"key": "A", "text": "開始NGT enteral nutrition、加SUP、停fentanyl及midazolam"}, {"key": "B", "text": "開始nutrition、停DVT預防、insulin改sliding scale"}, {"key": "C", "text": "Insulin改sliding scale、加SUP、停fentanyl及midazolam"}, {"key": "D", "text": "停fentanyl及midazolam、停DVT預防、加SUP"}], "explanationZh": "可開始enteral nutrition及SUP，過深sedation需中斷評估；無理由停VTE prophylaxis。", "contextZh": ""}, {"id": "14-case-02", "chapter": 14, "type": "case", "number": 2, "stem": "Which best reflects this patient’s risk factors for stress-related bleeding?", "context": "A 45-year-old woman is admitted to the ICU for severe respiratory failure from community-acquired pneumonia. She is endotracheally intubated and placed on mechanical ventilation. An NGT is placed to begin enteral nutrition. Three days later, she is receiving norepinephrine and vasopressin infusions and appropriate antimicrobial agents. Her WBC is 20 x 103 cells/mm3, Plt 45,000/mm3, BUN 70 mg/dL, SCr 4.5 mg/dL (baseline 0.9 mg/ dL), K 4.5 mEq/L, INR 1.4, AST 30 IU/mL, and ALT 46 IU/mL.", "options": [{"key": "A", "text": "Mechanical ventilation.", "sourceKey": "A"}, {"key": "B", "text": "Mechanical ventilation, coagulopathy, and acute kidney injury.", "sourceKey": "B"}, {"key": "C", "text": "Mechanical ventilation, coagulopathy, acute kidney injury, and shock.", "sourceKey": "C"}, {"key": "D", "text": "Mechanical ventilation, coagulopathy, acute kidney injury, shock, and enteral nutrition.", "sourceKey": "D"}], "answer": "C", "explanation": "Two independent risk factors for SRMD are respiratory failure requiring mechanical ventilation for 48 hours or longer and coagulopathy (Plt less than 50,000/mm3, INR greater than 1.5, or aPTT greater than 2 times the control). This patient has both of these risk factors. In addition, she has septic shock, as evidenced by endorgan dysfunction and acute kidney injury (Answer C is correct). Answers A, B, and D are incorrect because this patient has four risk factors for developing stress-related mucosal damage.", "page": 17, "answerPage": 36, "stemZh": "依共同病例，病人的stress-related bleeding風險因子有哪些？", "optionsZh": [{"key": "A", "text": "MV"}, {"key": "B", "text": "MV、coagulopathy、AKI"}, {"key": "C", "text": "MV、coagulopathy、AKI、shock"}, {"key": "D", "text": "前述加enteral nutrition"}], "explanationZh": "MV、低platelets／coagulopathy、AKI及shock增加風險；enteral nutrition不是風險因子。", "contextZh": "45歲女性因CAP造成severe respiratory failure，已intubation／MV及NGT feeding。3天後使用norepinephrine、vasopressin及合適antimicrobials；WBC20×10³、Plt45000、BUN70、SCr4.5（baseline0.9）、K4.5、INR1.4、AST30、ALT46。"}, {"id": "14-case-03", "chapter": 14, "type": "case", "number": 3, "stem": "Which would be most appropriate for preventing stress-related bleeding?", "context": "A 45-year-old woman is admitted to the ICU for severe respiratory failure from community-acquired pneumonia. She is endotracheally intubated and placed on mechanical ventilation. An NGT is placed to begin enteral nutrition. Three days later, she is receiving norepinephrine and vasopressin infusions and appropriate antimicrobial agents. Her WBC is 20 x 103 cells/mm3, Plt 45,000/mm3, BUN 70 mg/dL, SCr 4.5 mg/dL (baseline 0.9 mg/ dL), K 4.5 mEq/L, INR 1.4, AST 30 IU/mL, and ALT 46 IU/mL.", "options": [{"key": "A", "text": "Sucralfate 1 g four times daily by NGT.", "sourceKey": "A"}, {"key": "B", "text": "Magnesium hydroxide 30 mL every 4 hours by NGT.", "sourceKey": "B"}, {"key": "C", "text": "Pantoprazole 40 mg intravenously twice daily.", "sourceKey": "C"}, {"key": "D", "text": "Famotidine 20 mg intravenously daily.", "sourceKey": "D"}], "answer": "D", "explanation": "Antacids are not recommended for routine use because of their frequency of administration, adverse effects, and interactions (Answer B is incorrect). In a large randomized controlled trial, sucralfate was inferior to H 2 RAs in preventing clinically significant bleeding from SRMD and is generally not recommended because of its adverse effect profile (Answer A is incorrect). Proton pump inhibitors are no better than H 2 RAs in preventing SRMD and are associated with increased infectious complications, including pneumonia and CDI (Answer D is correct). Meta-analyses have favored PPIs to H 2 RAs for GI bleeding; however, the individual trials included lacked methodological quality (Answer C is incorrect).", "page": 17, "answerPage": 36, "stemZh": "共同病例最適當的stress-related bleeding預防為何？", "optionsZh": [{"key": "A", "text": "Sucralfate1 g NGT QID"}, {"key": "B", "text": "Magnesium hydroxide30 mL NGT每4小時"}, {"key": "C", "text": "Pantoprazole40 mg IV BID"}, {"key": "D", "text": "Famotidine20 mg IV daily"}], "explanationZh": "Famotidine低劑量適合此病人的renal dysfunction；其他方案不適當或劑量過高。", "contextZh": "45歲女性因CAP造成severe respiratory failure，已intubation／MV及NGT feeding。3天後使用norepinephrine、vasopressin及合適antimicrobials；WBC20×10³、Plt45000、BUN70、SCr4.5（baseline0.9）、K4.5、INR1.4、AST30、ALT46。"}, {"id": "14-case-04", "chapter": 14, "type": "case", "number": 4, "stem": "One week later, the patient’s respiratory status has greatly improved. She has been off sedation and vasopressors for the past 4 days, working with physical therapy, and is now extubated. Her only medications include ceftriaxone, heparin subcutaneously, and SUP. Her current laboratory values are as follows: WBC 6 x 103 cells/mm3, Plt 256,000/mm3, BUN 10 mg/dL, SCr 1.1 mg/dL, K 4.0 mEq/L, INR 0.8, AST 15 IU/mL, and ALT 10 IU/mL. Which would be the most appropriate recommendation regarding this patient’s SUP regimen?", "context": "A 45-year-old woman is admitted to the ICU for severe respiratory failure from community-acquired pneumonia. She is endotracheally intubated and placed on mechanical ventilation. An NGT is placed to begin enteral nutrition. Three days later, she is receiving norepinephrine and vasopressin infusions and appropriate antimicrobial agents. Her WBC is 20 x 103 cells/mm3, Plt 45,000/mm3, BUN 70 mg/dL, SCr 4.5 mg/dL (baseline 0.9 mg/ dL), K 4.5 mEq/L, INR 1.4, AST 30 IU/mL, and ALT 46 IU/mL.", "options": [{"key": "A", "text": "SUP should be continued until hospital discharge.", "sourceKey": "A"}, {"key": "B", "text": "SUP should be continued until ICU discharge.", "sourceKey": "B"}, {"key": "C", "text": "SUP should be discontinued now.", "sourceKey": "C"}, {"key": "D", "text": "SUP should be discontinued once the patient is off antimicrobials.", "sourceKey": "D"}], "answer": "C", "explanation": "Once the risk factors are no longer present, SUP should promptly be discontinued (Answer C is correct). This patient no longer has risk factors (mechanical ventilation, coagulopathy acute kidney failure, and severe sepsis). In addition, there is no evidence that SUP should be continued until hospital or ICU discharge or when antimicrobial therapy is complete (Answers A, B, and D are incorrect).", "page": 17, "answerPage": 36, "stemZh": "一週後已extubation且停sedation與vasopressor4天，SCr1.1、Plt256000、INR0.8；目前ceftriaxone、SC heparin及SUP，如何處理SUP？", "optionsZh": [{"key": "A", "text": "用到出院"}, {"key": "B", "text": "用到離開ICU"}, {"key": "C", "text": "現在停用"}, {"key": "D", "text": "停antimicrobials後才停"}], "explanationZh": "原有主要bleeding風險已消失，應停止不必要SUP。", "contextZh": "45歲女性因CAP造成severe respiratory failure，已intubation／MV及NGT feeding。3天後使用norepinephrine、vasopressin及合適antimicrobials；WBC20×10³、Plt45000、BUN70、SCr4.5（baseline0.9）、K4.5、INR1.4、AST30、ALT46。"}, {"id": "14-case-05", "chapter": 14, "type": "case", "number": 5, "stem": "A 93-year-old man (weight 45 kg) confined to his bed is admitted from a nursing home with a chronic obstructive pulmonary disease exacerbation requiring mechanical ventilation. He has a history of diabetes and heart failure. His laboratory values are all within normal limits except for BUN 35 mg/dL and SCr 2.8 mg/dL (baseline 0.5). Which would be the most appropriate recommendation for VTE prophylaxis in this patient?", "context": "", "options": [{"key": "A", "text": "Intermittent pneumatic compression devices.", "sourceKey": "A"}, {"key": "B", "text": "Enoxaparin 30 mg subcutaneously once daily.", "sourceKey": "B"}, {"key": "C", "text": "Heparin 5000 units subcutaneously twice daily.", "sourceKey": "C"}, {"key": "D", "text": "Fondaparinux 2.5 mg subcutaneously daily.", "sourceKey": "D"}], "answer": "C", "explanation": "This patient has several risk factors for VTE, including immobility and respiratory failure, making heparin 5000 units subcutaneously twice daily appropriate for VTE prophylaxis (Answer C is correct). Neither enoxaparin nor fondaparinux is appropriate for this patient, who has acute kidney injury with an estimated CrCl of less than 20 mL/minute/1.73 m2 (Answers B and D are incorrect). Additionally, VTE prophylaxis with fondaparinux is contraindicated in patients less than 50 kg. Intermittent pneumatic compression would be insufficient in a patient with no contraindication to pharmacologic prophylaxis (Answer A is incorrect).", "page": 25, "answerPage": 36, "stemZh": "93歲男性45 kg，bedbound且COPD需MV，有diabetes及HF；BUN35、SCr2.8（baseline0.5），VTE預防何者最適當？", "optionsZh": [{"key": "A", "text": "Intermittent pneumatic compression"}, {"key": "B", "text": "Enoxaparin30 mg SC daily"}, {"key": "C", "text": "Heparin5000 units SC BID"}, {"key": "D", "text": "Fondaparinux2.5 mg SC daily"}], "explanationZh": "Severe renal dysfunction時UFH較易使用；高齡低體重可選5000 units BID。", "contextZh": ""}, {"id": "14-case-06", "chapter": 14, "type": "case", "number": 6, "stem": "Which would be the best course of action?", "context": "A 55-year-old man (weight 60 kg) with a medical history of diabetes, hyperlipidemia, and a DVT 4 months ago secondary to lower-extremity trauma is admitted today to the ICU for acute respiratory failure from influenza virus. His current laboratory values are as follows: WBC 13.1 x 103 cells/mm3, Plt 250,000/mm3, BUN 13 mg/dL, SCr 0.9 mg/dL, INR 1.2, AST 22 IU/mL, and ALT 11 IU/mL. His current medication regimen includes fentanyl and midazolam boluses for pain and agitation, piperacillin/tazobactam, vancomycin, regular insulin infusion, SUP, and a heparin drip. Five days later, the patient remains intubated on the same medications. At this time, his Plt has decreased to 112,000/mm3, and his BUN and SCr have increased to 45 mg/dL and 2.7 mg/dL, respectively. The team sends a heparin-PF4 immunoassay; however, the results will not return for 48 hours.", "options": [{"key": "A", "text": "Discontinue the heparin drip, and initiate an argatroban continuous infusion at 0.25 mcg/kg/minute.", "sourceKey": "A"}, {"key": "B", "text": "Do nothing because the patient has several other reasons to be thrombocytopenic.", "sourceKey": "B"}, {"key": "C", "text": "Discontinue the heparin drip, and initiate fondaparinux at 10 mg subcutaneously daily.", "sourceKey": "C"}, {"key": "D", "text": "Do nothing until the heparin-PF4 immunoassay results return.", "sourceKey": "D"}], "answer": "A", "explanation": "Diagnosing HIT is difficult in a critically ill patient because there are many alternative causes of thrombocytopenia. Clinical assessment is essential in diagnosing HIT because of the immediate need for treatment and the delay in laboratory testing (Answers B and D are incorrect). Clinically, this patient has had a greater than 50% decrease in Plt within 5 days of receiving heparin. The calculated 4Ts score is 5 (2 points for Plt decrease by greater than 50%, 2 points for a clear onset at days 5–10, and 1 point for other possible causes of thrombocytopenia. This score is an intermediate probability for HIT. In managing suspected HIT, first ensure that all forms of heparin are discontinued, including flushes and heparin-coated catheters. Next, initiate an alternative form of anticoagulation. Direct thrombin inhibitors are the agents of choice for anticoagulation in acute HIT because they have no cross-reactivity with heparin (Answer A is correct). Factor Xa inhibitors have been used to manage HIT; however, they would not be best in this patient, who has acute kidney injury (Answer C is incorrect).", "page": 25, "answerPage": 36, "stemZh": "共同病例疑似HIT，PF4結果需48小時才回報；何處置最適當？", "optionsZh": [{"key": "A", "text": "停heparin drip，argatroban0.25 mcg/kg/min infusion"}, {"key": "B", "text": "因其他thrombocytopenia原因而不處理"}, {"key": "C", "text": "停heparin，fondaparinux10 mg SC daily"}, {"key": "D", "text": "等PF4結果再處理"}], "explanationZh": "臨床HIT疑慮足夠時應立即停heparin並開始適當non-heparin anticoagulant；renal dysfunction支持argatroban。", "contextZh": "55歲男性60 kg，有diabetes、hyperlipidemia及4個月前trauma-related DVT，因influenza respiratory failure入住ICU。原Plt250000、BUN13、SCr0.9、INR1.2、AST22、ALT11。使用fentanyl及midazolam bolus、piperacillin/tazobactam、vancomycin、insulin infusion、SUP及heparin drip。5天後仍intubation且用藥相同，Plt降至112000、BUN45、SCr2.7；heparin-PF4結果要48小時。"}, {"id": "14-case-07", "chapter": 14, "type": "case", "number": 7, "stem": "Three days later, both the heparin-PF4 immunoassay and the serotonin release assay return positive, and the patient has a new DVT. The team wants to initiate warfarin. The patient’s current Plt is 130,000/mm3. Which would be the most appropriate response?", "context": "A 55-year-old man (weight 60 kg) with a medical history of diabetes, hyperlipidemia, and a DVT 4 months ago secondary to lower-extremity trauma is admitted today to the ICU for acute respiratory failure from influenza virus. His current laboratory values are as follows: WBC 13.1 x 103 cells/mm3, Plt 250,000/mm3, BUN 13 mg/dL, SCr 0.9 mg/dL, INR 1.2, AST 22 IU/mL, and ALT 11 IU/mL. His current medication regimen includes fentanyl and midazolam boluses for pain and agitation, piperacillin/tazobactam, vancomycin, regular insulin infusion, SUP, and a heparin drip. Five days later, the patient remains intubated on the same medications. At this time, his Plt has decreased to 112,000/mm3, and his BUN and SCr have increased to 45 mg/dL and 2.7 mg/dL, respectively. The team sends a heparin-PF4 immunoassay; however, the results will not return for 48 hours.", "options": [{"key": "A", "text": "Discontinue argatroban and initiate warfarin at 5 mg orally daily.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue argatroban and initiate warfarin at 10 mg orally daily.", "sourceKey": "B"}, {"key": "C", "text": "Warfarin should never be used in patients with HIT.", "sourceKey": "C"}, {"key": "D", "text": "Warfarin should not be initiated right now.", "sourceKey": "D"}], "answer": "D", "explanation": "Warfarin can be initiated (Answer C is incorrect) once the Plt has recovered to at least 150,000/mm3 and after at least 5 days of therapy with an alternative anticoagulant (Answer D is correct). Because this patient’s Plts have not reached 150,000/mm3 and only 3 days of argatroban have been completed, warfarin therapy should not be initiated at this time (Answers A and B are incorrect). Argatroban should be continued, and warfarin may be considered at low doses (maximum 5 mg) as the Plt continues to recover (Answer B is incorrect).", "page": 25, "answerPage": 37, "stemZh": "3天後PF4及serotonin release assay陽性，且新增DVT；Plt130000，團隊想給warfarin，何建議最好？", "optionsZh": [{"key": "A", "text": "停argatroban，warfarin5 mg daily"}, {"key": "B", "text": "停argatroban，warfarin10 mg daily"}, {"key": "C", "text": "HIT永遠不能warfarin"}, {"key": "D", "text": "現在不應開始warfarin"}], "explanationZh": "Acute HIT時須等platelet recovery後才開始warfarin，以免venous limb gangrene等風險。", "contextZh": "55歲男性60 kg，有diabetes、hyperlipidemia及4個月前trauma-related DVT，因influenza respiratory failure入住ICU。原Plt250000、BUN13、SCr0.9、INR1.2、AST22、ALT11。使用fentanyl及midazolam bolus、piperacillin/tazobactam、vancomycin、insulin infusion、SUP及heparin drip。5天後仍intubation且用藥相同，Plt降至112000、BUN45、SCr2.7；heparin-PF4結果要48小時。"}, {"id": "14-case-08", "chapter": 14, "type": "case", "number": 8, "stem": "An 88-year-old woman is admitted to the ICU for decompensated heart failure, acute kidney injury, and uncontrollable pain from the rib fractures she had 1 month ago from a fall. This is her fourth admission to the ICU in the past 5 months. Speaking with her, you find that she wishes not to be resuscitated or intubated but only to be comfortable. Her blood pressure is currently 119/70 mm Hg, heart rate 120 beats/ minute, and respiratory rate 55 breaths/minute. Her pain is 9/10 using the BPS. In a meeting with the patient’s family, all members agree that they do not want to see her suffer any longer. It is decided to initiate a morphine drip at 2 mg/hour. Titration parameters include giving a bolus dose equivalent to the current rate and increasing the infusion by 25% to maintain a score of 3 (no pain) using the BPS. Her laboratory values are all within normal limits, including BUN 10 mg/dL and SCr 0.6 mg/dL. The nurse taking care of the patient believes that the titration parameters are too aggressive. Which would be the most appropriate change in titration parameters?", "context": "", "options": [{"key": "A", "text": "Change the parameters to increase the morphine drip when the patient has signs of discomfort, such as an increase in blood pressure or heart rate.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue titration parameters, keeping the morphine infusion at the current rate.", "sourceKey": "B"}, {"key": "C", "text": "Discontinue titration parameters, keeping the morphine infusion at the current rate and adding a midazolam infusion at 2 mg/hour.", "sourceKey": "C"}, {"key": "D", "text": "Do not change the titration parameters at this time; however, assess the patient’s response after the first dose increase.", "sourceKey": "D"}], "answer": "D", "explanation": "Up to 50% of seriously ill hospitalized patients have moderate or severe pain. Opioids are the treatment mainstay for patients with pain and dyspnea at the end of life. Assessing pain in the ICU can be particularly challenging because many patients have impaired cognition and communication. Vital signs alone should not be used for pain assessment (Answer A is incorrect). Evidence suggests that pain can be improved with correct dosing and titration (Answers B and C are incorrect) without causing respiratory depression or hastening death (Answer D is correct).", "page": 28, "answerPage": 37, "stemZh": "88歲女性end-of-life舒適照護，pain9/10；morphine2 mg/hour，依BPS目標3，以目前輸注速率等量bolus並增加25%。SCr0.6，護理師疑慮太積極，何調整最適當？", "optionsZh": [{"key": "A", "text": "只依BP／HR上升才加morphine"}, {"key": "B", "text": "取消titration維持原速率"}, {"key": "C", "text": "取消titration且加midazolam2 mg/hour"}, {"key": "D", "text": "先不改，但首次加量後評估反應"}], "explanationZh": "應依症狀與validated pain assessment調整；先評估第一次加量反應，勿無理由限制comfort care。", "contextZh": ""}, {"id": "15-self-01", "chapter": 15, "type": "self", "number": 1, "stem": "Which clinical symptoms and physiologic variables most likely indicate that this patient has a shock syndrome?", "context": "An 80-year-old woman presents to the intensive care unit (ICU) with septic shock caused by an Escherichia coli urinary tract infection. Pertinent vital signs on admission are as follows: blood pressure 80/40 mm Hg, heart rate 155 beats/minute with a rhythm of atrial fibrillation, respiratory rate 26 breaths/minute, and temperature 105.8°F (41°C). On physical examination, the patient is weak, lethargic, and confused. Pertinent laboratory values are as follows: sodium (Na) 155 mEq/L, potassium (K) 3.6 mEq/L, serum creatinine (SCr) 1.8 mg/dL, and lactate 4.2 mmol/L.", "options": [{"key": "A", "text": "Fever, lethargy, and tachycardia.", "sourceKey": "A"}, {"key": "B", "text": "Hypotension, fever, and tachypnea.", "sourceKey": "B"}, {"key": "C", "text": "Hypotension, confusion, and hyperlactatemia.", "sourceKey": "C"}, {"key": "D", "text": "Tachypnea, fever, and hyperlactatemia.", "sourceKey": "D"}], "answer": "C", "explanation": "This older adult patient presents with septic shock. Shock is a syndrome of impaired Do2 , leading to tissue injury and end-organ failure. In this case, it is important to realize that fever is a symptom of an inflammatory syndrome, not a shock syndrome (Answers A, B, and D are incorrect). This patient’s presentation with hypotension, confusion, and hyperlactatemia suggests the presence of a shock syndrome in the setting of impaired Do2 (Answer C is correct).", "page": 4, "answerPage": 62, "stemZh": "哪些症狀及physiologic variables最支持shock syndrome？", "optionsZh": [{"key": "A", "text": "Fever、lethargy、tachycardia"}, {"key": "B", "text": "Hypotension、fever、tachypnea"}, {"key": "C", "text": "Hypotension、confusion、hyperlactatemia"}, {"key": "D", "text": "Tachypnea、fever、hyperlactatemia"}], "explanationZh": "低血壓、意識改變與高lactate代表灌流不足，較直接支持shock。", "contextZh": "80歲女性因E.coli UTI造成septic shock：BP80/40、AF HR155、RR26、41°C，虛弱、lethargy及confusion。Na155、K3.6、SCr1.8、lactate4.2 mmol/L。"}, {"id": "15-self-02", "chapter": 15, "type": "self", "number": 2, "stem": "Which variable is most likely contributing to impaired oxygen delivery (Do2 ) to the patient’s end organs?", "context": "An 80-year-old woman presents to the intensive care unit (ICU) with septic shock caused by an Escherichia coli urinary tract infection. Pertinent vital signs on admission are as follows: blood pressure 80/40 mm Hg, heart rate 155 beats/minute with a rhythm of atrial fibrillation, respiratory rate 26 breaths/minute, and temperature 105.8°F (41°C). On physical examination, the patient is weak, lethargic, and confused. Pertinent laboratory values are as follows: sodium (Na) 155 mEq/L, potassium (K) 3.6 mEq/L, serum creatinine (SCr) 1.8 mg/dL, and lactate 4.2 mmol/L.", "options": [{"key": "A", "text": "Serum lactate.", "sourceKey": "A"}, {"key": "B", "text": "Atrial fibrillation.", "sourceKey": "B"}, {"key": "C", "text": "Acute kidney injury.", "sourceKey": "C"}, {"key": "D", "text": "Fever.", "sourceKey": "D"}], "answer": "B", "explanation": "The Fick equation for Do2 best shows Do2 . According to this equation, Do2 depends on CO and Cao2 . Cardiac output depends on heart rate and SV. Typically, an elevated heart rate will increase CO and Do2 . However, if a patient has atrial fibrillation, ventricular filling is impaired and SV is decreased, causing a decrease in CO and Do2 (Answer B is correct). Lactate does not impede Do2 but is a byproduct of impaired Do2 (Answer A is incorrect). Similarly, Do2 is not impaired by acute kidney injury (Answer C is incorrect). Finally, fever is an inflammatory response that increases Vo2 but does not impair Do2 (Answer D is incorrect).", "page": 4, "answerPage": 62, "stemZh": "哪項最可能造成這位病人end-organ oxygen delivery（DO2）不足？", "optionsZh": [{"key": "A", "text": "Serum lactate"}, {"key": "B", "text": "AF"}, {"key": "C", "text": "AKI"}, {"key": "D", "text": "Fever"}], "explanationZh": "AF with rapid rate可降低有效cardiac output，影響oxygen delivery。", "contextZh": "80歲女性因E.coli UTI造成septic shock：BP80/40、AF HR155、RR26、41°C，虛弱、lethargy及confusion。Na155、K3.6、SCr1.8、lactate4.2 mmol/L。"}, {"id": "15-self-03", "chapter": 15, "type": "self", "number": 3, "stem": "A 62-year-old woman (weight 119 kg) develops ventilator-associated pneumonia in the setting of prolonged intubation after aortic valve replacement surgery. Her pneumonia is complicated by septic shock, and she is given 2 L of 0.9% sodium chloride and 1 L of 5% albumin for resuscitation and initiated on norepinephrine. Her laboratory values are as follows: Na 144 mEq/L, chloride (Cl) 110 mEq/L, K 3.8 mEq/L, bicarbonate 18 mEq/L, SCr 1.8 mg/ dL, arterial pH 7.28, and albumin 3.2 g/dL. Having determined that the patient is still fluid responsive, you would like to give another fluid bolus. Which fluid is best for the fluid bolus?", "context": "", "options": [{"key": "A", "text": "0.9% sodium chloride.", "sourceKey": "A"}, {"key": "B", "text": "5% albumin.", "sourceKey": "B"}, {"key": "C", "text": "6% hydroxyethyl starch.", "sourceKey": "C"}, {"key": "D", "text": "Lactated Ringer’s solution.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient’s laboratory values and arterial pH are consistent with hyperchloremic metabolic acidosis, and chloride-rich fluids should be avoided. Lactated Ringer’s solution is considered a relatively chloridepoor solution (chloride content 111 mEq/L) and is best in this case (Answer D is correct). With its chloride content of 154 mEq/L, 0.9% sodium chloride is considered a chloride-rich fluid. Liberal use of chloride-rich fluids such as 0.9% sodium chloride has been associated with an increased need for renal replacement therapy (Answer A is incorrect). Although albumin 5% is considered a chloride-poor solution, data from randomized controlled trials have not supported a mortality benefit with albumin over crystalloids, even in the setting of hypoalbuminemia. Moreover, the patient has not received a “substantial volume” of crystalloids (she has received less than 30 mL/kg of fluid) that would coincide with recommendations to give albumin (Answer B is incorrect). Hydroxyethyl starch solutions may also have a high chloride content (depending on the formulation) and have been associated with an increased need for renal replacement therapy in the general critical care population, with no mortality benefit. Hydroxyethyl starch solutions should be avoided for fluid resuscitation in the ICU (Answer C is incorrect).", "page": 4, "answerPage": 62, "stemZh": "62歲女性119 kg，aortic valve replacement後VAP併septic shock，已2 L normal saline及1 L albumin5%；Cl110、HCO3 18、pH7.28、SCr1.8且仍fluid responsive，下一fluid bolus選何者？", "optionsZh": [{"key": "A", "text": "Normal saline0.9%"}, {"key": "B", "text": "Albumin5%"}, {"key": "C", "text": "Hydroxyethyl starch6%"}, {"key": "D", "text": "Lactated Ringer solution"}], "explanationZh": "已有hyperchloremic acidosis，balanced crystalloid較適合；避免hydroxyethyl starch。", "contextZh": ""}, {"id": "15-self-04", "chapter": 15, "type": "self", "number": 4, "stem": "A 48-year-old man (weight 82 kg) presents to the medical ICU for septic shock secondary to a urinary tract infection. His medical history is significant only for hypertension. The patient has an initial mean arterial pressure (MAP) of 58 mm Hg and a lactate concentration of 4.8 mmol/L. The patient is initiated on broad-spectrum antimicrobials, has a central venous catheter placed in his right subclavian vein, and is resuscitated with quantitative resuscitation. He receives 2 L of 0.9% sodium chloride total and 2 L of lactated Ringer’s solution, and he is initiated on norepinephrine. Three hours after presentation, his current pertinent vital signs, hemodynamic parameters, and laboratory values are as follows: MAP 68 mm Hg on norepinephrine 8 mcg/minute, central venous pressure (CVP) 10 mm Hg, central venous oxygen saturation (Scvo2 ) 72%, urinary output 0.2 mL/kg/hour, and lactate 4.6 mmol/L. Which is the next best step for the patient’s hemodynamic therapy?", "context": "", "options": [{"key": "A", "text": "Continue current therapy.", "sourceKey": "A"}, {"key": "B", "text": "Increase the norepinephrine dose.", "sourceKey": "B"}, {"key": "C", "text": "Give 1 L of 0.9% sodium chloride.", "sourceKey": "C"}, {"key": "D", "text": "Initiate dobutamine.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient has evidence of end-organ hypoperfusion (urinary output less than 0.5 mL/kg/hour and elevated lactate concentration without significant clearance), despite a MAP greater than 65 mm Hg and quantitative resuscitation. The patient probably needs a higher perfusion pressure because of a right-shifted zone of autoregulation secondary to hypertension. The norepinephrine dose should be increased to target a higher MAP; the exact target will depend on the patient’s response and should be selected as the threshold that improves end-organ perfusion (Answer B is correct). The patient has no evidence of impaired CO (his Scvo2 is not low); therefore, fluids (to improve SV) and inotropes (e.g., dobutamine) are not indicated (Answers C and D are incorrect). Because the patient has continued evidence of hypoperfusion, action should be taken, and the current therapy should be modified (Answer A is incorrect).", "page": 5, "answerPage": 62, "stemZh": "48歲男性urosepsis，3小時後norepinephrine8 mcg/min時MAP68、CVP10、ScvO2 72%、UOP0.2 mL/kg/hour、lactate4.6；下一步hemodynamic therapy為何？", "optionsZh": [{"key": "A", "text": "維持原療法"}, {"key": "B", "text": "增加norepinephrine"}, {"key": "C", "text": "Normal saline1 L"}, {"key": "D", "text": "開始dobutamine"}], "explanationZh": "本題在達初始MAP後仍灌流不佳且有hypertension病史，原章支持調高norepinephrine目標。", "contextZh": ""}, {"id": "15-self-05", "chapter": 15, "type": "self", "number": 5, "stem": "An 82-year-old man is admitted to the surgical ICU after an exploratory laparotomy and small bowel resection for a small bowel obstruction that was complicated by fecal peritonitis and hypotension. The patient received 2 L of lactated Ringer’s solution, 500 mL of 5% albumin, and 500 mL of 6% hydroxyethyl starch in the operating room, but vasopressors were never initiated. He remains intubated and mechanically ventilated, requiring a 90% fraction of inspired oxygen (Fio2 ), with the following vital signs: heart rate 131 beats/minute in atrial fibrillation, MAP 62 mm Hg (by arterial blood pressure catheter), respiratory rate 22 breaths/minute, and temperature 100.8°F (38.2°C). An arterial blood gas show lactate 5.2 mmol/L. An arterial pulse pressure waveform analysis monitor shows pulse pressure variation (PPV) 18%. The patient has a central venous catheter in his right femoral vein. Which next step is best?", "context": "", "options": [{"key": "A", "text": "Give 1 L of lactated Ringer’s solution.", "sourceKey": "A"}, {"key": "B", "text": "Do a passive leg raising (PLR) test.", "sourceKey": "B"}, {"key": "C", "text": "Measure CVP.", "sourceKey": "C"}, {"key": "D", "text": "Send a blood gas for venous oxygen saturation.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient has hypotension and signs of hypoperfusion with an elevated lactate concentration; possible interventions such as fluid administration should be explored further. Because the patient requires a high Fio2 , a reliable predictor of fluid responsiveness should be used to guide fluid therapy instead of administering fluid without respect to predicting responsiveness. In the setting of atrial fibrillation, an elevated PPV is not a reliable predictor of fluid responsiveness, and further evaluation should be done before fluids are administered (Answer A is incorrect). A PLR test can be used in both spontaneously breathing patients and those receiving mechanical ventilation to predict fluid responsiveness, and the patient has a method to assess the presence (or absence) of a CO response (Answer B is correct). Although the accuracy of the CO value from arterial pulse pressure waveform analysis may be somewhat limited by atrial fibrillation, this may be accounted for with the internal software of most devices and can be used to gauge a response to the PLR test. The patient has a femoral central venous catheter, which cannot be used to assess hemodynamic markers such as CVP or Scvo2 (Answers C and D are incorrect). Furthermore, CVP is an inadequate predictor of fluid responsiveness.", "page": 5, "answerPage": 62, "stemZh": "82歲男性小腸手術後peritonitis且hypotension，MV FiO2 90%、AF HR131、MAP62、lactate5.2、PPV18%；下一步何者最好？", "optionsZh": [{"key": "A", "text": "LR1 L"}, {"key": "B", "text": "PLR test"}, {"key": "C", "text": "測CVP"}, {"key": "D", "text": "測venous oxygen saturation"}], "explanationZh": "AF會使PPV不可靠，PLR較適合評估fluid responsiveness。", "contextZh": ""}, {"id": "15-self-06", "chapter": 15, "type": "self", "number": 6, "stem": "A 19-year-old man is admitted to the medical ICU for hypotension after being stung by a bee. He was given intramuscular epinephrine by emergency medical services and transferred to the emergency department (ED). On arrival at the ED, his blood pressure was 78/42 mm Hg; he was given 1 L of 0.9% sodium chloride, diphenhydramine, famotidine, and methylprednisolone. The patient remained hypotensive but responded to an additional 2 L of 0.9% sodium chloride. He was transferred to the medical ICU for further treatment. On arrival in the medical ICU, his MAP is 62 mm Hg. A right internal jugular central venous catheter is placed, which shows CVP 3 mm Hg, Scvo2 61%, venous lactate concentration 4.4 mmol/L, and hemoglobin (Hgb) 9.6 g/dL. Together with further fluid resuscitation, which agent would be best to initiate or administer?", "context": "", "options": [{"key": "A", "text": "Packed red blood cells (PRBCs).", "sourceKey": "A"}, {"key": "B", "text": "Dobutamine.", "sourceKey": "B"}, {"key": "C", "text": "Milrinone.", "sourceKey": "C"}, {"key": "D", "text": "Norepinephrine.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient has features of vasodilatory shock secondary to an immune-mediated (“anaphylactic”) reaction (low preload, a low Scvo2 [suggestive of poor Do2 ], and an elevated lactate concentration). The patient should receive aggressive fluid resuscitation and be initiated on a vasopressor such as norepinephrine with the primary effects of augmenting afterload (Answer D is correct). Although the patient has features of poor Do2 , this is likely because of inadequate preload, which will be augmented by fluid administration. Agents targeted toward improving Cao2 (PRBCs) and CO (dobutamine and milrinone) should not be initiated unless the patient has inadequate Do2 and is not fluid responsive (Answers A–C are incorrect).", "page": 5, "answerPage": 63, "stemZh": "19歲男性bee sting後shock，已epinephrine IM及3 L saline等；ICU MAP62、CVP3、ScvO2 61%、lactate4.4、Hgb9.6。持續補液外加何者？", "optionsZh": [{"key": "A", "text": "PRBC"}, {"key": "B", "text": "Dobutamine"}, {"key": "C", "text": "Milrinone"}, {"key": "D", "text": "Norepinephrine"}], "explanationZh": "仍hypotension，補液之外需vasopressor support；本題選norepinephrine。", "contextZh": ""}, {"id": "15-self-07", "chapter": 15, "type": "self", "number": 7, "stem": "A 56-year-old man (weight 66 kg) presents to the ED with presumed community-acquired pneumonia. Blood cultures are obtained, and the patient is given ceftriaxone 1 g and levofloxacin 750 mg. His initial blood pressure is 83/47 mm Hg with a lactate concentration of 6.2 mmol/L, and he is given 1.5 L of 0.9% sodium chloride over 1 hour. Subsequently, his blood pressure is 92/54 mm Hg with a lactate concentration of 4.6 mmol/L and urinary output of 30 mL/hour. A central venous catheter placed in his right internal jugular vein shows a CVP of 6 mm Hg, and a venous blood gas reading obtained from the central venous catheter shows an Scvo2 of 63%, Hgb 9.2 g/dL, and hematocrit (Hct) 28%. Which would be the best therapy for this patient right now?", "context": "", "options": [{"key": "A", "text": "0.9% sodium chloride.", "sourceKey": "A"}, {"key": "B", "text": "5% albumin.", "sourceKey": "B"}, {"key": "C", "text": "Phenylephrine.", "sourceKey": "C"}, {"key": "D", "text": "PRBCs.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient has received an initial fluid challenge of only 23 mL/kg of crystalloids and still has evidence of end-organ hypoperfusion (elevated lactate concentration and urinary output less than 0.5 mL/kg/hour). An additional bolus of at least 500 mL of 0.9% sodium chloride is indicated to ensure an initial fluid challenge of at least 30 mL/kg of crystalloids and to improve end-organ perfusion (Answer A is correct). Because the patient has not received a complete initial fluid challenge (or even a substantial amount of crystalloids), albumin is not indicated (Answer B is incorrect). Vasopressors are not indicated right now because the patient’s MAP is above 65 mm Hg (the patient’s MAP is 67 mm Hg). In addition, if an initial vasopressor were to be selected, norepinephrine would be preferred (Answer C is incorrect). The patient’s low Scvo2 is likely caused by inadequate preload (resulting in inadequate SV and CO). Adequate preload should be ensured before giving PRBCs as part of improving Do2 (Answer D is incorrect).", "page": 5, "answerPage": 63, "stemZh": "56歲男性66 kg，CAP且初始BP83/47、lactate6.2；1.5 L saline後BP92/54、lactate4.6、UOP30 mL/hour、CVP6、ScvO2 63%、Hgb9.2，現在何療法最好？", "optionsZh": [{"key": "A", "text": "Normal saline0.9%"}, {"key": "B", "text": "Albumin5%"}, {"key": "C", "text": "Phenylephrine"}, {"key": "D", "text": "PRBC"}], "explanationZh": "尚需initial fluid resuscitation，crystalloid適當；Hgb9.2不支持常規輸血。", "contextZh": ""}, {"id": "15-self-08", "chapter": 15, "type": "self", "number": 8, "stem": "A 68-year-old woman (weight 88 kg) presents to the ED with a urinary tract infection. Her medical history is significant for paroxysmal atrial fibrillation. The patient’s vital signs in the ED are as follows: blood pressure 83/47 mm Hg, heart rate 118 beats/ minute in atrial fibrillation, respiratory rate 24 breaths/minute, and temperature 102°F (38.9°C). Her laboratory values of interest in the ED include white blood cell count (WBC) 19.6 × 103 cells/mm3, Hgb 9.3 g/dL, albumin 2.4 g/dL, lactate 4.9 mmol/L, and SCr 1.2 mg/dL. Blood and urinary cultures are obtained, and she receives levofloxacin 750 mg and 3 L of 0.9% sodium chloride. Thirty minutes after completing the 0.9% sodium chloride infusion, her blood pressure is 92/49 mm Hg with a lactate concentration of 4.6 mmol/L and urinary output of 30 mL/hour. Which would be the best therapy for this patient right now?", "context": "", "options": [{"key": "A", "text": "Norepinephrine.", "sourceKey": "A"}, {"key": "B", "text": "Vasopressin.", "sourceKey": "B"}, {"key": "C", "text": "Phenylephrine.", "sourceKey": "C"}, {"key": "D", "text": "Dopamine.", "sourceKey": "D"}], "answer": "A", "explanation": "Despite an initial fluid challenge of greater than 30 mL/ kg of crystalloids, the patient has continued evidence of hypotension (MAP 63 mm Hg) and hypoperfusion (an elevated lactate and a urinary output less than 0.5 mL/ kg/hour). A vasopressor should be initiated to improve blood pressure (MAP greater than 65 mm Hg) and organ perfusion. Norepinephrine is recommended by the SSC as the first-line vasopressor (Answer A is correct). Vasopressin is not recommended as the single initial vasopressor, but it may be added to norepinephrine (Answer B is incorrect). Phenylephrine is no longer recommended in the SSC guidelines. Although this patient has a history of atrial fibrillation and a high heart rate, norepinephrine should still be tried and the patient observed for signs of worsening tachyarrhythmias (Answer C is incorrect). Dopamine is recommended as an alternative vasopressor to norepinephrine in select patients, such as those with bradycardia. In a metaanalysis of patients with septic shock, dopamine was associated with a higher mortality rate and more frequent tachyarrhythmias (Answer D is incorrect).", "page": 6, "answerPage": 63, "stemZh": "68歲女性88 kg，UTI、paroxysmal AF；3 L saline後BP92/49、lactate4.6、UOP30 mL/hour，下一療法何者最好？", "optionsZh": [{"key": "A", "text": "Norepinephrine"}, {"key": "B", "text": "Vasopressin"}, {"key": "C", "text": "Phenylephrine"}, {"key": "D", "text": "Dopamine"}], "explanationZh": "補液後仍低血壓，norepinephrine為septic shock首選vasopressor。", "contextZh": ""}, {"id": "15-self-09", "chapter": 15, "type": "self", "number": 9, "stem": "A 34-year-old man is admitted to the surgical ICU with septic shock associated with necrotizing soft tissue infection of the right leg. He received 100% oxygen by high-flow mask; adequate broadspectrum antibiotics with vancomycin, piperacillin/ tazobactam, and clindamycin; and quantitative resuscitation. The patient has been resuscitated for the past 4 hours with 5 L of normal saline and currently is hemodynamically unstable on norepinephrine 14 mcg/minute with a corresponding blood pressure of 92/45 mm Hg and heart rate of 132 beats/minute in sinus rhythm. His CVP is 12 mm Hg, Scvo2 72%, urinary output 0.3 mL/kg/hour, and lactate 7.4 mmol/L. Which would be best to initiate for this patient?", "context": "", "options": [{"key": "A", "text": "0.9% sodium chloride.", "sourceKey": "A"}, {"key": "B", "text": "Vasopressin.", "sourceKey": "B"}, {"key": "C", "text": "Phenylephrine.", "sourceKey": "C"}, {"key": "D", "text": "Epinephrine.", "sourceKey": "D"}], "answer": "B", "explanation": "Vasopressin can be added to norepinephrine to either increase MAP or lower norepinephrine requirements. In the VASST (Vasopressin and Septic Shock Trial) study comparing norepinephrine monotherapy with norepinephrine plus vasopressin, mortality did not differ between the two groups, but norepinephrine requirements were significantly lower in the patients allocated to receive AVP. According to the SSC guidelines, vasopressin can be added to norepinephrine to either raise the MAP or decrease the norepinephrine dosage (Answer B is correct). Although a dynamic marker of fluid responsiveness is not presented, the patient’s CO and cardiac preload are likely adequate, given that his Scvo2 is 72%. Additional fluid loading is not indicated, given the information presented (Answer A is incorrect). Phenylephrine is no longer recommended as a treatment in the SSC guidelines; however, it has theoretical benefit as a second-line vasopressor when a malignant tachyarrhythmia is associated with norepinephrine. In this case, phenylephrine is not indicated because sinus tachycardia is not considered a malignant tachyarrhythmia (Answer C is incorrect). Epinephrine is recommended when an additional agent is needed to raise the MAP to the target. Adding epinephrine to norepinephrine would only add inotropic support, but this patient has no signs of low CO with an Scvo2 of 72%, and the patient’s inadequate blood pressure is the most likely reason for his hypoperfusion (elevated lactate and low urinary output). Adding epinephrine would also likely increase the patient’s heart rate and potential for a tachyarrhythmia. As such, epinephrine is not indicated (Answer D is incorrect).", "page": 6, "answerPage": 63, "stemZh": "34歲男性septic shock，已5 L saline、norepinephrine14 mcg/min；BP92/45、HR132、CVP12、ScvO2 72%、UOP0.3、lactate7.4，何藥最好加入？", "optionsZh": [{"key": "A", "text": "Normal saline0.9%"}, {"key": "B", "text": "Vasopressin"}, {"key": "C", "text": "Phenylephrine"}, {"key": "D", "text": "Epinephrine"}], "explanationZh": "Persistent shock可加vasopressin，減少norepinephrine需求。", "contextZh": ""}, {"id": "15-case-01", "chapter": 15, "type": "case", "number": 1, "stem": "A 77-year-old man presents to the ED with light-headedness and fatigue. He reports increasing melena during the past 24 hours. His medical history is significant for hypertension, asthma, and gastroesophageal reflux disease. Vital signs in the ED are as follows: blood pressure 88/54 mm Hg, heart rate 124 beats/minute, respiratory rate 18 breaths/minute, and temperature 102.2°F (39°C). While interviewing the patient, you note that he appears lethargic and confused. His serum chemistry panel shows the following: Na 138 mEq/L, K 3.8 mEq/L, Cl 105 mEq/L, carbon dioxide 22 mEq/L, blood urea nitrogen (BUN) 25 mg/dL, SCr 1.1 mg/dL, and glucose 78 mg/dL. Results of the complete blood cell count (CBC) are as follows: WBC 10.2 × 103 cells/mm3, Hgb 6.6 g/dL, Hct 19.2%, and platelet count (Plt) 180,000/mm3. Which is most likely contributing to this patient’s compromised Do2 to the end organs?", "context": "", "options": [{"key": "A", "text": "Medical history of hypertension.", "sourceKey": "A"}, {"key": "B", "text": "Reduced Hgb.", "sourceKey": "B"}, {"key": "C", "text": "Tachycardia.", "sourceKey": "C"}, {"key": "D", "text": "Leukocytosis.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient has hypovolemic shock caused by his upper GI hemorrhage and has symptoms of compromised endorgan perfusion (i.e., confusion). Although his history of hypertension is relevant in relation to determining a resuscitation goal, it does not acutely affect Do2 (Answer A is incorrect). Tachycardia is a symptom in response to his hypovolemia, and, in the absence of complicating factors (e.g., atrial fibrillation or LV diastolic dysfunction), tachycardia will increase (not decrease) Do2 (Answer C is incorrect). Leukocytosis does not impede Do2 until it reaches an exorbitant threshold (greater than 75 L/mm3) (Answer D is incorrect). When examining the Fick equation for Do2 , acute anemia is the determinant that is adversely affecting Do2 (Answer B is correct).", "page": 16, "answerPage": 60, "stemZh": "77歲男性melena，BP88/54、HR124、意識混亂，Hgb6.6；哪因素最可能造成end-organ DO2不足？", "optionsZh": [{"key": "A", "text": "Hypertension病史"}, {"key": "B", "text": "低Hgb"}, {"key": "C", "text": "Tachycardia"}, {"key": "D", "text": "Leukocytosis"}], "explanationZh": "Hemoglobin是arterial oxygen content的主要決定因素，嚴重anemia降低DO2。", "contextZh": ""}, {"id": "15-case-02", "chapter": 15, "type": "case", "number": 2, "stem": "With which shock state are the patient’s post-resuscitation hemodynamic parameters most consistent?", "context": "A 59-year-old man with a medical history of cirrhosis complicated by ascites was transferred from the ward to the medical ICU for gross hematemesis, with an Hgb decrease from 9.2 g/dL to 7.3 g/dL, blood pressure 82/36 mm Hg, and new-onset confusion. After 2 L of lactated Ringer’s solution and 2 units of PRBCs, the patient’s Hgb increased to 9.1 g/dL, but he remained hypotensive. The medical team placed a PAC and an arterial blood pressure catheter, which showed the following: CVP 8 mm Hg, PCWP 14 mm Hg, CO 7.4 L/minute, and MAP 58 mm Hg.", "options": [{"key": "A", "text": "Hypovolemic.", "sourceKey": "A"}, {"key": "B", "text": "Obstructive.", "sourceKey": "B"}, {"key": "C", "text": "Vasodilatory.", "sourceKey": "C"}, {"key": "D", "text": "Cardiogenic.", "sourceKey": "D"}], "answer": "C", "explanation": "The patient has evidence of vasodilatory shock postresuscitation, with his relatively high CVP and PCWP values and high CO (Answer C is correct). This is further confirmed by a calculated SVR of 541 dynes x second x cm-5. The patient could be thought to have spontaneous bacterial peritonitis in the setting of cirrhosis and ascites complicated by upper GI hemorrhage. Even though his presentation suggests hypovolemic shock (from GI hemorrhage), his MAP did not respond to fluid and blood product administration. Furthermore, he does not have low preload or low CO (Answer A is incorrect). If the patient had a low CO together with a high SVR, cardiogenic shock or obstructive shock might be possible (with one differentiation depending on CVP/right atrial pressure and PCWP), but this is untrue for the patient (Answers B and D are incorrect).", "page": 20, "answerPage": 60, "stemZh": "共同病例復甦後的hemodynamic parameters最符合哪種shock？", "optionsZh": [{"key": "A", "text": "Hypovolemic"}, {"key": "B", "text": "Obstructive"}, {"key": "C", "text": "Vasodilatory"}, {"key": "D", "text": "Cardiogenic"}], "explanationZh": "補血後仍低MAP但CO高，符合vasodilatory shock。", "contextZh": "59歲男性cirrhosis合併ascites，hematemesis使Hgb9.2降至7.3，BP82/36且新發confusion。給LR2 L及PRBC2 units後Hgb9.1，但仍hypotension；CVP8、PCWP14、CO7.4 L/min、MAP58。"}, {"id": "15-case-03", "chapter": 15, "type": "case", "number": 3, "stem": "After further resuscitation, the patient developed hypoxemia requiring intubation and mechanical ventilation. A post-intubation radiograph revealed diffuse bilateral alveolar opacities. The patient remained hypoxemic with an Fio2 of 90% and was subsequently deeply sedated and given atracurium. The patient also remained hypotensive with low urinary output. Which best predicts that the patient will respond favorably to a fluid bolus?", "context": "A 59-year-old man with a medical history of cirrhosis complicated by ascites was transferred from the ward to the medical ICU for gross hematemesis, with an Hgb decrease from 9.2 g/dL to 7.3 g/dL, blood pressure 82/36 mm Hg, and new-onset confusion. After 2 L of lactated Ringer’s solution and 2 units of PRBCs, the patient’s Hgb increased to 9.1 g/dL, but he remained hypotensive. The medical team placed a PAC and an arterial blood pressure catheter, which showed the following: CVP 8 mm Hg, PCWP 14 mm Hg, CO 7.4 L/minute, and MAP 58 mm Hg.", "options": [{"key": "A", "text": "CVP 7 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "PCWP 11 mm Hg.", "sourceKey": "B"}, {"key": "C", "text": "SVV 16%.", "sourceKey": "C"}, {"key": "D", "text": "MAP 62 mm Hg.", "sourceKey": "D"}], "answer": "C", "explanation": "The patient’s clinical scenario of refractory hypoxemia and hypotension with hypoperfusion suggests that an accurate prediction of fluid responsiveness is needed. Dynamic markers of fluid responsiveness (e.g., SVV) are superior to static markers of fluid responsiveness (e.g., CVP and PCWP) (Answer C is correct; Answers A and B are incorrect). A low MAP may be from either a low CO or a low SVR. Furthermore, a low preload is only one of many components that may contribute to a low CO. As such, a low MAP is not a good predictor of fluid responsiveness (Answer D is incorrect).", "page": 20, "answerPage": 60, "stemZh": "病人後續hypoxemia需MV，FiO2 90%、deep sedation及atracurium，仍低BP與低UOP；何項最能預測fluid responsiveness？", "optionsZh": [{"key": "A", "text": "CVP7"}, {"key": "B", "text": "PCWP11"}, {"key": "C", "text": "SVV16%"}, {"key": "D", "text": "MAP62"}], "explanationZh": "在適當MV條件、無顯著自主呼吸時，dynamic SVV較static pressures有預測力。", "contextZh": "59歲男性cirrhosis合併ascites，hematemesis使Hgb9.2降至7.3，BP82/36且新發confusion。給LR2 L及PRBC2 units後Hgb9.1，但仍hypotension；CVP8、PCWP14、CO7.4 L/min、MAP58。"}, {"id": "15-case-04", "chapter": 15, "type": "case", "number": 4, "stem": "Which would best meet J.B.’s fluid needs?", "context": "J.B. is a 28-year-old man (weight 92 kg) who presented to the surgical ICU with shock after an appendectomy was complicated by appendiceal perforation. In the operating room, the patient received 2 L of lactated Ringer’s solution and 500 mL of 5% albumin and was initiated on norepinephrine. The patient is still receiving norepinephrine 12 mcg/minute (0.13 mcg/kg/minute) with a lactate of 6.8 mmol/L and had a CO increase of 18% with a PLR.", "options": [{"key": "A", "text": "5% albumin.", "sourceKey": "A"}, {"key": "B", "text": "6% hydroxyethyl starch.", "sourceKey": "B"}, {"key": "C", "text": "0.9% sodium chloride.", "sourceKey": "C"}, {"key": "D", "text": "No fluids necessary.", "sourceKey": "D"}], "answer": "C", "explanation": "The patient has shock with hypoperfusion and a positive response to a PLR test, which suggests he is still fluid responsive (Answer D is incorrect). Data from a large randomized trial of patients with heterogeneous shock types showed no difference in efficacy and safety between albumin and 0.9% sodium chloride, but the cost of albumin is substantially higher. These data suggest that crystalloids such as 0.9% sodium chloride are preferred for fluid resuscitation in the ICU. In addition, the patient has not received a substantial volume of fluid (he has received less than 30 mL/kg; Answer C is correct; Answer A is incorrect). Hydroxyethyl starch, which has been associated with an increased need for renal replacement therapy without a mortality benefit, should be avoided for fluid resuscitation in the ICU (Answer B is incorrect).", "page": 28, "answerPage": 60, "stemZh": "哪種補液最符合J.B.需求？", "optionsZh": [{"key": "A", "text": "Albumin5%"}, {"key": "B", "text": "Hydroxyethyl starch6%"}, {"key": "C", "text": "Normal saline0.9%"}, {"key": "D", "text": "不需補液"}], "explanationZh": "PLR使CO增加18%支持fluid responsiveness；本題適當crystalloid為normal saline。", "contextZh": "J.B.，28歲男性92 kg，appendectomy併appendiceal perforation後shock。術中LR2 L與albumin5%500 mL並開始norepinephrine；目前12 mcg/min（0.13 mcg/kg/min）、lactate6.8，PLR使CO增加18%。"}, {"id": "15-case-05", "chapter": 15, "type": "case", "number": 5, "stem": "After 12 hours in the surgical ICU, J.B. remains hypotensive with a lactate concentration of 5.2 mmol/L. He currently requires norepinephrine 14 mcg/minute (0.15 mcg/kg/minute); his MAP is 64 mm Hg and Scvo2 is 61%. A bedside echocardiogram done by the ICU team reveals large ventricles with poor contractility. Which action is best?", "context": "J.B. is a 28-year-old man (weight 92 kg) who presented to the surgical ICU with shock after an appendectomy was complicated by appendiceal perforation. In the operating room, the patient received 2 L of lactated Ringer’s solution and 500 mL of 5% albumin and was initiated on norepinephrine. The patient is still receiving norepinephrine 12 mcg/minute (0.13 mcg/kg/minute) with a lactate of 6.8 mmol/L and had a CO increase of 18% with a PLR.", "options": [{"key": "A", "text": "Start phenylephrine.", "sourceKey": "A"}, {"key": "B", "text": "Start vasopressin.", "sourceKey": "B"}, {"key": "C", "text": "Increase norepinephrine.", "sourceKey": "C"}, {"key": "D", "text": "Start epinephrine.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient has evidence of ventricular dysfunction with a low Scvo2 and poor ventricular contractility on echocardiogram. A vasoactive agent with strong inotropic properties is indicated. Epinephrine has strong β 1 -adrenergic properties and is the best selection in this case (Answer D is correct). Both phenylephrine and vasopressin are essentially pure vasoconstrictors that do not increase CO and could theoretically decrease CO. In addition, use of phenylephrine is no longer recommended by the guidelines (Answers A and B are incorrect). Although norepinephrine has β 1 -adrenergic properties, it primarily increases blood pressure through vasoconstriction secondary to its α 1 -adrenergic properties, with only minimal effects on CO. Increasing norepinephrine in this case would probably not improve the patient’s CO sufficiently to improve tissue perfusion (Answer C is incorrect).", "page": 28, "answerPage": 60, "stemZh": "J.B.術後12小時norepinephrine14 mcg/min，MAP64、ScvO2 61%、lactate5.2，ECHO顯示large ventricles與poor contractility；何者最佳？", "optionsZh": [{"key": "A", "text": "開始phenylephrine"}, {"key": "B", "text": "開始vasopressin"}, {"key": "C", "text": "增加norepinephrine"}, {"key": "D", "text": "開始epinephrine"}], "explanationZh": "伴低contractility及oxygen delivery不足時，需要inotropic作用；本題選epinephrine。", "contextZh": "J.B.，28歲男性92 kg，appendectomy併appendiceal perforation後shock。術中LR2 L與albumin5%500 mL並開始norepinephrine；目前12 mcg/min（0.13 mcg/kg/min）、lactate6.8，PLR使CO增加18%。"}, {"id": "15-case-06", "chapter": 15, "type": "case", "number": 6, "stem": "A 56-year-old woman with a medical history of hypertension presents to the ED with shortness of breath and cough productive of sputum. Her vital signs on admission are as follows: blood pressure 92/68 mm Hg, heart rate 104 beats/minute, respiratory rate 26 breaths/minute, and temperature 101.6°F (38.7°C). A chest radiograph reveals an opacity in the left lower lobe, but the radiograph is otherwise unremarkable. Her laboratory values of interest include Hgb 12.7 g/dL, WBC 16.4 × 103 cells/mm3, Plt 80,000/mm3, albumin 2.0 g/dL, lactate 3.2 mmol/L, and SCr 1.3 mg/dL. Her Glasgow Coma Scale score is 13. Which best describes the patient’s condition?", "context": "", "options": [{"key": "A", "text": "Systemic inflammatory response syndrome.", "sourceKey": "A"}, {"key": "B", "text": "Sepsis.", "sourceKey": "B"}, {"key": "C", "text": "Severe sepsis.", "sourceKey": "C"}, {"key": "D", "text": "Septic shock.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient has life-threatening organ dysfunction secondary to infection. Although not all the criteria to calculate the score are available, her SOFA score is at least 4 points (2 points for Plt, 1 point for Glasgow Coma Scale score, and 1 point for SCr), indicating organ dysfunction. In addition, the patient fulfills all three qSOFA criteria (altered mental status, SBP of 100 mm Hg or less, and respiratory rate of 22 breaths/minute or greater). Therefore, she meets the criteria for sepsis, according to the new definition (Answer B is correct). Although she has an elevated lactate concentration, she does not require vasopressors to maintain a MAP above 65 mm Hg and therefore does not meet the criteria for septic shock (Answer C is incorrect). In the new sepsis definition, severe sepsis and systemic inflammatory response syndrome are no longer clinical entities in the spectrum of sepsis severity and should not be used (Answers A and D are incorrect).", "page": 41, "answerPage": 60, "stemZh": "56歲女性疑pneumonia，BP92/68、HR104、RR26、38.7°C；Plt80000、lactate3.2、SCr1.3、GCS13，病況最符合何者？", "optionsZh": [{"key": "A", "text": "SIRS"}, {"key": "B", "text": "Sepsis"}, {"key": "C", "text": "Severe sepsis"}, {"key": "D", "text": "Septic shock"}], "explanationZh": "感染合併organ dysfunction符合Sepsis-3；尚未符合vasopressor-dependent septic shock。", "contextZh": ""}, {"id": "15-case-07", "chapter": 15, "type": "case", "number": 7, "stem": "A 55-year-old man presents to the medical ICU with presumed urosepsis. His medical history is significant for congestive heart failure with a baseline ejection fraction of 20%. In the medical ICU, his vital signs are as follows: blood pressure 69/45 mm Hg, heart rate 84 beats/minute, respiratory rate 32 breaths/minute, and temperature 100.6°F (38.1°C). Blood cultures are obtained, and piperacillin/tazobactam is initiated. A central venous catheter shows CVP 18 mm Hg and Scvo2 70%. Which is the most appropriate initial vasopressor for this patient?", "context": "", "options": [{"key": "A", "text": "Norepinephrine.", "sourceKey": "A"}, {"key": "B", "text": "Vasopressin.", "sourceKey": "B"}, {"key": "C", "text": "Dobutamine.", "sourceKey": "C"}, {"key": "D", "text": "Epinephrine.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient currently has a MAP less than 65 mm Hg and signs of a global lack of perfusion with an increased lactate concentration. Vasopressor therapy is indicated to sustain perfusion. This patient has underlying severe congestive heart failure with an ejection fraction of 20%; however, the Scvo2 shows that the patient’s Do2 is sufficient, which suggests he is in distributive septic shock as opposed to cardiogenic shock. The SSC guidelines recommend initiating vasopressor therapy to target a MAP of 65 mm Hg and norepinephrine as the first-choice vasopressor (Answer A is correct). Vasopressin is currently recommended only as a secondary vasopressor, as an addition to catecholamine therapy (Answer B is incorrect). In septic shock, dobutamine is recommended only when the Scvo2 is less than 70% and the patient has an adequate Hgb concentration (Answer C is incorrect). Epinephrine is currently recommended as an alternative to norepinephrine. In a study that compared epinephrine with norepinephrine plus dobutamine, the two arms did not differ in mortality outcomes; however, epinephrine was associated with lower pH values and higher lactate concentrations on day 1 (Answer D is incorrect).", "page": 48, "answerPage": 61, "stemZh": "55歲男性urosepsis且HF baseline EF20%，BP69/45、CVP18、ScvO2 70%；初始vasopressor何者最適當？", "optionsZh": [{"key": "A", "text": "Norepinephrine"}, {"key": "B", "text": "Vasopressin"}, {"key": "C", "text": "Dobutamine"}, {"key": "D", "text": "Epinephrine"}], "explanationZh": "Septic shock初始vasopressor為norepinephrine，即使合併HF亦然。", "contextZh": ""}, {"id": "15-case-08", "chapter": 15, "type": "case", "number": 8, "stem": "A 62-year-old woman was admitted to the surgical ICU with presumed aspiration pneumonia. The patient has a history of insulin-dependent diabetes and hyperthyroidism. On admission, she was intubated and required aggressive resuscitation and vasopressor therapy. Currently, the patient is receiving norepinephrine 8 mcg/minute and has the following vital signs and laboratory values: blood pressure 100/60 mm Hg, heart rate 90 beats/minute, and CVP 14 mm Hg; her Scvo2 is 55%. Which is best regarding the patient’s steroid therapy?", "context": "", "options": [{"key": "A", "text": "Administer hydrocortisone 50 mg every 6 hours.", "sourceKey": "A"}, {"key": "B", "text": "Administer hydrocortisone 8.3 mg/hour as a continuous infusion.", "sourceKey": "B"}, {"key": "C", "text": "Perform the ACTH stimulation test.", "sourceKey": "C"}, {"key": "D", "text": "No steroids are necessary right now.", "sourceKey": "D"}], "answer": "D", "explanation": "According to the SSC guidelines, corticosteroids may be considered if patients have a poor response to fluid resuscitation and vasopressor therapy. In addition, guidelines from the Society of Critical Care Medicine and the European Society of Intensive Care Medicine suggest corticosteroids only in patients requiring moderate- to high-dose vasopressors. In this case, the patient is receiving relatively low doses of vasopressors with an adequate MAP; hence, no steroids are currently necessary (Answer D is correct; Answers A and B are incorrect). Hydrocortisone is recommended at a dose of 200–400 mg/day. Administering it as a continuous infusion could be considered because this might lead to fewer variations in serum glucose. The ACTH stimulation test to determine which patients with sepsis should receive hydrocortisone is no longer recommended because the CORTICUS study showed that the ACTH stimulation test did not predict response to hydrocortisone therapy (Answer C is incorrect).", "page": 50, "answerPage": 61, "stemZh": "62歲女性aspiration pneumonia，已積極resuscitation，目前norepinephrine8 mcg/min、BP100/60、CVP14、ScvO2 55%；關於steroid何者最好？", "optionsZh": [{"key": "A", "text": "Hydrocortisone50 mg每6小時"}, {"key": "B", "text": "Hydrocortisone8.3 mg/hour infusion"}, {"key": "C", "text": "ACTH stimulation test"}, {"key": "D", "text": "目前不需steroid"}], "explanationZh": "原章此情境尚無需steroid；不要因ScvO2低就自動加hydrocortisone。", "contextZh": ""}, {"id": "16-self-01", "chapter": 16, "type": "self", "number": 1, "stem": "A 41-year-old man presents to the emergency department (ED) after a motorcycle accident. While the patient is being evaluated, it is apparent that he has broken ribs, a broken pelvis, and bilateral broken femurs. He is confused, and his vital signs are as follows: blood pressure 82/48 mm Hg, heart rate 125 beats/minute, respiratory rate 34 breaths/ minute, and temperature 95°F (35°C). On further assessment, laboratory tests show that the patient has lost around 35% of his total blood volume. Which most accurately reflects this patient’s class of hemorrhage from trauma?", "context": "", "options": [{"key": "A", "text": "I.", "sourceKey": "A"}, {"key": "B", "text": "II.", "sourceKey": "B"}, {"key": "C", "text": "III.", "sourceKey": "C"}, {"key": "D", "text": "IV.", "sourceKey": "D"}], "answer": "C", "explanation": "This patient presents with likely hemorrhagic shock after blunt trauma. The extent of injuries in highly vascularized areas suggests a hemorrhagic source. Given the extent of confusion, oliguria, tachycardia, and tachypnea, as well as the amount of blood loss (35% of total blood volume), this patient has class III hemorrhage (Answer C is correct; Answers A, B, and D are incorrect).", "page": 4, "answerPage": 44, "stemZh": "41 歲男性機車事故後有肋骨、骨盆及雙側股骨骨折，意識混亂。BP 82/48 mm Hg、HR 125/min、RR 34/min、體溫 95°F（35°C），估計失血約總血量 35%。屬於哪一級 traumatic hemorrhage？", "contextZh": "", "optionsZh": [{"key": "A", "text": "I"}, {"key": "B", "text": "II"}, {"key": "C", "text": "III"}, {"key": "D", "text": "IV"}], "explanationZh": "失血 30%–40%，合併意識混亂、tachycardia、tachypnea，符合 class III hemorrhage。"}, {"id": "16-self-02", "chapter": 16, "type": "self", "number": 2, "stem": "A 62-year-old man with a history of alcoholic cirrhosis and portal hypertension presents to the ED with weakness and hematemesis. Pertinent vital signs on admission are as follows: blood pressure 76/42 mm Hg, heart rate 134 beats/minute with a rhythm of sinus tachycardia, and respiratory rate 24 breaths/ minute. Frank red blood is noted on nasogastric lavage. On physical examination, the patient is confused, with cold and clammy extremities. Pertinent laboratory values are as follows: hemoglobin (Hgb) 5.5 g/dL, blood urea nitrogen (BUN) 56 mg/dL, serum creatinine (SCr) 1.8 mg/dL, international normalized ratio (INR) 2.6, total bilirubin 7.5 mg/dL, central venous oxygen saturation (Scvo 2 ) 58%, and lactate 2.7 mmol/L. In this patient, which variable would best explain reduced oxygen delivery (Do 2 ) and which associated clinical or biochemical sign would best indicate a shock syndrome?", "context": "", "options": [{"key": "A", "text": "Elevated INR and hematemesis.", "sourceKey": "A"}, {"key": "B", "text": "Sinus tachycardia and elevated serum creatinine.", "sourceKey": "B"}, {"key": "C", "text": "Low hemoglobin and cold and clammy extremities.", "sourceKey": "C"}, {"key": "D", "text": "Low Scvo 2 and hyperlactatemia. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 775", "sourceKey": "D"}], "answer": "C", "explanation": "The Fick equation describes oxygen delivery (Do2 (mL/ minute) = 10 x CO (L/minute) x Cao2 ). A diagnosis of shock is typically based on hemodynamic, clinical, and biochemical assessment of impaired Do2 . Although an elevated INR may represent a coagulopathy that can contribute to bleeding, it is not directly related to impaired Do2 . In addition, hematemesis is a clinical sign of bleeding but is not necessarily specific to a shock syndrome (Answer A is incorrect). Although heart rate is a determinant of CO, CO is not generally impaired unless the patient has acute supraventricular or ventricular tachycardia. In addition, an elevated serum creatinine may be a biochemical sign of impaired tissue oxygenation, but this generally presents in a delayed fashion and may represent chronic renal dysfunction in this specific patient (Answer B is incorrect). A low Scvo2 represents the balance between oxygen consumption and delivery (not solely delivery) and does not explain reduced Do2 . Although an elevated lactate concentration may indicate impaired Do2 in shock syndrome, lactate may be elevated secondary to altered hepatic metabolism and is not a specific marker for circulatory shock (Answer D is incorrect). Therefore, according to the Fick equation, a low hemoglobin reduces the Cao2 , decreasing Do2 . Cold and clammy extremities is a common clinical marker of a shock syndrome, indicating a low-flow state (Answer C is correct).", "page": 4, "answerPage": 44, "stemZh": "62 歲男性有 alcoholic cirrhosis、portal hypertension，因虛弱與吐血就醫。BP 76/42 mm Hg、HR 134/min（sinus tachycardia）、RR 24/min；胃管抽出鮮血，意識混亂、四肢冰冷濕黏。Hgb 5.5 g/dL、BUN 56 mg/dL、SCr 1.8 mg/dL、INR 2.6、total bilirubin 7.5 mg/dL、ScvO2 58%、lactate 2.7 mmol/L。哪個變數最能解釋 DO2 降低，且哪個徵象最能指出 shock syndrome？", "contextZh": "", "optionsZh": [{"key": "A", "text": "INR 升高與吐血"}, {"key": "B", "text": "Sinus tachycardia 與 SCr 升高"}, {"key": "C", "text": "低 hemoglobin 與四肢冰冷濕黏"}, {"key": "D", "text": "低 ScvO2 與 hyperlactatemia"}], "explanationZh": "低 hemoglobin 使 CaO2 與 DO2 降低；四肢冰冷濕黏提示低血流狀態。ScvO2 反映供需平衡，lactate 也可能受肝臟代謝影響。"}, {"id": "16-self-03", "chapter": 16, "type": "self", "number": 3, "stem": "A 44-year-old man (weight 82 kg) presents to the ED after a motor vehicle collision at highway speeds secondary to his windshield being shattered by a rock thrown from an overpass. On primary survey, his King airway device is replaced for an endotracheal tube; his respiratory rate is 37 breaths/ minute, systolic blood pressure (SBP) is 77 mm Hg, heart rate is 146 beats/minute, and Glasgow Coma Scale score is 3. In addition, he is noted to have a positive seatbelt sign. The Focused Assessment with Sonography in Trauma (FAST) examination is positive. He is taken to the operating room for an emergency exploratory laparotomy. Which best represents the most appropriate initial transfusion, resuscitation, and hemostasis strategy?", "context": "", "options": [{"key": "A", "text": "Give 2 L of warmed lactated Ringer solution, followed by a 2-unit transfusion of erythrocytes.", "sourceKey": "A"}, {"key": "B", "text": "Administer 30 mL/kg of warmed lactated Ringer solution and a tranexamic acid 1-g bolus, followed by 1 g infused over 8 hours.", "sourceKey": "B"}, {"key": "C", "text": "Obtain and send an INR, activated partial thromboplastin time (aPTT), fibrinogen, and complete blood cell count to guide initial resuscitation.", "sourceKey": "C"}, {"key": "D", "text": "Initiate massive transfusion, giving erythrocytes and plasma in a 1:1 ratio plus a tranexamic acid 1-g bolus and 1 g infused over 8 hours.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient presents with likely hemorrhagic shock after blunt trauma. The patient has signs consistent with intra-abdominal bleeding with the positive FAST examination in hemodynamic instability; thus, urgent intervention is required. According to the extent of altered mentation, tachycardia, and tachypnea, this patient has class IV hemorrhage, consistent with greater than 40% blood loss, indicating the requirement for erythrocyte transfusions. However, giving only erythrocyte transfusions would increase oxygen-carrying capacity but not correct the likely underlying coagulopathy (Answer A is incorrect). Although warmed lactated Ringer solution may be indicated in a trauma patient with bleeding, excessive fluid resuscitation (above 1.5 L) should initially be avoided (Answer B is incorrect). Given the patient’s blood pressure, heart rate, and positive FAST, he is at high risk of requiring massive transfusion, which should be initiated promptly with an empiric ratio. In addition, given the presence of hemorrhagic shock requiring erythrocyte transfusions, tranexamic acid is indicated early to improve mortality (Answer D is correct). Although goal-directed resuscitation is recommended for continued resuscitation, empiric blood product transfusions should not be delayed while awaiting laboratory results unless pointof-care assays are available (Answer C is incorrect).", "page": 5, "answerPage": 44, "stemZh": "44 歲男性（82 kg）高速車禍，改以 endotracheal tube 取代 King airway。RR 37/min、SBP 77 mm Hg、HR 146/min、GCS 3，有 seatbelt sign，FAST 陽性，準備緊急 exploratory laparotomy。最適當的初始 transfusion、resuscitation 與 hemostasis 策略？", "contextZh": "", "optionsZh": [{"key": "A", "text": "給 2 L 加溫 lactated Ringer solution，再輸 2 units erythrocytes"}, {"key": "B", "text": "給 30 mL/kg 加溫 lactated Ringer solution；tranexamic acid 1 g bolus，再 1 g 輸注 8 小時"}, {"key": "C", "text": "先送 INR、aPTT、fibrinogen、CBC，依結果決定初始 resuscitation"}, {"key": "D", "text": "立即 massive transfusion，erythrocytes:plasma = 1:1；tranexamic acid 1 g bolus，再 1 g 輸注 8 小時"}], "explanationZh": "不穩定血壓與 FAST 陽性提示重大腹內出血，應立即按比例輸血並早期使用 tranexamic acid，不應等檢驗或給過多 crystalloid。"}, {"id": "16-self-04", "chapter": 16, "type": "self", "number": 4, "stem": "H.S. is a 76-year-old man (weight 142 kg) with a history of several pulmonary embolisms (PEs) and associated chronic thromboembolic pulmonary hypertension (CTEPH) on warfarin who is admitted to the ED with weakness and hematemesis. Pertinent vital signs on admission are as follows: blood pressure 82/46 mm Hg, heart rate 121 beats/minute with a rhythm of sinus tachycardia, and respiratory rate 22 breaths/minute. Frank red blood is noted on nasogastric lavage. On physical examination, the patient is confused, with clammy extremities. Pertinent laboratory values are as follows: Hgb 5.2 g/dL, BUN 52 mg/dL, SCr 2 mg/dL, INR 9.2, and platelet count (Plt) 120,000/mm3. Which is most effective to immediately reverse his coagulopathy secondary to warfarin?", "context": "", "options": [{"key": "A", "text": "Phytonadione 10 mg orally once.", "sourceKey": "A"}, {"key": "B", "text": "4-factor prothrombin complex concentrate (4FPCC) 50 units/kg intravenously infused over 30 minutes.", "sourceKey": "B"}, {"key": "C", "text": "Fresh frozen plasma 15-mL/kg infusion once.", "sourceKey": "C"}, {"key": "D", "text": "Phytonadione 10-mg intravenous push once.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient has apparent warfarin toxicity contributing to an acute GI hemorrhage. Because he meets the criteria for a major bleed, particularly associated with hemodynamic instability, many guidelines recommend anticoagulation reversal. Although phytonadione is the specific reversal for warfarin to promote hepatic production of factors II, VII, IX, and X, it does not immediately correct coagulopathy, and factor replacement is recommended (Answer D is incorrect). In addition, when used for life-threatening hemorrhage, intravenous administration is recommended because of its quicker onset of action of 4–6 hours compared with 18–24 hours for oral administration (Answer A is incorrect). Although plasma has traditionally been used for immediate factor replacement for warfarin reversal, the time to laboratory reversal is inferior to PCC. In addition, the volume of plasma needed to reverse his INR would likely not be well tolerated by this patient with CTEPH (Answer C is incorrect). Therefore, 4F-PCC, which contains nonactivated highly concentrated factors II, VII, IX, and X, is recommended for warfarin reversal in life-threatening hemorrhage because of its superiority for laboratory reversal and noninferiority for clinical hemostasis. Rates of thrombotic events appear similar when comparing 4F-PCC with plasma for warfarin reversal in life-threatening hemorrhage and surgical populations; however, rates ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 815 of fluid overload complications are greater with plasma (Answer B is correct).", "page": 5, "answerPage": 44, "stemZh": "H.S.，76 歲男性（142 kg），反覆 PE、CTEPH，使用 warfarin，因吐血就醫。BP 82/46 mm Hg、HR 121/min、RR 22/min，意識混亂、四肢濕黏。Hgb 5.2 g/dL、BUN 52 mg/dL、SCr 2 mg/dL、INR 9.2、Plt 120,000/mm3。何者最能立即逆轉 warfarin 所致 coagulopathy？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Phytonadione 10 mg 口服一次"}, {"key": "B", "text": "4F-PCC 50 units/kg IV，輸注 30 分鐘"}, {"key": "C", "text": "Fresh frozen plasma 15 mL/kg 一次"}, {"key": "D", "text": "Phytonadione 10 mg IV push 一次"}], "explanationZh": "危及生命的出血需立即補充凝血因子；4F-PCC 比 plasma 更快逆轉 INR，且輸注體積小。Phytonadione 需數小時起效，不能單獨達到立即逆轉。"}, {"id": "16-self-05", "chapter": 16, "type": "self", "number": 5, "stem": "A 66-year-old man with a medical history of non– small cell lung cancer presents to the ED with new-onset shortness of breath. A chest computed tomography (CT) scan reveals a PE at the bifurcation of the right and left pulmonary arteries. The patient is initiated on parenteral anticoagulation and transferred to the medical intensive care unit (ICU). On ICU admission, he develops pulseless electrical activity. He is intubated and mechanically ventilated, with recovery of spontaneous circulation after one round of chest compressions and epinephrine 1 mg. Which is the next best step to evaluate and/or treat this patient’s PE?", "context": "", "options": [{"key": "A", "text": "Administer alteplase 100 mg infused over 2 hours.", "sourceKey": "A"}, {"key": "B", "text": "Check a troponin T concentration.", "sourceKey": "B"}, {"key": "C", "text": "Check a brain natriuretic peptide concentration.", "sourceKey": "C"}, {"key": "D", "text": "Obtain a transthoracic echocardiogram (TTE).", "sourceKey": "D"}], "answer": "A", "explanation": "The patient has a massive PE, as evidenced by pulseless activity. Massive PE should be treated with thrombolytic therapy unless absolute contraindications to thrombolytics are present. Prolonged chest compressions may be considered a relative contraindication to thrombolytics, but this patient had a short duration of chest compressions (Answer A is correct). Troponin T and brain natriuretic concentrations may help classify a patient as having a submassive PE, but the patient in this case has already fulfilled the criteria for a massive PE, and these laboratory values will not change the patient’s treatment (Answers B and C are incorrect). Although a TTE might provide information on RV function, it is unlikely to change the patient’s treatment plan with thrombolytics and might delay therapy (Answer D is incorrect).", "page": 5, "answerPage": 45, "stemZh": "66 歲男性有 non–small cell lung cancer，CT 發現左右 pulmonary artery 分叉處 PE，開始 parenteral anticoagulation 後轉 ICU，發生 PEA。插管後經一輪胸外按壓與 epinephrine 1 mg 恢復 ROSC。下一步最適當？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Alteplase 100 mg 輸注 2 小時"}, {"key": "B", "text": "檢查 troponin T"}, {"key": "C", "text": "檢查 BNP"}, {"key": "D", "text": "做 TTE"}], "explanationZh": "PE 導致 cardiac arrest，符合 massive PE。短暫 CPR 不應延遲 thrombolysis；額外 biomarkers 或 TTE 不會改變已明確的高風險治療需求。"}, {"id": "16-self-06", "chapter": 16, "type": "self", "number": 6, "stem": "Which would best categorize R.M.’s PE?", "context": "R.M is a 78-year-old man with a history of alcoholic cirrhosis and portal hypertension who is in an urban, academic ICU after treatment of a variceal hemorrhage (now stable) and respiratory failure. Five days after admission, he develops hypoxemia (partial pressure oxygen saturation [Pao 2 ] 78%), requiring an increased fraction of inspired oxygen (Fio2 ) on the ventilator. A chest computed tomography angiography (CTA) reveals several filling defects at the bifurcation of the main pulmonary artery, suggesting a “saddle” PE. His heart rate is 142 beats/minute with a rhythm of sinus tachycardia. His blood pressure is 97/62 mm Hg and current weight is 87 kg. R.M. has a TTE that reveals right ventricular (RV) hypokinesis and tricuspid regurgitation. His cardiac troponin I (0.6 ng/mL) and troponin T (0.2 ng/mL) are positive.", "options": [{"key": "A", "text": "High risk.", "sourceKey": "A"}, {"key": "B", "text": "Intermediate-high risk.", "sourceKey": "B"}, {"key": "C", "text": "Intermediate-low risk.", "sourceKey": "C"}, {"key": "D", "text": "Low risk. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 776", "sourceKey": "D"}], "answer": "B", "explanation": "This patient’s PE is causing stress on the RV, as evidenced by his echocardiogram and positive cardiac enzymes. Therefore, this is not a low-risk PE (Answer D is incorrect). However, the patient is hemodynamically stable at this point, so it is also not a high-risk PE (Answer A is incorrect). Given that the patient has both evidence for RV straining and myocardial ischemia as represented by both the echocardiogram and the cardiac enzymes, this meets the criteria for an intermediate-high risk PE (Answer B is correct; Answer C is incorrect).", "page": 5, "answerPage": 45, "stemZh": "R.M. 的 PE 最符合哪一風險分類？", "contextZh": "R.M.，78 歲男性（87 kg），alcoholic cirrhosis、portal hypertension；因 variceal hemorrhage（現已穩定）與 respiratory failure 住 urban academic ICU。第 5 天 hypoxemia（原書列 PaO2 78%），需增加 ventilator FiO2。CTA 顯示 main pulmonary artery bifurcation 多處 filling defects，疑 saddle PE。HR 142/min（sinus tachycardia）、BP 97/62 mm Hg；TTE 見 RV hypokinesis、tricuspid regurgitation，troponin I 0.6 ng/mL、troponin T 0.2 ng/mL 陽性。", "optionsZh": [{"key": "A", "text": "High risk"}, {"key": "B", "text": "Intermediate-high risk"}, {"key": "C", "text": "Intermediate-low risk"}, {"key": "D", "text": "Low risk"}], "explanationZh": "血壓尚穩定，但同時有 RV strain 與 positive cardiac enzymes，符合 intermediate-high risk PE。"}, {"id": "16-self-07", "chapter": 16, "type": "self", "number": 7, "stem": "After initiating therapeutic heparin and monitoring, R.M.’s blood pressure is now maintained at 90/50 mm Hg, but his oxygenation continues to worsen, now requiring 80% Fio2 . The medical team has decided that the patient’s potential benefit from thrombolytic therapy outweighs the potential risks. Which is the best approach for this patient’s thrombolytic administration?", "context": "R.M is a 78-year-old man with a history of alcoholic cirrhosis and portal hypertension who is in an urban, academic ICU after treatment of a variceal hemorrhage (now stable) and respiratory failure. Five days after admission, he develops hypoxemia (partial pressure oxygen saturation [Pao 2 ] 78%), requiring an increased fraction of inspired oxygen (Fio2 ) on the ventilator. A chest computed tomography angiography (CTA) reveals several filling defects at the bifurcation of the main pulmonary artery, suggesting a “saddle” PE. His heart rate is 142 beats/minute with a rhythm of sinus tachycardia. His blood pressure is 97/62 mm Hg and current weight is 87 kg. R.M. has a TTE that reveals right ventricular (RV) hypokinesis and tricuspid regurgitation. His cardiac troponin I (0.6 ng/mL) and troponin T (0.2 ng/mL) are positive.", "options": [{"key": "A", "text": "Alteplase 100 mg infused over 2 hours.", "sourceKey": "A"}, {"key": "B", "text": "Catheter-directed thrombolysis (CDT).", "sourceKey": "B"}, {"key": "C", "text": "Alteplase 50 mg infused over 2 hours.", "sourceKey": "C"}, {"key": "D", "text": "Alteplase 0.5 mg/hour by a pulmonary artery catheter.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient appears to be clinically worsening with blood pressures that are approaching hemodynamic instability and worsening oxygenation requiring high levels of Fio2 . Consideration for reperfusion therapy is warranted. Given his history of a recent GI bleed requiring ICU admission, systemic, full-dose thrombolytics would be contraindicated (Answer A is incorrect). A thrombolytic strategy to minimize the risk of bleeding may be appropriate. Although half-dose alteplase has been studied, it is not recommended because of insufficient evidence (Answer C is incorrect). Therefore, in intermediate-high risk PE with clinical deterioration, the guidelines recommend CDT when systemic thrombolytic contraindications exist and resources are available, such as in an urban, academic ICU. Catheter-directed thrombolysis is administered with mechanical methods (e.g., ultrasound-assisted thrombolysis) and specific catheters (not pulmonary artery catheters) (Answer B is correct; Answer D is incorrect).", "page": 6, "answerPage": 45, "stemZh": "R.M. 開始 therapeutic heparin 後 BP 90/50 mm Hg，氧合持續惡化，需 FiO2 80%。團隊認為 thrombolysis 效益高於風險，最適當給藥方式？", "contextZh": "R.M.，78 歲男性（87 kg），alcoholic cirrhosis、portal hypertension；因 variceal hemorrhage（現已穩定）與 respiratory failure 住 urban academic ICU。第 5 天 hypoxemia（原書列 PaO2 78%），需增加 ventilator FiO2。CTA 顯示 main pulmonary artery bifurcation 多處 filling defects，疑 saddle PE。HR 142/min（sinus tachycardia）、BP 97/62 mm Hg；TTE 見 RV hypokinesis、tricuspid regurgitation，troponin I 0.6 ng/mL、troponin T 0.2 ng/mL 陽性。", "optionsZh": [{"key": "A", "text": "Alteplase 100 mg 輸注 2 小時"}, {"key": "B", "text": "Catheter-directed thrombolysis（CDT）"}, {"key": "C", "text": "Alteplase 50 mg 輸注 2 小時"}, {"key": "D", "text": "經 pulmonary artery catheter 給 alteplase 0.5 mg/hour"}], "explanationZh": "近期 GI bleed 使 full-dose systemic thrombolysis 風險高。Intermediate-high risk PE 惡化且有 systemic thrombolysis contraindication 時，可考慮 CDT；需使用專用 catheter。"}, {"id": "16-self-08", "chapter": 16, "type": "self", "number": 8, "stem": "As you prepare to begin administering your strategy chosen previously, R.M. goes into a cardiac arrest with pulseless electrical activity. Which is the best intervention for managing R.M.’s PE while still in the ICU?", "context": "R.M is a 78-year-old man with a history of alcoholic cirrhosis and portal hypertension who is in an urban, academic ICU after treatment of a variceal hemorrhage (now stable) and respiratory failure. Five days after admission, he develops hypoxemia (partial pressure oxygen saturation [Pao 2 ] 78%), requiring an increased fraction of inspired oxygen (Fio2 ) on the ventilator. A chest computed tomography angiography (CTA) reveals several filling defects at the bifurcation of the main pulmonary artery, suggesting a “saddle” PE. His heart rate is 142 beats/minute with a rhythm of sinus tachycardia. His blood pressure is 97/62 mm Hg and current weight is 87 kg. R.M. has a TTE that reveals right ventricular (RV) hypokinesis and tricuspid regurgitation. His cardiac troponin I (0.6 ng/mL) and troponin T (0.2 ng/mL) are positive.", "options": [{"key": "A", "text": "Give alteplase 50 mg intravenous push once.", "sourceKey": "A"}, {"key": "B", "text": "Proceed to surgical embolectomy.", "sourceKey": "B"}, {"key": "C", "text": "Give alteplase 100 mg over 2 hours.", "sourceKey": "C"}, {"key": "D", "text": "Abort cardiopulmonary resuscitation.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient now has a cardiac arrest secondary to his PE. Because he has a confirmed PE as the precipitant of cardiac arrest, systemic thrombolytic is recommended as an emergency treatment. Given the mortality rates from PE in a cardiac arrest, standard contraindications to thrombolysis may be suspended in favor of a lifesaving intervention. Systemic thrombolytics in this setting may be associated with return of spontaneous circulation and possibly survival benefits (Answer D is incorrect). The recommended alteplase dose is a 50-mg intravenous bolus, repeated in 15 minutes if needed (Answer A is correct; Answer C is incorrect). Although surgical embolectomy would be reasonable in the operating room, systemic thrombolytics would be preferred, given the patient’s current location in the ICU (Answer B is incorrect).", "page": 6, "answerPage": 45, "stemZh": "準備執行上述治療時，R.M. 發生 PEA cardiac arrest。仍在 ICU，處理 PE 的最佳介入為何？", "contextZh": "R.M.，78 歲男性（87 kg），alcoholic cirrhosis、portal hypertension；因 variceal hemorrhage（現已穩定）與 respiratory failure 住 urban academic ICU。第 5 天 hypoxemia（原書列 PaO2 78%），需增加 ventilator FiO2。CTA 顯示 main pulmonary artery bifurcation 多處 filling defects，疑 saddle PE。HR 142/min（sinus tachycardia）、BP 97/62 mm Hg；TTE 見 RV hypokinesis、tricuspid regurgitation，troponin I 0.6 ng/mL、troponin T 0.2 ng/mL 陽性。", "optionsZh": [{"key": "A", "text": "Alteplase 50 mg IV push 一次"}, {"key": "B", "text": "立即 surgical embolectomy"}, {"key": "C", "text": "Alteplase 100 mg 輸注 2 小時"}, {"key": "D", "text": "停止 CPR"}], "explanationZh": "教材建議已確診 PE 導致 cardiac arrest 時，alteplase 50 mg IV bolus，必要時 15 分鐘後重複。此緊急救命情境會重新衡量通常的 thrombolysis contraindications。"}, {"id": "16-self-09", "chapter": 16, "type": "self", "number": 9, "stem": "K.A. is a 50-year-old man admitted to the neonatal ICU because of a head trauma causing a subarachnoid hemorrhage. On ICU day 3, his blood pressure is 70/50 mm Hg, and he is mechanically ventilated. K.A. was resuscitated with a normal saline bolus, and norepinephrine was initiated. A TTE reveals RV dilation and tricuspid regurgitation, and a CT scan reveals a filling defect within the pulmonary arteries, dilatation of the right ventricle of the heart, and enlargement of the pulmonary artery. K.A.’s condition continues to worsen, and vasopressin is added for refractory shock. Which is the best approach for treatment of K.A.’s shock?", "context": "", "options": [{"key": "A", "text": "Place an inferior vena cava filter.", "sourceKey": "A"}, {"key": "B", "text": "Administer alteplase 100 mg infused over 2 hours.", "sourceKey": "B"}, {"key": "C", "text": "Administer alteplase 50 mg infused over 2 hours.", "sourceKey": "C"}, {"key": "D", "text": "Consult for possible catheter-directed thrombolysis. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 777", "sourceKey": "D"}], "answer": "D", "explanation": "This patient is experiencing a high-risk or massive PE, as evidenced by a confirmed CT scan, clinical signs consistent with a PE, and a dilated right ventricle on TTE in the setting of sustained hypotension requiring norepinephrine. Although an inferior vena cava filter may prevent additional embolization, it will not limit the growth or cause lysis of the current clot burden associated with his PE (Answer A is incorrect). For a high-risk or massive PE, administration of systemic thrombolytic agents is recommended unless contraindications are present. Because this patient had a recent subarachnoid hemorrhage, the risk of systemic thrombolytic therapy might outweigh the potential benefit (Answer B is incorrect), even at a reduced dose (Answer C is incorrect). Therefore, the CHEST guidelines recommend CDT for patients who are hemodynamically unstable from a PE but have a high bleeding risk (Answer D is correct).", "page": 6, "answerPage": 45, "stemZh": "K.A.，50 歲男性，頭部創傷合併 SAH，ICU 第 3 天 BP 70/50 mm Hg，使用 MV、normal saline、norepinephrine。TTE 見 RV dilation、tricuspid regurgitation；CT 見 pulmonary artery filling defect 與 RV、pulmonary artery 擴大。惡化後加 vasopressin。最佳 shock 治療方式？", "contextZh": "", "optionsZh": [{"key": "A", "text": "放置 inferior vena cava filter"}, {"key": "B", "text": "Alteplase 100 mg 輸注 2 小時"}, {"key": "C", "text": "Alteplase 50 mg 輸注 2 小時"}, {"key": "D", "text": "會診評估 catheter-directed thrombolysis"}], "explanationZh": "確診 PE 且持續 hypotension 為 high-risk PE；近期 SAH 有很高 systemic thrombolysis 出血風險，教材答案為評估 CDT。IVC filter 不能溶解現存 thrombus。"}, {"id": "16-case-01", "chapter": 16, "type": "case", "number": 1, "stem": "A 67-year-old man is accidentally shot in the buttocks while deer hunting with his friends. He is brought to the ED immediately. While in transfer, the patient receives 500 mL of lactated Ringer solution. His vital signs on admission to the ED are as follows: blood pressure 104/58 mm Hg, heart rate 108 beats/minute, respiratory rate 22 breaths/minute, and temperature 95°F (35°C). On examination, he has 8/10 pain and appears anxious. Which is best for resuscitation strategies?", "context": "", "options": [{"key": "A", "text": "Administer lactated Ringer solution at 1000 mL/hour to maintain a urinary output greater than 30 mL/ hour and an SBP greater than 100 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "Transfuse 2 units of PRBCs and administer a 1-L bolus of lactated Ringer solution to maintain a urinary output greater than 1 mL/kg/hour.", "sourceKey": "B"}, {"key": "C", "text": "Transfuse 2 units of PRBCs, 2 units of fresh frozen plasma, and a 1-L bolus of lactated Ringer solution to normal mentation.", "sourceKey": "C"}, {"key": "D", "text": "Administer lactated Ringer solution at 1000 mL/hour to maintain a urinary output greater than 30 mL/ hour, an SBP greater than 80–90 mm Hg, and normal mentation.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient has class II hemorrhagic shock caused by penetrating trauma (heart rate greater than 100 beats/ minute, respiratory rate 20–30 breaths/minute, and anxious on examination). The appropriate resuscitation strategy should focus on selecting the fluid, volume, and resuscitation goal. Recommended end points for resuscitation include SBP greater than 90 mm Hg, urinary output greater than 30 mL/hour, and normal mentation. Administering fluid to target an SBP greater than 90 mm Hg would be appropriate (Answer A is incorrect). Blood products for transfusion are indicated when the patient’s estimated blood loss is greater than 30% (Answers B and C are incorrect because the patient has class II hemorrhagic shock). Given his hemorrhagic shock class, the patient may be initially managed with crystalloid boluses targeting a urinary output greater than 30 mL/hour, an SBP greater than 90 mm Hg, and normal mentation (Answer D is correct).", "page": 15, "answerPage": 42, "stemZh": "67 歲男性狩獵時臀部中彈，轉送已給 lactated Ringer solution 500 mL。到 ED：BP 104/58 mm Hg、HR 108/min、RR 22/min、95°F（35°C），疼痛 8/10、焦慮。最佳 resuscitation 策略？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Lactated Ringer solution 1000 mL/hour，目標 UOP >30 mL/hour、SBP >100 mm Hg"}, {"key": "B", "text": "PRBCs 2 units 與 lactated Ringer solution 1 L bolus，目標 UOP >1 mL/kg/hour"}, {"key": "C", "text": "PRBCs 2 units、FFP 2 units、lactated Ringer solution 1 L bolus，目標意識正常"}, {"key": "D", "text": "Lactated Ringer solution 1000 mL/hour，目標 UOP >30 mL/hour、SBP >80–90 mm Hg、意識正常"}], "explanationZh": "符合 class II hemorrhage，可先用 crystalloid，依尿量、permissive hypotension 與意識調整；此程度失血尚未必需要血品。"}, {"id": "16-case-02", "chapter": 16, "type": "case", "number": 2, "stem": "A 29-year-old man (height 72 inches, weight 85 kg) is admitted to the burn unit with a 40% TBSA burn to the lower extremities and buttocks after a fall into a molten slag at work in a steel mill. He received 500 mL of normal saline during transfer to the hospital. On his presentation to the burn unit, the surgical resident asks for your help in calculating the patient’s fluid resuscitation needs. Which is best for resuscitation?", "context": "", "options": [{"key": "A", "text": "15 L of lactated Ringer solution over 24 hours; initiate at 1000 mL/hour for the first 12 hours, followed by 250 mL/hour, titrating to goal urinary output of 1 mL/kg/hour.", "sourceKey": "A"}, {"key": "B", "text": "13 L of lactated Ringer solution over 24 hours; initiate at 813 mL/hour for the first 8 hours, followed by 406 mL/hour, titrating to goal urinary output of 0.5 mL/kg/hour.", "sourceKey": "B"}, {"key": "C", "text": "12 L of lactated Ringer solution over 12 hours; initiate at 1000 mL/hour, titrating to goal urinary output of 0.5 mL/kg/hour.", "sourceKey": "C"}, {"key": "D", "text": "24 L of lactated Ringer solution over the first 24 hours; initiate at 1000 mL/hour, titrating to goal urinary output of 0.5 mL/kg/hour.", "sourceKey": "D"}], "answer": "B", "explanation": "Using the Parkland formula for burn resuscitation, the 24-hour fluid requirement would be 13.6 L, to be segmented into the first 8 hours of resuscitation and the remaining 16 hours. Calculating fluid requirements according to weight and TBSA to target a urinary output of greater than 0.5 mL/kg/hour would be correct (Answers A, C, and D are incorrect). Answer B is correct because the total volume requirement accounting for prehospital fluid, titration of fluid rates, and target urinary output are appropriate.", "page": 16, "answerPage": 42, "stemZh": "29 歲男性（72 inches、85 kg）工作時掉入 molten slag，下肢與臀部 40% TBSA burn，轉送已給 normal saline 500 mL。最佳 fluid resuscitation 計畫？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Lactated Ringer solution 15 L/24 小時：前 12 小時 1000 mL/hour，再 250 mL/hour；UOP 1 mL/kg/hour"}, {"key": "B", "text": "Lactated Ringer solution 13 L/24 小時：前 8 小時 813 mL/hour，再 406 mL/hour；UOP 0.5 mL/kg/hour"}, {"key": "C", "text": "Lactated Ringer solution 12 L/12 小時，1000 mL/hour；UOP 0.5 mL/kg/hour"}, {"key": "D", "text": "Lactated Ringer solution 24 L/24 小時，1000 mL/hour；UOP 0.5 mL/kg/hour"}], "explanationZh": "Parkland formula = 4 mL × 85 kg × 40 = 13.6 L/24 小時。扣除院前 500 mL，分前 8 小時與後 16 小時給予，依 UOP >0.5 mL/kg/hour 調整。"}, {"id": "16-case-03", "chapter": 16, "type": "case", "number": 3, "stem": "Which is the best initial resuscitation strategy to manage his hypotension?", "context": "D.R. is a 37-year-old man with an unknown medical history who presents after a helmeted motorcycle collision into a deer. On primary survey, his endotracheal tube is secured, respiratory rate is 37 breaths/minute, SBP is 72 mm Hg, heart rate is 141 beats/minute, and Glasgow Coma Scale score is 5T. His FAST examination is positive. A massive transfusion protocol is initiated, and the patient is taken to the operating room for an emergency exploratory laparotomy.", "options": [{"key": "A", "text": "Initiate a sodium chloride (0.9%) 3000-mL bolus to maintain a MAP over 65 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "Obtain an Hgb concentration to guide erythrocyte transfusions, with goal Hgb 7–9 g/dL.", "sourceKey": "B"}, {"key": "C", "text": "Initiate a norepinephrine infusion to maintain an SBP goal of 80–90 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "Initiate PBRCs, plasma, and platelets in a 1:1:1 ratio on the basis of clinical examination.", "sourceKey": "D"}], "answer": "D", "explanation": "Given this patient’s hemodynamic parameters in a positive FAST examination, he will likely require a massive transfusion, as assessed by the ABC (Assessments of Blood Consumption) score for a massive transfusion protocol, which should be initiated promptly. A fixed ratio of 1:1:1 PRBC, plasma, and platelets is more likely to achieve hemostasis and lower mortality from exsanguination at 24 hours than is 2:1:1 (Answer D is correct). Although fluid resuscitation is an adjunct to increase intravascular volume and tissue perfusion, 0.9% sodium chloride does not increase oxygen-carrying capacity, and total volume should be minimized to less than 1.5 L (Answer A is incorrect). In a traumatic hemorrhage, a normal hemoglobin likely will not reflect the extent of blood loss secondary to hemoconcentration until capillary recruitment is complete or resuscitation begins. In addition, resuscitation efforts in a hemodynamically unstable patients should not be delayed while awaiting laboratory results (Answer B is incorrect). Although vasopressors may be considered an adjunct to maintain tissue perfusion while minimizing fluid volume, this strategy should be reserved for those with life-threatening hypotension despite resuscitation efforts (Answer C is incorrect).", "page": 22, "answerPage": 42, "stemZh": "此病人 hypotension 的最佳初始 resuscitation 策略？", "contextZh": "D.R.，37 歲男性，病史未知，戴安全帽騎車撞鹿。已固定 endotracheal tube，RR 37/min、SBP 72 mm Hg、HR 141/min、GCS 5T；FAST 陽性，啟動 massive transfusion，準備 emergency exploratory laparotomy。", "optionsZh": [{"key": "A", "text": "0.9% sodium chloride 3000 mL bolus，MAP >65 mm Hg"}, {"key": "B", "text": "先取得 Hgb 再決定 erythrocyte transfusion，Hgb 7–9 g/dL"}, {"key": "C", "text": "Norepinephrine infusion，SBP 80–90 mm Hg"}, {"key": "D", "text": "依臨床評估啟動 PRBCs、plasma、platelets = 1:1:1"}], "explanationZh": "不穩定生命徵象與 FAST 陽性支持立即 massive transfusion；1:1:1 有助 hemostasis。急性失血的 Hgb 可能尚未反映程度，不應等檢驗才開始輸血。"}, {"id": "16-case-04", "chapter": 16, "type": "case", "number": 4, "stem": "In the operating room, the patient is found to have grade 5 hepatic laceration and grade IV spleen injury status after perihepatic packing and splenectomy. His abdomen is left open with a wound vacuum-assisted closure, and he is taken to the ICU. On arrival to the ICU (5 hours after injury), an arterial blood gas reveals a pH 7.18, partial pressure of carbon dioxide 22 mm Hg, lactate 12.7 g/dL, and Pao2 of 86% on 40% Fio2 with assist control ventilation. He has received 14 units of erythrocytes, 12 units of plasma, and 12 units of platelets. His laboratory values include aPTT 37 seconds, INR 1.3, Hgb 7.5 g/dL, and Plt 154,000/mm3. His temperature is 99°F (37.2°C) and ionized calcium is 0.7 mmol/L. Which is the best pharmacologic treatment strategy to manage his ongoing hemorrhagic shock in a goal-directed fashion?", "context": "D.R. is a 37-year-old man with an unknown medical history who presents after a helmeted motorcycle collision into a deer. On primary survey, his endotracheal tube is secured, respiratory rate is 37 breaths/minute, SBP is 72 mm Hg, heart rate is 141 beats/minute, and Glasgow Coma Scale score is 5T. His FAST examination is positive. A massive transfusion protocol is initiated, and the patient is taken to the operating room for an emergency exploratory laparotomy.", "options": [{"key": "A", "text": "Infuse 150 mEq of sodium bicarbonate in 1 L of sterile water at 200 mL/hour.", "sourceKey": "A"}, {"key": "B", "text": "Give 1 g of calcium chloride once infused over 1 hour.", "sourceKey": "B"}, {"key": "C", "text": "Give rFVIIa 90 mcg/kg once intravenous push.", "sourceKey": "C"}, {"key": "D", "text": "Give a tranexamic acid 1000-mg bolus and 1000 mg infused over 8 hours. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 793", "sourceKey": "D"}], "answer": "B", "explanation": "Acute hypocalcaemia is a common complication in a massive transfusion secondary to citrate added to stored blood. Calcium is essential for stabilization of fibrin, and low ionized calcium concentrations in traumatic hemorrhage are associated with increased mortality. Therefore, ionized calcium concentrations should be maintained within the normal range (Answer B is correct). Evidence is insufficient to recommend sodium bicarbonate therapy in patients with acute trauma and has the potential for increased mortality. The patient’s acidosis should be corrected by addressing the underlying cause – in this case, hemorrhage (Answer A is incorrect). Use of rFVIIa should only be considered if major bleeding and persistent traumatic coagulopathy persist despite best practice, inconsistent with the patient’s current condition. In addition, a pH less than 7.2 is a predictor of a poor response to rFVIIa (Answer C is incorrect). Unfortunately, this patient’s injury was 5 hours ago, and he has no laboratory evidence of hyperfibrinolysis. In this setting, tranexamic acid does not improve mortality after 3 hours from injury and has been associated with an increased risk of death from bleeding (Answer D is incorrect).", "page": 22, "answerPage": 42, "stemZh": "病人手術見 grade 5 hepatic laceration、grade IV spleen injury，完成 packing、splenectomy，以 wound VAC 暫時關腹。受傷 5 小時後入 ICU：pH 7.18、PCO2 22 mm Hg、lactate 12.7 g/dL（教材原值）、PaO2 86%（教材原值）、FiO2 40%。已給 erythrocytes 14 units、plasma 12 units、platelets 12 units。aPTT 37 秒、INR 1.3、Hgb 7.5 g/dL、Plt 154,000/mm3、99°F（37.2°C）、ionized calcium 0.7 mmol/L。最佳 goal-directed 藥物處置？", "contextZh": "D.R.，37 歲男性，病史未知，戴安全帽騎車撞鹿。已固定 endotracheal tube，RR 37/min、SBP 72 mm Hg、HR 141/min、GCS 5T；FAST 陽性，啟動 massive transfusion，準備 emergency exploratory laparotomy。", "optionsZh": [{"key": "A", "text": "Sodium bicarbonate 150 mEq/1 L sterile water，以 200 mL/hour 輸注"}, {"key": "B", "text": "Calcium chloride 1 g，一次輸注 1 小時"}, {"key": "C", "text": "rFVIIa 90 mcg/kg IV push 一次"}, {"key": "D", "text": "Tranexamic acid 1000 mg bolus，再 1000 mg 輸注 8 小時"}], "explanationZh": "Massive transfusion 的 citrate 可造成 hypocalcemia，且 calcium 對 fibrin 穩定重要。應矯正 ionized calcium。已超過受傷 3 小時，不宜依此情境新增 tranexamic acid。"}, {"id": "16-case-05", "chapter": 16, "type": "case", "number": 5, "stem": "A 54-year-old man with an unknown medical history presents after a rollover automobile accident. On primary survey, his respiratory rate is 34 breaths/minute, SBP is 79 mm Hg, and Glasgow Coma Scale score is 3. The FAST examination is positive, a massive transfusion protocol is initiated, and the patient is taken to the operating room for an emergency exploratory laparotomy. In the operating room, he is found to have grade 5 splenic injury, so the spleen is removed. Four hours after admission, he has received 14 units of PRBCs, 12 units of fresh frozen plasma, and 10 units of platelets. His laboratory values include aPTT 66 seconds, INR 1.7, fibrinogen 176 mg/dL, Plt 160,000/mm3, and ionized calcium 1.1 mmol/L. The TEG is normal except for an LY30 of 0% (normal 0.8%–8%). The patient’s wife arrives at the hospital and clarifies that he was out for a Sunday afternoon ride. She also shares that the patient has a history of atrial fibrillation and takes dabigatran (last dose this morning). Which is the best pharmacologic treatment of his ongoing hemorrhagic shock?", "context": "", "options": [{"key": "A", "text": "Administer 4F-PCC 50 units/kg.", "sourceKey": "A"}, {"key": "B", "text": "Administer a tranexamic acid 1-g bolus with 1-g infusion over 8 hours.", "sourceKey": "B"}, {"key": "C", "text": "Administer an idarucizumab 5-g intravenous push.", "sourceKey": "C"}, {"key": "D", "text": "Administer an idarucizumab 5-g intravenous push and a tranexamic acid 1-g bolus, followed by 1 g infused over 8 hours.", "sourceKey": "D"}], "answer": "C", "explanation": "At this point, ongoing resuscitation should be goal directed. The TEG reveals hypofibrinolysis or “shutdown,” not hyperfibrinolysis for which tranexamic acid is expected to help. In addition, if there was no TEG to evaluate for hypofibrinolysis, tranexamic acid should be administered within the first 3 hours from injury, and this patient’s injuries occurred more than 4 hours earlier (Answers B and D are incorrect). With the updated history that the patient was taking dabigatran preinjury, dabigatran is likely contributing to the patient’s ongoing ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 813 coagulopathy and hemorrhage. A normal TEG and elevated aPTT may not rule out the presence of dabigatran. In addition, it seems the patient took the last dabigatran dose within the previous 12 hours. Therefore, dabigatran reversal is indicated. Idarucizumab is FDA approved for dabigatran reversal and recommended in various guidelines, whereas PCCs have weak supporting evidence and are recommended only if idarucizumab is unavailable (Answer C is correct; Answer A is incorrect).", "page": 30, "answerPage": 42, "stemZh": "54 歲男性車禍，RR 34/min、SBP 79 mm Hg、GCS 3、FAST 陽性，啟動 massive transfusion，手術移除 grade 5 損傷脾臟。入院 4 小時已給 PRBCs 14 units、FFP 12 units、platelets 10 units。aPTT 66 秒、INR 1.7、fibrinogen 176 mg/dL、Plt 160,000/mm3、ionized calcium 1.1 mmol/L；TEG 除 LY30 0%（正常 0.8%–8%）外正常。妻子告知病人有 AF，今早服過 dabigatran。最佳持續 hemorrhagic shock 藥物處置？", "contextZh": "", "optionsZh": [{"key": "A", "text": "4F-PCC 50 units/kg"}, {"key": "B", "text": "Tranexamic acid 1 g bolus，再 1 g 輸注 8 小時"}, {"key": "C", "text": "Idarucizumab 5 g IV push"}, {"key": "D", "text": "Idarucizumab 5 g IV push，加 tranexamic acid 1 g bolus，再 1 g 輸注 8 小時"}], "explanationZh": "Idarucizumab 可特異逆轉 dabigatran。LY30 0% 為 fibrinolytic shutdown，且已超過受傷 3 小時，不支持新增 tranexamic acid。"}, {"id": "16-case-06", "chapter": 16, "type": "case", "number": 6, "stem": "B.P is a 76-year-old man (120 kg) with atrial fibrillation on warfarin admitted to the ED with weakness and hematemesis. Pertinent vital signs on admission are as follows: blood pressure 79/52 mm Hg, heart rate 136 beats/minute with a rhythm of sinus tachycardia, and respiratory rate 26 breaths/minute. Frank red blood is noted on nasogastric lavage. On physical examination, the patient is confused, with clammy extremities. Pertinent laboratory values are as follows: Hgb 6.3 g/dL, INR 9.2, and Plt 300,000/mm3. In addition to intravenous phytonadione, which therapy is most appropriate for managing warfarin reversal in this patient?", "context": "", "options": [{"key": "A", "text": "4F-PCC 1000 units.", "sourceKey": "A"}, {"key": "B", "text": "4F-PCC 5000 units.", "sourceKey": "B"}, {"key": "C", "text": "rFVIIa 1-mg intravenous push.", "sourceKey": "C"}, {"key": "D", "text": "4F-PCC 6000 units.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient has an acute GI hemorrhage complicated by supratherapeutic INR warfarin and hemodynamic instability necessitating warfarin reversal with 4F-PCC. Given his weight and degree of INR elevation, the package insert dose is 50 units/kg not to exceed 5000 units (Answer B is correct; Answer D is incorrect). Although fixed, low-dose PCC has been evaluated for warfarin reversal, this dose is off-label and supported by a lower quality of evidence. In addition, the 1000-unit dose has shown lower achievement of a goal INR, necessitating rescue doses, and a low dose would probably not achieve adequate laboratory reversal, given his weight and excessively high INR (Answer A is incorrect). Finally, although rFVIIa lowers INR, it is no longer recommended for the reversal of vitamin K antagonists, given the incomplete correction of factors II, IX, and X and the possibility that the INR does not reflect the patient’s underlying coagulopathy (Answer C is incorrect).", "page": 30, "answerPage": 43, "stemZh": "B.P.，76 歲男性（120 kg），AF 使用 warfarin，虛弱與吐血。BP 79/52 mm Hg、HR 136/min、RR 26/min，鮮血胃液、意識混亂與四肢濕黏；Hgb 6.3 g/dL、INR 9.2、Plt 300,000/mm3。除 IV phytonadione 外，最佳 warfarin reversal 為何？", "contextZh": "", "optionsZh": [{"key": "A", "text": "4F-PCC 1000 units"}, {"key": "B", "text": "4F-PCC 5000 units"}, {"key": "C", "text": "rFVIIa 1 mg IV push"}, {"key": "D", "text": "4F-PCC 6000 units"}], "explanationZh": "INR >6 時 4F-PCC 50 units/kg，但最大 5000 units；不能按 120 kg 計算後超過上限。rFVIIa 不完整補足 warfarin 抑制的凝血因子。"}, {"id": "16-case-07", "chapter": 16, "type": "case", "number": 7, "stem": "A 48-year-old woman (weight 75 kg) presents to the ED with shortness of breath. The patient’s hypoxemia does not improve with supplemental oxygen, and her chest radiograph is not significant for any lung abnormalities. A contrasted chest CT scan reveals a PE in the subsegmental branch of the right pulmonary artery and no RV dilation. The patient’s vital signs and significant laboratory values are as follows: heart rate 118 beats/minute, blood pressure 98/62 mm Hg, urinary output 1 mL/kg/hour, troponin T 0.06 ng/mL, brain natriuretic peptide 60 pg/mL, lactate 0.9 mmol/L, and SCr 1.1 mg/dL. In addition to initiating a parenteral anticoagulant, which is best for the patient?", "context": "", "options": [{"key": "A", "text": "Tenecteplase 40-mg bolus.", "sourceKey": "A"}, {"key": "B", "text": "Alteplase 100-mg infusion over 2 hours.", "sourceKey": "B"}, {"key": "C", "text": "Alteplase 50-mg bolus.", "sourceKey": "C"}, {"key": "D", "text": "No thrombolytic therapy.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient has evidence of a PE, but she lacks features of an increased risk of early mortality from it. She does not have shock or evidence of end-organ hypoperfusion and thus does not have a massive PE. In addition, she has no evidence of RV dysfunction (no RV dilation on chest CT, brain natriuretic peptide less than 90 pg/mL) or myocardial necrosis (troponin less than 0.1 mg/mL) and thus does not have a submassive PE. The patient is best classified as having a low-risk PE. A meta-analysis suggested that thrombolytics do not decrease mortality in unselected (and low risk) patients and may increase bleeding risk (Answer D is correct; Answers A–C are incorrect).", "page": 37, "answerPage": 43, "stemZh": "48 歲女性（75 kg）呼吸困難，給氧仍 hypoxemia，CXR 無明顯異常。CT 見右 pulmonary artery subsegmental PE、無 RV dilation。HR 118/min、BP 98/62 mm Hg、UOP 1 mL/kg/hour、troponin T 0.06 ng/mL、BNP 60 pg/mL、lactate 0.9 mmol/L、SCr 1.1 mg/dL。除 parenteral anticoagulant 外，最佳處置？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Tenecteplase 40 mg bolus"}, {"key": "B", "text": "Alteplase 100 mg 輸注 2 小時"}, {"key": "C", "text": "Alteplase 50 mg bolus"}, {"key": "D", "text": "不使用 thrombolytic therapy"}], "explanationZh": "無 shock、end-organ hypoperfusion、RV dysfunction 或明顯 myocardial necrosis，教材分類為 low-risk PE；thrombolysis 增加 bleeding risk，未見此族群死亡效益。"}, {"id": "16-case-08", "chapter": 16, "type": "case", "number": 8, "stem": "A 56-year-old man (weight 140 kg) with a history of smoking and chronic obstructive pulmonary disease was admitted to the medical ICU with sudden-onset dyspnea, chest pain, and hypoxemia (Pao2 78%). A chest CTA reveals a subsegmental PE. His blood pressure is 87/56 mm Hg, now requiring norepinephrine. Which is the next best step to evaluate and/or treat his PE?", "context": "", "options": [{"key": "A", "text": "Administer tenecteplase 40-mg intravenous push, followed by a therapeutic heparin infusion.", "sourceKey": "A"}, {"key": "B", "text": "Obtain an echocardiogram and cardiac enzymes to guide further risk stratification.", "sourceKey": "B"}, {"key": "C", "text": "Administer catheter-directed alteplase 1 mg/hour for 12 hours by EKOS EndoWave system catheter.", "sourceKey": "C"}, {"key": "D", "text": "Administer alteplase 100 mg infused over 2 hours, followed by a therapeutic heparin infusion. ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 808", "sourceKey": "D"}], "answer": "D", "explanation": "The patient has a massive or high-risk PE, as evidenced by signs of hemodynamic complications requiring norepinephrine, likely confounded by poor physiologic reserve with chronic obstructive pulmonary disease. The current guidelines recommend systemic thrombolysis in patients with a massive PE and an acceptable risk of bleeding. This patient does not appear to have any obvious risk of bleeding, including age; therefore, systemic thrombolytic agents are indicated in addition to a therapeutic heparin infusion. The most common options include alteplase as a fixed dose of 100 mg infused over 2 hours or tenecteplase adjusted according to patient weight. Because this patient weighs 140 kg, the recommended tenecteplase dose would be a 50-mg intravenous push once (Answer A is incorrect); therefore, alteplase 100 mg infused over 2 hours is the most appropriate answer (Answer D is correct). The 2021 CHEST guidelines state that if thrombolytic agents are indicated, systemic thrombolysis is preferred to catheter-directed thrombolytic administration (Answer C is incorrect). Echocardiogram and cardiac enzymes are not considered necessary to guide therapy in patients with hypotension/shock and a CTA-confirmed PE (Answer B is incorrect). ACCP/ASHP 2024: Critical Care Pharmacy Preparatory Review Course 814", "page": 37, "answerPage": 43, "stemZh": "56 歲男性（140 kg），抽菸與 COPD 病史，突然 dyspnea、胸痛、hypoxemia（教材列 PaO2 78%），CTA 見 subsegmental PE。BP 87/56 mm Hg，需 norepinephrine。下一步最佳評估或治療？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Tenecteplase 40 mg IV push，再 therapeutic heparin infusion"}, {"key": "B", "text": "先做 echocardiogram 與 cardiac enzymes 再分風險"}, {"key": "C", "text": "經 EKOS EndoWave catheter 給 alteplase 1 mg/hour，共 12 小時"}, {"key": "D", "text": "Alteplase 100 mg 輸注 2 小時，再 therapeutic heparin infusion"}], "explanationZh": "需 vasopressor 的 PE 為 massive/high-risk。無明顯 bleeding contraindication，教材選 systemic alteplase。140 kg 的 tenecteplase 對應 50 mg，選項 40 mg 不適當。"}, {"id": "17-self-01", "chapter": 17, "type": "self", "number": 1, "stem": "P.J. has been receiving propofol 50–60 mcg/kg/ minute and fentanyl 75–100 mcg/hour for 4 days. She has no significant medical history. Laboratory results today show that transaminases have increased to 5 times baseline, lactate is increased to 5 mmol/L, and triglyceride concentration is 450 mg/ dL. No new medications have been added. Given these laboratory values, which complication would be most appropriate to address?", "context": "", "options": [{"key": "A", "text": "Deep venous thrombosis (DVT).", "sourceKey": "A"}, {"key": "B", "text": "Critical illness-induced polyneuropathy.", "sourceKey": "B"}, {"key": "C", "text": "Intensive care unit (ICU) delirium.", "sourceKey": "C"}, {"key": "D", "text": "Propofol-related infusion syndrome (PRIS).", "sourceKey": "D"}], "answer": "D", "explanation": "Propofol infusion syndrome is a well-documented and complex set of adverse events, potentially resulting in multiorgan failure. An elevation in lactate, creatine kinase, transaminases, SCr, and triglycerides and the presence of a metabolic acidosis are some of the abnormalities that should concern the critical care provider for the presence of PRIS (Answer D is correct). Both DVT and critical illness polyneuropathy are serious concerns in the ICU patient; however, the abnormalities in the case are not representative of these complications (Answers A and B are incorrect). There are currently no known abnormal laboratory values to help determine whether delirium is present in an ICU patient (Answer C is incorrect).", "page": 4, "answerPage": 53, "stemZh": "P.J. 連續 4 天使用 propofol 50–60 mcg/kg/minute、fentanyl 75–100 mcg/hour，無重要病史，未加新藥。Transaminases 達 baseline 的 5 倍、lactate 5 mmol/L、triglycerides 450 mg/dL。最應處理哪個併發症？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Deep venous thrombosis（DVT）"}, {"key": "B", "text": "Critical illness-induced polyneuropathy"}, {"key": "C", "text": "ICU delirium"}, {"key": "D", "text": "Propofol-related infusion syndrome（PRIS）"}], "explanationZh": "PRIS 可有 lactate、CK、transaminases、SCr、triglycerides 升高與 metabolic acidosis，甚至 multiorgan failure。這些檢驗異常不支持其他選項。"}, {"id": "17-self-02", "chapter": 17, "type": "self", "number": 2, "stem": "T.I. is a 35-year-old man admitted to the ICU for severe alcohol withdrawal. His medical history is otherwise unknown. Laboratory values are within normal limits on admission. He has been receiving a lorazepam infusion 6–8 mg/hour for active alcohol withdrawal. On day 4, his blood pressure is 130/75 mm Hg, oxygen saturation is 98% on 2 L of oxygen, blood urea nitrogen (BUN) is 50 mg/dL, and serum creatinine (SCr) is 2.0 mg/dL; he has a new anion gap of 20 mEq/L, an osmolar gap of 18 mmol/L H 2 O, and a fractional excretion of sodium of 0.2. Which is the most likely cause for his clinical presentation?", "context": "", "options": [{"key": "A", "text": "Acute respiratory distress syndrome (ARDS).", "sourceKey": "A"}, {"key": "B", "text": "Propylene glycol toxicity.", "sourceKey": "B"}, {"key": "C", "text": "Delirium tremens.", "sourceKey": "C"}, {"key": "D", "text": "Acute tubular necrosis.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient is at risk of propylene glycol toxicity after receiving a lorazepam drip for more than 48 hours. Lorazepam is dissolved in propylene glycol, an alcohol that can induce an osmolar gap and metabolic lactic acidosis, particularly in patients with significant hepatic or renal failure. Quantitative propylene glycol levels may be unavailable; therefore, surrogate markers such as an abnormal osmolar gap (greater than 10 mmol) and metabolic acidosis may indicate propylene glycol toxicity and a need to discontinue lorazepam. Although lorazepam drips are not routinely used for general sedation in adult ICUs, they may be used for other indications (e.g., severe EtOH [ethyl alcohol] or benzodiazepine withdrawal), and clinicians should remain aware of this serious complication (Answer B is correct). With an oxygen saturation of 98% on 2 L of oxygen, this patient does not meet the predefined criteria of ARDS (Answer A is incorrect). Encephalopathy will not cause a metabolic acidosis; therefore, an ammonia concentration would not be helpful at this stage (Answer C is incorrect). With a low fractional excretion of sodium and a high BUN/SCr ratio, the patient’s laboratory values are indicative of a pre-renal concern versus acute tubular necrosis (Answer D is incorrect).", "page": 4, "answerPage": 53, "stemZh": "T.I.，35 歲男性，因 severe alcohol withdrawal 入 ICU，入院檢驗正常，使用 lorazepam infusion 6–8 mg/hour。第 4 天 BP 130/75 mm Hg、2 L oxygen 下 SpO2 98%、BUN 50 mg/dL、SCr 2.0 mg/dL、anion gap 20 mEq/L、osmolar gap 18 mmol/L H2O、FENa 0.2。最可能原因？", "contextZh": "", "optionsZh": [{"key": "A", "text": "ARDS"}, {"key": "B", "text": "Propylene glycol toxicity"}, {"key": "C", "text": "Delirium tremens"}, {"key": "D", "text": "Acute tubular necrosis"}], "explanationZh": "高劑量持續 lorazepam 的溶劑 propylene glycol 可引起 osmolar gap、lactic acidosis 與 renal injury；超過 48 小時輸注應留意。低 FENa 與高 BUN/SCr 比不支持 ATN。"}, {"id": "17-self-03", "chapter": 17, "type": "self", "number": 3, "stem": "R.B. is a 25-year-old man admitted to the ICU for acute pancreatitis and sepsis. He is intermittently agitated on hydromorphone 2 mg/hour and midazolam 6 mg/hour (Richmond Agitation-Sedation Scale [RASS] score of –1 to +2) and is not oxygenating adequately after adjustments on the ventilator. The physician would like to initiate therapeutic paralysis. Which is the next best step in the treatment of this patient?", "context": "", "options": [{"key": "A", "text": "Spontaneous awakening and breathing trials.", "sourceKey": "A"}, {"key": "B", "text": "Cisatracurium infusion.", "sourceKey": "B"}, {"key": "C", "text": "Intermittent vecuronium.", "sourceKey": "C"}, {"key": "D", "text": "Sedate the patient to a “deeply sedated” clinical state.", "sourceKey": "D"}], "answer": "D", "explanation": "It is inappropriate to initiate an NMBA in a patient who has a sedation score indicating “agitation.” This implies that the patient may potentially detect pain or discomfort while paralyzed (Answers B and C are incorrect). The goal should be to achieve a deeply sedated and/or nonagitated state before initiating an NMBA in an effort to avoid any patient discomfort that may be undetected during paralysis (Answer D is correct). The SAT would be inappropriate in someone who is rated “agitated” on the sedation scale or in a patient requiring escalating doses of sedation (Answer A is incorrect).", "page": 4, "answerPage": 53, "stemZh": "R.B.，25 歲男性，acute pancreatitis、sepsis。Hydromorphone 2 mg/hour、midazolam 6 mg/hour 下仍間歇 agitation（RASS −1 至 +2），調整 ventilator 後氧合仍不足。醫師想啟動 paralysis。下一步最佳處置？", "contextZh": "", "optionsZh": [{"key": "A", "text": "SAT 與 SBT"}, {"key": "B", "text": "Cisatracurium infusion"}, {"key": "C", "text": "間歇 vecuronium"}, {"key": "D", "text": "先使病人達 deep sedation"}], "explanationZh": "NMBA 不提供 analgesia 或 sedation；在 agitation 尚未控制時 paralysis 會造成無法表達的不適，應先確保 deep sedation 與 analgesia。"}, {"id": "17-self-04", "chapter": 17, "type": "self", "number": 4, "stem": "P.V. is a 70-year-old woman (weight 50 kg, decreased from 60 kg 2 months ago) admitted to the ICU in ARDS. She has a history of cirrhosis and is currently fluid overloaded (net positive 5 L). She has been on a continuous infusion of fentanyl and propofol for 5 days. Which pharmacologic factor would best be considered with respect to her analgesics or sedatives?", "context": "", "options": [{"key": "A", "text": "Risk of PRIS in patients with ARDS.", "sourceKey": "A"}, {"key": "B", "text": "Unpredictable clearance of fentanyl.", "sourceKey": "B"}, {"key": "C", "text": "Enzymatic induction of fentanyl by propofol.", "sourceKey": "C"}, {"key": "D", "text": "Hypocalcaemia secondary to extended use of propofol.", "sourceKey": "D"}], "answer": "B", "explanation": "The pharmacokinetics/dynamics of prolonged fentanyl infusions have not been well described in the adult ICU population. Most data for fentanyl are derived from short-term infusions or boluses in healthy volunteers and in animal models. Fentanyl is hepatically metabolized primarily by the CYP3A4 enzyme, and decreased clearance of fentanyl has been described in patients with significant liver disease. Other properties of fentanyl (e.g., high volume of distribution, high protein binding, and high lipophilicity) may contribute to unpredictable clearance and a prolonged context-sensitive half-time for patients in acute renal failure or in patients who have inadequate nutritional status (Answer B is correct). Propofol is a CYP3A4 inhibitor; therefore, it should not induce the metabolism of fentanyl (Answer C is incorrect). Propofol is known to chelate trace elements and increase urinary loss of zinc when used for more than 5 days; propofol has not been shown to cause hypocalcemia (Answer D is incorrect). Disease states identified as risk factors for PRIS may include sepsis, acute liver failure, and history of pancreatitis; ARDS is not currently a documented risk factor (Answer A is incorrect).", "page": 5, "answerPage": 53, "stemZh": "P.V.，70 歲女性，50 kg（2 個月前 60 kg），ARDS、cirrhosis，fluid balance +5 L，已持續 fentanyl、propofol 5 天。最需考量的藥理因素？", "contextZh": "", "optionsZh": [{"key": "A", "text": "ARDS 病人的 PRIS risk"}, {"key": "B", "text": "Fentanyl clearance 不易預測"}, {"key": "C", "text": "Propofol 對 fentanyl 的 enzyme induction"}, {"key": "D", "text": "長期 propofol 導致 hypocalcemia"}], "explanationZh": "肝病、營養不良、fluid overload、fentanyl 的高 Vd、protein binding、lipophilicity 使 prolonged infusion 的 clearance 與 context-sensitive half-time 不易預測。Propofol 不是 CYP3A4 inducer。"}, {"id": "17-self-05", "chapter": 17, "type": "self", "number": 5, "stem": "L.B. is a 38-year-old woman intubated in the neurosurgery ICU for 72 hours receiving propofol. The nurse is requesting medications for “severe agitation and hallucinations.” Her heart rate and blood pressure have steadily increased since admission, and a chart review reveals years of chronic pain while receiving oxycodone and tramadol at home. Her laboratory values are normal, but she is not tolerating enteral-route medications. Which is the most appropriate recommendation at this time?", "context": "", "options": [{"key": "A", "text": "Quetiapine as needed for agitation.", "sourceKey": "A"}, {"key": "B", "text": "Fentanyl infusion.", "sourceKey": "B"}, {"key": "C", "text": "Lorazepam as needed for agitation.", "sourceKey": "C"}, {"key": "D", "text": "Hydromorphone patient-controlled analgesia.", "sourceKey": "D"}], "answer": "B", "explanation": "Withdrawal from certain home medications may occur if these medications are not reinitiated within a few days of admission. The onset of withdrawal symptoms will vary depending on the half-life of each medication. Symptoms may include agitation, anxiety, psychosis, insomnia, hypertension, and tachycardia and can occur with medications such as opiates, GABA receptor agonists, antiepileptics, antidepressants, and antipsychotics. A pharmacist can assist the medical team by obtaining a thorough medication history and assessment of home medication compliance to help identify drug withdrawal symptoms. Reinitiating these medications can be considered unless contraindicated because of the clinical scenario (e.g., drug-drug interactions, drugdisease state interactions). The Agitation and Sedation section of the PADIS guidelines discusses identifying and treating the etiology of agitation before adding other medications; fentanyl should treat this patient’s chronic pain and treat opiate/tramadol withdrawal (Answer B is correct). Adding quetiapine or lorazepam for agitation would not address or treat the underlying etiology of potential opiate/tramadol withdrawal (Answers A and C are incorrect). Patient-controlled analgesia with an opiate would help treat opiate withdrawal; however, this patient is not alert enough to use it (Answer D is incorrect).", "page": 5, "answerPage": 53, "stemZh": "L.B.，38 歲女性，neurosurgery ICU 已插管 72 小時，使用 propofol。護理師回報 severe agitation、hallucinations，HR 與 BP 自入院上升。家中長年因 chronic pain 用 oxycodone、tramadol，檢驗正常，目前不能使用 enteral medications。最佳建議？", "contextZh": "", "optionsZh": [{"key": "A", "text": "需要時給 quetiapine"}, {"key": "B", "text": "Fentanyl infusion"}, {"key": "C", "text": "需要時給 lorazepam"}, {"key": "D", "text": "Hydromorphone patient-controlled analgesia"}], "explanationZh": "應辨識可能 opioid/tramadol withdrawal 與疼痛；fentanyl infusion 能處理原因。Quetiapine、lorazepam 不治療 opioid withdrawal，病人也不適合操作 PCA。"}, {"id": "17-self-06", "chapter": 17, "type": "self", "number": 6, "stem": "S.P. has just been intubated in the ICU and is in severe alcohol withdrawal. He has a history of frequent delirium tremens and alcohol withdrawal seizures. Which medication is most appropriate to begin initial management of pain, agitation, and delirium (PAD) in this patient?", "context": "", "options": [{"key": "A", "text": "Dexmedetomidine.", "sourceKey": "A"}, {"key": "B", "text": "Phenytoin.", "sourceKey": "B"}, {"key": "C", "text": "Fentanyl.", "sourceKey": "C"}, {"key": "D", "text": "Midazolam.", "sourceKey": "D"}], "answer": "D", "explanation": "Up to 30%–60% of ICU patients may go through alcohol withdrawal on cessation of alcohol use. The presence of alcohol withdrawal in ICU patients may prolong their ICU stay, increase hospital costs significantly, and lead to other complications during the hospital stay. Early and aggressive symptom-triggered management with a benzodiazepine, particularly in a patient with a history of alcohol withdrawal, is a key element in management. There is no otherwise published protocol for alcohol withdrawal in ICU patients. In this case, although dexmedetomidine is useful as an adjunctive agent to help decrease sympathetic storm and agitation secondary to alcohol withdrawal, it is not currently recommended for use as a single agent for alcohol withdrawal (Answer A is incorrect). Opiates do not treat alcohol withdrawal (Answer C is incorrect). Phenytoin is a known antiepileptic for use in epilepsy; however, it has not been shown to be effective in preventing or treating alcohol withdrawal (Answer B is incorrect). Benzodiazepines are the drugs of choice for alcohol withdrawal seizures; therefore, midazolam is the most appropriate drug for this patient, whose medical history is significant for recurrent alcohol withdrawal seizures (Answer D is correct).", "page": 5, "answerPage": 54, "stemZh": "S.P. 剛插管，severe alcohol withdrawal，常有 delirium tremens 與 alcohol withdrawal seizures。初始 PAD 處理最適當藥物？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dexmedetomidine"}, {"key": "B", "text": "Phenytoin"}, {"key": "C", "text": "Fentanyl"}, {"key": "D", "text": "Midazolam"}], "explanationZh": "Benzodiazepines 為 alcohol withdrawal seizures 的首選。Dexmedetomidine 只能作 adjunct，fentanyl 與 phenytoin 不治療 underlying alcohol withdrawal。"}, {"id": "17-self-07", "chapter": 17, "type": "self", "number": 7, "stem": "H.F., a 65-year-old man admitted to the ICU from home for aspiration pneumonia requiring intubation, is initiated on levofloxacin and metronidazole. Other medications include fentanyl and dexmedetomidine infusions as well as amiodarone, a home medication. His last RASS was -2), and he has intermittent agitation. Vital signs and laboratory values are normal, and corrected QT (QTc) is 550 milliseconds. Which is the most appropriate recommendation at this time?", "context": "", "options": [{"key": "A", "text": "Add quetiapine for agitation, and monitor QTc.", "sourceKey": "A"}, {"key": "B", "text": "Start nonpharmacologic management of agitation/delirium.", "sourceKey": "B"}, {"key": "C", "text": "Discontinue dexmedetomidine because of his prolonged QTc.", "sourceKey": "C"}, {"key": "D", "text": "Give lorazepam as needed for agitation.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient is at risk of delirium given the patient’s age and being critically ill in the ICU. Avoiding medications that may cause or worsen delirium, such as benzodiazepines, is a strong recommendation in the PAD guidelines (Answer D is incorrect). With a QTc of 550 milliseconds, increasing the quetiapine dose for agitation could further increase the QTc and put this patient at high risk of cardiac arrhythmias. Starting quetiapine would not be the best option (Answer A is incorrect). Starting nonpharmacologic management of agitation/delirium is the best option (Answer B is correct). Dexmedetomidine does not prolong the QTc and should be continued in the setting of agitation (Answer C is incorrect).", "page": 5, "answerPage": 54, "stemZh": "H.F.，65 歲男性，aspiration pneumonia 插管，使用 levofloxacin、metronidazole、fentanyl、dexmedetomidine，另有家中 amiodarone。RASS −2，間歇 agitation；生命徵象與檢驗正常，QTc 550 ms。最佳建議？", "contextZh": "", "optionsZh": [{"key": "A", "text": "加 quetiapine 並監測 QTc"}, {"key": "B", "text": "啟動非藥物 agitation/delirium 處置"}, {"key": "C", "text": "因 QTc 延長停止 dexmedetomidine"}, {"key": "D", "text": "需要時给 lorazepam"}], "explanationZh": "QTc 550 ms 應避免再增加 QT-prolonging drugs。先採非藥物處置；benzodiazepines 可惡化 delirium。教材指出 dexmedetomidine 不延長 QTc。"}, {"id": "17-self-08", "chapter": 17, "type": "self", "number": 8, "stem": "S.V., a 70-year-old woman with a history of hypertension, is transferred from the floor to the ICU for worsening pneumonia and new-onset hypoactive delirium. She has been nil per os (NPO) since admission 3 days prior. She remains febrile (temperature 102°F [38.89°C]) with decreased urine output; other vital signs and laboratory values are within normal limits. Her medications include ceftriaxone, heparin, and hydrochlorothiazide. Which best represents the most important set of considerations regarding her delirium?", "context": "", "options": [{"key": "A", "text": "Dementia and sleep disorder.", "sourceKey": "A"}, {"key": "B", "text": "Undetected alcohol withdrawal.", "sourceKey": "B"}, {"key": "C", "text": "Adrenal insufficiency.", "sourceKey": "C"}, {"key": "D", "text": "Dehydration and untreated infection.", "sourceKey": "D"}], "answer": "D", "explanation": "Dementia is a progressive and chronic state of cognitive impairment that worsens over weeks to months; this differs from the acute onset characteristic of ICU delirium (Answer A is incorrect). Alcohol withdrawal should always be a consideration for patients who become altered or agitated in the ICU. This patient’s vital signs are normal, and she is presenting in a hypoactive state; these findings are not typical for acute alcohol withdrawal, and alternative causes for her decline in mental status need to be considered (Answer B is incorrect). Adrenal insufficiency in the ICU usually presents with abnormal laboratory values and/or hemodynamic instability. This patient’s laboratory values and hemodynamics are reported as normal; therefore, adrenal insufficiency is unlikely (Answer C is incorrect). Both iatrogenic and non-iatrogenic causes for delirium are well documented in the literature. Dehydration and infection are common causes of delirium, particularly in the older adult population. This patient has several reasons for being dehydrated in the hospital: NPO status, persistent fevers, and taking hydrochlorothiazide. Untreated infection or lack of source control is also a concern with the presence of persistent fever, even while the patient is taking antibiotics (Answer D is correct).", "page": 5, "answerPage": 54, "stemZh": "S.V.，70 歲女性，hypertension，因 pneumonia 惡化與新發 hypoactive delirium 轉 ICU。入院 3 天 NPO，持續發燒 102°F（38.89°C）、UOP 減少，其他生命徵象與檢驗正常。使用 ceftriaxone、heparin、hydrochlorothiazide。最需考慮的 delirium 原因？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dementia 與 sleep disorder"}, {"key": "B", "text": "未辨識的 alcohol withdrawal"}, {"key": "C", "text": "Adrenal insufficiency"}, {"key": "D", "text": "Dehydration 與未控制的 infection"}], "explanationZh": "NPO、發燒、hydrochlorothiazide 增加 dehydration risk；抗生素治療仍發燒也需考慮 infection 未控制或缺乏 source control。"}, {"id": "17-case-01", "chapter": 17, "type": "case", "number": 1, "stem": "Which grouping of initial sedatives is most appropriate at this time?", "context": "T.O. is a 70-year-old man just admitted to the ICU with multiple fractures after a motor vehicle accident. His medical history includes hypertension. He is now agitated after intubation. His laboratory values are normal, and his vital signs include blood pressure 175/95 mm Hg and heart rate 110 beats/minute.", "options": [{"key": "A", "text": "Fentanyl infusion and midazolam infusion", "sourceKey": "A"}, {"key": "B", "text": "Propofol infusion and fentanyl as needed", "sourceKey": "B"}, {"key": "C", "text": "Midazolam as needed and fentanyl as needed", "sourceKey": "C"}, {"key": "D", "text": "Fentanyl infusion and propofol infusion, if needed", "sourceKey": "D"}], "answer": "D", "explanation": "This patient has a clear indication for intravenous pain medication from his recent trauma and multiple fractures. An “as-needed” opiate would likely not keep up with his pain control needs (Answers B and C are incorrect). His age and history of hypertension place him at risk of delirium; therefore, a benzodiazepine is not the best initial choice for this patient. A fentanyl infusion for pain with a propofol infusion if needed for sedation is the most appropriate answer (Answer A is incorrect; Answer D is correct).", "page": 15, "answerPage": 51, "stemZh": "此時最適當的初始 sedation/analgesia 組合？", "contextZh": "T.O.，70 歲男性，車禍多處骨折，hypertension 病史。插管後 agitation，檢驗正常，BP 175/95 mm Hg、HR 110/min。", "optionsZh": [{"key": "A", "text": "Fentanyl infusion 加 midazolam infusion"}, {"key": "B", "text": "Propofol infusion 加必要時 fentanyl"}, {"key": "C", "text": "必要時 midazolam 與 fentanyl"}, {"key": "D", "text": "Fentanyl infusion，需要時加 propofol infusion"}], "explanationZh": "多處骨折需要持續 analgesia；先給 fentanyl，需要時加 propofol。高齡與 hypertension 增加 delirium risk，benzodiazepine 不為最佳起始選擇。"}, {"id": "17-case-02", "chapter": 17, "type": "case", "number": 2, "stem": "After 2 weeks in the ICU, T.O. is being prepared for chest tube removal. He is currently receiving a fentanyl drip with adequate pain control. Which is the best pain management regimen for chest tube removal?", "context": "T.O. is a 70-year-old man just admitted to the ICU with multiple fractures after a motor vehicle accident. His medical history includes hypertension. He is now agitated after intubation. His laboratory values are normal, and his vital signs include blood pressure 175/95 mm Hg and heart rate 110 beats/minute.", "options": [{"key": "A", "text": "Give intravenous acetaminophen 15 minutes before chest tube removal.", "sourceKey": "A"}, {"key": "B", "text": "Make no change in pain treatment because his current pain regimen is adequate.", "sourceKey": "B"}, {"key": "C", "text": "Increase his pain medication infusion dose by 50% the morning of his chest tube removal.", "sourceKey": "C"}, {"key": "D", "text": "Give fentanyl 50 mcg injectable 15 minutes before chest tube removal.", "sourceKey": "D"}], "answer": "D", "explanation": "Chest tube removal is specifically cited in the PADIS guidelines as an indication for both preemptive analgesia and nonpharmacologic relaxation techniques. This is given a “strong” recommendation, determining that the benefits outweigh the risks of preemptive therapy (Answer D is correct). Acetaminophen given just before the procedure will most likely not adequately treat pain associated with chest tube removal (Answer A is incorrect). Increasing an opiate infusion several hours before a bedside procedure can expose the patient to substantially higher amounts of drug than needed and cause delayed awakening times or other significant adverse effects from opiates (Answer C is incorrect). Extensive studies of appropriate preemptive analgesia for chest tube removal have not been completed; however, administering an opiate appropriately timed before manipulation of a chest tube is an accepted standard of therapy (Answer B is incorrect).", "page": 15, "answerPage": 51, "stemZh": "ICU 2 週後，T.O. 準備移除 chest tube；目前 fentanyl drip 能控制基礎疼痛。最佳 procedure analgesia？", "contextZh": "T.O.，70 歲男性，車禍多處骨折，hypertension 病史。插管後 agitation，檢驗正常，BP 175/95 mm Hg、HR 110/min。", "optionsZh": [{"key": "A", "text": "移除前 15 分鐘給 IV acetaminophen"}, {"key": "B", "text": "維持原 regimen 即可"}, {"key": "C", "text": "當天早上將 infusion dose 增加 50%"}, {"key": "D", "text": "移除前 15 分鐘給 injectable fentanyl 50 mcg"}], "explanationZh": "Chest tube removal 需 preemptive analgesia。適時 fentanyl bolus 比提前數小時增加 infusion 更有針對性，acetaminophen 單用可能不足。"}, {"id": "17-case-03", "chapter": 17, "type": "case", "number": 3, "stem": "A 48-year-old man with cirrhosis and now hepatorenal syndrome was intubated for respiratory distress. He has been receiving midazolam 1 mg/hour and fentanyl 75 mcg/hour for 2 days; his RASS (−4 to −5) and CPOT has been 1 for 24 hours. Oxygen requirements have decreased, and vital signs are normal. Which is the most appropriate change in his medications?", "context": "", "options": [{"key": "A", "text": "Decrease midazolam; give as-needed lorazepam for agitated RASS score.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue midazolam and fentanyl; give as-needed fentanyl for CPOT of 3 or greater.", "sourceKey": "B"}, {"key": "C", "text": "Discontinue midazolam; initiate propofol drip.", "sourceKey": "C"}, {"key": "D", "text": "Change midazolam to dexmedetomidine drip.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient has end-stage liver failure and acute renal failure; he will therefore not predictably clear midazolam or fentanyl infusions. With a RASS of −4 to −5, indicating no meaningful responsiveness to stimuli, all sedatives should be held if the patient is otherwise clinically stable to allow time for clearance of medications. If the patient was to develop pain based on a CPOT of 3 or more, then intermittent fentanyl is appropriate (Answer B is correct). A decrease in sedative dose or changing to a different sedative is not needed at this time based on the deeply sedated RASS score and would only further delay awakening time. Intermittent doses of benzodiazepines should avoided. (Answers A, C, and D are incorrect).", "page": 27, "answerPage": 51, "stemZh": "48 歲男性，cirrhosis、hepatorenal syndrome，因 respiratory distress 插管。Midazolam 1 mg/hour、fentanyl 75 mcg/hour 已 2 天；24 小時 RASS −4 至 −5、CPOT 1，oxygen requirement 已降低且生命徵象正常。最佳藥物調整？", "contextZh": "", "optionsZh": [{"key": "A", "text": "降低 midazolam，agitation 時給 lorazepam"}, {"key": "B", "text": "停止 midazolam 與 fentanyl；CPOT ≥3 時給必要時 fentanyl"}, {"key": "C", "text": "停止 midazolam，改 propofol drip"}, {"key": "D", "text": "Midazolam 改 dexmedetomidine drip"}], "explanationZh": "嚴重肝腎 dysfunction 使 clearance 不易預測；深 sedation 且臨床穩定應暫停 infusion 讓藥物清除，疼痛再以 intermittent fentanyl 處理。"}, {"id": "17-case-04", "chapter": 17, "type": "case", "number": 4, "stem": "T.L. is a 55-year-old woman intubated for respiratory distress for severe pneumonia. She is receiving fentanyl 50 mcg/hour and dexmedetomidine 1.0 mcg/kg/hour. Her home medications are confirmed to include esomeprazole 20 mg daily, lorazepam 1 mg three times daily, and citalopram 10 mg daily. The nurse reports intermittent agitation with tachycardia and a negative pain score. Which is the most appropriate recommendation?", "context": "", "options": [{"key": "A", "text": "Increase fentanyl drip for agitated RASS score.", "sourceKey": "A"}, {"key": "B", "text": "Reinitiate lorazepam and citalopram.", "sourceKey": "B"}, {"key": "C", "text": "Give fentanyl boluses as needed for agitation.", "sourceKey": "C"}, {"key": "D", "text": "Increase dexmedetomidine.", "sourceKey": "D"}], "answer": "B", "explanation": "Withdrawal from certain home medications may occur if these medications are not reinitiated within a few days of admission. The onset of withdrawal symptoms will vary depending on the half-life of each medication. Symptoms may include agitation, anxiety, psychosis, insomnia, hypertension, and tachycardia and can occur with medications such as opiates, GABA receptor agonists, antiepileptics, antidepressants, and antipsychotics. A pharmacist can assist the medical team by obtaining a thorough medication history and assessment of home medication adherence to help identify drug withdrawal symptoms. Reinitiating these medications can be considered, unless contraindicated because of the clinical scenario (e.g., drug-drug interactions, drug-disease state interactions). The Agitation and Sedation section of the PADIS guidelines discusses identifying and treating the etiology of agitation before adding other medications; reinitiating the benzodiazepine and antidepressant to treat withdrawal symptoms is the most appropriate answer (Answer B is correct). Neither fentanyl nor dexmedetomidine would treat withdrawal from a benzodiazepine or antidepressant (Answers A, C, and D are incorrect).", "page": 27, "answerPage": 51, "stemZh": "護理師回報間歇 agitation、tachycardia，pain score 陰性。最佳建議？", "contextZh": "T.L.，55 歲女性，severe pneumonia 插管，fentanyl 50 mcg/hour、dexmedetomidine 1.0 mcg/kg/hour。家中用 esomeprazole 20 mg/day、lorazepam 1 mg 三次/day、citalopram 10 mg/day。", "optionsZh": [{"key": "A", "text": "因 agitation 增加 fentanyl drip"}, {"key": "B", "text": "重新開始 lorazepam 與 citalopram"}, {"key": "C", "text": "Agitation 時給 fentanyl bolus"}, {"key": "D", "text": "增加 dexmedetomidine"}], "explanationZh": "停用長期 benzodiazepine 與 antidepressant 可引起 withdrawal；應處理病因，確認無 contraindication 後恢復家中藥物，而非只加 sedatives。"}, {"id": "17-case-05", "chapter": 17, "type": "case", "number": 5, "stem": "T.L. (from question 4) was extubated 24 hours ago, is currently receiving dexmedetomidine 0.2 mcg/kg/ hour, and has received two doses of fentanyl 25 mcg over 24 hours for pain. She is alert and calm with intermittent periods of agitation. Her pain score is now negative, and she is newly positive for delirium by CAM-ICU. Her laboratory values and vital signs are normal. Which would best be recommended for the management of delirium?", "context": "", "options": [{"key": "A", "text": "Continue dexmedetomidine, and start quetiapine for delirium.", "sourceKey": "A"}, {"key": "B", "text": "Discontinue dexmedetomidine, and increase maintenance fluids for dehydration.", "sourceKey": "B"}, {"key": "C", "text": "Discontinue dexmedetomidine, and order patient mobility as tolerated.", "sourceKey": "C"}, {"key": "D", "text": "Continue dexmedetomidine, and schedule oxycodone sustained release every 12 hours.", "sourceKey": "D"}], "answer": "C", "explanation": "The PADIS guidelines stress using nonpharmacologic means to manage delirium when it is safe for the patient. Strong evidence for using dexmedetomidine to treat delirium is still not available and the MIND USA Study has shown that anti-psychotics are ineffective at treating delirium. This patient’s presentation of “alert and calm with intermittent periods of agitation” is a common scenario, and initial therapy should focus on reorienting and getting the patient interactive and mobile (Answers A and D are incorrect; Answer C is correct). Dehydration is a common cause of agitation, and it should be addressed; however, with normal laboratory values and vital signs, this patient is unlikely dehydrated at this time (Answer B is incorrect).", "page": 38, "answerPage": 51, "stemZh": "T.L.（第 4 題病人）extubation 已 24 小時，dexmedetomidine 0.2 mcg/kg/hour，24 小時因疼痛給 fentanyl 25 mcg 兩次。清醒平靜但間歇 agitation，現在 pain score 陰性、CAM-ICU 新轉陽性，檢驗與生命徵象正常。最佳 delirium 處置？", "contextZh": "T.L.，55 歲女性，severe pneumonia 插管，fentanyl 50 mcg/hour、dexmedetomidine 1.0 mcg/kg/hour。家中用 esomeprazole 20 mg/day、lorazepam 1 mg 三次/day、citalopram 10 mg/day。", "optionsZh": [{"key": "A", "text": "持續 dexmedetomidine，開始 quetiapine"}, {"key": "B", "text": "停止 dexmedetomidine，增加 maintenance fluids"}, {"key": "C", "text": "停止 dexmedetomidine，安排可耐受的 mobility"}, {"key": "D", "text": "持續 dexmedetomidine，固定 oxycodone sustained release q12h"}], "explanationZh": "先採 reorientation、互動與 mobility 等非藥物措施。沒有脫水證據；antipsychotics 不縮短 delirium，固定 opioid 也缺乏目前疼痛適應症。"}, {"id": "17-case-06", "chapter": 17, "type": "case", "number": 6, "stem": "P.V. is a 70-year-old woman intubated for severe respiratory failure (Fio 2 80%) and refractory shock from methicillin-resistant Staphylococcus aureus pneumonia, for which she was administered antibiotics, vasopressors, and steroids. She is on day 5 of mechanical ventilation (Fio 2 50%) and has been off vasopressors for 48 hours. The nurse describes PAD, but the patient denies pain. Medications include vancomycin 1000 mg daily, heparin 5000 units subcutaneously every 12 hours, hydrocortisone 50 mg every 6 hours, and fentanyl 75 mcg/hour. Which is the most appropriate recommendation at this time?", "context": "", "options": [{"key": "A", "text": "Increase fentanyl, and add midazolam for agitation.", "sourceKey": "A"}, {"key": "B", "text": "Decrease fentanyl, and discontinue hydrocortisone.", "sourceKey": "B"}, {"key": "C", "text": "Decrease fentanyl, and add haloperidol for delirium.", "sourceKey": "C"}, {"key": "D", "text": "Increase fentanyl, and change vancomycin to linezolid.", "sourceKey": "D"}], "answer": "B", "explanation": "In the general population, systemic corticosteroids are known to cause many neuropsychiatric events, including hyperactivity and agitation; in a recent study of adult ICU patients with acute lung injury, only age and use of systemic corticosteroids in the preceding 24 hours were independently associated with the transition to delirium from a non-delirious state (Answer B is correct). Benzodiazepines have a sedating effect and may calm an acutely agitated patient; however, they would not be recommended in this patient because they could worsen her confusion or delirium (Answer A is incorrect). The PADIS guidelines state that no evidence supports the use of haloperidol to reduce the duration of delirium (Answer C is incorrect). Vancomycin is not currently recognized as a cause of delirium; therefore, changing to linezolid is not indicated (Answer D is incorrect).", "page": 38, "answerPage": 51, "stemZh": "P.V.，70 歲女性，MRSA pneumonia 導致 severe respiratory failure（FiO2 80%）與 refractory shock，已給 antibiotics、vasopressors、steroids。目前 MV 第 5 天（FiO2 50%），停 vasopressors 已 48 小時。護理師回報 PAD，但病人否認疼痛。藥物：vancomycin 1000 mg/day、heparin 5000 units SC q12h、hydrocortisone 50 mg q6h、fentanyl 75 mcg/hour。最佳建議？", "contextZh": "", "optionsZh": [{"key": "A", "text": "增加 fentanyl，為 agitation 加 midazolam"}, {"key": "B", "text": "降低 fentanyl，停止 hydrocortisone"}, {"key": "C", "text": "降低 fentanyl，為 delirium 加 haloperidol"}, {"key": "D", "text": "增加 fentanyl，vancomycin 改 linezolid"}], "explanationZh": "無疼痛時應減少 opioid；shock 已改善，且 corticosteroids 可能導致 agitation/delirium，可停止 hydrocortisone。Benzodiazepines 可惡化 delirium；haloperidol 未證實縮短病程。"}, {"id": "17-case-07", "chapter": 17, "type": "case", "number": 7, "stem": "A 55-year-old man intubated for severe ARDS (Pao 2 /Fio 2 ratio less than 100 mm Hg) is receiving fentanyl 200 mcg/hour, midazolam 8 mg/hour, and propofol 40 mcg/kg/minute. He is deeply sedated but remains hypoxic and dyssynchronous with the ventilator after several changes in mechanical ventilation settings. Which is the most appropriate consideration at this time?", "context": "", "options": [{"key": "A", "text": "Start scheduled lorazepam every 6 hours.", "sourceKey": "A"}, {"key": "B", "text": "Add quetiapine 50 mg every 8 hours.", "sourceKey": "B"}, {"key": "C", "text": "Change propofol to dexmedetomidine.", "sourceKey": "C"}, {"key": "D", "text": "Start a cisatracurium infusion.", "sourceKey": "D"}], "answer": "D", "explanation": "The midazolam dose is high, and the patient is “deeply sedated”; therefore, adding another benzodiazepine will likely not improve this patient’s clinical status. Quetiapine has no indication for general sedation in a critically ill patient, and it should not be a consideration for sedation in this patient with severe ARDS. Dexmedetomidine is considered a weak sedative with no effect on respiratory drive; therefore, it would likely not improve this patient’s ventilator dyssynchrony and hypoxia (Answers A–C are incorrect). At this stage in the patient’s clinical course, it is reasonable to consider an NMDA. In a 2010 study of cisatracurium versus placebo for 48 hours in early ARDS, the cisatracurium group had more days free of mechanical ventilation and decreased mortality (30% vs. 44%) at 90 days for the subgroup of patients with severe ARDS (Pao 2 /Fio 2 ratio less than 120 mm Hg). The incidence of pneumothorax was lower in the cisatracurium group than in the placebo group (4% vs. 11%). There were more days free of organ failure (non-lung) in the cisatracurium group than in the placebo group (15.8 vs. 12.2 days) in the first 28 days. A recent metaanalysis concluded that using short-term cisatracurium in patients with severe ARDS decreases mortality and time on mechanical ventilation compared with placebo. The risk of prolonged neuromuscular weakness was not found in these studies; however, use beyond 48 hours may increase this risk (Answer D is correct).", "page": 43, "answerPage": 52, "stemZh": "55 歲男性 severe ARDS（PaO2/FiO2 <100 mm Hg），使用 fentanyl 200 mcg/hour、midazolam 8 mg/hour、propofol 40 mcg/kg/minute。已 deep sedation，調整 MV 仍 hypoxia 與 ventilator dyssynchrony。最適當考量？", "contextZh": "", "optionsZh": [{"key": "A", "text": "固定 lorazepam q6h"}, {"key": "B", "text": "Quetiapine 50 mg q8h"}, {"key": "C", "text": "Propofol 改 dexmedetomidine"}, {"key": "D", "text": "開始 cisatracurium infusion"}], "explanationZh": "已適當 deep sedation 而 severe ARDS、dyssynchrony 仍未控制，可考慮短期 NMBA。再加 benzodiazepine 或改較弱 sedative 不直接解決問題；使用超過 48 小時需留意 weakness。"}, {"id": "17-case-08", "chapter": 17, "type": "case", "number": 8, "stem": "A 70-year-old woman who is day 2 in the ICU is receiving a neuromuscular blocking agent (NMBA) and is sedated for severe ARDS. The TOF over 24 hours is 2 of 4 twitches at an amplitude of 10 mA. Arterial blood gas is pH 7.38, Pco 2 40 mm Hg, Po 2 91 mm Hg, and bicarbonate 24 mEq/L on 50% inspired oxygen and 10 cm H 2 O PEEP; the patient is synchronous with the ventilator, and other clinical markers are stable. Which changes in management would be best to recommend?", "context": "", "options": [{"key": "A", "text": "Decrease stimulator amplitude to decrease pain from excessive electrical current.", "sourceKey": "A"}, {"key": "B", "text": "Increase stimulator amplitude to test for more frequent twitches.", "sourceKey": "B"}, {"key": "C", "text": "Decrease the NMBA dose because the patient is clinically stable.", "sourceKey": "C"}, {"key": "D", "text": "Increase the NMBA dose until the TOF induces fewer twitches.", "sourceKey": "D"}], "answer": "C", "explanation": "The TOF method of assessment is primarily used to help determine the degree of neuromuscular blockade and should not be used to titrate the dose of the NMBA. The patient’s clinical status and laboratory values are the true determinants for dose adjustment of the NMBA. Patients may be at their clinical goal with a TOF of 2 or 3 twitches of 4. This is the ideal scenario, and it will predict a faster reversal of neuromuscular blockade (Answer C is correct). A TOF of 0 or 1 of 4 twitches predicts a significantly slower neuromuscular recovery time, and clinicians should try to decrease the NMBA as soon as the patient is clinically stable by laboratory values and ventilator management (Answer D is incorrect). A baseline electrical current intensity (amperage) should be established before the onset of neuromuscular blockade and should not be changed during paralysis unless a new baseline is indicated (Answer A is incorrect). As the electrical intensity (amperage) is established, an increase in the amperage is not indicated during infusion of the NMBA in order to increase the number of twitches. A decrease in the dose of NMBA would be indicated if an increase in the number of twitches were the clinical goal (Answer B is incorrect).", "page": 43, "answerPage": 52, "stemZh": "70 歲女性 ICU 第 2 天，severe ARDS，已 sedation 與 NMBA。24 小時 TOF 在 10 mA 為 2/4 twitches。ABG：pH 7.38、PCO2 40 mm Hg、PO2 91 mm Hg、HCO3 24 mEq/L；FiO2 50%、PEEP 10 cm H2O，ventilator synchronous，其他臨床指標穩定。最佳調整？", "contextZh": "", "optionsZh": [{"key": "A", "text": "降低電刺激強度以減輕疼痛"}, {"key": "B", "text": "增加電刺激強度測試更多 twitches"}, {"key": "C", "text": "因臨床穩定降低 NMBA dose"}, {"key": "D", "text": "增加 NMBA dose，使 TOF twitches 更少"}], "explanationZh": "NMBA 應依氧合與 ventilator synchrony 等臨床狀態降至最低有效劑量；TOF 不能單獨指導 dosing，穩定時 2–3/4 twitches 有助較快恢復。"}, {"id": "18-self-01", "chapter": 18, "type": "self", "number": 1, "stem": "Which best describes the category of acute respiratory distress syndrome (ARDS) that most benefits from prone positioning and cisatracurium administration?", "context": "", "options": [{"key": "A", "text": "Acute lung injury.", "sourceKey": "A"}, {"key": "B", "text": "Moderate to severe.", "sourceKey": "B"}, {"key": "C", "text": "Mild to moderate.", "sourceKey": "C"}, {"key": "D", "text": "Mild.", "sourceKey": "D"}], "answer": "B", "explanation": "According to the Berlin ARDS definition, the category of acute lung injury was removed in favor of categorizing the severity of ARDS (Pao2 /Fio2 less than 200 mm Hg) (Answer A is incorrect). Because of the relative difference in mortality rates, mild and moderate ARDS cases are less likely to benefit from therapeutic interventions, given the number needed to treat to show an effective intervention (Answers C and D are incorrect). In the trials evaluating prone positioning and cisatracurium, patients with severe ARDS were the most likely to benefit. Although the criteria used for severe ARDS in these studies differed from those used in the Berlin definition (both studies were initiated before publication of the Berlin ARDS definition), a post hoc analysis shows a survival benefit in favor of the group with the highest mortality rate (Answer B is correct).", "page": 4, "answerPage": 28, "stemZh": "哪一類 ARDS 最可能從 prone positioning 與 cisatracurium 獲益？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Acute lung injury"}, {"key": "B", "text": "Moderate to severe"}, {"key": "C", "text": "Mild to moderate"}, {"key": "D", "text": "Mild"}], "explanationZh": "教材所述試驗中較嚴重 ARDS 族群較可能獲益；Berlin definition 已用 ARDS severity 取代 acute lung injury 分類。"}, {"id": "18-self-02", "chapter": 18, "type": "self", "number": 2, "stem": "Several clinical trials have been conducted in moderate to severe ARDS. Which of the following partial pressure of arterial oxygen (Pao2 )/ fraction of inspired oxygen (Fio2 ) parameters best describes this ARDS subpopulation?", "context": "", "options": [{"key": "A", "text": "100–200 mm Hg.", "sourceKey": "A"}, {"key": "B", "text": "Greater than 150 mm Hg.", "sourceKey": "B"}, {"key": "C", "text": "Less than 150 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "50–150 mm Hg.", "sourceKey": "D"}], "answer": "C", "explanation": "The Belin definition defines ARDS severity with Pao2/ Fio2 as one element of criteria. Comprehension of subpopulations of ARDS is essential to apply published clinical data among various therapies. Although not universal defined, the most commonly reported inclusion criteria among landmark ARDS clinical trials (ROSE, ACURASYS, DEXA-ARDS, etc.) was moderate to severe ARDS criteria was less than 150 mm Hg (Answer C is correct; Answers A and B are incorrect). Also, these trials did not define a lower limit of ARDS severity (e.g., 50–150 mm Hg) as inclusion criteria (Answer D is incorrect).", "page": 4, "answerPage": 28, "stemZh": "多項 moderate-to-severe ARDS clinical trials 的 PaO2/FiO2 納入門檻，以下何者最符合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "100–200 mm Hg"}, {"key": "B", "text": ">150 mm Hg"}, {"key": "C", "text": "<150 mm Hg"}, {"key": "D", "text": "50–150 mm Hg"}], "explanationZh": "ROSE、ACURASYS、DEXA-ARDS 等 landmark trials 常採 PaO2/FiO2 <150 mm Hg，而未設定 50 mm Hg 的下限。"}, {"id": "18-self-03", "chapter": 18, "type": "self", "number": 3, "stem": "Which of the following parameters best describes “low tidal volumes” for invasive mechanical ventilation in ARDS?", "context": "", "options": [{"key": "A", "text": "6 mL/kg of total body weight.", "sourceKey": "A"}, {"key": "B", "text": "4 mL/kg of ideal body weight.", "sourceKey": "B"}, {"key": "C", "text": "7 mL/kg of total body weight.", "sourceKey": "C"}, {"key": "D", "text": "5 mL/kg of adjusted body weight.", "sourceKey": "D"}], "answer": "B", "explanation": "The landmark ARDSNet trial evaluating lung protective mechanical ventilation strategies defined low tidal volumes ranging from 4 to 8 mL/kg using predicted body weight (also known as ideal body weight (Answer B is correct). Total body weight may overestimate ventilation requirements in adult patients with obesity because lung volume is unrelated to increasing total body weight (i.e., lung size remains relatively constant irrespective of adult body mass) (Answers A, C, and D are incorrect).", "page": 4, "answerPage": 28, "stemZh": "ARDS invasive MV 的 low tidal volume，哪個參數最適當？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Total body weight 的 6 mL/kg"}, {"key": "B", "text": "Ideal body weight 的 4 mL/kg"}, {"key": "C", "text": "Total body weight 的 7 mL/kg"}, {"key": "D", "text": "Adjusted body weight 的 5 mL/kg"}], "explanationZh": "ARDSNet 的 low tidal volume 範圍為 predicted/ideal body weight 的 4–8 mL/kg。Lung size 不隨成人肥胖體重增加，不應用 total 或 adjusted body weight。"}, {"id": "18-self-04", "chapter": 18, "type": "self", "number": 4, "stem": "A 65-year-old man presents to the emergency department with severe shortness of breath, tachypnea, altered mental status, and diaphoresis. A chest radiograph reveals diffuse, bilateral opacities. His vital signs are as follows: blood pressure 94/54 mm Hg, respiratory rate 26 breaths/minute, heart rate 120 beats/minute, pain score 2/10, and temperature 105.8°F (41.0°C). The patient’s wife states that his symptoms began about 2 days ago and gradually worsened over the past day. The patient is transferred to the ICU, where he is intubated. His arterial blood gas values are pH 7.30, partial pressure of arterial carbon dioxide (Paco2 ) 50 mm Hg, Pao2 50 mm Hg, and oxygen saturation (Sao2 ) 85% while receiving Fio2 100%. Which is the best therapy plan for the next 24 hours?", "context": "", "options": [{"key": "A", "text": "Empiric antibiotic therapy, intravenous fluid resuscitation, and vasopressors for shock; low tidal volume (4–8 mL/kg) ventilation strategy; deep sedation to achieve a Richmond AgitationSedation Scale (RASS) score of Č4; and prone positioning.", "sourceKey": "A"}, {"key": "B", "text": "Empiric antibiotic therapy, intravenous fluid resuscitation, and vasopressors for shock; low tidal volume (4–8 mL/kg) ventilation strategy; deep sedation to achieve a RASS score of Č5 and cisatracurium administration to limit plateau pressures; and prone positioning.", "sourceKey": "B"}, {"key": "C", "text": "Empiric antibiotic therapy, aggressive diuresis (goal central venous pressure less than 4 mm Hg), and vasopressors for shock; low tidal volume (4–8 mL/kg) ventilation strategy; deep sedation to achieve a RASS score of Č4; and prone positioning.", "sourceKey": "C"}, {"key": "D", "text": "Empiric antibiotic therapy, intravenous fluid resuscitation, and vasopressors for shock; low tidal volume (4–8 mL/kg) ventilation strategy; deep sedation to achieve a RASS score of Č4; and supine positioning.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient has both ARDS and septic shock. In addition, he has likely had ARDS for less than 48 hours; therefore, the time to initiation of several treatments is essential. The patient is actively in shock (as evidenced by his blood pressure), thus making a fluid-conservative strategy (CVP less than 4 mm Hg) impossible (Answer C is incorrect). Because the time to presentation is less than 48 hours and the patient has severe ARDS, he meets the criteria for cisatracurium administration and prone positioning, and a treatment plan should include these two therapies (Answers A and D are incorrect). A therapy plan should include shock resuscitation (fluid-liberal strategy, CVP 10–14 mm Hg), lung-protective ventilation (tidal volume 4–8 mL/kg of ideal body weight), prone positioning, and cisatracurium administration (Answer B is correct).", "page": 4, "answerPage": 28, "stemZh": "65 歲男性 severe dyspnea、tachypnea、意識改變、盜汗，CXR diffuse bilateral opacities。BP 94/54 mm Hg、RR 26/min、HR 120/min、pain 2/10、105.8°F（41°C），症狀約 2 天。ICU 插管後 pH 7.30、PaCO2 50 mm Hg、PaO2 50 mm Hg、SaO2 85%，FiO2 100%。未來 24 小時最佳計畫？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Empiric antibiotics、IV fluid resuscitation、vasopressors；tidal volume 4–8 mL/kg；RASS −4；prone positioning"}, {"key": "B", "text": "Empiric antibiotics、IV fluid resuscitation、vasopressors；tidal volume 4–8 mL/kg；RASS −5 與 cisatracurium 限制 plateau pressure；prone positioning"}, {"key": "C", "text": "Empiric antibiotics、積極 diuresis（CVP <4 mm Hg）、vasopressors；tidal volume 4–8 mL/kg；RASS −4；prone positioning"}, {"key": "D", "text": "Empiric antibiotics、IV fluid resuscitation、vasopressors；tidal volume 4–8 mL/kg；RASS −4；supine positioning"}], "explanationZh": "早期 severe ARDS 合併 septic shock：需 shock resuscitation、lung-protective MV、prone positioning 與教材情境下 cisatracurium。仍在 shock，不適用積極 conservative fluid removal。"}, {"id": "18-self-05", "chapter": 18, "type": "self", "number": 5, "stem": "P.D. is a 67-year-old woman (height 160 cm; total body weight 68 kg) admitted to the ICU with ARDS pneumonia. Her mechanical ventilation parameters are as follows: tidal volume 280 mL, respiratory rate 20 breaths/minute, positive end-expiratory pressure (PEEP) 12 cm H 2 O, and Fio2 80% with plateau pressure of 22 mm Hg. Her mean arterial pressure (MAP) is currently 68 mm Hg with norepinephrine discontinued 4 hours ago and CVP ranging between 8 and 14 cm H 2 O over the last 2 hours. Also, her total urine output over the past 24 hours is 1150 mL. The ICU team is discussing fluid management using the FACTT Lite protocol. Which of the following options is the most appropriate strategy?", "context": "", "options": [{"key": "A", "text": "Administer furosemide 40 mg IV once and reevaluate in 4 hours.", "sourceKey": "A"}, {"key": "B", "text": "Administer furosemide 1mg/hour continuous infusion and re-evaluate in 8 hours.", "sourceKey": "B"}, {"key": "C", "text": "Administer 0.9% sodium chloride 500 mL over 1 hour and re-evaluate in 4 hours.", "sourceKey": "C"}, {"key": "D", "text": "Monitor only and re-evaluate in 8 hours.", "sourceKey": "D"}], "answer": "D", "explanation": "The FACTT Lite approach attempts to simplify fluid management for implementation among ARDS patients in clinical practice. The parameters used to determine clinical course of action (remove fluid from diuretic administration, administer fluid boluses, or monitor without administration of either therapy) include MAP, urine output, and CVP (pulmonary arterial occlusion pressure may be optional based on institutional practices for invasive monitoring). Administering fluids in this patient may not be the most appropriate approach because MAP, CVP, and urine output do not suggest hypovolemia (Answer C is incorrect). Although continuous infusion furosemide may be an option within this published protocol, it is important to note both the suggested rate of infusion and time to re-evaluate and inconsistent with the FACTT Lite protocol. Re-evaluation should be relatively short irrespective of the clinical decision-making (i.e., 1 or 4 hours) (Answer B is incorrect). It is important to emphasize conservative management approaches defined in this protocol require the patient achieve a MAP of 60 mm Hg without any vasoactive support for at least 12 hours. The short time period since vasopressor support cessation may be too aggressive to administer without demonstrating clinical stable hemodynamic pressures (Answer A is incorrect). The most appropriate approach would be monitoring until adequate MAP has been achieved without vasoactive support for at least 12 hours (Answer D is correct).", "page": 5, "answerPage": 28, "stemZh": "P.D.，67 歲女性（160 cm、68 kg），ARDS pneumonia。MV：tidal volume 280 mL、RR 20/min、PEEP 12 cm H2O、FiO2 80%、plateau pressure 22 mm Hg。MAP 68 mm Hg，norepinephrine 停用 4 小時；最近 2 小時 CVP 8–14 cm H2O，24 小時 UOP 1150 mL。按 FACTT Lite，最適當 fluid management？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Furosemide 40 mg IV 一次，4 小時後重評"}, {"key": "B", "text": "Furosemide 1 mg/hour infusion，8 小時後重評"}, {"key": "C", "text": "0.9% sodium chloride 500 mL/1 小時，4 小時後重評"}, {"key": "D", "text": "先監測，8 小時後重評"}], "explanationZh": "FACTT Lite 的 conservative fluid strategy 要求不用 vasoactive support 仍維持 MAP ≥60 mm Hg 至少 12 小時；此病人僅停 4 小時，先監測。"}, {"id": "18-self-06", "chapter": 18, "type": "self", "number": 6, "stem": "Which of the following statements most appropriately describes published clinical trials of corticosteroids in ARDS?", "context": "", "options": [{"key": "A", "text": "Dexamethasone demonstrated improved clinical outcomes among ARDS patients on lung-protective strategies.", "sourceKey": "A"}, {"key": "B", "text": "Dexamethasone initiated after 7 days of ARDS onset was associated with worse clinical outcomes.", "sourceKey": "B"}, {"key": "C", "text": "Methylprednisolone demonstrated improved clinical outcomes among ARDS patients on lung-protective strategies.", "sourceKey": "C"}, {"key": "D", "text": "Methylprednisolone initiated after 7 days of ARDS onset was associated with worse clinical outcomes.", "sourceKey": "D"}], "answer": "A", "explanation": "The DEXA-ARDS clinical trial has been the only contemporary trial evaluating corticosteroids (dexamethasone) among ARDS patients already receiving lung-protective mechanical ventilation strategies (Answer A is correct). Despite the numerous ARDS trials evaluating methylprednisolone, none have concurrently evaluated with lung-protective strategies among all study patients (Answer C is correct). Despite the optimal timing of corticosteroid use in ARDS remains controversial, dexamethasone was started “early” after ARDS onset in the DEXA-ARDS trial (Answer B is incorrect). The LaSRS clinical trial found increased risk of death in the steroid group compared with controls among patients enrolled greater than 14 days after ARDS onset. Unfortunately, this unadjusted subgroup analysis may have biased these findings. Subsequent re-evaluation of these results found no differences in mortality among in this subgroup. Furthermore, “late” (greater than 5–7 days) corticosteroid use in ARDS has not consistently demonstrated worse outcomes (Answer D is incorrect).", "page": 5, "answerPage": 29, "stemZh": "關於 ARDS corticosteroid clinical trials，何者最適當？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dexamethasone 在已採 lung-protective MV 的 ARDS 病人改善 outcomes"}, {"key": "B", "text": "Dexamethasone 於 ARDS 發生 7 天後開始使 outcomes 更差"}, {"key": "C", "text": "Methylprednisolone 在已採 lung-protective MV 的 ARDS 病人改善 outcomes"}, {"key": "D", "text": "Methylprednisolone 於 ARDS 發生 7 天後開始使 outcomes 更差"}], "explanationZh": "教材以 DEXA-ARDS 支持 A；dexamethasone 是早期使用。Late steroid 的風險與最佳時機仍有爭議，不能將 7 天當作所有試驗一致的傷害界線。"}, {"id": "18-self-07", "chapter": 18, "type": "self", "number": 7, "stem": "Which order of medication administration would be most appropriate for a 34-year-old woman with no significant medical history receiving rapid sequence intubation (RSI)?", "context": "", "options": [{"key": "A", "text": "Rocuronium, etomidate, midazolam.", "sourceKey": "A"}, {"key": "B", "text": "Fentanyl, succinylcholine, propofol.", "sourceKey": "B"}, {"key": "C", "text": "Atropine, rocuronium, etomidate.", "sourceKey": "C"}, {"key": "D", "text": "Fentanyl, etomidate, succinylcholine.", "sourceKey": "D"}], "answer": "D", "explanation": "Neuromuscular blocking agents should always be administered after induction agents (Answers A, B, and C are incorrect). In addition, atropine is not routinely recommended (Answer C is incorrect) for RSI in adult patients. Atropine should be kept nearby for patients who are at an increased risk of bradycardia during RSI (use of ƾ-blockers, calcium channel blockers, digoxin, or amiodarone). Induction agents (and pretreatment medications) should be administered before NMBAs (Answer D is correct).", "page": 5, "answerPage": 29, "stemZh": "34 歲女性無重要病史，RSI 的最佳藥物給予順序？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Rocuronium → etomidate → midazolam"}, {"key": "B", "text": "Fentanyl → succinylcholine → propofol"}, {"key": "C", "text": "Atropine → rocuronium → etomidate"}, {"key": "D", "text": "Fentanyl → etomidate → succinylcholine"}], "explanationZh": "Pretreatment/analgesia 與 induction agent 必須先於 NMBA；避免清醒 paralysis。成人 RSI 不常規給 atropine。"}, {"id": "18-self-08", "chapter": 18, "type": "self", "number": 8, "stem": "A 78-year-old man (weight 70 kg) presents to the ICU after being intubated for acute respiratory failure. His ventilator settings are as follows: assist control/volume control mode, tidal volume 700 mL (10 mL/kg), respiratory rate 20 breaths/minute, Fio2 50%, PEEP 5 cm H 2 O, and pressure support 10 cm H 2 O. The first arterial blood gas values are pH 7.25, Paco2 65 mm Hg, HCO 3 26 mEq/L, Pao2 65 mm Hg, and Sao2 90%. His MAP is 72 mm Hg without requiring vasoactive support, with a serum creatinine of 1.2 mg/dL and urinary output of 350 mL over the past 6 hours. Which approach would be best for this patient’s initial treatment?", "context": "", "options": [{"key": "A", "text": "High tidal volume mechanical ventilation (MV) and conservative fluid management.", "sourceKey": "A"}, {"key": "B", "text": "Low tidal volume MV and conservative fluid management.", "sourceKey": "B"}, {"key": "C", "text": "High tidal volume MV and liberal fluid management.", "sourceKey": "C"}, {"key": "D", "text": "Low tidal volume MV and liberal fluid management.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient has moderate to severe ARDS. The initial MV strategy is using low tidal volumes (Answers A and C are incorrect). Considering the patient is hemodynamically stable without requiring vasoactive support, conservative fluid management approaches are warranted (Answer B is correct). Hemodynamically unstable patients may be candidates for liberal fluid management strategies (Answer D is incorrect).", "page": 5, "answerPage": 29, "stemZh": "78 歲男性（70 kg），acute respiratory failure 插管。AC/VC：tidal volume 700 mL（10 mL/kg）、RR 20/min、FiO2 50%、PEEP 5 cm H2O、PS 10 cm H2O。ABG：pH 7.25、PaCO2 65 mm Hg、HCO3 26 mEq/L、PaO2 65 mm Hg、SaO2 90%。MAP 72 mm Hg，無 vasoactive support；SCr 1.2 mg/dL，6 小時 UOP 350 mL。最佳初始治療？", "contextZh": "", "optionsZh": [{"key": "A", "text": "High tidal volume MV ＋ conservative fluid management"}, {"key": "B", "text": "Low tidal volume MV ＋ conservative fluid management"}, {"key": "C", "text": "High tidal volume MV ＋ liberal fluid management"}, {"key": "D", "text": "Low tidal volume MV ＋ liberal fluid management"}], "explanationZh": "符合 moderate-to-severe ARDS，應採 low tidal volume；hemodynamically stable、無 vasopressors，可採 conservative fluid management。"}, {"id": "18-case-01", "chapter": 18, "type": "case", "number": 1, "stem": "A 56-year-old man is admitted to the ICU with ARDS after experiencing increasing dyspnea during the past 24 hours. His medical history is significant for alcoholism and hypertension. Results of the initial arterial blood gas are as follows: pH 7.24, Paco2 58 mm Hg, HCO 3 24 mEq/L, Pao2 50 mm Hg, and Sao2 84% while receiving MV AC mode with Fio2 100%. Chest radiography reveals diffuse bilateral infiltrates. The patient has blood pressure 120/40 mm Hg (MAP 67 mm Hg), heart rate 142 beats/minute, and CVP 8 mm Hg while receiving a norepinephrine (10 mcg/minute) infusion after intravenous fluid resuscitation. Norepinephrine has now been weaned off while maintaining a MAP of 67 mm Hg. Ceftriaxone 1 g intravenously every 24 hours and levofloxacin 750 mg intravenously every 24 hours have been initiated for community-acquired pneumonia. Which is the best therapeutic plan for the patient’s ARDS?", "context": "", "options": [{"key": "A", "text": "Continue fluid resuscitation to maintain a CVP of 10–14 mm Hg; low tidal volume strategy of 4–8 mL/ kg of ideal body weight; prone positioning; and sedative administration to target deep sedation and cisatracurium infusion.", "sourceKey": "A"}, {"key": "B", "text": "Begin diuresis to target a CVP less than 4 mm Hg; low tidal volume strategy of 4–8 mL/kg of ideal body weight; supine positioning; and sedative administration to target deep sedation and cisatracurium infusion.", "sourceKey": "B"}, {"key": "C", "text": "Begin diuresis to target a CVP less than 4 mm Hg; low tidal volume strategy of 4–8 mL/kg of ideal body weight; supine positioning; and sedative administration to target deep sedation.", "sourceKey": "C"}, {"key": "D", "text": "Discontinue fluid resuscitation and begin diuresis to target a CVP less than 4 mm Hg while maintaining a MAP greater than 65 mm Hg; low tidal volume strategy of 4–8 mL/kg of ideal body weight; prone positioning; and sedative administration to target deep sedation and cisatracurium infusion.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient has early severe ARDS (for less than 48 hours and Pao2 /Fio2 less than 150 mm Hg) and hemodynamic stability (post-resuscitation MAP greater than 65 mm Hg). According to the findings of an ARDSNet-sponsored multicenter trial, he would qualify for conservative fluid management (CVP less than 4 mm Hg). In addition, vasopressors should be discontinued and diuresis initiated to achieve a target CVP less than 4 mm Hg (Answer A is incorrect). Given the timing and the severity of the patient’s ARDS, he should be placed in the prone position (Answers B and C are incorrect). In addition, this patient would qualify for a cisatracurium infusion. Given the timing and severity of his ARDS, he qualifies to receive a lung-protective ventilation strategy (tidal volume 4–6 mL/kg of ideal body weight) and diuresis to a CVP less than 4 mm Hg (hemodynamically stable if weaned off vasopressors) while placed in the prone position and administered a cisatracurium infusion (Answer D is correct).", "page": 15, "answerPage": 26, "stemZh": "56 歲男性，近 24 小時 dyspnea 增加，ARDS，有 alcoholism、hypertension。ABG：pH 7.24、PaCO2 58 mm Hg、HCO3 24 mEq/L、PaO2 50 mm Hg、SaO2 84%；AC mode、FiO2 100%，CXR diffuse bilateral infiltrates。Resuscitation 後 BP 120/40 mm Hg（MAP 67）、HR 142/min、CVP 8 mm Hg，原 norepinephrine 10 mcg/minute 已停且 MAP 仍 67。CAP 使用 ceftriaxone 1 g IV q24h、levofloxacin 750 mg IV q24h。最佳 ARDS 計畫？", "contextZh": "", "optionsZh": [{"key": "A", "text": "繼續 fluid resuscitation，CVP 10–14 mm Hg；ideal body weight 的 tidal volume 4–8 mL/kg；prone、deep sedation、cisatracurium"}, {"key": "B", "text": "開始 diuresis，CVP <4 mm Hg；ideal body weight 的 tidal volume 4–8 mL/kg；supine、deep sedation、cisatracurium"}, {"key": "C", "text": "開始 diuresis，CVP <4 mm Hg；ideal body weight 的 tidal volume 4–8 mL/kg；supine、deep sedation"}, {"key": "D", "text": "停止 fluid resuscitation、diuresis 至 CVP <4 mm Hg 且 MAP >65 mm Hg；ideal body weight 的 tidal volume 4–8 mL/kg；prone、deep sedation、cisatracurium"}], "explanationZh": "依本題教材：早期 severe ARDS 且 resuscitation 後穩定，採 conservative fluid、lung-protective MV、prone positioning 與 cisatracurium。應連同原書情境判讀停 vasopressor 時間。"}, {"id": "18-case-02", "chapter": 18, "type": "case", "number": 2, "stem": "A 70-year-old woman (height 63 inches, weight 65 kg) is transferred to your ICU from an outside hospital after outside hospital admission for hypoxic respiratory failure. She had been treated for ARDS at the outside hospital for 3 days before her son requested hospital transfer. On admission, the patient is receiving MV with the following settings: SIMV mode, tidal volume 600 mL (12 mL/kg), respiratory rate 12 breaths/minute, PS 10 cm H 2 O, and PEEP 10 cm H 2 O. Which is the best therapy for her ARDS?", "context": "", "options": [{"key": "A", "text": "AC/VC mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O; supine positioning.", "sourceKey": "A"}, {"key": "B", "text": "AC/VC mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O; prone positioning; cisatracurium administration.", "sourceKey": "B"}, {"key": "C", "text": "SIMV mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O; supine positioning; cisatracurium administration.", "sourceKey": "C"}, {"key": "D", "text": "AC/VC mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O; prone positioning.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient presents to your ICU after 3 days of care. Therefore, she does not currently meet the criteria for being administered cisatracurium or placed in the prone position (Answers B–D are incorrect). Currently, the applicable therapy to apply is a lung-protective ventilation strategy (tidal volume 4–6 mL/kg of ideal body weight) (Answer A is correct).", "page": 16, "answerPage": 26, "stemZh": "70 歲女性（63 inches、65 kg），外院因 hypoxic respiratory failure 治療 ARDS 3 天後轉院。目前 SIMV、tidal volume 600 mL（12 mL/kg）、RR 12/min、PS 10 cm H2O、PEEP 10 cm H2O。最佳 ARDS 治療？", "contextZh": "", "optionsZh": [{"key": "A", "text": "AC/VC；tidal volume 300 mL（6 mL/kg）、RR 20/min、PS 10、PEEP 5 cm H2O；supine"}, {"key": "B", "text": "同 A 的 AC/VC 設定；prone 並給 cisatracurium"}, {"key": "C", "text": "SIMV；tidal volume 300 mL（6 mL/kg）、RR 20/min、PS 10、PEEP 5 cm H2O；supine 並給 cisatracurium"}, {"key": "D", "text": "同 A 的 AC/VC 設定；prone"}], "explanationZh": "教材以已治療 3 天、不符合其所引早期試驗時窗為由選 A；適用 lung-protective MV。此為教材題目答案，不應視為所有晚期 ARDS 的一律治療規則。"}, {"id": "18-case-03", "chapter": 18, "type": "case", "number": 3, "stem": "A 63-year-old woman (height 165 cm; total body weight 64 kg) with a medical history of insulin-dependent diabetes and chronic kidney disease was admitted to the general ward 2 days ago for acute COVID-19 pneumonia requiring oxygen therapy via nasal cannula. She was started on dexamethasone 6 mg oral daily. Today, she transferred to the intensive care unit following endotracheal intubation because of worsening oxygenation and meeting severe ARDS criteria. Lung-protective MV is initiated at tidal volume 340 mL, respiratory rate 22 breaths/minute, PEEP 12 cm H 2 O, and Fio2 100%. Her arterial blood gas values are as follows: pH 7.28, Paco2 46 mm Hg, Pao2 60 mm Hg, and HCo 3 24 mEq/L with Sao2 of 92%. Which is most appropriate therapeutic plan regarding her corticosteroids?", "context": "", "options": [{"key": "A", "text": "Discontinue dexamethasone 6 mg oral daily.", "sourceKey": "A"}, {"key": "B", "text": "Change dexamethasone 6 mg oral daily to methylprednisolone 40 mg intravenous four times daily.", "sourceKey": "B"}, {"key": "C", "text": "Change dexamethasone 6 mg oral daily to dexamethasone 6 mg intravenous daily.", "sourceKey": "C"}, {"key": "D", "text": "Change dexamethasone 6 mg oral daily to dexamethasone 20 mg intravenous daily.", "sourceKey": "D"}], "answer": "C", "explanation": "The patient was appropriately started on corticosteroids for COVID-19 pneumonia during the same hospital admission prior to developing ARDS and subsequently transferred to the ICU. Dexamethasone was associated with favorable results among COVID-19 hospitalized patient requiring oxygen support (both noninvasive and invasive mechanical ventilation) as well as critically ill patients with moderate to severe ARDS; therefore, continuing dexamethasone is appropriate (Answer A is incorrect). Methylprednisolone has not been associated with favorable clinical outcomes among COVID-19 or moderate to severe ARDS patients (Answer B is incorrect). Although the DEXA-ARDS trial found improved clinical outcomes associated with the dexamethasone 20 mg daily (followed by 10 mg daily) regimen in ARDS patients, it is important to recognize this patient population did not consist of COVID-19. Furthermore, a meta-analysis evaluating various corticosteroid regimens failed to find any benefit of higher dexamethasone dosing strategies (i.e., 20 mg daily) compared with lower doses (6 mg daily) (Answer C is correct; Answer D is incorrect).", "page": 16, "answerPage": 26, "stemZh": "63 歲女性（165 cm、64 kg），insulin-dependent diabetes、CKD，2 天前因 COVID-19 pneumonia 住院使用 nasal cannula 與 dexamethasone 6 mg PO/day。今日氧合惡化，插管轉 ICU，severe ARDS。MV：tidal volume 340 mL、RR 22/min、PEEP 12 cm H2O、FiO2 100%；pH 7.28、PaCO2 46、PaO2 60 mm Hg、HCO3 24 mEq/L、SaO2 92%。最佳 corticosteroid 計畫？", "contextZh": "", "optionsZh": [{"key": "A", "text": "停止 dexamethasone 6 mg PO/day"}, {"key": "B", "text": "改 methylprednisolone 40 mg IV 每日四次"}, {"key": "C", "text": "改 dexamethasone 6 mg IV/day"}, {"key": "D", "text": "改 dexamethasone 20 mg IV/day"}], "explanationZh": "需要 oxygen support 的 COVID-19 病人持續 dexamethasone 6 mg 適當，插管後改 IV。DEXA-ARDS 的 20 mg regimen 並非 COVID-19 族群，未支持本題因 ARDS 直接加到高劑量。"}, {"id": "18-case-04", "chapter": 18, "type": "case", "number": 4, "stem": "K.J. is a 56-year-old man (height 72 inches; total body weight 120 kg) admitted to the ICU for septic shock requiring vasoactive support and ARDS pneumonia. Lung-protective MV is initiated as follows: tidal volume 600 mL, respiratory rate 24 breaths/minute, PEEP 14 cm H 2 O, and Fio2 100% with plateau pressure of 24 mm Hg. His arterial blood gas values are pH 7.28, Paco2 46 mm Hg, Pao2 62 mm Hg, and Hco 3 24 mEq/L. Which of the following treatment strategies may be most appropriate at this time to improve oxygenation?", "context": "", "options": [{"key": "A", "text": "Inhaled nitric oxide.", "sourceKey": "A"}, {"key": "B", "text": "ECMO.", "sourceKey": "B"}, {"key": "C", "text": "Inhaled epoprostenol.", "sourceKey": "C"}, {"key": "D", "text": "Cistracurium.", "sourceKey": "D"}], "answer": "B", "explanation": "Although selective pulmonary vasodilating agents may modestly improve oxygenation parameters at best, they have not shown to improve clinical outcomes. Their role in therapy is uncertain, but it may be mostly considered salvage therapy after failing more proven strategies (Answers A and C are incorrect). The role of neuromuscular blocking agents in ARDS remain controversial. However, the ROSE clinical trial failed to corroborate any improved clinical outcomes previously demonstrated (ACURASYS trial). Cisatracurium may not be appropriate at this time since plateau pressures remain acceptable despite using high PEEP (Answer D is incorrect). ECMO use in ARDS also remains controversial. However, severe ARDS may be a compelling reason to initiate ECMO compared with alternative supportive therapies (Answer B is correct).", "page": 16, "answerPage": 26, "stemZh": "K.J.，56 歲男性（72 inches、120 kg），septic shock 需 vasoactive support，ARDS pneumonia。MV：tidal volume 600 mL、RR 24/min、PEEP 14 cm H2O、FiO2 100%、plateau pressure 24 mm Hg。pH 7.28、PaCO2 46、PaO2 62 mm Hg、HCO3 24 mEq/L。此時何者最適當改善氧合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Inhaled nitric oxide"}, {"key": "B", "text": "ECMO"}, {"key": "C", "text": "Inhaled epoprostenol"}, {"key": "D", "text": "Cisatracurium"}], "explanationZh": "教材選 ECMO：severe refractory oxygenation impairment 是考慮依據；inhaled vasodilators 雖可暫改善 oxygenation，未證實改善 clinical outcomes。Plateau pressure 尚可，教材未選 NMBA。"}, {"id": "18-case-05", "chapter": 18, "type": "case", "number": 5, "stem": "D.J. is a 49-year-old man with septic shock requiring vasoactive support and ARDS with MV at the following settings: tidal volume 400 mL, respiratory rate 26 breaths/minute, PEEP 20 cm H 2 O, and Fio2 100%, resulting in a plateau pressure of 40 mm Hg. The patient’s arterial blood gas values after mechanical ventilation initiation are as follows: pH 7.45, Paco 2 34 mm Hg, Pao2 110 mm Hg, and HCO 3 24 mmol/L with Sao2 88%. Which of the following strategies is most appropriate at this time?", "context": "", "options": [{"key": "A", "text": "Cisatracurium, furosemide, and prone positioning.", "sourceKey": "A"}, {"key": "B", "text": "Cistatracurium, furosemide, and ECMO.", "sourceKey": "B"}, {"key": "C", "text": "Prone positioning, dexamethasone, and cisatracurium.", "sourceKey": "C"}, {"key": "D", "text": "Prone positioning, dexamethasone, and ECMO.", "sourceKey": "D"}], "answer": "C", "explanation": "ECMO may not be the most appropriate strategy at this time considering the patient has moderate to severe ARDS with corresponding Pao2 of 110 mm Hg on lung protective mechanical ventilation alone (Answers B and D are incorrect). Furosemide may not be the most appropriate strategy because the patient is currently requiring vasoactive support (Answers A and B and incorrect). Cisatracurium may be indicated for this patient considering the plateau pressure is elevated as well as prone positioning to help improve oxygenation with suboptimal parameters on mechanical ventilation along; furthermore, corticosteroids may also be indicated given ARDS severity and timing (Answer C is correct).", "page": 16, "answerPage": 26, "stemZh": "D.J.，49 歲男性，septic shock 需 vasoactive support，ARDS。MV：tidal volume 400 mL、RR 26/min、PEEP 20 cm H2O、FiO2 100%、plateau pressure 40 mm Hg。ABG：pH 7.45、PaCO2 34、PaO2 110 mm Hg、HCO3 24 mmol/L、SaO2 88%。最佳策略？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Cisatracurium、furosemide、prone positioning"}, {"key": "B", "text": "Cisatracurium、furosemide、ECMO"}, {"key": "C", "text": "Prone positioning、dexamethasone、cisatracurium"}, {"key": "D", "text": "Prone positioning、dexamethasone、ECMO"}], "explanationZh": "Plateau pressure 明顯升高，可採 cisatracurium；moderate-to-severe ARDS 可考慮 prone、steroid。仍在 vasoactive support 下，不選 furosemide；教材認為尚不先選 ECMO。"}, {"id": "18-case-06", "chapter": 18, "type": "case", "number": 6, "stem": "A 55-year-old man (weight 75 kg) is admitted to the burn ICU after a 65% total body surface area burn to the abdomen, back, and lower extremities from a house fire. He is unconscious and unable to protect his airway. His medical history is significant for hypertension and hyperlipidemia. He is currently receiving high-dose norepinephrine and vasopressin to maintain a MAP of 65 mm Hg. His current laboratory test results show the following: sodium (Na) 130 mEq/L, potassium (K) 5.9 mEq/L, chloride (Cl) 122 mEq/L, carbon dioxide (CO 2 ) 15 mg/dL, blood urea nitrogen (BUN) 10 mg/dL, and serum creatinine (SCr) 1.3 mg/dL. Which group of medications would be most appropriate for RSI?", "context": "", "options": [{"key": "A", "text": "Fentanyl, propofol, rocuronium.", "sourceKey": "E"}, {"key": "B", "text": "Fentanyl, ketamine, succinylcholine.", "sourceKey": "F"}, {"key": "C", "text": "Fentanyl, etomidate, rocuronium.", "sourceKey": "G"}, {"key": "D", "text": "Fentanyl, propofol, succinylcholine.", "sourceKey": "H"}], "answer": "C", "explanation": "Propofol, ketamine, and etomidate can all be used for induction. Propofol may worsen hypotension; therefore, because this patient is already receiving vasoactive medications to maintain his blood pressure, propofol would not be ideal (Answer A is incorrect). Succinylcholine causes the up-regulation of acetylcholine receptors, predisposing the muscle fibers to release excess potassium because they are depolarized, which leads to significant dysrhythmias or cardiac arrest (Answers B and D are incorrect). Appropriate induction and neuromuscular blockade in this patient would be to administer etomidate (indicated for hemodynamically unstable patients), fentanyl (providing adequate analgesia), and rocuronium (does not increase serum potassium) (Answer C is correct).", "page": 20, "answerPage": 26, "stemZh": "55 歲男性（75 kg），火災後腹部、背部、下肢共 65% TBSA burn，失去意識且不能保護 airway。Hypertension、hyperlipidemia 病史，需 high-dose norepinephrine、vasopressin 維持 MAP 65 mm Hg。Na 130、K 5.9、Cl 122 mEq/L、CO2 15 mg/dL、BUN 10 mg/dL、SCr 1.3 mg/dL。最佳 RSI 組合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Fentanyl、propofol、rocuronium"}, {"key": "B", "text": "Fentanyl、ketamine、succinylcholine"}, {"key": "C", "text": "Fentanyl、etomidate、rocuronium"}, {"key": "D", "text": "Fentanyl、propofol、succinylcholine"}], "explanationZh": "血壓不穩避免 propofol 加重 hypotension；hyperkalemia 與 burn 情境避免 succinylcholine。Etomidate、fentanyl、rocuronium 分別提供 induction、analgesia 與 neuromuscular blockade。"}, {"id": "18-case-07", "chapter": 18, "type": "case", "number": 7, "stem": "A 39-year-old homeless man (weight 70 kg) was admitted to the neurosciences ICU with a traumatic head injury after falling off a 3-ft ladder while intoxicated. Imaging reveals a subdural hematoma. The team decides to intubate this patient. His current laboratory values are as follows: Na 133 mEq/L, K 4.5 mEq/L, Cl 97 mEq/L, CO 2 28 mg/dL, BUN 13 mg/dL, SCr 0.7 mg/dL, and glucose 140 mg/dL. Which induction medication would be most appropriate to use for RSI?", "context": "", "options": [{"key": "A", "text": "Propofol 90 mg intravenous push.", "sourceKey": "I"}, {"key": "B", "text": "Ketamine 100 mg intravenous push.", "sourceKey": "J"}, {"key": "C", "text": "Midazolam 15 mg intravenous push.", "sourceKey": "K"}, {"key": "D", "text": "Etomidate 150 mg intravenous push. MECHANICAL VENTILATION", "sourceKey": "L"}], "answer": "B", "explanation": "Although propofol may promptly lower ICP, it can also induce hypotension and thus decrease cerebral perfusion pressure (Answer A is incorrect). Midazolam could be used as an induction agent; however, it is not the best agent for RSI because of its delayed onset of action (Answer C is incorrect). Etomidate may be considered in the setting of increased ICP; however, the dose in this case is too high (Answer D is incorrect). Ketamine not only decreases ICP but also prevents fluctuations in ICP (Answer B is correct).", "page": 20, "answerPage": 27, "stemZh": "39 歲男性（70 kg），無家可歸，酒醉自 3-ft 梯子跌落，traumatic head injury、subdural hematoma，準備 RSI。Na 133、K 4.5、Cl 97 mEq/L、CO2 28 mg/dL、BUN 13 mg/dL、SCr 0.7 mg/dL、glucose 140 mg/dL。最佳 induction medication？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Propofol 90 mg IV push"}, {"key": "B", "text": "Ketamine 100 mg IV push"}, {"key": "C", "text": "Midazolam 15 mg IV push"}, {"key": "D", "text": "Etomidate 150 mg IV push"}], "explanationZh": "教材選 ketamine，考量 ICP 與 hemodynamics。Propofol 可能降低 cerebral perfusion；midazolam onset 較慢；etomidate 150 mg 明顯過量。"}, {"id": "18-case-08", "chapter": 18, "type": "case", "number": 8, "stem": "A 74-year-old woman (height 63 inches, weight 65 kg) is transferred to your ICU from an outside hospital after admission for hypoxic respiratory failure. She had been treated at the outside hospital for ARDS for 3 days before her son requested transfer. When the patient arrives in your ICU, she is receiving MV with the following settings: SIMV mode, tidal volume 600 mL (12 mL/kg), respiratory rate 12 breaths/minute, PS 10 cm H 2 O, and PEEP 10 cm H 2 O. Which is the best ventilator plan for treating her ARDS?", "context": "", "options": [{"key": "A", "text": "AC/VC mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O.", "sourceKey": "M"}, {"key": "B", "text": "SIMV mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O.", "sourceKey": "N"}, {"key": "C", "text": "PS mode, PS 10 cm H 2 O, PEEP 5 cm H 2 O.", "sourceKey": "O"}, {"key": "D", "text": "SIMV mode, tidal volume 300 mL (6 mL/kg), respiratory rate 10 breaths/minute, PS 10 cm H 2 O, PEEP 5 cm H 2 O.", "sourceKey": "P"}], "answer": "A", "explanation": "After recognizing that the patient has ARDS, a lungprotective ventilation strategy should be implemented (tidal volume 4–6 mL/kg). Choosing a PS or SIMV mode would allow the patient to initiate spontaneous breaths in excess of the goal tidal volume (Answers B–D are incorrect). In the ARDSNet study of tidal volume strategy, the AC mode was most commonly used to promote the application of low tidal volumes (Answer A is correct).", "page": 22, "answerPage": 27, "stemZh": "74 歲女性（63 inches、65 kg），外院 hypoxic respiratory failure、ARDS 已治療 3 天後轉院。目前 SIMV、tidal volume 600 mL（12 mL/kg）、RR 12/min、PS 10 cm H2O、PEEP 10 cm H2O。最佳 ventilator plan？", "contextZh": "", "optionsZh": [{"key": "A", "text": "AC/VC，tidal volume 300 mL（6 mL/kg）、RR 20/min、PS 10、PEEP 5 cm H2O"}, {"key": "B", "text": "SIMV，tidal volume 300 mL（6 mL/kg）、RR 20/min、PS 10、PEEP 5 cm H2O"}, {"key": "C", "text": "PS mode，PS 10、PEEP 5 cm H2O"}, {"key": "D", "text": "SIMV，tidal volume 300 mL（6 mL/kg）、RR 10/min、PS 10、PEEP 5 cm H2O"}], "explanationZh": "應採 lung-protective tidal volume；教材偏好 AC mode，避免 PS/SIMV 中 spontaneous breaths 超過設定目標 volume。"}, {"id": "19-self-01", "chapter": 19, "type": "self", "number": 1, "stem": "A 21-year-old woman (height 62 inches, weight 50 kg) with a medical history significant for cystic fibrosis (CF) is admitted to the intensive care unit (ICU) with acute respiratory failure requiring mechanical ventilation (MV). After intubation, her arterial blood gas (ABG) results are as follows: pH 7.27, PaCO 2 45 mm Hg, bicarbonate 22 mEq/L, PaO 2 55 mm Hg, and oxygen saturation (SaO 2 ) 88%. Her ventilator settings are as follows: assist control/volume control (AC/VC) mode, tidal volume 300 mL (6 mL/kg), respiratory rate 20 breaths/minute, fraction of inspired oxygen 60%, pressure support 5 cm H 2 O, and positive end-expiratory pressure (PEEP) 5 cm H 2 O. Her blood pressure is 110/70 mm Hg and heart rate is 95 beats/minute. Which is the best holistic therapy plan?", "context": "", "options": [{"key": "A", "text": "Initiate cefepime 2 g intravenously every 8 hours and tobramycin 150 mg intravenously every 8 hours; intravenous fluid resuscitation to maintain a central venous pressure (CVP) goal of 10–14 mm Hg; dornase alfa and hypertonic saline 7% nebulization.", "sourceKey": "A"}, {"key": "B", "text": "Initiate cefepime 2 g intravenously every 8 hours and tobramycin 500 mg intravenously every 8 hours; intravenous fluid resuscitation to maintain a CVP goal of 10–14 mm Hg; dornase alfa and hypertonic saline 7% nebulization.", "sourceKey": "B"}, {"key": "C", "text": "Initiate cefepime 2 g intravenously every 8 hours and tobramycin 150 mg intravenously every 8 hours; intravenous fluid resuscitation to maintain a CVP goal of 10–14 mm Hg.", "sourceKey": "C"}, {"key": "D", "text": "Initiate cefepime 2 g intravenously every 8 hours and tobramycin 500 mg intravenously every 24 hours; diuresis to maintain a CVP goal of less than 4 mm Hg while mean arterial pressure is greater than 65 mm Hg; dornase alfa and hypertonic saline 7% nebulization.", "sourceKey": "D"}], "answer": "D", "explanation": "It is imperative to recognize that this patient has acute respiratory distress syndrome (ARDS) caused by a CF exacerbation. Therefore, an inclusive therapy plan should include appropriate treatments for ARDS and CF. For ARDS, a lung-protective ventilation strategy (tidal volume 4–6 mL/kg) and a fluid-conservative strategy (CVP less than 4 mm Hg, if not in shock) are of utmost importance (Answers A and C are incorrect because of the CVP goal; Answer D is correct). Appropriate treatment of the CF exacerbation includes empiric therapy for P. aeruginosa in the form of optimal doses of a β-lactam and aminoglycoside (Answer B is incorrect because of the inappropriate tobramycin dose and CVP goal of 10–14 mm Hg).", "page": 4, "answerPage": 41, "stemZh": "21 歲女性（62 inches、50 kg），CF，因 acute respiratory failure 插管。pH 7.27、PaCO2 45、PaO2 55 mm Hg、HCO3 22 mEq/L、SaO2 88%。AC/VC、tidal volume 300 mL（6 mL/kg）、RR 20/min、FiO2 60%、PS 5、PEEP 5 cm H2O。BP 110/70 mm Hg、HR 95/min。最佳整體計畫？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Cefepime 2 g IV q8h、tobramycin 150 mg IV q8h；fluids 維持 CVP 10–14 mm Hg；dornase alfa、7% hypertonic saline nebulization"}, {"key": "B", "text": "Cefepime 2 g IV q8h、tobramycin 500 mg IV q8h；fluids 維持 CVP 10–14 mm Hg；dornase alfa、7% hypertonic saline nebulization"}, {"key": "C", "text": "Cefepime 2 g IV q8h、tobramycin 150 mg IV q8h；fluids 維持 CVP 10–14 mm Hg"}, {"key": "D", "text": "Cefepime 2 g IV q8h、tobramycin 500 mg IV q24h；diuresis 維持 CVP <4 mm Hg 且 MAP >65 mm Hg；dornase alfa、7% hypertonic saline nebulization"}], "explanationZh": "需同時處理 CF exacerbation 與 ARDS：適當 antipseudomonal β-lactam/aminoglycoside dosing、mucus clearance、lung-protective MV，無 shock 時 conservative fluids。"}, {"id": "19-self-02", "chapter": 19, "type": "self", "number": 2, "stem": "Which adjunctive measure for a CF exacerbation has the highest quality of evidence for improving patient outcomes?", "context": "", "options": [{"key": "A", "text": "Normal saline (0.9%) nebulization.", "sourceKey": "A"}, {"key": "B", "text": "Corticosteroid administration.", "sourceKey": "B"}, {"key": "C", "text": "Concurrent administration of intravenous and inhaled antibiotics.", "sourceKey": "C"}, {"key": "D", "text": "Aggressive chest physical therapy.", "sourceKey": "D"}], "answer": "D", "explanation": "The highest quality of evidence for improved outcomes with CF exacerbations is with adjunctive therapy for mucous clearance. The guidelines recommend airway clearance options such as aggressive chest physical therapy, nebulized dornase alfa, and hypertonic saline as a grade B recommendation (Answer D is correct). Hypertonic saline would be appropriate, but nebulization of normal saline is not included in any of the recommendations (Answer A is incorrect). Both corticosteroid administration and concurrent administration of intravenous and inhaled antibiotics have a grade I recommendation, meaning evidence is insuffi- cient to support them (Answers B and C are incorrect).", "page": 5, "answerPage": 41, "stemZh": "CF exacerbation 的哪項 adjunctive treatment，改善 outcomes 的證據品質最高？", "contextZh": "", "optionsZh": [{"key": "A", "text": "0.9% normal saline nebulization"}, {"key": "B", "text": "Corticosteroids"}, {"key": "C", "text": "同時 IV 與 inhaled antibiotics"}, {"key": "D", "text": "積極 chest physical therapy"}], "explanationZh": "Airway clearance 包括 chest physical therapy、dornase alfa、hypertonic saline 有較佳證據；routine steroids、同時 IV/inhaled antibiotics 證據不足。"}, {"id": "19-self-03", "chapter": 19, "type": "self", "number": 3, "stem": "A 55-year-old woman with pulmonary artery hypertension (PAH) is admitted to the ICU for severe respiratory failure. She reports increased work of breathing for the past 5 days and full adherence to her PAH medication regimen, which includes macitentan 10 mg daily and sildenafil 40 mg three times daily. Her current vital signs are as follows: blood pressure 76/60 mm Hg, heart rate 140 beats/minute, respiratory rate 30 breaths/minute, and 85% SaO 2 on 6 L of nasal cannula. Right heart catheterization reveals the following: mean pulmonary artery pressure (mPAP) 50 mm Hg, right atrial pressure 25 mm Hg, cardiac index 1.9 L/minute/m2, and pulmonary capillary wedge pressure (PCWP) 16 mm Hg. A transthoracic echocardiogram reveals an ejection fraction of 60% with severe right ventricular (RV) dilatation. Which regimen would be most appropriate for this patient?", "context": "", "options": [{"key": "A", "text": "Dopamine infusion.", "sourceKey": "A"}, {"key": "B", "text": "Epoprostenol infusion.", "sourceKey": "B"}, {"key": "C", "text": "Phenylephrine infusion.", "sourceKey": "C"}, {"key": "D", "text": "Furosemide intravenous push.", "sourceKey": "D"}], "answer": "D", "explanation": "This patient presents with severe right heart failure. The primary goal is to optimize RV preload by maintaining a net negative fluid balance using gentle diuresis and blood pressure monitoring (Answer D is correct). Dopamine would increase blood pressure; however, it might worsen the patient’s tachycardia, thereby worsening her already tenuous clinical status (Answer A is incorrect). Epoprostenol would help decrease pulmonary pressures; however, epoprostenol would potentially worsen the patient’s blood pressure because of its peripheral vasodilating effects (Answer B is incorrect). Phenylephrine would not be optimal because this vasopressor might worsen RV function, further elevate pulmonary artery pressure by α1-receptors in the pulmonary vasculature, and potentially induce a reflex bradycardia (Answer C is incorrect).", "page": 5, "answerPage": 41, "stemZh": "55 歲女性 PAH，5 天 work of breathing 增加，持續服 macitentan 10 mg/day、sildenafil 40 mg TID。BP 76/60 mm Hg、HR 140/min、RR 30/min、6 L nasal cannula 下 SaO2 85%。RHC：mPAP 50、RAP 25、PCWP 16 mm Hg、CI 1.9 L/min/m2；TTE EF 60%、severe RV dilation。最佳 regimen？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dopamine infusion"}, {"key": "B", "text": "Epoprostenol infusion"}, {"key": "C", "text": "Phenylephrine infusion"}, {"key": "D", "text": "Furosemide IV push"}], "explanationZh": "教材優先以 gentle diuresis 降低過高 RV preload、嚴密監測 BP。Dopamine 可能加重 tachycardia，epoprostenol 可能加重 hypotension，phenylephrine 可能提高 pulmonary vascular resistance。"}, {"id": "19-self-04", "chapter": 19, "type": "self", "number": 4, "stem": "Which best describes one of the primary treatment goals for the management of PAH?", "context": "", "options": [{"key": "A", "text": "Achieve and maintain WHO functional class (FC) III or IV.", "sourceKey": "A"}, {"key": "B", "text": "Preserve 6-minute walk distance (6MWD) to greater than 300 m.", "sourceKey": "B"}, {"key": "C", "text": "Preserve RV size and function (right atrial pressure less than 8 mm Hg).", "sourceKey": "C"}, {"key": "D", "text": "Normalize B-type natriuretic peptide (BNP) (less than 200 ng/L).", "sourceKey": "D"}], "answer": "C", "explanation": "Treatment goals for PAH include, but are not limited to, achieving and maintaining WHO FC I or II (Answer A is incorrect), preserving 6MWD to greater than 440 m (Answer B is incorrect), and preserving RV size and function (right atrial pressure less than 8 mm Hg and cardiac index 2.5 L/minute/m2 or greater) (Answer C is correct). The clinician should normalize BNP to less than 50 ng/L (Answer D is incorrect).", "page": 5, "answerPage": 41, "stemZh": "PAH management 的主要目標，何者正確？", "contextZh": "", "optionsZh": [{"key": "A", "text": "達到並維持 WHO FC III 或 IV"}, {"key": "B", "text": "6MWD >300 m"}, {"key": "C", "text": "保留 RV size/function，RAP <8 mm Hg"}, {"key": "D", "text": "BNP 正常化至 <200 ng/L"}], "explanationZh": "教材目標為 WHO FC I–II、6MWD >440 m、RAP <8 mm Hg、CI ≥2.5 L/min/m2、BNP <50 ng/L，故 C 正確。"}, {"id": "19-self-05", "chapter": 19, "type": "self", "number": 5, "stem": "A 42-year-old man presents to the emergency department (ED) with anxiety and shortness of breath. Auscultation reveals audible wheezing. He has difficulty speaking in full sentences. He has used his albuterol metered dose inhaler (MDI) at home for the past several hours without symptom resolution. His forced expiratory volume in the first second of expiration (FEV 1 ) is 35% of predicted. Which best classifies this patient’s asthma exacerbation?", "context": "", "options": [{"key": "A", "text": "Mild.", "sourceKey": "A"}, {"key": "B", "text": "Moderate.", "sourceKey": "B"}, {"key": "C", "text": "Severe.", "sourceKey": "C"}, {"key": "D", "text": "Life threatening.", "sourceKey": "D"}], "answer": "C", "explanation": "This patient has shortness of breath at rest that is interfering with his conversational ability, and his FEV 1 is less than 50% of predicted; therefore, his asthma exacerbation would be classified as severe (Answer C is correct). FEV 1 would be greater than 50% in mild/ moderate asthma exacerbation (Answers A and B are incorrect). In a life-threatening asthma exacerbation, the patient would have symptoms such as drowsiness, confusion, or silent chest. This patient could progress to life threatening but currently would not be classified as such (Answer D is incorrect).", "page": 5, "answerPage": 41, "stemZh": "42 歲男性焦慮、dyspnea、明顯 wheezing，無法完整說句子，家中 albuterol MDI 數小時無效，FEV1 為 predicted 35%。Asthma exacerbation 最適當分類？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Mild"}, {"key": "B", "text": "Moderate"}, {"key": "C", "text": "Severe"}, {"key": "D", "text": "Life threatening"}], "explanationZh": "FEV1 <50%、休息時 dyspnea 影響說話，為 severe。Life-threatening 常有 drowsiness、confusion、silent chest；本題尚無這些表現。"}, {"id": "19-self-06", "chapter": 19, "type": "self", "number": 6, "stem": "A 55-year-old man presents to the ED with a 2-week history of progressive shortness of breath, wheezing, and dyspnea at rest. He is confused and speaking in short phrases but can indicate that his inhaled bronchodilator has failed to improve his symptoms for the past 2 days. He is afebrile with heart rate 116 beats/minute, respiratory rate 32 breaths/minute, and SaO 2 86% on room air. He is placed on supplemental oxygen and administered albuterol nebulization and methylprednisolone 125 mg intravenously ×1. One hour later, his oxygenation has not improved. Which adjunctive therapy would be best to add to his current regimen?", "context": "", "options": [{"key": "A", "text": "Antimicrobial agents directed at communityacquired pathogens.", "sourceKey": "A"}, {"key": "B", "text": "Magnesium sulfate 2 g intravenously over 20 minutes.", "sourceKey": "B"}, {"key": "C", "text": "Theophylline 4.6 mg/kg intravenous loading dose; then obtain serum concentration in 30 minutes to guide further dosing.", "sourceKey": "C"}, {"key": "D", "text": "Acetylcysteine 20% 3 mL, nebulized every 6 hours.", "sourceKey": "D"}], "answer": "B", "explanation": "This patient presents with near-fatal asthma that is unresponsive to initial therapy. Magnesium sulfate (2 g intravenously administered over 20–30 minutes) can be considered in patients who have life-threatening exacerbations and are unresponsive to conventional therapies after 1 hour (Answer B is correct). Antimicrobials are not routinely recommended for asthma exacerbations if the patient has no evidence of concurrent infection (Answer A is incorrect). Because of the lack of improved outcomes, risk of adverse effects, and superior bronchodilation with SABAs, methylxanthines (theophylline and aminophylline) are not recommended for acute asthma exacerbations (Answer C is incorrect). Mucolytic agents are irritating and may worsen cough and airflow obstruction (Answer D is incorrect).", "page": 5, "answerPage": 41, "stemZh": "55 歲男性，2 週逐漸 dyspnea、wheezing，休息也 dyspnea；confusion，只能短句，2 天 inhaled bronchodilator 無效。無發燒，HR 116/min、RR 32/min、room-air SaO2 86%。給 oxygen、albuterol nebulization、methylprednisolone 125 mg IV 一次，1 小時後氧合仍無改善。最佳 adjunctive treatment？", "contextZh": "", "optionsZh": [{"key": "A", "text": "給針對 community-acquired pathogens 的 antibiotics"}, {"key": "B", "text": "Magnesium sulfate 2 g IV，輸注 20 分鐘"}, {"key": "C", "text": "Theophylline 4.6 mg/kg IV loading，30 分鐘後測濃度調整"}, {"key": "D", "text": "Acetylcysteine 20% 3 mL nebulized q6h"}], "explanationZh": "對初始治療無效的 life-threatening asthma，可加 magnesium sulfate 2 g IV 20–30 分鐘。無 infection 不常規 antibiotics；methylxanthines 效益不足且 adverse effects 多；mucolytics 可刺激氣道。"}, {"id": "19-self-07", "chapter": 19, "type": "self", "number": 7, "stem": "A 66-year-old man presents to the ICU with acute respiratory failure from a chronic obstructive pulmonary disease exacerbation (ECOPD). He has had no exacerbations in the past 2 years. His home medications include albuterol hydrofluoroalkane 2 puffs four times daily as needed and tiotropium 1 puff once daily. The patient denies any recent sick contacts or changes in sputum production. He has no known drug allergies. He is placed on 3 L of nasal cannula (SaO 2 97%) and inhaled albuterol and ipratropium by nebulization. Which other therapy would be most appropriate for this patient?", "context": "", "options": [{"key": "A", "text": "Azithromycin 500 mg intravenously daily.", "sourceKey": "A"}, {"key": "B", "text": "Prednisone 40 mg orally daily.", "sourceKey": "B"}, {"key": "C", "text": "Levofloxacin 500 mg orally daily.", "sourceKey": "C"}, {"key": "D", "text": "Methylprednisolone 125 mg intravenously every 6 hours.", "sourceKey": "D"}], "answer": "B", "explanation": "The recommended corticosteroid dose for an ECOPD is prednisone 40 mg orally once daily (Answer D is incorrect; Answer B is correct). Antimicrobial treatment should be initiated if (1) all three cardinal symptoms of an ECOPD (increased dyspnea, increased sputum production, and increased sputum purulence) are present; (2) two of the three cardinal signs are present, with increased sputum purulence as one of the symptoms; or (3) the patient requires noninvasive or invasive ventilation. This patient has no indication for antimicrobials (Answers A and C are incorrect).", "page": 6, "answerPage": 41, "stemZh": "66 歲男性 ECOPD acute respiratory failure，2 年無 exacerbations；家中 albuterol HFA 2 puffs QID PRN、tiotropium 1 puff/day。無最近接觸病人或 sputum 改變，無 drug allergy。3 L nasal cannula 下 SaO2 97%，已給 albuterol/ipratropium nebulization。最適當追加治療？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Azithromycin 500 mg IV/day"}, {"key": "B", "text": "Prednisone 40 mg PO/day"}, {"key": "C", "text": "Levofloxacin 500 mg PO/day"}, {"key": "D", "text": "Methylprednisolone 125 mg IV q6h"}], "explanationZh": "教材 ECOPD 建議 prednisone 40 mg/day；本題缺乏增加 sputum/purulence 或 MV 等 antibiotic indication，不選 antibiotics 或過高 steroid dose。"}, {"id": "19-self-08", "chapter": 19, "type": "self", "number": 8, "stem": "A 65-year-old Black man (height 177.8 cm, weight 90 kg, SCr 1.5 mg/dL) presents with a medical history of end-stage renal disease on dialysis, COPD, hypertension, and hyperlipidemia. He is admitted from home to the ICU with respiratory failure. His symptoms before admission included shortness of breath, cough, increased sputum production, purulence, and fever. His respiratory viral panel is positive for rhinovirus. His SaO 2 is 85% on room air; he is placed on high-flow nasal cannula (HFNC) 40 L/minute, fraction of inspired oxygen (FiO 2 ) 60%. The patient’s work of breathing decreases, and after 15 minutes, his SaO 2 is 97%. He is continued on the same HFNC settings. He has been administered methylprednisolone 60 mg intravenously once and azithromycin 500 mg intravenously once. Which best depicts the current intervention for this patient that has demonstrated an increase in mortality?", "context": "", "options": [{"key": "A", "text": "Corticosteroid dose higher than prednisone 40 mg oral equivalent.", "sourceKey": "A"}, {"key": "B", "text": "Titration of oxygen to peripheral SaO 2 .", "sourceKey": "B"}, {"key": "C", "text": "Azithromycin dose greater than 250 mg.", "sourceKey": "C"}, {"key": "D", "text": "Maintaining SaO 2 greater than 92%.", "sourceKey": "D"}], "answer": "D", "explanation": "Although the GOLD-recommended dose of steroids for an ECOPD is prednisone 40 mg orally (or intravenously), some studies that included populations of ICU patients have shown higher doses may be needed or may be tolerated with some increase in adverse effects. Currently, doses higher than prednisone 40 mg have not been linked to increased mortality (Answer A is incorrect). A recent investigation identified significant racial bias in the use of peripheral SaO 2 because of frequent overestimation of SaO 2 compared with a direct ABG measurement for patients with darker skin tones. This answer is incorrect because the publication did not investigate patient outcomes. This patient has a higher SpO 2 measure than the patients in the study (92%–96%), who had a high rate of hypoxemia identified on ABG. Answer C is incorrect because no specific dose of macrolide has been linked to mortality, and azithromycin 500 mg intravenously once is the recommended loading dose. Answer D is correct because titrating oxygen therapy to peripheral SaO 2 greater than 88%–92% has been linked to mortality. The correct intervention would have been to decrease the FiO 2 when the patient had an SaO 2 greater than 92%.", "page": 6, "answerPage": 42, "stemZh": "65 歲 Black 男性（177.8 cm、90 kg、SCr 1.5 mg/dL），ESRD dialysis、COPD、hypertension、hyperlipidemia；dyspnea、cough、sputum 增加且 purulent、fever，rhinovirus 陽性。Room-air SaO2 85%，HFNC 40 L/min、FiO2 60%，15 分鐘後 SaO2 97%，仍保持設定。已給 methylprednisolone 60 mg IV、azithromycin 500 mg IV 各一次。哪項目前介入曾與 increased mortality 相關？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Steroid dose 高於 prednisone 40 mg equivalent"}, {"key": "B", "text": "以 peripheral SaO2 調整 oxygen"}, {"key": "C", "text": "Azithromycin dose >250 mg"}, {"key": "D", "text": "維持 SaO2 >92%"}], "explanationZh": "教材指出 ECOPD 過度 oxygenation、SpO2 高於 88%–92% 目標可增加死亡風險；達 97% 後應評估下調 FiO2。"}, {"id": "19-case-01", "chapter": 19, "type": "case", "number": 1, "stem": "Which of the following would be best to manage her acute CF exacerbation?", "context": "A 20-year-old woman is admitted to the ICU for an acute CF exacerbation. Before admission, her condition had been stable. She had maintained her ideal body weight and had just completed a home regimen of suppressive antibiotics. The patient requires MV for the management of hypoxic respiratory failure. She is initiated on AC/ VC mode with a lung-protective strategy (4–8 mL/kg tidal volume).", "options": [{"key": "A", "text": "Tobramycin nebulization; hypertonic saline 7% nebulization; and tube feedings to target a hypocaloric goal during her acute illness (15 kcal/kg/day).", "sourceKey": "A"}, {"key": "B", "text": "Ceftriaxone 2 g intravenously every 24 hours; tobramycin nebulization; normal saline 0.9% nebulization; and tube feedings to target her goal caloric intake (25 kcal/kg/day).", "sourceKey": "B"}, {"key": "C", "text": "Piperacillin/tazobactam 4.5 g intravenously every 6 hours; tobramycin 10 mg/kg intravenously once daily; hypertonic saline 7% nebulization; and tube feedings to target her goal caloric intake (25 kcal/ kg/day).", "sourceKey": "C"}, {"key": "D", "text": "Cefepime 2 g intravenously every 8 hours extended infusion; tobramycin 10 mg/kg intravenously every 8 hours; hypertonic saline 7% nebulization; and tube feedings to target her goal caloric intake (25 kcal/ kg/day).", "sourceKey": "D"}], "answer": "C", "explanation": "The patient presents with a CF exacerbation, probably caused by an infection. The most likely causative organism of her infection is P. aeruginosa; therefore, therapy must be directed to P. aeruginosa (Answer B is incorrect). In addition, antibiotic treatment should include the empiric selection of two antibacterial agents, ideally a β-lactam and an aminoglycoside, dosed to effectively treat the infection (Answers A and D are incorrect). The ideal regimen should include a β-lactam dosed to treat P. aeruginosa – in this case, piperacillin/tazobactam at the recommended dose – and an aminoglycoside dosed once daily (Answer C is correct).", "page": 11, "answerPage": 39, "stemZh": "最佳 acute CF exacerbation 治療？", "contextZh": "20 歲女性 acute CF exacerbation 入 ICU；先前穩定、維持 ideal body weight，剛完成家中 suppressive antibiotics。需 MV 控制 hypoxic respiratory failure，已開始 AC/VC lung-protective strategy（tidal volume 4–8 mL/kg）。", "optionsZh": [{"key": "A", "text": "Tobramycin nebulization、7% hypertonic saline nebulization；tube feeding 15 kcal/kg/day"}, {"key": "B", "text": "Ceftriaxone 2 g IV q24h、tobramycin nebulization、0.9% saline nebulization；tube feeding 25 kcal/kg/day"}, {"key": "C", "text": "Piperacillin/tazobactam 4.5 g IV q6h、tobramycin 10 mg/kg IV once daily、7% hypertonic saline nebulization；tube feeding 25 kcal/kg/day"}, {"key": "D", "text": "Cefepime 2 g IV q8h extended infusion、tobramycin 10 mg/kg IV q8h、7% hypertonic saline nebulization；tube feeding 25 kcal/kg/day"}], "explanationZh": "最可能病原 P. aeruginosa，選適當劑量 antipseudomonal β-lactam 加 once-daily aminoglycoside；選項 D 的 tobramycin q8h 劑量過高。"}, {"id": "19-case-02", "chapter": 19, "type": "case", "number": 2, "stem": "After treatment with intravenous antibiotics, aggressive chest physical therapy, and her maintenance CF medications for 5 days, this patient improved and was extubated. She was moved out of the ICU on day 6 of her hospitalization. Which duration of antibiotics would be best to recommend for this patient?", "context": "A 20-year-old woman is admitted to the ICU for an acute CF exacerbation. Before admission, her condition had been stable. She had maintained her ideal body weight and had just completed a home regimen of suppressive antibiotics. The patient requires MV for the management of hypoxic respiratory failure. She is initiated on AC/ VC mode with a lung-protective strategy (4–8 mL/kg tidal volume).", "options": [{"key": "A", "text": "7 days.", "sourceKey": "A"}, {"key": "B", "text": "10 days.", "sourceKey": "B"}, {"key": "C", "text": "14 days.", "sourceKey": "C"}, {"key": "D", "text": "Until cultures are negative.", "sourceKey": "D"}], "answer": "B", "explanation": "According to the STOP2 trial, patients who improve within 7 days of antimicrobial therapy can complete 10 days of antimicrobials. These patients’ clinical outcomes are noninferior to those of patients who continue antimicrobials for 14 days (Answer B is correct). Answer A is incorrect; 7 days is too short for an exacerbation of CF. Answer C is incorrect, given the results of the STOP2 trial. Answer D is incorrect because microbiological cure is neither expected nor likely for patients with CF.", "page": 11, "answerPage": 39, "stemZh": "IV antibiotics、積極 chest physical therapy 與 maintenance CF medications 治療 5 天後改善、extubated，第 6 天轉出 ICU。最佳 antibiotic duration？", "contextZh": "20 歲女性 acute CF exacerbation 入 ICU；先前穩定、維持 ideal body weight，剛完成家中 suppressive antibiotics。需 MV 控制 hypoxic respiratory failure，已開始 AC/VC lung-protective strategy（tidal volume 4–8 mL/kg）。", "optionsZh": [{"key": "A", "text": "7 天"}, {"key": "B", "text": "10 天"}, {"key": "C", "text": "14 天"}, {"key": "D", "text": "直到 cultures 陰性"}], "explanationZh": "STOP2 中治療 7 天內改善的族群，10 天療程 noninferior 於 14 天。CF 不期待完全 microbiological eradication。"}, {"id": "19-case-03", "chapter": 19, "type": "case", "number": 3, "stem": "Which best describes his WHO FC and risk of mortality in the next year?", "context": "A 44-year-old man is transferred to the medical ICU for treatment of his worsening PAH. He currently receives no PAH treatment. The patient has had increased dyspnea on exertion for the past 6 months with exercise. For the past 2 months, he has had difficulty going for walks with his dog without getting fatigued, and occasionally, he has chest pain. In the past few days, he has had severe shortness of breath at rest, which prompted him to come to the hospital. His physical examination is remarkable for blood pressure 105/64 mm Hg and heart rate 85 beats/ minute. Lung examination is clear, and extremities are notable for trace edema. An echocardiogram reveals an elevated pulmonary systolic pressure and a normal ejection fraction. The patient has an unfavorable response to vasodilator challenge. Pertinent laboratory data are serum urea nitrogen 10 mg/dL, SCr 0.6 mg/dL, AST 160 U/L, and ALT 100 U/L.", "options": [{"key": "A", "text": "WHO FC III, mortality risk 5%.", "sourceKey": "E"}, {"key": "B", "text": "WHO FC III, mortality risk 10%.", "sourceKey": "F"}, {"key": "C", "text": "WHO FC IV, mortality risk 15%.", "sourceKey": "G"}, {"key": "D", "text": "WHO FC IV, mortality risk greater than 20%.", "sourceKey": "H"}], "answer": "D", "explanation": "This patient has signs of right heart failure and rapid progression of symptoms, which place him in the highrisk category for mortality within 1 year (greater than 20%) (Answers A, B, and C are incorrect). In addition, he has symptoms at rest, which place him in WHO FC IV (Answer D is correct).", "page": 21, "answerPage": 39, "stemZh": "WHO FC 與未來一年 mortality risk 最適當分類？", "contextZh": "44 歲男性 PAH 惡化轉 ICU，未接受 PAH therapy。6 個月 exertional dyspnea，2 個月遛狗容易疲累、偶有 chest pain，最近幾天休息也 severe dyspnea。BP 105/64 mm Hg、HR 85/min，lung clear、trace edema。Echo pulmonary systolic pressure 升高、EF 正常；vasodilator challenge 不佳。BUN 10 mg/dL、SCr 0.6 mg/dL、AST 160 U/L、ALT 100 U/L。", "optionsZh": [{"key": "A", "text": "WHO FC III，5%"}, {"key": "B", "text": "WHO FC III，10%"}, {"key": "C", "text": "WHO FC IV，15%"}, {"key": "D", "text": "WHO FC IV，>20%"}], "explanationZh": "休息時症狀為 WHO FC IV；right heart failure 與快速惡化符合高風險，教材列一年 mortality >20%。"}, {"id": "19-case-04", "chapter": 19, "type": "case", "number": 4, "stem": "Which medication therapy would be best to recommend initiating at this time?", "context": "A 44-year-old man is transferred to the medical ICU for treatment of his worsening PAH. He currently receives no PAH treatment. The patient has had increased dyspnea on exertion for the past 6 months with exercise. For the past 2 months, he has had difficulty going for walks with his dog without getting fatigued, and occasionally, he has chest pain. In the past few days, he has had severe shortness of breath at rest, which prompted him to come to the hospital. His physical examination is remarkable for blood pressure 105/64 mm Hg and heart rate 85 beats/ minute. Lung examination is clear, and extremities are notable for trace edema. An echocardiogram reveals an elevated pulmonary systolic pressure and a normal ejection fraction. The patient has an unfavorable response to vasodilator challenge. Pertinent laboratory data are serum urea nitrogen 10 mg/dL, SCr 0.6 mg/dL, AST 160 U/L, and ALT 100 U/L.", "options": [{"key": "A", "text": "Epoprostenol infusion at 2 ng/kg/minute.", "sourceKey": "A"}, {"key": "B", "text": "Diltiazem 180 mg orally daily.", "sourceKey": "B"}, {"key": "C", "text": "Macitentan 10 mg orally daily.", "sourceKey": "C"}, {"key": "D", "text": "Sildenafil 10 mg intravenously three times daily.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient’s symptoms and physical findings place him in WHO FC IV. His unfavorable response to the vasodilator challenge makes CCBs an undesirable class of medications for him (Answer B is incorrect). Epoprostenol continuous infusion is indicated for patients with PAH presenting with WHO FC IV to improve symptoms, exercise capacity, and hemodynamics. In addition, it is the only treatment shown to reduce mortality in PAH (Answer A is correct). Macitentan and sildenafil could be considered in this patient; however, his elevated liver enzymes do not make macitentan an ideal agent (Answer C is incorrect). Intravenous sildenafil is also not ideal because of the hypotension associated with the intravenous formulation (Answer D is incorrect).", "page": 21, "answerPage": 39, "stemZh": "最適當開始哪項 therapy？", "contextZh": "44 歲男性 PAH 惡化轉 ICU，未接受 PAH therapy。6 個月 exertional dyspnea，2 個月遛狗容易疲累、偶有 chest pain，最近幾天休息也 severe dyspnea。BP 105/64 mm Hg、HR 85/min，lung clear、trace edema。Echo pulmonary systolic pressure 升高、EF 正常；vasodilator challenge 不佳。BUN 10 mg/dL、SCr 0.6 mg/dL、AST 160 U/L、ALT 100 U/L。", "optionsZh": [{"key": "A", "text": "Epoprostenol infusion 2 ng/kg/minute"}, {"key": "B", "text": "Diltiazem 180 mg PO/day"}, {"key": "C", "text": "Macitentan 10 mg PO/day"}, {"key": "D", "text": "Sildenafil 10 mg IV TID"}], "explanationZh": "WHO FC IV 適用 continuous IV epoprostenol。Vasodilator challenge 陰性不適用 high-dose CCB；liver enzymes 高與 BP 風險使其他選項較不理想。"}, {"id": "19-case-05", "chapter": 19, "type": "case", "number": 5, "stem": "Which best represents the patient’s risk factors for higher mortality?", "context": "A 30-year-old woman (weight 115 kg) with status asthmaticus is admitted to the ICU. She has a history of severe refractory asthma that has required endotracheal intubation three times in the past 6 months. Her medical history includes hypertension, diabetes, obesity, and bipolar disorder. She has used at least three canisters of albuterol per month for the past 2 months to manage her symptoms.", "options": [{"key": "A", "text": "Three hospitalizations in the past 6 months and bipolar disorder.", "sourceKey": "A"}, {"key": "B", "text": "Use of more than two canisters of SABAs in the past month and obesity.", "sourceKey": "B"}, {"key": "C", "text": "Hospitalization for asthma in the past month and diabetes.", "sourceKey": "C"}, {"key": "D", "text": "Prior episode of near-fatal asthma and hypertension.", "sourceKey": "D"}], "answer": "C", "explanation": "Risk factors for increased mortality in patients with asthma include (1) history of near-fatal asthma (e.g., requiring mechanical ventilation); (2) hospitalization or ED visit for asthma in the past year; (3) active use of oral corticosteroids or completion of recent course for asthma; (4) not currently using inhaled corticosteroids; (5) use of more than one canister of SABAs per month; (6) poor adherence to inhaled corticosteroid containing asthma medications and/or poor adherence to asthma action plan; (7) social history that includes major psychosocial problems or psychiatric illness; (8) food allergies; (9) comorbidities including pneumonia, diabetes, and arrhythmias. Two of the patient’s listed characteristics are risk factors (Answer C is correct). Other answers include one risk factor or none (Answers A, B, and D are incorrect).", "page": 26, "answerPage": 39, "stemZh": "哪些特徵最符合較高 mortality risk？", "contextZh": "30 歲女性（115 kg），status asthmaticus 入 ICU，severe refractory asthma，6 個月內曾 3 次需插管。有 hypertension、diabetes、obesity、bipolar disorder；2 個月來每月用至少 3 canisters albuterol。", "optionsZh": [{"key": "A", "text": "6 個月內住院 3 次與 bipolar disorder"}, {"key": "B", "text": "過去 1 個月用 >2 canisters SABA 與 obesity"}, {"key": "C", "text": "過去 1 個月因 asthma 住院與 diabetes"}, {"key": "D", "text": "曾 near-fatal asthma 與 hypertension"}], "explanationZh": "教材答案為 C，將近期 hospitalization 與 diabetes 列為風險。原題 A 的 psychiatric illness 與住院史也與解析列出的 risk factors 重疊；此題原書選項與解析有疑義，請開啟來源核對。"}, {"id": "19-case-06", "chapter": 19, "type": "case", "number": 6, "stem": "The patient is endotracheally intubated and placed on MV. Which would be the most appropriate initial therapy for this patient with life-threatening asthma exacerbation?", "context": "A 30-year-old woman (weight 115 kg) with status asthmaticus is admitted to the ICU. She has a history of severe refractory asthma that has required endotracheal intubation three times in the past 6 months. Her medical history includes hypertension, diabetes, obesity, and bipolar disorder. She has used at least three canisters of albuterol per month for the past 2 months to manage her symptoms.", "options": [{"key": "A", "text": "Inhaled albuterol by nebulization 2.5 mg every 4 hours.", "sourceKey": "A"}, {"key": "B", "text": "Inhaled albuterol by nebulization 2.5 mg every 4 hours and inhaled ipratropium by nebulization 0.5 mg every 6 hours.", "sourceKey": "B"}, {"key": "C", "text": "Inhaled albuterol by nebulization 2.5 mg every 4 hours, inhaled ipratropium by nebulization 0.5 mg every 6 hours, and methylprednisolone 40 mg intravenously daily.", "sourceKey": "C"}, {"key": "D", "text": "Inhaled albuterol by nebulization 2.5 mg every 4 hours, inhaled ipratropium by nebulization 0.5 mg every 6 hours, and methylprednisolone 125 mg intravenously every 6 hours.", "sourceKey": "D"}], "answer": "C", "explanation": "For life-threatening asthma exacerbations, SABAs , shortacting antimuscarinics, and intravenous corticosteroids are recommended (Answers A and B are incorrect). The recommended dose of intravenous corticosteroids is methylprednisolone 40 mg (equivalent to prednisone 50 mg) intravenously per day administered early in the course of the exacerbation (Answer C is correct; Answer D is incorrect).", "page": 26, "answerPage": 39, "stemZh": "病人已插管、MV，life-threatening asthma exacerbation 的最佳初始 therapy？", "contextZh": "30 歲女性（115 kg），status asthmaticus 入 ICU，severe refractory asthma，6 個月內曾 3 次需插管。有 hypertension、diabetes、obesity、bipolar disorder；2 個月來每月用至少 3 canisters albuterol。", "optionsZh": [{"key": "A", "text": "Albuterol nebulization 2.5 mg q4h"}, {"key": "B", "text": "Albuterol 2.5 mg q4h ＋ ipratropium 0.5 mg q6h nebulization"}, {"key": "C", "text": "Albuterol 2.5 mg q4h ＋ ipratropium 0.5 mg q6h nebulization ＋ methylprednisolone 40 mg IV/day"}, {"key": "D", "text": "Albuterol 2.5 mg q4h ＋ ipratropium 0.5 mg q6h nebulization ＋ methylprednisolone 125 mg IV q6h"}], "explanationZh": "教材選 SABA、short-acting antimuscarinic、early systemic corticosteroid；methylprednisolone 40 mg/day 避免不必要的高劑量。"}, {"id": "19-case-07", "chapter": 19, "type": "case", "number": 7, "stem": "A 79-year-old woman (weight 70 kg) is admitted to the ICU for the management of hypercapnic respiratory failure related to an ECOPD. She has had several admissions for ECOPD. The patient presents with fever, profound dyspnea, increased sputum production (thick and purulent), and confusion. She has a history of anaphylaxis to penicillin. Her blood pressure is 190/100 mm Hg, heart rate is 110 beats/minute, and respiratory rate is 22 breaths/minute. Her chest is hyperinflated and has poor air entry bilaterally. Her ABG values are as follows: pH 7.20, PcO 2 85 mm Hg, and PaO 2 44 mm Hg on 6 L of nasal cannula. She is intubated and placed on MV. Which would be the most appropriate group of medications to treat this patient’s severe ECOPD?", "context": "", "options": [{"key": "A", "text": "Methylprednisolone 1 mg/kg intravenously administered as two divided doses, inhaled albuterol by nebulization, ampicillin/sulbactam 3 g intravenously every 6 hours for 7 days, and azithromycin 500 mg intravenously daily for 5 days.", "sourceKey": "A"}, {"key": "B", "text": "Prednisone 40 mg by nasogastric tube (NGT) daily for 5 days, inhaled albuterol and ipratropium by nebulization, ampicillin/sulbactam 3 g intravenously every 6 hours for 10 days, and azithromycin 500 mg daily intravenously for 5 days.", "sourceKey": "B"}, {"key": "C", "text": "Methylprednisolone 1 mg/kg intravenously administered as two divided doses, inhaled albuterol and ipratropium by nebulization, and levofloxacin 750 mg by NGT daily for 7 days.", "sourceKey": "C"}, {"key": "D", "text": "Prednisone 40 mg by NGT daily for 5 days, inhaled albuterol and ipratropium by nebulization, and levofloxacin 750 mg intravenously daily for 5 days.", "sourceKey": "D"}], "answer": "D", "explanation": "The latest GOLD guidelines recommend systemic corticosteroids to shorten recovery time, improve FEV 1 , and improve hypoxemia. The recommended dose is prednisone 40 mg orally once daily (or equivalent) for 5 days. Although recent data identified that some patients may have worse outcomes with fixed prednisone 40-mg doses, the data suggest prednisone 60 mg is adequate to balance the benefit of steroids with the risks of adverse effects (Answers A and C are incorrect). Adding inhaled SABAs (nebulized or MDI) with or without a shortacting anticholinergic is the preferred treatment in an ECOPD. Antibiotic treatment for 5–7 days is also indicated because the patient has signs of bacterial infection (fever, purulent sputum) and a severe ECOPD with respiratory failure. This patient has a history of anaphylactic reaction to penicillin and repeated exacerbations that may predispose her to resistant organisms such as P. aeruginosa (Answers A and B are incorrect); therefore, levofloxacin would be the best recommendation (Answer D is correct).", "page": 33, "answerPage": 39, "stemZh": "79 歲女性（70 kg），多次 ECOPD 住院，本次 hypercapnic respiratory failure，fever、severe dyspnea、thick purulent sputum、confusion，penicillin anaphylaxis。BP 190/100 mm Hg、HR 110/min、RR 22/min，hyperinflated chest、poor air entry。6 L nasal cannula 下 pH 7.20、PCO2 85、PaO2 44 mm Hg，已插管 MV。最佳用藥組合？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Methylprednisolone 1 mg/kg IV 分兩次、albuterol nebulization、ampicillin/sulbactam 3 g IV q6h 7 天、azithromycin 500 mg IV/day 5 天"}, {"key": "B", "text": "Prednisone 40 mg NGT/day 5 天、albuterol/ipratropium nebulization、ampicillin/sulbactam 3 g IV q6h 10 天、azithromycin 500 mg IV/day 5 天"}, {"key": "C", "text": "Methylprednisolone 1 mg/kg IV 分兩次、albuterol/ipratropium nebulization、levofloxacin 750 mg NGT/day 7 天"}, {"key": "D", "text": "Prednisone 40 mg NGT/day 5 天、albuterol/ipratropium nebulization、levofloxacin 750 mg IV/day 5 天"}], "explanationZh": "ECOPD 選 prednisone 40 mg/day 5 天、SABA/SAMA。Purulent sputum、fever、MV 支持 antibiotic；penicillin anaphylaxis 避免 ampicillin/sulbactam，選 levofloxacin。"}, {"id": "19-case-08", "chapter": 19, "type": "case", "number": 8, "stem": "A 75-year-old woman presents to the ED with a productive cough and altered mental status (oriented only to person). Her medical history is significant for type 2 diabetes and severe COPD. On physical examination, she has a productive cough and is alert and oriented ċ 4. Her vital signs are temperature 101.8 F, heart rate 95 beats/minute, respiratory rate 33 breaths/minute, systolic blood pressure 105 mm Hg, and SpO 2 86% on her home oxygen of 2 L/minute by nasal cannula. The patient is placed on noninvasive ventilation by Venturi mask at an FiO 2 of 40%, and her SpO 2 is now 91%. A basic metabolic panel returns with SCr 1.3 mg/ dL and serum urea nitrogen 55 mg/dL, and an ABG reports pH 7.37, PaCO 2 55 mm Hg, and PaO 2 59 mm Hg. Radiography reveals multilobar infiltrates. Which best describes the severity of the patient’s ECOPD and her level of respiratory failure according to the 2024 GOLD guidelines?", "context": "", "options": [{"key": "A", "text": "Moderate ECOPD with non–life-threatening acute respiratory failure.", "sourceKey": "A"}, {"key": "B", "text": "Moderate ECOPD with life-threatening acute respiratory failure.", "sourceKey": "B"}, {"key": "C", "text": "Severe ECOPD with life-threatening acute respiratory failure.", "sourceKey": "C"}, {"key": "D", "text": "Severe ECOPD with non–life-threatening acute respiratory failure.", "sourceKey": "D"}], "answer": "A", "explanation": "The current GOLD guidelines provide specific diagnostic parameters to determine the severity of an ECOPD. A respiratory rate greater than 24 breaths/minute and an SpO 2 less than 92% on home oxygen therapy clearly identify this patient as having either a moderate or severe asthma exacerbation. Patients with a moderate ECOPD may have hypercapnia (PaCO 2 greater than 45 mm Hg) or hypoxia (PaO 2 less than 60 mm Hg); however, they have not yet developed acidosis (pH less than 7.35), whereas those experiencing a severe ECOPD have developed acidosis (Answers C and D are incorrect). Although the degree of respiratory failure is determined using many of the same parameters as the severity of ECOPD, there is a greater focus on patient response to therapy. An improvement in hypoxemia with noninvasive ventilation by Venturi mask with an FiO 2 greater than 35% and the absence of an altered mental status are associated with non–life-threatening respiratory failure (Answer B is incorrect; Answer A is correct).", "page": 33, "answerPage": 40, "stemZh": "75 歲女性，type 2 diabetes、severe COPD，productive cough、意識改變（原書開頭寫僅認得人，但檢查又寫 oriented ×4）。T 101.8°F、HR 95/min、RR 33/min、SBP 105 mm Hg，家中 nasal cannula 2 L/min 下 SpO2 86%；改 Venturi mask FiO2 40% 後 SpO2 91%。SCr 1.3 mg/dL、BUN 55 mg/dL；pH 7.37、PaCO2 55、PaO2 59 mm Hg，multilobar infiltrates。依 2024 GOLD，最佳 ECOPD 與 respiratory failure 分類？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Moderate ECOPD，non–life-threatening acute respiratory failure"}, {"key": "B", "text": "Moderate ECOPD，life-threatening acute respiratory failure"}, {"key": "C", "text": "Severe ECOPD，life-threatening acute respiratory failure"}, {"key": "D", "text": "Severe ECOPD，non–life-threatening acute respiratory failure"}], "explanationZh": "教材答案 A：hypercapnia/hypoxemia 但未 acidosis（pH ≥7.35）支持 moderate ECOPD；氧合改善、解析假設無持續意識改變，為 non–life-threatening respiratory failure。原題意識描述矛盾，請核對來源。"}, {"id": "20-self-01", "chapter": 20, "type": "self", "number": 1, "stem": "A 38-year-old woman with type 2 diabetes is admitted for confusion and altered mental status. She has an active prescription for glipizide 10 mg by mouth twice daily, but she cannot respond to further questioning. Her vital signs are as follows: blood pressure (BP) 115/65 mm Hg, heart rate (HR) 68 beats/minute, respiratory rate (RR) 15 breaths/ minute, and temperature 98.6°F (37°C). Her pointof-care glucose concentration is 45 mg/dL, and she is given 50 mL of 50% dextrose in water intravenously twice. Her follow-up point-of-care glucose concentration is 50 mg/dL after the first dose and 57 mg/dL after the second dose, with no improvement in symptoms. Which is the most appropriate intervention at this time?", "context": "", "options": [{"key": "A", "text": "Dextrose.", "sourceKey": "A"}, {"key": "B", "text": "Glucagon.", "sourceKey": "B"}, {"key": "C", "text": "Octreotide.", "sourceKey": "C"}, {"key": "D", "text": "Sodium bicarbonate.", "sourceKey": "D"}], "answer": "C", "explanation": "The best option for this patient right now is to administer octreotide 50–100 mcg subcutaneously (Answer C is correct). The patient has not responded to two doses of intravenous dextrose, as evidenced by point-of-care glucose concentrations less than 70 mg/dL; therefore, additional doses of dextrose are not indicated (Answer A is incorrect). Although glucagon is also a potential option, it is not recommended for sulfonylurea exposures (Answer B is incorrect). Sodium bicarbonate intravenously may be indicated in this scenario if the patient had metformin-associated lactic acidosis; however, the patient is not on metformin and has no signs of lactic acidosis (Answer D is incorrect).", "page": 4, "answerPage": 47, "stemZh": "38 歲女性 type 2 diabetes，使用 glipizide 10 mg PO BID，因 confusion、意識改變入院，不能回答問題。BP 115/65 mm Hg、HR 68/min、RR 15/min、98.6°F（37°C）。POC glucose 45 mg/dL，已兩次給 50% dextrose 50 mL IV，後續 glucose 分別 50、57 mg/dL，症狀未改善。最佳介入？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Dextrose"}, {"key": "B", "text": "Glucagon"}, {"key": "C", "text": "Octreotide"}, {"key": "D", "text": "Sodium bicarbonate"}], "explanationZh": "教材選 octreotide 50–100 mcg SC，抑制 sulfonylurea-induced insulin secretion。兩次 dextrose 後仍 hypoglycemia；glucagon 不為 sulfonylurea exposure 的優先選項。"}, {"id": "20-self-02", "chapter": 20, "type": "self", "number": 2, "stem": "A 56-year-old man is admitted to the intensive care unit (ICU) after a β-blocker overdose. After administering 2 L of 0.9% sodium chloride and 3 g of calcium gluconate, his vital signs are as follows: BP 70/40 mm Hg, HR 52 beats/minute, and RR 22 breaths/minute. Which therapy is most appropriate at this time?", "context": "", "options": [{"key": "A", "text": "Glucagon 5 mg intravenously.", "sourceKey": "A"}, {"key": "B", "text": "Atropine 2 mg intravenously.", "sourceKey": "B"}, {"key": "C", "text": "Insulin 0.1 unit/kg intravenously.", "sourceKey": "C"}, {"key": "D", "text": "Dopamine 2 mcg/kg/minute intravenously.", "sourceKey": "D"}], "answer": "A", "explanation": "Any of the options listed in this question are possible treatments for a patient with a β-blocker overdose who is not responding to the administration of intravenous fluids and calcium. The optimal choice ultimately involves efficacy and appropriate dosing. Glucagon is an option, and it should be dosed at 5–10 mg intravenously initially (Answer A is correct). Atropine is an option for the patient’s bradycardia, but the initial recommended dose is 0.5–1 mg intravenously (Answer B is incorrect). Hyperinsulinemic euglycemic therapy may be preferred in this setting; however, the correct bolus dose is 1 unit/ kg intravenously (Answer C is incorrect). Dopamine is an option for the treatment of hypotension and bradycardia, but the correct dose would be the initiation of an infusion at 5–10 mcg/kg/minute titrated to effect (Answer D is incorrect).", "page": 4, "answerPage": 47, "stemZh": "56 歲男性 β-blocker overdose，給 0.9% sodium chloride 2 L、calcium gluconate 3 g 後，BP 70/40 mm Hg、HR 52/min、RR 22/min。此時最佳 therapy？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Glucagon 5 mg IV"}, {"key": "B", "text": "Atropine 2 mg IV"}, {"key": "C", "text": "Insulin 0.1 unit/kg IV"}, {"key": "D", "text": "Dopamine 2 mcg/kg/minute IV"}], "explanationZh": "教材選初始 glucagon 5–10 mg IV。其餘選項雖是可能治療方式，但所列劑量不適當：HIET bolus 為 1 unit/kg，dopamine 通常需更高 infusion dose。"}, {"id": "20-self-03", "chapter": 20, "type": "self", "number": 3, "stem": "A 76-year-old woman is admitted to the emergency department (ED) with the chief concern of decreased mental status. Her vital signs are as follows: BP 118/72 mm Hg, HR 57 beats/minute, and RR 17 breaths/minute. She is experiencing nausea, but her physical examination is otherwise normal. Her husband is concerned that she may not be taking her medications properly. Given her presentation, which common toxidrome is the patient most likely experiencing?", "context": "", "options": [{"key": "A", "text": "Anticholinergic.", "sourceKey": "A"}, {"key": "B", "text": "Cholinergic.", "sourceKey": "B"}, {"key": "C", "text": "Opioid.", "sourceKey": "C"}, {"key": "D", "text": "Sympathomimetic.", "sourceKey": "D"}], "answer": "B", "explanation": "Given the patient’s presentation and the common toxidromes, the most likely scenario is a cholinergic agent (Answer B is correct). The patient is experiencing bradycardia with a normal BP and RR, has a decrease in mental status, and is experiencing nausea. Although not an absolute, anticholinergics and sympathomimetics are more commonly associated with tachycardia (Answers A and D are incorrect). Similarly, opioids are typically associated with a decrease in respirations (Answer C is incorrect).", "page": 4, "answerPage": 47, "stemZh": "76 歲女性 decreased mental status、nausea，BP 118/72 mm Hg、HR 57/min、RR 17/min，其餘檢查正常。丈夫擔心藥物服用不當。最可能 toxidrome？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Anticholinergic"}, {"key": "B", "text": "Cholinergic"}, {"key": "C", "text": "Opioid"}, {"key": "D", "text": "Sympathomimetic"}], "explanationZh": "Bradycardia、nausea 與意識下降較符合 cholinergic toxidrome。Anticholinergic、sympathomimetic 常 tachycardia；opioid 通常有 respiratory depression。"}, {"id": "20-self-04", "chapter": 20, "type": "self", "number": 4, "stem": "A 38-year-old woman is admitted to the ICU after a suspected overdose of risperidone. She was initially hypotensive, but she was stabilized after the administration of two 500-mL boluses of lactated Ringer solution. Her BP is now 118/77 mm Hg, HR 75 beats/minute, and RR 16 breaths/minute. A 12-lead electrocardiogram (ECG) shows QT prolongation (corrected QT interval [QTc] = 480 milliseconds), and her chemistry panel is significant for a bicarbonate of 24 mEq/L, potassium of 3.1 mEq/L, and magnesium of 1.8 mg/dL. Which intervention is most appropriate at this time?", "context": "", "options": [{"key": "A", "text": "Potassium chloride 20 mEq every hour for two doses.", "sourceKey": "A"}, {"key": "B", "text": "Activated charcoal 50 g.", "sourceKey": "B"}, {"key": "C", "text": "Magnesium sulfate 2 g.", "sourceKey": "C"}, {"key": "D", "text": "Lorazepam 2 mg.", "sourceKey": "D"}], "answer": "A", "explanation": "The patient is experiencing QT prolongation after an atypical antipsychotic overdose. It is important to stabilize the patient by administering intravenous sodium bicarbonate and electrolyte replacement (Answer A is correct). Her potassium concentration is low, requiring replacement. Because the time interval of the overdose is not known, there is limited benefit for activated charcoal (Answer B is incorrect). Although her magnesium concentration is normal, it should be monitored; however, her magnesium concentration does not require replacement at this time because her QTc is less than 500 milliseconds (Answer C is incorrect). Lorazepam is not indicated for prophylaxis of seizure activity (Answer D is incorrect).", "page": 5, "answerPage": 47, "stemZh": "38 歲女性疑似 risperidone overdose，原 hypotension，兩次 lactated Ringer solution 500 mL bolus 後 BP 118/77 mm Hg、HR 75/min、RR 16/min。QTc 480 ms、HCO3 24 mEq/L、K 3.1 mEq/L、Mg 1.8 mg/dL。最適當介入？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Potassium chloride 20 mEq 每小時，共兩次"}, {"key": "B", "text": "Activated charcoal 50 g"}, {"key": "C", "text": "Magnesium sulfate 2 g"}, {"key": "D", "text": "Lorazepam 2 mg"}], "explanationZh": "應矯正 hypokalemia，降低 QT-related arrhythmia risk。服藥時間未知，charcoal 效益不確定；無 seizure，不預防性給 lorazepam。"}, {"id": "20-self-05", "chapter": 20, "type": "self", "number": 5, "stem": "A 48-year-old man is admitted to the medical floor for community-acquired pneumonia. His medical history is significant for hypertension, hyperlipidemia, and chronic obstructive pulmonary disease (COPD), and he reports occasional alcohol use but no history of alcohol withdrawal. He is initiated on levofloxacin 750 mg intravenously daily and nebulizer treatments with albuterol and ipratropium. Twenty-four hours after admission, he is increasingly more confused and has nausea and vomiting. His vital signs are stable: BP 115/68 mm Hg, HR 122 beats/minute, RR 21 breaths/minute, and temperature 99.7°F (37.6°C). The team is concerned about possible alcohol withdrawal and asks for recommendations for initial therapy. Which is the most appropriate treatment for this patient?", "context": "", "options": [{"key": "A", "text": "Lorazepam 2 mg intravenous push every 4 hours as needed according to the patient’s Clinical Institute Withdrawal Assessment for Alcohol Scale (CIWA) score.", "sourceKey": "A"}, {"key": "B", "text": "Phenobarbital 65 mg by mouth every 8 hours as needed according to the patient’s CIWA score.", "sourceKey": "B"}, {"key": "C", "text": "Propofol continuous infusion.", "sourceKey": "C"}, {"key": "D", "text": "Clonidine 0.1 mg by mouth every 12 hours.", "sourceKey": "D"}], "answer": "A", "explanation": "This patient has the clinical signs and symptoms of alcohol withdrawal. Management should focus on the patient’s safety and controlling his symptoms, and treatment should be administered using a symptom-triggered therapy strategy. The primary agents used to control symptoms are the benzodiazepines, and lorazepam is a good option (Answer A is correct). Barbiturates such as phenobarbital are typically reserved for patients who do not respond to benzodiazepine therapy because of benzodiazepine’s long elimination half-life and stronger sedative effects and oral dosing may be difficult with his level of confusion (Answer B is incorrect). Propofol should be avoided in non-intubated patients (Answer C is incorrect). Clonidine is a potential option, especially because this patient has borderline hypertension, but oral dosing may be difficult with his level of confusion (Answer D is incorrect).", "page": 5, "answerPage": 47, "stemZh": "48 歲男性 CAP 住院，hypertension、hyperlipidemia、COPD，偶爾喝酒但無 withdrawal 史。使用 levofloxacin 750 mg IV/day、albuterol/ipratropium nebulization。24 小時後 confusion 加重、nausea/vomiting；BP 115/68 mm Hg、HR 122/min、RR 21/min、99.7°F（37.6°C）。團隊考慮 alcohol withdrawal。最佳初始 therapy？", "contextZh": "", "optionsZh": [{"key": "A", "text": "依 CIWA score，lorazepam 2 mg IV push q4h PRN"}, {"key": "B", "text": "依 CIWA score，phenobarbital 65 mg PO q8h PRN"}, {"key": "C", "text": "Propofol continuous infusion"}, {"key": "D", "text": "Clonidine 0.1 mg PO q12h"}], "explanationZh": "教材選 symptom-triggered benzodiazepine therapy。未插管不宜 propofol，confusion 也可能使口服給藥不適合。"}, {"id": "20-self-06", "chapter": 20, "type": "self", "number": 6, "stem": "A 57-year-old male patient on the medical floor is incorrectly administered a dose of methadone 40 mg by mouth that was written for the patient in the adjoining bed. Two hours later, the nurse finds him unresponsive with the following vital signs: BP 105/67 mm Hg, HR 61 beats/minute, RR 8 breaths/ minute, and temperature 98.7°F (37.1°C). The nurse calls for the rapid response team, and, as the team pharmacist, you are asked for a recommendation. Which treatment is most appropriate at this time?", "context": "", "options": [{"key": "A", "text": "Activated charcoal 50 g orally.", "sourceKey": "A"}, {"key": "B", "text": "Naloxone 0.04 mg intravenously.", "sourceKey": "B"}, {"key": "C", "text": "Whole bowel irrigation orally.", "sourceKey": "C"}, {"key": "D", "text": "1 L of 0.9% sodium chloride intravenously.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient is experiencing an unintended opioid overdose, as evidenced by the decreased RR and decreased consciousness. Administration of the antidote, naloxone, is the best option (Answer B is correct). Because 2 hours have passed since the methadone dose was given, there is limited usefulness for activated charcoal at this time, and it would not be advisable to administer it to an unconscious patient without an established airway (Answer A is incorrect). Whole bowel irrigation is also not useful in this situation because it is too late to prevent drug absorption together with the airway safety concern (Answer C is incorrect). Administration of intravenous fluids would be beneficial to improve BP but should not be administered in this case before naloxone (Answer D is incorrect).", "page": 5, "answerPage": 47, "stemZh": "57 歲男性被誤給隔壁病人的 methadone 40 mg PO。2 小時後無反應，BP 105/67 mm Hg、HR 61/min、RR 8/min、98.7°F（37.1°C）。Rapid response team 最佳處置？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Activated charcoal 50 g PO"}, {"key": "B", "text": "Naloxone 0.04 mg IV"}, {"key": "C", "text": "Whole bowel irrigation PO"}, {"key": "D", "text": "0.9% sodium chloride 1 L IV"}], "explanationZh": "Opioid exposure 後 respiratory depression、意識降低，先用 naloxone 並處理 airway/breathing。無保護 airway 的昏迷病人不能口服 charcoal 或 bowel irrigation。"}, {"id": "20-self-07", "chapter": 20, "type": "self", "number": 7, "stem": "Which is most appropriate to initiate or do first with respect to HIET?", "context": "A 56-year-old female patient is admitted to the ED after an intentional overdose of 25 amlodipine 10-mg tablets. She is given activated charcoal 50 g, 2 L of 0.9% sodium chloride, and 3 g of calcium gluconate. Her current vital signs are as follows: BP 90/50 mm Hg, HR 107 beats/ minute, RR 17 breaths/minute, and temperature 98.7°F (37.1°C). Serum chemistries are as follows: Na 141 mEq/L, K 2.5 mEq/L, Cl 101 mEq/L, HCO 3 24 mEq/L, blood urea nitrogen (BUN) 19 mg/dL, serum creatinine (SCr) 0.9 mg/dL, and glucose 215 mg/dL. The ED physician wants to initiate hyperinsulinemic euglycemic therapy (HIET).", "options": [{"key": "A", "text": "Give insulin 1 unit/kg intravenously.", "sourceKey": "A"}, {"key": "B", "text": "Give 50 mL of 50% dextrose in water intravenously.", "sourceKey": "B"}, {"key": "C", "text": "Warn the physician that full effects may take up to 30 minutes.", "sourceKey": "C"}, {"key": "D", "text": "Give 20 mEq of potassium chloride intravenously every hour for four doses.", "sourceKey": "D"}], "answer": "D", "explanation": "The patient is not responding to the initiation of intravenous fluids and calcium gluconate, so HIET is warranted. Because of the patient’s low serum potassium concentrations, it is critical to replace this before administering insulin (Answer A is incorrect and Answer D is correct). The patient’s glucose concentration is greater than 200 mg/dL, so additional glucose need not be given at this time (Answer B is incorrect). Full effects may take up to 30 minutes to be seen, but this should not prevent the initiation of HIET (Answer C is incorrect).", "page": 5, "answerPage": 48, "stemZh": "HIET 相關處置，最應先做哪一項？", "contextZh": "56 歲女性故意吞下 amlodipine 10 mg 共 25 顆，已給 activated charcoal 50 g、0.9% sodium chloride 2 L、calcium gluconate 3 g。BP 90/50 mm Hg、HR 107/min、RR 17/min、98.7°F（37.1°C）；Na 141、K 2.5、Cl 101、HCO3 24 mEq/L、BUN 19 mg/dL、SCr 0.9 mg/dL、glucose 215 mg/dL。醫師準備 HIET。", "optionsZh": [{"key": "A", "text": "Insulin 1 unit/kg IV"}, {"key": "B", "text": "50% dextrose 50 mL IV"}, {"key": "C", "text": "告知醫師完整效果可能需 30 分鐘"}, {"key": "D", "text": "Potassium chloride 20 mEq IV 每小時，共四次"}], "explanationZh": "K 2.5 mEq/L，需先處理明顯 hypokalemia，避免 insulin 進一步降低 K。Glucose >200 mg/dL，當下不先補 dextrose。"}, {"id": "20-self-08", "chapter": 20, "type": "self", "number": 8, "stem": "The patient is not responding to HIET initiation. Her current infusion rate is 1 unit/kg/hour. Her BP remains low at 70/40 mm Hg, and her HR is now 58 beats/minute. Her repeat glucose is 186 mg/dL. Which is most appropriate to initiate at this time?", "context": "A 56-year-old female patient is admitted to the ED after an intentional overdose of 25 amlodipine 10-mg tablets. She is given activated charcoal 50 g, 2 L of 0.9% sodium chloride, and 3 g of calcium gluconate. Her current vital signs are as follows: BP 90/50 mm Hg, HR 107 beats/ minute, RR 17 breaths/minute, and temperature 98.7°F (37.1°C). Serum chemistries are as follows: Na 141 mEq/L, K 2.5 mEq/L, Cl 101 mEq/L, HCO 3 24 mEq/L, blood urea nitrogen (BUN) 19 mg/dL, serum creatinine (SCr) 0.9 mg/dL, and glucose 215 mg/dL. The ED physician wants to initiate hyperinsulinemic euglycemic therapy (HIET).", "options": [{"key": "A", "text": "Discontinue HIET, and initiate norepinephrine.", "sourceKey": "A"}, {"key": "B", "text": "Continue HIET, and increase the insulin infusion rate and initiate norepinephrine.", "sourceKey": "B"}, {"key": "C", "text": "Continue HIET, and initiate epinephrine.", "sourceKey": "C"}, {"key": "D", "text": "Discontinue HIET, and begin intravenous lipid therapy.", "sourceKey": "D"}], "answer": "B", "explanation": "The patient is not responding to the initiation of intravenous fluids, calcium, and HIET. The most appropriate option at this time would be to increase the rate of the insulin infusion and initiate vasopressor therapy to improve hemodynamic stability in the interim (Answer B is correct). The initial infusion rate is 0.5–1 unit/kg/ hour and is titrated every 15–20 minutes until hemodynamically stable. The next option would be to initiate a vasopressor agent (Answers A and C are incorrect). From the choices listed, the best first option is norepinephrine initiated at 4 mcg/minute and titrated to the desired effect. Epinephrine is also a possible option, but it would be recommended if the patient were not responding to increasing doses of norepinephrine. Intravenous lipid emulsion is a potential therapy, but it is typically administered in a patient with severe decompensation caused by a lipophilic medication who is not responding to fluids or vasopressors (Answer D is incorrect).", "page": 5, "answerPage": 48, "stemZh": "HIET 初始 infusion 1 unit/kg/hour 後仍無反應。BP 70/40 mm Hg、HR 58/min，repeat glucose 186 mg/dL。此時最適當？", "contextZh": "56 歲女性故意吞下 amlodipine 10 mg 共 25 顆，已給 activated charcoal 50 g、0.9% sodium chloride 2 L、calcium gluconate 3 g。BP 90/50 mm Hg、HR 107/min、RR 17/min、98.7°F（37.1°C）；Na 141、K 2.5、Cl 101、HCO3 24 mEq/L、BUN 19 mg/dL、SCr 0.9 mg/dL、glucose 215 mg/dL。醫師準備 HIET。", "optionsZh": [{"key": "A", "text": "停止 HIET，開始 norepinephrine"}, {"key": "B", "text": "繼續 HIET，提高 insulin infusion rate 並開始 norepinephrine"}, {"key": "C", "text": "繼續 HIET，開始 epinephrine"}, {"key": "D", "text": "停止 HIET，開始 IV lipid therapy"}], "explanationZh": "提高 insulin infusion、密切追蹤 glucose/K，並用 norepinephrine 作 hemodynamic support。HIET 效果需時間，無理由立即停用；lipid therapy 通常留給 refractory severe toxicity。"}, {"id": "20-case-01", "chapter": 20, "type": "case", "number": 1, "stem": "A 53-year-old man (height 74 inches, weight 97 kg [215 lb]) arrives in the ED confused and disoriented. He cannot provide any information about his condition or medical history. Vital signs are as follows: BP 85/50 mm Hg, HR 120 beats/minute, RR 28 breaths/minute, and temperature 99.2°F (37.3°C). On physical examination, an unmarked pill bottle is found in his pocket. Two tablets remain, and a possible drug overdose is suspected. Which is most appropriate to do first for this patient?", "context": "", "options": [{"key": "A", "text": "Send a quantitative urine drug screen.", "sourceKey": "A"}, {"key": "B", "text": "Stabilize the patient’s ABC.", "sourceKey": "B"}, {"key": "C", "text": "Order a coma cocktail.", "sourceKey": "C"}, {"key": "D", "text": "Try to identify the tablets in a drug database.", "sourceKey": "D"}], "answer": "B", "explanation": "The most important first step in all drug overdose cases is to try to stabilize the patient’s ABC (Answer B is correct). This may involve the use of supplemental oxygen or advanced airway management, establishment of intravenous access, and administration of intravenous fluids. Once the patient is stable, the process of identifying the suspected toxin can begin (Answer D is incorrect). This may include thoroughly examining the patient, speaking with family or first responders, and communicating with the patient’s physicians and pharmacies. Blood and urine samples may be sent for quantitative or qualitative toxicologic assays (Answer A is incorrect). A coma cocktail may provide some benefit, but a clear cause should be established before considering its use (Answer C is incorrect).", "page": 10, "answerPage": 45, "stemZh": "53 歲男性（74 inches、97 kg［215 lb］），confusion、disorientation，不能提供病史。BP 85/50 mm Hg、HR 120/min、RR 28/min、99.2°F（37.3°C）；口袋找到無標記 pill bottle，剩 2 tablets，疑 overdose。第一步最適當？", "contextZh": "", "optionsZh": [{"key": "A", "text": "送 quantitative urine drug screen"}, {"key": "B", "text": "穩定 airway、breathing、circulation（ABC）"}, {"key": "C", "text": "給 coma cocktail"}, {"key": "D", "text": "用 drug database 辨識 tablets"}], "explanationZh": "所有疑 overdose 先穩定 ABC，必要時 oxygen、advanced airway、IV access、fluids；辨識 toxin 與檢驗在穩定後進行。"}, {"id": "20-case-02", "chapter": 20, "type": "case", "number": 2, "stem": "Which general management strategy is most indicated for this patient?", "context": "A 42-year-old woman (height 66 inches, weight 79.2 kg [176 lb]) presents to the ED with the chief concern of flu-like symptoms. Her symptoms include headache, congestion, severe nausea and vomiting, abdominal pain, and some confusion. She has been taking acetaminophen 500-mg caplets as needed for her symptoms, but she just ran out of the bottle she purchased yesterday. On presentation, she is alert and oriented. Her vital signs are as follows: BP 135/90 mm Hg, HR 83 beats/minute, RR 18 breaths/minute, and temperature 101.8°F (38.8°C). An acetaminophen concentration on admission was 100 mcg/mL, AST 560 IU/L, and ALT 310 IU/L. The physician wants to begin general management.", "options": [{"key": "A", "text": "10% magnesium citrate 240 mL per tube once", "sourceKey": "A"}, {"key": "B", "text": "Continued stabilization of the patient and good supportive care", "sourceKey": "B"}, {"key": "C", "text": "Gastric lavage", "sourceKey": "C"}, {"key": "D", "text": "Charcoal 50 g once", "sourceKey": "D"}], "answer": "B", "explanation": "The patient has symptoms of an acute acetaminophen overdose, and stabilizing the patient, together with providing good supportive care, is indicated until a determination for additional therapy can be made (Answer B is correct). Typical decontamination strategies may provide benefit, but they do not definitively improve patient outcome. Magnesium citrate (and cathartics as a whole) is not considered an effective decontamination strategy (Answer A is incorrect). Gastric lavage is of most benefit within the first 60 minutes of exposure, and the potential adverse effects outweigh any potential benefit (Answer C is incorrect). Similarly, single-dose charcoal requires more rapid administration (Answer D is incorrect).", "page": 17, "answerPage": 45, "stemZh": "最適當一般 management strategy？", "contextZh": "42 歲女性（66 inches、79.2 kg［176 lb］），flu-like symptoms、headache、congestion、severe nausea/vomiting、腹痛、些微 confusion。按需要服 acetaminophen 500 mg caplets，昨天買的一瓶已用完。到院 alert/oriented，BP 135/90 mm Hg、HR 83/min、RR 18/min、101.8°F（38.8°C）；acetaminophen 100 mcg/mL、AST 560 IU/L、ALT 310 IU/L。", "optionsZh": [{"key": "A", "text": "10% magnesium citrate 240 mL 經 tube 一次"}, {"key": "B", "text": "持續穩定病人並給良好 supportive care"}, {"key": "C", "text": "Gastric lavage"}, {"key": "D", "text": "Charcoal 50 g 一次"}], "explanationZh": "先穩定與 supportive care，再評估特異 therapy。Gastric lavage、charcoal 效益受時間影響；cathartics 不是有效單獨 decontamination 策略。"}, {"id": "20-case-03", "chapter": 20, "type": "case", "number": 3, "stem": "Which is the most appropriate treatment for her acetaminophen toxicity?", "context": "A 42-year-old woman (height 66 inches, weight 79.2 kg [176 lb]) presents to the ED with the chief concern of flu-like symptoms. Her symptoms include headache, congestion, severe nausea and vomiting, abdominal pain, and some confusion. She has been taking acetaminophen 500-mg caplets as needed for her symptoms, but she just ran out of the bottle she purchased yesterday. On presentation, she is alert and oriented. Her vital signs are as follows: BP 135/90 mm Hg, HR 83 beats/minute, RR 18 breaths/minute, and temperature 101.8°F (38.8°C). An acetaminophen concentration on admission was 100 mcg/mL, AST 560 IU/L, and ALT 310 IU/L. The physician wants to begin general management.", "options": [{"key": "A", "text": "Give acetylcysteine 11,200 mg oral bolus, followed by 5600 mg orally every 4 hours for 17 doses.", "sourceKey": "A"}, {"key": "B", "text": "Give acetylcysteine 11,200 mg intravenous bolus, followed by 5600 mg intravenously every 4 hours for 12 doses.", "sourceKey": "B"}, {"key": "C", "text": "Give acetylcysteine 12,000 mg intravenously over 1 hour, followed by 4000 mg intravenously over 4 hours; then 8000 mg intravenously over 16 hours.", "sourceKey": "C"}, {"key": "D", "text": "Acetylcysteine therapy is not indicated in this patient.", "sourceKey": "D"}], "answer": "C", "explanation": "The patient is considered at high risk of developing hepatic damage from acetaminophen and requires therapy with intravenous acetylcysteine (Answer D is incorrect). The dose of intravenous acetylcysteine is as follows (doses are calculated using actual body weight): loading dose: 150 mg/kg in 200 mL of 5% dextrose in water for 60 minutes; maintenance dose: 50 mg/kg in 500 mL of 5% dextrose in water for 4 hours, followed by 100 mg/kg in 1000 mL of 5% dextrose in water for 16 hours (Answer C is correct and Answer B is incorrect). Oral dosing of acetylcysteine is not a viable option because of the patient’s severe nausea and vomiting (Answer A is incorrect).", "page": 17, "answerPage": 45, "stemZh": "Acetaminophen toxicity 最適當 treatment？", "contextZh": "42 歲女性（66 inches、79.2 kg［176 lb］），flu-like symptoms、headache、congestion、severe nausea/vomiting、腹痛、些微 confusion。按需要服 acetaminophen 500 mg caplets，昨天買的一瓶已用完。到院 alert/oriented，BP 135/90 mm Hg、HR 83/min、RR 18/min、101.8°F（38.8°C）；acetaminophen 100 mcg/mL、AST 560 IU/L、ALT 310 IU/L。", "optionsZh": [{"key": "A", "text": "Acetylcysteine 11,200 mg PO bolus，再 5600 mg PO q4h，共 17 doses"}, {"key": "B", "text": "Acetylcysteine 11,200 mg IV bolus，再 5600 mg IV q4h，共 12 doses"}, {"key": "C", "text": "Acetylcysteine 12,000 mg IV/1 小時，再 4000 mg IV/4 小時，再 8000 mg IV/16 小時"}, {"key": "D", "text": "不需 acetylcysteine"}], "explanationZh": "肝損傷高風險需 acetylcysteine。IV regimen 為 150 mg/kg/1 小時、50 mg/kg/4 小時、100 mg/kg/16 小時；severe vomiting 使 oral regimen 不適合。"}, {"id": "20-case-04", "chapter": 20, "type": "case", "number": 4, "stem": "A 62-year-old man presents to the ED with the chief concern of nausea, tachypnea, and flu-like symptoms. He is alert and oriented and can communicate that his symptoms have been worsening for the past 2 days. He has been taking a combination cold product, which he thinks has helped. His medical history is significant for a stroke, for which he takes aspirin 325 mg by mouth daily, and hypertension, for which he takes amlodipine 5 mg by mouth daily. His vital signs are as follows: BP 135/82 mm Hg, HR 78 beats/minute, RR 29 breaths/minute, and temperature 100.2°F (37.9°C). Arterial blood gas results are as follows: pH 7.52, Pco 2 25, and HCO 3 20 mEq/L. A salicylate concentration is sent, which is 25 mg/dL. Which treatment management strategy is most indicated for this patient?", "context": "", "options": [{"key": "A", "text": "Sodium chloride infusion", "sourceKey": "A"}, {"key": "B", "text": "Urgent endotracheal intubation", "sourceKey": "B"}, {"key": "C", "text": "Sodium bicarbonate infusion", "sourceKey": "C"}, {"key": "D", "text": "Hemodialysis", "sourceKey": "D"}], "answer": "C", "explanation": "This patient has an acute salicylate overdose. Although his serum salicylate concentrations are in the therapeutic range, he has symptoms consistent with salicylate toxicity, as evidenced by his nausea, tachycardia, and respiratory alkalosis. He is currently stable, but his serum salicylate concentrations may continue to rise; therefore, enhanced elimination with serum bicarbonate is the best option (Answer C is correct). His vital signs, which are stable, should be monitored for changes; however, although he is not experiencing signs of significant dehydration, he would benefit from the fluid administration of sodium bicarbonate. Sodium chloride would be more beneficial if his vital signs were more unstable (Answer A is incorrect). His RR, which is elevated, should be monitored; however, he is alert and able to communicate and therefore does not need intubation at this time (Answer B is incorrect). He is also not indicated for hemodialysis because of his moderate symptoms, but this could be considered if his condition deteriorates (Answer D is incorrect).", "page": 19, "answerPage": 45, "stemZh": "62 歲男性 nausea、tachypnea、flu-like symptoms 2 天惡化，使用 combination cold product；stroke 病史服 aspirin 325 mg/day，hypertension 服 amlodipine 5 mg/day。Alert/oriented，BP 135/82 mm Hg、HR 78/min、RR 29/min、100.2°F（37.9°C）；pH 7.52、PCO2 25、HCO3 20 mEq/L、salicylate 25 mg/dL。最佳 treatment？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Sodium chloride infusion"}, {"key": "B", "text": "緊急 endotracheal intubation"}, {"key": "C", "text": "Sodium bicarbonate infusion"}, {"key": "D", "text": "Hemodialysis"}], "explanationZh": "症狀與 respiratory alkalosis 支持 salicylate toxicity，即使濃度在常見 therapeutic range。穩定時可用 bicarbonate 增強 elimination，惡化再評估 dialysis。"}, {"id": "20-case-05", "chapter": 20, "type": "case", "number": 5, "stem": "A 35-year-old man is admitted to the ED appearing inebriated. He is alert but oriented only to person. His vital signs are BP 122/80 mm Hg, HR 82 beats/minute, and RR 25 breaths/minute. His serum ethanol concentration is 20 mg/dL, and his ethylene glycol concentration is 100 mg/dL. Which is the most appropriate therapy at this time?", "context": "", "options": [{"key": "A", "text": "Fomepizole", "sourceKey": "A"}, {"key": "B", "text": "Ethanol infusion", "sourceKey": "B"}, {"key": "C", "text": "Thiamine", "sourceKey": "C"}, {"key": "D", "text": "Activated charcoal", "sourceKey": "D"}], "answer": "A", "explanation": "The most appropriate therapy for an ethylene glycol intoxication is fomepizole (Answer A is correct). An ethanol infusion is a possible treatment option, but it is not preferred because of the difficulties in dosing and adverse effects (Answer B is incorrect). Thiamine is a cofactor in the metabolism of ethylene glycol, but it would not be preferred to administer thiamine before fomepizole (Answer C is incorrect). Activated charcoal is not an option for gastric decontamination because it is not effective for alcohols (Answer D is incorrect).", "page": 25, "answerPage": 45, "stemZh": "35 歲男性像酒醉，到 ED 時清醒但僅認得人。BP 122/80 mm Hg、HR 82/min、RR 25/min；ethanol 20 mg/dL、ethylene glycol 100 mg/dL。最佳 therapy？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Fomepizole"}, {"key": "B", "text": "Ethanol infusion"}, {"key": "C", "text": "Thiamine"}, {"key": "D", "text": "Activated charcoal"}], "explanationZh": "Fomepizole 抑制 alcohol dehydrogenase，阻止 toxic metabolites 形成；ethanol dosing/adverse effects 較不理想。Charcoal 對 alcohols 不有效。"}, {"id": "20-case-06", "chapter": 20, "type": "case", "number": 6, "stem": "A patient with methanol intoxication is initiated on fomepizole treatment together with hemodialysis. After the 15-mg/kg bolus dose is given, which would be best for adjusting the maintenance fomepizole doses during dialysis?", "context": "", "options": [{"key": "A", "text": "10 mg/kg every 12 hours", "sourceKey": "A"}, {"key": "B", "text": "20 mg/kg every 12 hours", "sourceKey": "B"}, {"key": "C", "text": "10 mg/kg every 4 hours", "sourceKey": "C"}, {"key": "D", "text": "20 mg/kg every 4 hours", "sourceKey": "D"}], "answer": "C", "explanation": "After the initial bolus of fomepizole, 10 mg/kg should be administered every 12 hours. Because of the increased clearance of fomepizole during hemodialysis, the frequency is changed to every 4 hours during dialysis (Answer C is correct and Answer A is incorrect). When dialysis is completed, the dose returns to 10 mg/kg administered every 12 hours; and once the patient has been on 48 hours of therapy, dosing increases to 15 mg/ kg because of self-induction. There is no indication for a dose increase (Answer B and D are incorrect).", "page": 25, "answerPage": 45, "stemZh": "Methanol intoxication 同時使用 fomepizole 與 hemodialysis；15 mg/kg bolus 後，dialysis 期間最佳 maintenance dose 調整？", "contextZh": "", "optionsZh": [{"key": "A", "text": "10 mg/kg q12h"}, {"key": "B", "text": "20 mg/kg q12h"}, {"key": "C", "text": "10 mg/kg q4h"}, {"key": "D", "text": "20 mg/kg q4h"}], "explanationZh": "Hemodialysis 增加 fomepizole clearance，教材建議從 10 mg/kg q12h 改 q4h；結束後恢復一般間隔，療程 48 小時後再依 self-induction 調整。"}, {"id": "20-case-07", "chapter": 20, "type": "case", "number": 7, "stem": "Which decontamination strategy would provide the most benefit?", "context": "A 52-year-old man is admitted to the ED with concerns about dizziness and headache. His vital signs are as follows: temperature 98.9°F (37.2°C), BP 87/50 mm Hg, and HR 58 beats/minute. His wife reports that he has a history of hypertension and that he was recently given a diagnosis of being in the early stages of Alzheimer disease. She has brought his medications with her; the 1-month supply was refilled 2 days ago: a bottle of diltiazem CD 120 mg/day (7 tablets remaining) and a bottle of donepezil 5 mg once daily (28 tablets remaining).", "options": [{"key": "A", "text": "Charcoal 25 g every hour until his BP improves", "sourceKey": "A"}, {"key": "B", "text": "Ipecac 30 mL, followed by 240 mL of water", "sourceKey": "B"}, {"key": "C", "text": "Polyethylene glycol-electrolyte solution 1500 mL/hour until the rectal effluent is clear", "sourceKey": "C"}, {"key": "D", "text": "Magnesium citrate 240 mL, followed by 240 mL of water", "sourceKey": "D"}], "answer": "C", "explanation": "The best treatment option for this patient is whole bowel irrigation because of the extended-release formulation of diltiazem (Answer C is correct). Activated charcoal may provide some benefit, but, similar to ipecac, the time interval is not known, and diltiazem does not undergo enterohepatic recirculation (Answer A is incorrect). Ipecac is not recommended because it may impede treatment with more effective treatment options and because it is no longer manufactured in the United States (Answer B is incorrect). A cathartic would not be useful in this situation; guidelines recommend its use only in combination with other decontamination strategies, not as a single agent (Answer D is incorrect).", "page": 30, "answerPage": 46, "stemZh": "哪個 decontamination strategy 最有益？", "contextZh": "52 歲男性因 dizziness、headache 就醫，98.9°F（37.2°C）、BP 87/50 mm Hg、HR 58/min。Hypertension、early Alzheimer disease。妻子帶來 2 天前補的一個月份藥物：diltiazem CD 120 mg/day（剩 7 tablets）、donepezil 5 mg/day（剩 28 tablets）。", "optionsZh": [{"key": "A", "text": "Charcoal 25 g 每小時直到 BP 改善"}, {"key": "B", "text": "Ipecac 30 mL 後給水 240 mL"}, {"key": "C", "text": "Polyethylene glycol-electrolyte solution 1500 mL/hour，直到 rectal effluent 清澈"}, {"key": "D", "text": "Magnesium citrate 240 mL 後給水 240 mL"}], "explanationZh": "教材選 whole bowel irrigation，因 diltiazem 為 extended-release formulation。Ipecac 不建議，cathartic 不宜單獨使用。需連同病人穩定度與 airway 狀態閱讀原書。"}, {"id": "20-case-08", "chapter": 20, "type": "case", "number": 8, "stem": "Which antidote would be best to administer first?", "context": "A 52-year-old man is admitted to the ED with concerns about dizziness and headache. His vital signs are as follows: temperature 98.9°F (37.2°C), BP 87/50 mm Hg, and HR 58 beats/minute. His wife reports that he has a history of hypertension and that he was recently given a diagnosis of being in the early stages of Alzheimer disease. She has brought his medications with her; the 1-month supply was refilled 2 days ago: a bottle of diltiazem CD 120 mg/day (7 tablets remaining) and a bottle of donepezil 5 mg once daily (28 tablets remaining).", "options": [{"key": "A", "text": "Calcium chloride 1 g intravenously over 1 minute", "sourceKey": "A"}, {"key": "B", "text": "Glucagon 5 mg intravenously over 1 minute", "sourceKey": "B"}, {"key": "C", "text": "Atropine 2 mg intravenously over 1 minute", "sourceKey": "C"}, {"key": "D", "text": "Epinephrine 1 mg intravenously over 1 minute", "sourceKey": "D"}], "answer": "A", "explanation": "There are several potential antidotes for a calcium channel blocker overdose. Calcium is the most effective, and it should be given by bolus, followed by continuous infusion if needed (Answer A is correct). Glucagon is not an effective antidote and is therefore not an option for this patient (Answer B is incorrect). Atropine is effective for symptomatic bradycardia caused by the calcium channel blocker, but the dose should be 0.5–1 mg (Answer C is incorrect). Epinephrine is an alternative to glucagon, but this dose is excessive for a patient not experiencing cardiac arrest (Answer D is incorrect).", "page": 30, "answerPage": 46, "stemZh": "第一個最適當 antidote？", "contextZh": "52 歲男性因 dizziness、headache 就醫，98.9°F（37.2°C）、BP 87/50 mm Hg、HR 58/min。Hypertension、early Alzheimer disease。妻子帶來 2 天前補的一個月份藥物：diltiazem CD 120 mg/day（剩 7 tablets）、donepezil 5 mg/day（剩 28 tablets）。", "optionsZh": [{"key": "A", "text": "Calcium chloride 1 g IV/1 分鐘"}, {"key": "B", "text": "Glucagon 5 mg IV/1 分鐘"}, {"key": "C", "text": "Atropine 2 mg IV/1 分鐘"}, {"key": "D", "text": "Epinephrine 1 mg IV/1 分鐘"}], "explanationZh": "Calcium channel blocker overdose 可先給 calcium bolus，必要時 infusion。Glucagon 不為教材首選；其餘選項 doses 在非 cardiac arrest 情境不適當。"}, {"id": "20-case-09", "chapter": 20, "type": "case", "number": 9, "stem": "A 21-year-old man is admitted to the ED after taking 30 citalopram 20-mg tablets about 2 hours ago. His vital signs are as follows: BP 125/85 mm Hg, HR 77 beats/minute, RR 15 breaths/minute, and temperature 98.7°F (37.1°C). Which is the best intervention for this patient?", "context": "", "options": [{"key": "A", "text": "Administer lorazepam 2 mg intravenously to prevent seizure activity.", "sourceKey": "A"}, {"key": "B", "text": "Administer cyproheptadine 8 mg by mouth to prevent muscle rigidity.", "sourceKey": "B"}, {"key": "C", "text": "Recommend a cooling blanket to prevent serotonin syndrome–related hyperthermia.", "sourceKey": "C"}, {"key": "D", "text": "Order a 12-lead ECG to monitor for cardiac conduction disturbances.", "sourceKey": "D"}], "answer": "D", "explanation": "Most of the SSRIs are relatively safe, and many patients will present as asymptomatic after an overdose. However, there is a potential for a patient to develop serious adverse effects, such as serotonin syndrome, seizures, and cardiac toxicity. Although this patient is stable and has no specific concerns, it is recommended to check a 12-lead ECG to measure for QT-interval prolongation and treat with sodium bicarbonate, if necessary (Answer D is correct). A benzodiazepine should be administered if muscle rigidity develops, but it should not be used as a prophylactic measure (Answer A is incorrect). It is recommended that the patient be observed for at least 6–8 hours. Cyproheptadine is only indicated for symptomatic patients (Answer B is incorrect). Measures should be performed to reduce hyperthermia if a serotonergic syndrome develops, but this should be treated with measures to reduce muscle activity (i.e., sedation or chemical paralysis), not by applying measures to enhance surface cooling (Answer C is incorrect).", "page": 34, "answerPage": 46, "stemZh": "21 歲男性 2 小時前吞下 citalopram 20 mg 共 30 顆。BP 125/85 mm Hg、HR 77/min、RR 15/min、98.7°F（37.1°C）。最佳介入？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Lorazepam 2 mg IV 預防 seizure"}, {"key": "B", "text": "Cyproheptadine 8 mg PO 預防 muscle rigidity"}, {"key": "C", "text": "Cooling blanket 預防 serotonin-related hyperthermia"}, {"key": "D", "text": "12-lead ECG 監測 cardiac conduction disturbances"}], "explanationZh": "目前穩定無症狀，但 citalopram overdose 可引起 QT prolongation，應 ECG 監測。Lorazepam、cyproheptadine 或 hyperthermia treatment 用於有症狀時，不常規預防性給予。"}, {"id": "20-case-10", "chapter": 20, "type": "case", "number": 10, "stem": "A 24-year-old woman is brought to the ED by her roommate. She has been in a normal state of health, but the roommate is concerned because she “seems really out of it.” According to the roommate, the patient had an appointment with the physician today, and she had been given a prescription to refill olanzapine 5 mg by mouth daily, but the bottle is empty. On physical examination, she is alert and oriented person, place and time but she dozes off several times. Her vital signs are stable, and a 12-lead ECG shows sinus tachycardia. Which intervention is most appropriate for this patient?", "context": "", "options": [{"key": "A", "text": "Lactated Ringer solution 500 mL intravenously", "sourceKey": "A"}, {"key": "B", "text": "8.4% sodium bicarbonate 50 mL intravenously", "sourceKey": "B"}, {"key": "C", "text": "Lorazepam 2 mg intravenously", "sourceKey": "C"}, {"key": "D", "text": "Clinical monitoring for 6 hours", "sourceKey": "D"}], "answer": "D", "explanation": "Although the patient appears to have taken an overdose of olanzapine, she is experiencing only mild symptoms. The best intervention would be to monitor her for 6 hours for the progression of her symptoms or development of additional complications (Answer D is correct). Intravenous fluids would be appropriate if the patient has dehydration or hypotension (Answer A is incorrect). Sodium bicarbonate is indicated for QRS prolongation and is not warranted at this time (Answer B is incorrect). Olanzapine does not cause seizures; therefore, lorazepam would not be indicated (Answer C is incorrect).", "page": 36, "answerPage": 46, "stemZh": "24 歲女性室友稱她恍神，今天剛拿到 olanzapine 5 mg/day refill 處方，但藥瓶已空。人、地、時定向正常但數次打瞌睡，生命徵象穩定，ECG sinus tachycardia。最佳介入？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Lactated Ringer solution 500 mL IV"}, {"key": "B", "text": "8.4% sodium bicarbonate 50 mL IV"}, {"key": "C", "text": "Lorazepam 2 mg IV"}, {"key": "D", "text": "Clinical monitoring 6 小時"}], "explanationZh": "教材選穩定、輕症 overdose 的 clinical monitoring，觀察症狀進展。無 hypotension/dehydration、QRS prolongation 或 seizure，不先給其他介入。"}, {"id": "20-case-11", "chapter": 20, "type": "case", "number": 11, "stem": "As the pharmacist in the ICU satellite, you receive a call from a distressed nurse about a patient in the cardiac step-down unit. The patient was found unconscious, and, on investigation, it was discovered that he had received a glyburide 20-mg tablet 1 hour earlier that was meant for another patient. The patient has stable vital signs, but his point-of-care blood glucose concentration is 37 mg/dL. Which intervention is most appropriate at this time?", "context": "", "options": [{"key": "A", "text": "8 oz of milk by mouth", "sourceKey": "A"}, {"key": "B", "text": "50 mL of 50% dextrose in water intravenously", "sourceKey": "B"}, {"key": "C", "text": "Octreotide 100 mcg subcutaneously", "sourceKey": "C"}, {"key": "D", "text": "Glucagon 1 mg intramuscularly", "sourceKey": "D"}], "answer": "B", "explanation": "The most appropriate intervention at this time is to give the patient intravenous dextrose (Answer B is correct). Oral glucose is a viable option, but it cannot be administered to an unconscious patient without oral access (Answer A is incorrect). Octreotide should be reserved for use if the administration of a glucose solution fails to raise the blood glucose above 70 mg/dL for two consecutive readings (Answer C is incorrect). Glucagon is a potential option for treatment, but because the patient has intravenous access, the intramuscular route would not be preferred (Answer D is incorrect).", "page": 37, "answerPage": 46, "stemZh": "Cardiac step-down 病人被發現 unconscious，1 小時前誤服另一病人的 glyburide 20 mg。生命徵象穩定，POC glucose 37 mg/dL。最適當立即介入？", "contextZh": "", "optionsZh": [{"key": "A", "text": "Milk 8 oz PO"}, {"key": "B", "text": "50% dextrose 50 mL IV"}, {"key": "C", "text": "Octreotide 100 mcg SC"}, {"key": "D", "text": "Glucagon 1 mg IM"}], "explanationZh": "先給 IV dextrose 矯正 severe symptomatic hypoglycemia。昏迷不能 oral intake；octreotide 用於 sulfonylurea-related recurrent/persistent hypoglycemia 的後續處理。"}]};